using System.Collections.Immutable;
using Mist.Analysis.Builtin;
using Mist.Common.Diagnostics;
using Mist.Common.Source;
using Mist.Driver.Contracts;
using Mist.Generated;
using Mist.Semantics.Contracts;
using Mist.Semantics.Model.Types;

namespace Mist.Semantics.Model;

/// <summary>
/// Builds an immutable <see cref="SemanticModel"/> from a set of ASTs.
/// Walks ASTs to build symbols, scopes, and types, then freezes all mutable
/// builders before returning the immutable model.
/// </summary>
public sealed class SemanticModelBuilder : ISemanticModelBuilder
{
    // ── Overloading diagnostic IDs ───────────────────────────────────────
    internal static readonly DiagnosticId DuplicateMethodSignature = new("MIST_SM_0020");
    internal static readonly DiagnosticId DuplicateConstructorSignature = new("MIST_SM_0021");
    internal static readonly DiagnosticId MissingAbstractOverload = new("MIST_SM_0022");

    // ── Namespace scope registry ─────────────────────────────────────────
    // Maps fully-qualified namespace names to their scope instances. Populated
    // by GetOrCreateNamespaceScope during Pass 1 and consulted by
    // FindExistingNamespaceScope. This replaces the fragile heuristic of
    // locating namespace scopes by searching for type symbols with a matching
    // ContainingNamespace — that approach failed when a namespace contained
    // only type aliases (which lack ContainingNamespace on their DeclaredType).
    [ThreadStatic]
    private static Dictionary<string, Scope>? namespaceScopeMap;

    // ── Deprecation diagnostic IDs ───────────────────────────────────────
    internal static readonly DiagnosticId VoidDotVoidDeprecated = new("MIST_SM_0023");
    // ── Extension member lookup context ──────────────────────────────────
    // Set before Pass 2 type resolution and cleared after. Allows
    // LookupMemberType to perform extension member fallback without
    // threading the registry through the entire deep call chain.
    [ThreadStatic]
    private static ExtensionRegistry? extensionRegistryContext;

    // ── Target type context for empty array literal inference ─────────────
    // Set before resolving a typed variable declaration's initializer so that
    // EmptyArrayLiteralExpressionPrimaryNode can infer its element type from
    // the declared array type. Cleared immediately after resolution.
    [ThreadStatic]
    private static IType? emptyArrayTargetType;

    // ── Target type context for lambda expression inference ──────────────
    // Set before resolving a lambda expression's initializer so that
    // implicitly-typed lambda parameters can infer their types from the
    // target Func type. Cleared immediately after resolution.
    [ThreadStatic]
    private static IType? lambdaTargetType;

    // ── Target type context for void value literal resolution ─────────────
    // Set before resolving an expression whose target type is known (typed
    // variable initializer, method argument, return value, generic constructor
    // argument) so that TypeLiteralExpressionPrimaryNode with a void type
    // reference can resolve as VoidType when the target type is void.
    // Cleared immediately after resolution.
    [ThreadStatic]
    private static IType? voidLiteralTargetType;

    // ── Target type context for target-typed new expression resolution ────
    // Set before resolving an expression whose target type is known (typed
    // field initializer, typed variable initializer, return statement, method
    // argument, assignment RHS) so that TargetTypedNewExpressionPrimaryNode
    // and TargetTypedNewExpressionNoArgsPrimaryNode can resolve their type
    // from the surrounding context. Cleared immediately after resolution.
    [ThreadStatic]
    private static IType? targetTypedNewTargetType;

    // ── Current method return type for return-statement lambda/void inference ──
    // Set when entering a method body so that return statements can propagate
    // the method's return type as a lambda target type and as the target type
    // for void value literal resolution.
    [ThreadStatic]
    private static IType? currentMethodReturnType;
    // ── Symbolic length ID allocation for parameter arrays ────────────────
    // Generates unique IDs for unsized array parameters so that two references
    // to the same parameter's .Length resolve to the same symbolic identity.
    // Reset at the start of each Build() call.
    [ThreadStatic]
    private static int nextSymbolicLengthId;

    // Set to true while resolving a parameter's type reference so that
    // unsized array types (e.g., int[] items) receive a symbolic length ID.
    // Cleared immediately after the type reference is resolved.
    [ThreadStatic]
    private static bool allocatingParameterArrayType;

    // ── Async context tracking ───────────────────────────────────────────
    // Set to true while resolving expressions inside an async method body.
    // When false (sync context), async method invocations are auto-unwrapped
    // from Task<T> to T. Cleared after method body resolution completes.
    [ThreadStatic]
    private static bool isInAsyncContext;



    // ── Discarded-task tracking (Drop-based model) ──────────────────────
    // Under the Drop-based model, named Task<T>/ValueTask<T> locals are
    // scope-exit drop obligations handled by the emitter's auto-drop
    // try/finally wrapping (tasks 7.1, 7.3). This tracking covers only
    // DISCARDED task expressions — bare async method calls whose result is
    // not assigned to a variable. The emitter still needs to intercept these,
    // emit them as `var __task_N = expr;`, and await them at scope exit.
    //
    // Tracking is NOT gated on _isInAsyncContext — discarded tasks in sync
    // contexts are also tracked so the emitter can promote the method to
    // async when scope-exit await is needed.
    //
    // _discardedTaskScopes is a stack of per-block-scope task lists. Pushed
    // on block entry, popped on block exit, with un-consumed entries stored
    // in the result map.
    //
    // _discardedTaskCounter generates unique variable names (__task_0, etc.)
    // per method body.
    [ThreadStatic]
    private static Stack<List<DiscardedTaskInfo>>? discardedTaskScopes;

    [ThreadStatic]
    private static int discardedTaskCounter;

    // The result map populated during resolution. Keyed by block scope node,
    // valued by the list of discarded tasks that need scope-exit await.
    [ThreadStatic]
    private static Dictionary<Storm.Runtime.SyntaxNode, List<DiscardedTaskInfo>>? discardedTaskResult;

    // ── Intrinsic-marker diagnostic IDs (Task 9, Requirements 5.3, 5.6, 5.13, 5.15) ──
    /// <summary>
    /// An intrinsic member was declared with a body. Per Requirement 5.3,
    /// intrinsic members must terminate with <c>;</c> because their body is
    /// supplied by the backend's <c>IntrinsicEmissionTable</c>.
    /// </summary>
    internal static readonly DiagnosticId IntrinsicMemberHasBody = new("MIST_SB_0030");

    /// <summary>
    /// The <c>intrinsic</c> modifier (at either type or member level) was
    /// used in a non-stdlib compilation unit. Per Requirements 5.6 and 5.13,
    /// the modifier is reserved for the Standard Library.
    /// </summary>
    internal static readonly DiagnosticId IntrinsicReservedForStdlib = new("MIST_SB_0031");

    /// <summary>
    /// A member-level <c>intrinsic</c> appeared inside a type that does not
    /// itself carry the type-level <c>intrinsic</c> marker. Per Requirement
    /// 5.15, intrinsic members are always hosted on Backend_Backed_Types.
    /// </summary>
    internal static readonly DiagnosticId MemberIntrinsicRequiresTypeIntrinsic = new("MIST_SB_0032");

    // ── Operator-shape diagnostic IDs (Task 12, Requirements 4.2, 4.7, 4.8, 4.9) ──
    /// <summary>
    /// An <c>operator</c> declaration appeared outside a class or struct body
    /// (Requirement 4.7). NOTE: the grammar already forbids operator
    /// declarations outside a class/struct body (see <c>MemberDeclaration</c>
    /// rule in <c>Mist.storm</c>), so this diagnostic is a defensive
    /// safety net that currently has no triggerable path from parsed source.
    /// It is registered here so the diagnostic ID is allocated and the
    /// shape-validation logic would cover a future grammar change that
    /// admitted top-level operator declarations.
    /// </summary>
    internal static readonly DiagnosticId OperatorOutsideTypeBody = new("MIST_SB_0033");

    /// <summary>
    /// An <c>operator</c> declaration's parameter count does not match the
    /// arity required by its operator symbol (Requirements 4.8 &amp; 4.9).
    /// Binary operators require exactly 2 parameters; unary operators require
    /// exactly 1. The <c>-</c> symbol is overloaded binary/unary; its arity
    /// is disambiguated by declared parameter count (2 = binary, 1 = unary;
    /// anything else selects the closest-fitting error message).
    /// </summary>
    internal static readonly DiagnosticId OperatorArityMismatch = new("MIST_SB_0034");

    /// <summary>
    /// An <c>operator</c> declaration is missing the required
    /// <c>public static</c> modifier combination (Requirement 4.2).
    /// Every operator must be declared <c>public static</c> in v1; any
    /// deviation (missing either modifier, or adding <c>private</c>) fires
    /// this diagnostic.
    /// </summary>
    internal static readonly DiagnosticId OperatorMustBePublicStatic = new("MIST_SB_0035");

    // ── Cast-operator-shape diagnostic IDs (Task 3.2, Requirements 6.1, 6.3, 6.4, 6.5) ──

    /// <summary>
    /// A cast operator declaration has a parameter count other than 1
    /// (Requirement 6.3, 6.4). Cast operators must have exactly one parameter.
    /// </summary>
    internal static readonly DiagnosticId CastOperatorArityMismatch = new("MIST_SB_0040");

    /// <summary>
    /// A cast operator declaration is missing the required
    /// <c>public static</c> modifier combination (Requirement 6.1).
    /// </summary>
    internal static readonly DiagnosticId CastOperatorMustBePublicStatic = new("MIST_SB_0041");

    /// <summary>
    /// A cast operator declaration appeared outside a class or struct body
    /// (Requirement 6.1). Like <see cref="OperatorOutsideTypeBody"/>, this
    /// is currently unreachable from parsed source because the grammar
    /// restricts cast operator declarations to <c>MemberDeclaration</c>.
    /// Registered defensively.
    /// </summary>
    internal static readonly DiagnosticId CastOperatorOutsideTypeBody = new("MIST_SB_0042");

    /// <summary>
    /// Two cast operators in the same type have the same kind (both implicit
    /// or both explicit) and the same target type name (Requirement 6.5).
    /// This is a name-based duplicate check; full type-based duplicate
    /// detection is deferred to the type checker.
    /// </summary>
    internal static readonly DiagnosticId DuplicateCastOperator = new("MIST_SB_0043");

    // ── Storage-ban diagnostic IDs (unknown-type Task 11, Requirements 5.1–5.3, 7.5–7.6, 16.1) ──

    /// <summary>
    /// A field declaration has a declared type that is storage-banned under
    /// the <c>unknown-type</c> rules (Requirement 5.1). Fires when the
    /// declared type is <see cref="UnknownType"/> directly, or transitively
    /// contains it through <see cref="ArrayType"/> / <see cref="ConstructedType"/>
    /// arguments (Requirements 7.5, 7.6). Detection is performed via
    /// <see cref="TypeContainment.IsStorageBanned"/> in
    /// <see cref="ResolveFieldDeclaration"/>, immediately after the field
    /// type is resolved in Pass 2. The diagnostic message names the
    /// declaring type and the field (Requirement 16.1).
    /// </summary>
    internal static readonly DiagnosticId UnknownAsFieldType = new("MIST_SB_0050");

    /// <summary>
    /// A property declaration has a declared type that is storage-banned
    /// under the <c>unknown-type</c> rules (Requirement 5.2). Like
    /// <see cref="UnknownAsFieldType"/>, fires on bare
    /// <see cref="UnknownType"/> and on transitive containment through
    /// arrays and constructed generics (Requirements 7.5, 7.6). Detection
    /// runs immediately after the property type is resolved in Pass 2
    /// (for both block and expression-bodied properties). The diagnostic
    /// message names the declaring type and the property (Requirement 16.1).
    /// </summary>
    internal static readonly DiagnosticId UnknownAsPropertyType = new("MIST_SB_0051");

    /// <summary>
    /// An indexer declaration has an element type (the indexer's declared
    /// return type) that is storage-banned under the <c>unknown-type</c>
    /// rules (Requirement 5.3). Like the field and property variants, fires
    /// on bare <see cref="UnknownType"/> and transitive containment
    /// (Requirements 7.5, 7.6). Detection runs immediately after the
    /// indexer element type is resolved in Pass 2. The diagnostic message
    /// names the declaring type and the indexer (Requirement 16.1).
    /// </summary>
    internal static readonly DiagnosticId UnknownAsIndexerElementType = new("MIST_SB_0052");

    /// <summary>
    /// A <c>new T(...)</c> object-creation expression constructs a generic
    /// type whose substituted type contains <see cref="UnknownType"/> at one
    /// or more positions — e.g., <c>new List&lt;unknown&gt;()</c> or
    /// <c>new Map&lt;unknown, int&gt;()</c> (Requirement 5.7). The
    /// constructed type satisfies <see cref="TypeContainment.IsStorageBanned"/>
    /// because each constructor stores its parameters into T-typed slots,
    /// which would require persisting an <c>unknown</c>-typed value. The
    /// diagnostic message names the generic type and the position(s) where
    /// <c>unknown</c> appears (Requirement 16.2). Detection is performed by
    /// <see cref="Builtin.TypeCheckerAnalyzer"/> during
    /// <c>CheckObjectCreation</c>; the ID is declared here alongside the
    /// other storage-ban IDs so the whole cascade lives in one place.
    /// </summary>
    internal static readonly DiagnosticId UnknownInGenericConstruction = new("MIST_SB_0053");

    /// <summary>
    /// A class, struct, or abstract type declaration names
    /// <see cref="UnknownType"/> in its base clause or abstract type list
    /// (Requirements 6.1, 6.2, 6.3, 6.4). <c>UnknownType</c> is the
    /// user-facing top type and is not an inheritable or implementable
    /// shape: it declares no members (Requirement 3.4) and does not
    /// participate in inheritance relationships (Requirement 3.5).
    /// </summary>
    /// <remarks>
    /// In practice the grammar rejects this form before Pass 1b runs —
    /// <c>BaseTypeRef = name:IDENTIFIER typeArgs:TypeArgumentList?</c>
    /// requires an <c>IDENTIFIER</c> token, and <c>unknown</c> is a
    /// reserved keyword that lexes to <c>UNKNOWN</c>, not
    /// check is retained as a defensive guard for programmatically
    /// constructed ASTs and for documentation alignment with
    /// Requirements 6.1–6.4 and 16.6. When triggered, the offending
    /// base/abstract type reference is dropped from the declaring type's
    /// base/abstract type list so subsequent passes see a consistent model.
    /// </remarks>
    internal static readonly DiagnosticId UnknownAsBaseType = new("MIST_SB_0054");

    /// <summary>
    /// A <c>new T[n]</c> array-creation expression uses
    /// <see cref="UnknownType"/> as the array element type — e.g.,
    /// <c>new unknown[5]</c> (Requirement 5.5). The storage ban applies
    /// because every array slot would hold an <c>unknown</c>-typed value,
    /// and array elements are writable storage. Detection is performed by
    /// <see cref="Builtin.TypeCheckerAnalyzer"/> during
    /// <c>CheckArrayCreation</c>; the ID is declared here alongside the
    /// other storage-ban IDs.
    /// </summary>
    internal static readonly DiagnosticId UnknownAsArrayElement = new("MIST_SB_0055");

    /// <summary>
    /// A <c>new T(...)</c> object-creation expression attempts to
    /// instantiate <see cref="UnknownType"/> directly — <c>new unknown(...)</c>
    /// (Requirement 5.4). <c>UnknownType</c> has no declared members
    /// (Requirement 3.4) and no constructor, so the operation is
    /// categorically forbidden. Detection is performed by
    /// <see cref="Builtin.TypeCheckerAnalyzer"/> during
    /// <c>CheckObjectCreation</c>.
    /// </summary>
    /// <remarks>
    /// In practice the grammar rejects this form before the type checker
    /// runs — <c>ObjectCreationExpression</c> requires a
    /// <c>QualifiedIdentifier</c>, and <c>unknown</c> is a reserved keyword
    /// that lexes to <c>UNKNOWN</c>, not <c>IDENTIFIER</c>. The check is
    /// retained as a defensive guard for programmatically-constructed ASTs
    /// and for documentation alignment with Requirement 5.4.
    /// </remarks>
    internal static readonly DiagnosticId UnknownCannotBeInstantiated = new("MIST_SB_0056");

    /// <summary>
    /// A <c>default(T)</c> expression or a bare <c>default</c> whose
    /// inferred context type is <see cref="UnknownType"/> — e.g.,
    /// <c>default(unknown)</c> or <c>unknown x = default;</c>
    /// (Requirement 5.6). <c>UnknownType</c> has no default value because
    /// it has no declared members and no associated runtime representation
    /// beyond C# <c>object</c>; producing a default would materialize a
    /// specific value (<c>null</c>) whose static type is <c>unknown</c>,
    /// violating the storage ban on freshly-materialized <c>unknown</c>
    /// values. Detection is performed by
    /// <see cref="Builtin.TypeCheckerAnalyzer"/> inside
    /// <c>ValidateDefaultableType</c>, before the abstract type/type-parameter
    /// checks, so both explicit <c>default(unknown)</c> and bare
    /// <c>default</c> inferred to <c>unknown</c> fire.
    /// </summary>
    internal static readonly DiagnosticId UnknownHasNoDefault = new("MIST_SB_0057");

    // ── Type alias diagnostic IDs (Task 5.3, Requirements 4.1–4.4, 5.4) ──

    /// <summary>
    /// A type alias forms a cycle (e.g., <c>type A = B; type B = A;</c>).
    /// Detected during Pass 2 resolution using a visited-set. The alias is
    /// assigned <see cref="ErrorType"/> to prevent infinite loops.
    /// </summary>
    internal static readonly DiagnosticId CyclicTypeAlias = new("MIST_SB_0060");

    /// <summary>
    /// A type alias name is already defined in the same scope (Requirement 4.3).
    /// </summary>
    internal static readonly DiagnosticId DuplicateTypeAlias = new("MIST_SB_0061");

    /// <summary>
    /// The target type in a type alias declaration could not be resolved
    /// (Requirement 4.4).
    /// </summary>
    internal static readonly DiagnosticId UnresolvedTypeAliasTarget = new("MIST_SB_0062");

    /// <summary>
    /// A refinement predicate is incompatible with the base type (e.g., relational
    /// patterns like <c>&gt;= 18</c> applied to a non-comparable type like <c>string</c>).
    /// </summary>
    internal static readonly DiagnosticId IncompatibleRefinementPredicate = new("MIST_TC_0072");

    /// <summary>
    /// A regex refinement predicate is applied to a non-<c>string</c> base type.
    /// Regex refinement predicates are only valid on <c>string</c> types (Requirement 11.3).
    /// </summary>
    internal static readonly DiagnosticId RegexRefinementOnNonString = new("MIST_TC_REGEX_REFINEMENT");

    /// <summary>
    /// A newtype name is already defined in the same scope (Requirement 3.3).
    /// </summary>
    internal static readonly DiagnosticId DuplicateNewtype = new("MIST_SB_0063");

    /// <summary>
    /// The source type in a newtype declaration could not be resolved (Requirement 3.4).
    /// </summary>
    internal static readonly DiagnosticId UnresolvedNewtypeSource = new("MIST_SB_0064");

    internal static readonly DiagnosticId ExtensionReceiverUnresolved = new("MIST_SB_0070");

    /// <summary>
    /// An extension property declares a <c>set</c> or <c>init</c> accessor.
    /// Extension properties are read-only (Requirement 20.3).
    /// </summary>
    internal static readonly DiagnosticId ExtensionPropertyHasSetAccessor = new("MIST_SB_0071");

    /// <summary>
    /// An extension block contains an invalid member declaration. Only methods
    /// and properties are allowed inside extension blocks (Requirement 20.2).
    /// </summary>
    internal static readonly DiagnosticId ExtensionInvalidMember = new("MIST_SB_0072");

    /// <summary>
    /// Two extension blocks for the same receiver type declare members with identical
    /// signatures (Requirement 8.9, 20.4).
    /// </summary>
    internal static readonly DiagnosticId ExtensionDuplicateMember = new("MIST_SB_0073");

    /// <summary>
    /// The <c>void</c> type cannot be used as an extension receiver type
    /// (Requirement 20.6).
    /// </summary>
    internal static readonly DiagnosticId ExtensionVoidReceiver = new("MIST_SB_0074");

    /// <summary>
    /// A static extension member body references the receiver parameter.
    /// Static members cannot access the receiver instance (Requirements 3.3, 13.4).
    /// </summary>
    internal static readonly DiagnosticId ExtensionStaticReceiverAccess = new("MIST_TC_0080");

    /// <summary>
    /// A method parameter name conflicts with the receiver parameter name,
    /// creating ambiguity in the method body (Requirement 20.5).
    /// </summary>
    internal static readonly DiagnosticId ExtensionParameterConflictsWithReceiver = new("MIST_TC_0081");

    /// <summary>
    /// A member declaration inside an extension block has the same name as the
    /// receiver parameter, which shadows it and may cause confusion
    /// (Requirements 10.4, 20.5).
    /// </summary>
    internal static readonly DiagnosticId ExtensionMemberShadowsReceiver = new("MIST_TC_0083");

    // ── Constraint diagnostic IDs (generic-constraints spec, Requirements 3.1–3.9) ──

    /// <summary>
    /// A <c>where</c> clause references a type parameter name that is not
    /// defined on the declaring type or method (Requirement 3.2).
    /// </summary>
    internal static readonly DiagnosticId ConstraintUndefinedTypeParam = new("MIST_CONSTRAINT_0001");

    /// <summary>
    /// Multiple <c>where</c> clauses target the same type parameter on a
    /// single declaration (Requirement 3.9).
    /// </summary>
    internal static readonly DiagnosticId ConstraintDuplicateWhereClause = new("MIST_CONSTRAINT_0007");

    /// <summary>
    /// The 'class' and 'struct' constraints are mutually exclusive on the same
    /// type parameter (Requirement 4.1).
    /// </summary>
    internal static readonly DiagnosticId ConstraintClassStructMutualExclusion = new("MIST_CONSTRAINT_0002");

    /// <summary>
    /// The 'new()' constraint is redundant when 'struct' is present because all
    /// structs have a parameterless constructor (Requirement 4.2).
    /// </summary>
    internal static readonly DiagnosticId ConstraintStructNewRedundant = new("MIST_CONSTRAINT_0003");

    /// <summary>
    /// At most one base class constraint is allowed on a type parameter
    /// (Requirement 4.3).
    /// </summary>
    internal static readonly DiagnosticId ConstraintMultipleBaseClasses = new("MIST_CONSTRAINT_0004");

    /// <summary>
    /// A struct type cannot be used as a base class constraint
    /// (Requirement 4.4).
    /// </summary>
    internal static readonly DiagnosticId ConstraintStructAsBaseClass = new("MIST_CONSTRAINT_0005");

    /// <summary>
    /// A base class constraint is incompatible with the 'struct' constraint
    /// (Requirement 4.5).
    /// </summary>
    internal static readonly DiagnosticId ConstraintBaseClassStructIncompatible = new("MIST_CONSTRAINT_0006");

    /// <summary>
    /// A constraint type reference could not be resolved to a known type
    /// (Requirement 3.4).
    /// </summary>
    internal static readonly DiagnosticId ConstraintUnresolvableType = new("MIST_CONSTRAINT_0008");

    /// <summary>
    /// Multiple substructural constraints (linear, affine, relevant) are specified
    /// on the same type parameter (Requirement 3.3).
    /// </summary>
    internal static readonly DiagnosticId ConstraintMultipleSubstructural = new("MIST_CONSTRAINT_0009");

    // ── Enum diagnostic IDs (Task 3.6, Requirements 3.5, 3.6, 3.7, 5.2) ──

    /// <summary>
    /// An enum member's value expression is not assignable to the explicitly
    /// annotated underlying type (Requirement 3.5). Fires during Pass 2 when
    /// the member value type does not match the declared type annotation.
    /// </summary>
    internal static readonly DiagnosticId EnumMemberValueNotAssignableToExplicitType = new("MIST_SB_0080");

    /// <summary>
    /// An enum member's value expression is not assignable to the inferred
    /// underlying type (Requirement 3.7). Fires during Pass 2 when the
    /// member value type does not conform to the type inferred from other
    /// members.
    /// </summary>
    internal static readonly DiagnosticId EnumMemberValueNotAssignableToInferredType = new("MIST_SB_0081");

    /// <summary>
    /// An expression accesses a member name that does not exist on the enum
    /// (Requirement 5.2). Fires when <c>EnumName.InvalidMember</c> is used
    /// and <c>InvalidMember</c> is not a declared member of the enum.
    /// </summary>
    internal static readonly DiagnosticId UndefinedEnumMemberAccess = new("MIST_SB_0082");

    /// <summary>
    /// A value of the underlying type is assigned to a variable of the enum
    /// type (Requirement 7.3). Reverse conversion from underlying type to
    /// enum type is not supported; only enum-to-underlying is implicit.
    /// </summary>
    internal static readonly DiagnosticId CannotAssignUnderlyingToEnum = new("MIST_SB_0083");

    /// <summary>
    /// An enum declaration uses a name that is already defined in the same
    /// scope (Requirement 5.2 — duplicate enum name). Fires during Pass 1
    /// when a second enum with the same name is registered.
    /// </summary>
    internal static readonly DiagnosticId DuplicateEnumName = new("MIST_SB_0084");

    /// <summary>
    /// Two members of the same enum resolve to the same underlying value
    /// (e.g., two string-backed members both map to the same string, or
    /// two integer-backed members share a numeric value). Fires during Pass 2
    /// after all member values have been resolved.
    /// </summary>
    internal static readonly DiagnosticId DuplicateEnumMemberValue = new("MIST_SB_0085");

    // ── Member kind mismatch diagnostic IDs ──────────────────────────────

    /// <summary>
    /// A member access expression (e.g., <c>obj.Foo</c>) resolved to a method.
    /// Methods must be invoked with parentheses: <c>obj.Foo()</c>.
    /// </summary>
    internal static readonly DiagnosticId PropertyAccessResolvesToMethod = new("MIST_TC_0084");

    /// <summary>
    /// A method call expression (e.g., <c>obj.Foo()</c>) resolved to a field or property.
    /// Fields and properties must be accessed without parentheses: <c>obj.Foo</c>.
    /// </summary>
    internal static readonly DiagnosticId MethodCallResolvesToProperty = new("MIST_TC_0085");

    // ── Dependent type parameter diagnostic IDs (Requirements 4.1–4.6, 6.1, 6.4) ──

    /// <summary>
    /// A type annotation used as a dependent type parameter is not in the
    /// allowed set {int, uint, long, ulong, short, ushort, byte, sbyte, bool, char}.
    /// The parameter is still registered with <see cref="ErrorType"/> as its
    /// value type to allow downstream analysis to continue without cascading errors.
    /// </summary>
    internal static readonly DiagnosticId DependentTypeDisallowedAnnotation = new("MIST_DT_0001");

    /// <summary>
    /// A named constraint type reference could not be resolved to any known type
    /// in scope (Requirement 2.3).
    /// </summary>
    internal static readonly DiagnosticId DependentTypeConstraintNotFound = new("MIST_DT_0002");

    /// <summary>
    /// A dependent type parameter name conflicts with a member declared in the
    /// same type. The dependent parameter takes precedence in scope resolution
    /// (consistent with how type parameters shadow members in C#), but the
    /// diagnostic warns the user to rename one or the other.
    /// </summary>
    internal static readonly DiagnosticId DependentTypeParameterNameCollision = new("MIST_DT_0005");

    /// <summary>
    /// A type with dependent parameters is used without providing the required
    /// dependent type arguments. Also used for duplicate dependent parameter names
    /// within the same type parameter list.
    /// </summary>
    internal static readonly DiagnosticId DependentTypeMissingArguments = new("MIST_DT_0006");

    // ── Adhoc refinement constraint diagnostic IDs (Requirements 4.4, 4.5, 4.6) ──

    /// <summary>
    /// An adhoc refinement constraint references a name that is not a dependent
    /// type parameter or value parameter on the declaration (Requirement 4.4).
    /// </summary>
    internal static readonly DiagnosticId RefinementConstraintUnknownName = new("MIST_REFINEMENT_0001");

    /// <summary>
    /// An adhoc refinement constraint targets a regular type parameter instead of
    /// a dependent type parameter or value parameter (Requirement 4.5).
    /// </summary>
    internal static readonly DiagnosticId RefinementConstraintOnRegularTypeParam = new("MIST_REFINEMENT_0002");

    /// <summary>
    /// Duplicate adhoc refinement constraint on the same name within a single
    /// declaration (Requirement 4.6).
    /// </summary>
    internal static readonly DiagnosticId RefinementConstraintDuplicate = new("MIST_REFINEMENT_0003");

    /// <summary>
    /// An implementation method has a stronger refinement constraint on a parameter than
    /// the abstract type method requires, violating Liskov Substitution (Requirement 17.4).
    /// </summary>
    internal static readonly DiagnosticId RefinementConstraintStrongerThanAbstract = new("MIST_REFINEMENT_0009");

    // ── Nested type diagnostic IDs (nested-scoping spec, Requirements 9.4, 9.5, 14.3) ──

    /// <summary>
    /// A nested type has the same name as another type already registered in
    /// the same parent type's member scope (Requirement 9.4, 14.3). The second
    /// declaration is skipped to avoid cascading errors.
    /// </summary>
    internal static readonly DiagnosticId DuplicateNestedType = new("MIST0303");

    /// <summary>
    /// A nested type has the same name as a type parameter declared on the
    /// parent type (Requirement 9.5). The nested type declaration conflicts
    /// with the type parameter and is skipped.
    /// </summary>
    internal static readonly DiagnosticId NestedTypeConflictsWithTypeParameter = new("MIST0304");

    // ── Struct inheritance diagnostic IDs (struct-inheritance spec, Requirements 1.2, 2.1–2.6, 3.3, 7.3, 7.4) ──

    /// <summary>
    /// A struct inheritance chain contains a cycle (e.g., <c>struct A : B</c>
    /// and <c>struct B : A</c>). The <c>BaseType</c> is set to <c>null</c>
    /// on the offending struct to break the cycle.
    /// </summary>
    internal static readonly DiagnosticId StructCircularInheritance = new("MIST_STRUCT_CIRCULAR_INHERITANCE");

    /// <summary>
    /// A struct inheritance chain exceeds the maximum allowed depth of 64.
    /// The <c>BaseType</c> is set to <c>null</c> to prevent infinite loops.
    /// </summary>
    internal static readonly DiagnosticId StructMaxDepth = new("MIST_STRUCT_MAX_DEPTH");

    /// <summary>
    /// A struct's base list contains more than one struct type. Only single
    /// struct inheritance is supported; additional struct entries are rejected.
    /// </summary>
    internal static readonly DiagnosticId StructMultipleInheritance = new("MIST_STRUCT_MULTIPLE_INHERITANCE");

    /// <summary>
    /// A field declared in a derived struct has the same name as a field
    /// inherited from an ancestor struct, which would cause ambiguity.
    /// </summary>
    internal static readonly DiagnosticId StructFieldHiding = new("MIST_STRUCT_FIELD_HIDING");

    /// <summary>
    /// A struct's base list names a type that is not a struct (e.g., a class
    /// or other non-struct/non-abstract type used in the base position).
    /// </summary>
    internal static readonly DiagnosticId StructInvalidBase = new("MIST_STRUCT_INVALID_BASE");

    /// <summary>
    /// A derived struct constructor does not provide <c>: base(...)</c> but
    /// the base struct has no parameterless constructor.
    /// </summary>
    internal static readonly DiagnosticId StructBaseCtorRequired = new("MIST_STRUCT_BASE_CTOR_REQUIRED");

    /// <summary>
    /// A derived struct constructor's <c>: base(...)</c> arguments do not
    /// match any constructor on the base struct.
    /// </summary>
    internal static readonly DiagnosticId StructBaseCtorMismatch = new("MIST_STRUCT_BASE_CTOR_MISMATCH");

    // ── Ref struct diagnostic IDs (ref-structs spec, Requirement 1.5) ──

    /// <summary>
    /// The <c>ref</c> modifier was used on a non-struct type declaration
    /// (class, abstract type, or enum). The <c>ref</c> modifier is only
    /// valid on struct declarations (Requirement 1.5).
    /// </summary>
    internal static readonly DiagnosticId RefModifierOnlyValidOnStruct = new("MIST2001");

    /// <summary>
    /// A ref struct type was used with the optional suffix (<c>?</c>).
    /// Ref structs cannot be optional because optional maps to <c>Nullable&lt;T&gt;</c>
    /// which requires boxing (Requirement 3.9).
    /// </summary>
    internal static readonly DiagnosticId RefStructCannotBeOptional = new("MIST2006");

    /// <summary>
    /// The set of primitive type keywords allowed as dependent type parameter annotations.
    /// </summary>
    private static readonly HashSet<string> AllowedDependentTypeAnnotations = new(StringComparer.Ordinal)
    {
        "int", "uint", "long", "ulong", "short", "ushort", "byte", "sbyte", "bool", "char",
    };

    /// <summary>
    /// Maps a stdlib type's <see cref="IType.DisplayName"/> (e.g., "Int32", "Boolean")
    /// or a legacy keyword name (e.g., "int", "bool") to the canonical keyword form
    /// used by <see cref="AllowedDependentTypeAnnotations"/>.
    /// Returns <c>null</c> if the name does not correspond to any known primitive keyword.
    /// </summary>
    private static readonly Dictionary<string, string> StdlibNameToKeyword =
        BuildStdlibNameToKeywordMap();

    private static Dictionary<string, string> BuildStdlibNameToKeywordMap()
    {
        var map = new Dictionary<string, string>(StringComparer.Ordinal);

        // Build from KeywordAliases.Map: "int" → "Standard.Int32" becomes "Int32" → "int"
        foreach(var (keyword, qualifiedName) in KeywordAliases.Map)
        {
            // qualifiedName is like "Standard.Int32" — extract just the type name.
            var dotIndex = qualifiedName.LastIndexOf('.');
            var typeName = dotIndex >= 0 ? qualifiedName[(dotIndex + 1)..] : qualifiedName;
            map[typeName] = keyword;
        }

        // Also include the keyword names themselves (for legacy primitives).
        foreach(var (keyword, _) in KeywordAliases.Map)
        {
            map[keyword] = keyword;
        }

        return map;
    }

    /// <summary>
    /// Returns the Mist keyword for a given type's display name, or the display name
    /// itself if no mapping is found.
    /// </summary>
    private static string GetKeywordForBaseType(IType baseType)
    {
        var displayName = baseType.DisplayName;
        return StdlibNameToKeyword.TryGetValue(displayName, out var keyword)
            ? keyword
            : displayName;
    }

    public ISemanticModel Build(
        MistCompilation compilation,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        IAmbientTypeResolver? ambientTypeResolver,
        string namespaceRoot,
        string projectFolder,
        DiagnosticBag diagnostics,
        ImmutableHashSet<string>? directReferencePaths = null)
    {
        var globalScope = new Scope(parent: null);
        var transitiveScope = new Scope(parent: null);
        var symbolTable = new SymbolTable();

        // Reset symbolic length ID counter for this compilation.
        nextSymbolicLengthId = 1;
        allocatingParameterArrayType = false;

        // Reset namespace scope map for this compilation.
        namespaceScopeMap = new Dictionary<string, Scope>();

        // Initialize live task tracking for this compilation.
        discardedTaskResult = new Dictionary<Storm.Runtime.SyntaxNode, List<DiscardedTaskInfo>>();

        // (Task 49: PrimitiveTypeRegistry and PrimitiveType have been
        // deleted. No migration-window registry reset is needed.)

        // Pass 1: Register user-defined types.
        // Walk each AST to discover namespaces, types, and members.
        // Units from transitive-only references are registered in a separate
        // scope that is not searched during name resolution for the user
        // project, enforcing transitive visibility rules (Requirements 6.1,
        // 6.2, 6.4).
        var extensionBlockScopes = new Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)>();
        for(var i = 0; i < asts.Length; i++)
        {
            var ast = asts[i];
            var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;
            var unit = i < compilation.Units.Length ? compilation.Units[i] : null;

            // Each unit can carry its own namespace root and project folder
            // (e.g., stdlib units use "Standard" and the Standard/ directory).
            // Fall back to the driver-level values for user units.
            var effectiveNamespaceRoot = unit?.NamespaceRoot ?? namespaceRoot;
            var effectiveProjectFolder = unit?.ProjectFolder ?? projectFolder;

            // Determine whether this unit is directly visible to the user
            // project. A unit is directly visible if:
            //   - OriginProjectPath is null (stdlib or user's own code), OR
            //   - OriginProjectPath is in the set of direct reference paths.
            // Units from transitive-only references are registered in a
            // separate scope so their symbols are not found during name
            // resolution for the user project.
            var isTransitiveOnly = directReferencePaths is not null
                && unit?.OriginProjectPath is not null
                && !directReferencePaths.Contains(unit.OriginProjectPath);

            var targetScope = isTransitiveOnly ? transitiveScope : globalScope;

            try
            {
                Pass1_RegisterTypes(ast, targetScope, symbolTable, sourceText, effectiveNamespaceRoot, effectiveProjectFolder, diagnostics, extensionBlockScopes);
            }
            catch(Exception ex)
            {
                diagnostics.Report(SemanticDiagnostics.SemanticError, default, "<unknown>", (object)$"Error during semantic model construction: {ex.Message}");
            }
        }

        // Pass 1: Validate namespace declarations.
        // After all types are registered, walk each compilation unit to detect:
        //   * MIST0301 — duplicate file-scoped namespaces in the same file.
        //   * MIST0302 — mixed file-scoped and block namespaces in the same file.
        //   * MIST0305 — file-scoped namespace inside a block namespace.
        for(var i = 0; i < asts.Length; i++)
        {
            var ast = asts[i];
            if(ast is CompilationUnitNode cu)
            {
                var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;
                Pass1_ValidateNamespaceDeclarations(cu, sourceText, diagnostics);
            }
        }

        // Phase 1 (cont.): Eagerly build declaration-site file scopes.
        // After all types are registered, construct each file's scope (namespace
        // parent + using imports + global usings) and store it in a dictionary
        // indexed by the CompilationUnitNode. Subsequent phases (type forwards,
        // inheritance, explicit member types) reuse these scopes instead of
        // rebuilding them per-file.
        // NOTE: We use a separate diagnostic bag here to avoid duplicate
        // "undefined namespace" diagnostics — Pass2_ResolveTypes will rebuild
        // each file's scope with the real diagnostic bag and emit any errors.
        var fileScopesByUnit = new Dictionary<Storm.Runtime.SyntaxNode, Scope>();
        var fileScopeDiagnostics = new DiagnosticBag();
        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is CompilationUnitNode cu)
            {
                var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;
                var unitGlobalUsings = i < compilation.Units.Length
                    ? compilation.Units[i].GlobalUsings
                    : ImmutableArray<string>.Empty;

                var fileScope = BuildFileScopeForUnit(
                    cu, globalScope, symbolTable, ambientTypeResolver,
                    sourceText, fileScopeDiagnostics, unitGlobalUsings, out _);

                fileScopesByUnit[cu] = fileScope;
            }
        }

        // Phase 2: Resolve type forwards (aliases and newtype source types).
        // Builds a dependency graph of all alias/newtype symbols, walks it in
        // topological order (leaves first), and resolves each target using
        // declaration-site scopes. Cycles are detected and reported. For
        // newtypes, only the source type identity is resolved (members are NOT
        // cloned here — that happens in Phase 4b).
        Pass1a_ResolveTypeForwards(asts, symbolTable, ambientTypeResolver, fileScopesByUnit, compilation, diagnostics);

        // Pass 1e: Validate intrinsic markers (Task 9).
        // Walks every registered type and member to emit diagnostics for:
        //   * MIST_SB_0030 — intrinsic member with a body (Requirement 5.3).
        //   * MIST_SB_0031 — 'intrinsic' modifier used in a non-stdlib unit
        //     (Requirements 5.6, 5.13). Until Task 26 lands
        //     CompilationUnit.IsStdlib, every unit is treated as non-stdlib,
        //     so any 'intrinsic' in the semantic model currently fires this.
        //   * MIST_SB_0032 — member-level 'intrinsic' inside a non-intrinsic
        //     containing type (Requirement 5.15).
        Pass1e_ValidateIntrinsicMarkers(asts, symbolTable, compilation, diagnostics);

        // Pass 1e (cont.): Validate operator-declaration shape (Task 12).
        // Walks every operator symbol registered on class/struct member scopes
        // to emit diagnostics for:
        //   * MIST_SB_0033 — operator declared outside a class/struct body
        //     (Requirement 4.7). Unreachable from parsed source because the
        //     grammar already restricts OperatorDeclaration to MemberDeclaration;
        //     registered defensively.
        //   * MIST_SB_0034 — operator parameter count mismatches its required
        //     arity (Requirements 4.8, 4.9).
        //   * MIST_SB_0035 — operator not declared `public static`
        //     (Requirement 4.2).
        Pass1e_ValidateOperatorShape(symbolTable, diagnostics);

        // Pass 1e (cont.): Validate cast-operator-declaration shape.
        // Walks every cast operator symbol registered on class/struct member
        // scopes to emit diagnostics for:
        //   * MIST_SB_0040 — cast operator parameter count is not 1
        //     (Requirements 6.3, 6.4).
        //   * MIST_SB_0041 — cast operator not declared `public static`
        //     (Requirement 6.1).
        //   * MIST_SB_0042 — cast operator declared outside a class/struct
        //     body (Requirement 6.1). Defensive; unreachable from parsed source.
        //   * MIST_SB_0043 — duplicate cast operator (same kind + same target
        //     type name) in the same type (Requirement 6.5).
        Pass1e_ValidateCastOperatorShape(symbolTable, diagnostics);

        // (Task 49: PrimitiveTypeRegistry has been deleted. Stdlib types
        // are resolved directly via ResolvePrimitiveKeyword in Pass 2.)

        // Pass 1b: Resolve base types for class inheritance.
        // This runs after all types are registered so that forward references
        // to base classes are supported.
        Pass1_ResolveBaseTypes(asts, globalScope, symbolTable, compilation, diagnostics, ambientTypeResolver);

        // Pass 1b (cont.): Resolve struct base types for struct inheritance.
        // Mirrors the class base type resolution above. Checks if the first
        // entry in a struct's abstract type list resolves to a StructType and, if
        // so, sets it as the struct's BaseType.
        Pass1_ResolveStructBaseTypes(symbolTable, asts, globalScope, compilation, diagnostics, ambientTypeResolver);

        // Pass 1b (cont.): Resolve abstract type lists on classes, structs, and abstract types.
        // After base types are resolved, resolve abstract type names on all types.
        // For classes, the first name in the base clause may be a base class
        // (already resolved above) or an abstract type; this pass handles the
        // abstract type case and any additional abstract type names.
        Pass1_ResolveAbstractLists(symbolTable, asts, globalScope, compilation, diagnostics, ambientTypeResolver);

        // Pass 1b (cont.): Resolve constraint clauses on type/method declarations.
        // After base types and abstract type lists are resolved, resolve constraint
        // type references and store them on TypeParameterType.Constraints.
        // Emits MIST_CONSTRAINT_0001 for undefined type parameter references,
        // MIST_CONSTRAINT_0007 for duplicate where clauses, and
        // MIST_CONSTRAINT_0008 for unresolvable constraint types.
        var parameterRefinements = new Dictionary<ISymbol, RefinementPredicate>();
        Pass1_ResolveConstraints(symbolTable, asts, compilation, diagnostics);

        // Pass 1b (cont.): Resolve with-clauses on method-like declarations.
        // After all types are registered, resolve the type references in
        // with-clauses and store ContextClauseInfo on each method symbol's
        // WithClauses property.
        Pass1_ResolveWithClauses(symbolTable, asts, compilation, diagnostics);



        // Pass 1c: Detect circular abstract type inheritance chains.
        // After abstract type lists are resolved, walk each abstract type's Abstracts
        // chain to detect cycles (including self-inheritance). Cycles are
        // broken by removing the back-edge from the abstract types list.
        Pass1_DetectAbstractCycles(symbolTable, asts, compilation, diagnostics);

        // Pass 1c (cont.): Detect circular class inheritance chains.
        // After all base types are resolved, walk each class's BaseType chain
        // to detect cycles (including self-inheritance). Cycles are broken by
        // setting BaseType = null on the class that closes the cycle.
        Pass1_DetectCycles(symbolTable, asts, compilation, diagnostics);

        // Pass 1d: Validate abstract type satisfaction.
        // After cycles are broken, check that each class and struct
        // implementing abstract types provides all required methods.
        Pass1_ValidateAbstractSatisfaction(symbolTable, asts, compilation, diagnostics);

        // Pass 1f: Check that base class constructor requirements are satisfied.
        // If a base class has explicit constructors that require parameters,
        // the derived class must provide a constructor with `: base(args)`.
        Pass1_CheckBaseConstructorSatisfied(symbolTable, asts, compilation, diagnostics);

        // Upgrade the ambient type resolver's stdlib provider so that
        // lazy type factories (e.g., Math.Abs returning Int32) reference
        // the real stdlib IType instances registered in Pass 1 instead of
        // the FallbackStdlibTypeProvider singletons (which have empty
        // member scopes and therefore no operator members).
        if(ambientTypeResolver is Backends.CSharpTranspiler.CSharpAmbientTypeResolver)
        {
            Backends.CSharpTranspiler.CSharpAmbientTypeResolver.UpdateStdlibProvider(
                new ScopeBasedStdlibTypeProvider(globalScope, symbolTable));
        }

        if(ambientTypeResolver is Backends.CSharpTranspiler.AssemblyTypeProvider)
        {
            Backends.CSharpTranspiler.AssemblyTypeProvider.UpdateStdlibProvider(
                new ScopeBasedStdlibTypeProvider(globalScope, symbolTable));
        }

        // Phase 4: Resolve explicit member type annotations globally.
        // After inheritance is fully resolved (base types, abstract type lists,
        // constraints), resolve all
        // explicitly-annotated member types across ALL compilation units
        // using declaration-site scopes. This guarantees that every
        // explicitly-typed field, property, method signature, constructor,
        // indexer, operator, and cast operator has a non-null DeclaredType
        // BEFORE any expression-level inference begins in Pass 2.
        Pass1_5_ResolveExplicitMemberTypes(asts, globalScope, symbolTable, ambientTypeResolver, fileScopesByUnit, compilation, diagnostics);

        // Phase 4c: Resolve with-block declarations. After all member types
        // are resolved (Phase 4), validate with-block type references, member
        // mappings, and signature compatibility. Register validated mappings
        // in the ConformanceMap for later use by the type checker and emitter.
        var conformanceMap = new ConformanceMap();
        Pass1_ResolveWithBlocks(asts, symbolTable, conformanceMap, compilation, diagnostics);

        // Phase 4b: Clone newtype members. After all source types have their
        // members fully typed (Phase 4), iterate all newtype symbols and clone
        // members from their source types. This ensures cloned members carry
        // the correct DeclaredType values resolved in Phase 4.
        Pass1_5b_CloneNewtypeMembers(symbolTable);

        // Phase 5: Resolve accessibility and sealed flag on every declaration.
        // After all types, members, and newtype clones are registered, walk
        // every symbol to call AccessibilityFacts.TryReduceExplicit on its
        // modifier list. When no explicit modifier is present, resolve the
        // scope-kind default (namespace/compilation → Internal; class/struct →
        // Private; interface/enum → Public; nested type → Private). Store the
        // concrete value on both the symbol and the type object. Set IsSealed
        // from AccessibilityFacts.HasSealed on ClassType/StructType.
        ResolveAccessibilityAndSealed(symbolTable);

        // Pass 2e (Phase A): Resolve extension block receiver types and register
        // member signatures in the ExtensionRegistry. This runs BEFORE Pass 2 so
        // that extension members are available during member lookup fallback.
        // Only receiver types and member signatures are resolved here; method
        // bodies are resolved in Phase B (after Pass 2) because they may
        // reference expressions that require full type resolution.
        var extensionRegistry = new ExtensionRegistry();
        Pass2_RegisterExtensionMembers(extensionBlockScopes, globalScope, symbolTable, ambientTypeResolver, extensionRegistry, diagnostics);

        // Pass 2e (Phase A, cont.): Register ambient extension methods from .NET assemblies.
        // Collect all imported namespaces from using directives and global usings,
        // then scan those namespaces for C# extension methods and register them
        // in the ExtensionRegistry alongside Mist-native extensions.
        if(ambientTypeResolver is Backends.CSharpTranspiler.AssemblyTypeProvider ambientAssemblyProvider)
        {
            var allImportedNamespaces = new HashSet<string>();
            for(var i = 0; i < asts.Length; i++)
            {
                if(asts[i] is CompilationUnitNode cu)
                {
                    var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;
                    foreach(var usingDecl in cu.Usings)
                    {
                        var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
                        if(!string.IsNullOrEmpty(usingName))
                        {
                            _ = allImportedNamespaces.Add(usingName);
                        }
                    }
                    // Also collect using directives that appear after a file-scoped namespace
                    // (parsed as UsingItem top-level items rather than CompilationUnit.Usings).
                    foreach(var item in cu.Items)
                    {
                        if(item is UsingItemTopLevelItemNode usingItem)
                        {
                            var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                            if(!string.IsNullOrEmpty(usingName))
                            {
                                _ = allImportedNamespaces.Add(usingName);
                            }
                        }
                    }
                }

                if(i < compilation.Units.Length)
                {
                    foreach(var globalNs in compilation.Units[i].GlobalUsings)
                    {
                        if(!string.IsNullOrEmpty(globalNs))
                        {
                            _ = allImportedNamespaces.Add(globalNs);
                        }
                    }
                }
            }

            RegisterAmbientExtensions(ambientAssemblyProvider, extensionRegistry, allImportedNamespaces.ToList());
        }

        // Pass 2: Resolve types and build expression types.
        // Set the extension registry context so LookupMemberType can perform
        // extension member fallback without threading the registry through
        // the entire deep call chain.
        extensionRegistryContext = extensionRegistry;
        var expressionTypes = new Dictionary<Storm.Runtime.SyntaxNode, IType>();
        for(var i = 0; i < asts.Length; i++)
        {
            var ast = asts[i];
            var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;
            var unitHasTopLevelStatements = i < compilation.Units.Length && compilation.Units[i].HasTopLevelStatements;
            var unitGlobalUsings = i < compilation.Units.Length
                ? compilation.Units[i].GlobalUsings
                : ImmutableArray<string>.Empty;

            try
            {
                Pass2_ResolveTypes(ast, globalScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, unitHasTopLevelStatements, diagnostics, unitGlobalUsings);
            }
            catch(Exception ex)
            {
                diagnostics.Report(SemanticDiagnostics.SemanticError, default, "<unknown>", (object)$"Error during type resolution: {ex.Message}");
            }
        }

        extensionRegistryContext = null;

        // Pass 2e (Phase B): Resolve extension block method/property bodies.
        // This runs after Pass 2 so that expression types are available for
        // body resolution.
        Pass2_ResolveExtensionBodies(extensionBlockScopes, globalScope, symbolTable, expressionTypes, ambientTypeResolver, asts, compilation, diagnostics);

        // Post-Pass 2: Resolve named type parameter constraints.
        // During Pass 1, NamedConstraintDependentTypeParameter nodes stored
        // the constraint name as PendingConstraintName with ErrorType as a
        // placeholder. Now that type aliases are resolved in Pass 2, we can
        // look up the constraint, validate it is a RefinementType with an
        // allowed base type, and update the DependentTypeParameterType.
        Pass2_ResolveNamedTypeParameterConstraints(symbolTable, globalScope, asts, compilation, diagnostics);

        // Post-Pass 2: Fix up DependentValueArguments created during Pass 2.
        // When Pass 2 resolved type arguments at positions corresponding to named-constraint
        // dependent parameters, the DependentTypeParameterType.ValueType was still ErrorType
        // (the placeholder). Now that constraints are resolved, update those arguments.
        FixUpDependentValueArguments(symbolTable, expressionTypes);

        // Post-Pass 2: Resolve adhoc refinement constraints.
        // This runs after Pass 2 so that parameter symbols are registered and
        // can be looked up by name. Attaches predicates to dependent type
        // parameters and stores parameter refinements in the lookup map.
        Pass2_ResolveAdhocRefinementConstraints(symbolTable, diagnostics, parameterRefinements);

        // Post-Pass 2: Validate refinement constraint satisfaction for
        // abstract type method implementations (Liskov Substitution).
        // This runs after adhoc refinement constraints are resolved so that
        // parameter refinement predicates are available for both abstract type
        // methods and their implementations.
        Pass2_ValidateRefinementConstraintSatisfaction(
            symbolTable, parameterRefinements, diagnostics);

        // Post-Pass 2: Check for duplicate extension member signatures across
        // all extension blocks for the same receiver type (Requirement 8.9, 20.4, 20.7).
        Pass2_CheckDuplicateExtensionSignatures(extensionRegistry, symbolTable, diagnostics);

        // Post-Pass 2: Compute defaultability for all class and struct types.
        // This runs after type resolution because field types must be resolved
        // to determine whether they are defaultable. The pass builds a
        // dependency graph and processes types in topological order.
        ComputeDefaultability(symbolTable, compilation, diagnostics);

        // Post-Pass 2: Compute stampability for all struct types.
        // A struct is stampable iff every instance field is transitively a
        // primitive or another stampable struct. Classes are never stampable.
        // This runs after field types are resolved (same timing as defaultability).
        ComputeStampability(symbolTable);

        // Post-Pass 2: Check for member redeclarations in derived classes.
        // This runs after type resolution so that parameter types are resolved
        // and method signatures can be compared accurately for overloading.
        Pass1_CheckMemberRedeclarations(symbolTable, asts, compilation, diagnostics);

        // Post-Pass 2: Check for duplicate method/constructor signatures.
        // This runs after type resolution so that parameter types are resolved
        // and signatures can be compared accurately.
        Pass1_CheckDuplicateSignatures(symbolTable, asts, compilation, diagnostics);

        // Post-Pass 2: Recognize Drop() methods on class/struct types.
        // This runs after method return types are resolved (Pass 2) so that the
        // Drop() return type can be recorded. A method named "Drop" with zero
        // parameters marks its declaring type as having a drop method
        // (drop-semantics tasks 2.4, 3.4). The void aliases Task/ValueTask
        // inherit this from their generic forms because discipline and drop
        // state live on the shared generic ClassType definition.
        RecognizeDropMethods(symbolTable);

        // Post-Pass 3: Propagate IsOwnedField for owned types (Req 3 AC 1).
        // All instance fields of an owned type are implicitly owned.
        PropagateOwnedFieldsForOwnedTypes(symbolTable);

        // Clear the thread-local stdlib provider to prevent stale references
        // to this compilation's scopes from leaking to subsequent compilations
        // on the same thread.
        if(ambientTypeResolver is Backends.CSharpTranspiler.AssemblyTypeProvider)
        {
            Backends.CSharpTranspiler.AssemblyTypeProvider.ClearStdlibProvider();
        }

        return new SemanticModel(
            compilation,
            compilation.Units.Select(u => u).ToList(),
            asts,
            globalScope,
            symbolTable,
            expressionTypes,
            extensionRegistry,
            conformanceMap,
            parameterRefinements,
            discardedTaskResult);
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Inferred Namespace Computation
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Computes the inferred namespace for a source file based on its location
    /// relative to the project folder.
    /// </summary>
    /// <param name="namespaceRoot">The root namespace segment (from mist.toml or project name).</param>
    /// <param name="projectFolder">The absolute path to the project folder.</param>
    /// <param name="filePath">The absolute path to the source file.</param>
    /// <returns>The inferred namespace string.</returns>
    internal static string ComputeInferredNamespace(
        string namespaceRoot, string projectFolder, string filePath)
    {
        var fileDir = Path.GetDirectoryName(filePath);
        if(string.IsNullOrEmpty(fileDir))
        {
            return namespaceRoot;
        }

        var relativePath = Path.GetRelativePath(projectFolder, fileDir);
        if(relativePath == "." || string.IsNullOrEmpty(relativePath))
        {
            return namespaceRoot;
        }

        var segments = relativePath
            .Replace(Path.DirectorySeparatorChar, '.')
            .Replace(Path.AltDirectorySeparatorChar, '.');
        return $"{namespaceRoot}.{segments}";
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1 — Register user-defined types
    // ═══════════════════════════════════════════════════════════════════════

    private static void Pass1_RegisterTypes(
        Storm.Runtime.SyntaxNode ast,
        Scope globalScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        string namespaceRoot,
        string projectFolder,
        DiagnosticBag diagnostics,
        Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)>? extensionBlockScopes = null)
    {
        if(ast is not CompilationUnitNode compilationUnit)
        {
            return;
        }

        // Compute the inferred namespace for this file based on its path.
        var filePath = sourceText?.Path ?? "";
        var inferredNamespace = string.IsNullOrEmpty(filePath)
            ? namespaceRoot
            : ComputeInferredNamespace(namespaceRoot, projectFolder, filePath);

        // Track the "current namespace" — initially the inferred namespace.
        var currentNamespace = inferredNamespace;
        var currentScope = GetOrCreateNamespaceScope(globalScope, symbolTable, currentNamespace, ast);

        // Iterate over TopLevelItem nodes.
        foreach(var item in compilationUnit.Items)
        {
            switch(item)
            {
                case NamespaceItemTopLevelItemNode nsItem:
                    {
                        var nsDecl = nsItem.NamespaceDeclaration;
                        var declaredName = ExtractNamespaceName(nsDecl, sourceText);

                        if(nsDecl is FileScopedNamespaceNamespaceDeclarationNode)
                        {
                            // File-scoped: update current namespace for subsequent types.
                            currentNamespace = declaredName;
                            currentScope = GetOrCreateNamespaceScope(globalScope, symbolTable, currentNamespace, nsDecl);

                            // Register all body items (types, aliases, newtypes, extensions, nested namespaces).
                            RegisterNamespaceBody(nsDecl, currentScope, currentNamespace, globalScope, symbolTable, sourceText, diagnostics, extensionBlockScopes);
                        }
                        else if(nsDecl is BlockNamespaceNamespaceDeclarationNode)
                        {
                            // Block: register only enclosed types; current namespace unchanged after block.
                            var blockScope = GetOrCreateNamespaceScope(globalScope, symbolTable, declaredName, nsDecl);

                            // Register all body items (types, aliases, newtypes, extensions, nested namespaces).
                            RegisterNamespaceBody(nsDecl, blockScope, declaredName, globalScope, symbolTable, sourceText, diagnostics, extensionBlockScopes);
                        }

                        break;
                    }
                case TypeItemTopLevelItemNode typeItem:
                    {
                        // Register type under the current namespace.
                        RegisterTypeDeclaration(typeItem.TypeDeclaration, currentScope, symbolTable, currentNamespace, sourceText, diagnostics);
                        break;
                    }
                case ExtensionItemTopLevelItemNode extensionItem:
                    {
                        // Create a placeholder scope for the extension block and register
                        // type parameters (if generic). The scope is stored for Pass 2
                        // to resolve the receiver type and register member symbols.
                        RegisterExtensionBlock(extensionItem.ExtensionDeclaration, currentScope, currentNamespace, sourceText, diagnostics, extensionBlockScopes);
                        break;
                    }
                case StatementItemTopLevelItemNode:
                    {
                        // Top-level statements don't declare types — skip during type registration.
                        break;
                    }
            }
        }
    }

    /// <summary>
    /// Registers all body items within a namespace declaration (types, type aliases, newtypes,
    /// extension blocks, and nested namespace declarations). Handles nested namespaces by
    /// computing the nested FQN and recursively processing the nested namespace's body.
    /// </summary>
    private static void RegisterNamespaceBody(
        NamespaceDeclarationNode nsDecl,
        Scope namespaceScope,
        string namespaceFqn,
        Scope globalScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)>? extensionBlockScopes = null)
    {
        var bodyItems = nsDecl switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Body,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Body,
            _ => ImmutableArray<NamespaceBodyItemNode>.Empty
        };

        foreach(var bodyItem in bodyItems)
        {
            switch(bodyItem)
            {
                case NamespaceTypeItemNamespaceBodyItemNode typeItem:
                    RegisterTypeDeclaration(typeItem.TypeDeclaration, namespaceScope, symbolTable, namespaceFqn, sourceText, diagnostics);
                    break;

                case NamespaceExtensionItemNamespaceBodyItemNode extensionItem:
                    RegisterExtensionBlock(extensionItem.ExtensionDeclaration, namespaceScope, namespaceFqn, sourceText, diagnostics, extensionBlockScopes);
                    break;

                case NamespaceNamespaceItemNamespaceBodyItemNode nsBodyItem:
                    var nestedNsDecl = nsBodyItem.NamespaceDeclaration;
                    var nestedDeclaredName = ExtractNamespaceName(nestedNsDecl, sourceText);
                    var nestedFqn = namespaceFqn + "." + nestedDeclaredName;
                    var nestedScope = GetOrCreateNamespaceScope(globalScope, symbolTable, nestedFqn, nestedNsDecl);
                    // Recursively register types and nested namespaces within.
                    RegisterNamespaceBody(nestedNsDecl, nestedScope, nestedFqn, globalScope, symbolTable, sourceText, diagnostics, extensionBlockScopes);
                    break;
            }
        }
    }

    /// <summary>
    /// Gets or creates a namespace scope for the given namespace name.
    /// Reuses an existing scope if the namespace was already registered by a previous file.
    /// </summary>
    private static Scope GetOrCreateNamespaceScope(
        Scope globalScope,
        SymbolTable symbolTable,
        string namespaceName,
        Storm.Runtime.SyntaxNode declaringNode)
    {
        // Fast path: check the namespace scope map first.
        namespaceScopeMap ??= new Dictionary<string, Scope>();
        if(namespaceScopeMap.TryGetValue(namespaceName, out var cached))
        {
            return cached;
        }

        // Create a new namespace scope and register the namespace symbol.
        var namespaceScope = new Scope(parent: globalScope);
        namespaceScopeMap[namespaceName] = namespaceScope;

        // Only register the namespace symbol if it doesn't already exist.
        var symbolExists = false;
        foreach(var member in globalScope.Members)
        {
            if(member.Kind == SymbolKind.Namespace && member.Name == namespaceName)
            {
                symbolExists = true;
                break;
            }
        }

        if(!symbolExists)
        {
            var namespaceSpan = ToMistSourceSpan(declaringNode.Span);
            var namespaceSymbol = new Symbol(
                namespaceName,
                SymbolKind.Namespace,
                SymbolOrigin.UserCode,
                globalScope,
                declaredType: null,
                namespaceSpan);

            globalScope.AddMember(namespaceSymbol);
            symbolTable.Register(namespaceSymbol, declaringNode);
        }

        return namespaceScope;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1: Namespace Declaration Validation
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Validates namespace declarations within a compilation unit:
    /// - Detects duplicate file-scoped namespaces (MIST0301).
    /// - Detects mixed file-scoped and block namespaces (MIST0302).
    /// - Detects file-scoped namespace declarations inside block namespaces (MIST0305).
    /// </summary>
    private static void Pass1_ValidateNamespaceDeclarations(
        CompilationUnitNode cu,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var fileScopedCount = 0;
        var hasBlockNamespace = false;
        var hasFileScopedNamespace = false;

        foreach(var item in cu.Items)
        {
            if(item is not NamespaceItemTopLevelItemNode nsItem)
            {
                continue;
            }

            var nsDecl = nsItem.NamespaceDeclaration;

            if(nsDecl is FileScopedNamespaceNamespaceDeclarationNode)
            {
                fileScopedCount++;

                if(fileScopedCount > 1)
                {
                    // MIST0301: Only one file-scoped namespace is permitted per file.
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST0301",
                        DiagnosticSeverity.Error,
                        "Only one file-scoped namespace is permitted per file.",
                        nsDecl,
                        sourceText));
                }
                else if(hasBlockNamespace)
                {
                    // MIST0302: File-scoped and block namespaces cannot be mixed.
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST0302",
                        DiagnosticSeverity.Error,
                        "File-scoped and block namespaces cannot be mixed in the same file.",
                        nsDecl,
                        sourceText));
                }

                hasFileScopedNamespace = true;

                // Check for file-scoped namespaces nested inside this file-scoped namespace's body.
                CheckForFileScopedInsideBlock(nsDecl, sourceText, diagnostics);
            }
            else if(nsDecl is BlockNamespaceNamespaceDeclarationNode)
            {
                if(hasFileScopedNamespace)
                {
                    // MIST0302: File-scoped and block namespaces cannot be mixed.
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST0302",
                        DiagnosticSeverity.Error,
                        "File-scoped and block namespaces cannot be mixed in the same file.",
                        nsDecl,
                        sourceText));
                }

                hasBlockNamespace = true;

                // Check for file-scoped namespaces nested inside this block namespace's body.
                CheckForFileScopedInsideBlock(nsDecl, sourceText, diagnostics);
            }
        }
    }

    /// <summary>
    /// Recursively checks namespace bodies for file-scoped namespace declarations
    /// that appear inside block namespaces (MIST0305).
    /// </summary>
    private static void CheckForFileScopedInsideBlock(
        NamespaceDeclarationNode nsDecl,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var bodyItems = nsDecl switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Body,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Body,
            _ => ImmutableArray<NamespaceBodyItemNode>.Empty
        };

        foreach(var bodyItem in bodyItems)
        {
            if(bodyItem is not NamespaceNamespaceItemNamespaceBodyItemNode nestedNsItem)
            {
                continue;
            }

            var nestedNsDecl = nestedNsItem.NamespaceDeclaration;

            if(nestedNsDecl is FileScopedNamespaceNamespaceDeclarationNode)
            {
                // MIST0305: File-scoped namespace declarations cannot appear inside a block namespace.
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST0305",
                    DiagnosticSeverity.Error,
                    "File-scoped namespace declarations cannot appear inside a block namespace.",
                    nestedNsDecl,
                    sourceText));
            }
            else if(nestedNsDecl is BlockNamespaceNamespaceDeclarationNode)
            {
                // Recursively check nested block namespaces for file-scoped declarations.
                CheckForFileScopedInsideBlock(nestedNsDecl, sourceText, diagnostics);
            }
        }
    }

    private static void RegisterTypeDeclaration(
        TypeDeclarationNode typeDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // When namespaceName is null, this is a nested type being registered inside a parent type's scope.
        // Check for duplicate nested type names and type parameter conflicts.
        if(namespaceName is null)
        {
            var (nestedTypeName, declNode) = GetTypeDeclarationNameAndNode(typeDecl);
            if(nestedTypeName is not null && declNode is not null)
            {
                // Find the parent type name for diagnostic messages.
                var parentTypeName = FindParentTypeName(parentScope, symbolTable);

                // MIST0304: Check if the nested type name conflicts with a type parameter on the parent.
                foreach(var member in parentScope.Members)
                {
                    if(member.Name == nestedTypeName
                        && member.DeclaredType is TypeParameterType or DependentTypeParameterType)
                    {
                        var parent = parentTypeName ?? "<unknown>";
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            NestedTypeConflictsWithTypeParameter.Value,
                            DiagnosticSeverity.Error,
                            $"Type '{nestedTypeName}' conflicts with type parameter '{nestedTypeName}' on '{parent}'.",
                            declNode,
                            sourceText));
                        return; // Skip registration to avoid cascading errors.
                    }
                }

                // MIST0303: Check if the name already exists as a type in the parent type's scope.
                foreach(var member in parentScope.Members)
                {
                    if(member.Name == nestedTypeName
                        && member.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.Enum
                        && member.DeclaredType is not TypeParameterType and not DependentTypeParameterType)
                    {
                        var parent = parentTypeName ?? "<unknown>";
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DuplicateNestedType.Value,
                            DiagnosticSeverity.Error,
                            $"Duplicate type '{nestedTypeName}' in type '{parent}'.",
                            declNode,
                            sourceText));
                        return; // Skip registration to avoid cascading errors.
                    }
                }
            }
        }

        switch(typeDecl)
        {
            case BodyTypeTypeDeclarationNode body:
                switch(body.TypeBody.Keyword)
                {
                    case ClassKeywordTypeKeywordNode:
                        RegisterClassDeclaration(body.TypeBody, parentScope, symbolTable, namespaceName, sourceText, diagnostics);
                        break;
                    case StructKeywordTypeKeywordNode:
                        RegisterStructDeclaration(body.TypeBody, parentScope, symbolTable, namespaceName, sourceText, diagnostics);
                        break;
                    case AbstractKeywordTypeKeywordNode:
                        RegisterAbstractDeclaration(body.TypeBody, parentScope, symbolTable, namespaceName, sourceText, diagnostics);
                        break;
                }

                break;
            case EnumTypeTypeDeclarationNode enumTypeNode:
                RegisterEnumDeclaration(
                    enumTypeNode.EnumDeclaration,
                    parentScope, symbolTable, namespaceName, sourceText, diagnostics);
                break;
            case NewtypeTypeTypeDeclarationNode newtypeTypeNode:
                RegisterNewtypeDeclaration(newtypeTypeNode.NewtypeDeclaration, parentScope, symbolTable, sourceText, diagnostics);
                break;
            case TypeAliasTypeTypeDeclarationNode typeAliasTypeNode:
                RegisterTypeAliasDeclaration(typeAliasTypeNode.TypeAliasDeclaration, parentScope, symbolTable, sourceText, diagnostics);
                break;
        }
    }

    /// <summary>
    /// Extracts the type name and the declaration syntax node from a <see cref="TypeDeclarationNode"/>.
    /// Used for duplicate/conflict checking before registration.
    /// </summary>
    private static (string? Name, Storm.Runtime.SyntaxNode? DeclNode) GetTypeDeclarationNameAndNode(TypeDeclarationNode typeDecl)
    {
        return typeDecl switch
        {
            BodyTypeTypeDeclarationNode body => (body.TypeBody.Name.Lexeme, body.TypeBody),
            EnumTypeTypeDeclarationNode et => (et.EnumDeclaration.Name.Lexeme, et.EnumDeclaration),
            NewtypeTypeTypeDeclarationNode nt => (nt.NewtypeDeclaration.Name.Lexeme, nt.NewtypeDeclaration),
            TypeAliasTypeTypeDeclarationNode ta => (ta.TypeAliasDeclaration.Name.Lexeme, ta.TypeAliasDeclaration),
            _ => (null, null),
        };
    }

    /// <summary>
    /// Finds the name of the parent type that owns the given type scope.
    /// Searches the parent scope's parent for a type symbol whose MemberScope matches.
    /// </summary>
    private static string? FindParentTypeName(Scope typeScope, SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is not (SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.Enum))
            {
                continue;
            }

            var memberScope = symbol.DeclaredType switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                AbstractType it => it.MemberScope,
                EnumType et => et.MemberScope,
                _ => null,
            };

            if(memberScope is not null && ReferenceEquals(memberScope, typeScope))
            {
                return symbol.Name;
            }
        }

        return null;
    }

    private static void RegisterClassDeclaration(
        TypeBodyDeclarationNode classDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // MIST2001: The 'ref' modifier is only valid on struct declarations.
        if(HasRefModifier(classDecl.Modifiers))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                RefModifierOnlyValidOnStruct.Value,
                DiagnosticSeverity.Error,
                "The 'ref' modifier is only valid on struct declarations.",
                classDecl,
                sourceText));
        }

        var className = classDecl.Name.Lexeme;
        var typeScope = new Scope(parent: parentScope);
        var isBackendBacked = HasIntrinsicModifier(classDecl.Modifiers);
        var classType = new ClassType(className, typeScope, namespaceName, isBackendBacked);

        var isReadonly = HasReadonlyModifier(classDecl.Modifiers);
        classType.IsReadonly = isReadonly;

        classType.IsOwnedType = HasOwnedModifier(classDecl.Modifiers);

        // Resolve the substructural discipline from the type's modifiers.
        // affine/linear imply owned (write-through to IsOwnedType); relevant and
        // None leave IsOwnedType governed by the existing owned-modifier logic.
        // Conflicting combinations resolve to None here; the conflicting-modifier
        // diagnostic is reported by DropAnalyzer (drop-semantics task 5.1).
        var classDiscipline = ResolveDiscipline(classDecl.Modifiers);
        classType.Discipline = classDiscipline;
        if(classDiscipline is SubstructuralDiscipline.Affine or SubstructuralDiscipline.Linear)
        {
            classType.IsOwnedType = true;
        }

        var classSpan = ToMistSourceSpan(classDecl.Name.Span);
        var classSymbol = new Symbol(className, SymbolKind.Class, SymbolOrigin.UserCode, parentScope, classType, classSpan);

        parentScope.AddMember(classSymbol);
        symbolTable.Register(classSymbol, classDecl);

        // Register type parameters if present.
        RegisterTypeParameters(classDecl.TypeParams, className, typeScope, classType, sourceText, diagnostics);

        foreach(var memberDecl in classDecl.Members)
        {
            RegisterMemberDeclaration(memberDecl, typeScope, symbolTable, sourceText, diagnostics);
        }

        // If the type is readonly, set all members to ImplicitReadonly.
        if(isReadonly)
        {
            SetMembersImplicitReadonly(typeScope);
        }
    }

    private static void RegisterStructDeclaration(
        TypeBodyDeclarationNode structDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var structName = structDecl.Name.Lexeme;
        var typeScope = new Scope(parent: parentScope);
        var isBackendBacked = HasIntrinsicModifier(structDecl.Modifiers);

        // Standard.Span<T, Length> / Standard.ReadOnlySpan<T, Length> are canonical
        // backend-backed ref-struct intrinsics (R1.3/R2.3): the registration MUST set
        // IsRefStruct and IsBackendBacked to true. The declaration already carries
        // `intrinsic public ref struct`, so the normal modifier path satisfies this;
        // force the invariant defensively in case those modifiers were incomplete so
        // an inconsistent type is never registered.
        var isCanonicalSpan = namespaceName == "Standard"
            && (structName == "Span" || structName == "ReadOnlySpan");
        if(isCanonicalSpan)
        {
            isBackendBacked = true;
        }

        var structType = new StructType(structName, typeScope, namespaceName, isBackendBacked);

        var isReadonly = HasReadonlyModifier(structDecl.Modifiers);
        structType.IsReadonly = isReadonly;

        structType.IsRefStruct = HasRefModifier(structDecl.Modifiers);
        if(isCanonicalSpan)
        {
            structType.IsRefStruct = true;
        }

        structType.IsOwnedType = HasOwnedModifier(structDecl.Modifiers);

        // Resolve the substructural discipline from the type's modifiers.
        // affine/linear imply owned (write-through to IsOwnedType); relevant and
        // None leave IsOwnedType governed by the existing owned-modifier logic.
        // Conflicting combinations resolve to None here; the conflicting-modifier
        // diagnostic is reported by DropAnalyzer (drop-semantics task 5.1).
        var structDiscipline = ResolveDiscipline(structDecl.Modifiers);
        structType.Discipline = structDiscipline;
        if(structDiscipline is SubstructuralDiscipline.Affine or SubstructuralDiscipline.Linear)
        {
            structType.IsOwnedType = true;
        }

        var structSpan = ToMistSourceSpan(structDecl.Name.Span);
        var structSymbol = new Symbol(structName, SymbolKind.Struct, SymbolOrigin.UserCode, parentScope, structType, structSpan);

        parentScope.AddMember(structSymbol);
        symbolTable.Register(structSymbol, structDecl);

        // Register type parameters if present.
        RegisterTypeParameters(structDecl.TypeParams, structName, typeScope, structType, sourceText, diagnostics);

        foreach(var memberDecl in structDecl.Members)
        {
            RegisterMemberDeclaration(memberDecl, typeScope, symbolTable, sourceText, diagnostics);
        }

        // If the type is readonly, set all members to ImplicitReadonly.
        if(isReadonly)
        {
            SetMembersImplicitReadonly(typeScope);
        }
    }

    private static void RegisterAbstractDeclaration(
        TypeBodyDeclarationNode abstractDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // MIST2001: The 'ref' modifier is only valid on struct declarations.
        if(HasRefModifier(abstractDecl.Modifiers))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                RefModifierOnlyValidOnStruct.Value,
                DiagnosticSeverity.Error,
                "The 'ref' modifier is only valid on struct declarations.",
                abstractDecl,
                sourceText));
        }

        var abstractName = abstractDecl.Name.Lexeme;
        var typeScope = new Scope(parent: parentScope);
        var abstractType = new AbstractType(abstractName, typeScope, namespaceName);

        var isReadonly = HasReadonlyModifier(abstractDecl.Modifiers);
        abstractType.IsReadonly = isReadonly;

        var abstractSpan = ToMistSourceSpan(abstractDecl.Name.Span);
        var abstractSymbol = new Symbol(abstractName, SymbolKind.Abstract, SymbolOrigin.UserCode, parentScope, abstractType, abstractSpan);

        parentScope.AddMember(abstractSymbol);
        symbolTable.Register(abstractSymbol, abstractDecl);

        // Register type parameters if present.
        RegisterTypeParameters(abstractDecl.TypeParams, abstractName, typeScope, abstractType, sourceText, diagnostics);

        foreach(var member in abstractDecl.Members)
        {
            switch(member)
            {
                case MethodMemberMemberDeclarationNode methodMember
                    when methodMember.Method.Body is CallableNoBodyCallableBodyNode:
                    RegisterAbstractMethodDeclaration(methodMember.Method, typeScope, symbolTable, sourceText, diagnostics);
                    break;
                case MethodMemberMemberDeclarationNode defaultMethodMember
                    when defaultMethodMember.Method.Body is CallableBlockBodyCallableBodyNode:
                    {
                        // A default method has a body. Register it as a normal method symbol so
                        // member resolution works, AND record it in DefaultMethods so the type
                        // checker can distinguish defaults (which implementers may omit) from slots.
                        var defaultSymbol = RegisterMethodDeclaration(
                            defaultMethodMember.Method, typeScope, symbolTable, sourceText, diagnostics);
                        abstractType.DefaultMethods[defaultMethodMember.Method.Name.Lexeme] = defaultSymbol;
                        break;
                    }
                case PropertyMemberMemberDeclarationNode propertyMember:
                    RegisterAbstractPropertyDeclaration(propertyMember.Property, typeScope, symbolTable);
                    break;
                case AssociatedTypeMemberMemberDeclarationNode associatedTypeMember:
                    RegisterAssociatedTypeSlotDeclaration(associatedTypeMember.AssociatedType, abstractType, typeScope, symbolTable, sourceText, diagnostics);
                    break;
            }
        }

        // Check for duplicate associated type slot names.
        DetectDuplicateAssociatedTypeSlots(abstractDecl.Members, abstractName, sourceText, diagnostics);

        // If the abstract type is readonly, set all members to ImplicitReadonly.
        if(isReadonly)
        {
            SetMembersImplicitReadonly(typeScope);
        }
    }


    private static void RegisterEnumDeclaration(
        EnumDeclarationNode enumDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // MIST2001: The 'ref' modifier is only valid on struct declarations.
        if(HasRefModifier(enumDecl.Modifiers))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                RefModifierOnlyValidOnStruct.Value,
                DiagnosticSeverity.Error,
                "The 'ref' modifier is only valid on struct declarations.",
                enumDecl,
                sourceText));
        }

        var enumName = enumDecl.Name.Lexeme;
        var typeScope = new Scope(parent: parentScope);
        var enumType = new EnumType(enumName, typeScope, namespaceName);

        var enumSpan = ToMistSourceSpan(enumDecl.Name.Span);
        var enumSymbol = new Symbol(enumName, SymbolKind.Enum, SymbolOrigin.UserCode, parentScope, enumType, enumSpan);

        parentScope.AddMember(enumSymbol);
        symbolTable.Register(enumSymbol, enumDecl);

        // Register each enum member as a field symbol in the enum's MemberScope.
        if(enumDecl.Members is not null)
        {
            var members = new List<EnumMemberNode> { enumDecl.Members.EnumMember };
            foreach(var member in enumDecl.Members.EnumMembers)
            {
                members.Add(member);
            }

            foreach(var member in members)
            {
                var memberName = member.Name.Lexeme;
                var memberSpan = ToMistSourceSpan(member.Name.Span);
                var memberSymbol = new Symbol(memberName, SymbolKind.Field, SymbolOrigin.UserCode, typeScope, declaredType: enumType, memberSpan);
                typeScope.AddMember(memberSymbol);
                symbolTable.Register(memberSymbol, member);
            }
        }
    }

    /// <summary>
    /// Registers a type alias declaration as a symbol in the enclosing scope.
    /// Reports <see cref="DuplicateTypeAlias"/> if the name already exists in scope.
    /// </summary>
    private static void RegisterTypeAliasDeclaration(
        TypeAliasDeclarationNode aliasDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var aliasName = aliasDecl.Name.Lexeme;
        var aliasSpan = ToMistSourceSpan(aliasDecl.Name.Span);

        // Check for duplicate alias name in the same scope.
        // Type aliases participate in arity-based overloading: an alias may coexist
        // with another alias or a class/struct/abstract type of the same name as long as
        // they declare a different number of type parameters (e.g., the Action family
        // `type Action = Func<void>;` through `type Action<T1, ..., T16> = ...;`, and
        // `type Task = Task<void>;` alongside `class Task<TResult>`).
        var aliasTypeParams = aliasDecl.TypeParams;
        // A TypeParameterListNode stores its first parameter separately (TypeParameter)
        // from the remaining ones (TypeParameters), so the arity is 1 + the rest.
        var aliasArity = aliasTypeParams is null ? 0 : 1 + aliasTypeParams.TypeParameters.Length;

        foreach(var member in parentScope.Members)
        {
            if(member.Name != aliasName)
            {
                continue;
            }

            // Compute the existing member's arity. Aliases registered in Pass 1 have a
            // null DeclaredType, so fall back to the symbol's TypeParameters list.
            var memberArity = member.DeclaredType switch
            {
                ClassType ct => ct.TypeParameters.Count,
                StructType st => st.TypeParameters.Count,
                AbstractType it => it.TypeParameters.Count,
                _ => (member as Symbol)?.TypeParameters.Count ?? 0,
            };

            // Different arity — not a conflict (arity-based overloading).
            if(memberArity != aliasArity)
            {
                continue;
            }

            diagnostics.Add(MakeDiagnosticWithLocation(
                DuplicateTypeAlias.Value,
                DiagnosticSeverity.Error,
                $"Type alias '{aliasName}' is already defined in this scope.",
                aliasDecl,
                sourceText));
            return;
        }

        // Extract type parameters (if generic alias).
        var typeParams = ExtractTypeParameters(aliasDecl.TypeParams, aliasName, sourceText, diagnostics);

        // Create the symbol with a null DeclaredType — it will be set in Pass 2
        // after the target type reference is resolved.
        var aliasSymbol = new Symbol(
            aliasName,
            SymbolKind.TypeAlias,
            SymbolOrigin.UserCode,
            parentScope,
            declaredType: null,
            aliasSpan)
        {
            // Store type parameters on the symbol for later resolution.
            TypeParameters = typeParams
        };

        parentScope.AddMember(aliasSymbol);
        symbolTable.Register(aliasSymbol, aliasDecl);
    }

    /// <summary>
    /// Registers a member-level type alias declaration (e.g., <c>public type ArrayBounds = ZeroOrPositiveInt and &lt; Length;</c>)
    /// as a symbol in the enclosing type's scope. The <c>DeclaredType</c> is left null during Pass 1 and
    /// resolved during Pass 2 when the target type expression is processed.
    /// </summary>
    private static void RegisterMemberTypeAliasDeclaration(
        TypeAliasDeclarationNode aliasDecl,
        Scope typeScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var aliasName = aliasDecl.Name.Lexeme;
        var aliasSpan = ToMistSourceSpan(aliasDecl.Name.Span);

        // Extract type parameters (if generic alias).
        var typeParams = ExtractTypeParameters(aliasDecl.TypeParams, aliasName, sourceText, diagnostics);

        // Create the symbol with a null DeclaredType — it will be set in Pass 2
        // after the target type reference is resolved.
        var aliasSymbol = new Symbol(
            aliasName,
            SymbolKind.TypeAlias,
            SymbolOrigin.UserCode,
            typeScope,
            declaredType: null,
            aliasSpan)
        {
            // Store type parameters on the symbol for later resolution.
            TypeParameters = typeParams
        };

        typeScope.AddMember(aliasSymbol);
        symbolTable.Register(aliasSymbol, aliasDecl);
    }

    /// <summary>
    /// Registers a newtype declaration as a symbol in the enclosing scope.
    /// Reports <see cref="DuplicateNewtype"/> if the name already exists in scope.
    /// The <c>DeclaredType</c> is left null — it will be set in Pass 2 after
    /// the source type reference is resolved and members are cloned.
    /// </summary>
    private static void RegisterNewtypeDeclaration(
        NewtypeDeclarationNode newtypeDecl,
        Scope parentScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var name = newtypeDecl.Name.Lexeme;
        var span = ToMistSourceSpan(newtypeDecl.Name.Span);

        // Check for duplicate name in the same scope.
        foreach(var member in parentScope.Members)
        {
            if(member.Name == name)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    DuplicateNewtype.Value,
                    DiagnosticSeverity.Error,
                    $"Type '{name}' is already defined in this scope.",
                    newtypeDecl,
                    sourceText));
                return;
            }
        }

        // Create the symbol with a null DeclaredType — it will be set in Pass 2
        // after the source type reference is resolved and members are cloned.
        var newtypeSymbol = new Symbol(
            name,
            SymbolKind.Newtype,
            SymbolOrigin.UserCode,
            parentScope,
            declaredType: null,
            span);

        parentScope.AddMember(newtypeSymbol);
        symbolTable.Register(newtypeSymbol, newtypeDecl);
    }

    /// <summary>
    /// Creates a placeholder scope for an extension block and registers its type
    /// parameters (if generic). The scope is stored in the dictionary so Pass 2
    /// can resolve the receiver type and register member symbols.
    /// </summary>
    private static void RegisterExtensionBlock(
        ExtensionBlockDeclarationNode extDecl,
        Scope parentScope,
        string? namespaceName,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)>? extensionBlockScopes)
    {
        // Create a child scope for the extension block.
        var extensionScope = new Scope(parent: parentScope);

        // Register type parameters (if generic) in the extension block's scope.
        if(extDecl.TypeParams is not null)
        {
            var typeParams = ExtractTypeParameters(extDecl.TypeParams, enclosingTypeName: null, sourceText, diagnostics);
            foreach(var tp in typeParams)
            {
                var (tpName, tpOrdinal) = GetTypeParameterNameAndOrdinal(tp);
                var tpSpan = GetTypeParameterSpan(extDecl.TypeParams, tpOrdinal);
                var tpSymbol = new Symbol(tpName, SymbolKind.Class, SymbolOrigin.UserCode, extensionScope, tp, tpSpan);
                extensionScope.AddMember(tpSymbol);
            }
        }

        // Store the scope so Pass 2 can find it later.
        _ = (extensionBlockScopes?.TryAdd(extDecl, (extensionScope, namespaceName, sourceText)));
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 2e (Phase A) — Register extension member signatures
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves extension block receiver types, registers receiver parameters,
    /// registers member symbols with their declared types, and populates the
    /// <see cref="ExtensionRegistry"/>. Does NOT resolve method/property bodies
    /// (that happens in Phase B after Pass 2).
    /// </summary>
    private static void Pass2_RegisterExtensionMembers(
        Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)> extensionBlockScopes,
        Scope globalScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        ExtensionRegistry extensionRegistry,

        DiagnosticBag diagnostics)
    {
        foreach(var (extDecl, (extensionScope, namespaceName, sourceText)) in extensionBlockScopes)
        {

            // Create a file scope for type resolution that includes the
            // extension block's parent scope (which has namespace context).
            var fileScope = extensionScope.Parent is Scope parentScope
                ? parentScope
                : globalScope;

            // Resolve the receiver type reference.
            var receiverType = ResolveTypeReference(
                extDecl.ReceiverType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

            // If resolution fails (ErrorType), emit MIST_SB_0070 and skip.
            if(receiverType is ErrorType)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    ExtensionReceiverUnresolved.Value,
                    DiagnosticSeverity.Error,
                    "Extension block receiver type cannot be resolved.",
                    extDecl.ReceiverType,
                    sourceText));
                continue;
            }

            // If receiver type is void, emit MIST_SB_0074 and skip.
            if(receiverType.IsVoid())
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    ExtensionVoidReceiver.Value,
                    DiagnosticSeverity.Error,
                    "'void' cannot be used as an extension receiver type.",
                    extDecl.ReceiverType,
                    sourceText));
                continue;
            }

            // Register a parameter symbol for the receiver in the extension block's scope.
            var receiverName = extDecl.ReceiverName.Lexeme;
            var receiverSpan = ToMistSourceSpan(extDecl.ReceiverName.Span);
            var receiverSymbol = new Symbol(
                receiverName, SymbolKind.Parameter, SymbolOrigin.UserCode,
                extensionScope, receiverType, receiverSpan);
            extensionScope.AddMember(receiverSymbol);
            symbolTable.Register(receiverSymbol, extDecl);

            // Create a member scope for the extension block's members.
            var memberScope = new Scope(parent: extensionScope);

            // Walk member declarations — register symbols and resolve types (but not bodies).
            foreach(var member in extDecl.Members)
            {
                switch(member)
                {
                    case ExtensionMethodMemberExtensionMemberDeclarationNode methodMember:
                        {
                            var methodDecl = methodMember.Method;
                            var methodName = methodDecl.Name.Lexeme;
                            var methodSpan = ToMistSourceSpan(methodDecl.Name.Span);
                            var hasBody = methodDecl.Body is not CallableNoBodyCallableBodyNode;
                            var methodSymbol = new Symbol(
                                methodName, SymbolKind.Method, SymbolOrigin.UserCode,
                                memberScope, declaredType: null, methodSpan, hasBody: hasBody);
                            memberScope.AddMember(methodSymbol);
                            symbolTable.Register(methodSymbol, methodDecl);

                            // Warn if the method name shadows the receiver parameter name.
                            if(string.Equals(methodName, receiverName, StringComparison.Ordinal))
                            {
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    ExtensionMemberShadowsReceiver.Value,
                                    DiagnosticSeverity.Warning,
                                    $"Extension method '{methodName}' shadows the receiver parameter name '{receiverName}'.",
                                    methodDecl,
                                    sourceText));
                            }

                            // Emit error if any method parameter name conflicts with the receiver parameter name.
                            if(methodDecl.Parameters is not null)
                            {
                                foreach(var child in methodDecl.Parameters.Children())
                                {
                                    if(child is ParameterNode param &&
                                        string.Equals(param.Name.Lexeme, receiverName, StringComparison.Ordinal))
                                    {
                                        diagnostics.Add(MakeDiagnosticWithLocation(
                                            ExtensionParameterConflictsWithReceiver.Value,
                                            DiagnosticSeverity.Error,
                                            $"Method parameter '{param.Name.Lexeme}' conflicts with the receiver parameter name '{receiverName}'.",
                                            param,
                                            sourceText));
                                    }
                                }
                            }

                            // Register method type parameters if present.
                            RegisterMethodTypeParameters(methodDecl.TypeParams, methodSymbol, memberScope, sourceText, diagnostics);

                            // Resolve the return type.
                            var returnType = ResolveTypeReference(
                                methodDecl.ReturnType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                            // Detect async modifier and wrap return type in Task<T>.
                            var isAsync = methodDecl.Modifiers.Any(m => m is AsyncModifierModifierNode);
                            if(isAsync)
                            {
                                methodSymbol.IsAsync = true;
                                methodSymbol.DeclaredReturnType = returnType;
                                var effectiveReturnType = ConstructTaskType(returnType, fileScope, symbolTable);
                                methodSymbol.EffectiveReturnType = effectiveReturnType;
                                methodSymbol.DeclaredType = effectiveReturnType;
                            }
                            else
                            {
                                methodSymbol.DeclaredReturnType = returnType;
                                methodSymbol.EffectiveReturnType = returnType;
                                methodSymbol.DeclaredType = returnType;
                            }

                            // Register parameters.
                            if(methodDecl.Parameters is not null)
                            {
                                var methodScope = new Scope(parent: memberScope);
                                RegisterParameters(methodDecl.Parameters, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                            }

                            break;
                        }
                    case ExtensionPropertyMemberExtensionMemberDeclarationNode propertyMember:
                        {
                            var propertyDecl = propertyMember.Property;

                            // Check for set/init accessors — reject with MIST_SB_0071.
                            if(HasSetOrInitAccessor(propertyDecl))
                            {
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    ExtensionPropertyHasSetAccessor.Value,
                                    DiagnosticSeverity.Error,
                                    "Extension properties cannot declare a 'set' or 'init' accessor; extension properties are read-only.",
                                    propertyDecl switch
                                    {
                                        BlockPropertyPropertyDeclarationNode bp => bp,
                                        ExpressionBodiedPropertyPropertyDeclarationNode ep => ep,
                                        _ => member
                                    },
                                    sourceText));
                            }

                            // Register the property symbol.
                            var (propName, propSpan) = propertyDecl switch
                            {
                                BlockPropertyPropertyDeclarationNode bp => (bp.Name.Lexeme, ToMistSourceSpan(bp.Name.Span)),
                                ExpressionBodiedPropertyPropertyDeclarationNode ep => (ep.Name.Lexeme, ToMistSourceSpan(ep.Name.Span)),
                                _ => ("?", (SourceSpan?)null)
                            };
                            var propSymbol = new Symbol(
                                propName, SymbolKind.Property, SymbolOrigin.UserCode,
                                memberScope, declaredType: null, propSpan);
                            memberScope.AddMember(propSymbol);
                            symbolTable.Register(propSymbol, propertyDecl switch
                            {
                                BlockPropertyPropertyDeclarationNode bp => bp,
                                ExpressionBodiedPropertyPropertyDeclarationNode ep => ep,
                                _ => member
                            });

                            // Warn if the property name shadows the receiver parameter name.
                            if(string.Equals(propName, receiverName, StringComparison.Ordinal))
                            {
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    ExtensionMemberShadowsReceiver.Value,
                                    DiagnosticSeverity.Warning,
                                    $"Extension property '{propName}' shadows the receiver parameter name '{receiverName}'.",
                                    propertyDecl switch
                                    {
                                        BlockPropertyPropertyDeclarationNode bp => bp,
                                        ExpressionBodiedPropertyPropertyDeclarationNode ep => ep,
                                        _ => member
                                    },
                                    sourceText));
                            }

                            // Resolve the property type.
                            var propType = propertyDecl switch
                            {
                                BlockPropertyPropertyDeclarationNode bp =>
                                    ResolveTypeReference(bp.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics),
                                ExpressionBodiedPropertyPropertyDeclarationNode ep =>
                                    ResolveTypeReference(ep.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics),
                                _ => ErrorType.Instance
                            };
                            propSymbol.DeclaredType = propType;
                            break;
                        }
                    default:
                        {
                            // Invalid member (field or other) — emit MIST_SB_0072.
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                ExtensionInvalidMember.Value,
                                DiagnosticSeverity.Error,
                                "Extension blocks can only contain methods and properties.",
                                member,
                                sourceText));
                            break;
                        }
                }
            }

            // Collect type parameters from the extension block's scope.
            var typeParameters = new List<TypeParameterType>();
            foreach(var sym in extensionScope.Members)
            {
                if(sym.DeclaredType is TypeParameterType tp)
                {
                    typeParameters.Add(tp);
                }
            }

            // Create and register the ExtensionBlockInfo.
            var extensionBlockInfo = new ExtensionBlockInfo
            {
                ReceiverType = receiverType,
                ReceiverParameterName = receiverName,
                MemberScope = memberScope,
                TypeParameters = typeParameters,
                ContainingNamespace = namespaceName,
                DeclaringNode = extDecl,
            };
            extensionRegistry.Register(extensionBlockInfo);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 2e (Phase A, cont.) — Register ambient extension methods
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Queries the ambient type resolver for extension methods in each imported namespace,
    /// groups them by receiver type, projects receiver/params/return types via TypeProjector,
    /// creates ExtensionBlockInfo entries with ContainingNamespace and AmbientStaticClassName,
    /// and registers them in the ExtensionRegistry.
    /// </summary>
    private static void RegisterAmbientExtensions(
        Backends.CSharpTranspiler.AssemblyTypeProvider assemblyProvider,
        ExtensionRegistry extensionRegistry,
        IReadOnlyList<string> importedNamespaces)
    {
        var projector = assemblyProvider.Projector;
        var stdlib = assemblyProvider.CurrentStdlib;

        foreach(var ns in importedNamespaces)
        {
            var ambientExtensions = assemblyProvider.GetExtensionMethodsInNamespace(ns);
            if(ambientExtensions.Count == 0)
            {
                continue;
            }

            // Group by (receiver CLR type, containing class) so that each ExtensionBlockInfo
            // has the correct AmbientStaticClassName for emission. Different static classes
            // (e.g., Enumerable vs AsyncEnumerable) may define extension methods for the same
            // receiver type, but the emitter needs to know which class to call.
            var byReceiverAndClass = new Dictionary<(string ReceiverKey, string ClassName), List<Backends.CSharpTranspiler.AmbientExtensionMethodInfo>>();
            foreach(var ext in ambientExtensions)
            {
                var receiverKey = ext.ReceiverClrType.FullName ?? ext.ReceiverClrType.Name;
                var classKey = ext.ContainingClassName;
                var key = (receiverKey, classKey);
                if(!byReceiverAndClass.TryGetValue(key, out var list))
                {
                    list = new List<Backends.CSharpTranspiler.AmbientExtensionMethodInfo>();
                    byReceiverAndClass[key] = list;
                }

                list.Add(ext);
            }

            foreach(var (groupKey, group) in byReceiverAndClass)
            {
                // Project the receiver type from the first entry in the group.
                var receiverType = projector.ProjectMemberType(group[0].ReceiverClrType, stdlib);

                // Skip if receiver type projection fails (returns ErrorType or UnknownType).
                if(receiverType is ErrorType or UnknownType)
                {
                    continue;
                }

                var memberScope = new Scope(parent: null);

                foreach(var ext in group)
                {
                    // Project the return type.
                    var returnType = projector.ProjectMemberType(ext.ReturnClrType, stdlib);

                    // Skip if return type projection fails.
                    if(returnType is ErrorType)
                    {
                        continue;
                    }

                    var methodSymbol = new Symbol(
                        ext.MethodName,
                        SymbolKind.Method,
                        SymbolOrigin.Backend,
                        memberScope,
                        returnType,
                        null);

                    // Project remaining parameters (excluding receiver).
                    var paramScope = new Scope(parent: memberScope);
                    var paramSymbols = projector.ProjectParametersWithResult(
                        ext.RemainingParameters.ToArray(), paramScope, stdlib);
                    methodSymbol.Parameters = paramSymbols;

                    // Project method-level type parameters for generic methods.
                    if(ext.IsGenericMethod)
                    {
                        methodSymbol.TypeParameters = projector.ProjectMethodTypeParameters(
                            ext.MethodInfo, stdlib);
                    }

                    memberScope.AddMember(methodSymbol);
                }

                // Only register if at least one method was successfully projected.
                if(memberScope.Members.Count == 0)
                {
                    continue;
                }

                // Collect type parameters referenced in the receiver type.
                // For generic ambient extension methods (e.g., Count<TSource>(this IEnumerable<TSource>)),
                // the receiver type contains TypeParameterType instances that must be registered
                // on the ExtensionBlockInfo so the type checker's unification logic can filter
                // non-matching candidates (e.g., exclude IQueryable<T> extensions for int[]).
                var blockTypeParams = CollectTypeParametersFromType(receiverType);

                var blockInfo = new ExtensionBlockInfo
                {
                    ReceiverType = receiverType,
                    ReceiverParameterName = "self",
                    MemberScope = memberScope,
                    TypeParameters = blockTypeParams,
                    ContainingNamespace = ns,
                    DeclaringNode = null,
                    AmbientStaticClassName = groupKey.ClassName,
                };

                extensionRegistry.Register(blockInfo);
            }
        }
    }

    /// <summary>
    /// Collects all <see cref="TypeParameterType"/> instances referenced within a type.
    /// Used to extract type parameters from ambient extension receiver types so that
    /// the type checker's unification logic can filter non-matching candidates.
    /// </summary>
    private static TypeParameterType[] CollectTypeParametersFromType(IType type)
    {
        var result = new List<TypeParameterType>();
        CollectTypeParametersRecursive(type, result);
        return result.Count > 0 ? result.ToArray() : Array.Empty<TypeParameterType>();
    }

    private static void CollectTypeParametersRecursive(IType type, List<TypeParameterType> result)
    {
        if(type is TypeParameterType tp)
        {
            // Avoid duplicates (same type parameter referenced multiple times).
            if(!result.Any(existing => existing.Name == tp.Name && existing.Ordinal == tp.Ordinal))
            {
                result.Add(tp);
            }
        }
        else if(type is ConstructedType ct)
        {
            foreach(var arg in ct.TypeArguments)
            {
                CollectTypeParametersRecursive(arg, result);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 2e (Phase B) — Resolve extension block method/property bodies
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves extension block method and property bodies. Runs after Pass 2
    /// so that expression types are available for body resolution.
    /// </summary>
    private static void Pass2_ResolveExtensionBodies(
        Dictionary<ExtensionBlockDeclarationNode, (Scope Scope, string? Namespace, SourceText? SourceText)> extensionBlockScopes,
        Scope globalScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var (extDecl, (extensionScope, namespaceName, sourceText)) in extensionBlockScopes)
        {

            // Create a file scope for type resolution that includes the
            // extension block's parent scope (which has namespace context)
            // AND the imported namespaces from the containing compilation unit.
            var parentScope = extensionScope.Parent is Scope ps ? ps : globalScope;
            var fileScope = new Scope(parent: parentScope);

            // Add the extension's own namespace as implicitly imported.
            if(namespaceName is not null)
            {
                fileScope.AddImportedNamespace(namespaceName);
            }

            // Find the containing compilation unit to get using directives and global usings.
            var filePath = sourceText?.Path;
            CompilationUnit? containingUnit = null;
            CompilationUnitNode? containingCu = null;
            if(filePath is not null)
            {
                for(var i = 0; i < compilation.Units.Length; i++)
                {
                    if(compilation.Units[i].Source.Path == filePath)
                    {
                        containingUnit = compilation.Units[i];
                        if(i < asts.Length && asts[i] is CompilationUnitNode cu)
                        {
                            containingCu = cu;
                        }

                        break;
                    }
                }
            }

            // Register using directives from the compilation unit.
            if(containingCu is not null)
            {
                foreach(var usingDecl in containingCu.Usings)
                {
                    var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
                    if(!string.IsNullOrEmpty(usingName))
                    {
                        // Verify namespace exists before adding.
                        var nsExists = false;
                        foreach(var member in globalScope.Members)
                        {
                            if(member.Kind == SymbolKind.Namespace && member.Name == usingName)
                            {
                                nsExists = true;
                                break;
                            }
                        }

                        if(!nsExists && ambientTypeResolver is not null)
                        {
                            nsExists = ambientTypeResolver.HasNamespace(usingName);
                        }

                        if(nsExists)
                        {
                            fileScope.AddImportedNamespace(usingName);
                        }
                    }
                }
                // Also collect using directives that appear after a file-scoped namespace
                // (parsed as UsingItem top-level items rather than CompilationUnit.Usings).
                foreach(var item in containingCu.Items)
                {
                    if(item is UsingItemTopLevelItemNode usingItem)
                    {
                        var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                        if(!string.IsNullOrEmpty(usingName))
                        {
                            var nsExists = false;
                            foreach(var member in globalScope.Members)
                            {
                                if(member.Kind == SymbolKind.Namespace && member.Name == usingName)
                                {
                                    nsExists = true;
                                    break;
                                }
                            }

                            if(!nsExists && ambientTypeResolver is not null)
                            {
                                nsExists = ambientTypeResolver.HasNamespace(usingName);
                            }

                            if(nsExists)
                            {
                                fileScope.AddImportedNamespace(usingName);
                            }
                        }
                    }
                }
            }

            // Register global usings from the compilation unit.
            if(containingUnit is not null)
            {
                foreach(var globalNs in containingUnit.GlobalUsings)
                {
                    if(!string.IsNullOrEmpty(globalNs))
                    {
                        var nsExists = false;
                        foreach(var member in globalScope.Members)
                        {
                            if(member.Kind == SymbolKind.Namespace && member.Name == globalNs)
                            {
                                nsExists = true;
                                break;
                            }
                        }

                        if(!nsExists && ambientTypeResolver is not null)
                        {
                            nsExists = ambientTypeResolver.HasNamespace(globalNs);
                        }

                        if(nsExists)
                        {
                            fileScope.AddImportedNamespace(globalNs);
                        }
                    }
                }
            }

            // Find the receiver type (already resolved in Phase A).
            var receiverType = ResolveTypeReference(
                extDecl.ReceiverType, fileScope, ambientTypeResolver, symbolTable, sourceText, new DiagnosticBag());

            // Skip blocks that failed receiver resolution in Phase A.
            if(receiverType is ErrorType || receiverType.IsVoid())
            {
                continue;
            }

            // Get the receiver parameter name for static receiver access validation.
            var receiverName = extDecl.ReceiverName.Lexeme;

            // Walk member declarations — resolve bodies only.
            foreach(var member in extDecl.Members)
            {
                switch(member)
                {
                    case ExtensionMethodMemberExtensionMemberDeclarationNode methodMember:
                        {
                            var methodDecl = methodMember.Method;
                            var isStatic = methodDecl.Modifiers.Any(m => m is StaticModifierModifierNode);

                            // Resolve the body if present.
                            if(methodDecl.Body.GetBlock() is BlockNode methodBlock)
                            {
                                var bodyScope = new Scope(parent: extensionScope);

                                // Register method parameters in the body scope so they're
                                // accessible during body resolution.
                                if(methodDecl.Parameters is not null)
                                {
                                    RegisterParameters(methodDecl.Parameters, bodyScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                                }

                                ResolveBlock(methodBlock, bodyScope, fileScope, receiverType, /* isStatic */ false, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                                // Task 7.5: If this is a static extension member, check for
                                // receiver parameter references in the body → emit MIST_TC_0080.
                                if(isStatic)
                                {
                                    CheckStaticExtensionReceiverAccess(methodBlock, receiverName, sourceText, diagnostics);
                                }
                            }

                            break;
                        }
                    // Properties don't have bodies that need expression resolution
                    // (expression-bodied properties are handled by the emitter).
                    case ExtensionPropertyMemberExtensionMemberDeclarationNode propertyMember:
                        {
                            var propertyDecl = propertyMember.Property;
                            var isStatic = propertyDecl switch
                            {
                                BlockPropertyPropertyDeclarationNode bp => bp.Modifiers.Any(m => m is StaticModifierModifierNode),
                                ExpressionBodiedPropertyPropertyDeclarationNode ep => ep.Modifiers.Any(m => m is StaticModifierModifierNode),
                                _ => false,
                            };

                            // Task 7.5: If this is a static extension property, check for
                            // receiver parameter references in the property body → emit MIST_TC_0080.
                            if(isStatic)
                            {
                                switch(propertyDecl)
                                {
                                    case BlockPropertyPropertyDeclarationNode bp:
                                        foreach(var accessor in bp.Accessors)
                                        {
                                            CheckStaticExtensionReceiverAccess(accessor, receiverName, sourceText, diagnostics);
                                        }

                                        break;
                                    case ExpressionBodiedPropertyPropertyDeclarationNode ep:
                                        CheckStaticExtensionReceiverAccess(ep.Body, receiverName, sourceText, diagnostics);
                                        break;
                                }
                            }

                            break;
                        }
                }
            }
        }
    }

    /// <summary>
    /// Recursively walks an AST node tree looking for <see cref="IdentifierExpressionPrimaryNode"/>
    /// references that match the receiver parameter name. Emits <c>MIST_TC_0080</c> for each
    /// occurrence found. Used to validate that static extension members do not access the receiver.
    /// </summary>
    private static void CheckStaticExtensionReceiverAccess(
        Storm.Runtime.SyntaxNode node,
        string receiverName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(node is IdentifierExpressionPrimaryNode identifier &&
            string.Equals(identifier.Name.Lexeme, receiverName, StringComparison.Ordinal))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                ExtensionStaticReceiverAccess.Value,
                DiagnosticSeverity.Error,
                $"Static extension member cannot access the receiver parameter '{receiverName}'.",
                node,
                sourceText));
            return; // Don't recurse into children of this identifier node.
        }

        foreach(var child in node.Children())
        {
            if(child is not null)
            {
                CheckStaticExtensionReceiverAccess(child, receiverName, sourceText, diagnostics);
            }
        }
    }

    /// <summary>
    /// Checks for duplicate member signatures across all extension blocks registered
    /// for the same receiver type. Emits <c>MIST_SB_0073</c> on the second occurrence.
    /// </summary>
    private static void Pass2_CheckDuplicateExtensionSignatures(
        ExtensionRegistry extensionRegistry,
        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        foreach(var (receiverType, blocks) in extensionRegistry.AllGroups)
        {
            if(blocks.Count < 1)
            {
                continue;
            }

            // Collect all member symbols across all extension blocks for this receiver type.
            // Track which block each member came from for diagnostic reporting.
            var allMembers = new List<(ISymbol Symbol, ExtensionBlockInfo Block)>();
            foreach(var block in blocks)
            {
                foreach(var member in block.MemberScope.Members)
                {
                    if(member.Kind is SymbolKind.Method or SymbolKind.Property)
                    {
                        allMembers.Add((member, block));
                    }
                }
            }

            // Group by name, then check for duplicate signatures within each name group.
            var nameGroups = allMembers.GroupBy(m => m.Symbol.Name);
            foreach(var group in nameGroups)
            {
                var groupList = group.ToList();
                if(groupList.Count <= 1)
                {
                    continue;
                }

                // Track which members have already been reported as duplicates.
                var reported = new HashSet<int>();

                for(var i = 0; i < groupList.Count; i++)
                {
                    for(var j = i + 1; j < groupList.Count; j++)
                    {
                        if(reported.Contains(j))
                        {
                            continue;
                        }

                        var (symbolA, blockA) = groupList[i];
                        var (symbolB, blockB) = groupList[j];

                        // Skip duplicate checking between two ambient extension methods.
                        // .NET assemblies are already compiled and their overloads are valid
                        // by definition. The type projector may map different generic type
                        // parameters to the same display name, causing false positives.
                        if(blockA.IsAmbient && blockB.IsAmbient)
                        {
                            continue;
                        }

                        // For properties, same name is sufficient for a duplicate.
                        if(symbolA.Kind == SymbolKind.Property && symbolB.Kind == SymbolKind.Property)
                        {
                            _ = reported.Add(j);
                            EmitDuplicateExtensionMemberDiagnostic(
                                symbolB, blockB, receiverType, symbolTable, diagnostics);
                            continue;
                        }

                        // For methods, compare parameter signatures.
                        if(symbolA.Kind == SymbolKind.Method && symbolB.Kind == SymbolKind.Method)
                        {
                            var sigA = ParameterSignature.Extract(symbolA, symbolTable);
                            var sigB = ParameterSignature.Extract(symbolB, symbolTable);
                            var refKindsA = ParameterSignature.ExtractRefKinds(symbolA, symbolTable);
                            var refKindsB = ParameterSignature.ExtractRefKinds(symbolB, symbolTable);

                            if(ParameterSignature.AreEqualWithRefKind(sigA, refKindsA, sigB, refKindsB))
                            {
                                _ = reported.Add(j);
                                EmitDuplicateExtensionMemberDiagnostic(
                                    symbolB, blockB, receiverType, symbolTable, diagnostics);
                            }
                        }
                    }
                }
            }
        }
    }

    /// <summary>
    /// Emits the <c>MIST_SB_0073</c> diagnostic for a duplicate extension member.
    /// </summary>
    private static void EmitDuplicateExtensionMemberDiagnostic(
        ISymbol duplicateSymbol,
        ExtensionBlockInfo containingBlock,
        IType receiverType,
        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        var memberKind = duplicateSymbol.Kind == SymbolKind.Method ? "method" : "property";
        var message = $"Duplicate extension {memberKind} '{duplicateSymbol.Name}' for receiver type '{receiverType.DisplayName}'. " +
                      $"Another extension block for the same receiver type already declares a member with this signature.";

        var declaringNode = symbolTable.GetDeclaringNode(duplicateSymbol);
        if(declaringNode is not null)
        {
            var sourceText = containingBlock.DeclaringNode is not null
                ? GetSourceTextFromOrigin(containingBlock.DeclaringNode)
                : null;
            diagnostics.Add(MakeDiagnosticWithLocation(
                ExtensionDuplicateMember.Value,
                DiagnosticSeverity.Error,
                message,
                declaringNode,
                sourceText));
        }
        else
        {
            diagnostics.Add(new Diagnostic(
                ExtensionDuplicateMember,
                DiagnosticSeverity.Error,
                PipelineStage.SemanticModelConstruction,
                message,
                Location: default,
                CompilationUnitPath: "<unknown>",
                AnalyzerName: null));
        }
    }

    /// <summary>
    /// Checks whether a property declaration has a set or init accessor.
    /// </summary>
    private static bool HasSetOrInitAccessor(PropertyDeclarationNode propertyDecl)
    {
        switch(propertyDecl)
        {
            case BlockPropertyPropertyDeclarationNode blockProp:
                foreach(var accessor in blockProp.Accessors)
                {
                    if(accessor is AutoSetAccessorAccessorDeclarationNode
                        or BlockSetAccessorAccessorDeclarationNode
                        or ExpressionSetAccessorAccessorDeclarationNode
                        or AutoInitAccessorAccessorDeclarationNode
                        or BlockInitAccessorAccessorDeclarationNode
                        or ExpressionInitAccessorAccessorDeclarationNode)
                    {
                        return true;
                    }
                }

                return false;
            case ExpressionBodiedPropertyPropertyDeclarationNode:
                // Expression-bodied properties are always get-only.
                return false;
            default:
                return false;
        }
    }

    private static void RegisterAbstractMethodDeclaration(
        MethodDeclarationNode methodDecl,
        Scope typeScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var methodName = methodDecl.Name.Lexeme;
        var methodSpan = ToMistSourceSpan(methodDecl.Name.Span);
        var methodSymbol = new Symbol(methodName, SymbolKind.Method, SymbolOrigin.UserCode, typeScope, declaredType: null, methodSpan);
        typeScope.AddMember(methodSymbol);
        symbolTable.Register(methodSymbol, methodDecl);

        // Register method type parameters if present.
        RegisterMethodTypeParameters(methodDecl.TypeParams, methodSymbol, typeScope, sourceText, diagnostics);
    }

    /// <summary>
    /// Registers an abstract type property declaration as a <see cref="SymbolKind.Property"/> symbol
    /// on the abstract type type scope.
    /// </summary>
    private static void RegisterAbstractPropertyDeclaration(
        PropertyDeclarationNode propertyDecl,
        Scope typeScope,
        SymbolTable symbolTable)
    {
        var (propName, propSpan) = propertyDecl switch
        {
            BlockPropertyPropertyDeclarationNode bp => (bp.Name.Lexeme, ToMistSourceSpan(bp.Name.Span)),
            ExpressionBodiedPropertyPropertyDeclarationNode ep => (ep.Name.Lexeme, ToMistSourceSpan(ep.Name.Span)),
            _ => ("?", (SourceSpan?)null),
        };

        var hasGet = false;
        var hasSet = false;
        AccessorInfo? getAccessor = null;
        AccessorInfo? setAccessor = null;

        if(propertyDecl is BlockPropertyPropertyDeclarationNode blockProp)
        {
            foreach(var accessor in blockProp.Accessors)
            {
                switch(accessor)
                {
                    case AutoGetAccessorAccessorDeclarationNode:
                        hasGet = true;
                        getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Auto, Modifier = null };
                        break;
                    case AutoSetAccessorAccessorDeclarationNode:
                        hasSet = true;
                        setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Auto, Modifier = null };
                        break;
                }
            }
        }

        var propertyInfo = new PropertyInfo
        {
            HasGet = hasGet,
            HasSet = hasSet,
            HasInit = false,
            IsComputed = false,
            IsStatic = false,
            IsExpressionBodied = false,
            GetAccessor = getAccessor,
            SetAccessor = setAccessor,
            InitAccessor = null,
            BackingField = null,
        };

        var propSymbol = new Symbol(propName, SymbolKind.Property, SymbolOrigin.UserCode, typeScope, declaredType: null, propSpan)
        {
            PropertyMetadata = propertyInfo
        };
        typeScope.AddMember(propSymbol);
        symbolTable.Register(propSymbol, propertyDecl);
    }

    /// <summary>
    /// Checks for duplicate associated type slot names in an abstract type's members.
    /// Emits <c>MIST_AT_0001</c> pointing to the second (duplicate) declaration.
    /// </summary>
    private static void DetectDuplicateAssociatedTypeSlots(
        ImmutableArray<MemberDeclarationNode> members,
        string typeName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var seenSlotNames = new HashSet<string>();

        foreach(var member in members)
        {
            string? slotName;
            Storm.Runtime.SyntaxNode declarationNode;

            switch(member)
            {
                case AssociatedTypeMemberMemberDeclarationNode assoc:
                    slotName = assoc.AssociatedType.Name.Lexeme;
                    declarationNode = assoc.AssociatedType;
                    break;
                default:
                    continue;
            }

            if(!seenSlotNames.Add(slotName))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    CommonDiagnostics.DuplicateAssociatedTypeSlot.Id.Value,
                    DiagnosticSeverity.Error,
                    $"Abstract type '{typeName}' declares duplicate associated type slot '{slotName}'",
                    declarationNode,
                    sourceText));
            }
        }
    }


    /// <summary>
    /// Emits <c>MIST_AT_0005</c> when modifiers precede an associated type slot declaration.
    /// The diagnostic points to the first modifier token.
    /// </summary>
    private static void EmitModifiersOnAssociatedTypeSlotDiagnostic(
        AssociatedTypeSlotDeclarationNode slotDecl,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(slotDecl.Modifiers.IsDefaultOrEmpty)
        {
            return;
        }

        var firstModifier = slotDecl.Modifiers[0];
        diagnostics.Add(MakeDiagnosticWithLocation(
            CommonDiagnostics.ModifiersOnAssociatedTypeSlot.Id.Value,
            DiagnosticSeverity.Error,
            "Modifiers are not permitted on associated type slot declarations",
            firstModifier,
            sourceText));
    }

    /// <summary>
    /// Emits <c>MIST_AT_0006</c> when an abstract type slot declaration appears in a class or struct body.
    /// The diagnostic points to the <c>type</c> keyword token.
    /// </summary>
    private static void EmitAssociatedTypeSlotInWrongContextDiagnostic(
        Storm.Runtime.Token typeKeywordToken,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        diagnostics.Add(MakeDiagnosticWithTokenLocation(
            CommonDiagnostics.AssociatedTypeSlotInWrongContext.Id.Value,
            DiagnosticSeverity.Error,
            "Abstract type slots are only permitted in abstract types",
            typeKeywordToken,
            sourceText));
    }

    /// <summary>
    /// Registers an associated type slot declaration (constrained or unconstrained) as a symbol
    /// in the declaring abstract type's member scope. Creates an <see cref="AssociatedTypeSlotType"/>
    /// with empty constraints (resolved later in <see cref="Pass1_ResolveConstraints"/>)
    /// and registers any type parameters declared on the slot.
    /// </summary>
    private static void RegisterAssociatedTypeSlotDeclaration(
        AssociatedTypeSlotDeclarationNode slotDecl,
        IType declaringType,
        Scope typeScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Emit diagnostic if modifiers are present (not yet supported in old system).
        if(!slotDecl.Modifiers.IsDefaultOrEmpty)
        {
            EmitModifiersOnAssociatedTypeSlotDiagnostic(slotDecl, sourceText, diagnostics);
        }

        var slotName = slotDecl.Name.Lexeme;
        var slotSpan = ToMistSourceSpan(slotDecl.Name.Span);

        // Extract type parameters on the slot itself (e.g., type Iterator<TState> : ...).
        var typeParams = ExtractTypeParameters(slotDecl.TypeParams, slotName, sourceText, diagnostics);

        // Create the slot's own member scope for its type parameters.
        var slotScope = new Scope(parent: typeScope);

        // Register each type parameter as a symbol in the slot's scope.
        if(typeParams.Count > 0 && slotDecl.TypeParams is not null)
        {
            foreach(var tp in typeParams)
            {
                var (tpName, tpOrdinal) = GetTypeParameterNameAndOrdinal(tp);
                var tpSpan = GetTypeParameterSpan(slotDecl.TypeParams, tpOrdinal);
                var tpSymbol = new Symbol(tpName, SymbolKind.Class, SymbolOrigin.UserCode, slotScope, tp, tpSpan);
                slotScope.AddMember(tpSymbol);
            }
        }

        // Create the AssociatedTypeSlotType with empty constraints initially.
        // Constraints will be resolved during Pass1_ResolveConstraints.
        var slotType = new AssociatedTypeSlotType(
            displayName: slotName,
            memberScope: slotScope,
            containingNamespace: declaringType switch
            {
                AbstractType it => it.ContainingNamespace,
                _ => null
            },
            declaringType: declaringType,
            constraints: new TypeParameterConstraints(),
            typeParameters: typeParams);

        // Register the slot as a symbol in the declaring type's member scope.
        var slotSymbol = new Symbol(slotName, SymbolKind.TypeAlias, SymbolOrigin.UserCode, typeScope, slotType, slotSpan)
        {
            TypeParameters = typeParams
        };
        typeScope.AddMember(slotSymbol);
        symbolTable.Register(slotSymbol, slotDecl);
    }

    private static void RegisterMemberDeclaration(
        MemberDeclarationNode memberDecl,
        Scope typeScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(memberDecl)
        {
            case FieldMemberMemberDeclarationNode fieldMember:
                RegisterFieldDeclaration(fieldMember.Field, typeScope, symbolTable);
                break;
            case ConstructorMemberMemberDeclarationNode ctorMember:
                RegisterConstructorDeclaration(ctorMember.Constructor, typeScope, symbolTable);
                break;
            case MethodMemberMemberDeclarationNode methodMember:
                _ = RegisterMethodDeclaration(methodMember.Method, typeScope, symbolTable, sourceText, diagnostics);
                break;
            case OperatorMemberMemberDeclarationNode operatorMember:
                RegisterOperatorDeclaration(operatorMember.Operator, typeScope, symbolTable);
                break;
            case PropertyMemberMemberDeclarationNode propertyMember:
                RegisterPropertyDeclaration(propertyMember.Property, typeScope, symbolTable);
                break;
            case IndexerMemberMemberDeclarationNode indexerMember:
                RegisterIndexerDeclaration(indexerMember.Indexer, typeScope, symbolTable);
                break;
            case CastOperatorMemberMemberDeclarationNode castOpMember:
                RegisterCastOperatorDeclaration(castOpMember.CastOperator, typeScope, symbolTable, sourceText);
                break;
            case DefaultBlockMemberMemberDeclarationNode defaultBlockMember:
                RegisterDefaultBlockDeclaration(defaultBlockMember, typeScope, symbolTable, sourceText, diagnostics);
                break;
            case NestedBodyTypeMemberMemberDeclarationNode nestedBodyMember:
                RegisterTypeDeclaration(
                    new BodyTypeTypeDeclarationNode { TypeBody = nestedBodyMember.NestedBody },
                    typeScope,
                    symbolTable,
                    namespaceName: null,
                    sourceText,
                    diagnostics);
                break;
            case NestedEnumMemberMemberDeclarationNode nestedEnumMember:
                RegisterTypeDeclaration(
                    new EnumTypeTypeDeclarationNode { EnumDeclaration = nestedEnumMember.NestedEnum },
                    typeScope,
                    symbolTable,
                    namespaceName: null,
                    sourceText,
                    diagnostics);
                break;
            case NestedNewtypeMemberMemberDeclarationNode nestedNewtypeMember:
                RegisterTypeDeclaration(
                    new NewtypeTypeTypeDeclarationNode { NewtypeDeclaration = nestedNewtypeMember.NestedNewtype },
                    typeScope,
                    symbolTable,
                    namespaceName: null,
                    sourceText,
                    diagnostics);
                break;
            case AssociatedTypeMemberMemberDeclarationNode associatedTypeMember:
                EmitAssociatedTypeSlotInWrongContextDiagnostic(associatedTypeMember.AssociatedType.TYPE, sourceText, diagnostics);
                break;
            case NestedTypeAliasMemberMemberDeclarationNode memberTypeAlias:
                RegisterMemberTypeAliasDeclaration(memberTypeAlias.NestedTypeAlias, typeScope, symbolTable, sourceText, diagnostics);
                break;
        }
    }

    private static void RegisterDefaultBlockDeclaration(
        DefaultBlockMemberMemberDeclarationNode defaultBlockMember,
        Scope typeScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Find the containing ClassType or StructType whose MemberScope matches typeScope.
        IType? containingType = null;
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is not (SymbolKind.Class or SymbolKind.Struct))
            {
                continue;
            }

            var memberScope = symbol.DeclaredType switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                _ => null,
            };

            if(memberScope is not null && ReferenceEquals(memberScope, typeScope))
            {
                containingType = symbol.DeclaredType;
                break;
            }
        }

        if(containingType is null)
        {
            return;
        }

        var defaultBlockNode = defaultBlockMember.DefaultBlock;

        switch(containingType)
        {
            case ClassType classType:
                if(classType.DefaultBlockNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        CommonDiagnostics.DefaultDuplicateBlock.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Type '{classType.DisplayName}' declares more than one default block; only one is permitted per type.",
                        defaultBlockNode,
                        sourceText));
                    return;
                }

                classType.DefaultBlockNode = defaultBlockNode;
                classType.Defaultability = DefaultabilityStatus.Explicit;
                break;

            case StructType structType:
                if(structType.DefaultBlockNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        CommonDiagnostics.DefaultDuplicateBlock.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Type '{structType.DisplayName}' declares more than one default block; only one is permitted per type.",
                        defaultBlockNode,
                        sourceText));
                    return;
                }

                structType.DefaultBlockNode = defaultBlockNode;
                structType.Defaultability = DefaultabilityStatus.Explicit;
                break;
        }
    }

    private static void RegisterFieldDeclaration(FieldDeclarationNode fieldDecl, Scope typeScope, SymbolTable symbolTable)
    {
        var fieldName = fieldDecl.Name.Lexeme;
        var fieldSpan = ToMistSourceSpan(fieldDecl.Name.Span);
        var fieldSymbol = new Symbol(fieldName, SymbolKind.Field, SymbolOrigin.UserCode, typeScope, declaredType: null, fieldSpan);

        if(HasReadonlyModifier(fieldDecl.Modifiers))
        {
            fieldSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        if(fieldDecl.OwnershipSpecifier is not null)
        {
            // When the parser sees "readonly ref" on a field, it may parse it as
            // modifier=READONLY + ownershipSpecifier=RefSpecifier (due to greedy matching).
            // In that case, the combined meaning is ReadonlyRef.
            fieldSymbol.OwnershipTier = HasReadonlyModifier(fieldDecl.Modifiers) && fieldDecl.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode
                ? OwnershipTier.ReadonlyRef
                : MapOwnershipSpecifier(fieldDecl.OwnershipSpecifier);

            // Mark as owned field when the specifier is 'owned' (Req 1.1, 1.2).
            if(fieldDecl.OwnershipSpecifier is OwnedSpecifierOwnershipSpecifierNode)
            {
                fieldSymbol.IsOwnedField = true;
            }
        }
        else if(HasRefModifier(fieldDecl.Modifiers))
        {
            // The parser consumed 'ref' as a RefModifier (since REF is in the Modifier rule).
            // On a field declaration, 'ref' means ref-field ownership, not ref-struct modifier.
            // "readonly ref" → ReadonlyRef; bare "ref" → Borrowed (same as RefSpecifier).
            fieldSymbol.OwnershipTier = HasReadonlyModifier(fieldDecl.Modifiers)
                ? OwnershipTier.ReadonlyRef
                : OwnershipTier.Borrowed;
        }
        else if(fieldDecl.Modifiers.Any(m => m is OwnedModifierModifierNode))
        {
            fieldSymbol.OwnershipTier = OwnershipTier.Owned;
            fieldSymbol.IsOwnedField = true;
        }

        typeScope.AddMember(fieldSymbol);
        symbolTable.Register(fieldSymbol, fieldDecl);
    }

    private static void RegisterConstructorDeclaration(ConstructorDeclarationNode ctorDecl, Scope typeScope, SymbolTable symbolTable)
    {
        var ctorName = ctorDecl.Name.Lexeme;
        var ctorSpan = ToMistSourceSpan(ctorDecl.Name.Span);
        var isIntrinsic = HasIntrinsicModifier(ctorDecl.Modifiers);
        var hasBody = ctorDecl.Body is not CallableNoBodyCallableBodyNode;
        var ctorSymbol = new Symbol(
            ctorName, SymbolKind.Constructor, SymbolOrigin.UserCode, typeScope,
            declaredType: null, ctorSpan,
            isIntrinsic: isIntrinsic, hasBody: hasBody);

        if(HasReadonlyModifier(ctorDecl.Modifiers))
        {
            ctorSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        typeScope.AddMember(ctorSymbol);
        symbolTable.Register(ctorSymbol, ctorDecl);
    }

    private static Symbol RegisterMethodDeclaration(MethodDeclarationNode methodDecl, Scope typeScope, SymbolTable symbolTable, SourceText? sourceText, DiagnosticBag diagnostics)
    {
        var methodName = methodDecl.Name.Lexeme;
        var methodSpan = ToMistSourceSpan(methodDecl.Name.Span);
        var isIntrinsic = HasIntrinsicModifier(methodDecl.Modifiers);
        var hasBody = methodDecl.Body is not CallableNoBodyCallableBodyNode;
        var methodSymbol = new Symbol(
            methodName, SymbolKind.Method, SymbolOrigin.UserCode, typeScope,
            declaredType: null, methodSpan,
            isIntrinsic: isIntrinsic, hasBody: hasBody);

        if(HasReadonlyModifier(methodDecl.Modifiers))
        {
            methodSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        typeScope.AddMember(methodSymbol);
        symbolTable.Register(methodSymbol, methodDecl);

        // Register method type parameters if present.
        RegisterMethodTypeParameters(methodDecl.TypeParams, methodSymbol, typeScope, sourceText, diagnostics);

        return methodSymbol;
    }

    /// <summary>
    /// Registers an operator declaration as a static method symbol on the
    /// containing type's scope. The operator's name is mangled as
    /// <c>operator&lt;symbol&gt;</c> (e.g., <c>operator+</c>) so that overload
    /// resolution in Task 14 can look it up by constructing the same key from
    /// an operator expression.
    ///
    /// Pass 1 establishes only the symbol's identity (name, kind, modifiers,
    /// body-presence). Parameter signature extraction and the operator's
    /// return type are wired up in Pass 2's <see cref="ResolveOperatorDeclaration"/>,
    /// which mirrors <see cref="ResolveMethodDeclaration"/> — operators are
    /// treated as static methods for semantic-model purposes (Requirement 4.6),
    /// and <see cref="ParameterSignature.Extract"/> reads the parameter list
    /// from the <see cref="OperatorDeclarationNode"/> just like for methods.
    /// </summary>
    private static void RegisterOperatorDeclaration(OperatorDeclarationNode opDecl, Scope typeScope, SymbolTable symbolTable)
    {
        var opLexeme = GetOperatorSymbolLexeme(opDecl.Symbol);
        var opName = "operator" + opLexeme;
        var opSpan = ToMistSourceSpan(opDecl.Symbol.Span);
        var isIntrinsic = HasIntrinsicModifier(opDecl.Modifiers);
        var hasBody = opDecl.Body is not CallableNoBodyCallableBodyNode;
        var opSymbol = new Symbol(
            opName, SymbolKind.Method, SymbolOrigin.UserCode, typeScope,
            declaredType: null, opSpan,
            isIntrinsic: isIntrinsic, hasBody: hasBody);
        typeScope.AddMember(opSymbol);
        symbolTable.Register(opSymbol, opDecl);
    }

    /// <summary>
    /// Registers a cast operator declaration as a static method symbol on the
    /// containing type's scope. The operator's name is encoded as
    /// <c>operator_{kind}_{targetType}</c> (e.g., <c>operator_implicit_Weight</c>,
    /// <c>operator_explicit_string</c>) so that the type checker can look it up
    /// by constructing the same key from a cast expression or implicit conversion
    /// site.
    ///
    /// Pass 1 establishes only the symbol's identity (name, kind, modifiers,
    /// body-presence). The target type and parameter are resolved in Pass 2's
    /// <see cref="ResolveCastOperatorDeclaration"/>.
    /// </summary>
    private static void RegisterCastOperatorDeclaration(
        CastOperatorDeclarationNode castOpDecl, Scope typeScope, SymbolTable symbolTable, SourceText? sourceText = null)
    {
        // Extract the cast kind prefix.
        var kindPrefix = castOpDecl.CastKind switch
        {
            ImplicitCastCastOperatorKindNode => "implicit",
            ExplicitCastCastOperatorKindNode => "explicit",
            _ => "unknown",
        };

        // Extract the target type name from the type reference for the encoded name.
        // The full type resolution happens in Pass 2; here we use the raw lexeme.
        var targetTypeName = ExtractTypeReferenceName(castOpDecl.TargetType, sourceText);
        var opName = $"operator_{kindPrefix}_{targetTypeName}";

        var opSpan = ToMistSourceSpan(castOpDecl.CastKind.Span);
        var isIntrinsic = HasIntrinsicModifier(castOpDecl.Modifiers);
        var hasBody = castOpDecl.Body is not CallableNoBodyCallableBodyNode;

        var opSymbol = new Symbol(
            opName, SymbolKind.Method, SymbolOrigin.UserCode, typeScope,
            declaredType: null, opSpan,
            isIntrinsic: isIntrinsic, hasBody: hasBody);
        typeScope.AddMember(opSymbol);
        symbolTable.Register(opSymbol, castOpDecl);
    }

    /// <summary>
    /// Extracts the raw type name from a <see cref="TypeReferenceNode"/> for use
    /// in encoded symbol names (e.g., cast operator names). For named types, this
    /// returns the IDENTIFIER lexeme; for primitive types, the keyword string
    /// (e.g., <c>"int"</c>, <c>"string"</c>). Array ranks are not included.
    /// <para>
    /// The generated parser may not populate <c>IDENTIFIER.Lexeme</c> on
    /// <see cref="QualifiedIdentifierNode"/>. When the lexeme is empty, this
    /// method falls back to extracting the name from the node's source span
    /// via the <paramref name="sourceText"/> parameter (if available).
    /// </para>
    /// </summary>
    private static string ExtractTypeReferenceName(TypeReferenceNode typeRef, SourceText? sourceText = null)
    {
        switch(typeRef.First)
        {
            case NamedSingleTypeRefSingleTypeRefNode namedRef:
                var lexeme = namedRef.Name.IDENTIFIER.Lexeme;
                if(!string.IsNullOrEmpty(lexeme))
                {
                    return lexeme;
                }
                // Fallback: extract from the QualifiedIdentifier's source span.
                if(sourceText is not null)
                {
                    var span = namedRef.Name.Span;
                    if(span.Length > 0 && span.Start + span.Length <= sourceText.Contents.Length)
                    {
                        return sourceText.Contents.Substring(span.Start, span.Length);
                    }
                }
                // Last resort: extract from the TypeReference's own span (covers
                // cases where the QualifiedIdentifier span is zero but the
                // TypeReference span is valid).
                {
                    var span = namedRef.Span;
                    if(sourceText is not null && span.Length > 0 && span.Start + span.Length <= sourceText.Contents.Length)
                    {
                        var raw = sourceText.Contents.Substring(span.Start, span.Length);
                        // Strip array rank suffix if present.
                        var bracketIdx = raw.IndexOf('[');
                        return bracketIdx >= 0 ? raw[..bracketIdx].Trim() : raw.Trim();
                    }
                }

                return "";
            case PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef:
                return FormatPrimitiveType(primitiveRef.PrimitiveType);
            case VoidSingleTypeRefSingleTypeRefNode:
                return "void";
            case TupleSingleTypeRefSingleTypeRefNode tupleRef:
                return FormatTupleTypeReference(tupleRef);
            default:
                return "unknown";
        }
    }

    /// <summary>
    /// Returns <c>true</c> if the modifier list contains an
    /// <see cref="IntrinsicModifierModifierNode"/>. Used at type level to set
    /// <c>IsBackendBacked</c> on <see cref="ClassType"/>/<see cref="StructType"/>
    /// and at member level to set <c>IsIntrinsic</c> on <see cref="Symbol"/>.
    /// </summary>
    private static bool HasIntrinsicModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is IntrinsicModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasReadonlyModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is ReadonlyModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasOwnedModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is OwnedModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasRefModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is RefModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasAffineModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is AffineModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasLinearModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is LinearModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    private static bool HasRelevantModifier(ImmutableArray<ModifierNode> modifiers)
    {
        foreach(var modifier in modifiers)
        {
            if(modifier is RelevantModifierModifierNode)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Resolves the <see cref="SubstructuralDiscipline"/> declared on a type from its
    /// modifier list, following the resolution table in the drop-semantics design:
    /// <list type="bullet">
    ///   <item><c>[affine]</c> → <see cref="SubstructuralDiscipline.Affine"/> (implies owned)</item>
    ///   <item><c>[linear]</c> → <see cref="SubstructuralDiscipline.Linear"/> (implies owned)</item>
    ///   <item><c>[relevant]</c> → <see cref="SubstructuralDiscipline.Relevant"/> (aliasable)</item>
    ///   <item><c>[owned]</c> or <c>[]</c> → <see cref="SubstructuralDiscipline.None"/></item>
    /// </list>
    /// Conflicting combinations (more than one substructural modifier, or a substructural
    /// modifier combined with <c>owned</c>) resolve to <see cref="SubstructuralDiscipline.None"/>.
    /// The conflicting-modifier diagnostic itself is reported by <c>DropAnalyzer</c>, not here.
    /// </summary>
    private static SubstructuralDiscipline ResolveDiscipline(ImmutableArray<ModifierNode> modifiers)
    {
        var hasAffine = HasAffineModifier(modifiers);
        var hasLinear = HasLinearModifier(modifiers);
        var hasRelevant = HasRelevantModifier(modifiers);
        var hasOwned = HasOwnedModifier(modifiers);

        var substructuralCount = (hasAffine ? 1 : 0) + (hasLinear ? 1 : 0) + (hasRelevant ? 1 : 0);

        // No substructural modifier — discipline is None (owned/unrestricted governed elsewhere).
        if(substructuralCount == 0)
        {
            return SubstructuralDiscipline.None;
        }

        // More than one substructural modifier is a conflict — resolve to None.
        if(substructuralCount > 1)
        {
            return SubstructuralDiscipline.None;
        }

        // affine/linear imply owned; combining with explicit owned is redundant (conflict).
        // relevant must be aliasable; combining with owned is contradictory (conflict).
        if(hasOwned)
        {
            return SubstructuralDiscipline.None;
        }

        if(hasAffine)
        {
            return SubstructuralDiscipline.Affine;
        }

        if(hasLinear)
        {
            return SubstructuralDiscipline.Linear;
        }

        return SubstructuralDiscipline.Relevant;
    }

    /// <summary>
    /// Recognizes <c>Drop()</c> methods on class and struct types. A method named
    /// <c>Drop</c> that accepts zero parameters is the type's drop method. When such a
    /// method is found, the declaring type's <c>HasDrop</c> is set to <c>true</c> and its
    /// <c>DropReturnType</c> is set to the method's return type (null when the return type
    /// is <c>void</c>).
    /// <para>
    /// Runs after Pass 2 so method return types are resolved. The void aliases
    /// <c>Task</c>/<c>ValueTask</c> inherit drop state from their generic forms because the
    /// state lives on the shared generic <see cref="ClassType"/>/<see cref="StructType"/>
    /// definition.
    /// </para>
    /// </summary>
    private static void RecognizeDropMethods(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is not (SymbolKind.Class or SymbolKind.Struct))
            {
                continue;
            }

            var type = symbol.DeclaredType;
            var memberScope = type switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                _ => null,
            };

            if(memberScope is null)
            {
                continue;
            }

            foreach(var member in memberScope.Members)
            {
                if(member.Kind != SymbolKind.Method || member.Name != "Drop")
                {
                    continue;
                }

                // Drop() must accept zero parameters to be recognized as the type's
                // drop method. Parameter count is taken from the declaring AST node
                // (Mist-declared methods store parameters in the AST, not on the symbol).
                var declaringNode = symbolTable.GetDeclaringNode(member);
                if(declaringNode is not MethodDeclarationNode methodDecl)
                {
                    continue;
                }

                var parameterCount = ExtractParameterTypes(methodDecl.Parameters).Count;
                if(parameterCount != 0)
                {
                    continue;
                }

                // Determine the Drop() return type. The developer-written return type is
                // recorded on DeclaredReturnType; null DropReturnType means void.
                var dropReturnType = (member as Symbol)?.DeclaredReturnType
                    ?? (member as Symbol)?.DeclaredType
                    ?? member.DeclaredType;

                var isVoid = dropReturnType is null || dropReturnType.IsVoid();

                switch(type)
                {
                    case ClassType ct:
                        ct.HasDrop = true;
                        ct.DropReturnType = isVoid ? null : dropReturnType;
                        break;
                    case StructType st:
                        st.HasDrop = true;
                        st.DropReturnType = isVoid ? null : dropReturnType;
                        break;
                }

                // Only the first zero-parameter Drop() defines the drop method.
                break;
            }
        }
    }

    /// <summary>
    /// Propagates <see cref="Symbol.IsOwnedField"/> for all instance fields of owned types.
    /// When a type is declared <c>owned</c>, all its instance fields are implicitly owned
    /// (Req 3 AC 1), regardless of whether they carry an explicit <c>owned</c> annotation.
    /// </summary>
    private static void PropagateOwnedFieldsForOwnedTypes(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is not (SymbolKind.Class or SymbolKind.Struct))
            {
                continue;
            }

            var type = symbol.DeclaredType;
            var isOwnedType = type switch
            {
                ClassType ct => ct.IsOwnedType,
                StructType st => st.IsOwnedType,
                _ => false,
            };

            if(!isOwnedType)
            {
                continue;
            }

            var memberScope = type switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                _ => null,
            };

            if(memberScope is null)
            {
                continue;
            }

            foreach(var member in memberScope.Members)
            {
                if(member.Kind != SymbolKind.Field)
                {
                    continue;
                }

                if(member is not Symbol fieldSym)
                {
                    continue;
                }

                // Skip static fields — check via the declaring AST node since
                // Symbol.IsStatic is not set during field registration.
                var declaringNode = symbolTable.GetDeclaringNode(member);
                if(declaringNode is FieldDeclarationNode fieldDecl
                    && fieldDecl.Modifiers.Any(m => m is StaticModifierModifierNode))
                {
                    continue;
                }

                // Mark all instance fields of owned types as owned (Req 3 AC 1).
                fieldSym.IsOwnedField = true;
            }
        }
    }

    /// <summary>
    /// Maps an <see cref="OwnershipSpecifierNode"/> AST node to the corresponding
    /// <see cref="OwnershipTier"/> enum value. Returns <see cref="OwnershipTier.Unrestricted"/>
    /// when no specifier is present (null).
    /// </summary>
    private static OwnershipTier MapOwnershipSpecifier(OwnershipSpecifierNode? specifier)
    {
        return specifier switch
        {
            OwnedSpecifierOwnershipSpecifierNode => OwnershipTier.Owned,
            FrozenSpecifierOwnershipSpecifierNode => OwnershipTier.Frozen,
            ReadonlyRefSpecifierOwnershipSpecifierNode => OwnershipTier.ReadonlyRef,
            BorrowedSpecifierOwnershipSpecifierNode => OwnershipTier.Borrowed,
            RefSpecifierOwnershipSpecifierNode => OwnershipTier.Borrowed,
            _ => OwnershipTier.Unrestricted,
        };
    }

    /// <summary>
    /// Sets all member symbols in the given type scope to <see cref="ReadonlyStatus.ImplicitReadonly"/>,
    /// unless they are already explicitly marked readonly. Called when a type is declared as readonly.
    /// </summary>
    private static void SetMembersImplicitReadonly(Scope typeScope)
    {
        foreach(var member in typeScope.Members)
        {
            if(member is Symbol symbol &&
                symbol.Kind is SymbolKind.Field or SymbolKind.Property or SymbolKind.Indexer or SymbolKind.Method or SymbolKind.Constructor)
            {
                if(symbol.ReadonlyStatus == ReadonlyStatus.Unknown)
                {
                    symbol.ReadonlyStatus = ReadonlyStatus.ImplicitReadonly;
                }

                // Also update PropertyInfo.ReadonlyStatus for properties and indexers.
                if(symbol.PropertyMetadata is { ReadonlyStatus: ReadonlyStatus.Unknown } propInfo)
                {
                    symbol.PropertyMetadata = new PropertyInfo
                    {
                        HasGet = propInfo.HasGet,
                        HasSet = propInfo.HasSet,
                        HasInit = propInfo.HasInit,
                        IsComputed = propInfo.IsComputed,
                        IsStatic = propInfo.IsStatic,
                        IsExpressionBodied = propInfo.IsExpressionBodied,
                        GetAccessor = propInfo.GetAccessor,
                        SetAccessor = propInfo.SetAccessor,
                        InitAccessor = propInfo.InitAccessor,
                        BackingField = propInfo.BackingField,
                        ReadonlyStatus = ReadonlyStatus.ImplicitReadonly,
                    };
                }
            }
        }
    }

    /// <summary>
    /// Extracts the textual lexeme of an operator symbol node
    /// (e.g., <c>"+"</c> for <see cref="PlusOpOperatorSymbolNode"/>). The
    /// lexeme becomes the suffix of the operator's symbol name
    /// (<c>"operator+"</c>) so the type checker can construct the same key
    /// from an operator expression.
    /// </summary>
    private static string GetOperatorSymbolLexeme(OperatorSymbolNode symbol)
    {
        return symbol switch
        {
            PlusOpOperatorSymbolNode => "+",
            MinusOpOperatorSymbolNode => "-",
            StarOpOperatorSymbolNode => "*",
            SlashOpOperatorSymbolNode => "/",
            ModuloOpOperatorSymbolNode => "%",
            EqualEqualOpOperatorSymbolNode => "==",
            NotEqualOpOperatorSymbolNode => "!=",
            LessThanOpOperatorSymbolNode => "<",
            GreaterThanOpOperatorSymbolNode => ">",
            LessThanOrEqualOpOperatorSymbolNode => "<=",
            GreaterThanOrEqualOpOperatorSymbolNode => ">=",
            LogicalAndOpOperatorSymbolNode => "&&",
            LogicalOrOpOperatorSymbolNode => "||",
            ExclamationOpOperatorSymbolNode => "!",
            _ => "",
        };
    }

    /// <summary>
    /// Extracts type parameter names from a <see cref="TypeParameterListNode"/> and returns
    /// them as a list of <see cref="IType"/> instances (either <see cref="TypeParameterType"/>
    /// or <see cref="DependentTypeParameterType"/>) with correct ordinals.
    /// Also checks for duplicate names and shadowing of the enclosing type name.
    /// </summary>
    private static IReadOnlyList<IType> ExtractTypeParameters(
        TypeParameterListNode? typeParamList,
        string? enclosingTypeName,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(typeParamList is null)
        {
            return Array.Empty<IType>();
        }

        var typeParams = new List<IType>();
        var seenNames = new HashSet<string>();
        var ordinal = 0;

        // Process the first type parameter.
        ProcessTypeParameter(typeParamList.TypeParameter, ordinal++, enclosingTypeName, seenNames, typeParams, sourceText, diagnostics);

        // Process the rest of the type parameters.
        foreach(var tp in typeParamList.TypeParameters)
        {
            ProcessTypeParameter(tp, ordinal++, enclosingTypeName, seenNames, typeParams, sourceText, diagnostics);
        }

        return typeParams;
    }

    /// <summary>
    /// Processes a single type parameter: checks for duplicates and shadowing,
    /// then creates either a <see cref="TypeParameterType"/> or a
    /// <see cref="DependentTypeParameterType"/> and adds it to the list.
    /// </summary>
    private static void ProcessTypeParameter(
        TypeParameterNode node,
        int ordinal,
        string? enclosingTypeName,
        HashSet<string> seenNames,
        List<IType> typeParams,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var name = node.GetName().Lexeme;

        // Check for duplicate type parameter names.
        if(!seenNames.Add(name))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                GenericsDiagnostics.DuplicateTypeParameter.Id.Value,
                DiagnosticSeverity.Error,
                $"Duplicate type parameter name '{name}'.",
                node,
                sourceText));
        }

        // Check if the type parameter shadows the enclosing type name.
        if(enclosingTypeName is not null && name == enclosingTypeName)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                GenericsDiagnostics.TypeParameterShadowsType.Id.Value,
                DiagnosticSeverity.Warning,
                $"Type parameter '{name}' shadows the enclosing type name.",
                node,
                sourceText));
        }

        // Determine whether this is a dependent type parameter or a regular one.
        if(node is DependentTypeParameterTypeParameterNode depNode)
        {
            var valueTypeKeyword = FormatPrimitiveType(depNode.ValueType);

            if(!AllowedDependentTypeAnnotations.Contains(valueTypeKeyword))
            {
                // Emit MIST_DT_0001 and use ErrorType as the value type.
                diagnostics.Add(MakeDiagnosticWithLocation(
                    DependentTypeDisallowedAnnotation.Value,
                    DiagnosticSeverity.Error,
                    $"Type '{valueTypeKeyword}' cannot be used as a dependent type parameter. Only primitive integral types, bool, and char are allowed.",
                    depNode,
                    sourceText));

                typeParams.Add(new DependentTypeParameterType(name, ordinal, ErrorType.Instance));
            }
            else
            {
                // Resolve the value type using the legacy primitive type mapping.
                // During Pass 1, stdlib types may not be fully registered yet,
                // so we use the LegacyPrimitiveTypes singletons directly.
                var valueType = ResolvePrimitiveType(depNode.ValueType);
                typeParams.Add(new DependentTypeParameterType(name, ordinal, valueType));
            }
        }
        else if(node is NamedConstraintDependentTypeParameterTypeParameterNode namedNode)
        {
            // Named constraint (e.g., Length:ZeroOrPositiveInt).
            // During Pass 1, the constraint type alias may not have its DeclaredType
            // resolved yet (type aliases are resolved in Pass 2). Store the constraint
            // name as pending and use ErrorType as a placeholder; resolution completes
            // in Pass2_ResolveNamedTypeParameterConstraints after type alias resolution.
            var constraintName = namedNode.ConstraintName.Lexeme;
            var depType = new DependentTypeParameterType(name, ordinal, ErrorType.Instance)
            {
                PendingConstraintName = constraintName
            };
            typeParams.Add(depType);
        }
        else
        {
            typeParams.Add(new TypeParameterType(name, ordinal));
        }
    }

    /// <summary>
    /// Registers type parameters for a class, struct, or abstract type declaration.
    /// Creates <see cref="TypeParameterType"/> or <see cref="DependentTypeParameterType"/>
    /// instances, stores them on the declaring type, and registers each as a symbol
    /// in the type's member scope.
    /// </summary>
    private static void RegisterTypeParameters(
        TypeParameterListNode? typeParamList,
        string typeName,
        Scope typeScope,
        IType declaringType,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var typeParams = ExtractTypeParameters(typeParamList, typeName, sourceText, diagnostics);
        if(typeParams.Count == 0)
        {
            return;
        }

        // Store type parameters on the declaring type.
        switch(declaringType)
        {
            case ClassType classType:
                classType.TypeParameters = typeParams;
                break;
            case StructType structType:
                structType.TypeParameters = typeParams;
                break;
            case AbstractType abstractType:
                abstractType.TypeParameters = typeParams;
                break;
        }

        // Register each type parameter as a symbol in the type's member scope
        // so it can be resolved as a type within the type body.
        foreach(var tp in typeParams)
        {
            var (tpName, tpOrdinal) = GetTypeParameterNameAndOrdinal(tp);
            var tpSpan = GetTypeParameterSpan(typeParamList!, tpOrdinal);
            var tpSymbol = new Symbol(tpName, SymbolKind.Class, SymbolOrigin.UserCode, typeScope, tp, tpSpan);
            typeScope.AddMember(tpSymbol);
        }
    }

    /// <summary>
    /// Registers type parameters for a method declaration (both regular and abstract type methods).
    /// Creates <see cref="TypeParameterType"/> or <see cref="DependentTypeParameterType"/>
    /// instances, stores them on the method symbol, and registers each in the method's
    /// enclosing type scope so they can be resolved.
    /// </summary>
    private static void RegisterMethodTypeParameters(
        TypeParameterListNode? typeParamList,
        Symbol methodSymbol,
        Scope typeScope,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(typeParamList is null)
        {
            return;
        }

        // For method type parameters, we don't check shadowing against the enclosing type name
        // (that's only for type-level type parameters). We only check for duplicates.
        var typeParams = ExtractTypeParameters(typeParamList, enclosingTypeName: null, sourceText, diagnostics);
        if(typeParams.Count == 0)
        {
            return;
        }

        // Store type parameters on the method symbol.
        methodSymbol.TypeParameters = typeParams;

        // Register each type parameter as a symbol in the type scope so they
        // take precedence over enclosing type parameters during resolution.
        foreach(var tp in typeParams)
        {
            var (tpName, tpOrdinal) = GetTypeParameterNameAndOrdinal(tp);
            var tpSpan = GetTypeParameterSpan(typeParamList, tpOrdinal);
            var tpSymbol = new Symbol(tpName, SymbolKind.Class, SymbolOrigin.UserCode, typeScope, tp, tpSpan);
            typeScope.AddMember(tpSymbol);
        }
    }

    /// <summary>
    /// Extracts the name and ordinal from a type parameter (either regular or dependent).
    /// </summary>
    private static (string Name, int Ordinal) GetTypeParameterNameAndOrdinal(IType typeParam)
    {
        return typeParam switch
        {
            TypeParameterType tpt => (tpt.Name, tpt.Ordinal),
            DependentTypeParameterType dpt => (dpt.Name, dpt.Ordinal),
            _ => (typeParam.DisplayName, 0),
        };
    }

    /// <summary>
    /// Gets the source span for a type parameter at the given ordinal in a <see cref="TypeParameterListNode"/>.
    /// </summary>
    private static SourceSpan? GetTypeParameterSpan(TypeParameterListNode typeParamList, int ordinal)
    {
        if(ordinal == 0)
        {
            return ToMistSourceSpan(typeParamList.TypeParameter.GetName().Span);
        }

        var index = ordinal - 1;
        if(index < typeParamList.TypeParameters.Length)
        {
            return ToMistSourceSpan(typeParamList.TypeParameters[index].GetName().Span);
        }

        return null;
    }

    /// <summary>
    /// Generates implicit public static get-only property symbols for each
    /// <see cref="DependentTypeParameterType"/> on a type. Called during Pass 2
    /// (member resolution) after the type symbol is retrieved.
    /// <para>
    /// For each dependent parameter, this method:
    /// <list type="number">
    ///   <item>Checks for name collisions with existing members → emits <c>MIST_DT_0005</c>.</item>
    ///   <item>Checks for duplicate dependent parameter names → emits <c>MIST_DT_0006</c>.</item>
    ///   <item>Creates a public static get-only property symbol with the parameter's value type.</item>
    ///   <item>Registers the property in the type's member scope.</item>
    /// </list>
    /// </para>
    /// </summary>
    private static void GenerateDependentTypeProperties(
        IReadOnlyList<IType> typeParameters,
        Scope typeScope,
        IType declaringType,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(typeParameters.Count == 0)
        {
            return;
        }

        var seenDependentNames = new HashSet<string>(StringComparer.Ordinal);

        foreach(var tp in typeParameters)
        {
            if(tp is not DependentTypeParameterType depParam)
            {
                continue;
            }

            var paramName = depParam.Name;

            // Check for duplicate dependent parameter names.
            if(!seenDependentNames.Add(paramName))
            {
                diagnostics.Add(new Diagnostic(
                    DependentTypeMissingArguments,
                    DiagnosticSeverity.Error,
                    PipelineStage.SemanticModelConstruction,
                    $"Duplicate dependent type parameter name '{paramName}' in type '{declaringType.DisplayName}'.",
                    Location: default,
                    CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                    AnalyzerName: null));
                continue;
            }

            // Check for name collisions with existing members (fields, methods, properties).
            // When the declaring type is intrinsic (backend-backed), the explicit property
            // declaration IS the dependent parameter's value accessor (e.g., Array's
            // `intrinsic public Int32 Length` is the accessor for the `Length` dependent
            // parameter). No conflict exists and we skip generating an implicit property
            // since the intrinsic declaration serves that purpose.
            var isBackendBacked = declaringType switch
            {
                ClassType ct => ct.IsBackendBacked,
                StructType st => st.IsBackendBacked,
                _ => false,
            };
            var hasCollision = false;
            foreach(var member in typeScope.Members)
            {
                if(member.Name == paramName &&
                    member.Kind is SymbolKind.Field or SymbolKind.Method or SymbolKind.Property or SymbolKind.Indexer)
                {
                    if(isBackendBacked)
                    {
                        // Intrinsic type with same-named member — this is the intended
                        // value accessor for the dependent parameter. No diagnostic needed.
                        hasCollision = true;
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            DependentTypeParameterNameCollision,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Dependent type parameter '{paramName}' conflicts with member '{paramName}' declared in type '{declaringType.DisplayName}'. Rename either the parameter or the member.",
                            Location: default,
                            CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                            AnalyzerName: null));
                    }

                    break;
                }
            }

            // When an intrinsic declaration already provides the value accessor, skip
            // generating the implicit property to avoid duplicates in the scope.
            if(hasCollision)
            {
                continue;
            }

            // Generate the implicit property even if there's a collision
            // (the dependent parameter takes precedence per design doc).
            var propertyInfo = new PropertyInfo
            {
                HasGet = true,
                HasSet = false,
                HasInit = false,
                IsComputed = true,
                IsStatic = true,
                IsExpressionBodied = true,
            };

            var propSymbol = new Symbol(
                paramName,
                SymbolKind.Property,
                SymbolOrigin.UserCode,
                typeScope,
                declaredType: depParam.ValueType,
                declarationSpan: null)
            {
                PropertyMetadata = propertyInfo
            };
            typeScope.AddMember(propSymbol);
        }
    }

    /// <summary>
    /// Registers dependent type parameter names as compile-time constants in a
    /// method's lexical scope. Called during Pass 2 for method-level dependent
    /// parameters.
    /// </summary>
    private static void RegisterMethodDependentParameters(
        IReadOnlyList<IType> typeParameters,
        Scope methodScope)
    {
        if(typeParameters.Count == 0)
        {
            return;
        }

        foreach(var tp in typeParameters)
        {
            if(tp is not DependentTypeParameterType depParam)
            {
                continue;
            }

            // Register the dependent parameter name as a compile-time constant
            // in the method's lexical scope so it can be resolved within the method body.
            var constSymbol = new Symbol(
                depParam.Name,
                SymbolKind.Property,
                SymbolOrigin.UserCode,
                methodScope,
                declaredType: depParam.ValueType,
                declarationSpan: null)
            {
                PropertyMetadata = new PropertyInfo
                {
                    HasGet = true,
                    HasSet = false,
                    HasInit = false,
                    IsComputed = true,
                    IsStatic = true,
                    IsExpressionBodied = true,
                }
            };
            methodScope.AddMember(constSymbol);
        }
    }

    /// <summary>
    /// Registers a property declaration as a <see cref="SymbolKind.Property"/> symbol.
    /// Walks the accessor list to build <see cref="PropertyInfo"/>, classifies
    /// computed properties, and generates a backing field when needed.
    /// </summary>
    private static void RegisterPropertyDeclaration(PropertyDeclarationNode propertyDecl, Scope typeScope, SymbolTable symbolTable)
    {
        switch(propertyDecl)
        {
            case BlockPropertyPropertyDeclarationNode blockProp:
                RegisterBlockProperty(blockProp, typeScope, symbolTable);
                break;
            case ExpressionBodiedPropertyPropertyDeclarationNode exprProp:
                RegisterExpressionBodiedProperty(exprProp, typeScope, symbolTable);
                break;
        }
    }

    private static void RegisterBlockProperty(BlockPropertyPropertyDeclarationNode blockProp, Scope typeScope, SymbolTable symbolTable)
    {
        var propName = blockProp.Name.Lexeme;
        var propSpan = ToMistSourceSpan(blockProp.Name.Span);
        var isStatic = blockProp.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Walk accessor list to build PropertyInfo.
        AccessorInfo? getAccessor = null;
        AccessorInfo? setAccessor = null;
        AccessorInfo? initAccessor = null;
        var hasAutoAccessor = false;
        var usesFieldKeyword = false;

        foreach(var accessor in blockProp.Accessors)
        {
            switch(accessor)
            {
                case AutoGetAccessorAccessorDeclarationNode autoGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Auto, Modifier = autoGet.AccessorModifier };
                    hasAutoAccessor = true;
                    break;
                case BlockGetAccessorAccessorDeclarationNode blockGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Block, Modifier = blockGet.AccessorModifier };
                    if(ContainsFieldKeyword(blockGet.Body))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
                case ExpressionGetAccessorAccessorDeclarationNode exprGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Expression, Modifier = exprGet.AccessorModifier };
                    if(ContainsFieldKeywordInExpression(exprGet.Expression))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
                case AutoSetAccessorAccessorDeclarationNode autoSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Auto, Modifier = autoSet.AccessorModifier };
                    hasAutoAccessor = true;
                    break;
                case BlockSetAccessorAccessorDeclarationNode blockSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Block, Modifier = blockSet.AccessorModifier };
                    if(ContainsFieldKeyword(blockSet.Body))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
                case ExpressionSetAccessorAccessorDeclarationNode exprSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Expression, Modifier = exprSet.AccessorModifier };
                    if(ContainsFieldKeywordInExpression(exprSet.Expression))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
                case AutoInitAccessorAccessorDeclarationNode autoInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Auto, Modifier = autoInit.AccessorModifier };
                    hasAutoAccessor = true;
                    break;
                case BlockInitAccessorAccessorDeclarationNode blockInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Block, Modifier = blockInit.AccessorModifier };
                    if(ContainsFieldKeyword(blockInit.Body))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
                case ExpressionInitAccessorAccessorDeclarationNode exprInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Expression, Modifier = exprInit.AccessorModifier };
                    if(ContainsFieldKeywordInExpression(exprInit.Expression))
                    {
                        usesFieldKeyword = true;
                    }

                    break;
            }
        }

        var hasGet = getAccessor is not null;
        var hasSet = setAccessor is not null;
        var hasInit = initAccessor is not null;

        // Computed property classification:
        // IsComputed = HasGet && !HasSet && !HasInit && GetAccessor.BodyKind != Auto
        var isComputed = hasGet && !hasSet && !hasInit && getAccessor!.BodyKind != AccessorBodyKind.Auto;

        // Backing field generation:
        // NeedsBackingField = !IsComputed && (HasAutoAccessor || UsesFieldKeyword)
        Symbol? backingFieldSymbol = null;
        if(!isComputed && (hasAutoAccessor || usesFieldKeyword))
        {
            var backingFieldName = $"_{propName}_k__BackingField";
            var backingFieldSpan = propSpan; // Use property span for the backing field.
            backingFieldSymbol = new Symbol(backingFieldName, SymbolKind.Field, SymbolOrigin.UserCode, typeScope, declaredType: null, backingFieldSpan)
            {
                IsStatic = isStatic
            };
            typeScope.AddMember(backingFieldSymbol);
            symbolTable.Register(backingFieldSymbol, blockProp);
        }

        var propertyInfo = new PropertyInfo
        {
            HasGet = hasGet,
            HasSet = hasSet,
            HasInit = hasInit,
            IsComputed = isComputed,
            IsStatic = isStatic,
            IsExpressionBodied = false,
            GetAccessor = getAccessor,
            SetAccessor = setAccessor,
            InitAccessor = initAccessor,
            BackingField = backingFieldSymbol,
            ReadonlyStatus = HasReadonlyModifier(blockProp.Modifiers) ? ReadonlyStatus.ExplicitReadonly : ReadonlyStatus.Unknown,
        };

        var propSymbol = new Symbol(propName, SymbolKind.Property, SymbolOrigin.UserCode, typeScope, declaredType: null, propSpan)
        {
            PropertyMetadata = propertyInfo
        };

        if(HasReadonlyModifier(blockProp.Modifiers))
        {
            propSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        typeScope.AddMember(propSymbol);
        symbolTable.Register(propSymbol, blockProp);
    }

    private static void RegisterExpressionBodiedProperty(ExpressionBodiedPropertyPropertyDeclarationNode exprProp, Scope typeScope, SymbolTable symbolTable)
    {
        var propName = exprProp.Name.Lexeme;
        var propSpan = ToMistSourceSpan(exprProp.Name.Span);
        var isStatic = exprProp.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Expression-bodied properties are always computed (get-only with expression body).
        var getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Expression, Modifier = null };

        var propertyInfo = new PropertyInfo
        {
            HasGet = true,
            HasSet = false,
            HasInit = false,
            IsComputed = true,
            IsStatic = isStatic,
            IsExpressionBodied = true,
            GetAccessor = getAccessor,
            SetAccessor = null,
            InitAccessor = null,
            BackingField = null,
            ReadonlyStatus = HasReadonlyModifier(exprProp.Modifiers) ? ReadonlyStatus.ExplicitReadonly : ReadonlyStatus.Unknown,
        };

        var propSymbol = new Symbol(propName, SymbolKind.Property, SymbolOrigin.UserCode, typeScope, declaredType: null, propSpan)
        {
            PropertyMetadata = propertyInfo
        };

        if(HasReadonlyModifier(exprProp.Modifiers))
        {
            propSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        typeScope.AddMember(propSymbol);
        symbolTable.Register(propSymbol, exprProp);
    }

    /// <summary>
    /// Registers an indexer declaration as a <see cref="SymbolKind.Indexer"/> symbol.
    /// Stores parameter types and accessor info via <see cref="PropertyInfo"/>.
    /// </summary>
    private static void RegisterIndexerDeclaration(IndexerDeclarationNode indexerDecl, Scope typeScope, SymbolTable symbolTable)
    {
        if(indexerDecl.Body is not BlockIndexerBodyIndexerBodyNode blockBody)
        {
            // Intrinsic indexer — register with get-only accessor info.
            var intrinsicName = "this[]";
            var intrinsicSpan = ToMistSourceSpan(indexerDecl.THIS.Span);
            var intrinsicIsStatic = indexerDecl.Modifiers.Any(m => m is StaticModifierModifierNode);
            var intrinsicPropertyInfo = new PropertyInfo
            {
                HasGet = true,
                HasSet = true,
                HasInit = false,
                IsComputed = false,
                IsStatic = intrinsicIsStatic,
                IsExpressionBodied = false,
                GetAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Auto, Modifier = null },
                SetAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Auto, Modifier = null },
                InitAccessor = null,
                BackingField = null,
                ReadonlyStatus = HasReadonlyModifier(indexerDecl.Modifiers) ? ReadonlyStatus.ExplicitReadonly : ReadonlyStatus.Unknown,
            };
            var intrinsicSymbol = new Symbol(intrinsicName, SymbolKind.Indexer, SymbolOrigin.UserCode, typeScope, declaredType: null, intrinsicSpan)
            {
                PropertyMetadata = intrinsicPropertyInfo
            };
            if(HasReadonlyModifier(indexerDecl.Modifiers))
            {
                intrinsicSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
            }

            typeScope.AddMember(intrinsicSymbol);
            symbolTable.Register(intrinsicSymbol, indexerDecl);
            return;
        }

        var indexerName = "this[]";
        var indexerSpan = ToMistSourceSpan(indexerDecl.THIS.Span);
        var isStatic = indexerDecl.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Walk accessor list to build PropertyInfo (same as block property).
        AccessorInfo? getAccessor = null;
        AccessorInfo? setAccessor = null;
        AccessorInfo? initAccessor = null;

        foreach(var accessor in blockBody.Accessors)
        {
            switch(accessor)
            {
                case AutoGetAccessorAccessorDeclarationNode autoGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Auto, Modifier = autoGet.AccessorModifier };
                    break;
                case BlockGetAccessorAccessorDeclarationNode blockGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Block, Modifier = blockGet.AccessorModifier };
                    break;
                case ExpressionGetAccessorAccessorDeclarationNode exprGet:
                    getAccessor = new AccessorInfo { Kind = AccessorKind.Get, BodyKind = AccessorBodyKind.Expression, Modifier = exprGet.AccessorModifier };
                    break;
                case AutoSetAccessorAccessorDeclarationNode autoSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Auto, Modifier = autoSet.AccessorModifier };
                    break;
                case BlockSetAccessorAccessorDeclarationNode blockSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Block, Modifier = blockSet.AccessorModifier };
                    break;
                case ExpressionSetAccessorAccessorDeclarationNode exprSet:
                    setAccessor = new AccessorInfo { Kind = AccessorKind.Set, BodyKind = AccessorBodyKind.Expression, Modifier = exprSet.AccessorModifier };
                    break;
                case AutoInitAccessorAccessorDeclarationNode autoInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Auto, Modifier = autoInit.AccessorModifier };
                    break;
                case BlockInitAccessorAccessorDeclarationNode blockInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Block, Modifier = blockInit.AccessorModifier };
                    break;
                case ExpressionInitAccessorAccessorDeclarationNode exprInit:
                    initAccessor = new AccessorInfo { Kind = AccessorKind.Init, BodyKind = AccessorBodyKind.Expression, Modifier = exprInit.AccessorModifier };
                    break;
            }
        }

        var propertyInfo = new PropertyInfo
        {
            HasGet = getAccessor is not null,
            HasSet = setAccessor is not null,
            HasInit = initAccessor is not null,
            IsComputed = false,
            IsStatic = isStatic,
            IsExpressionBodied = false,
            GetAccessor = getAccessor,
            SetAccessor = setAccessor,
            InitAccessor = initAccessor,
            BackingField = null,
            ReadonlyStatus = HasReadonlyModifier(indexerDecl.Modifiers) ? ReadonlyStatus.ExplicitReadonly : ReadonlyStatus.Unknown,
        };

        var indexerSymbol = new Symbol(indexerName, SymbolKind.Indexer, SymbolOrigin.UserCode, typeScope, declaredType: null, indexerSpan)
        {
            PropertyMetadata = propertyInfo
        };

        if(HasReadonlyModifier(indexerDecl.Modifiers))
        {
            indexerSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
        }

        typeScope.AddMember(indexerSymbol);
        symbolTable.Register(indexerSymbol, indexerDecl);
    }

    /// <summary>
    /// Checks whether a block body contains a <c>field</c> keyword expression.
    /// </summary>
    private static bool ContainsFieldKeyword(BlockNode block)
    {
        foreach(var child in block.Children())
        {
            if(ContainsFieldKeywordInNode(child))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether an expression contains a <c>field</c> keyword expression.
    /// </summary>
    private static bool ContainsFieldKeywordInExpression(ExpressionNode expr)
    {
        return ContainsFieldKeywordInNode(expr);
    }

    /// <summary>
    /// Recursively checks whether a syntax node tree contains a <c>field</c> keyword expression.
    /// </summary>
    private static bool ContainsFieldKeywordInNode(Storm.Runtime.SyntaxNode node)
    {
        if(node is FieldKeywordExpressionPrimaryNode)
        {
            return true;
        }

        foreach(var child in node.Children())
        {
            if(child is not null && ContainsFieldKeywordInNode(child))
            {
                return true;
            }
        }

        return false;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1e — Validate intrinsic markers (Task 9)
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Validates the <c>intrinsic</c> markers propagated by Pass 1 onto types
    /// and members. Emits three diagnostics:
    /// <list type="bullet">
    /// <item>
    /// <description><c>MIST_SB_0030</c> — an intrinsic member has a body
    /// (Requirement 5.3). Intrinsic members must terminate with <c>;</c>
    /// because their bodies are supplied by the backend.</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0031</c> — the <c>intrinsic</c> modifier
    /// appears in a non-stdlib compilation unit (Requirements 5.6 &amp; 5.13).
    /// Fires on both type-level and member-level misuse. Until Task 26
    /// introduces <c>CompilationUnit.IsStdlib</c>, every unit is treated as
    /// non-stdlib, so any occurrence of <c>intrinsic</c> currently triggers
    /// this diagnostic.</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0032</c> — a member-level <c>intrinsic</c> sits
    /// inside a type that is not itself declared <c>intrinsic</c>
    /// (Requirement 5.15). Intrinsic members are always hosted on
    /// Backend_Backed_Types.</description>
    /// </item>
    /// </list>
    /// </summary>
    private static void Pass1e_ValidateIntrinsicMarkers(
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        SymbolTable symbolTable,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Iterate class and struct type symbols. For each, check the
        // type-level intrinsic marker (MIST_SB_0031), then walk its member
        // scope to check each member-level intrinsic marker.
        foreach(var typeSymbol in symbolTable.AllSymbols)
        {
            if(typeSymbol.Kind is not SymbolKind.Class and not SymbolKind.Struct)
            {
                continue;
            }

            var containingType = typeSymbol.DeclaredType;
            if(containingType is null)
            {
                continue;
            }

            var isBackendBacked = containingType switch
            {
                ClassType ct => ct.IsBackendBacked,
                StructType st => st.IsBackendBacked,
                _ => false,
            };

            // MIST_SB_0031 (type-level): the 'intrinsic' modifier is reserved
            // for the Standard Library. Units loaded via StdlibLoader carry
            // IsStdlib=true; user-code units do not, so this fires only on
            // user code.
            if(isBackendBacked && !IsStdlibSymbol(typeSymbol, symbolTable, asts, compilation))
            {
                var declaringNode = symbolTable.GetDeclaringNode(typeSymbol);
                if(declaringNode is not null)
                {
                    var sourceText = GetSourceTextFromOrigin(declaringNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        IntrinsicReservedForStdlib.Value,
                        DiagnosticSeverity.Error,
                        "The 'intrinsic' modifier is reserved for the Standard Library and cannot be used in user code.",
                        declaringNode,
                        sourceText));
                }
            }

            // Walk the type's members to check member-level intrinsic markers.
            var memberScope = containingType switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                _ => null,
            };
            if(memberScope is null)
            {
                continue;
            }

            foreach(var member in memberScope.Members)
            {
                if(member is not Symbol memberSymbol || !memberSymbol.IsIntrinsic)
                {
                    continue;
                }

                // Only validate members that can carry 'intrinsic': methods,
                // constructors, and operators (operators are registered as
                // SymbolKind.Method with a mangled "operator<sym>" name).
                if(memberSymbol.Kind is not SymbolKind.Method
                    and not SymbolKind.Constructor)
                {
                    continue;
                }

                var memberDeclaringNode = symbolTable.GetDeclaringNode(memberSymbol);
                var memberSourceText = memberDeclaringNode is null
                    ? null
                    : GetSourceTextFromOrigin(memberDeclaringNode);

                // MIST_SB_0030 — intrinsic member with a body.
                if(memberSymbol.HasBody && memberDeclaringNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        IntrinsicMemberHasBody.Value,
                        DiagnosticSeverity.Error,
                        $"Intrinsic member '{typeSymbol.Name}.{memberSymbol.Name}' must not have a body; use ';' to mark it as backend-provided.",
                        memberDeclaringNode,
                        memberSourceText));
                }

                // MIST_SB_0031 — member-level 'intrinsic' in user code.
                if(!IsStdlibSymbol(typeSymbol, symbolTable, asts, compilation) && memberDeclaringNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        IntrinsicReservedForStdlib.Value,
                        DiagnosticSeverity.Error,
                        "The 'intrinsic' modifier is reserved for the Standard Library and cannot be used in user code.",
                        memberDeclaringNode,
                        memberSourceText));
                }

                // MIST_SB_0032 — member-level 'intrinsic' inside a
                // non-intrinsic containing type (Requirement 5.15).
                if(!isBackendBacked && memberDeclaringNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        MemberIntrinsicRequiresTypeIntrinsic.Value,
                        DiagnosticSeverity.Error,
                        $"Member-level 'intrinsic' is only permitted inside a type that is itself declared 'intrinsic'. Type '{typeSymbol.Name}' is not intrinsic.",
                        memberDeclaringNode,
                        memberSourceText));
                }
            }
        }
    }

    /// <summary>
    /// Returns <c>true</c> if the type declared by <paramref name="typeSymbol"/>
    /// resides in a Standard Library compilation unit — i.e., the
    /// <see cref="CompilationUnit"/> whose AST contains the symbol's declaring
    /// node has <see cref="CompilationUnit.IsStdlib"/> set to <c>true</c>.
    /// Units loaded via <see cref="StdlibLoader"/> carry this flag; user-code
    /// units do not. Gates <c>MIST_SB_0031</c> (Requirements 5.6, 5.13) so the
    /// diagnostic fires only on user code.
    /// </summary>
    private static bool IsStdlibSymbol(
        ISymbol typeSymbol,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        // Locate the declaring AST node for this type symbol, then walk the
        // ASTs using reference-equality containment (the same mechanism that
        // powers FindCompilationUnitPathForSymbol) to find the matching
        // CompilationUnit and read its IsStdlib flag. Reference equality is
        // reliable across files; span-based matching is not (every file's
        // span starts at 0).
        var declaringNode = symbolTable.GetDeclaringNode(typeSymbol);
        if(declaringNode is null)
        {
            return false;
        }

        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is CompilationUnitNode cu && ContainsTypeDeclarationNode(cu, declaringNode))
            {
                return i < compilation.Units.Length && compilation.Units[i].IsStdlib;
            }
        }

        return false;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1e — Validate operator-declaration shape (Task 12)
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Binary operator symbols that require exactly 2 parameters
    /// (Requirement 4.3, 4.5). The <c>-</c> symbol is omitted here because it
    /// is overloaded binary/unary and disambiguated by parameter count below.
    /// </summary>
    private static readonly HashSet<string> BinaryOperatorSymbols = new()
    {
        "+", "*", "/", "%", "==", "!=", "<", ">", "<=", ">=", "&&", "||",
    };

    /// <summary>
    /// Unary operator symbols that require exactly 1 parameter
    /// (Requirement 4.4). The <c>-</c> symbol is omitted here because it is
    /// overloaded binary/unary.
    /// </summary>
    private static readonly HashSet<string> UnaryOperatorSymbols = new()
    {
        "!",
    };

    /// <summary>
    /// Validates the shape of every registered operator declaration and
    /// emits diagnostics for:
    /// <list type="bullet">
    /// <item>
    /// <description><c>MIST_SB_0033</c> — operator declared outside a class
    /// or struct body (Requirement 4.7). This is currently unreachable from
    /// parsed source because the grammar already restricts
    /// <c>OperatorDeclaration</c> to appear only within
    /// <c>MemberDeclaration</c>. The diagnostic ID is registered defensively
    /// so a future grammar change that admits top-level operators inherits
    /// the validation automatically.</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0034</c> — binary operator without exactly 2
    /// parameters, or unary operator without exactly 1 parameter
    /// (Requirements 4.8, 4.9). Arity rules: <c>+ * / % == != &lt; &gt; &lt;= &gt;= &amp;&amp; ||</c>
    /// are binary; <c>!</c> is unary; <c>-</c> is overloaded (2 params → binary,
    /// 1 param → unary, anything else treated as binary when count &gt; 1 or
    /// unary when count ≤ 1).</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0035</c> — operator not declared
    /// <c>public static</c> (Requirement 4.2). Both modifiers must be present
    /// in the declaration's modifier list.</description>
    /// </item>
    /// </list>
    /// </summary>
    private static void Pass1e_ValidateOperatorShape(

        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        // Walk every registered symbol whose declaring node is an
        // OperatorDeclarationNode. Operator symbols are registered with
        // SymbolKind.Method and a mangled "operator<sym>" name, so filter by
        // declaring-node shape rather than by name to avoid collisions with
        // user methods that happen to start with "operator".
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbolTable.GetDeclaringNode(symbol) is not OperatorDeclarationNode opDecl)
            {
                continue;
            }

            var sourceText = GetSourceTextFromOrigin(opDecl);
            var opLexeme = GetOperatorSymbolLexeme(opDecl.Symbol);

            // Parameter count: the ParameterList rule is
            // `Parameter (COMMA Parameter)*`, so count = 1 + Parameters.Length
            // when non-null (one for the `Parameter` head, plus each COMMA-
            // separated `Parameter` in the tail), or 0 when the list is absent.
            var paramCount = opDecl.Parameters is null
                ? 0
                : 1 + opDecl.Parameters.Parameters.Length;

            // Determine the operator's expected arity. For `-` (overloaded
            // binary/unary), disambiguate by the declared parameter count:
            // a count > 1 is diagnosed as a binary-arity mismatch (because
            // the author was likely declaring subtraction), and a count ≤ 1
            // is diagnosed as a unary-arity mismatch.
            bool isBinary;
            if(opLexeme == "-")
            {
                isBinary = paramCount > 1;
            }
            else if(BinaryOperatorSymbols.Contains(opLexeme))
            {
                isBinary = true;
            }
            else if(UnaryOperatorSymbols.Contains(opLexeme))
            {
                isBinary = false;
            }
            else
            {
                // Unknown operator symbol (grammar forbids this); skip shape
                // validation so we don't produce a misleading diagnostic.
                continue;
            }

            var expectedArity = isBinary ? 2 : 1;

            // MIST_SB_0034 — arity mismatch (Requirements 4.8 & 4.9).
            if(paramCount != expectedArity)
            {
                var message = isBinary
                    ? $"Binary operator '{opLexeme}' must declare exactly 2 parameters; found {paramCount}."
                    : $"Unary operator '{opLexeme}' must declare exactly 1 parameter; found {paramCount}.";

                diagnostics.Add(MakeDiagnosticWithLocation(
                    OperatorArityMismatch.Value,
                    DiagnosticSeverity.Error,
                    message,
                    opDecl,
                    sourceText));
            }

            // MIST_SB_0035 — operator must be declared `public static`
            // (Requirement 4.2). Both modifiers must be present.
            var hasPublic = false;
            var hasStatic = false;
            foreach(var modifier in opDecl.Modifiers)
            {
                if(modifier is PublicModifierModifierNode)
                {
                    hasPublic = true;
                }

                if(modifier is StaticModifierModifierNode)
                {
                    hasStatic = true;
                }
            }

            if(!hasPublic || !hasStatic)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    OperatorMustBePublicStatic.Value,
                    DiagnosticSeverity.Error,
                    $"Operator '{opLexeme}' must be declared 'public static'.",
                    opDecl,
                    sourceText));
            }

            // MIST_SB_0033 — operator declared outside a class/struct body
            // (Requirement 4.7). The grammar already restricts
            // OperatorDeclaration to MemberDeclaration (see Mist.storm), so
            // every operator reaches this pass inside a type's member scope
            // and this check is unreachable from parsed source today. It is
            // wired defensively so a future grammar change admitting top-
            // level operators would inherit validation automatically. We
            // detect a top-level operator by checking whether the symbol's
            // containing scope is the member scope of a registered class or
            // struct type. If no registered type claims this scope, the
            // operator is not inside any type body.
            if(!IsScopeInsideRegisteredType(symbol.ContainingScope, symbolTable))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    OperatorOutsideTypeBody.Value,
                    DiagnosticSeverity.Error,
                    "Operators must be declared as 'public static' members of a class or struct.",
                    opDecl,
                    sourceText));
            }
        }
    }

    /// <summary>
    /// Returns <c>true</c> if <paramref name="scope"/> (or any of its
    /// ancestor scopes) is the member scope of a class or struct type
    /// registered in <paramref name="symbolTable"/>. Used by
    /// <see cref="Pass1e_ValidateOperatorShape"/> as the trigger for
    /// <c>MIST_SB_0033</c>. The grammar forbids operator declarations
    /// outside a type body today, so every reachable operator symbol
    /// satisfies this condition; the helper exists to guarantee the
    /// diagnostic would still fire on a future grammar relaxation.
    /// </summary>
    private static bool IsScopeInsideRegisteredType(
        IScope? scope,
        SymbolTable symbolTable)
    {
        for(var s = scope; s is not null; s = s.Parent)
        {
            foreach(var typeSymbol in symbolTable.AllSymbols)
            {
                if(typeSymbol.Kind is not SymbolKind.Class and not SymbolKind.Struct)
                {
                    continue;
                }

                var memberScope = typeSymbol.DeclaredType switch
                {
                    ClassType ct => ct.MemberScope,
                    StructType st => st.MemberScope,
                    _ => null,
                };

                if(memberScope is not null && ReferenceEquals(memberScope, s))
                {
                    return true;
                }
            }
        }

        return false;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1e — Validate cast-operator-declaration shape (Task 3.2)
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Validates the shape of every registered cast operator declaration and
    /// emits diagnostics for:
    /// <list type="bullet">
    /// <item>
    /// <description><c>MIST_SB_0040</c> — cast operator parameter count is
    /// not exactly 1 (Requirements 6.3, 6.4).</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0041</c> — cast operator not declared
    /// <c>public static</c> (Requirement 6.1).</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0042</c> — cast operator declared outside a
    /// class or struct body (Requirement 6.1). Unreachable from parsed source
    /// because the grammar restricts <c>CastOperatorDeclaration</c> to
    /// <c>MemberDeclaration</c>; registered defensively.</description>
    /// </item>
    /// <item>
    /// <description><c>MIST_SB_0043</c> — duplicate cast operator (same kind
    /// and same target type name) in the same type (Requirement 6.5).
    /// Name-based only; full type-based duplicate detection is deferred to
    /// the type checker.</description>
    /// </item>
    /// </list>
    /// </summary>
    private static void Pass1e_ValidateCastOperatorShape(

        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        // Track seen cast operator encoded names per containing scope for
        // duplicate detection. Key = containing scope reference, Value = set
        // of encoded names already seen (e.g., "operator_implicit_Weight").
        var seenPerScope = new Dictionary<IScope, HashSet<string>>(ReferenceEqualityComparer.Instance);

        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbolTable.GetDeclaringNode(symbol) is not CastOperatorDeclarationNode castOpDecl)
            {
                continue;
            }

            var sourceText = GetSourceTextFromOrigin(castOpDecl);

            // ── MIST_SB_0040: Parameter count must be exactly 1 ──────────
            // The ParameterList rule is `Parameter (COMMA Parameter)*`, so
            // count = 1 + Parameters.Length when non-null, or 0 when absent.
            var paramCount = castOpDecl.Parameters is null
                ? 0
                : 1 + castOpDecl.Parameters.Parameters.Length;

            if(paramCount != 1)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    CastOperatorArityMismatch.Value,
                    DiagnosticSeverity.Error,
                    $"Cast operator must have exactly one parameter; found {paramCount}.",
                    castOpDecl,
                    sourceText));
            }

            // ── MIST_SB_0041: Must be declared `public static` ──────────
            var hasPublic = false;
            var hasStatic = false;
            foreach(var modifier in castOpDecl.Modifiers)
            {
                if(modifier is PublicModifierModifierNode)
                {
                    hasPublic = true;
                }

                if(modifier is StaticModifierModifierNode)
                {
                    hasStatic = true;
                }
            }

            if(!hasPublic || !hasStatic)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    CastOperatorMustBePublicStatic.Value,
                    DiagnosticSeverity.Error,
                    "Cast operator must be declared 'public static'.",
                    castOpDecl,
                    sourceText));
            }

            // ── MIST_SB_0042: Must be inside a class or struct ──────────
            if(!IsScopeInsideRegisteredType(symbol.ContainingScope, symbolTable))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    CastOperatorOutsideTypeBody.Value,
                    DiagnosticSeverity.Error,
                    "Cast operators must be declared inside a class or struct.",
                    castOpDecl,
                    sourceText));
            }

            // ── MIST_SB_0043: Duplicate cast operator detection ─────────
            // Two cast operators in the same type with the same encoded name
            // (same kind + same target type name) are duplicates.
            if(symbol.ContainingScope is not null)
            {
                if(!seenPerScope.TryGetValue(symbol.ContainingScope, out var seenNames))
                {
                    seenNames = new HashSet<string>();
                    seenPerScope[symbol.ContainingScope] = seenNames;
                }

                if(!seenNames.Add(symbol.Name))
                {
                    // Extract kind and type names for the diagnostic message.
                    var kindPrefix = castOpDecl.CastKind switch
                    {
                        ImplicitCastCastOperatorKindNode => "implicit",
                        ExplicitCastCastOperatorKindNode => "explicit",
                        _ => "unknown",
                    };
                    var targetTypeName = ExtractTypeReferenceName(castOpDecl.TargetType, sourceText);

                    // Extract source type name from the parameter (if present).
                    var sourceTypeName = castOpDecl.Parameters is not null
                        ? ExtractTypeReferenceName(castOpDecl.Parameters.Parameter.Type, sourceText)
                        : "?";

                    diagnostics.Add(MakeDiagnosticWithLocation(
                        DuplicateCastOperator.Value,
                        DiagnosticSeverity.Error,
                        $"Duplicate {kindPrefix} cast operator from '{sourceTypeName}' to '{targetTypeName}'.",
                        castOpDecl,
                        sourceText));
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1b — Resolve base types for class inheritance
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Performs a using-aware lookup for a type name during Pass 1.
    /// First tries the normal scope chain lookup. If that fails, finds the
    /// compilation unit containing the declaration, extracts its <c>using</c>
    /// directives, and searches the imported namespace scopes.
    /// </summary>
    private static ISymbol? LookupWithUsings(
        string name,
        IScope parentScope,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        SymbolTable symbolTable,
        MistCompilation compilation,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        // 1. Normal scope chain lookup.
        var result = parentScope.Lookup(name);
        if(result is not null)
        {
            return result;
        }

        // 2. Find the compilation unit containing this declaration.
        CompilationUnitNode? containingCu = null;
        var containingCuIndex = -1;
        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is CompilationUnitNode cu && ContainsNodeByReference(cu, declaringNode))
            {
                containingCu = cu;
                containingCuIndex = i;
                break;
            }
        }

        if(containingCu is null)
        {
            return null;
        }

        // Find the source text for this compilation unit (needed for ExtractQualifiedName).
        var sourceText = containingCuIndex < compilation.Units.Length
            ? compilation.Units[containingCuIndex].Source
            : null;

        // 3. Extract using directives and search imported namespace scopes.
        foreach(var usingDecl in containingCu.Usings)
        {
            var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
            if(string.IsNullOrEmpty(usingName))
            {
                continue;
            }

            // Find the namespace scope for this using directive.
            var nsScope = FindExistingNamespaceScope(globalScope, symbolTable, usingName);
            if(nsScope is null)
            {
                continue;
            }

            // Search the namespace scope for the name (non-recursive, direct members only).
            foreach(var member in nsScope.Members)
            {
                if(member.Name == name)
                {
                    return member;
                }
            }
        }
        // Also search using directives that appear after a file-scoped namespace
        // (parsed as UsingItem top-level items rather than CompilationUnit.Usings).
        foreach(var item in containingCu.Items)
        {
            if(item is UsingItemTopLevelItemNode usingItem)
            {
                var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                if(string.IsNullOrEmpty(usingName))
                {
                    continue;
                }

                var nsScope = FindExistingNamespaceScope(globalScope, symbolTable, usingName);
                if(nsScope is null)
                {
                    continue;
                }

                foreach(var member in nsScope.Members)
                {
                    if(member.Name == name)
                    {
                        return member;
                    }
                }
            }
        }

        // 4. Fall back to the ambient type resolver (CLR types from SDK/NuGet assemblies).
        // This enables inheriting from CLR types (e.g., DbContext, Exception, Stream)
        // and implementing CLR interfaces in base type positions.
        if(ambientTypeResolver is not null)
        {
            // Collect imported namespaces from using directives.
            var importedNamespaces = new List<string>();
            foreach(var usingDecl in containingCu.Usings)
            {
                var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
                if(!string.IsNullOrEmpty(usingName))
                {
                    importedNamespaces.Add(usingName);
                }
            }

            foreach(var item in containingCu.Items)
            {
                if(item is UsingItemTopLevelItemNode usingItem)
                {
                    var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                    if(!string.IsNullOrEmpty(usingName))
                    {
                        importedNamespaces.Add(usingName);
                    }
                }
            }
            // Also include global usings from the compilation unit.
            if(containingCuIndex < compilation.Units.Length)
            {
                foreach(var globalNs in compilation.Units[containingCuIndex].GlobalUsings)
                {
                    if(!string.IsNullOrEmpty(globalNs))
                    {
                        importedNamespaces.Add(globalNs);
                    }
                }
            }

            foreach(var ns in importedNamespaces)
            {
                var resolvedType = ambientTypeResolver.ResolveType(ns, name);
                if(resolvedType is not null)
                {
                    // Create a symbol for the resolved ambient type. We intentionally
                    // do NOT call RegisterAmbientTypeInScope here because Pass 1 runs
                    // before the stdlib provider is upgraded — populating members now
                    // would produce incorrect type references. Pass 2's ResolveNamedType
                    // will handle full registration when the type is encountered in
                    // expression/type-annotation contexts.
                    var kind = resolvedType is ClassType ? SymbolKind.Class
                        : resolvedType is AbstractType ? SymbolKind.Abstract
                        : resolvedType is StructType ? SymbolKind.Struct
                        : SymbolKind.Class;
                    return new Symbol(name, kind, SymbolOrigin.Backend, globalScope, resolvedType, declarationSpan: null);
                }
            }
        }

        return null;
    }

    /// <summary>
    /// After all types are registered in Pass 1, resolve base type references
    /// for classes with inheritance clauses. This runs as a separate step so
    /// that forward references to base classes are supported.
    /// </summary>
    private static void Pass1_ResolveBaseTypes(
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        SymbolTable symbolTable,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        // Walk all registered symbols to find class types and their AST nodes.
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Class || symbol.DeclaredType is not ClassType classType)
            {
                continue;
            }

            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is not TypeBodyDeclarationNode classDecl)
            {
                continue;
            }

            // Check if this class has an inheritance clause.
            if(classDecl.BaseList is null)
            {
                continue;
            }

            var baseClassName = classDecl.BaseList.First.Name.Lexeme;
            var parentScope = symbol.ContainingScope;

            // Look up the base class name in the parent scope, falling back to
            // imported namespace scopes from the file's using directives.
            var resolvedSymbol = LookupWithUsings(
                baseClassName, parentScope, classDecl, asts, globalScope, symbolTable, compilation, ambientTypeResolver);

            if(resolvedSymbol is null)
            {
                // Determine the source text for the diagnostic.
                var sourceText = GetSourceTextFromOrigin(classDecl);

                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_UNDEFINED_BASE_TYPE",
                    DiagnosticSeverity.Error,
                    $"The base type '{baseClassName}' could not be found.",
                    classDecl,
                    sourceText));
            }
            else if(resolvedSymbol.DeclaredType is StructType ||
                     UnwrapTypeForwards(resolvedSymbol.DeclaredType) is StructType)
            {
                var sourceText = GetSourceTextFromOrigin(classDecl);

                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_CANNOT_INHERIT_STRUCT",
                    DiagnosticSeverity.Error,
                    $"Class '{classType.DisplayName}' cannot inherit from struct '{baseClassName}'.",
                    classDecl,
                    sourceText));
            }
            else if(resolvedSymbol.DeclaredType is UnknownType)
            {
                // Defensive guard (Requirements 6.1, 16.6). The grammar
                // prevents `unknown` from appearing as the name in a
                // `BaseTypeRef` because `unknown` lexes to the reserved
                // `UNKNOWN` token, not `IDENTIFIER`. This branch exists
                // to keep the rule robust for programmatically-constructed
                // ASTs and for documentation alignment with Req 6.1. The
                // reference is dropped from the base list by simply not
                // assigning `classType.BaseType`.
                var sourceText = GetSourceTextFromOrigin(classDecl);

                diagnostics.Add(MakeDiagnosticWithLocation(
                    UnknownAsBaseType.Value,
                    DiagnosticSeverity.Error,
                    $"Class '{classType.DisplayName}' cannot inherit from 'unknown'. " +
                    "'unknown' is the user-facing top type and does not participate in inheritance.",
                    classDecl,
                    sourceText));
            }
            else if(resolvedSymbol.DeclaredType is ClassType resolvedClassType)
            {
                // Check if the resolved base type is sealed — sealed types cannot be inherited.
                if(resolvedClassType.IsSealed)
                {
                    var sourceText = GetSourceTextFromOrigin(classDecl);

                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST_SEALED_INHERITANCE",
                        DiagnosticSeverity.Error,
                        $"Class '{classType.DisplayName}' cannot inherit from '{baseClassName}' because it is sealed.",
                        classDecl,
                        sourceText));
                }
                else
                {
                    var typeArgs = classDecl.BaseList.First.TypeArgs;
                    classType.BaseType = ResolveGenericTypeReference(
                        resolvedClassType, typeArgs, baseClassName,
                        classType, classDecl, asts, compilation, diagnostics);
                }
            }
            else if(UnwrapTypeForwards(resolvedSymbol.DeclaredType) is ClassType unwrappedClassType)
            {
                // The base type resolves to a type alias or newtype wrapping a ClassType.
                if(unwrappedClassType.IsSealed)
                {
                    var sourceText = GetSourceTextFromOrigin(classDecl);

                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST_SEALED_INHERITANCE",
                        DiagnosticSeverity.Error,
                        $"Class '{classType.DisplayName}' cannot inherit from '{baseClassName}' because it is sealed.",
                        classDecl,
                        sourceText));
                }
                else
                {
                    var typeArgs = classDecl.BaseList.First.TypeArgs;
                    classType.BaseType = ResolveGenericTypeReference(
                        unwrappedClassType, typeArgs, baseClassName,
                        classType, classDecl, asts, compilation, diagnostics);
                }
            }
        }
    }

    /// <summary>
    /// Resolves base struct types for struct inheritance. Mirrors the class
    /// base type resolution logic in <see cref="Pass1_ResolveBaseTypes"/>.
    /// Iterates all struct symbols, checks if the first entry in the struct's
    /// abstract type list resolves to a <see cref="StructType"/>, and if so sets
    /// it as <see cref="StructType.BaseType"/>. If the first entry resolves
    /// to a <see cref="ClassType"/> or other non-struct/non-abstract type,
    /// emits <c>MIST_STRUCT_INVALID_BASE</c>.
    /// </summary>
    private static void Pass1_ResolveStructBaseTypes(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Struct || symbol.DeclaredType is not StructType structType)
            {
                continue;
            }

            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is not TypeBodyDeclarationNode structDecl)
            {
                continue;
            }

            if(structDecl.BaseList is null)
            {
                continue;
            }

            var entries = ExtractBaseListEntries(structDecl.BaseList);
            if(entries.Count == 0)
            {
                continue;
            }

            var firstEntry = entries[0];
            var firstName = firstEntry.Name.Lexeme;
            if(string.IsNullOrEmpty(firstName))
            {
                continue;
            }

            var parentScope = symbol.ContainingScope;
            var resolvedSymbol = LookupWithUsings(
                firstName, parentScope, structDecl, asts, globalScope, symbolTable, compilation, ambientTypeResolver);

            if(resolvedSymbol?.DeclaredType is StructType resolvedStructType)
            {
                // First entry is a struct → record as base type.
                var typeArgs = firstEntry.TypeArgs;
                structType.BaseType = ResolveGenericTypeReference(
                    resolvedStructType, typeArgs, firstName,
                    structType, structDecl, asts, compilation, diagnostics);
            }
            else if(UnwrapTypeForwards(resolvedSymbol?.DeclaredType) is StructType unwrappedStructType)
            {
                // First entry is a type alias or newtype wrapping a StructType → record as base type.
                var typeArgs = firstEntry.TypeArgs;
                structType.BaseType = ResolveGenericTypeReference(
                    unwrappedStructType, typeArgs, firstName,
                    structType, structDecl, asts, compilation, diagnostics);
            }
            else if(resolvedSymbol?.DeclaredType is ClassType ||
                     UnwrapTypeForwards(resolvedSymbol?.DeclaredType) is ClassType)
            {
                // A struct cannot inherit from a class.
                var sourceText = GetSourceTextFromOrigin(structDecl);

                diagnostics.Add(MakeDiagnosticWithLocation(
                    StructInvalidBase.Value,
                    DiagnosticSeverity.Error,
                    $"Struct '{structType.DisplayName}' cannot inherit from '{firstName}' because it is not a struct.",
                    structDecl,
                    sourceText));
            }
            // If it resolves to an abstract type, leave it for
            // ResolveStructAbstractList to handle normally.
        }

        // After all struct base types are resolved, detect cycles and
        // chains exceeding the maximum depth.
        DetectStructInheritanceCycles(symbolTable, diagnostics);

        // After cycles are broken, populate inherited public members into
        // each derived struct's MemberScope so that member lookup works
        // without a manual chain walk (Requirements 2.7, 3.2, 3.4, 3.5, 3.6).
        PopulateInheritedStructMembers(symbolTable);
    }

    /// <summary>
    /// Walks the ancestor chain for each struct with a base type and injects
    /// public fields, methods, and properties from ancestors into the derived
    /// struct's <see cref="StructType.MemberScope"/>. Only public members are
    /// injected; private members remain inaccessible from the derived struct.
    /// Members already declared on the derived struct are not overwritten.
    /// </summary>
    private static void PopulateInheritedStructMembers(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Struct || symbol.DeclaredType is not StructType structType)
            {
                continue;
            }

            if(structType.BaseType is null)
            {
                continue;
            }

            // BaseType may be a StructType directly or a ConstructedType
            // wrapping a StructType (for generic struct inheritance).
            var baseStruct = structType.BaseType as StructType
                ?? (structType.BaseType as ConstructedType)?.GenericDefinition as StructType;

            if(baseStruct is null)
            {
                continue;
            }

            if(structType.MemberScope is not Scope derivedScope)
            {
                continue;
            }

            // Collect names already declared directly on the derived struct
            // so we don't overwrite them with inherited members.
            var declaredNames = new HashSet<string>();
            foreach(var member in derivedScope.Members)
            {
                _ = declaredNames.Add(member.Name);
            }

            // Walk the ancestor chain and inject public members.
            var current = baseStruct;
            while(current is not null)
            {
                foreach(var member in current.MemberScope.Members)
                {
                    // Only inject fields, methods, and properties.
                    if(member.Kind is not (SymbolKind.Field or SymbolKind.Method or SymbolKind.Property))
                    {
                        continue;
                    }

                    // Skip members already present in the derived scope (either
                    // declared directly or inherited from a closer ancestor).
                    if(declaredNames.Contains(member.Name))
                    {
                        continue;
                    }

                    // Only inject public members.
                    if(!IsMemberPublic(member, symbolTable))
                    {
                        continue;
                    }

                    derivedScope.AddMember(member);
                    _ = declaredNames.Add(member.Name);
                }

                // Walk up: BaseType may also be a ConstructedType wrapping a StructType.
                current = current.BaseType as StructType
                    ?? (current.BaseType as ConstructedType)?.GenericDefinition as StructType;
            }
        }
    }

    /// <summary>
    /// Unwraps type forwards (type aliases and newtypes) to reach the underlying
    /// concrete type. <see cref="TypeAliasType"/> is unwrapped via
    /// <see cref="TypeAliasType.UnderlyingType"/> and <see cref="NewtypeType"/> is
    /// unwrapped via <see cref="NewtypeType.SourceType"/>. Chains of aliases/newtypes
    /// are followed until a non-forward type is reached.
    /// </summary>
    private static IType? UnwrapTypeForwards(IType? type)
    {
        while(type is TypeAliasType alias)
        {
            type = alias.UnderlyingType;
        }

        if(type is NewtypeType newtype)
        {
            type = newtype.SourceType;
        }

        return type;
    }

    /// <summary>
    /// Resolves a type reference in an inheritance context (base clause or abstract type list),
    /// handling type arguments to produce a <see cref="ConstructedType"/> when appropriate.
    /// Emits diagnostics for arity mismatches, non-generic type arguments, and missing type arguments.
    /// </summary>
    private static IType ResolveGenericTypeReference(
        IType resolvedType,
        TypeArgumentListNode? typeArgs,
        string typeName,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Get the type parameters from the resolved type.
        var typeParams = GetTypeParameters(resolvedType);
        var hasTypeArgs = typeArgs is not null;
        var typeParamCount = typeParams.Count;

        if(hasTypeArgs)
        {
            // Type arguments were provided.
            if(typeParamCount == 0)
            {
                // The referenced type is not generic — emit MIST_NOT_GENERIC.
                var sourceText = GetSourceTextFromOrigin(declaringNode);
                diagnostics.Add(MakeDiagnosticWithLocation(
                    GenericsDiagnostics.NotGeneric.Id.Value,
                    DiagnosticSeverity.Error,
                    $"Type '{typeName}' is not generic and does not accept type arguments.",
                    declaringNode,
                    sourceText));
                return resolvedType;
            }

            // Check if the resolved type has any dependent type parameters.
            // If so, use the dependent-aware resolution path that handles
            // literal type arguments and forwarded dependent parameters.
            var hasDependentParams = typeParams.Any(p => p is DependentTypeParameterType);

            if(hasDependentParams)
            {
                // Use dependent-aware resolution (handles literals, const refs, forwarding).
                var (resolvedTypeArgs, dependentArgs) = ResolvePass1TypeArgumentListWithDependents(
                    typeArgs!, typeParams, declaringType, declaringNode, asts, compilation, diagnostics);
                var typeArgCount = resolvedTypeArgs.Count;

                if(typeArgCount != typeParamCount)
                {
                    // Arity mismatch — emit MIST_ARITY_MISMATCH.
                    var sourceText = GetSourceTextFromOrigin(declaringNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        GenericsDiagnostics.ArityMismatch.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Type '{typeName}' expects {typeParamCount} type argument(s) but received {typeArgCount}.",
                        declaringNode,
                        sourceText));
                    return resolvedType;
                }

                // Construct the ConstructedType with dependent arguments.
                return new ConstructedType(resolvedType, resolvedTypeArgs, dependentArgs);
            }
            else
            {
                // No dependent parameters — use the standard resolution path.
                var resolvedTypeArgs = ResolveTypeArgumentList(typeArgs!, declaringType, declaringNode, asts, compilation, diagnostics);
                var typeArgCount = resolvedTypeArgs.Count;

                if(typeArgCount != typeParamCount)
                {
                    // Arity mismatch — emit MIST_ARITY_MISMATCH.
                    var sourceText = GetSourceTextFromOrigin(declaringNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        GenericsDiagnostics.ArityMismatch.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Type '{typeName}' expects {typeParamCount} type argument(s) but received {typeArgCount}.",
                        declaringNode,
                        sourceText));
                    return resolvedType;
                }

                // Construct the ConstructedType.
                return new ConstructedType(resolvedType, resolvedTypeArgs);
            }
        }
        else
        {
            // No type arguments provided.
            if(typeParamCount > 0)
            {
                // The referenced type is generic but no type arguments were provided.
                // Check if the declaring type has matching type parameters that could
                // be forwarded (e.g., class Foo<T> : Bar<T> is handled when type args
                // are explicitly provided). If the declaring type is non-generic,
                // emit MIST_MISSING_TYPE_ARGUMENTS.
                var declaringTypeParams = GetTypeParameters(declaringType);
                if(declaringTypeParams.Count == 0)
                {
                    var sourceText = GetSourceTextFromOrigin(declaringNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        GenericsDiagnostics.MissingTypeArguments.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Generic type '{typeName}' requires type arguments.",
                        declaringNode,
                        sourceText));
                }
            }

            return resolvedType;
        }
    }

    /// <summary>
    /// Resolves a <see cref="TypeArgumentListNode"/> to a list of <see cref="IType"/> instances.
    /// Each type argument name is looked up in the declaring type's member scope (for type parameters)
    /// and in the parent scope (for concrete types).
    /// </summary>
    private static IReadOnlyList<IType> ResolveTypeArgumentList(
        TypeArgumentListNode typeArgList,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        var resolvedArgs = new List<IType>();

        // Resolve the first type argument.
        var firstType = ResolveTypeArgFromTypeReference(typeArgList.GetTypeReference(), declaringType, declaringNode, asts, compilation, diagnostics);
        resolvedArgs.Add(firstType);

        // Resolve the rest of the type arguments.
        foreach(var typeRef in typeArgList.GetTypeReferences())
        {
            var argType = ResolveTypeArgFromTypeReference(typeRef, declaringType, declaringNode, asts, compilation, diagnostics);
            resolvedArgs.Add(argType);
        }

        return resolvedArgs;
    }

    /// <summary>
    /// Resolves a <see cref="TypeArgumentListNode"/> to a list of <see cref="IType"/> instances
    /// and a parallel list of <see cref="DependentValueArgument"/> entries in the Pass 1
    /// inheritance context. This handles literal type arguments (e.g., <c>16</c> in
    /// <c>IFixedCollection&lt;16&gt;</c>) and forwarded dependent parameters (e.g., <c>N</c>
    /// in <c>class Buffer&lt;N:int&gt; : IFixedCollection&lt;N&gt;</c>).
    /// </summary>
    private static (IReadOnlyList<IType> TypeArgs, IReadOnlyList<DependentValueArgument?>? DependentArgs) ResolvePass1TypeArgumentListWithDependents(
        TypeArgumentListNode typeArgList,
        IReadOnlyList<IType> typeParams,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Collect all TypeArgumentNode entries in order.
        var argNodes = new List<TypeArgumentNode> { typeArgList.TypeArgument };
        foreach(var extra in typeArgList.TypeArguments)
        {
            argNodes.Add(extra);
        }

        var resolvedTypeArgs = new List<IType>(argNodes.Count);
        List<DependentValueArgument?>? dependentArgs = null;

        for(var i = 0; i < argNodes.Count; i++)
        {
            var argNode = argNodes[i];
            var correspondingParam = i < typeParams.Count ? typeParams[i] : null;
            var isDependentPosition = correspondingParam is DependentTypeParameterType;

            if(isDependentPosition)
            {
                var depParam = (DependentTypeParameterType)correspondingParam!;
                var (depArg, forwardedType) = TryResolvePass1DependentValueArgument(
                    argNode, depParam, declaringType, declaringNode);
                if(depArg is not null)
                {
                    // Successfully resolved as a dependent value argument.
                    // If a forwarded DependentTypeParameterType was detected, use it as the
                    // type argument so ValidateDependentForwardingForConstructedBase can detect it.
                    // Otherwise, use the dependent parameter's value type as a placeholder.
                    resolvedTypeArgs.Add(forwardedType ?? depParam.ValueType);
                    dependentArgs ??= new List<DependentValueArgument?>(new DependentValueArgument?[argNodes.Count]);
                    dependentArgs[i] = depArg;
                    continue;
                }
                // If resolution returned null, fall through to normal type resolution.
            }

            // Normal type argument resolution (for regular type parameters or when
            // a dependent position has a type reference that isn't a const).
            if(argNode is TypeReferenceTypeArgumentTypeArgumentNode typeRefArg)
            {
                var resolved = ResolveTypeArgFromTypeReference(
                    typeRefArg.Type, declaringType, declaringNode, asts, compilation, diagnostics);
                resolvedTypeArgs.Add(resolved);
            }
            else
            {
                // A literal type argument in a non-dependent position — this is an error
                // that will be caught by the type checker later. For now, use ErrorType.
                resolvedTypeArgs.Add(ErrorType.Instance);
            }
        }

        return (resolvedTypeArgs, dependentArgs);
    }

    /// <summary>
    /// Attempts to resolve a <see cref="TypeArgumentNode"/> as a <see cref="DependentValueArgument"/>
    /// in the Pass 1 inheritance context. Returns <c>(null, null)</c> if the argument is a type reference
    /// (not a const or literal), indicating normal type argument resolution should proceed.
    /// When a forwarded dependent parameter is detected, the second tuple element contains the
    /// <see cref="DependentTypeParameterType"/> so it can be placed in the TypeArguments list
    /// for forwarding validation.
    /// </summary>
    private static (DependentValueArgument? DepArg, DependentTypeParameterType? ForwardedType) TryResolvePass1DependentValueArgument(
        TypeArgumentNode argNode,
        DependentTypeParameterType depParam,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode)
    {
        switch(argNode)
        {
            case IntegerLiteralTypeArgumentTypeArgumentNode intLit:
                {
                    var valueText = intLit.Literal.Lexeme;
                    if(long.TryParse(valueText, out var value))
                    {
                        return (new DependentValueArgument(value, depParam.ValueType, valueText), null);
                    }

                    return (new DependentValueArgument(0L, depParam.ValueType, valueText), null);
                }

            case NegatedIntegerTypeArgumentTypeArgumentNode negLit:
                {
                    var valueText = negLit.Literal.Lexeme;
                    if(long.TryParse(valueText, out var value))
                    {
                        return (new DependentValueArgument(-value, depParam.ValueType, $"-{valueText}"), null);
                    }

                    return (new DependentValueArgument(0L, depParam.ValueType, $"-{valueText}"), null);
                }

            case HexLiteralTypeArgumentTypeArgumentNode hexLit:
                {
                    var valueText = hexLit.Literal.Lexeme;
                    var hexStr = valueText.StartsWith("0x", StringComparison.OrdinalIgnoreCase)
                        ? valueText[2..] : valueText;
                    if(long.TryParse(hexStr, System.Globalization.NumberStyles.HexNumber, null, out var value))
                    {
                        return (new DependentValueArgument(value, depParam.ValueType, valueText), null);
                    }

                    return (new DependentValueArgument(0L, depParam.ValueType, valueText), null);
                }

            case BinaryLiteralTypeArgumentTypeArgumentNode binLit:
                {
                    var valueText = binLit.Literal.Lexeme;
                    var binStr = valueText.StartsWith("0b", StringComparison.OrdinalIgnoreCase)
                        ? valueText[2..] : valueText;
                    try
                    {
                        var value = Convert.ToInt64(binStr, 2);
                        return (new DependentValueArgument(value, depParam.ValueType, valueText), null);
                    }
                    catch
                    {
                        return (new DependentValueArgument(0L, depParam.ValueType, valueText), null);
                    }
                }

            case TrueLiteralTypeArgumentTypeArgumentNode:
                return (new DependentValueArgument(true, depParam.ValueType, "true"), null);

            case FalseLiteralTypeArgumentTypeArgumentNode:
                return (new DependentValueArgument(false, depParam.ValueType, "false"), null);

            case CharLiteralTypeArgumentTypeArgumentNode charLit:
                {
                    var valueText = charLit.Literal.Lexeme;
                    // Strip surrounding quotes to get the char value.
                    var charValue = valueText.Length >= 3 ? valueText[1] : '\0';
                    return (new DependentValueArgument(charValue, depParam.ValueType, valueText), null);
                }

            case TypeReferenceTypeArgumentTypeArgumentNode typeRefArg:
                {
                    // Disambiguation: check if this is a bare identifier that resolves to a
                    // forwarded dependent parameter from the declaring type.
                    if(typeRefArg.Type.First is NamedSingleTypeRefSingleTypeRefNode namedRef
                        && namedRef.TypeArgs is null
                        && namedRef.ArrayRank is null)
                    {
                        var argName = namedRef.Name.IDENTIFIER.Lexeme;
                        if(string.IsNullOrEmpty(argName))
                        {
                            var span = namedRef.Name.Span;
                            if(span.Length > 0)
                            {
                                var srcTextForArg = GetSourceTextFromOrigin(declaringNode);
                                if(srcTextForArg is not null && span.Start + span.Length <= srcTextForArg.Contents.Length)
                                {
                                    argName = srcTextForArg.Contents.Substring(span.Start, span.Length);
                                }
                            }
                        }

                        // Look up in the declaring type's member scope for dependent parameters.
                        var memberScope = GetMemberScope(declaringType);
                        var resolvedSymbol = memberScope?.Lookup(argName);

                        if(resolvedSymbol is not null && resolvedSymbol.DeclaredType is DependentTypeParameterType forwardedParam)
                        {
                            // This is a forwarded dependent parameter (e.g., class Buffer<N:int> : IFixedCollection<N>).
                            // Return a DependentValueArgument with the parameter name as the value,
                            // and the forwarded DependentTypeParameterType for the TypeArguments list.
                            return (new DependentValueArgument(argName, forwardedParam.ValueType, argName), forwardedParam);
                        }

                        // If it resolves to a type, fall through to normal resolution.
                        if(resolvedSymbol is not null
                            && resolvedSymbol.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum)
                        {
                            return (null, null);
                        }

                        // If it resolves to a field (potential const), treat as dependent value.
                        if(resolvedSymbol is not null
                            && resolvedSymbol.Kind is SymbolKind.Field or SymbolKind.LocalVariable)
                        {
                            return (new DependentValueArgument(argName, resolvedSymbol.DeclaredType ?? depParam.ValueType, argName), null);
                        }
                    }

                    // Not a dependent value — fall through to normal type resolution.
                    return (null, null);
                }

            default:
                return (null, null);
        }
    }

    /// <summary>
    /// Resolves a single type argument from a <see cref="TypeReferenceNode"/> in an inheritance context.
    /// Handles primitive types, type parameter references, and named types.
    /// </summary>
    private static IType ResolveTypeArgFromTypeReference(
        TypeReferenceNode typeRef,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        switch(typeRef.First)
        {
            case PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef:
                var baseType = ResolvePrimitiveType(primitiveRef.PrimitiveType);
                if(primitiveRef.ArrayRank is not null)
                {
                    return new ArrayType(baseType);
                }

                return baseType;

            case VoidSingleTypeRefSingleTypeRefNode:
                return LegacyPrimitiveTypes.Void;

            case NamedSingleTypeRefSingleTypeRefNode namedRef:
                {
                    // The generated parser may not populate IDENTIFIER.Lexeme on
                    // QualifiedIdentifierNode. Fall back to extracting the name
                    // from the source text span when the lexeme is empty.
                    var argName = namedRef.Name.IDENTIFIER.Lexeme;
                    if(string.IsNullOrEmpty(argName))
                    {
                        var span = namedRef.Name.Span;
                        if(span.Length > 0)
                        {
                            // Find the correct source text by matching the declaring
                            // node to its compilation unit via containment check
                            // (span-based matching is unreliable across files).
                            var srcTextForArg = GetSourceTextFromOrigin(declaringNode);
                            if(srcTextForArg is not null && span.Start + span.Length <= srcTextForArg.Contents.Length)
                            {
                                argName = srcTextForArg.Contents.Substring(span.Start, span.Length);
                            }
                        }
                    }

                    // First, look up in the declaring type's member scope (for type parameters).
                    var memberScope = GetMemberScope(declaringType);
                    var resolvedSymbol = memberScope?.Lookup(argName);

                    if(resolvedSymbol is not null && resolvedSymbol.DeclaredType is TypeParameterType tpt)
                    {
                        return tpt;
                    }

                    // If the symbol found is not a type (e.g., a constructor with the same
                    // name as the class), skip it and look in the parent scope instead.
                    if(resolvedSymbol is not null
                        && resolvedSymbol.Kind is not (SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum))
                    {
                        resolvedSymbol = null;
                    }

                    // Look up in the parent scope chain (for concrete types).
                    if(resolvedSymbol is null && memberScope?.Parent is not null)
                    {
                        resolvedSymbol = memberScope.Parent.Lookup(argName);
                    }

                    // If the parent scope lookup also found a non-type symbol, try
                    // walking further up the scope chain to find a type symbol.
                    if(resolvedSymbol is not null
                        && resolvedSymbol.DeclaredType is null
                        && resolvedSymbol.Kind is not (SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum))
                    {
                        // Walk up the scope chain manually to find a type symbol.
                        var searchScope = memberScope?.Parent?.Parent;
                        resolvedSymbol = null;
                        while(searchScope is not null && resolvedSymbol is null)
                        {
                            if(searchScope is Scope s)
                            {
                                foreach(var m in s.Members)
                                {
                                    if(m.Name == argName && m.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum)
                                    {
                                        resolvedSymbol = m;
                                        break;
                                    }
                                }
                            }

                            searchScope = searchScope.Parent;
                        }
                    }

                    if(resolvedSymbol is not null && resolvedSymbol.DeclaredType is not null)
                    {
                        var resolvedType = resolvedSymbol.DeclaredType;

                        // If this type argument itself has type arguments (nested generics),
                        // resolve them recursively.
                        if(namedRef.TypeArgs is not null)
                        {
                            var nestedTypeParams = GetTypeParameters(resolvedType);
                            if(nestedTypeParams.Count == 0)
                            {
                                var sourceText = GetSourceTextFromOrigin(declaringNode);
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    GenericsDiagnostics.NotGeneric.Id.Value,
                                    DiagnosticSeverity.Error,
                                    $"Type '{argName}' is not generic and does not accept type arguments.",
                                    declaringNode,
                                    sourceText));
                                return resolvedType;
                            }

                            var nestedArgs = ResolveTypeArgumentList(namedRef.TypeArgs, declaringType, declaringNode, asts, compilation, diagnostics);
                            if(nestedArgs.Count != nestedTypeParams.Count)
                            {
                                var sourceText = GetSourceTextFromOrigin(declaringNode);
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    GenericsDiagnostics.ArityMismatch.Id.Value,
                                    DiagnosticSeverity.Error,
                                    $"Type '{argName}' expects {nestedTypeParams.Count} type argument(s) but received {nestedArgs.Count}.",
                                    declaringNode,
                                    sourceText));
                                return resolvedType;
                            }

                            return new ConstructedType(resolvedType, nestedArgs);
                        }

                        if(namedRef.ArrayRank is not null)
                        {
                            return new ArrayType(resolvedType);
                        }

                        return resolvedType;
                    }

                    // Type argument could not be resolved.
                    var srcText = GetSourceTextFromOrigin(declaringNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        GenericsDiagnostics.UndefinedTypeArgument.Id.Value,
                        DiagnosticSeverity.Error,
                        $"Type argument '{argName}' could not be resolved.",
                        declaringNode,
                        srcText));
                    return ErrorType.Instance;
                }

            case TupleSingleTypeRefSingleTypeRefNode tupleRef:
                {
                    // Collect all elements: First + Rest + TupleTypeElements (additional).
                    var elementCount = 2 + tupleRef.TupleTypeElements.Length;
                    var elementTypes = new List<IType>(elementCount);
                    var elementNames = new List<string?>(elementCount);
                    var hasAnyName = false;

                    // Resolve First element.
                    elementTypes.Add(ResolveTypeArgFromTypeReference(tupleRef.First.Type, declaringType, declaringNode, asts, compilation, diagnostics));
                    var firstName = tupleRef.First.Name?.Lexeme;
                    elementNames.Add(firstName);
                    if(firstName is not null)
                    {
                        hasAnyName = true;
                    }

                    // Resolve Rest element.
                    elementTypes.Add(ResolveTypeArgFromTypeReference(tupleRef.Rest.Type, declaringType, declaringNode, asts, compilation, diagnostics));
                    var restName = tupleRef.Rest.Name?.Lexeme;
                    elementNames.Add(restName);
                    if(restName is not null)
                    {
                        hasAnyName = true;
                    }

                    // Resolve additional elements.
                    foreach(var additional in tupleRef.TupleTypeElements)
                    {
                        elementTypes.Add(ResolveTypeArgFromTypeReference(additional.Type, declaringType, declaringNode, asts, compilation, diagnostics));
                        var additionalName = additional.Name?.Lexeme;
                        elementNames.Add(additionalName);
                        if(additionalName is not null)
                        {
                            hasAnyName = true;
                        }
                    }

                    return new TupleType(elementTypes, hasAnyName ? elementNames : null);
                }

            default:
                return ErrorType.Instance;
        }
    }

    /// <summary>
    /// Gets the type parameters from a type (ClassType, StructType, or AbstractType).
    /// Returns an empty list for types that don't have type parameters.
    /// </summary>
    private static IReadOnlyList<IType> GetTypeParameters(IType type)
    {
        return type switch
        {
            ClassType ct => ct.TypeParameters,
            StructType st => st.TypeParameters,
            AbstractType it => it.TypeParameters,
            TypeAliasType at => at.TypeParameters,
            AssociatedTypeSlotType slot => slot.TypeParameters,
            DelegateType dt => dt.TypeParameters,
            _ => Array.Empty<IType>(),
        };
    }

    /// <summary>
    /// Gets the member scope from a type (ClassType, StructType, or AbstractType).
    /// Returns null for types that don't have a member scope.
    /// </summary>
    private static IScope? GetMemberScope(IType type)
    {
        return type switch
        {
            ClassType ct => ct.MemberScope,
            StructType st => st.MemberScope,
            AbstractType it => it.MemberScope,
            NewtypeType nt => nt.MemberScope,
            AssociatedTypeSlotType slot => slot.MemberScope,
            _ => null,
        };
    }

    /// <summary>
    /// Extracts the <see cref="SourceText"/> from a node's <see cref="Storm.Runtime.SyntaxNode.Origin"/>
    /// property. Returns <c>null</c> if the origin is not a <see cref="ParsedOrigin"/> or is null.
    /// </summary>
    private static SourceText? GetSourceTextFromOrigin(Storm.Runtime.SyntaxNode node)
    {
        return node.Origin is ParsedOrigin po ? po.Source : null;
    }

    /// <summary>
    /// Extracts the <see cref="SourceText"/> for a symbol by looking up its declaring
    /// node in the symbol table and reading the node's origin.
    /// </summary>
    private static SourceText? GetSourceTextForSymbol(ISymbol symbol, SymbolTable symbolTable)
    {
        var declaringNode = symbolTable.GetDeclaringNode(symbol);
        return declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null;
    }

    /// <summary>
    /// Finds the compilation unit path for a class declaration node by walking
    /// the ASTs to find which compilation unit contains the node.
    /// </summary>
    private static string? FindCompilationUnitPath(
        TypeBodyDeclarationNode classDecl,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is CompilationUnitNode cu && ContainsClassDeclaration(cu, classDecl))
            {
                return i < compilation.Units.Length ? compilation.Units[i].Source?.Path : null;
            }
        }

        return null;
    }

    /// <summary>
    /// Checks whether a compilation unit contains the given class declaration.
    /// </summary>
    private static bool ContainsClassDeclaration(CompilationUnitNode cu, TypeBodyDeclarationNode classDecl)
    {
        foreach(var item in cu.Items)
        {
            switch(item)
            {
                case TypeItemTopLevelItemNode typeItem:
                    if(typeItem.TypeDeclaration is BodyTypeTypeDeclarationNode ct && ReferenceEquals(ct.TypeBody, classDecl))
                    {
                        return true;
                    }

                    break;
                case NamespaceItemTopLevelItemNode nsItem:
                    var namespaceTypes = GetNamespaceBodyTypes(nsItem.NamespaceDeclaration);
                    foreach(var typeDecl in namespaceTypes)
                    {
                        if(typeDecl is BodyTypeTypeDeclarationNode nsCt && ReferenceEquals(nsCt.TypeBody, classDecl))
                        {
                            return true;
                        }
                    }

                    break;
            }
        }

        return false;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1b (cont.) — Resolve abstract type lists on all types
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After all types are registered and base types are resolved, resolve
    /// abstract type lists on classes, structs, and abstract types.
    ///
    /// For classes: the first name in the base clause (<c>BaseClassName</c>)
    /// may be a base class (already resolved by <see cref="Pass1_ResolveBaseTypes"/>)
    /// or an abstract type. If it resolves to an <see cref="AbstractType"/>, it is
    /// treated as an abstract type (no base class). The class's <c>Abstracts</c>
    /// property is set accordingly.
    ///
    /// For structs: the first name in the abstract type list (<c>abstractName</c>)
    /// is resolved to an <see cref="AbstractType"/> and stored on
    /// <c>StructType.Abstracts</c>.
    ///
    /// For abstract types: the first name in the abstract type list (<c>abstractName</c>)
    /// is resolved to an <see cref="AbstractType"/> and stored on
    /// <c>AbstractType.Abstracts</c>.
    ///
    /// Emits <c>MIST_UNDEFINED_ABSTRACT</c> when an abstract type name is not found,
    /// and <c>MIST_NOT_AN_ABSTRACT</c> when a name resolves to a class or struct.
    /// </summary>
    private static void Pass1_ResolveAbstractLists(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            switch(symbol.Kind)
            {
                case SymbolKind.Class when symbol.DeclaredType is ClassType classType:
                    ResolveClassAbstractList(symbol, classType, symbolTable, asts, globalScope, compilation, diagnostics, ambientTypeResolver);
                    break;

                case SymbolKind.Struct when symbol.DeclaredType is StructType structType:
                    ResolveStructAbstractList(symbol, structType, symbolTable, asts, globalScope, compilation, diagnostics, ambientTypeResolver);
                    break;

                case SymbolKind.Abstract when symbol.DeclaredType is AbstractType abstractType:
                    ResolveAbstractParentList(symbol, abstractType, symbolTable, asts, globalScope, compilation, diagnostics, ambientTypeResolver);
                    break;
            }
        }
    }

    /// <summary>
    /// Resolves the abstract type list for a class declaration.
    /// The first name in the base clause (<c>BaseClassName</c>) may be a base class
    /// or an abstract type. If Pass1_ResolveBaseTypes already set <c>BaseType</c>, the
    /// first name is a base class and is skipped here. If <c>BaseType</c> is null
    /// and the base clause is present, the first name is checked as an abstract type.
    /// </summary>
    private static void ResolveClassAbstractList(
        ISymbol classSymbol,
        ClassType classType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        var declaringNode = symbolTable.GetDeclaringNode(classSymbol);
        if(declaringNode is not TypeBodyDeclarationNode classDecl)
        {
            return;
        }

        // No base clause means no base class and no abstract types.
        if(classDecl.BaseList is null)
        {
            return;
        }

        // Collect all BaseTypeRefNode entries from the base list.
        var allEntries = new List<BaseTypeRefNode>
        {
            classDecl.BaseList.First
        };
        foreach(var rest in classDecl.BaseList.BaseTypeRefs)
        {
            allEntries.Add(rest);
        }

        // If Pass1_ResolveBaseTypes already resolved a base class, the first
        // entry was consumed as the base class. Start from the second entry.
        var startIndex = classType.BaseType is not null ? 1 : 0;

        if(startIndex == 0)
        {
            // The first name was NOT resolved as a base class. Check if it's an abstract type.
            var firstName = allEntries[0].Name.Lexeme;
            if(string.IsNullOrEmpty(firstName))
            {
                return;
            }

            var parentScope = classSymbol.ContainingScope;
            var resolvedSymbol = LookupWithUsings(
                firstName, parentScope, classDecl, asts, globalScope, symbolTable, compilation, ambientTypeResolver);

            if(resolvedSymbol is null)
            {
                // Already reported as MIST_UNDEFINED_BASE_TYPE by Pass1_ResolveBaseTypes. Skip.
                startIndex = 1;
            }
            else if(resolvedSymbol.DeclaredType is AbstractType resolvedAbstract)
            {
                var typeArgs = allEntries[0].TypeArgs;
                var resolvedType = ResolveGenericTypeReference(
                    resolvedAbstract, typeArgs, firstName,
                    classType, classDecl, asts, compilation, diagnostics);
                classType.Abstracts = new List<IType> { resolvedType };
                startIndex = 1;
            }
            else if(UnwrapTypeForwards(resolvedSymbol.DeclaredType) is AbstractType unwrappedAbstract)
            {
                // The first entry is a type alias or newtype wrapping an AbstractType.
                var typeArgs = allEntries[0].TypeArgs;
                var resolvedType = ResolveGenericTypeReference(
                    unwrappedAbstract, typeArgs, firstName,
                    classType, classDecl, asts, compilation, diagnostics);
                classType.Abstracts = new List<IType> { resolvedType };
                startIndex = 1;
            }
            else if(resolvedSymbol.DeclaredType is StructType ||
                     UnwrapTypeForwards(resolvedSymbol.DeclaredType) is StructType)
            {
                // Already reported as MIST_CANNOT_INHERIT_STRUCT by Pass1_ResolveBaseTypes.
                startIndex = 1;
            }
            else if(resolvedSymbol.DeclaredType is UnknownType)
            {
                // Already reported by Pass1_ResolveBaseTypes' defensive
                // UnknownType guard (Requirements 6.1, 16.6). Skip the
                // first entry so it is not additionally reported here.
                startIndex = 1;
            }
            else
            {
                // Resolved to a ClassType but BaseType is null (shouldn't happen normally).
                startIndex = 1;
            }
        }

        // Resolve remaining entries as abstract types.
        if(startIndex < allEntries.Count)
        {
            var parentScope = classSymbol.ContainingScope;
            var additionalAbstracts = ResolveAbstractEntries(
                allEntries.Skip(startIndex),
                parentScope,
                classType,
                classDecl,
                symbolTable, asts, globalScope, compilation, diagnostics,
                findPathForSymbol: classSymbol,
                ambientTypeResolver: ambientTypeResolver);

            if(additionalAbstracts.Count > 0)
            {
                var existing = classType.Abstracts.ToList();
                existing.AddRange(additionalAbstracts);
                classType.Abstracts = existing;
            }
        }
    }

    /// <summary>
    /// Resolves the abstract type list for a struct declaration.
    /// If <see cref="StructType.BaseType"/> is already set (consumed by
    /// <c>Pass1_ResolveStructBaseTypes</c>), the first entry is skipped.
    /// Any additional struct types in the remaining entries emit
    /// <c>MIST_STRUCT_MULTIPLE_INHERITANCE</c>.
    /// </summary>
    private static void ResolveStructAbstractList(
        ISymbol structSymbol,
        StructType structType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        var declaringNode = symbolTable.GetDeclaringNode(structSymbol);
        if(declaringNode is not TypeBodyDeclarationNode structDecl)
        {
            return;
        }

        if(structDecl.BaseList is null)
        {
            return;
        }

        var entries = ExtractBaseListEntries(structDecl.BaseList);
        if(entries.Count == 0)
        {
            return;
        }

        // If Pass1_ResolveStructBaseTypes consumed the first entry as a base struct, skip it.
        var startIndex = structType.BaseType is not null ? 1 : 0;

        // Check remaining entries for additional struct types and emit an error if found.
        var parentScope = structSymbol.ContainingScope;
        for(var i = startIndex; i < entries.Count; i++)
        {
            var name = entries[i].Name.Lexeme;
            if(string.IsNullOrEmpty(name))
            {
                continue;
            }

            var resolvedSymbol = LookupWithUsings(
                name, parentScope, structDecl, asts, globalScope, symbolTable, compilation, ambientTypeResolver);
            if(resolvedSymbol?.DeclaredType is StructType ||
                UnwrapTypeForwards(resolvedSymbol?.DeclaredType) is StructType)
            {
                var sourceText = GetSourceTextForSymbol(structSymbol, symbolTable);
                diagnostics.Add(MakeDiagnosticWithLocation(
                    StructMultipleInheritance.Value,
                    DiagnosticSeverity.Error,
                    $"Struct '{structType.DisplayName}' cannot inherit from multiple structs. Only single struct inheritance is supported.",
                    structDecl,
                    sourceText));
                continue;
            }
        }

        // Resolve remaining entries as abstracts (existing logic).
        var abstractEntries = entries.Skip(startIndex);
        var resolvedAbstracts = ResolveAbstractEntries(
            abstractEntries,
            parentScope,
            structType,
            structDecl,
            symbolTable, asts, globalScope, compilation, diagnostics,
            findPathForSymbol: structSymbol,
            ambientTypeResolver: ambientTypeResolver);

        if(resolvedAbstracts.Count > 0)
        {
            structType.Abstracts = resolvedAbstracts;
        }
    }

    /// <summary>
    /// Resolves the abstract type list for an abstract type declaration.
    /// </summary>
    private static void ResolveAbstractParentList(
        ISymbol abstractSymbol,
        AbstractType abstractType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        var declaringNode = symbolTable.GetDeclaringNode(abstractSymbol);
        if(declaringNode is not TypeBodyDeclarationNode abstractDecl)
        {
            return;
        }

        if(abstractDecl.BaseList is null)
        {
            return;
        }

        var entries = ExtractBaseListEntries(abstractDecl.BaseList);
        if(entries.Count == 0)
        {
            return;
        }

        var parentScope = abstractSymbol.ContainingScope;
        var resolvedAbstracts = ResolveAbstractEntries(
            entries,
            parentScope,
            abstractType,
            abstractDecl,
            symbolTable, asts, globalScope, compilation, diagnostics,
            findPathForSymbol: abstractSymbol,
            ambientTypeResolver: ambientTypeResolver);

        if(resolvedAbstracts.Count > 0)
        {
            abstractType.Abstracts = resolvedAbstracts;
        }
    }

    /// <summary>
    /// Resolves a set of <see cref="BaseTypeRefNode"/> entries to abstract types,
    /// handling type arguments to produce <see cref="ConstructedType"/> when appropriate.
    /// Emits diagnostics for undefined names and non-abstract types.
    /// </summary>
    private static List<IType> ResolveAbstractEntries(
        IEnumerable<BaseTypeRefNode> entries,
        IScope parentScope,
        IType declaringType,
        Storm.Runtime.SyntaxNode declaringNode,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        ISymbol findPathForSymbol,
        IAmbientTypeResolver? ambientTypeResolver = null)
    {
        var resolved = new List<IType>();

        foreach(var entry in entries)
        {
            var name = entry.Name.Lexeme;
            if(string.IsNullOrEmpty(name))
            {
                continue;
            }

            var resolvedSymbol = LookupWithUsings(
                name, parentScope, declaringNode, asts, globalScope, symbolTable, compilation, ambientTypeResolver);

            if(resolvedSymbol is null)
            {
                var sourceText = GetSourceTextForSymbol(
                    findPathForSymbol, symbolTable);
                var declNode = symbolTable.GetDeclaringNode(findPathForSymbol);

                if(declNode is not null)
                {
                    LinePositionSpan undefinedAbstractLocation = default;
                    var undefinedAbstractPath = sourceText?.Path ?? "<unknown>";
                    if(sourceText is not null && declNode.Span.Length > 0)
                    {
                        var mistSpan = new SourceSpan(declNode.Span.Start, declNode.Span.Length);
                        undefinedAbstractLocation = sourceText.ToLinePositionSpan(mistSpan);
                    }

                    diagnostics.Report(SemanticDiagnostics.UndefinedAbstract, undefinedAbstractLocation, undefinedAbstractPath, (object)name);
                }
                else
                {
                    var compilationUnitPath = FindCompilationUnitPathForSymbol(
                        findPathForSymbol, symbolTable, asts, compilation);

                    diagnostics.Report(SemanticDiagnostics.UndefinedAbstract, default, compilationUnitPath ?? "<unknown>", (object)name);
                }

                continue;
            }

            if(resolvedSymbol.DeclaredType is AbstractType resolvedAbstract)
            {
                var resolvedType = ResolveGenericTypeReference(
                    resolvedAbstract, entry.TypeArgs, name,
                    declaringType, declaringNode, asts, compilation, diagnostics);
                resolved.Add(resolvedType);
            }
            else if(UnwrapTypeForwards(resolvedSymbol.DeclaredType) is AbstractType unwrappedAbstract)
            {
                // The entry is a type alias or newtype wrapping an AbstractType.
                var resolvedType = ResolveGenericTypeReference(
                    unwrappedAbstract, entry.TypeArgs, name,
                    declaringType, declaringNode, asts, compilation, diagnostics);
                resolved.Add(resolvedType);
            }
            else if(resolvedSymbol.DeclaredType is UnknownType)
            {
                // Defensive guard (Requirements 6.2, 6.3, 16.6). The
                // grammar prevents `unknown` from appearing as the name
                // of a `BaseTypeRef` because `unknown` lexes to the
                // reserved `UNKNOWN` token rather than `IDENTIFIER`, so
                // no parsed struct abstract type list or abstract type base
                // list can land here. The branch is retained so the
                // rule is complete for programmatically-constructed
                // ASTs and for documentation alignment with Req 6.2–6.3.
                // The reference is dropped by simply not appending it to
                // `resolved`.
                var sourceText = GetSourceTextForSymbol(
                    findPathForSymbol, symbolTable);
                var declNode = symbolTable.GetDeclaringNode(findPathForSymbol);

                if(declNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        UnknownAsBaseType.Value,
                        DiagnosticSeverity.Error,
                        $"'{declaringType.DisplayName}' cannot reference 'unknown' as a base or implemented type. " +
                        "'unknown' is the user-facing top type and does not participate in inheritance.",
                        declNode,
                        sourceText));
                }
                else
                {
                    var compilationUnitPath = FindCompilationUnitPathForSymbol(
                        findPathForSymbol, symbolTable, asts, compilation);

                    diagnostics.Add(new Diagnostic(
                        UnknownAsBaseType,
                        DiagnosticSeverity.Error,
                        PipelineStage.SemanticModelConstruction,
                        $"'{declaringType.DisplayName}' cannot reference 'unknown' as a base or implemented type. " +
                        "'unknown' is the user-facing top type and does not participate in inheritance.",
                        Location: default,
                        CompilationUnitPath: compilationUnitPath ?? "<unknown>",
                        AnalyzerName: null));
                }
            }
            else
            {
                var sourceText = GetSourceTextForSymbol(
                    findPathForSymbol, symbolTable);
                var declNode = symbolTable.GetDeclaringNode(findPathForSymbol);

                if(declNode is not null)
                {
                    LinePositionSpan notAbstractLocation = default;
                    var notAbstractPath = sourceText?.Path ?? "<unknown>";
                    if(sourceText is not null && declNode.Span.Length > 0)
                    {
                        var mistSpan = new SourceSpan(declNode.Span.Start, declNode.Span.Length);
                        notAbstractLocation = sourceText.ToLinePositionSpan(mistSpan);
                    }

                    diagnostics.Report(SemanticDiagnostics.NotAnAbstract, notAbstractLocation, notAbstractPath, (object)name);
                }
                else
                {
                    var compilationUnitPath = FindCompilationUnitPathForSymbol(
                        findPathForSymbol, symbolTable, asts, compilation);

                    diagnostics.Report(SemanticDiagnostics.NotAnAbstract, default, compilationUnitPath ?? "<unknown>", (object)name);
                }
            }
        }

        return resolved;
    }

    /// <summary>
    /// Extracts all <see cref="BaseTypeRefNode"/> entries from a <see cref="BaseListNode"/>.
    /// </summary>
    private static List<BaseTypeRefNode> ExtractBaseListEntries(BaseListNode baseList)
    {
        var entries = new List<BaseTypeRefNode>
        {
            baseList.First
        };
        foreach(var rest in baseList.BaseTypeRefs)
        {
            entries.Add(rest);
        }

        return entries;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // Pass 1b (cont.): Constraint Resolution
    // ═══════════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves constraint clauses on all type and method declarations.
    /// For each declaration with constraint clauses:
    ///   1. Validates the <c>where</c> clause references a valid type parameter name.
    ///   2. Checks for duplicate <c>where</c> clauses on the same type parameter.
    ///   3. Resolves each constraint (class, struct, new(...), type reference).
    ///   4. Stores the resulting <see cref="TypeParameterConstraints"/> on the
    ///      <see cref="TypeParameterType.Constraints"/> property.
    /// Adhoc refinement constraints are skipped here and processed in
    /// <see cref="Pass2_ResolveAdhocRefinementConstraints"/> after parameter
    /// symbols are registered.
    /// </summary>
    private static void Pass1_ResolveConstraints(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is null)
            {
                continue;
            }

            // Get the constraint clauses and type parameters for this declaration.
            var (constraintClauses, typeParameters) = GetConstraintClausesAndTypeParams(symbol, declaringNode);
            if(constraintClauses.IsDefaultOrEmpty || typeParameters.Count == 0)
            {
                continue;
            }

            var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                ?? GetSourceTextFromOrigin(declaringNode);
            var declaringName = symbol.Name;

            // Track which type parameters have already been constrained to detect duplicates.
            var constrainedParams = new Dictionary<string, bool>();

            foreach(var clause in constraintClauses)
            {
                // Only process generic constraint clauses in this pass.
                // AdhocRefinementConstraintWhereClauseNode is processed in
                // Pass2_ResolveAdhocRefinementConstraints after parameter symbols exist.
                if(clause is not GenericConstraintClauseWhereClauseNode genericClause)
                {
                    continue;
                }

                var typeParamName = genericClause.Name.Lexeme;

                // Validate the type parameter name exists on this declaration.
                var typeParam = FindTypeParameter(typeParameters, typeParamName);
                if(typeParam is null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        ConstraintUndefinedTypeParam.Value,
                        DiagnosticSeverity.Error,
                        $"Type parameter '{typeParamName}' is not defined on '{declaringName}'.",
                        genericClause,
                        sourceText));
                    continue;
                }

                // Check for duplicate where clauses on the same type parameter.
                if(constrainedParams.ContainsKey(typeParamName))
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        ConstraintDuplicateWhereClause.Value,
                        DiagnosticSeverity.Error,
                        $"Type parameter '{typeParamName}' cannot have multiple 'where' clauses. Combine constraints in a single clause.",
                        genericClause,
                        sourceText));
                    continue;
                }

                constrainedParams[typeParamName] = true;

                // Resolve the constraints in this clause.
                var constraints = ResolveConstraintClause(
                    genericClause, typeParam, symbol, declaringNode, symbolTable, asts, compilation, diagnostics, sourceText);

                // Store the resolved constraints on the type parameter.
                typeParam.Constraints = constraints;
            }
        }

        // Resolve constraint lists on associated type slot declarations.
        // The slot's main constraint list (after ':') defines what the concrete
        // type must satisfy. This is stored on AssociatedTypeSlotType.Constraints.
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.DeclaredType is not AssociatedTypeSlotType slotType)
            {
                continue;
            }

            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is not AssociatedTypeSlotDeclarationNode slotDecl)
            {
                continue;
            }

            // Only resolve constraints if the constraint clause is present.
            if(slotDecl.Constraints is null)
            {
                continue;
            }

            var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                ?? GetSourceTextFromOrigin(declaringNode);

            var resolvedConstraints = ResolveAssociatedTypeSlotConstraintList(
                slotDecl.Constraints, symbol, declaringNode, symbolTable, asts, compilation, diagnostics, sourceText);

            slotType.Constraints = resolvedConstraints;
        }
    }

    /// <summary>
    /// Resolves named type parameter constraints that were deferred during Pass 1.
    /// During Pass 1, <see cref="NamedConstraintDependentTypeParameterTypeParameterNode"/>
    /// nodes store the constraint name in <see cref="DependentTypeParameterType.PendingConstraintName"/>
    /// because type alias <c>DeclaredType</c> may not be resolved yet. After Pass 2 resolves
    /// type aliases, this method:
    ///   - Looks up the constraint name in the declaring type's containing scope (with usings).
    ///   - Validates it resolves to a <see cref="RefinementType"/>.
    ///   - Validates the base type is in <see cref="AllowedDependentTypeAnnotations"/>.
    ///   - Updates <see cref="DependentTypeParameterType.ValueType"/> and
    ///     <see cref="DependentTypeParameterType.RefinementConstraint"/>.
    ///   - Emits MIST_DT_0002 if the constraint cannot be found or is not a refinement type.
    ///   - Emits MIST_DT_0001 if the base type is not in the allowed set.
    /// </summary>
    private static void Pass2_ResolveNamedTypeParameterConstraints(
        SymbolTable symbolTable,
        Scope globalScope,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            // Get type parameters from the symbol's declared type.
            var typeParameters = symbol.DeclaredType switch
            {
                ClassType ct => ct.TypeParameters,
                StructType st => st.TypeParameters,
                AbstractType it => it.TypeParameters,
                _ => null,
            };

            if(typeParameters is null || typeParameters.Count == 0)
            {
                continue;
            }

            foreach(var tp in typeParameters)
            {
                if(tp is not DependentTypeParameterType depType)
                {
                    continue;
                }

                if(depType.PendingConstraintName is null)
                {
                    continue;
                }

                var constraintName = depType.PendingConstraintName;

                // Look up the constraint name in the type's containing scope.
                var containingScope = symbol.ContainingScope;
                var constraintSymbol = containingScope.Lookup(constraintName);

                // Also search via using directives by finding the declaring node
                // and using LookupWithUsings.
                if(constraintSymbol is null)
                {
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    if(declaringNode is not null)
                    {
                        constraintSymbol = LookupWithUsings(
                            constraintName, containingScope, declaringNode,
                            asts, globalScope, symbolTable, compilation);
                    }
                }

                if(constraintSymbol is null)
                {
                    // Constraint type not found — emit MIST_DT_0002.
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeConstraintNotFound.Value,
                            DiagnosticSeverity.Error,
                            $"Constraint type '{constraintName}' could not be found.",
                            declaringNode,
                            sourceText));
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            DependentTypeConstraintNotFound,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Constraint type '{constraintName}' could not be found.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    continue;
                }

                // Resolve to RefinementType — check DeclaredType.
                RefinementType? refinement = null;
                if(constraintSymbol.DeclaredType is RefinementType directRefinement)
                {
                    refinement = directRefinement;
                }
                else if(constraintSymbol.DeclaredType is TypeAliasType aliasType
                         && aliasType.UnderlyingType is RefinementType aliasRefinement)
                {
                    refinement = aliasRefinement;
                }

                if(refinement is null)
                {
                    // Constraint resolves but is not a refinement type — emit MIST_DT_0002.
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeConstraintNotFound.Value,
                            DiagnosticSeverity.Error,
                            $"Constraint '{constraintName}' must be a refinement type with a primitive base type.",
                            declaringNode,
                            sourceText));
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            DependentTypeConstraintNotFound,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Constraint '{constraintName}' must be a refinement type with a primitive base type.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    continue;
                }

                // Validate the base type is in AllowedDependentTypeAnnotations.
                var baseType = refinement.BaseType;
                var baseKeyword = GetKeywordForBaseType(baseType);

                if(!AllowedDependentTypeAnnotations.Contains(baseKeyword))
                {
                    // Base type not allowed — emit MIST_DT_0001.
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeDisallowedAnnotation.Value,
                            DiagnosticSeverity.Error,
                            $"Type '{baseKeyword}' (base type of '{constraintName}') cannot be used as a dependent type parameter. Only primitive integral types, bool, and char are allowed.",
                            declaringNode,
                            sourceText));
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            DependentTypeDisallowedAnnotation,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Type '{baseKeyword}' (base type of '{constraintName}') cannot be used as a dependent type parameter. Only primitive integral types, bool, and char are allowed.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    continue;
                }

                // Resolution succeeded — update the DependentTypeParameterType.
                depType.ValueType = baseType;
                depType.RefinementConstraint = refinement;
                depType.PendingConstraintName = null;
            }
        }

        // Also resolve named constraints on method type parameters.
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is not (SymbolKind.Method or SymbolKind.Constructor))
            {
                continue;
            }

            var methodTypeParams = (symbol as Symbol)?.TypeParameters;
            if(methodTypeParams is null || methodTypeParams.Count == 0)
            {
                continue;
            }

            foreach(var tp in methodTypeParams)
            {
                if(tp is not DependentTypeParameterType depType)
                {
                    continue;
                }

                if(depType.PendingConstraintName is null)
                {
                    continue;
                }

                var constraintName = depType.PendingConstraintName;
                var containingScope = symbol.ContainingScope;
                var constraintSymbol = containingScope.Lookup(constraintName);

                if(constraintSymbol is null)
                {
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    if(declaringNode is not null)
                    {
                        constraintSymbol = LookupWithUsings(
                            constraintName, containingScope, declaringNode,
                            asts, globalScope, symbolTable, compilation);
                    }
                }

                if(constraintSymbol is null)
                {
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeConstraintNotFound.Value,
                            DiagnosticSeverity.Error,
                            $"Constraint type '{constraintName}' could not be found.",
                            declaringNode,
                            sourceText));
                    }

                    continue;
                }

                RefinementType? refinement = null;
                if(constraintSymbol.DeclaredType is RefinementType directRefinement)
                {
                    refinement = directRefinement;
                }
                else if(constraintSymbol.DeclaredType is TypeAliasType aliasType
                         && aliasType.UnderlyingType is RefinementType aliasRefinement)
                {
                    refinement = aliasRefinement;
                }

                if(refinement is null)
                {
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeConstraintNotFound.Value,
                            DiagnosticSeverity.Error,
                            $"Constraint '{constraintName}' must be a refinement type with a primitive base type.",
                            declaringNode,
                            sourceText));
                    }

                    continue;
                }

                var baseType = refinement.BaseType;
                var baseKeyword = GetKeywordForBaseType(baseType);

                if(!AllowedDependentTypeAnnotations.Contains(baseKeyword))
                {
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                        ?? (declaringNode is not null ? GetSourceTextFromOrigin(declaringNode) : null);

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            DependentTypeDisallowedAnnotation.Value,
                            DiagnosticSeverity.Error,
                            $"Type '{baseKeyword}' (base type of '{constraintName}') cannot be used as a dependent type parameter. Only primitive integral types, bool, and char are allowed.",
                            declaringNode,
                            sourceText));
                    }

                    continue;
                }

                depType.ValueType = baseType;
                depType.RefinementConstraint = refinement;
                depType.PendingConstraintName = null;
            }
        }
    }

    /// <summary>
    /// Fixes up <see cref="DependentValueArgument"/> instances that were created during Pass 2
    /// with <see cref="ErrorType"/> as their <c>ValueType</c>. This happens because named-constraint
    /// dependent parameters (e.g., <c>Count:PositiveInt</c>) have <c>ErrorType</c> as a placeholder
    /// during Pass 2 and are resolved after. This method patches those arguments by looking at the
    /// declaring type's resolved <see cref="DependentTypeParameterType.ValueType"/>.
    /// </summary>
    private static void FixUpDependentValueArguments(
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes)
    {
        // Fix DependentValueArguments in expression types.
        foreach(var (_, type) in expressionTypes)
        {
            FixUpDependentArgsInType(type);
        }

        // Fix DependentValueArguments in symbol declared types (e.g., base types, abstracts).
        foreach(var symbol in symbolTable.AllSymbols)
        {
            FixUpDependentArgsInType(symbol.DeclaredType);

            if(symbol.DeclaredType is ClassType ct)
            {
                FixUpDependentArgsInType(ct.BaseType);
                foreach(var iface in ct.Abstracts)
                {
                    FixUpDependentArgsInType(iface);
                }

                foreach(var member in ct.MemberScope.Members)
                {
                    FixUpDependentArgsInType(member.DeclaredType);
                }
            }
            else if(symbol.DeclaredType is StructType st)
            {
                foreach(var iface in st.Abstracts)
                {
                    FixUpDependentArgsInType(iface);
                }

                foreach(var member in st.MemberScope.Members)
                {
                    FixUpDependentArgsInType(member.DeclaredType);
                }
            }
        }
    }

    /// <summary>
    /// If the type is a <see cref="ConstructedType"/> with <see cref="ConstructedType.DependentArguments"/>,
    /// patches any argument whose <c>ValueType</c> is <see cref="ErrorType"/> by resolving the correct
    /// value type from the generic definition's type parameters.
    /// </summary>
    private static void FixUpDependentArgsInType(IType? type)
    {
        if(type is not ConstructedType ct)
        {
            return;
        }

        if(ct.DependentArguments is null)
        {
            return;
        }

        // Get the type parameters from the generic definition.
        var typeParams = GetTypeParametersForType(ct.GenericDefinition);
        if(typeParams is null)
        {
            return;
        }

        for(var i = 0; i < ct.DependentArguments.Count; i++)
        {
            var depArg = ct.DependentArguments[i];
            if(depArg is null)
            {
                continue;
            }

            if(depArg.ValueType is not ErrorType)
            {
                continue;
            }

            // The corresponding type parameter should now have the resolved ValueType.
            if(i < typeParams.Count && typeParams[i] is DependentTypeParameterType depParam
                && depParam.ValueType is not ErrorType)
            {
                depArg.ValueType = depParam.ValueType;
            }
        }
    }

    private static IReadOnlyList<IType>? GetTypeParametersForType(IType? type)
    {
        return type switch
        {
            ClassType ct => ct.TypeParameters,
            StructType st => st.TypeParameters,
            AbstractType it => it.TypeParameters,
            _ => null,
        };
    }

    /// <summary>
    /// Resolves adhoc refinement constraint clauses on all declarations after Pass 2
    /// has registered parameter symbols. For each <see cref="AdhocRefinementConstraintWhereClauseNode"/>:
    ///   - Looks up the name in dependent type parameters → attaches predicate to
    ///     <see cref="DependentTypeParameterType.AdhocConstraint"/>.
    ///   - Looks up the name in value parameters → stores in parameter refinement map.
    ///   - Emits MIST_REFINEMENT_0001 if name not found.
    ///   - Emits MIST_REFINEMENT_0002 if name is a regular type parameter.
    ///   - Emits MIST_REFINEMENT_0003 if duplicate.
    /// </summary>
    private static void Pass2_ResolveAdhocRefinementConstraints(
        SymbolTable symbolTable,

        DiagnosticBag diagnostics,
        Dictionary<ISymbol, RefinementPredicate> parameterRefinements)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is null)
            {
                continue;
            }

            // Get the constraint clauses and type parameters for this declaration.
            var (constraintClauses, typeParameters) = GetConstraintClausesAndTypeParams(symbol, declaringNode);
            if(constraintClauses.IsDefaultOrEmpty)
            {
                continue;
            }

            // Check if there are any adhoc refinement constraints to process.
            var hasAdhocClauses = false;
            foreach(var clause in constraintClauses)
            {
                if(clause is AdhocRefinementConstraintWhereClauseNode)
                {
                    hasAdhocClauses = true;
                    break;
                }
            }

            if(!hasAdhocClauses)
            {
                continue;
            }

            var sourceText = GetSourceTextForSymbol(symbol, symbolTable)
                ?? GetSourceTextFromOrigin(declaringNode);

            // Track which names have already been refined to detect duplicate adhoc constraints.
            var refinedNames = new Dictionary<string, bool>();

            foreach(var clause in constraintClauses)
            {
                if(clause is not AdhocRefinementConstraintWhereClauseNode refinementClause)
                {
                    continue;
                }

                ResolveAdhocRefinementConstraint(
                    refinementClause, declaringNode, typeParameters,
                    refinedNames, parameterRefinements, symbolTable, sourceText, diagnostics);
            }
        }
    }

    /// <summary>
    /// Validates refinement constraint satisfaction for abstract type method
    /// implementations (Liskov Substitution Principle). For each matched method pair,
    /// checks that the implementation does not impose a stronger refinement constraint
    /// on any parameter than the abstract type method requires.
    /// </summary>
    /// <remarks>
    /// This runs after <see cref="Pass2_ResolveAdhocRefinementConstraints"/> so that
    /// parameter refinement predicates are available for both abstract type methods
    /// and their implementations.
    ///
    /// Algorithm per parameter position:
    /// - If abstract type predicate is null → skip (implementation may freely add or omit constraints)
    /// - If abstract type predicate is non-null and impl predicate is null → accept (no constraint means accepts all values)
    /// - If both are non-null → check RefinementSolver.Implies(abstractPredicate, implPredicate):
    ///   - If true → accept
    ///   - If false → emit MIST_REFINEMENT_0009 diagnostic
    /// </remarks>
    private static void Pass2_ValidateRefinementConstraintSatisfaction(
        SymbolTable symbolTable,
        Dictionary<ISymbol, RefinementPredicate> parameterRefinements,

        DiagnosticBag diagnostics)
    {
        // ─── abstract type method refinement constraint satisfaction ─────────
        foreach(var symbol in symbolTable.AllSymbols)
        {
            IReadOnlyList<IType>? abstracts = null;
            IScope? memberScope = null;
            ClassType? classType = null;
            string? typeName = null;

            switch(symbol.Kind)
            {
                case SymbolKind.Class when symbol.DeclaredType is ClassType ct:
                    if(ct.Abstracts.Count > 0)
                    {
                        abstracts = ct.Abstracts;
                        memberScope = ct.MemberScope;
                        classType = ct;
                        typeName = ct.DisplayName;
                    }

                    break;

                case SymbolKind.Struct when symbol.DeclaredType is StructType st:
                    if(st.Abstracts.Count > 0)
                    {
                        abstracts = st.Abstracts;
                        memberScope = st.MemberScope;
                        typeName = st.DisplayName;
                    }

                    break;
            }

            if(abstracts is null || memberScope is null || typeName is null)
            {
                continue;
            }

            // Collect all required methods transitively from the abstract type hierarchy.
            var requiredMethods = new List<(AbstractType Abstract, ISymbol Method)>();
            var requiredProperties = new List<(AbstractType Abstract, ISymbol Property)>();
            var visitedAbstracts = new HashSet<AbstractType>();
            CollectRequiredMembers(abstracts, requiredMethods, requiredProperties, visitedAbstracts);

            foreach(var (requiredAbstract, requiredMethod) in requiredMethods)
            {
                var requiredNode = symbolTable.GetDeclaringNode(requiredMethod);
                if(requiredNode is not MethodDeclarationNode requiredMethodDecl)
                {
                    continue;
                }

                // Find the matching implementation method.
                var matchResult = FindMatchingMethod(
                    requiredMethod.Name, requiredMethodDecl,
                    memberScope, classType, symbolTable);

                if(matchResult is not MethodMatchResult.MatchedResult matched)
                {
                    continue;
                }

                // Validate refinement constraints for each parameter position.
                ValidateMethodRefinementConstraints(
                    requiredMethod, matched.ImplSymbol,
                    requiredAbstract.DisplayName, typeName,
                    parameterRefinements, symbolTable, diagnostics);
            }
        }
    }

    /// <summary>
    /// Validates refinement constraint compatibility between an abstract type method
    /// and its implementation for each parameter position.
    /// </summary>
    private static void ValidateMethodRefinementConstraints(
        ISymbol abstractMethod,
        ISymbol implMethod,
        string abstractName,
        string typeName,
        Dictionary<ISymbol, RefinementPredicate> parameterRefinements,
        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        // Get parameter nodes from both methods.
        var abstractNode = symbolTable.GetDeclaringNode(abstractMethod);
        var implNode = symbolTable.GetDeclaringNode(implMethod);

        if(abstractNode is null || implNode is null)
        {
            return;
        }

        var abstractParams = abstractNode switch
        {
            MethodDeclarationNode methodDecl => methodDecl.Parameters,
            _ => null,
        };

        var implParams = implNode switch
        {
            MethodDeclarationNode methodDecl => methodDecl.Parameters,
            _ => null,
        };

        if(abstractParams is null || implParams is null)
        {
            return;
        }

        // Collect parameter nodes from both methods.
        var abstractParamNodes = new List<ParameterNode>();
        foreach(var child in abstractParams.Children())
        {
            if(child is ParameterNode param)
            {
                abstractParamNodes.Add(param);
            }
        }

        var implParamNodes = new List<ParameterNode>();
        foreach(var child in implParams.Children())
        {
            if(child is ParameterNode param)
            {
                implParamNodes.Add(param);
            }
        }

        // Validate each parameter position independently.
        var count = Math.Min(abstractParamNodes.Count, implParamNodes.Count);
        for(var i = 0; i < count; i++)
        {
            var abstractParamSymbol = symbolTable.GetDeclaredSymbol(abstractParamNodes[i]);
            var implParamSymbol = symbolTable.GetDeclaredSymbol(implParamNodes[i]);

            if(abstractParamSymbol is null || implParamSymbol is null)
            {
                continue;
            }

            // Look up refinement predicates.
            _ = parameterRefinements.TryGetValue(abstractParamSymbol, out var abstractPredicate);
            _ = parameterRefinements.TryGetValue(implParamSymbol, out var implPredicate);

            // If abstract type predicate is null → skip (implementation may freely add or omit constraints).
            if(abstractPredicate is null)
            {
                continue;
            }

            // If abstract type predicate is non-null and impl predicate is null → accept
            // (no constraint means accepts all values).
            if(implPredicate is null)
            {
                continue;
            }

            // Both are non-null → check implication.
            if(!RefinementSolver.Implies(abstractPredicate, implPredicate))
            {
                // The implementation's constraint is stronger — emit MIST_REFINEMENT_0009.
                var paramName = implParamNodes[i].Name.Lexeme;
                var methodName = implMethod.Name;

                var message = $"Implementation of '{methodName}' on '{typeName}' has a stronger refinement constraint '{implPredicate}' on parameter '{paramName}' than the abstract type '{abstractName}' requires '{abstractPredicate}'. The implementation must accept all values the abstract type promises to accept.";

                // Get source location from the implementation method.
                var sourceText = FindSourceTextForType(typeName, symbolTable);
                diagnostics.Add(MakeDiagnosticWithLocation(
                    RefinementConstraintStrongerThanAbstract.Value,
                    DiagnosticSeverity.Error,
                    message,
                    implNode,
                    sourceText));
            }
        }
    }

    /// <summary>
    /// Extracts constraint clauses and type parameters from a symbol's declaring node.
    /// Returns empty/default values for declarations that don't support constraints.
    /// </summary>
    private static (ImmutableArray<WhereClauseNode> Clauses, IReadOnlyList<IType> TypeParams) GetConstraintClausesAndTypeParams(
        ISymbol symbol,
        Storm.Runtime.SyntaxNode declaringNode)
    {
        return declaringNode switch
        {
            TypeBodyDeclarationNode typeBodyDecl when symbol.DeclaredType is ClassType classType => (typeBodyDecl.Constraints, classType.TypeParameters),
            TypeBodyDeclarationNode typeBodyDecl when symbol.DeclaredType is StructType structType => (typeBodyDecl.Constraints, structType.TypeParameters),
            TypeBodyDeclarationNode typeBodyDecl when symbol.DeclaredType is AbstractType abstractType => (typeBodyDecl.Constraints, abstractType.TypeParameters),
            MethodDeclarationNode methodDecl when symbol is Symbol methodSymbol => (methodDecl.Constraints, methodSymbol.TypeParameters),
            TypeAliasDeclarationNode aliasDecl when symbol is Symbol aliasSymbol => (aliasDecl.Constraints, aliasSymbol.TypeParameters),
            ConstructorDeclarationNode ctorDecl => ((ImmutableArray<WhereClauseNode> Clauses, IReadOnlyList<IType> TypeParams))(ctorDecl.Constraints, Array.Empty<IType>()),
            IndexerDeclarationNode indexerDecl2 => ((ImmutableArray<WhereClauseNode> Clauses, IReadOnlyList<IType> TypeParams))(indexerDecl2.Constraints, Array.Empty<IType>()),
            AssociatedTypeSlotDeclarationNode slotDecl when symbol is Symbol slotSymbol && slotDecl.Constraints is not null => (slotDecl.SlotWhereConstraints, slotSymbol.TypeParameters),
            AssociatedTypeSlotDeclarationNode when symbol is Symbol slotSymbol2 => (ImmutableArray<WhereClauseNode>.Empty, slotSymbol2.TypeParameters),
            _ => ((ImmutableArray<WhereClauseNode> Clauses, IReadOnlyList<IType> TypeParams))(ImmutableArray<WhereClauseNode>.Empty, Array.Empty<IType>()),
        };
    }

    /// <summary>
    /// Finds a type parameter by name in the given list.
    /// </summary>
    private static TypeParameterType? FindTypeParameter(IReadOnlyList<IType> typeParameters, string name)
    {
        foreach(var tp in typeParameters)
        {
            if(tp is TypeParameterType tpt && tpt.Name == name)
            {
                return tpt;
            }
        }

        return null;
    }

    /// <summary>
    /// Resolves a single adhoc refinement constraint clause. Looks up the constrained
    /// name in dependent type parameters and value parameters, attaching the predicate
    /// or emitting diagnostics as appropriate.
    /// </summary>
    private static void ResolveAdhocRefinementConstraint(
        AdhocRefinementConstraintWhereClauseNode refinementClause,

        Storm.Runtime.SyntaxNode declaringNode,
        IReadOnlyList<IType> typeParameters,
        Dictionary<string, bool> refinedNames,
        Dictionary<ISymbol, RefinementPredicate> parameterRefinements,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var name = refinementClause.Name.Lexeme;

        // Check for duplicate refinement constraint on the same name.
        if(refinedNames.ContainsKey(name))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                RefinementConstraintDuplicate.Value,
                DiagnosticSeverity.Error,
                $"Duplicate refinement constraint on '{name}'. Combine predicates using 'and' in a single where clause.",
                refinementClause,
                sourceText));
            return;
        }

        // Check if the name is a regular type parameter (not dependent).
        var regularTypeParam = FindTypeParameter(typeParameters, name);
        if(regularTypeParam is not null)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                RefinementConstraintOnRegularTypeParam.Value,
                DiagnosticSeverity.Error,
                $"Refinement constraints cannot be applied to type parameter '{name}'. Refinement constraints apply only to dependent type parameters and value parameters.",
                refinementClause,
                sourceText));
            return;
        }

        // Check if the name is a dependent type parameter.
        var dependentParam = FindDependentTypeParameter(typeParameters, name);
        if(dependentParam is not null)
        {
            refinedNames[name] = true;
            dependentParam.AdhocConstraint = new RefinementPredicate(refinementClause.Predicate);
            return;
        }

        // Check if the name is a value parameter on the declaration.
        var valueParam = FindValueParameter(declaringNode, name, symbolTable);
        if(valueParam is not null)
        {
            refinedNames[name] = true;
            parameterRefinements[valueParam] = new RefinementPredicate(refinementClause.Predicate);
            return;
        }

        // Name not found — emit diagnostic.
        diagnostics.Add(MakeDiagnosticWithLocation(
            RefinementConstraintUnknownName.Value,
            DiagnosticSeverity.Error,
            $"Refinement constraint references '{name}', which is not a dependent type parameter or parameter on this declaration.",
            refinementClause,
            sourceText));
    }

    /// <summary>
    /// Finds a dependent type parameter by name in the given type parameter list.
    /// </summary>
    private static DependentTypeParameterType? FindDependentTypeParameter(IReadOnlyList<IType> typeParameters, string name)
    {
        foreach(var tp in typeParameters)
        {
            if(tp is DependentTypeParameterType dpt && dpt.Name == name)
            {
                return dpt;
            }
        }

        return null;
    }

    /// <summary>
    /// Finds a value parameter symbol by name on the given declaration.
    /// Searches method, constructor, and indexer parameter lists.
    /// </summary>
    private static ISymbol? FindValueParameter(

        Storm.Runtime.SyntaxNode declaringNode,
        string paramName,
        SymbolTable symbolTable)
    {
        // Get the parameter list node from the declaration.
        var paramList = declaringNode switch
        {
            MethodDeclarationNode methodDecl => methodDecl.Parameters,
            ConstructorDeclarationNode ctorDecl => ctorDecl.Parameters,
            IndexerDeclarationNode indexerDecl3 => indexerDecl3.Parameters,
            _ => null,
        };

        if(paramList is null)
        {
            return null;
        }

        // Walk the parameter list children to find the parameter by name.
        foreach(var child in paramList.Children())
        {
            if(child is ParameterNode param && param.Name.Lexeme == paramName)
            {
                // Look up the symbol registered for this parameter node.
                return symbolTable.GetDeclaredSymbol(param);
            }
        }

        return null;
    }

    /// <summary>
    /// Resolves all constraints in a single <c>where</c> clause and builds a
    /// <see cref="TypeParameterConstraints"/> instance.
    /// </summary>
    private static TypeParameterConstraints ResolveConstraintClause(
        GenericConstraintClauseWhereClauseNode clause,
        TypeParameterType typeParam,
        ISymbol declaringSymbol,
        Storm.Runtime.SyntaxNode declaringNode,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        var hasClassConstraint = false;
        var hasStructConstraint = false;
        var hasReadonlyConstraint = false;
        var hasMutableConstraint = false;
        var hasOwnedConstraint = false;
        var hasLinearConstraint = false;
        var hasAffineConstraint = false;
        var hasRelevantConstraint = false;
        var hasDefaultConstraint = false;
        IType? baseClassConstraint = null;
        var abstractConstraints = new List<IType>();
        var constructorConstraints = new List<IReadOnlyList<IType>>();

        // Track all base class constraints for validation (MIST_CONSTRAINT_0004).
        var baseClassConstraints = new List<IType>();
        // Track struct types used as type constraints (MIST_CONSTRAINT_0005).
        var structTypeConstraints = new List<IType>();

        // Collect all constraints from the clause (first + rest).
        var allConstraints = new List<ConstraintNode> { clause.Constraints.Constraint };
        allConstraints.AddRange(clause.Constraints.Constraints);

        foreach(var constraint in allConstraints)
        {
            switch(constraint)
            {
                case ClassConstraintConstraintNode:
                    hasClassConstraint = true;
                    break;

                case StructConstraintConstraintNode:
                    hasStructConstraint = true;
                    break;

                case ReadonlyConstraintConstraintNode:
                    hasReadonlyConstraint = true;
                    break;

                case MutableConstraintConstraintNode:
                    hasMutableConstraint = true;
                    break;

                case OwnedConstraintConstraintNode:
                    hasOwnedConstraint = true;
                    break;


                case LinearConstraintConstraintNode:
                    hasLinearConstraint = true;
                    break;

                case AffineConstraintConstraintNode:
                    hasAffineConstraint = true;
                    break;

                case RelevantConstraintConstraintNode:
                    hasRelevantConstraint = true;
                    break;
                case DefaultConstraintConstraintNode:
                    hasDefaultConstraint = true;
                    break;

                case ConstructorConstraintConstraintNode ctorConstraint:
                    {
                        var paramTypes = ResolveConstructorConstraintParams(
                            ctorConstraint, declaringSymbol, declaringNode, symbolTable, diagnostics, sourceText);
                        constructorConstraints.Add(paramTypes);
                        break;
                    }

                case TypeConstraintConstraintNode typeConstraint:
                    {
                        var resolvedType = ResolveConstraintTypeReference(
                            typeConstraint, declaringSymbol, declaringNode, asts, compilation, diagnostics, sourceText);

                        if(resolvedType is null or ErrorType)
                        {
                            // Already emitted MIST_CONSTRAINT_0008 in ResolveConstraintTypeReference.
                            break;
                        }

                        // Classify the resolved type, tracking base class and struct constraints.
                        ClassifyConstraintType(
                            resolvedType, ref baseClassConstraint,
                            abstractConstraints,
                            baseClassConstraints, structTypeConstraints);
                        break;
                    }
            }
        }

        // Validate constraint combinations after all constraints are resolved.
        ValidateConstraintCombinations(
            hasClassConstraint, hasStructConstraint,
            hasLinearConstraint, hasAffineConstraint, hasRelevantConstraint,
            baseClassConstraints, structTypeConstraints,
            constructorConstraints,
            typeParam, clause, sourceText, diagnostics);

        return new TypeParameterConstraints
        {
            HasClassConstraint = hasClassConstraint,
            HasStructConstraint = hasStructConstraint,
            BaseClassConstraint = baseClassConstraint,
            AbstractConstraints = abstractConstraints,
            ConstructorConstraints = constructorConstraints,
            HasReadonlyConstraint = hasReadonlyConstraint,
            HasMutableConstraint = hasMutableConstraint,
            HasOwnedConstraint = hasOwnedConstraint,
            HasLinearConstraint = hasLinearConstraint,
            HasAffineConstraint = hasAffineConstraint,
            HasRelevantConstraint = hasRelevantConstraint,
            HasDefaultConstraint = hasDefaultConstraint,
        };
    }

    /// <summary>
    /// Resolves the constraint list on an associated type slot declaration.
    /// This is the constraint list after ':' in <c>type Name : ConstraintList;</c>.
    /// Uses the same constraint resolution logic as <see cref="ResolveConstraintClause"/>
    /// but operates on a <see cref="ConstraintListNode"/> directly rather than a where clause.
    /// </summary>
    private static TypeParameterConstraints ResolveAssociatedTypeSlotConstraintList(
        ConstraintListNode constraintList,
        ISymbol declaringSymbol,
        Storm.Runtime.SyntaxNode declaringNode,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        var hasClassConstraint = false;
        var hasStructConstraint = false;
        var hasReadonlyConstraint = false;
        var hasMutableConstraint = false;
        var hasOwnedConstraint = false;
        var hasLinearConstraint = false;
        var hasAffineConstraint = false;
        var hasRelevantConstraint = false;
        var hasDefaultConstraint = false;
        IType? baseClassConstraint = null;
        var abstractConstraints = new List<IType>();
        var constructorConstraints = new List<IReadOnlyList<IType>>();

        // Track base class and struct constraints for validation.
        var baseClassConstraints = new List<IType>();
        var structTypeConstraints = new List<IType>();

        // Collect all constraints from the list (first + rest).
        var allConstraints = new List<ConstraintNode> { constraintList.Constraint };
        allConstraints.AddRange(constraintList.Constraints);

        foreach(var constraint in allConstraints)
        {
            switch(constraint)
            {
                case ClassConstraintConstraintNode:
                    hasClassConstraint = true;
                    break;

                case StructConstraintConstraintNode:
                    hasStructConstraint = true;
                    break;

                case ReadonlyConstraintConstraintNode:
                    hasReadonlyConstraint = true;
                    break;

                case MutableConstraintConstraintNode:
                    hasMutableConstraint = true;
                    break;

                case OwnedConstraintConstraintNode:
                    hasOwnedConstraint = true;
                    break;


                case LinearConstraintConstraintNode:
                    hasLinearConstraint = true;
                    break;

                case AffineConstraintConstraintNode:
                    hasAffineConstraint = true;
                    break;

                case RelevantConstraintConstraintNode:
                    hasRelevantConstraint = true;
                    break;
                case DefaultConstraintConstraintNode:
                    hasDefaultConstraint = true;
                    break;

                case ConstructorConstraintConstraintNode ctorConstraint:
                    {
                        var paramTypes = ResolveConstructorConstraintParams(
                            ctorConstraint, declaringSymbol, declaringNode, symbolTable, diagnostics, sourceText);
                        constructorConstraints.Add(paramTypes);
                        break;
                    }

                case TypeConstraintConstraintNode typeConstraint:
                    {
                        var resolvedType = ResolveConstraintTypeReference(
                            typeConstraint, declaringSymbol, declaringNode, asts, compilation, diagnostics, sourceText);

                        if(resolvedType is null or ErrorType)
                        {
                            // Already emitted diagnostic in ResolveConstraintTypeReference.
                            break;
                        }

                        // Classify the resolved type as abstract type, or base class constraint.
                        ClassifyConstraintType(
                            resolvedType, ref baseClassConstraint,
                            abstractConstraints,
                            baseClassConstraints, structTypeConstraints);
                        break;
                    }
            }
        }

        return new TypeParameterConstraints
        {
            HasClassConstraint = hasClassConstraint,
            HasStructConstraint = hasStructConstraint,
            BaseClassConstraint = baseClassConstraint,
            AbstractConstraints = abstractConstraints,
            ConstructorConstraints = constructorConstraints,
            HasReadonlyConstraint = hasReadonlyConstraint,
            HasMutableConstraint = hasMutableConstraint,
            HasOwnedConstraint = hasOwnedConstraint,
            HasLinearConstraint = hasLinearConstraint,
            HasAffineConstraint = hasAffineConstraint,
            HasRelevantConstraint = hasRelevantConstraint,
            HasDefaultConstraint = hasDefaultConstraint,
        };
    }

    /// <summary>
    /// Resolves the parameter types for a constructor constraint (<c>new(...)</c>).
    /// Returns an empty list for parameterless <c>new()</c>.
    /// </summary>
    private static IReadOnlyList<IType> ResolveConstructorConstraintParams(
        ConstructorConstraintConstraintNode ctorConstraint,
        ISymbol declaringSymbol,
        Storm.Runtime.SyntaxNode declaringNode,
        SymbolTable symbolTable,

        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        if(ctorConstraint.ParamTypes is null)
        {
            return Array.Empty<IType>();
        }

        var paramTypes = new List<IType>();
        var scope = declaringSymbol.ContainingScope;

        // Resolve the first parameter type.
        var firstType = ResolveConstraintParamType(
            ctorConstraint.ParamTypes.TypeReference, scope, symbolTable, declaringNode, diagnostics, sourceText);
        paramTypes.Add(firstType);

        // Resolve additional parameter types.
        foreach(var typeRef in ctorConstraint.ParamTypes.TypeReferences)
        {
            var resolvedType = ResolveConstraintParamType(
                typeRef, scope, symbolTable, declaringNode, diagnostics, sourceText);
            paramTypes.Add(resolvedType);
        }

        return paramTypes;
    }

    /// <summary>
    /// Resolves a single type reference within a constructor constraint parameter list.
    /// Uses scope-based lookup (same as Pass 1b base type resolution).
    /// </summary>
    private static IType ResolveConstraintParamType(
        TypeReferenceNode typeRef,
        IScope scope,
        SymbolTable symbolTable,
        Storm.Runtime.SyntaxNode declaringNode,

        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        // For primitive type references, resolve through the stdlib path so
        // that the resolved type is the same instance used during Pass 2
        // (e.g., Standard.Int32 rather than the legacy "int" singleton).
        // Falls back to legacy primitives when stdlib is not loaded (unit tests).
        if(typeRef.First is PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef)
        {
            try
            {
                var globalScope = FindGlobalScopeFromIScope(scope);
                if(globalScope is not null)
                {
                    return ResolvePrimitiveKeyword(globalScope, symbolTable, primitiveRef.PrimitiveType);
                }
            }
            catch(StdlibMissingException)
            {
                // Fall through to legacy path.
            }

            return ResolveLegacyPrimitive(primitiveRef.PrimitiveType);
        }

        // For named type references, look up in scope.
        if(typeRef.First is NamedSingleTypeRefSingleTypeRefNode namedRef)
        {
            var typeName = ExtractQualifiedName(namedRef.Name, sourceText);

            var resolvedSymbol = scope.Lookup(typeName);
            if(resolvedSymbol?.DeclaredType is not null)
            {
                return resolvedSymbol.DeclaredType;
            }

            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintUnresolvableType.Value,
                DiagnosticSeverity.Error,
                $"Constraint type '{typeName}' could not be resolved.",
                declaringNode,
                sourceText));
            return ErrorType.Instance;
        }

        return ErrorType.Instance;
    }

    /// <summary>
    /// Resolves the type reference in a type constraint (<c>where T : SomeType</c>).
    /// Returns null if the type cannot be resolved (diagnostic already emitted).
    /// </summary>
    private static IType? ResolveConstraintTypeReference(
        TypeConstraintConstraintNode typeConstraint,
        ISymbol declaringSymbol,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        var typeRef = typeConstraint.Type;
        var scope = declaringSymbol.ContainingScope;

        // For named type references, look up in scope.
        if(typeRef.First is NamedSingleTypeRefSingleTypeRefNode namedRef)
        {
            var typeName = ExtractQualifiedName(namedRef.Name, sourceText);

            var resolvedSymbol = scope.Lookup(typeName);
            if(resolvedSymbol?.DeclaredType is not null)
            {
                var resolvedType = resolvedSymbol.DeclaredType;

                // Handle generic type arguments if present.
                if(namedRef.TypeArgs is not null && resolvedType is ClassType or AbstractType or StructType)
                {
                    // When resolving type arguments for a constraint on an associated type slot,
                    // use the slot type itself as the declaring type. The slot's member scope
                    // contains its own type parameters (e.g., TOut in type Mapped<TOut>), and
                    // its parent scope is the enclosing abstract type's member scope which
                    // contains the abstract type's type parameters (e.g., TIn in IMapper<TIn>).
                    // Scope.Lookup walks parent scopes, so both are found.
                    var effectiveDeclaringType = declaringSymbol.DeclaredType ?? ErrorType.Instance;

                    resolvedType = ResolveGenericTypeReference(
                        resolvedType, namedRef.TypeArgs, typeName,
                        effectiveDeclaringType,
                        declaringNode, asts, compilation, diagnostics);
                }

                return resolvedType;
            }

            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintUnresolvableType.Value,
                DiagnosticSeverity.Error,
                $"Constraint type '{typeName}' could not be resolved.",
                declaringNode,
                sourceText));
            return null;
        }

        // For other type reference forms (primitives, etc.), they're not valid as constraints
        // but we still try to resolve them gracefully.
        diagnostics.Add(MakeDiagnosticWithLocation(
            ConstraintUnresolvableType.Value,
            DiagnosticSeverity.Error,
            "Constraint type could not be resolved.",
            declaringNode,
            sourceText));
        return null;
    }

    /// <summary>
    /// Classifies a resolved constraint type as a base class or abstract type constraint
    /// and adds it to the appropriate collection. Also tracks base class and struct types
    /// for validation purposes.
    /// </summary>
    private static void ClassifyConstraintType(
        IType resolvedType,
        ref IType? baseClassConstraint,
        List<IType> abstractConstraints,
        List<IType> baseClassConstraints,
        List<IType> structTypeConstraints)
    {
        // Unwrap ConstructedType to check the underlying definition.
        var definitionType = resolvedType is ConstructedType constructed
            ? constructed.GenericDefinition
            : resolvedType;

        switch(definitionType)
        {
            case AbstractType:
                abstractConstraints.Add(resolvedType);
                break;


            case ClassType:
                // Track all base class constraints for MIST_CONSTRAINT_0004 validation.
                baseClassConstraints.Add(resolvedType);
                // Store the first one as the effective base class constraint.
                baseClassConstraint ??= resolvedType;
                break;

            case StructType:
                // Track struct types used as constraints for MIST_CONSTRAINT_0005 validation.
                structTypeConstraints.Add(resolvedType);
                break;

            case TypeParameterType:
                // A type parameter used as a constraint (e.g., where U : T).
                // Treat as an abstract type-like constraint for now.
                abstractConstraints.Add(resolvedType);
                break;

            default:
                // Other types used as constraints — store as abstract constraint.
                abstractConstraints.Add(resolvedType);
                break;
        }
    }

    /// <summary>
    /// Validates constraint combinations after all constraints in a clause are resolved.
    /// Emits diagnostics for invalid combinations (Requirements 4.1–4.5).
    /// </summary>
    private static void ValidateConstraintCombinations(
        bool hasClassConstraint,
        bool hasStructConstraint,
        bool hasLinearConstraint,
        bool hasAffineConstraint,
        bool hasRelevantConstraint,
        List<IType> baseClassConstraints,
        List<IType> structTypeConstraints,
        List<IReadOnlyList<IType>> constructorConstraints,
        TypeParameterType typeParam,
        GenericConstraintClauseWhereClauseNode clause,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // MIST_CONSTRAINT_0009: Multiple substructural constraints on same type parameter.
        var substructuralCount = (hasLinearConstraint ? 1 : 0)
            + (hasAffineConstraint ? 1 : 0)
            + (hasRelevantConstraint ? 1 : 0);
        if(substructuralCount > 1)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintMultipleSubstructural.Value,
                DiagnosticSeverity.Error,
                $"Multiple substructural constraints are not allowed on type parameter '{typeParam.Name}'. " +
                "Specify at most one of 'linear', 'affine', or 'relevant'.",
                clause,
                sourceText));
        }

        // MIST_CONSTRAINT_0002: class + struct mutual exclusion.
        if(hasClassConstraint && hasStructConstraint)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintClassStructMutualExclusion.Value,
                DiagnosticSeverity.Error,
                $"The 'class' and 'struct' constraints are mutually exclusive on type parameter '{typeParam.Name}'.",
                clause,
                sourceText));
        }

        // MIST_CONSTRAINT_0003: struct + new() redundancy (warning).
        if(hasStructConstraint)
        {
            foreach(var ctorParams in constructorConstraints)
            {
                if(ctorParams.Count == 0)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        ConstraintStructNewRedundant.Value,
                        DiagnosticSeverity.Warning,
                        $"The 'new()' constraint is redundant on type parameter '{typeParam.Name}' because all structs have a parameterless constructor.",
                        clause,
                        sourceText));
                    break;
                }
            }
        }

        // MIST_CONSTRAINT_0004: Multiple base class constraints.
        if(baseClassConstraints.Count > 1)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintMultipleBaseClasses.Value,
                DiagnosticSeverity.Error,
                $"At most one base class constraint is allowed on type parameter '{typeParam.Name}'.",
                clause,
                sourceText));
        }

        // MIST_CONSTRAINT_0005: Struct used as base class constraint.
        // With struct inheritance, a struct constraint is valid when the type parameter
        // also has a `struct` constraint (analogous to base-class constraints on
        // class-constrained parameters). Only emit the error when the parameter does
        // NOT have a `struct` constraint.
        if(!hasStructConstraint)
        {
            foreach(var structType in structTypeConstraints)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    ConstraintStructAsBaseClass.Value,
                    DiagnosticSeverity.Error,
                    $"Struct '{structType.DisplayName}' cannot be used as a base class constraint.",
                    clause,
                    sourceText));
            }
        }

        // MIST_CONSTRAINT_0006: Base class + struct incompatibility.
        if(baseClassConstraints.Count > 0 && hasStructConstraint)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                ConstraintBaseClassStructIncompatible.Value,
                DiagnosticSeverity.Error,
                $"A base class constraint is incompatible with the 'struct' constraint on type parameter '{typeParam.Name}'.",
                clause,
                sourceText));
        }
    }

    /// <summary>
    /// Finds the compilation unit path for any symbol by looking up its declaring
    /// node in the symbol table and walking the ASTs.
    /// </summary>
    private static string? FindCompilationUnitPathForSymbol(
        ISymbol symbol,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        var declaringNode = symbolTable.GetDeclaringNode(symbol);
        if(declaringNode is null)
        {
            return null;
        }

        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is CompilationUnitNode cu && ContainsTypeDeclarationNode(cu, declaringNode))
            {
                return i < compilation.Units.Length ? compilation.Units[i].Source?.Path : null;
            }
        }

        return null;
    }

    /// <summary>
    /// Checks whether a compilation unit contains the given declaring node
    /// (class, struct, or abstract type declaration).
    /// </summary>
    private static bool ContainsTypeDeclarationNode(CompilationUnitNode cu, Storm.Runtime.SyntaxNode declaringNode)
    {
        foreach(var item in cu.Items)
        {
            switch(item)
            {
                case TypeItemTopLevelItemNode typeItem:
                    if(MatchesTypeDeclaration(typeItem.TypeDeclaration, declaringNode))
                    {
                        return true;
                    }

                    break;
                case NamespaceItemTopLevelItemNode nsItem:
                    var namespaceTypes = GetNamespaceBodyTypes(nsItem.NamespaceDeclaration);
                    foreach(var typeDecl in namespaceTypes)
                    {
                        if(MatchesTypeDeclaration(typeDecl, declaringNode))
                        {
                            return true;
                        }
                    }

                    break;
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether a type declaration node wraps the given declaring node.
    /// Also checks nested type declarations recursively.
    /// </summary>
    private static bool MatchesTypeDeclaration(TypeDeclarationNode typeDecl, Storm.Runtime.SyntaxNode declaringNode)
    {
        switch(typeDecl)
        {
            case BodyTypeTypeDeclarationNode body:
                if(ReferenceEquals(body.TypeBody, declaringNode))
                {
                    return true;
                }

                // Check nested types inside this type.
                foreach(var member in body.TypeBody.Members)
                {
                    if(member is NestedBodyTypeMemberMemberDeclarationNode nestedBody
                        && MatchesTypeDeclaration(new BodyTypeTypeDeclarationNode { TypeBody = nestedBody.NestedBody }, declaringNode))
                    {
                        return true;
                    }
                }

                return false;
            default:
                return false;
        }
    }

    /// <summary>
    /// Checks whether a compilation unit contains a given node by reference equality.
    /// Walks all top-level items including type declarations and namespace members.
    /// </summary>
    private static bool ContainsNodeByReference(CompilationUnitNode cu, Storm.Runtime.SyntaxNode targetNode)
    {
        foreach(var item in cu.Items)
        {
            switch(item)
            {
                case TypeItemTopLevelItemNode typeItem:
                    if(MatchesTypeDeclaration(typeItem.TypeDeclaration, targetNode))
                    {
                        return true;
                    }

                    break;
                case NamespaceItemTopLevelItemNode nsItem:
                    var namespaceTypes = GetNamespaceBodyTypes(nsItem.NamespaceDeclaration);
                    foreach(var typeDecl in namespaceTypes)
                    {
                        if(MatchesTypeDeclaration(typeDecl, targetNode))
                        {
                            return true;
                        }
                    }

                    break;
            }
        }

        return false;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1b (cont.) — Resolve with-clauses on method-like declarations
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves with-clause type references on method-like declarations (methods,
    /// constructors, abstract type methods) and stores the resolved
    /// <see cref="ContextClauseInfo"/> on each symbol's <see cref="Symbol.WithClauses"/>
    /// property. Uses scope-based type lookup consistent with Pass 1 constraint
    /// resolution.
    /// </summary>
    private static void Pass1_ResolveWithClauses(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol is not Symbol mutableSymbol)
            {
                continue;
            }

            if(symbol.Kind is not SymbolKind.Method and not SymbolKind.Constructor)
            {
                continue;
            }

            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is null)
            {
                continue;
            }

            var withClauseNodes = GetWithClauseNodes(declaringNode);
            if(withClauseNodes is null || withClauseNodes.Value.Length == 0)
            {
                continue;
            }

            var sourceText = GetSourceTextForSymbol(symbol, symbolTable);
            var scope = symbol.ContainingScope;
            var clauses = new List<ContextClauseInfo>();

            foreach(var clause in withClauseNodes.Value)
            {
                // Handle this-tier annotation: `with owned`, `with borrowed`, `with frozen`, `with readonly ref`
                if(clause is ThisTierWithClauseWithClauseNode tierClause)
                {
                    mutableSymbol.DeclaredThisTier = MapOwnershipSpecifierToThisTier(tierClause.Tier);
                    continue;
                }

                // Handle context binding: `with Logger log`
                if(clause is not ContextWithClauseWithClauseNode contextClause)
                {
                    continue;
                }

                var resolvedType = ResolveWithClauseType(
                    contextClause.Type, scope, symbolTable, declaringNode, asts, compilation, diagnostics, sourceText);

                if(resolvedType is null or ErrorType)
                {
                    continue;
                }

                clauses.Add(new ContextClauseInfo
                {
                    ContextType = resolvedType,
                    Identifier = contextClause.Name.Lexeme,
                    Span = ToMistSourceSpan(contextClause.Span),
                });
            }

            if(clauses.Count > 0)
            {
                mutableSymbol.WithClauses = clauses;
            }
        }
    }

    /// <summary>
    /// Maps an <see cref="OwnershipSpecifierNode"/> to the corresponding <see cref="ThisTier"/> value.
    /// </summary>
    private static ThisTier MapOwnershipSpecifierToThisTier(OwnershipSpecifierNode specifier)
    {
        return specifier switch
        {
            OwnedSpecifierOwnershipSpecifierNode => ThisTier.Owned,
            BorrowedSpecifierOwnershipSpecifierNode => ThisTier.Borrowed,
            FrozenSpecifierOwnershipSpecifierNode => ThisTier.Frozen,
            ReadonlyRefSpecifierOwnershipSpecifierNode => ThisTier.ReadonlyRef,
            _ => ThisTier.None,
        };
    }

    /// <summary>
    /// Extracts the <see cref="ImmutableArray{WithClauseNode}"/> from a method-like
    /// declaring node, or returns null if the node type does not support with-clauses.
    /// </summary>
    private static ImmutableArray<WithClauseNode>? GetWithClauseNodes(Storm.Runtime.SyntaxNode declaringNode)
    {
        return declaringNode switch
        {
            MethodDeclarationNode methodDecl => methodDecl.WithClauses,
            ConstructorDeclarationNode ctorDecl => ctorDecl.WithClauses,
            _ => null,
        };
    }

    /// <summary>
    /// Resolves a type reference from a with-clause using scope-based lookup,
    /// consistent with Pass 1 constraint type resolution. Handles primitive types,
    /// named types, and generic type arguments.
    /// </summary>
    private static IType? ResolveWithClauseType(
        TypeReferenceNode typeRef,
        IScope scope,
        SymbolTable symbolTable,
        Storm.Runtime.SyntaxNode declaringNode,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics,
        SourceText? sourceText)
    {
        // For primitive type references, resolve through the stdlib path.
        if(typeRef.First is PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef)
        {
            try
            {
                var globalScope = FindGlobalScopeFromIScope(scope);
                if(globalScope is not null)
                {
                    return ResolvePrimitiveKeyword(globalScope, symbolTable, primitiveRef.PrimitiveType);
                }
            }
            catch(StdlibMissingException)
            {
                // Fall through to legacy path.
            }

            return ResolveLegacyPrimitive(primitiveRef.PrimitiveType);
        }

        // For named type references, look up in scope.
        if(typeRef.First is NamedSingleTypeRefSingleTypeRefNode namedRef)
        {
            var typeName = ExtractQualifiedName(namedRef.Name, sourceText);

            var resolvedSymbol = scope.Lookup(typeName);
            if(resolvedSymbol?.DeclaredType is not null)
            {
                var resolvedType = resolvedSymbol.DeclaredType;

                // Handle generic type arguments if present.
                if(namedRef.TypeArgs is not null)
                {
                    resolvedType = ResolveGenericTypeReference(
                        resolvedType, namedRef.TypeArgs, typeName,
                        resolvedSymbol.DeclaredType,
                        declaringNode, asts, compilation, diagnostics);
                }

                return resolvedType;
            }

            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_CTX_UNDEFINED_TYPE",
                DiagnosticSeverity.Error,
                $"With-clause type '{typeName}' could not be resolved.",
                declaringNode,
                sourceText));
            return null;
        }

        // Other type reference forms are not valid in with-clauses.
        diagnostics.Add(MakeDiagnosticWithLocation(
            "MIST_CTX_UNDEFINED_TYPE",
            DiagnosticSeverity.Error,
            "With-clause type could not be resolved.",
            declaringNode,
            sourceText));
        return null;
    }


    /// <summary>
    /// Determines whether a member symbol is public by checking its declaring
    /// AST node's modifiers. A member is considered public if it has an explicit
    /// <c>public</c> modifier.
    /// </summary>
    private static bool IsMemberPublic(ISymbol member, SymbolTable symbolTable)
    {
        var declaringNode = symbolTable.GetDeclaringNode(member);
        if(declaringNode is null)
        {
            return false;
        }

        ImmutableArray<ModifierNode>? modifiers = declaringNode switch
        {
            FieldDeclarationNode f => f.Modifiers,
            MethodDeclarationNode m => m.Modifiers,
            BlockPropertyPropertyDeclarationNode bp => bp.Modifiers,
            ExpressionBodiedPropertyPropertyDeclarationNode ep => ep.Modifiers,
            ConstructorDeclarationNode c => c.Modifiers,
            OperatorDeclarationNode o => o.Modifiers,
            _ => null,
        };

        if(modifiers is null)
        {
            return false;
        }

        return modifiers.Value.Any(m => m is PublicModifierModifierNode);
    }


    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1 — Resolve With Blocks (Retroactive Conformance)
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves with-block declarations, validating type references, member
    /// mappings, and signature compatibility. Registers validated mappings
    /// in the <see cref="ConformanceMap"/>.
    /// </summary>
    private static void Pass1_ResolveWithBlocks(
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,

        SymbolTable symbolTable,
        ConformanceMap conformanceMap,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is not CompilationUnitNode cu)
            {
                continue;
            }

            var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;

            foreach(var item in cu.Items)
            {
                if(item is not WithItemTopLevelItemNode withItem)
                {
                    continue;
                }

                var withDecl = withItem.WithDeclaration;
                ResolveWithDeclaration(withDecl, symbolTable, conformanceMap, sourceText, diagnostics);
            }
        }
    }

    /// <summary>
    /// Resolves a single with-block declaration.
    /// </summary>
    private static void ResolveWithDeclaration(
        WithDeclarationNode withDecl,

        SymbolTable symbolTable,
        ConformanceMap conformanceMap,

        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var typeName = withDecl.TypeName.Lexeme;
        var abstractName = withDecl.AbstractName.Lexeme;

        // Resolve typeName to a concrete type by searching all registered symbols.
        ISymbol? typeSymbol = null;
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Name == typeName &&
                symbol.Kind is SymbolKind.Class or SymbolKind.Struct)
            {
                typeSymbol = symbol;
                break;
            }
        }

        if(typeSymbol is null)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0001",
                DiagnosticSeverity.Error,
                $"The type '{typeName}' could not be found.",
                withDecl,
                sourceText));
            return;
        }

        var concreteType = typeSymbol.DeclaredType;
        if(concreteType is not ClassType and not StructType)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0001",
                DiagnosticSeverity.Error,
                $"The type '{typeName}' could not be found.",
                withDecl,
                sourceText));
            return;
        }

        // Check if the type is a CLR/ambient type (not defined in Mist source).
        var typeDeclaringNode = symbolTable.GetDeclaringNode(typeSymbol);
        if(typeDeclaringNode is null)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0006",
                DiagnosticSeverity.Error,
                $"Cannot use 'with' to establish conformance for CLR type '{typeName}'. Only types defined in Mist source can be adapted via 'with' blocks.",
                withDecl,
                sourceText));
            return;
        }

        // Resolve abstractName to an AbstractType.
        ISymbol? abstractSymbol = null;
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Name == abstractName && symbol.Kind == SymbolKind.Abstract)
            {
                abstractSymbol = symbol;
                break;
            }
        }

        if(abstractSymbol is null)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0002",
                DiagnosticSeverity.Error,
                $"The abstract type '{abstractName}' could not be found.",
                withDecl,
                sourceText));
            return;
        }

        if(abstractSymbol.DeclaredType is not AbstractType abstractType)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0002",
                DiagnosticSeverity.Error,
                $"'{abstractName}' is not an abstract type.",
                withDecl,
                sourceText));
            return;
        }

        // Check for redundant conformance: type already declares `: AbstractType` in base clause.
        var typeAbstracts = concreteType switch
        {
            ClassType ct => ct.Abstracts,
            StructType st => st.Abstracts,
            _ => Array.Empty<IType>()
        };

        foreach(var existingAbstract in typeAbstracts)
        {
            var existing = existingAbstract switch
            {
                AbstractType at => at,
                ConstructedType { GenericDefinition: AbstractType gat } => gat,
                _ => null
            };

            if(existing is not null && ReferenceEquals(existing, abstractType))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_WITH_0003",
                    DiagnosticSeverity.Error,
                    $"Redundant conformance: '{typeName}' already declares ': {abstractName}' in its base clause.",
                    withDecl,
                    sourceText));
                return;
            }
        }

        // Process member mappings.
        var concreteScope = concreteType switch
        {
            ClassType ct => ct.MemberScope,
            StructType st => st.MemberScope,
            _ => null
        };

        if(concreteScope is null)
        {
            return;
        }

        var mappedSlotNames = new HashSet<string>();

        foreach(var mapping in withDecl.Mappings)
        {
            var sourceName = mapping.SourceName.Lexeme;
            var targetName = mapping.TargetName.Lexeme;

            // Find sourceName as a public member on the concrete type.
            ISymbol? sourceMember = null;
            foreach(var member in concreteScope.Members)
            {
                if(member.Name == sourceName && (member.Kind == SymbolKind.Method || member.Kind == SymbolKind.Property))
                {
                    sourceMember = member;
                    break;
                }
            }

            if(sourceMember is null)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_WITH_0004",
                    DiagnosticSeverity.Error,
                    $"'{typeName}' does not have a public member named '{sourceName}'.",
                    mapping,
                    sourceText));
                continue;
            }

            // Check member is public.
            if(!IsMemberPublic(sourceMember, symbolTable))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_WITH_0004",
                    DiagnosticSeverity.Error,
                    $"'{typeName}' does not have a public member named '{sourceName}'.",
                    mapping,
                    sourceText));
                continue;
            }

            // Find targetName as a slot on the abstract type.
            ISymbol? targetSlot = null;
            foreach(var member in abstractType.MemberScope.Members)
            {
                if(member.Name == targetName && (member.Kind == SymbolKind.Method || member.Kind == SymbolKind.Property))
                {
                    targetSlot = member;
                    break;
                }
            }

            if(targetSlot is null)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_WITH_0004",
                    DiagnosticSeverity.Error,
                    $"'{abstractName}' does not have a member named '{targetName}'.",
                    mapping,
                    sourceText));
                continue;
            }

            // Validate signature compatibility.
            if(sourceMember.Kind == SymbolKind.Method && targetSlot.Kind == SymbolKind.Method)
            {
                var sourceNode = symbolTable.GetDeclaringNode(sourceMember);
                var targetNode = symbolTable.GetDeclaringNode(targetSlot);

                if(sourceNode is MethodDeclarationNode sourceMethodDecl &&
                    targetNode is MethodDeclarationNode targetMethodDecl)
                {
                    if(!SignaturesMatch(targetMethodDecl, sourceMethodDecl))
                    {
                        var expectedSig = FormatInterfaceMethodSignature(targetMethodDecl);
                        var actualSig = FormatMethodSignature(sourceMethodDecl);
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            "MIST_WITH_0005",
                            DiagnosticSeverity.Error,
                            $"Signature mismatch: '{sourceName}' on '{typeName}' does not match slot '{targetName}' on '{abstractName}'. Expected: {expectedSig}, got: {actualSig}.",
                            mapping,
                            sourceText));
                        continue;
                    }
                }
            }
            else if(sourceMember.Kind != targetSlot.Kind)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_WITH_0005",
                    DiagnosticSeverity.Error,
                    $"Member kind mismatch: '{sourceName}' on '{typeName}' is a {sourceMember.Kind.ToString().ToLower()} but '{targetName}' on '{abstractName}' is a {targetSlot.Kind.ToString().ToLower()}.",
                    mapping,
                    sourceText));
                continue;
            }

            // Register the mapping.
            conformanceMap.Register(concreteType, abstractType, new ConformanceMapping
            {
                SourceMember = sourceMember,
                TargetSlot = targetSlot,
                SourceName = sourceName,
                TargetName = targetName,
            });

            _ = mappedSlotNames.Add(targetName);
        }

        // Validate that all required slots have mappings.
        // Default methods without mappings are automatically satisfied.
        var missingSlots = new List<string>();
        foreach(var member in abstractType.MemberScope.Members)
        {
            if(member.Kind is not (SymbolKind.Method or SymbolKind.Property))
            {
                continue;
            }

            // Skip default methods — they don't need mappings.
            if(member.Kind == SymbolKind.Method &&
                abstractType.DefaultMethods.TryGetValue(member.Name, out var defaultSymbol) &&
                ReferenceEquals(defaultSymbol, member))
            {
                continue;
            }

            if(!mappedSlotNames.Contains(member.Name))
            {
                missingSlots.Add(member.Name);
            }
        }

        if(missingSlots.Count > 0)
        {
            var slotList = string.Join(", ", missingSlots.Select(s => $"'{s}'"));
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_WITH_0004",
                DiagnosticSeverity.Error,
                $"With-block for '{typeName} : {abstractName}' is missing required slot mappings: {slotList}.",
                withDecl,
                sourceText));
        }
    }



    // ═══════════════════════════════════════════════════════════════════════




    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1c — Detect circular abstract type inheritance chains
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After abstract type lists are resolved, walk each abstract type's Abstracts
    /// chain to detect cycles (including self-inheritance). When a cycle is
    /// found, emit a <c>MIST_CIRCULAR_ABSTRACT_INHERITANCE</c> diagnostic
    /// and break the cycle by removing the back-edge from the abstract types list.
    /// </summary>
    private static void Pass1_DetectAbstractCycles(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Track abstracts that have already been verified as cycle-free so
        // we don't re-walk them.
        var verified = new HashSet<AbstractType>();

        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Abstract || symbol.DeclaredType is not AbstractType abstractType)
            {
                continue;
            }

            if(abstractType.Abstracts.Count == 0 || verified.Contains(abstractType))
            {
                continue;
            }

            // Walk the abstract types chain from this abstract type, tracking visited
            // abstracts using a stack-based DFS.
            DetectAbstractCyclesDfs(
                abstractType, verified, symbolTable, asts, compilation, diagnostics);
        }
    }

    /// <summary>
    /// Performs a DFS walk of the abstract type inheritance graph starting from
    /// <paramref name="root"/>. If a cycle is detected, emits a diagnostic
    /// and removes the back-edge from the parent's Abstracts list.
    /// </summary>
    private static void DetectAbstractCyclesDfs(
        AbstractType root,
        HashSet<AbstractType> verified,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // path tracks the current DFS path for cycle reporting.
        var path = new List<AbstractType>();
        // pathSet provides O(1) lookup for cycle detection.
        var pathSet = new HashSet<AbstractType>();

        DetectAbstractCyclesDfsVisit(
            root, path, pathSet, verified,
            symbolTable, asts, compilation, diagnostics);
    }

    /// <summary>
    /// Recursive DFS visitor for abstract type cycle detection.
    /// </summary>
    private static void DetectAbstractCyclesDfsVisit(
        AbstractType current,

        List<AbstractType> path,
        HashSet<AbstractType> pathSet,
        HashSet<AbstractType> verified,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        if(verified.Contains(current))
        {
            return;
        }

        if(!pathSet.Add(current))
        {
            // Cycle detected — current was already on the path.
            // Build the chain string for the diagnostic message.
            var cycleStart = path.IndexOf(current);
            var cycleMembers = path.Skip(cycleStart).Select(i => i.DisplayName).ToList();
            cycleMembers.Add(current.DisplayName);
            var chainStr = string.Join(" -> ", cycleMembers);

            // Find the abstract type that has the back-edge (the parent that
            // references current in its Abstracts list).
            var closingAbstract = path[^1];

            // Find the symbol and source text for the closing abstract type.
            var sourceText = FindSourceTextForAbstractType(
                closingAbstract, symbolTable);
            Storm.Runtime.SyntaxNode? closingNode = null;
            foreach(var sym in symbolTable.AllSymbols)
            {
                if(sym.DeclaredType == closingAbstract)
                {
                    closingNode = symbolTable.GetDeclaringNode(sym);
                    break;
                }
            }

            if(closingNode is not null)
            {
                LinePositionSpan location = default;
                var cuPath = sourceText?.Path ?? "<unknown>";
                if(sourceText is not null && closingNode.Span.Length > 0)
                {
                    var mistSpan = new SourceSpan(closingNode.Span.Start, closingNode.Span.Length);
                    location = sourceText.ToLinePositionSpan(mistSpan);
                }

                diagnostics.Report(SemanticDiagnostics.CircularAbstractInheritance, location, cuPath, (object)chainStr);
            }
            else
            {
                var compilationUnitPath = FindCompilationUnitPathForAbstractType(
                    closingAbstract, symbolTable, asts, compilation);

                diagnostics.Report(SemanticDiagnostics.CircularAbstractInheritance, default, compilationUnitPath ?? "<unknown>", (object)chainStr);
            }

            // Break the cycle by removing the back-edge from the closing
            // abstract type's Abstracts list.
            var updatedAbstracts = closingAbstract.Abstracts
                .Where(i => !ReferenceEquals(i, current))
                .ToList();
            closingAbstract.Abstracts = updatedAbstracts;

            return;
        }

        path.Add(current);

        // Visit each abstract type in the current abstract type's Abstracts list.
        // Take a snapshot of the list since it may be modified during cycle breaking.
        var abstracts = current.Abstracts.OfType<AbstractType>().ToList();
        foreach(var child in abstracts)
        {
            DetectAbstractCyclesDfsVisit(
                child, path, pathSet, verified,
                symbolTable, asts, compilation, diagnostics);
        }

        path.RemoveAt(path.Count - 1);
        _ = pathSet.Remove(current);
        _ = verified.Add(current);
    }

    /// <summary>
    /// Finds the compilation unit path for an abstract type type by looking up its
    /// declaring node in the symbol table.
    /// </summary>
    private static string? FindCompilationUnitPathForAbstractType(
        AbstractType abstractType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.DeclaredType == abstractType)
            {
                return FindCompilationUnitPathForSymbol(symbol, symbolTable, asts, compilation);
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the <see cref="SourceText"/> for an abstract type type by looking up its
    /// declaring node in the symbol table.
    /// </summary>
    private static SourceText? FindSourceTextForAbstractType(
        AbstractType abstractType,
        SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.DeclaredType == abstractType)
            {
                return GetSourceTextForSymbol(symbol, symbolTable);
            }
        }

        return null;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1c (cont.) — Detect circular class inheritance chains
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After all base types are resolved, walk each class's BaseType chain to
    /// detect cycles (including self-inheritance). When a cycle is found, emit
    /// a <c>MIST_CIRCULAR_INHERITANCE</c> diagnostic and set <c>BaseType = null</c>
    /// on the class that closes the cycle to break it.
    /// </summary>
    private static void Pass1_DetectCycles(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Track classes that have already been verified as cycle-free so we
        // don't re-walk them.
        var verified = new HashSet<ClassType>();

        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Class || symbol.DeclaredType is not ClassType classType)
            {
                continue;
            }

            if(classType.BaseType is null || verified.Contains(classType))
            {
                continue;
            }

            // Walk the BaseType chain from this class, tracking visited classes.
            var visited = new HashSet<ClassType>();
            var chain = new List<ClassType>();
            var current = classType;

            while(current is not null)
            {
                if(!visited.Add(current))
                {
                    // Cycle detected — current was already visited.
                    // Build the chain string for the diagnostic message.
                    var cycleStart = chain.IndexOf(current);
                    var cycleMembers = chain.Skip(cycleStart).Select(c => c.DisplayName).ToList();
                    cycleMembers.Add(current.DisplayName);
                    var chainStr = string.Join(" -> ", cycleMembers);

                    // Find the class declaration node that closes the cycle
                    // (the last class in the chain before we revisited current).
                    var closingClass = chain[^1];
                    var closingSourceText = FindSourceTextForClassType(closingClass, symbolTable);
                    Storm.Runtime.SyntaxNode? closingNode = null;
                    foreach(var sym in symbolTable.AllSymbols)
                    {
                        if(sym.DeclaredType == closingClass)
                        {
                            closingNode = symbolTable.GetDeclaringNode(sym);
                            break;
                        }
                    }

                    if(closingNode is not null)
                    {
                        LinePositionSpan closingLocation = default;
                        var closingPath = closingSourceText?.Path ?? "<unknown>";
                        if(closingSourceText is not null && closingNode.Span.Length > 0)
                        {
                            var mistSpan = new SourceSpan(closingNode.Span.Start, closingNode.Span.Length);
                            closingLocation = closingSourceText.ToLinePositionSpan(mistSpan);
                        }

                        diagnostics.Report(SemanticDiagnostics.CircularInheritance, closingLocation, closingPath, (object)chainStr);
                    }
                    else
                    {
                        var compilationUnitPath = FindCompilationUnitPathForClass(closingClass, symbolTable, asts, compilation);

                        diagnostics.Report(SemanticDiagnostics.CircularInheritance, default, compilationUnitPath ?? "<unknown>", (object)chainStr);
                    }

                    // Break the cycle by nulling the BaseType on the closing class.
                    closingClass.BaseType = null;
                    break;
                }

                chain.Add(current);
                current = current.BaseType as ClassType;
            }

            // All classes in this chain that didn't form a cycle are verified.
            foreach(var c in chain)
            {
                if(c.BaseType is not null || c == classType)
                {
                    _ = verified.Add(c);
                }
            }
        }
    }

    /// <summary>
    /// Finds the compilation unit path for a class type by looking up its
    /// declaring node in the symbol table.
    /// </summary>
    private static string? FindCompilationUnitPathForClass(
        ClassType classType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.DeclaredType == classType)
            {
                var declaringNode = symbolTable.GetDeclaringNode(symbol);
                if(declaringNode is TypeBodyDeclarationNode classDecl)
                {
                    return FindCompilationUnitPath(classDecl, asts, compilation);
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the <see cref="SourceText"/> for a class type by looking up its
    /// declaring node in the symbol table.
    /// </summary>
    private static SourceText? FindSourceTextForClassType(
        ClassType classType,
        SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.DeclaredType == classType)
            {
                var declaringNode = symbolTable.GetDeclaringNode(symbol);
                if(declaringNode is TypeBodyDeclarationNode classDecl)
                {
                    return GetSourceTextFromOrigin(classDecl);
                }
            }
        }

        return null;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1c (cont.) — Detect struct inheritance cycles
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Walks each struct's ancestor chain to detect circular inheritance and
    /// chains exceeding the maximum depth of 64 levels. On cycle detection,
    /// emits <c>MIST_STRUCT_CIRCULAR_INHERITANCE</c> and sets
    /// <c>BaseType = null</c>. On depth exceeded, emits
    /// <c>MIST_STRUCT_MAX_DEPTH</c> and sets <c>BaseType = null</c>.
    /// </summary>
    private static void DetectStructInheritanceCycles(
        SymbolTable symbolTable,

        DiagnosticBag diagnostics)
    {
        const int maxDepth = 64;

        // Track structs that have already been verified as cycle-free so we
        // don't re-walk them.
        var verified = new HashSet<StructType>();

        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Struct || symbol.DeclaredType is not StructType structType)
            {
                continue;
            }

            if(structType.BaseType is null || verified.Contains(structType))
            {
                continue;
            }

            // Walk the BaseType chain from this struct, tracking visited structs.
            var visited = new HashSet<StructType>();
            var chain = new List<StructType>();
            var current = structType;

            while(current is not null)
            {
                if(!visited.Add(current))
                {
                    // Cycle detected — current was already visited.
                    var cycleStart = chain.IndexOf(current);
                    var cycleMembers = chain.Skip(cycleStart).Select(c => c.DisplayName).ToList();
                    cycleMembers.Add(current.DisplayName);
                    var chainStr = string.Join(" -> ", cycleMembers);

                    // Find the struct declaration node that closes the cycle.
                    var closingStruct = chain[^1];
                    Storm.Runtime.SyntaxNode? closingNode = null;
                    foreach(var sym in symbolTable.AllSymbols)
                    {
                        if(sym.DeclaredType == closingStruct)
                        {
                            closingNode = symbolTable.GetDeclaringNode(sym);
                            break;
                        }
                    }

                    var closingSourceText = closingNode is not null
                        ? GetSourceTextFromOrigin(closingNode)
                        : null;

                    if(closingNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            StructCircularInheritance.Value,
                            DiagnosticSeverity.Error,
                            $"Circular inheritance detected in struct chain: '{chainStr}'.",
                            closingNode,
                            closingSourceText));
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            StructCircularInheritance,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Circular inheritance detected in struct chain: '{chainStr}'.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    // Break the cycle by nulling the BaseType on the closing struct.
                    closingStruct.BaseType = null;
                    break;
                }

                chain.Add(current);

                // Check max depth (only count edges, not the root itself).
                if(chain.Count - 1 > maxDepth)
                {
                    // Depth exceeded — emit diagnostic on the original struct.
                    var declaringNode = symbolTable.GetDeclaringNode(symbol);
                    var sourceText = declaringNode is not null
                        ? GetSourceTextFromOrigin(declaringNode)
                        : null;

                    if(declaringNode is not null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            StructMaxDepth.Value,
                            DiagnosticSeverity.Error,
                            $"Struct '{structType.DisplayName}' exceeds the maximum inheritance depth of {maxDepth}.",
                            declaringNode,
                            sourceText));
                    }
                    else
                    {
                        diagnostics.Add(new Diagnostic(
                            StructMaxDepth,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Struct '{structType.DisplayName}' exceeds the maximum inheritance depth of {maxDepth}.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    // Break the chain by nulling the BaseType on the original struct.
                    structType.BaseType = null;
                    break;
                }

                current = current.BaseType as StructType;
            }

            // All structs in this chain that didn't form a cycle are verified.
            foreach(var s in chain)
            {
                if(s.BaseType is not null || s == structType)
                {
                    _ = verified.Add(s);
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1d — Validate abstract type satisfaction
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After cycles are broken, check that each class and struct implementing
    /// abstracts provides all required methods. Walks the abstract type hierarchy
    /// transitively (using a visited set for diamond inheritance) to collect
    /// required methods, then searches the implementing type's member scope
    /// (and base type chain for classes) for matching methods.
    /// </summary>
    private static void Pass1_ValidateAbstractSatisfaction(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            switch(symbol.Kind)
            {
                case SymbolKind.Class when symbol.DeclaredType is ClassType classType:
                    if(classType.Abstracts.Count > 0)
                    {
                        ValidateAbstractSatisfaction(
                            classType.DisplayName, classType.Abstracts, classType.MemberScope,
                            classType, symbolTable, asts, compilation, diagnostics);
                    }

                    break;

                case SymbolKind.Struct when symbol.DeclaredType is StructType structType:
                    if(structType.Abstracts.Count > 0)
                    {
                        ValidateAbstractSatisfaction(
                            structType.DisplayName, structType.Abstracts, structType.MemberScope,
                            null, symbolTable, asts, compilation, diagnostics);
                    }

                    break;
            }
        }
    }

    /// <summary>
    /// Validates that the implementing type provides all methods required by
    /// its abstracts (including transitively inherited abstract types).
    /// </summary>
    /// <param name="typeName">Display name of the implementing type.</param>
    /// <param name="abstracts">direct abstract types of the implementing type.</param>
    /// <param name="memberScope">Member scope of the implementing type.</param>
    /// <param name="classType">If the implementing type is a class, its ClassType (for base chain walking). Null for structs.</param>
    /// <param name="symbolTable">The symbol table.</param>
    /// <param name="asts">The ASTs.</param>
    /// <param name="compilation">The compilation.</param>
    /// <param name="diagnostics">Diagnostic bag.</param>
    private static void ValidateAbstractSatisfaction(
        string typeName,
        IReadOnlyList<IType> abstracts,
        IScope memberScope,
        ClassType? classType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Collect all required methods transitively from the abstract type hierarchy.
        // Each entry is (AbstractType, methodSymbol) so we can report which
        // abstract type requires the method.
        var requiredMethods = new List<(AbstractType Abstract, ISymbol Method)>();
        var requiredProperties = new List<(AbstractType Abstract, ISymbol Property)>();
        var visitedAbstracts = new HashSet<AbstractType>();
        CollectRequiredMembers(abstracts, requiredMethods, requiredProperties, visitedAbstracts);

        // Build a substitution map for associated type slots: maps slot names in
        // the abstract type to the set of acceptable concrete type names in the implementor.
        var associatedTypeSubstitutions = BuildAssociatedTypeSubstitutionMap(
            abstracts, memberScope, classType);

        // For each required method, search for a matching implementation.
        foreach(var (requiredAbstract, requiredMethod) in requiredMethods)
        {
            var requiredNode = symbolTable.GetDeclaringNode(requiredMethod);
            if(requiredNode is not MethodDeclarationNode requiredMethodDecl)
            {
                continue;
            }

            // Search the implementing type's member scope for a method with the same name.
            var matchResult = FindMatchingMethod(
                requiredMethod.Name, requiredMethodDecl,
                memberScope, classType, symbolTable, associatedTypeSubstitutions);

            switch(matchResult)
            {
                case MethodMatchResult.MatchedResult:
                    // Method found with matching signature — satisfied.
                    // Refinement constraint validation is deferred to
                    // Pass2_ValidateRefinementConstraintSatisfaction (runs after
                    // adhoc refinement constraints are resolved).
                    break;

                case MethodMatchResult.SignatureMismatch when requiredAbstract.TypeParameters.Count > 0:
                    // A method with the same name exists but the signature doesn't match.
                    // When the abstract type has type parameters (e.g., IWrapper<T> with T Unwrap()),
                    // the signature comparison may fail because type parameter substitution
                    // in method signatures is not fully supported in this validation path.
                    // Treat as satisfied to avoid false positives.
                    break;

                case MethodMatchResult.MissingResult:
                    {
                        // No method with this name found anywhere in the type or its base chain.
                        // Emit MIST_SM_0022 with the specific abstract type method signature.
                        var paramSig = FormatParameterTypes(requiredMethodDecl.Parameters);
                        var missingSourceText = FindSourceTextForType(
                            typeName, symbolTable);
                        var missingNode = FindDeclaringNodeForType(typeName, symbolTable);

                        var message = $"'{typeName}' does not implement abstract type method '{requiredAbstract.DisplayName}.{requiredMethod.Name}({paramSig})'.";

                        if(missingNode is not null)
                        {
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                MissingAbstractOverload.Value,
                                DiagnosticSeverity.Error,
                                message,
                                missingNode,
                                missingSourceText));
                        }
                        else
                        {
                            var missingPath = FindCompilationUnitPathForType(
                                typeName, symbolTable, asts, compilation);

                            diagnostics.Add(new Diagnostic(
                                MissingAbstractOverload,
                                DiagnosticSeverity.Error,
                                PipelineStage.SemanticModelConstruction,
                                message,
                                Location: default,
                                CompilationUnitPath: missingPath ?? "<unknown>",
                                AnalyzerName: null));
                        }

                        break;
                    }

                case MethodMatchResult.SignatureMismatch:
                    {
                        // Method name matches but no overload has a matching parameter signature.
                        // Emit MIST_SM_0022 with the specific abstract type method signature.
                        var paramSig = FormatParameterTypes(requiredMethodDecl.Parameters);
                        var mismatchSourceText = FindSourceTextForType(
                            typeName, symbolTable);
                        var mismatchNode = FindDeclaringNodeForType(typeName, symbolTable);

                        var message = $"'{typeName}' does not implement abstract type method '{requiredAbstract.DisplayName}.{requiredMethod.Name}({paramSig})'.";

                        if(mismatchNode is not null)
                        {
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                MissingAbstractOverload.Value,
                                DiagnosticSeverity.Error,
                                message,
                                mismatchNode,
                                mismatchSourceText));
                        }
                        else
                        {
                            var mismatchPath = FindCompilationUnitPathForType(
                                typeName, symbolTable, asts, compilation);

                            diagnostics.Add(new Diagnostic(
                                MissingAbstractOverload,
                                DiagnosticSeverity.Error,
                                PipelineStage.SemanticModelConstruction,
                                message,
                                Location: default,
                                CompilationUnitPath: mismatchPath ?? "<unknown>",
                                AnalyzerName: null));
                        }

                        break;
                    }

                case MethodMatchResult.RefKindMismatchResult refKindMismatch:
                    {
                        // Types match but RefKind values differ — emit MIST_REF_0012.
                        var refMismatchSourceText = FindSourceTextForType(
                            typeName, symbolTable);
                        var refMismatchNode = FindDeclaringNodeForType(typeName, symbolTable);

                        var refMessage = $"Method '{refKindMismatch.ImplMethodName}' does not match abstract type method '{requiredAbstract.DisplayName}.{refKindMismatch.AbstractMethodName}': parameter ref kinds must match exactly";

                        if(refMismatchNode is not null)
                        {
                            LinePositionSpan refLocation = default;
                            var refPath = refMismatchSourceText?.Path ?? "<unknown>";
                            if(refMismatchSourceText is not null && refMismatchNode.Span.Length > 0)
                            {
                                var mistSpan = new SourceSpan(refMismatchNode.Span.Start, refMismatchNode.Span.Length);
                                refLocation = refMismatchSourceText.ToLinePositionSpan(mistSpan);
                            }

                            diagnostics.Report(SemanticDiagnostics.RefKindMismatch, refLocation, refPath, (object)refMessage);
                        }
                        else
                        {
                            var refMismatchPath = FindCompilationUnitPathForType(
                                typeName, symbolTable, asts, compilation);

                            diagnostics.Report(SemanticDiagnostics.RefKindMismatch, default, refMismatchPath ?? "<unknown>", (object)refMessage);
                        }

                        break;
                    }
            }
        }

        // For each required property, search for a matching implementation.
        foreach(var (requiredAbstract, requiredProperty) in requiredProperties)
        {
            var requiredPropInfo = (requiredProperty as Symbol)?.PropertyMetadata;
            if(requiredPropInfo is null)
            {
                continue;
            }

            // Search the implementing type's member scope (and base chain) for a property with the same name.
            var implProperty = FindMatchingProperty(requiredProperty.Name, memberScope, classType);

            if(implProperty is null)
            {
                var missingPath = FindCompilationUnitPathForType(
                    typeName, symbolTable, asts, compilation);

                diagnostics.Report(SemanticDiagnostics.MissingAbstractProperty, default, missingPath ?? "<unknown>", (object)typeName, requiredAbstract.DisplayName, requiredProperty.Name);
                continue;
            }

            var implPropInfo = (implProperty as Symbol)?.PropertyMetadata;
            if(implPropInfo is null)
            {
                continue;
            }

            // Check that the implementing property has the required accessors.
            if(requiredPropInfo.HasGet && !implPropInfo.HasGet)
            {
                var path = FindCompilationUnitPathForType(typeName, symbolTable, asts, compilation);
                diagnostics.Report(SemanticDiagnostics.MissingAbstractPropertyAccessor, default, path ?? "<unknown>", (object)typeName, requiredProperty.Name, "get", requiredAbstract.DisplayName);
            }

            if(requiredPropInfo.HasSet && !implPropInfo.HasSet && !implPropInfo.HasInit)
            {
                var path = FindCompilationUnitPathForType(typeName, symbolTable, asts, compilation);
                diagnostics.Report(SemanticDiagnostics.MissingAbstractPropertyAccessor, default, path ?? "<unknown>", (object)typeName, requiredProperty.Name, "set", requiredAbstract.DisplayName);
            }
        }

        // For each abstract type, check that the implementor provides concrete type members
        // for all associated type slots.
        ValidateAssociatedTypeSlotObligations(
            typeName, abstracts, memberScope, classType, symbolTable, asts, compilation, diagnostics);
    }

    /// <summary>
    /// Builds a substitution map for associated type slots and type parameters from
    /// generic abstract types: maps each slot/parameter name in the abstract type to the set
    /// of acceptable concrete type names in the implementor.
    /// For a slot named "X":
    /// - "X" itself is always acceptable (the implementor might have a nested type named "X")
    /// - If the implementor has a type alias "type X = Y", then "Y" is also acceptable
    /// For a type parameter "T" from a ConstructedType abstract type like IMapper&lt;int&gt;:
    /// - The concrete type argument's display name (e.g., "int") is acceptable
    /// </summary>
    private static Dictionary<string, HashSet<string>> BuildAssociatedTypeSubstitutionMap(
        IReadOnlyList<IType> abstracts,
        IScope memberScope,
        ClassType? classType)
    {
        var substitutions = new Dictionary<string, HashSet<string>>();

        // Collect all associated type slots from the abstract type hierarchy.
        var requiredSlots = new List<(AbstractType Abstract, ISymbol SlotSymbol, AssociatedTypeSlotType SlotType)>();
        var visitedAbstracts = new HashSet<AbstractType>();
        CollectRequiredAssociatedTypeSlots(abstracts, requiredSlots, visitedAbstracts);

        foreach(var (_, slotSymbol, slotType) in requiredSlots)
        {
            var slotName = slotSymbol.Name;
            if(substitutions.ContainsKey(slotName))
            {
                continue;
            }

            var acceptableNames = new HashSet<string> { slotName };

            // Search the implementor's scope for the concrete type member.
            var concreteTypeName = FindConcreteTypeMemberName(slotName, slotType.TypeParameters.Count, memberScope, classType);
            if(concreteTypeName is not null && concreteTypeName != slotName)
            {
                _ = acceptableNames.Add(concreteTypeName);
            }

            substitutions[slotName] = acceptableNames;
        }

        // Add type parameter substitutions from ConstructedType abstract types.
        // For example, if the type implements IMapper<int>, map "T" → {"int", "Int32"}.
        foreach(var ifaceType in abstracts)
        {
            if(ifaceType is not ConstructedType { GenericDefinition: AbstractType genericIface } constructed)
            {
                continue;
            }

            var typeParams = genericIface.TypeParameters;
            var typeArgs = constructed.TypeArguments;

            for(var i = 0; i < typeParams.Count && i < typeArgs.Count; i++)
            {
                var paramName = typeParams[i].DisplayName;
                if(string.IsNullOrEmpty(paramName))
                {
                    continue;
                }

                // Don't overwrite existing entries (associated type slots take precedence).
                if(substitutions.ContainsKey(paramName))
                {
                    continue;
                }

                var argDisplayName = typeArgs[i].DisplayName;
                if(string.IsNullOrEmpty(argDisplayName))
                {
                    continue;
                }

                var names = new HashSet<string> { argDisplayName };

                // Also add the keyword alias if the type argument is a stdlib type.
                // For example, if the type argument is Int32, also add "int".
                foreach(var (keyword, qualifiedName) in KeywordAliases.Map)
                {
                    var dotIndex = qualifiedName.LastIndexOf('.');
                    var simpleName = dotIndex >= 0 ? qualifiedName[(dotIndex + 1)..] : qualifiedName;
                    if(simpleName == argDisplayName || qualifiedName == argDisplayName)
                    {
                        _ = names.Add(keyword);
                        break;
                    }
                }

                // Also add the keyword if the type argument's display name IS the keyword
                // (e.g., legacy primitive types have DisplayName = "int").
                if(KeywordAliases.Map.ContainsKey(argDisplayName))
                {
                    // The display name is already a keyword — also add the stdlib simple name.
                    var qualifiedName = KeywordAliases.Map[argDisplayName];
                    var dotIndex = qualifiedName.LastIndexOf('.');
                    var simpleName = dotIndex >= 0 ? qualifiedName[(dotIndex + 1)..] : qualifiedName;
                    _ = names.Add(simpleName);
                }

                substitutions[paramName] = names;
            }
        }

        return substitutions;
    }

    /// <summary>
    /// Searches the implementing type's member scope (and base type chain for classes)
    /// for a concrete type member matching the given slot name and arity, and returns
    /// the resolved concrete type name. For type aliases, this returns the underlying
    /// type's display name. For nested types, this returns the nested type's name.
    /// Returns null if no concrete type member is found.
    /// </summary>
    private static string? FindConcreteTypeMemberName(
        string slotName,
        int requiredArity,
        IScope memberScope,
        ClassType? classType)
    {
        // Search the direct member scope.
        var name = SearchScopeForConcreteTypeMemberName(slotName, requiredArity, memberScope);
        if(name is not null)
        {
            return name;
        }

        // For classes, walk the base type chain.
        if(classType is not null)
        {
            var ancestor = classType.BaseType as ClassType;
            while(ancestor is not null)
            {
                name = SearchScopeForConcreteTypeMemberName(slotName, requiredArity, ancestor.MemberScope);
                if(name is not null)
                {
                    return name;
                }

                ancestor = ancestor.BaseType as ClassType;
            }
        }

        return null;
    }

    /// <summary>
    /// Searches a single scope for a concrete type member with the given name and arity,
    /// and returns the resolved concrete type name.
    /// </summary>
    private static string? SearchScopeForConcreteTypeMemberName(string slotName, int requiredArity, IScope scope)
    {
        foreach(var member in scope.Members)
        {
            if(member.Name != slotName)
            {
                continue;
            }

            // Type alias that is NOT an associated type slot (i.e., it's a concrete type alias).
            if(member.Kind == SymbolKind.TypeAlias && member.DeclaredType is not AssociatedTypeSlotType)
            {
                var memberArity = member is Symbol sym ? sym.TypeParameters.Count : 0;
                if(memberArity == requiredArity)
                {
                    // If it's a type alias, return the underlying type's display name.
                    if(member.DeclaredType is TypeAliasType alias)
                    {
                        return alias.UnderlyingType.DisplayName;
                    }

                    // Otherwise return the declared type's display name.
                    return member.DeclaredType?.DisplayName ?? slotName;
                }
            }

            // Nested type declarations (class/struct) with matching name and arity.
            if(member.Kind is SymbolKind.Class or SymbolKind.Struct)
            {
                var memberArity = member.DeclaredType switch
                {
                    ClassType ct => ct.TypeParameters.Count,
                    StructType st => st.TypeParameters.Count,
                    _ => 0
                };
                if(memberArity == requiredArity)
                {
                    // The nested type has the same name as the slot.
                    return member.Name;
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Validates that the implementing type provides concrete type members for all
    /// associated type slots declared in its abstracts (transitively).
    /// Emits <c>MIST_AT_0002</c> for each missing concrete type member.
    /// </summary>
    private static void ValidateAssociatedTypeSlotObligations(
        string typeName,
        IReadOnlyList<IType> abstracts,
        IScope memberScope,
        ClassType? classType,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Collect all associated type slots from the abstract type hierarchy.
        var requiredSlots = new List<(AbstractType Abstract, ISymbol SlotSymbol, AssociatedTypeSlotType SlotType)>();
        var visitedAbstracts = new HashSet<AbstractType>();
        CollectRequiredAssociatedTypeSlots(abstracts, requiredSlots, visitedAbstracts);

        foreach(var (requiredAbstract, slotSymbol, slotType) in requiredSlots)
        {
            var slotName = slotSymbol.Name;
            var slotArity = slotType.TypeParameters.Count;

            // Look for a matching concrete type member in the implementor's scope (by name and arity).
            var concreteType = FindConcreteTypeMemberType(slotName, slotArity, memberScope, classType);

            if(concreteType is null)
            {
                var sourceText = FindSourceTextForType(typeName, symbolTable);
                var declaringNode = FindDeclaringNodeForType(typeName, symbolTable);

                var message = $"Type '{typeName}' does not provide a concrete type for associated type slot '{slotName}' required by '{requiredAbstract.DisplayName}'";

                if(declaringNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        CommonDiagnostics.MissingAssociatedTypeMember.Id.Value,
                        DiagnosticSeverity.Error,
                        message,
                        declaringNode,
                        sourceText));
                }
                else
                {
                    var path = FindCompilationUnitPathForType(typeName, symbolTable, asts, compilation);

                    diagnostics.Add(new Diagnostic(
                        CommonDiagnostics.MissingAssociatedTypeMember.Id,
                        DiagnosticSeverity.Error,
                        PipelineStage.SemanticModelConstruction,
                        message,
                        Location: default,
                        CompilationUnitPath: path ?? "<unknown>",
                        AnalyzerName: null));
                }
            }
            else
            {
                // Concrete type member found — validate that it satisfies all constraints.
                ValidateAssociatedTypeConstraints(
                    concreteType, slotType, slotName, requiredAbstract,
                    typeName, symbolTable, asts, compilation, diagnostics);
            }
        }
    }

    /// <summary>
    /// Validates that a concrete type member satisfies all constraints declared on the
    /// associated type slot. Emits <c>MIST_AT_0003</c> for each unsatisfied constraint.
    /// </summary>
    private static void ValidateAssociatedTypeConstraints(
        IType concreteType,
        AssociatedTypeSlotType slotType,
        string slotName,
        AbstractType requiredAbstract,
        string implementorTypeName,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        var constraints = slotType.Constraints;
        if(constraints is null)
        {
            return;
        }

        var concreteTypeName = concreteType.DisplayName;
        var abstractName = requiredAbstract.DisplayName;

        // Check struct constraint: concrete type must be a struct.
        if(constraints.HasStructConstraint)
        {
            if(concreteType.Kind != TypeKind.Struct)
            {
                EmitUnsatisfiedConstraintDiagnostic(
                    concreteTypeName, "struct", slotName, abstractName,
                    implementorTypeName, concreteTypeName, symbolTable, asts, compilation, diagnostics);
            }
        }

        // Check class constraint: concrete type must be a class.
        if(constraints.HasClassConstraint)
        {
            if(concreteType.Kind != TypeKind.Class)
            {
                EmitUnsatisfiedConstraintDiagnostic(
                    concreteTypeName, "class", slotName, abstractName,
                    implementorTypeName, concreteTypeName, symbolTable, asts, compilation, diagnostics);
            }
        }

        // Check abstract type constraints: concrete type must implement each abstract type.
        foreach(var ifaceConstraint in constraints.AbstractConstraints)
        {
            if(!ConcreteTypeImplementsAbstract(concreteType, ifaceConstraint))
            {
                EmitUnsatisfiedConstraintDiagnostic(
                    concreteTypeName, ifaceConstraint.DisplayName, slotName, abstractName,
                    implementorTypeName, concreteTypeName, symbolTable, asts, compilation, diagnostics);
            }
        }

        // Check constructor constraints: concrete type must have a public parameterless constructor.
        foreach(var requiredParams in constraints.ConstructorConstraints)
        {
            if(requiredParams.Count == 0)
            {
                // new() constraint — check for public parameterless constructor.
                if(!HasPublicParameterlessConstructor(concreteType, symbolTable))
                {
                    EmitUnsatisfiedConstraintDiagnostic(
                        concreteTypeName, "new()", slotName, abstractName,
                        implementorTypeName, concreteTypeName, symbolTable, asts, compilation, diagnostics);
                }
            }
        }
    }

    /// <summary>
    /// Emits a <c>MIST_AT_0003</c> diagnostic for an unsatisfied constraint.
    /// The diagnostic location points to the concrete type member declaration.
    /// </summary>
    private static void EmitUnsatisfiedConstraintDiagnostic(
        string concreteTypeName,
        string constraintName,
        string slotName,
        string abstractName,
        string implementorTypeName,
        string concreteTypeSearchName,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        var message = $"Concrete type '{concreteTypeName}' does not satisfy constraint '{constraintName}' required by associated type slot '{slotName}' in '{abstractName}'";

        // Try to point the diagnostic at the concrete type member declaration.
        var declaringNode = FindDeclaringNodeForType(concreteTypeSearchName, symbolTable);
        var sourceText = FindSourceTextForType(concreteTypeSearchName, symbolTable);

        // If we can't find the concrete type's node, fall back to the implementor's node.
        if(declaringNode is null)
        {
            declaringNode = FindDeclaringNodeForType(implementorTypeName, symbolTable);
            sourceText = FindSourceTextForType(implementorTypeName, symbolTable);
        }

        if(declaringNode is not null)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                CommonDiagnostics.UnsatisfiedAssociatedTypeConstraint.Id.Value,
                DiagnosticSeverity.Error,
                message,
                declaringNode,
                sourceText));
        }
        else
        {
            var path = FindCompilationUnitPathForType(implementorTypeName, symbolTable, asts, compilation);

            diagnostics.Add(new Diagnostic(
                CommonDiagnostics.UnsatisfiedAssociatedTypeConstraint.Id,
                DiagnosticSeverity.Error,
                PipelineStage.SemanticModelConstruction,
                message,
                Location: default,
                CompilationUnitPath: path ?? "<unknown>",
                AnalyzerName: null));
        }
    }

    /// <summary>
    /// Checks whether a concrete type implements a given abstract type constraint.
    /// Handles both plain <see cref="AbstractType"/> and <see cref="ConstructedType"/> constraints.
    /// </summary>
    private static bool ConcreteTypeImplementsAbstract(IType concreteType, IType abstractConstraint)
    {
        var abstracts = concreteType switch
        {
            ClassType ct => ct.Abstracts,
            StructType st => st.Abstracts,
            _ => Array.Empty<IType>(),
        };

        // Walk the class base type chain for classes.
        if(concreteType is ClassType classType)
        {
            if(InterfaceListContainsConstraint(abstracts, abstractConstraint))
            {
                return true;
            }

            var ancestor = classType.BaseType as ClassType;
            while(ancestor is not null)
            {
                if(InterfaceListContainsConstraint(ancestor.Abstracts, abstractConstraint))
                {
                    return true;
                }

                ancestor = ancestor.BaseType as ClassType;
            }

            return false;
        }

        return InterfaceListContainsConstraint(abstracts, abstractConstraint);
    }

    /// <summary>
    /// Checks whether an abstract type list contains a match for the given abstract type constraint.
    /// Supports both plain <see cref="AbstractType"/> and <see cref="ConstructedType"/> matching.
    /// </summary>
    private static bool InterfaceListContainsConstraint(
        IReadOnlyList<IType> abstracts,
        IType constraint,
        HashSet<IType>? visited = null)
    {
        foreach(var ifaceType in abstracts)
        {
            if(InterfaceMatchesConstraint(ifaceType, constraint))
            {
                return true;
            }

            // Recursively check inherited abstract types.
            if(ifaceType is AbstractType iface)
            {
                visited ??= new HashSet<IType>(ReferenceEqualityComparer.Instance);
                if(visited.Add(iface))
                {
                    if(InterfaceListContainsConstraint(iface.Abstracts, constraint, visited))
                    {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether a single abstract type matches the given constraint.
    /// Handles ConstructedType matching by comparing generic definitions when
    /// the constraint contains type parameters (e.g., IEnumerator&lt;TElement&gt; matches IEnumerator&lt;int&gt;).
    /// </summary>
    private static bool InterfaceMatchesConstraint(IType ifaceType, IType constraint)
    {
        if(ReferenceEquals(ifaceType, constraint))
        {
            return true;
        }

        if(ifaceType.DisplayName == constraint.DisplayName)
        {
            return true;
        }

        // Handle constructed type matching (e.g., IEnumerator<int> matches IEnumerator<T>).
        if(constraint is AbstractType plainConstraint && ifaceType is AbstractType plainIface)
        {
            return ReferenceEquals(plainIface, plainConstraint) || plainIface.DisplayName == plainConstraint.DisplayName;
        }

        // Handle ConstructedType vs ConstructedType: match by generic definition.
        // This covers cases like IEnumerator<bool> matching constraint IEnumerator<TElement>
        // where TElement is a type parameter that should be substituted.
        if(constraint is ConstructedType constraintCt && ifaceType is ConstructedType ifaceCt)
        {
            if(ReferenceEquals(constraintCt.GenericDefinition, ifaceCt.GenericDefinition))
            {
                return true;
            }

            if(constraintCt.GenericDefinition.DisplayName == ifaceCt.GenericDefinition.DisplayName)
            {
                return true;
            }
        }

        // Handle ConstructedType matching a plain abstractType constraint by generic definition.
        if(constraint is ConstructedType constraintCt2 && ifaceType is AbstractType plainIface2)
        {
            if(ReferenceEquals(constraintCt2.GenericDefinition, plainIface2))
            {
                return true;
            }
        }

        if(constraint is AbstractType plainConstraint2 && ifaceType is ConstructedType ifaceCt2)
        {
            if(ReferenceEquals(ifaceCt2.GenericDefinition, plainConstraint2))
            {
                return true;
            }
        }

        return false;
    }


    /// <summary>
    /// Checks whether a concrete type has a public parameterless constructor.
    /// Structs always have an implicit parameterless constructor.
    /// Classes with no declared constructors have an implicit public parameterless constructor.
    /// </summary>
    private static bool HasPublicParameterlessConstructor(IType concreteType, SymbolTable symbolTable)
    {
        // Structs always have a parameterless constructor.
        if(concreteType.Kind == TypeKind.Struct)
        {
            return true;
        }

        // Collect constructors from the type's member scope.
        var memberScope = concreteType switch
        {
            ClassType ct => ct.MemberScope,
            StructType st => st.MemberScope,
            _ => null,
        };

        if(memberScope is null)
        {
            return false;
        }

        var constructors = memberScope.Members
            .Where(m => m.Kind == SymbolKind.Constructor)
            .ToList();

        // If no constructors are declared, the type has an implicit public parameterless constructor.
        if(constructors.Count == 0)
        {
            return true;
        }

        // Check if any declared constructor is public and parameterless.
        foreach(var ctor in constructors)
        {
            var ctorNode = symbolTable.GetDeclaringNode(ctor);
            if(ctorNode is ConstructorDeclarationNode ctorDecl && ctorDecl.Parameters is null)
            {
                // Check if it's public.
                if(IsMemberPublic(ctor, symbolTable))
                {
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Recursively collects all associated type slots from the abstract type hierarchy.
    /// Handles both raw <see cref="AbstractType"/> and <see cref="ConstructedType"/>
    /// (generic abstract types like <c>IEnumerable&lt;int&gt;</c>).
    /// </summary>
    private static void CollectRequiredAssociatedTypeSlots(
        IReadOnlyList<IType> abstracts,
        List<(AbstractType Abstract, ISymbol SlotSymbol, AssociatedTypeSlotType SlotType)> requiredSlots,
        HashSet<AbstractType> visited)
    {
        foreach(var ifaceType in abstracts)
        {
            // Unwrap ConstructedType to get the underlying AbstractType for generic
            // abstracts (e.g., IEnumerable<int> is a ConstructedType wrapping AbstractType).
            var iface = ifaceType switch
            {
                AbstractType directIface => directIface,
                ConstructedType { GenericDefinition: AbstractType genericIface } => genericIface,
                _ => null,
            };

            if(iface is null)
            {
                continue;
            }

            if(!visited.Add(iface))
            {
                continue;
            }

            // Find all associated type slot members in this abstract type.
            foreach(var member in iface.MemberScope.Members)
            {
                if(member.Kind == SymbolKind.TypeAlias && member.DeclaredType is AssociatedTypeSlotType slotType)
                {
                    requiredSlots.Add((iface, member, slotType));
                }
            }

            // Recurse into parent abstract types.
            if(iface.Abstracts.Count > 0)
            {
                CollectRequiredAssociatedTypeSlots(iface.Abstracts, requiredSlots, visited);
            }
        }
    }

    /// <summary>
    /// Searches the implementing type's member scope (and base type chain for classes)
    /// for a concrete type member matching the given name and arity.
    /// A concrete type member is a <see cref="SymbolKind.TypeAlias"/> whose
    /// <see cref="ISymbol.DeclaredType"/> is NOT an <see cref="AssociatedTypeSlotType"/>.
    /// Returns the resolved concrete type, or <c>null</c> if not found.
    /// </summary>
    private static IType? FindConcreteTypeMemberType(
        string slotName,
        int requiredArity,
        IScope memberScope,
        ClassType? classType)
    {
        // Search the direct member scope.
        var result = SearchScopeForConcreteTypeMemberType(slotName, requiredArity, memberScope);
        if(result is not null)
        {
            return result;
        }

        // For classes, walk the base type chain.
        if(classType is not null)
        {
            var ancestor = classType.BaseType as ClassType;
            while(ancestor is not null)
            {
                result = SearchScopeForConcreteTypeMemberType(slotName, requiredArity, ancestor.MemberScope);
                if(result is not null)
                {
                    return result;
                }

                ancestor = ancestor.BaseType as ClassType;
            }
        }

        return null;
    }

    /// <summary>
    /// Searches a single scope for a concrete type member with the given name and arity.
    /// Returns the resolved concrete type, or <c>null</c> if not found.
    /// </summary>
    private static IType? SearchScopeForConcreteTypeMemberType(string slotName, int requiredArity, IScope scope)
    {
        foreach(var member in scope.Members)
        {
            if(member.Name != slotName)
            {
                continue;
            }

            // Must be a type alias that is NOT an associated type slot (i.e., it's a concrete type).
            if(member.Kind == SymbolKind.TypeAlias && member.DeclaredType is not AssociatedTypeSlotType)
            {
                // Check arity: the concrete type member must have the same number of type parameters.
                var memberArity = member is Symbol sym ? sym.TypeParameters.Count : 0;
                if(memberArity == requiredArity)
                {
                    // Unwrap type alias to get the underlying type.
                    return member.DeclaredType is TypeAliasType alias ? alias.UnderlyingType : member.DeclaredType;
                }
            }

            // Also accept nested type declarations (class/struct) with matching name and arity.
            if(member.Kind is SymbolKind.Class or SymbolKind.Struct)
            {
                var memberArity = member.DeclaredType switch
                {
                    ClassType ct => ct.TypeParameters.Count,
                    StructType st => st.TypeParameters.Count,
                    _ => 0
                };
                if(memberArity == requiredArity)
                {
                    return member.DeclaredType;
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Recursively collects all required methods and properties from the abstract type hierarchy,
    /// using a visited set to handle diamond inheritance. Handles both raw <see cref="AbstractType"/>
    /// and <see cref="ConstructedType"/> (generic abstract types like <c>IEnumerator&lt;int&gt;</c>).
    /// <para>
    /// For <see cref="ConstructedType"/> abstracts, methods whose signatures reference the
    /// abstract type's type parameters are still collected — the caller's substitution map
    /// (built by <see cref="BuildAssociatedTypeSubstitutionMap"/>) handles the matching.
    /// </para>
    /// </summary>
    private static void CollectRequiredMembers(
        IReadOnlyList<IType> abstracts,
        List<(AbstractType Abstract, ISymbol Method)> requiredMethods,
        List<(AbstractType Abstract, ISymbol Property)> requiredProperties,
        HashSet<AbstractType> visited)
    {
        foreach(var ifaceType in abstracts)
        {
            // Unwrap ConstructedType to get the underlying AbstractType for generic
            // abstracts (e.g., IEnumerator<int> is a ConstructedType wrapping AbstractType).
            var iface = ifaceType switch
            {
                AbstractType directIface => directIface,
                ConstructedType { GenericDefinition: AbstractType genericIface } => genericIface,
                _ => null,
            };

            if(iface is null)
            {
                continue;
            }

            if(!visited.Add(iface))
            {
                continue;
            }

            // Add all method and property members from this abstract type.
            // Default methods (those with bodies, recorded in DefaultMethods) are
            // EXCLUDED from required slots — implementers may omit them because the
            // default fills the slot. A same-named non-default overload (a true slot)
            // is still required, so we compare by symbol identity rather than by name.
            foreach(var member in iface.MemberScope.Members)
            {
                if(member.Kind == SymbolKind.Method)
                {
                    if(iface.DefaultMethods.TryGetValue(member.Name, out var defaultSymbol)
                        && ReferenceEquals(defaultSymbol, member))
                    {
                        // This method has a default implementation — not a required slot.
                        continue;
                    }

                    requiredMethods.Add((iface, member));
                }
                else if(member.Kind == SymbolKind.Property)
                {
                    requiredProperties.Add((iface, member));
                }
            }

            // Recurse into parent abstract types.
            if(iface.Abstracts.Count > 0)
            {
                CollectRequiredMembers(iface.Abstracts, requiredMethods, requiredProperties, visited);
            }
        }
    }

    /// <summary>
    /// Searches the implementing type's member scope (and base type chain for
    /// classes) for a property with the given name.
    /// </summary>
    private static ISymbol? FindMatchingProperty(
        string propertyName,
        IScope memberScope,
        ClassType? classType)
    {
        // Search the direct member scope first.
        foreach(var member in memberScope.Members)
        {
            if(member.Kind == SymbolKind.Property && member.Name == propertyName)
            {
                return member;
            }
        }

        // For classes, walk the base type chain.
        if(classType is not null)
        {
            var ancestor = classType.BaseType as ClassType;
            while(ancestor is not null)
            {
                foreach(var member in ancestor.MemberScope.Members)
                {
                    if(member.Kind == SymbolKind.Property && member.Name == propertyName)
                    {
                        return member;
                    }
                }

                ancestor = ancestor.BaseType as ClassType;
            }
        }

        return null;
    }

    /// <summary>
    /// Result of searching for a matching method implementation.
    /// </summary>
    private abstract record MethodMatchResult
    {
        public static readonly MethodMatchResult Missing = new MissingResult();

        public static MethodMatchResult Match(ISymbol implSymbol)
        {
            return new MatchedResult(implSymbol);
        }

        public static MethodMatchResult Mismatch(string expectedSig, string actualSig)
        {
            return new SignatureMismatch(expectedSig, actualSig);
        }

        public static MethodMatchResult RefKindMismatch(string implMethodName, string abstractMethodName)
        {
            return new RefKindMismatchResult(implMethodName, abstractMethodName);
        }

        public sealed record MatchedResult(ISymbol ImplSymbol) : MethodMatchResult;
        public sealed record MissingResult : MethodMatchResult;
        public sealed record SignatureMismatch(string ExpectedSig, string ActualSig) : MethodMatchResult;
        public sealed record RefKindMismatchResult(string ImplMethodName, string AbstractMethodName) : MethodMatchResult;
    }

    /// <summary>
    /// Searches the implementing type's member scope (and base type chain for
    /// classes) for a method matching the required abstract type method.
    /// With overloading, we must check all scopes in the chain — a matching
    /// overload might be in a base class even if the derived class has methods
    /// with the same name but different signatures.
    /// </summary>
    private static MethodMatchResult FindMatchingMethod(
        string methodName,
        MethodDeclarationNode requiredMethodDecl,
        IScope memberScope,
        ClassType? classType,
        SymbolTable symbolTable,
        Dictionary<string, HashSet<string>>? associatedTypeSubstitutions = null)
    {
        // Track whether we found any method with the same name across all scopes.
        var foundAnyWithName = false;
        string? lastMismatchExpected = null;
        string? lastMismatchActual = null;
        MethodMatchResult.RefKindMismatchResult? refKindMismatch = null;

        // Search the direct member scope first.
        var result = SearchScopeForMethod(methodName, requiredMethodDecl, memberScope, symbolTable, associatedTypeSubstitutions);
        if(result is MethodMatchResult.MatchedResult)
        {
            return result;
        }

        if(result is MethodMatchResult.RefKindMismatchResult directRefKindMismatch)
        {
            foundAnyWithName = true;
            refKindMismatch = directRefKindMismatch;
        }
        else if(result is MethodMatchResult.SignatureMismatch directMismatch)
        {
            foundAnyWithName = true;
            lastMismatchExpected = directMismatch.ExpectedSig;
            lastMismatchActual = directMismatch.ActualSig;
        }

        // For classes, walk the base type chain.
        if(classType is not null)
        {
            var ancestor = classType.BaseType as ClassType;
            while(ancestor is not null)
            {
                result = SearchScopeForMethod(methodName, requiredMethodDecl, ancestor.MemberScope, symbolTable, associatedTypeSubstitutions);
                if(result is MethodMatchResult.MatchedResult)
                {
                    return result;
                }

                if(result is MethodMatchResult.RefKindMismatchResult ancestorRefKindMismatch)
                {
                    foundAnyWithName = true;
                    refKindMismatch ??= ancestorRefKindMismatch;
                }
                else if(result is MethodMatchResult.SignatureMismatch ancestorMismatch)
                {
                    foundAnyWithName = true;
                    lastMismatchExpected = ancestorMismatch.ExpectedSig;
                    lastMismatchActual = ancestorMismatch.ActualSig;
                }

                ancestor = ancestor.BaseType as ClassType;
            }
        }

        if(foundAnyWithName)
        {
            // Prefer the specific RefKind mismatch over generic signature mismatch.
            if(refKindMismatch is not null)
            {
                return refKindMismatch;
            }

            return MethodMatchResult.Mismatch(lastMismatchExpected!, lastMismatchActual!);
        }

        return MethodMatchResult.Missing;
    }

    /// <summary>
    /// Searches a single scope for a method with the given name and checks
    /// whether any overload's signature matches the required abstract type method.
    /// With overloading, multiple methods may share the same name — we must
    /// check all of them before concluding there is no match.
    /// </summary>
    private static MethodMatchResult SearchScopeForMethod(
        string methodName,
        MethodDeclarationNode requiredMethodDecl,
        IScope scope,
        SymbolTable symbolTable,
        Dictionary<string, HashSet<string>>? associatedTypeSubstitutions = null)
    {
        var foundAnyWithName = false;
        string? lastActualSig = null;
        string? refKindMismatchImplName = null;
        string? refKindMismatchAbstractName = null;

        foreach(var member in scope.Members)
        {
            if(member.Kind != SymbolKind.Method || member.Name != methodName)
            {
                continue;
            }

            foundAnyWithName = true;

            // Found a method with the same name. Check signature.
            var memberNode = symbolTable.GetDeclaringNode(member);
            if(memberNode is not MethodDeclarationNode implMethodDecl)
            {
                continue;
            }

            if(SignaturesMatch(requiredMethodDecl, implMethodDecl, associatedTypeSubstitutions))
            {
                return MethodMatchResult.Match(member);
            }

            // Check if types match but RefKind values differ (for MIST_REF_0012).
            if(TypesMatchButRefKindsDiffer(requiredMethodDecl, implMethodDecl, associatedTypeSubstitutions))
            {
                refKindMismatchImplName = member.Name;
                refKindMismatchAbstractName = methodName;
            }

            // Track the last seen actual signature for diagnostic purposes.
            lastActualSig = FormatMethodSignature(implMethodDecl);
        }

        if(foundAnyWithName)
        {
            // Prefer the specific RefKind mismatch result over generic signature mismatch.
            if(refKindMismatchImplName is not null)
            {
                return MethodMatchResult.RefKindMismatch(refKindMismatchImplName, refKindMismatchAbstractName!);
            }

            // Name matches but no overload has a matching signature.
            var expectedSig = FormatInterfaceMethodSignature(requiredMethodDecl);
            return MethodMatchResult.Mismatch(expectedSig, lastActualSig ?? "()");
        }

        return MethodMatchResult.Missing;
    }

    /// <summary>
    /// Checks whether an implementing method's signature matches the required
    /// abstract type method's signature (return type, parameter types, and parameter ref kinds).
    /// When associated type substitutions are provided, type references to associated
    /// type slot names in the abstract type signature are matched against the concrete type
    /// member names in the implementor's signature.
    /// </summary>
    private static bool SignaturesMatch(
        MethodDeclarationNode required,
        MethodDeclarationNode actual,
        Dictionary<string, HashSet<string>>? associatedTypeSubstitutions = null)
    {
        // Compare return types.
        if(!TypeReferencesMatchWithAssociatedTypes(required.ReturnType, actual.ReturnType, associatedTypeSubstitutions))
        {
            return false;
        }

        // Compare parameter types.
        var requiredParams = ExtractParameterTypes(required.Parameters);
        var actualParams = ExtractParameterTypes(actual.Parameters);

        if(requiredParams.Count != actualParams.Count)
        {
            return false;
        }

        for(var i = 0; i < requiredParams.Count; i++)
        {
            if(!TypeReferencesMatchWithAssociatedTypes(requiredParams[i], actualParams[i], associatedTypeSubstitutions))
            {
                return false;
            }
        }

        // Compare parameter RefKind values (Requirement 7.5).
        if(!ParameterRefKindsMatch(required.Parameters, actual.Parameters))
        {
            return false;
        }

        return true;
    }

    /// <summary>
    /// Checks whether two methods have matching types but mismatched RefKind values
    /// on one or more parameters. Used to emit the specific MIST_REF_0012 diagnostic.
    /// Returns true if types match but RefKind values differ.
    /// </summary>
    private static bool TypesMatchButRefKindsDiffer(
        MethodDeclarationNode required,
        MethodDeclarationNode actual,
        Dictionary<string, HashSet<string>>? associatedTypeSubstitutions = null)
    {
        // Check return types match.
        if(!TypeReferencesMatchWithAssociatedTypes(required.ReturnType, actual.ReturnType, associatedTypeSubstitutions))
        {
            return false;
        }

        // Check parameter types match.
        var requiredParams = ExtractParameterTypes(required.Parameters);
        var actualParams = ExtractParameterTypes(actual.Parameters);

        if(requiredParams.Count != actualParams.Count)
        {
            return false;
        }

        for(var i = 0; i < requiredParams.Count; i++)
        {
            if(!TypeReferencesMatchWithAssociatedTypes(requiredParams[i], actualParams[i], associatedTypeSubstitutions))
            {
                return false;
            }
        }

        // Types match — now check if RefKind values differ.
        return !ParameterRefKindsMatch(required.Parameters, actual.Parameters);
    }

    /// <summary>
    /// Compares the RefKind values of parameters between an abstract type method and
    /// an implementing method. Returns true if all parameter RefKind values match.
    /// </summary>
    private static bool ParameterRefKindsMatch(
        ParameterListNode? requiredParams,
        ParameterListNode? actualParams)
    {
        var requiredRefKinds = ExtractParameterRefKinds(requiredParams);
        var actualRefKinds = ExtractParameterRefKinds(actualParams);

        if(requiredRefKinds.Count != actualRefKinds.Count)
        {
            return false;
        }

        for(var i = 0; i < requiredRefKinds.Count; i++)
        {
            if(requiredRefKinds[i] != actualRefKinds[i])
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Extracts the RefKind for each parameter from a parameter list node based on
    /// the presence of the refModifier AST field.
    /// </summary>
    private static List<RefKind> ExtractParameterRefKinds(ParameterListNode? paramList)
    {
        var refKinds = new List<RefKind>();
        if(paramList is null)
        {
            return refKinds;
        }

        foreach(var child in paramList.Children())
        {
            if(child is ParameterNode param)
            {
                if(param.RefModifier is not null)
                {
                    // readonly ref → RefReadonly; bare ref → Ref
                    refKinds.Add(param.Modifier is not null ? RefKind.RefReadonly : RefKind.Ref);
                }
                else
                {
                    refKinds.Add(RefKind.None);
                }
            }
        }

        return refKinds;
    }

    /// <summary>
    /// Extracts the list of parameter type references from a parameter list node.
    /// </summary>
    private static List<TypeReferenceNode> ExtractParameterTypes(ParameterListNode? paramList)
    {
        var types = new List<TypeReferenceNode>();
        if(paramList is null)
        {
            return types;
        }

        foreach(var child in paramList.Children())
        {
            if(child is ParameterNode param)
            {
                types.Add(param.Type);
            }
        }

        return types;
    }

    /// <summary>
    /// Compares two TypeReferenceNode instances for structural equality.
    /// Two <c>unknown</c> references match each other (Requirement 12.3 —
    /// parameter positions require exact unknown-to-unknown match).
    /// </summary>
    private static bool TypeReferencesMatch(TypeReferenceNode a, TypeReferenceNode b)
    {
        // Unions (non-empty SingleTypeRefs continuation) never structurally match
        // here — the pre-restructure code represented them as a distinct
        // union node variant that fell through to the `_ => false` arm.
        if(a.SingleTypeRefs.Length > 0 || b.SingleTypeRefs.Length > 0)
        {
            return false;
        }

        return (a.First, b.First) switch
        {
            (VoidSingleTypeRefSingleTypeRefNode, VoidSingleTypeRefSingleTypeRefNode) => true,

            (PrimitiveSingleTypeRefSingleTypeRefNode pa, PrimitiveSingleTypeRefSingleTypeRefNode pb) =>
                PrimitiveTypesMatch(pa.PrimitiveType, pb.PrimitiveType)
                && (pa.ArrayRank is not null) == (pb.ArrayRank is not null),

            (NamedSingleTypeRefSingleTypeRefNode na, NamedSingleTypeRefSingleTypeRefNode nb) =>
                na.Name.IDENTIFIER.Lexeme == nb.Name.IDENTIFIER.Lexeme
                && (na.ArrayRank is not null) == (nb.ArrayRank is not null),

            // Two `unknown` references match each other exactly. This is
            // required for both abstract type return positions (where `unknown`
            // in both sides trivially satisfies Req 12.1) and abstract type
            // parameter positions (Req 12.3 — `unknown` in an abstract type
            // parameter requires exactly `unknown` in the implementer).
            (UnknownSingleTypeRefSingleTypeRefNode, UnknownSingleTypeRefSingleTypeRefNode) => true,

            // Two tuple type references match if they have the same arity
            // and each element type reference matches (names are ignored
            // for structural matching, consistent with name-erasure semantics).
            (TupleSingleTypeRefSingleTypeRefNode ta, TupleSingleTypeRefSingleTypeRefNode tb) =>
                TupleTypeReferencesMatch(ta, tb),

            // A named type ref could match a primitive type ref if someone
            // uses the type name form (e.g., "string" as named vs primitive).
            // In practice the parser produces consistent node types, so
            // cross-kind comparisons are mismatches.
            _ => false,
        };
    }

    /// <summary>
    /// Compares two <see cref="TupleSingleTypeRefSingleTypeRefNode"/> instances for
    /// structural equivalence: same arity and each element type reference matches.
    /// Element names are ignored (name-erasure semantics).
    /// </summary>
    private static bool TupleTypeReferencesMatch(
        TupleSingleTypeRefSingleTypeRefNode a, TupleSingleTypeRefSingleTypeRefNode b)
    {
        // Check arity: both must have the same number of additional elements.
        if(a.TupleTypeElements.Length != b.TupleTypeElements.Length)
        {
            return false;
        }

        // Compare First elements.
        if(!TypeReferencesMatch(a.First.Type, b.First.Type))
        {
            return false;
        }

        // Compare Rest elements.
        if(!TypeReferencesMatch(a.Rest.Type, b.Rest.Type))
        {
            return false;
        }

        // Compare additional elements.
        for(var i = 0; i < a.TupleTypeElements.Length; i++)
        {
            if(!TypeReferencesMatch(a.TupleTypeElements[i].Type, b.TupleTypeElements[i].Type))
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Compares two type references with associated type substitution support.
    /// When the abstract type type reference is a named type that matches an associated
    /// type slot name, the implementor's type reference is checked against the set
    /// of acceptable concrete type names for that slot.
    /// </summary>
    private static bool TypeReferencesMatchWithAssociatedTypes(
        TypeReferenceNode abstractRef,
        TypeReferenceNode implRef,
        Dictionary<string, HashSet<string>>? associatedTypeSubstitutions)
    {
        // If no substitutions are provided, fall back to standard comparison.
        if(associatedTypeSubstitutions is null || associatedTypeSubstitutions.Count == 0)
        {
            return TypeReferencesMatch(abstractRef, implRef);
        }

        // Check if the abstract type reference is a named type that matches a slot name.
        if(abstractRef.First is NamedSingleTypeRefSingleTypeRefNode namedAbstract)
        {
            var abstractName = namedAbstract.Name.IDENTIFIER.Lexeme;
            if(!string.IsNullOrEmpty(abstractName)
                && associatedTypeSubstitutions.TryGetValue(abstractName, out var acceptableNames))
            {
                // The abstract type reference is an associated type slot or type parameter reference.
                // The implementor must use one of the acceptable concrete type names.
                if(implRef.First is NamedSingleTypeRefSingleTypeRefNode namedImpl)
                {
                    var implName = namedImpl.Name.IDENTIFIER.Lexeme;
                    return !string.IsNullOrEmpty(implName)
                        && acceptableNames.Contains(implName)
                        && (namedAbstract.ArrayRank is not null) == (namedImpl.ArrayRank is not null);
                }

                // Handle primitive type references (e.g., int, string, bool) on the impl side.
                if(implRef.First is PrimitiveSingleTypeRefSingleTypeRefNode primitiveImpl)
                {
                    var primitiveName = FormatPrimitiveType(primitiveImpl.PrimitiveType);
                    return !string.IsNullOrEmpty(primitiveName)
                        && acceptableNames.Contains(primitiveName)
                        && (namedAbstract.ArrayRank is not null) == (primitiveImpl.ArrayRank is not null);
                }

                return false;
            }
        }

        // For non-slot type references, use the standard comparison.
        return TypeReferencesMatch(abstractRef, implRef);
    }



    /// <summary>
    /// Compares two PrimitiveTypeNode instances for equality by variant type.
    /// </summary>
    private static bool PrimitiveTypesMatch(PrimitiveTypeNode a, PrimitiveTypeNode b)
    {
        return (a, b) switch
        {
            (IntTypePrimitiveTypeNode, IntTypePrimitiveTypeNode) => true,
            (UintTypePrimitiveTypeNode, UintTypePrimitiveTypeNode) => true,
            (LongTypePrimitiveTypeNode, LongTypePrimitiveTypeNode) => true,
            (UlongTypePrimitiveTypeNode, UlongTypePrimitiveTypeNode) => true,
            (ShortTypePrimitiveTypeNode, ShortTypePrimitiveTypeNode) => true,
            (UshortTypePrimitiveTypeNode, UshortTypePrimitiveTypeNode) => true,
            (ByteTypePrimitiveTypeNode, ByteTypePrimitiveTypeNode) => true,
            (SbyteTypePrimitiveTypeNode, SbyteTypePrimitiveTypeNode) => true,
            (FloatTypePrimitiveTypeNode, FloatTypePrimitiveTypeNode) => true,
            (DoubleTypePrimitiveTypeNode, DoubleTypePrimitiveTypeNode) => true,
            (DecimalTypePrimitiveTypeNode, DecimalTypePrimitiveTypeNode) => true,
            (BoolTypePrimitiveTypeNode, BoolTypePrimitiveTypeNode) => true,
            (CharTypePrimitiveTypeNode, CharTypePrimitiveTypeNode) => true,
            (StringTypePrimitiveTypeNode, StringTypePrimitiveTypeNode) => true,
            (RegexTypePrimitiveTypeNode, RegexTypePrimitiveTypeNode) => true,
            _ => false,
        };
    }

    /// <summary>
    /// Formats an abstract type method signature as a string for diagnostic messages.
    /// Format: "returnType(paramType1, paramType2, ...)"
    /// </summary>
    private static string FormatInterfaceMethodSignature(MethodDeclarationNode methodDecl)
    {
        var returnType = FormatTypeReference(methodDecl.ReturnType);
        var paramTypes = FormatParameterTypes(methodDecl.Parameters);
        return $"{returnType}({paramTypes})";
    }

    /// <summary>
    /// Formats a method signature as a string for diagnostic messages.
    /// Format: "returnType(paramType1, paramType2, ...)"
    /// </summary>
    private static string FormatMethodSignature(MethodDeclarationNode methodDecl)
    {
        var returnType = FormatTypeReference(methodDecl.ReturnType);
        var paramTypes = FormatParameterTypes(methodDecl.Parameters);
        return $"{returnType}({paramTypes})";
    }

    /// <summary>
    /// Formats a parameter list as a comma-separated string of type names.
    /// </summary>
    private static string FormatParameterTypes(ParameterListNode? paramList)
    {
        if(paramList is null)
        {
            return "";
        }

        var types = new List<string>();
        foreach(var child in paramList.Children())
        {
            if(child is ParameterNode param)
            {
                types.Add(FormatTypeReference(param.Type));
            }
        }

        return string.Join(", ", types);
    }

    /// <summary>
    /// Formats a TypeReferenceNode as a human-readable string.
    /// </summary>
    private static string FormatTypeReference(TypeReferenceNode typeRef)
    {
        // Unions render their constituents joined by " | " (preserved from the
        // pre-restructure behaviour where unions were a distinct node type that
        // fell through to "unknown"; render them explicitly now).
        if(typeRef.SingleTypeRefs.Length > 0)
        {
            var constituents = new List<string> { FormatSingleTypeRef(typeRef.First) };
            foreach(var rest in typeRef.SingleTypeRefs)
            {
                constituents.Add(FormatSingleTypeRef(rest));
            }

            return string.Join(" | ", constituents);
        }

        return FormatSingleTypeRef(typeRef.First);
    }

    /// <summary>
    /// Formats a single <see cref="SingleTypeRefNode"/> constituent as a
    /// human-readable string.
    /// </summary>
    private static string FormatSingleTypeRef(SingleTypeRefNode singleRef)
    {
        return singleRef switch
        {
            VoidSingleTypeRefSingleTypeRefNode => "void",
            PrimitiveSingleTypeRefSingleTypeRefNode p =>
                FormatPrimitiveType(p.PrimitiveType) + (p.ArrayRank is not null ? "[]" : ""),
            NamedSingleTypeRefSingleTypeRefNode n =>
                n.Name.IDENTIFIER.Lexeme + (n.ArrayRank is not null ? "[]" : ""),
            TupleSingleTypeRefSingleTypeRefNode t => FormatTupleTypeReference(t),
            _ => "unknown",
        };
    }

    /// <summary>
    /// Formats a <see cref="TupleSingleTypeRefSingleTypeRefNode"/> as a human-readable
    /// string of the form <c>(T1, T2)</c> or <c>(T1 name1, T2 name2)</c>.
    /// </summary>
    private static string FormatTupleTypeReference(TupleSingleTypeRefSingleTypeRefNode tupleRef)
    {
        var parts = new List<string>
        {
            // Format First element.
            FormatTupleElement(tupleRef.First),

            // Format Rest element.
            FormatTupleElement(tupleRef.Rest)
        };

        // Format additional elements.
        foreach(var additional in tupleRef.TupleTypeElements)
        {
            parts.Add(FormatTupleElement(additional));
        }

        return $"({string.Join(", ", parts)})";
    }

    /// <summary>
    /// Formats a single <see cref="TupleTypeElementNode"/> as <c>Type</c> or <c>Type name</c>.
    /// </summary>
    private static string FormatTupleElement(TupleTypeElementNode element)
    {
        var typeStr = FormatTypeReference(element.Type);
        var name = element.Name?.Lexeme;
        return name is not null ? $"{typeStr} {name}" : typeStr;
    }

    /// <summary>
    /// Formats a PrimitiveTypeNode as a keyword string.
    /// </summary>
    private static string FormatPrimitiveType(PrimitiveTypeNode node)
    {
        return node switch
        {
            IntTypePrimitiveTypeNode => "int",
            UintTypePrimitiveTypeNode => "uint",
            LongTypePrimitiveTypeNode => "long",
            UlongTypePrimitiveTypeNode => "ulong",
            ShortTypePrimitiveTypeNode => "short",
            UshortTypePrimitiveTypeNode => "ushort",
            ByteTypePrimitiveTypeNode => "byte",
            SbyteTypePrimitiveTypeNode => "sbyte",
            FloatTypePrimitiveTypeNode => "float",
            DoubleTypePrimitiveTypeNode => "double",
            DecimalTypePrimitiveTypeNode => "decimal",
            BoolTypePrimitiveTypeNode => "bool",
            CharTypePrimitiveTypeNode => "char",
            StringTypePrimitiveTypeNode => "string",
            RegexTypePrimitiveTypeNode => "regex",
            _ => "unknown",
        };
    }

    /// <summary>
    /// Finds the compilation unit path for a type by its display name.
    /// </summary>
    private static string? FindCompilationUnitPathForType(
        string typeName,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if((symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.Enum)
                && symbol.Name == typeName)
            {
                return FindCompilationUnitPathForSymbol(symbol, symbolTable, asts, compilation);
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the <see cref="SourceText"/> for a type by its display name.
    /// </summary>
    private static SourceText? FindSourceTextForType(
        string typeName,
        SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if((symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.Enum)
                && symbol.Name == typeName)
            {
                return GetSourceTextForSymbol(symbol, symbolTable);
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the declaring <see cref="Storm.Runtime.SyntaxNode"/> for a type by its display name.
    /// </summary>
    private static Storm.Runtime.SyntaxNode? FindDeclaringNodeForType(
        string typeName,
        SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if((symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.Enum)
                && symbol.Name == typeName)
            {
                return symbolTable.GetDeclaringNode(symbol);
            }
        }

        return null;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1e — Check for member redeclarations in derived classes
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After base types are resolved and cycles are broken, walk each class's
    /// ancestor chain to enforce the additive-only constraint: a derived class
    /// cannot redeclare a field or method that already exists in any ancestor.
    /// For methods, same name with a different parameter signature is a valid
    /// overload (not a redeclaration). Only same name AND identical parameter
    /// signature is flagged as a redeclaration error. Constructors are skipped
    /// because they do not inherit across the class hierarchy.
    /// </summary>
    private static void Pass1_CheckMemberRedeclarations(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Class || symbol.DeclaredType is not ClassType classType)
            {
                continue;
            }

            if(classType.BaseType is null)
            {
                continue;
            }

            // Collect the names of members declared directly on this class.
            foreach(var member in classType.MemberScope.Members)
            {
                // Only check fields and methods (not constructors, parameters, etc.)
                // Constructors don't inherit, so they are never redeclarations.
                if(member.Kind is not SymbolKind.Field and not SymbolKind.Method)
                {
                    continue;
                }

                // For methods, extract the parameter signature so we can distinguish
                // overloads (same name, different signature) from true redeclarations
                // (same name AND same signature).
                IReadOnlyList<IType>? memberSignature = null;
                IReadOnlyList<RefKind>? memberRefKinds = null;
                if(member.Kind == SymbolKind.Method)
                {
                    memberSignature = ParameterSignature.Extract(member, symbolTable);
                    memberRefKinds = ParameterSignature.ExtractRefKinds(member, symbolTable);
                }

                // Walk the ancestor chain looking for a member with the same name.
                var ancestor = classType.BaseType as ClassType;
                while(ancestor is not null)
                {
                    foreach(var ancestorMember in ancestor.MemberScope.Members)
                    {
                        if(ancestorMember.Name != member.Name)
                        {
                            continue;
                        }

                        // Fields use name-only matching (unchanged behavior).
                        if(member.Kind == SymbolKind.Field && ancestorMember.Kind == SymbolKind.Field)
                        {
                            EmitRedeclarationDiagnostic(classType, member, ancestor, symbolTable, asts, compilation, diagnostics);
                            goto nextMember;
                        }

                        // Methods: only a redeclaration if the parameter signatures match.
                        // Same name with a different signature is a valid overload.
                        if(member.Kind == SymbolKind.Method && ancestorMember.Kind == SymbolKind.Method)
                        {
                            var ancestorSignature = ParameterSignature.Extract(ancestorMember, symbolTable);
                            var ancestorRefKinds = ParameterSignature.ExtractRefKinds(ancestorMember, symbolTable);
                            if(ParameterSignature.AreEqualWithRefKind(
                                memberSignature!, memberRefKinds!, ancestorSignature, ancestorRefKinds))
                            {
                                // If the ancestor method is virtual/abstract (a CLR override slot),
                                // this is not a redeclaration — it's an implicit override that the
                                // C# emitter will handle by emitting `override`.
                                if(ancestorMember is Symbol ancestorSym && ancestorSym.IsVirtualOrAbstract)
                                {
                                    goto nextMember;
                                }

                                EmitRedeclarationDiagnostic(classType, member, ancestor, symbolTable, asts, compilation, diagnostics);
                                goto nextMember;
                            }
                            // Different signature — valid overload, keep checking other ancestors.
                            continue;
                        }

                        // Cross-kind conflict (e.g. field in derived vs method in base with same name).
                        if(ancestorMember.Kind is SymbolKind.Field or SymbolKind.Method)
                        {
                            EmitRedeclarationDiagnostic(classType, member, ancestor, symbolTable, asts, compilation, diagnostics);
                            goto nextMember;
                        }
                    }

                    ancestor = ancestor.BaseType as ClassType;
                }

                nextMember:;
            }
        }
    }

    /// <summary>
    /// Emits a <c>MIST_MEMBER_REDECLARATION</c> diagnostic for a member that
    /// conflicts with an ancestor member.
    /// </summary>
    private static void EmitRedeclarationDiagnostic(
        ClassType classType,
        ISymbol member,
        ClassType ancestor,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        var memberNode = symbolTable.GetDeclaringNode(member);
        var redeclSourceText = FindSourceTextForClassType(
            classType, symbolTable);

        if(memberNode is not null)
        {
            LinePositionSpan redeclLocation = default;
            var redeclPath = redeclSourceText?.Path ?? "<unknown>";
            if(redeclSourceText is not null && memberNode.Span.Length > 0)
            {
                var mistSpan = new SourceSpan(memberNode.Span.Start, memberNode.Span.Length);
                redeclLocation = redeclSourceText.ToLinePositionSpan(mistSpan);
            }

            diagnostics.Report(SemanticDiagnostics.MemberRedeclaration, redeclLocation, redeclPath, (object)classType.DisplayName, member.Name, ancestor.DisplayName);
        }
        else
        {
            var compilationUnitPath = FindCompilationUnitPathForClass(
                classType, symbolTable, asts, compilation);

            diagnostics.Report(SemanticDiagnostics.MemberRedeclaration, default, compilationUnitPath ?? "<unknown>", (object)classType.DisplayName, member.Name, ancestor.DisplayName);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 1f — Check base constructor requirements are satisfied
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After base types are resolved and cycles are broken, check that each
    /// derived class satisfies its base class's constructor requirements.
    /// If the base class has explicit constructors that all require parameters,
    /// the derived class must have at least one constructor with a
    /// <c>: base(args)</c> chain. If the derived class has no explicit
    /// constructors at all, or has constructors without <c>: base(...)</c>,
    /// and the base class has no parameterless constructor, emit
    /// <c>MIST_BASE_CTOR_UNSATISFIED</c>.
    /// </summary>
    private static void Pass1_CheckBaseConstructorSatisfied(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Class || symbol.DeclaredType is not ClassType classType)
            {
                continue;
            }

            if(classType.BaseType is null)
            {
                continue;
            }

            var baseType = classType.BaseType;

            // Get the member scope from the base type.
            var baseScope = baseType switch
            {
                ClassType ct => ct.MemberScope,
                ConstructedType cst => cst.MemberScope,
                _ => null,
            };
            if(baseScope is null)
            {
                continue;
            }

            // Find explicit constructors on the base class.
            var baseConstructors = baseScope.Members
                .Where(m => m.Kind == SymbolKind.Constructor)
                .ToList();

            // If the base class has no explicit constructors, it has an implicit
            // parameterless constructor — no issue.
            if(baseConstructors.Count == 0)
            {
                continue;
            }

            // Check if the base class has at least one parameterless constructor.
            var baseHasParameterlessCtor = baseConstructors.Any(ctor =>
            {
                var ctorNode = symbolTable.GetDeclaringNode(ctor);
                return ctorNode is ConstructorDeclarationNode ctorDecl && ctorDecl.Parameters is null;
            });

            // If the base class has a parameterless constructor, derived classes
            // can implicitly call it — no issue.
            if(baseHasParameterlessCtor)
            {
                continue;
            }

            // The base class requires constructor arguments. Check if the derived
            // class satisfies this requirement.
            var derivedConstructors = classType.MemberScope.Members
                .Where(m => m.Kind == SymbolKind.Constructor)
                .ToList();

            if(derivedConstructors.Count == 0)
            {
                // Derived class has no explicit constructors and the base class
                // requires arguments — emit diagnostic.
                var classSourceText = FindSourceTextForClassType(
                    classType, symbolTable);
                Storm.Runtime.SyntaxNode? classNode = null;
                foreach(var sym in symbolTable.AllSymbols)
                {
                    if(sym.DeclaredType == classType)
                    {
                        classNode = symbolTable.GetDeclaringNode(sym);
                        break;
                    }
                }

                if(classNode is not null)
                {
                    LinePositionSpan ctorLocation = default;
                    var ctorPath = classSourceText?.Path ?? "<unknown>";
                    if(classSourceText is not null && classNode.Span.Length > 0)
                    {
                        var mistSpan = new SourceSpan(classNode.Span.Start, classNode.Span.Length);
                        ctorLocation = classSourceText.ToLinePositionSpan(mistSpan);
                    }

                    diagnostics.Report(SemanticDiagnostics.BaseCtorUnsatisfied, ctorLocation, ctorPath, (object)baseType.DisplayName);
                }
                else
                {
                    var compilationUnitPath = FindCompilationUnitPathForClass(
                        classType, symbolTable, asts, compilation);

                    diagnostics.Report(SemanticDiagnostics.BaseCtorUnsatisfied, default, compilationUnitPath ?? "<unknown>", (object)baseType.DisplayName);
                }

                continue;
            }

            // Check each derived constructor: at least one must have a `: base(...)` chain,
            // and any constructor without `: base(...)` is an error since the base class
            // has no parameterless constructor.
            foreach(var derivedCtor in derivedConstructors)
            {
                var ctorNode = symbolTable.GetDeclaringNode(derivedCtor);
                if(ctorNode is not ConstructorDeclarationNode ctorDecl)
                {
                    continue;
                }

                var hasBaseChain = ctorDecl.Chain is BaseChainConstructorChainNode;

                if(!hasBaseChain)
                {
                    // This constructor does not chain to the base class, but the
                    // base class requires arguments — emit diagnostic.
                    var ctorSourceText = FindSourceTextForClassType(
                        classType, symbolTable);

                    LinePositionSpan perCtorLocation = default;
                    var perCtorPath = ctorSourceText?.Path ?? "<unknown>";
                    if(ctorSourceText is not null && ctorDecl.Span.Length > 0)
                    {
                        var mistSpan = new SourceSpan(ctorDecl.Span.Start, ctorDecl.Span.Length);
                        perCtorLocation = ctorSourceText.ToLinePositionSpan(mistSpan);
                    }

                    diagnostics.Report(SemanticDiagnostics.BaseCtorUnsatisfied, perCtorLocation, perCtorPath, (object)baseType.DisplayName);
                }
            }
        }

        // ─── Struct base constructor satisfaction ───────────────────────────
        // Mirror the class logic above for structs with base struct types.
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Struct || symbol.DeclaredType is not StructType structType)
            {
                continue;
            }

            if(structType.BaseType is null)
            {
                continue;
            }

            var baseType = structType.BaseType;

            // Get the member scope from the base struct type.
            var baseScope = baseType switch
            {
                StructType bst => bst.MemberScope,
                ConstructedType cst => cst.MemberScope,
                _ => null,
            };
            if(baseScope is null)
            {
                continue;
            }

            // Find explicit constructors on the base struct.
            var baseConstructors = baseScope.Members
                .Where(m => m.Kind == SymbolKind.Constructor)
                .ToList();

            // If the base struct has no explicit constructors, it has an implicit
            // parameterless constructor — no issue.
            if(baseConstructors.Count == 0)
            {
                continue;
            }

            // Check if the base struct has at least one parameterless constructor.
            var baseHasParameterlessCtor = baseConstructors.Any(ctor =>
            {
                var ctorNode = symbolTable.GetDeclaringNode(ctor);
                return ctorNode is ConstructorDeclarationNode ctorDecl && ctorDecl.Parameters is null;
            });

            // If the base struct has a parameterless constructor, derived structs
            // can implicitly call it — no issue.
            if(baseHasParameterlessCtor)
            {
                continue;
            }

            // The base struct requires constructor arguments. Check if the derived
            // struct satisfies this requirement.
            var derivedConstructors = structType.MemberScope.Members
                .Where(m => m.Kind == SymbolKind.Constructor)
                .ToList();

            if(derivedConstructors.Count == 0)
            {
                // Derived struct has no explicit constructors and the base struct
                // requires arguments — emit diagnostic.
                Storm.Runtime.SyntaxNode? structNode = null;
                foreach(var sym in symbolTable.AllSymbols)
                {
                    if(sym.DeclaredType == structType)
                    {
                        structNode = symbolTable.GetDeclaringNode(sym);
                        break;
                    }
                }

                if(structNode is not null)
                {
                    var structSourceText = GetSourceTextFromOrigin(structNode);
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        StructBaseCtorRequired.Value,
                        DiagnosticSeverity.Error,
                        $"Struct '{baseType.DisplayName}' requires constructor arguments. Add ': base(...)' to the constructor of '{structType.DisplayName}'.",
                        structNode,
                        structSourceText));
                }
                else
                {
                    diagnostics.Add(new Diagnostic(
                        StructBaseCtorRequired,
                        DiagnosticSeverity.Error,
                        PipelineStage.SemanticModelConstruction,
                        $"Struct '{baseType.DisplayName}' requires constructor arguments. Add ': base(...)' to the constructor of '{structType.DisplayName}'.",
                        Location: default,
                        CompilationUnitPath: "<unknown>",
                        AnalyzerName: null));
                }

                continue;
            }

            // Check each derived constructor: any constructor without `: base(...)` is
            // an error since the base struct has no parameterless constructor.
            foreach(var derivedCtor in derivedConstructors)
            {
                var ctorNode = symbolTable.GetDeclaringNode(derivedCtor);
                if(ctorNode is not ConstructorDeclarationNode ctorDecl)
                {
                    continue;
                }

                var hasBaseChain = ctorDecl.Chain is BaseChainConstructorChainNode;

                if(!hasBaseChain)
                {
                    // This constructor does not chain to the base struct, but the
                    // base struct requires arguments — emit diagnostic.
                    var ctorSourceText = GetSourceTextForSymbol(symbol, symbolTable);

                    diagnostics.Add(MakeDiagnosticWithLocation(
                        StructBaseCtorRequired.Value,
                        DiagnosticSeverity.Error,
                        $"Struct '{baseType.DisplayName}' requires constructor arguments. Add ': base(...)' to the constructor of '{structType.DisplayName}'.",
                        ctorDecl,
                        ctorSourceText));
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Post-Pass 2 — Check duplicate method/constructor signatures
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// After Pass 2 (type resolution), check for duplicate method and constructor
    /// signatures within each type scope. Two methods with the same name and
    /// identical parameter types are a duplicate; two constructors with identical
    /// parameter types are a duplicate.
    /// </summary>
    private static void Pass1_CheckDuplicateSignatures(
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            IScope memberScope;
            string typeName;

            switch(symbol.Kind)
            {
                case SymbolKind.Class when symbol.DeclaredType is ClassType classType:
                    memberScope = classType.MemberScope;
                    typeName = classType.DisplayName;
                    break;
                case SymbolKind.Struct when symbol.DeclaredType is StructType structType:
                    memberScope = structType.MemberScope;
                    typeName = structType.DisplayName;
                    break;
                case SymbolKind.Abstract when symbol.DeclaredType is AbstractType abstractType:
                    memberScope = abstractType.MemberScope;
                    typeName = abstractType.DisplayName;
                    break;
                default:
                    continue;
            }

            // Check duplicate method signatures: group methods by name.
            var methods = memberScope.Members
                .Where(m => m.Kind == SymbolKind.Method)
                .ToList();

            var methodGroups = methods.GroupBy(m => m.Name);
            foreach(var group in methodGroups)
            {
                var groupList = group.ToList();
                if(groupList.Count <= 1)
                {
                    continue;
                }

                CheckDuplicatePairs(
                    groupList, typeName, isConstructor: false,
                    symbolTable, asts, compilation, diagnostics);
            }

            // Check duplicate constructor signatures.
            var constructors = memberScope.Members
                .Where(m => m.Kind == SymbolKind.Constructor)
                .ToList();

            if(constructors.Count > 1)
            {
                CheckDuplicatePairs(
                    constructors, typeName, isConstructor: true,
                    symbolTable, asts, compilation, diagnostics);
            }
        }
    }

    /// <summary>
    /// Checks all pairs of symbols in the list for identical parameter signatures
    /// and emits the appropriate duplicate diagnostic for each match.
    /// Two methods with the same parameter types but different RefKind values
    /// on one or more parameters are distinct overloads (Requirement 7.4).
    /// </summary>
    private static void CheckDuplicatePairs(
        List<ISymbol> symbols,
        string typeName,
        bool isConstructor,
        SymbolTable symbolTable,
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Pre-extract signatures for all symbols to avoid redundant extraction.
        var signatures = new IReadOnlyList<IType>[symbols.Count];
        var refKinds = new IReadOnlyList<RefKind>[symbols.Count];
        for(var i = 0; i < symbols.Count; i++)
        {
            signatures[i] = ParameterSignature.Extract(symbols[i], symbolTable);
            refKinds[i] = ParameterSignature.ExtractRefKinds(symbols[i], symbolTable);
        }

        // Track which symbols have already been reported as duplicates
        // to avoid emitting multiple diagnostics for the same pair.
        var reported = new HashSet<int>();

        for(var i = 0; i < symbols.Count; i++)
        {
            for(var j = i + 1; j < symbols.Count; j++)
            {
                if(reported.Contains(j))
                {
                    continue;
                }

                if(!ParameterSignature.AreEqualWithRefKind(
                    signatures[i], refKinds[i], signatures[j], refKinds[j]))
                {
                    continue;
                }

                // Found a duplicate — emit diagnostic on the second (later) declaration.
                _ = reported.Add(j);

                var diagnosticId = isConstructor
                    ? DuplicateConstructorSignature
                    : DuplicateMethodSignature;

                var paramTypeNames = string.Join(", ", signatures[j].Select(t => t.DisplayName));

                var message = isConstructor
                    ? $"Type '{typeName}' already defines a constructor with parameter types ({paramTypeNames})"
                    : $"Type '{typeName}' already defines method '{symbols[j].Name}' with parameter types ({paramTypeNames})";

                var duplicateNode = symbolTable.GetDeclaringNode(symbols[j]);
                var sourceText = FindSourceTextForType(
                    typeName, symbolTable);

                if(duplicateNode is not null)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        diagnosticId.Value,
                        DiagnosticSeverity.Error,
                        message,
                        duplicateNode,
                        sourceText));
                }
                else
                {
                    var compilationUnitPath = FindCompilationUnitPathForType(
                        typeName, symbolTable, asts, compilation);

                    diagnostics.Add(new Diagnostic(
                        diagnosticId,
                        DiagnosticSeverity.Error,
                        PipelineStage.SemanticModelConstruction,
                        message,
                        Location: default,
                        CompilationUnitPath: compilationUnitPath ?? "<unknown>",
                        AnalyzerName: null));
                }
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Pass 2 — Resolve types and build expression types
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Builds the declaration-site file scope for a compilation unit. The scope
    /// is parented to the appropriate namespace scope (inferred or explicit) and
    /// includes all using imports, global usings, and the file's own namespace
    /// as an implicit import. This scope is suitable for resolving type references
    /// declared in the file.
    /// </summary>
    /// <param name="compilationUnit">The compilation unit AST node.</param>
    /// <param name="globalScope">The root global scope containing all namespace symbols.</param>
    /// <param name="symbolTable">The symbol table populated by Pass 1.</param>
    /// <param name="ambientTypeResolver">Optional resolver for framework/ambient namespaces.</param>
    /// <param name="sourceText">Source text for the file (provides path and span info).</param>
    /// <param name="diagnostics">Diagnostic bag for reporting unresolvable using namespaces.</param>
    /// <param name="globalUsings">Global using namespaces to import into every file scope.</param>
    /// <param name="explicitUsingImports">
    /// Out: the list of namespace names imported via explicit <c>using</c> declarations
    /// (not including the auto-imported own namespace or global usings). Callers need
    /// this to propagate usings into per-namespace-section scopes.
    /// </param>
    /// <returns>The file-level scope with using imports resolved.</returns>
    internal static Scope BuildFileScopeForUnit(
        CompilationUnitNode compilationUnit,
        Scope globalScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        ImmutableArray<string> globalUsings,
        out List<string> explicitUsingImports)
    {
        // Compute the inferred namespace scope for this file.
        var inferredNamespaceScope = FindInferredNamespaceScopeForFile(
            compilationUnit, globalScope, symbolTable, sourceText);

        // Determine the primary namespace scope for this file.
        // The scope chain is: local → file → namespace → global.
        // For files with no explicit namespace, the inferred namespace scope is used.
        // For files with explicit namespaces, each namespace section gets its own scope.
        var primaryNamespaceScope = inferredNamespaceScope ?? globalScope;

        // Create a file-level scope to hold using imports. This scope sits between
        // the namespace scope and the type scopes.
        var fileScope = new Scope(parent: primaryNamespaceScope);

        // Add the file's own namespace as implicitly imported so that extensions
        // declared in the same namespace are visible without an explicit `using`.
        var ownNamespaceName = DetermineFileNamespaceName(compilationUnit, sourceText);
        if(ownNamespaceName is not null)
        {
            fileScope.AddImportedNamespace(ownNamespaceName);
        }

        // Process using declarations — verify namespace existence and record imports.
        foreach(var usingDecl in compilationUnit.Usings)
        {
            var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
            var nsExists = false;

            // Check user-defined namespaces.
            foreach(var member in globalScope.Members)
            {
                if(member.Kind == SymbolKind.Namespace && member.Name == usingName)
                {
                    nsExists = true;
                    break;
                }
            }

            // Check ambient namespaces.
            if(!nsExists && ambientTypeResolver is not null)
            {
                nsExists = ambientTypeResolver.HasNamespace(usingName);
            }

            if(nsExists)
            {
                fileScope.AddImportedNamespace(usingName);
            }
            else
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_UNDEFINED_NAMESPACE",
                    DiagnosticSeverity.Error,
                    $"The namespace '{usingName}' could not be found.",
                    usingDecl,
                    sourceText));
            }
        }

        // Also process using directives that appear after a file-scoped namespace
        // (parsed as UsingItem top-level items rather than CompilationUnit.Usings).
        foreach(var item in compilationUnit.Items)
        {
            if(item is UsingItemTopLevelItemNode usingItem)
            {
                var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                var nsExists = false;
                foreach(var member in globalScope.Members)
                {
                    if(member.Kind == SymbolKind.Namespace && member.Name == usingName)
                    {
                        nsExists = true;
                        break;
                    }
                }

                if(!nsExists && ambientTypeResolver is not null)
                {
                    nsExists = ambientTypeResolver.HasNamespace(usingName);
                }

                if(nsExists)
                {
                    fileScope.AddImportedNamespace(usingName);
                }
            }
        }

        // Process global usings — add each as an imported namespace on the file scope.
        foreach(var globalNs in globalUsings)
        {
            var nsExists = false;

            // Check user-defined namespaces.
            foreach(var member in globalScope.Members)
            {
                if(member.Kind == SymbolKind.Namespace && member.Name == globalNs)
                {
                    nsExists = true;
                    break;
                }
            }

            // Check ambient namespaces.
            if(!nsExists && ambientTypeResolver is not null)
            {
                nsExists = ambientTypeResolver.HasNamespace(globalNs);
            }

            if(nsExists)
            {
                fileScope.AddImportedNamespace(globalNs);
            }
            else
            {
                diagnostics.Report(SemanticDiagnostics.GlobalUsingUndefinedNamespace, default, sourceText?.Path ?? "<unknown>", (object)globalNs);
            }
        }

        // Collect the explicit using declarations (from source-level `using` statements).
        // These are the namespaces that should be copied to every namespace section.
        // The auto-imported "own namespace" (from DetermineFileNamespaceName) should NOT
        // be propagated to sections with a different namespace name.
        explicitUsingImports = new List<string>();
        foreach(var usingDecl in compilationUnit.Usings)
        {
            var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
            if(fileScope.ImportedNamespaces.Contains(usingName))
            {
                explicitUsingImports.Add(usingName);
            }
        }
        // Also collect UsingItem top-level items (usings after namespace declaration).
        foreach(var item in compilationUnit.Items)
        {
            if(item is UsingItemTopLevelItemNode usingItem)
            {
                var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                if(fileScope.ImportedNamespaces.Contains(usingName) && !explicitUsingImports.Contains(usingName))
                {
                    explicitUsingImports.Add(usingName);
                }
            }
        }

        return fileScope;
    }

    /// <summary>
    /// Pass 2: Walk the AST again to resolve type references, register parameters
    /// and local variables, and compute expression types.
    /// </summary>
    private static void Pass2_ResolveTypes(
        Storm.Runtime.SyntaxNode ast,
        Scope globalScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        bool hasTopLevelStatements,
        DiagnosticBag diagnostics,
        ImmutableArray<string> globalUsings)
    {
        if(ast is not CompilationUnitNode compilationUnit)
        {
            return;
        }

        // Build the file scope using the reusable helper.
        var fileScope = BuildFileScopeForUnit(
            compilationUnit, globalScope, symbolTable, ambientTypeResolver,
            sourceText, diagnostics, globalUsings, out var explicitUsingImports);

        // The primary namespace scope is the file scope's parent.
        var primaryNamespaceScope = fileScope.Parent as Scope ?? globalScope;

        // For files with top-level statements, create a synthetic scope that acts
        // like a method body scope. This scope is a child of the file scope so it
        // has access to all types in the global scope (via the parent chain). Local
        // variables declared by preceding top-level statements are registered here,
        // making them visible to later statements (sequential scope semantics).
        Scope? tlsScope = null;
        if(hasTopLevelStatements)
        {
            tlsScope = new Scope(parent: fileScope);

            // Synthesize an implicit `args` local variable of type string[]
            // so that top-level statements can access command-line arguments.
            IType stringType;
            try
            {
                stringType = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.String");
            }
            catch(StdlibMissingException)
            {
                stringType = LegacyPrimitiveTypes.String;
            }

            var stringArrayType = new ArrayType(stringType);
            var argsSymbol = new Symbol(
                "args", SymbolKind.LocalVariable, SymbolOrigin.UserCode,
                tlsScope, stringArrayType, declarationSpan: null);
            tlsScope.AddMember(argsSymbol);
        }

        foreach(var item in compilationUnit.Items)
        {
            switch(item)
            {
                case NamespaceItemTopLevelItemNode nsItem:
                    {
                        var nsDecl = nsItem.NamespaceDeclaration;
                        var declaredName = ExtractNamespaceName(nsDecl, sourceText);

                        // Find the namespace scope for this declaration.
                        var nsScope = FindExistingNamespaceScope(globalScope, symbolTable, declaredName);

                        // Create a file scope for this namespace section if it differs
                        // from the primary namespace scope.
                        Scope sectionFileScope;
                        if(nsScope is not null && nsScope != primaryNamespaceScope)
                        {
                            sectionFileScope = new Scope(parent: nsScope);
                            // Copy only explicit using imports to this section scope.
                            // Do NOT copy the auto-imported "own namespace" from the file scope,
                            // as that belongs to the first namespace in the file and should not
                            // leak into different-name namespace sections (Requirement 4.2).
                            foreach(var ns in explicitUsingImports)
                            {
                                sectionFileScope.AddImportedNamespace(ns);
                            }
                            // Copy global usings to this section scope so that globally-used
                            // namespaces are available in all namespace sections.
                            foreach(var ns in globalUsings)
                            {
                                sectionFileScope.AddImportedNamespace(ns);
                            }
                            // Add this section's own namespace as implicitly imported so that
                            // types within the same namespace are cross-resolvable (Requirement 4.1).
                            sectionFileScope.AddImportedNamespace(declaredName);
                        }
                        else
                        {
                            sectionFileScope = fileScope;
                        }

                        var namespaceTypes = GetNamespaceBodyTypes(nsDecl);
                        foreach(var typeDecl in namespaceTypes)
                        {
                            ResolveTypeDeclaration(typeDecl, sectionFileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }

                        // Safety net: Phase 2 (Pass1a_ResolveTypeForwards) already resolved all
                        // type aliases and newtypes. These calls are guarded no-ops — both methods
                        // early-return when DeclaredType is already populated.
                        var namespaceTypeAliases = GetNamespaceBodyTypeAliases(nsDecl);
                        foreach(var aliasDecl in namespaceTypeAliases)
                        {
                            ResolveTypeAliasDeclaration(aliasDecl, sectionFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }

                        var namespaceNewtypes = GetNamespaceBodyNewtypes(nsDecl);
                        foreach(var newtypeDecl in namespaceNewtypes)
                        {
                            ResolveNewtypeDeclaration(newtypeDecl, sectionFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }

                        break;
                    }
                case TypeItemTopLevelItemNode typeItem:
                    ResolveTypeDeclaration(typeItem.TypeDeclaration, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                case StatementItemTopLevelItemNode stmtItem when tlsScope is not null:
                    // Resolve the top-level statement within the synthetic TLS scope.
                    // The TLS scope acts like a method body scope: local variables
                    // declared here become visible to subsequent statements.
                    ResolveStatement(stmtItem.Statement, tlsScope, fileScope, enclosingType: null!, isStatic: true, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
            }
        }
    }

    /// <summary>
    /// Finds the inferred namespace scope for a file by looking at the first top-level
    /// type registered in Pass 1 (types outside any explicit namespace declaration).
    /// If the file has no top-level types, falls back to the first namespace declaration's scope.
    /// </summary>
    private static Scope? FindInferredNamespaceScopeForFile(
        CompilationUnitNode compilationUnit,
        Scope globalScope,
        SymbolTable symbolTable,
        SourceText? sourceText)
    {
        // First, try to find a top-level type (outside any namespace) and use its containing scope.
        foreach(var item in compilationUnit.Items)
        {
            if(item is TypeItemTopLevelItemNode typeItem)
            {
                Storm.Runtime.SyntaxNode declNode = typeItem.TypeDeclaration switch
                {
                    BodyTypeTypeDeclarationNode body => body.TypeBody,
                    EnumTypeTypeDeclarationNode et => et.EnumDeclaration,
                    NewtypeTypeTypeDeclarationNode nt => nt.NewtypeDeclaration,
                    TypeAliasTypeTypeDeclarationNode ta => ta.TypeAliasDeclaration,
                    _ => typeItem.TypeDeclaration
                };

                var symbol = symbolTable.GetDeclaredSymbol(declNode);
                if(symbol?.ContainingScope is Scope namespaceScope && namespaceScope.Parent == globalScope)
                {
                    return namespaceScope;
                }
            }
        }

        // No top-level types found. Try the first namespace declaration.
        foreach(var item in compilationUnit.Items)
        {
            if(item is NamespaceItemTopLevelItemNode nsItem)
            {
                var nsName = ExtractNamespaceName(nsItem.NamespaceDeclaration, sourceText);
                var nsScope = FindExistingNamespaceScope(globalScope, symbolTable, nsName);
                if(nsScope is not null)
                {
                    return nsScope;
                }

                // Fall back to FindNamespaceScope which looks at body types.
                return FindNamespaceScope(globalScope, symbolTable, nsItem.NamespaceDeclaration);
            }
        }

        return null;
    }

    /// <summary>
    /// Determines the namespace name for a file by examining its namespace declarations.
    /// Returns null if the file has no namespace declaration.
    /// Used to implicitly import the file's own namespace for extension visibility.
    /// </summary>
    private static string? DetermineFileNamespaceName(
        CompilationUnitNode compilationUnit,
        SourceText? sourceText)
    {
        foreach(var item in compilationUnit.Items)
        {
            if(item is NamespaceItemTopLevelItemNode nsItem)
            {
                return ExtractNamespaceName(nsItem.NamespaceDeclaration, sourceText);
            }
        }

        return null;
    }

    /// <summary>
    /// Finds the namespace scope created in Pass 1 by looking at the type declarations
    /// registered under the namespace. Returns the parent scope of the first type found.
    /// </summary>
    private static Scope FindNamespaceScope(
        Scope globalScope,
        SymbolTable symbolTable,
        NamespaceDeclarationNode namespaceNode)
    {
        var bodyTypes = GetNamespaceBodyTypes(namespaceNode);
        if(bodyTypes.Length > 0)
        {
            // Get the first type declaration and find its symbol's containing scope.
            var firstTypeDecl = bodyTypes[0];
            Storm.Runtime.SyntaxNode declNode = firstTypeDecl switch
            {
                BodyTypeTypeDeclarationNode body => body.TypeBody,
                _ => firstTypeDecl
            };

            var symbol = symbolTable.GetDeclaredSymbol(declNode);
            if(symbol?.ContainingScope is Scope namespaceScope)
            {
                return namespaceScope;
            }
        }

        // Fallback: create a new scope (shouldn't happen in practice).
        return new Scope(parent: globalScope);
    }

    /// <summary>
    /// Finds an existing namespace scope by consulting the namespace scope map.
    /// Falls back to the legacy heuristic of searching type symbols for backward
    /// compatibility with callers that run before the map is populated.
    /// </summary>
    private static Scope? FindExistingNamespaceScope(
        Scope globalScope,
        SymbolTable symbolTable,
        string namespaceName)
    {
        // Primary path: consult the namespace scope map (populated by GetOrCreateNamespaceScope).
        if(namespaceScopeMap is not null && namespaceScopeMap.TryGetValue(namespaceName, out var mapped))
        {
            return mapped;
        }

        // Fallback: walk all registered symbols to find a type in this namespace.
        // This handles edge cases where FindExistingNamespaceScope is called before
        // the map is populated (e.g., from Pass 2 after a fresh Build() call).
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if((symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.Enum)
                && symbol.ContainingScope is Scope parentScope
                && parentScope.Parent == globalScope)
            {
                // This type is in a namespace scope. Check if it matches.
                if(symbol.DeclaredType is ClassType ct && ct.ContainingNamespace == namespaceName)
                {
                    return parentScope;
                }

                if(symbol.DeclaredType is StructType st && st.ContainingNamespace == namespaceName)
                {
                    return parentScope;
                }

                if(symbol.DeclaredType is AbstractType it && it.ContainingNamespace == namespaceName)
                {
                    return parentScope;
                }

                if(symbol.DeclaredType is EnumType et && et.ContainingNamespace == namespaceName)
                {
                    return parentScope;
                }
            }
        }

        return null;
    }

    private static void ResolveTypeDeclaration(
        TypeDeclarationNode typeDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(typeDecl)
        {
            case BodyTypeTypeDeclarationNode bodyTypeNode:
                ResolveBodyTypeDeclaration(bodyTypeNode.TypeBody, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case EnumTypeTypeDeclarationNode enumTypeNode:
                ResolveEnumDeclaration(enumTypeNode.EnumDeclaration, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case TypeAliasTypeTypeDeclarationNode typeAliasTypeNode:
                ResolveTypeAliasDeclaration(typeAliasTypeNode.TypeAliasDeclaration, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                break;
            case NewtypeTypeTypeDeclarationNode newtypeTypeNode:
                ResolveNewtypeDeclaration(newtypeTypeNode.NewtypeDeclaration, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    // ── Enum type resolution (Pass 2) ──────────────────────────────────

    /// <summary>
    /// Resolves the underlying type and member values for an enum declaration.
    /// <list type="number">
    ///   <item>If an explicit type annotation is present, resolves the <see cref="TypeReferenceNode"/>.</item>
    ///   <item>If members have value expressions, infers the underlying type from member value types
    ///         (homogeneous → that type, heterogeneous → union type).</item>
    ///   <item>If name-only (no values), sets the underlying type to <c>byte</c>.</item>
    /// </list>
    /// Assigns sequential values (0, 1, 2, …) for name-only members, continuing after explicit values.
    /// </summary>
    private static void ResolveEnumDeclaration(
        EnumDeclarationNode enumDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var enumSymbol = symbolTable.GetDeclaredSymbol(enumDecl);
        if(enumSymbol?.DeclaredType is not EnumType enumType)
        {
            return;
        }

        // Collect all member AST nodes.
        var memberNodes = new List<EnumMemberNode>();
        if(enumDecl.Members is not null)
        {
            memberNodes.Add(enumDecl.Members.EnumMember);
            foreach(var member in enumDecl.Members.EnumMembers)
            {
                memberNodes.Add(member);
            }
        }

        // ── Step 1: Resolve the underlying type ──────────────────────────

        IType underlyingType;

        // Note: The grammar defines typeAnnotation:(COLON type:TypeReference)? which
        // produces two properties on EnumDeclarationNode: 'TypeAnnotation' (the outer
        // optional label — always null due to a code-gen quirk in labeled optional
        // sequences) and 'Type' (the inner label, holding the actual TypeReferenceNode
        // when a type annotation is present, or null/default when absent).
        // We check 'Type' as the reliable indicator of whether a type annotation exists.
        if(enumDecl.Type is { } typeAnnotationNode)
        {
            // Explicit type annotation — resolve the TypeReference node.
            underlyingType = ResolveTypeReference(
                typeAnnotationNode, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

            if(underlyingType is ErrorType)
            {
                // Cannot resolve the annotated type — assign ErrorType and skip member validation.
                enumType.UnderlyingType = ErrorType.Instance;
                enumType.Members = memberNodes.Select(m => new EnumMemberInfo(m.Name.Lexeme) { IsDefault = m.IsDefault is not null }).ToList();
                return;
            }
        }
        else if(memberNodes.Any(m => m.Value is not null))
        {
            // Members have value expressions — infer from member value types.
            // First, resolve all member value expressions to determine their types.
            var valueTypes = new List<IType>();
            foreach(var memberNode in memberNodes)
            {
                if(memberNode.Value is not null)
                {
                    var valueType = ResolveExpression(
                        memberNode.Value, (Scope)enumType.MemberScope, fileScope, enumType,
                        isStatic: true, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    valueTypes.Add(valueType);
                }
            }

            // Determine underlying type: homogeneous → that type, heterogeneous → union type.
            var distinctTypes = valueTypes
                .Where(t => t is not ErrorType)
                .Select(t => t.DisplayName)
                .Distinct()
                .ToList();

            if(distinctTypes.Count == 0)
            {
                // All values resolved to ErrorType — fall back to byte.
                underlyingType = ResolvePrimitiveByKeyword("byte", fileScope, symbolTable);
            }
            else if(distinctTypes.Count == 1)
            {
                // Homogeneous — use that type.
                underlyingType = valueTypes.First(t => t is not ErrorType);
            }
            else
            {
                // Heterogeneous — create a union type from the distinct value types.
                var uniqueTypes = new List<IType>();
                var seenNames = new HashSet<string>();
                foreach(var vt in valueTypes)
                {
                    if(vt is not ErrorType && seenNames.Add(vt.DisplayName))
                    {
                        uniqueTypes.Add(vt);
                    }
                }

                underlyingType = new UnionType(uniqueTypes);
            }
        }
        else
        {
            // Name-only enum — default underlying type is byte.
            underlyingType = ResolvePrimitiveByKeyword("byte", fileScope, symbolTable);
        }

        enumType.UnderlyingType = underlyingType;

        // ── Step 2: Resolve member values ────────────────────────────────

        var isStringBacked = IsStringLikeType(underlyingType);
        var memberInfos = new List<EnumMemberInfo>();
        long nextSequentialValue = 0;

        foreach(var memberNode in memberNodes)
        {
            var memberInfo = new EnumMemberInfo(memberNode.Name.Lexeme)
            {
                IsDefault = memberNode.IsDefault is not null
            };

            if(memberNode.Value is not null)
            {
                // Member has an explicit value expression.
                // If we already resolved this expression above (during type inference),
                // retrieve its type from the expression types map. Otherwise resolve it now.
                var valueType = expressionTypes.ContainsKey(memberNode.Value)
                    ? expressionTypes[memberNode.Value]
                    : ResolveExpression(
                        memberNode.Value, (Scope)enumType.MemberScope, fileScope, enumType,
                        isStatic: true, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                memberInfo.ValueType = valueType;

                // Try to extract a compile-time integer value for sequencing.
                var literalValue = TryExtractIntegerLiteral(memberNode.Value);
                if(literalValue.HasValue)
                {
                    memberInfo.ResolvedValue = literalValue.Value;
                    nextSequentialValue = literalValue.Value + 1;
                }
                else
                {
                    // Non-integer or complex expression — store null as resolved value.
                    // The next implicit member still gets nextSequentialValue.
                    memberInfo.ResolvedValue = null;
                    // Don't advance nextSequentialValue for non-integer explicit values.
                }
            }
            else if(isStringBacked)
            {
                // String-backed enum with no explicit value — use the variant name.
                memberInfo.ResolvedValue = memberNode.Name.Lexeme;
                memberInfo.ValueType = underlyingType;
            }
            else
            {
                // Name-only member — assign sequential value.
                memberInfo.ResolvedValue = nextSequentialValue;
                memberInfo.ValueType = underlyingType;
                nextSequentialValue++;
            }

            memberInfos.Add(memberInfo);
        }

        // ── Step 3: Check for duplicate enum member values ───────────────

        var seenValues = new Dictionary<string, string>(); // value → first member name
        foreach(var memberInfo in memberInfos)
        {
            // Determine the effective string representation of the value for comparison.
            string? valueKey = null;
            if(memberInfo.ResolvedValue is string strVal)
            {
                valueKey = $"s:{strVal}";
            }
            else if(memberInfo.ResolvedValue is long longVal)
            {
                valueKey = $"i:{longVal}";
            }

            if(valueKey is not null)
            {
                if(seenValues.TryGetValue(valueKey, out var firstMember))
                {
                    diagnostics.Add(new Diagnostic(
                        DuplicateEnumMemberValue,
                        DiagnosticSeverity.Error,
                        PipelineStage.SemanticModelConstruction,
                        $"Enum member '{memberInfo.Name}' has the same value as member '{firstMember}' in enum '{enumType.DisplayName}'.",
                        Location: default,
                        CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                        AnalyzerName: null));
                }
                else
                {
                    seenValues[valueKey] = memberInfo.Name;
                }
            }
        }

        enumType.Members = memberInfos;
    }

    /// <summary>
    /// Attempts to extract a compile-time integer value from a simple literal expression.
    /// Returns <c>null</c> for complex expressions or non-integer literals.
    /// </summary>
    private static long? TryExtractIntegerLiteral(ExpressionNode expr)
    {
        // Navigate: Expression → Assignment → LogicalOr → LogicalAnd → Equality
        //         → Relational → Additive → Multiplicative → Unary → Postfix → Primary
        var assignment = expr.AsAssignmentOrNull();
        if(assignment is null)
        {
            return null; // Lambda form — not a simple literal.
        }

        if(assignment.Value is not null)
        {
            return null; // It's an assignment, not a simple literal.
        }

        var voidCoalescing = assignment.Target;
        if(voidCoalescing?.LogicalOrs.Length > 0)
        {
            return null;
        }

        var logicalOr = voidCoalescing?.Left;
        if(logicalOr?.Right is not null && !ReferenceEquals(logicalOr.Right, logicalOr.Left))
        {
            return null;
        }

        var logicalAnd = logicalOr?.Left;
        if(logicalAnd?.Right is not null && !ReferenceEquals(logicalAnd.Right, logicalAnd.Left))
        {
            return null;
        }

        var equality = logicalAnd?.Left;
        if(equality?.Right is not null && !ReferenceEquals(equality.Right, equality.Left))
        {
            return null;
        }

        // Relational is a discriminated union.
        if(equality?.Left is not RelationalComparisonRelationalNode relCmp)
        {
            return null;
        }

        if(relCmp.Right is not null && !ReferenceEquals(relCmp.Right, relCmp.Left))
        {
            return null;
        }

        var additive = relCmp.Left;
        if(additive?.Right is not null && !ReferenceEquals(additive.Right, additive.Left))
        {
            return null;
        }

        var multiplicative = additive?.Left;
        if(multiplicative?.Right is not null && !ReferenceEquals(multiplicative.Right, multiplicative.Left))
        {
            return null;
        }

        // Unary is a discriminated union.
        if(multiplicative?.Left is not PostfixExpressionUnaryNode postfixUnary)
        {
            return null;
        }

        var postfix = postfixUnary.Primary;
        if(postfix.Suffix.Length > 0)
        {
            return null; // Has postfix suffixes (method calls, member access, etc.)
        }

        if(postfix.Target is not IntegerLiteralExpressionPrimaryNode intLiteral)
        {
            return null;
        }

        var lexeme = intLiteral.IntegerLiteral.Lexeme;
        // Strip suffixes for parsing.
        var upper = lexeme.ToUpperInvariant();
        var numericPart = lexeme;
        if(upper.EndsWith("UL") || upper.EndsWith("LU"))
        {
            numericPart = lexeme[..^2];
        }
        else if(upper.EndsWith("L") || upper.EndsWith("U"))
        {
            numericPart = lexeme[..^1];
        }

        if(long.TryParse(numericPart, out var value))
        {
            return value;
        }

        return null;
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Phase 4 — Global Explicit Member Type Resolution
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves all explicit type annotations on members (fields, properties,
    /// method signatures, constructors, indexers, operators, cast operators,
    /// dependent type parameter constraints, and extension block receiver types)
    /// across ALL compilation units, using declaration-site scopes.
    /// <para>
    /// After this pass completes, every explicitly-typed member has a non-null
    /// <see cref="Symbol.DeclaredType"/>, regardless of file ordering. This
    /// decouples "what type is this member?" from expression-level inference
    /// in Pass 2, eliminating cross-file ordering dependencies.
    /// </para>
    /// </summary>
    private static void Pass1_5_ResolveExplicitMemberTypes(
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,
        Scope globalScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        Dictionary<Storm.Runtime.SyntaxNode, Scope> fileScopesByUnit,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is not CompilationUnitNode cu)
            {
                continue;
            }

            if(!fileScopesByUnit.TryGetValue(cu, out var fileScope))
            {
                continue;
            }

            var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;

            // Determine the primary namespace scope — mirrors Pass 2 logic.
            var primaryNamespaceScope = fileScope.Parent as Scope ?? globalScope;

            // Collect explicit using imports from the compilation unit for section scopes.
            var explicitUsingImports = new List<string>();
            foreach(var usingDecl in cu.Usings)
            {
                var usingName = ExtractQualifiedName(usingDecl.Name, sourceText);
                if(fileScope.ImportedNamespaces.Contains(usingName))
                {
                    explicitUsingImports.Add(usingName);
                }
            }

            foreach(var uItem in cu.Items)
            {
                if(uItem is UsingItemTopLevelItemNode usingItem)
                {
                    var usingName = ExtractQualifiedName(usingItem.UsingDeclaration.Name, sourceText);
                    if(fileScope.ImportedNamespaces.Contains(usingName) && !explicitUsingImports.Contains(usingName))
                    {
                        explicitUsingImports.Add(usingName);
                    }
                }
            }

            foreach(var item in cu.Items)
            {
                switch(item)
                {
                    case NamespaceItemTopLevelItemNode nsItem:
                        {
                            var nsDecl = nsItem.NamespaceDeclaration;
                            var declaredName = ExtractNamespaceName(nsDecl, sourceText);

                            // Use namespace-specific scope if this namespace differs from the
                            // primary namespace — mirrors Pass 2 sectionFileScope logic.
                            var nsScope = FindExistingNamespaceScope(globalScope, symbolTable, declaredName);
                            Scope sectionFileScope;
                            if(nsScope is not null && nsScope != primaryNamespaceScope)
                            {
                                sectionFileScope = new Scope(parent: nsScope);
                                foreach(var ns in explicitUsingImports)
                                {
                                    sectionFileScope.AddImportedNamespace(ns);
                                }

                                sectionFileScope.AddImportedNamespace(declaredName);
                            }
                            else
                            {
                                sectionFileScope = fileScope;
                            }

                            var namespaceTypes = GetNamespaceBodyTypes(nsDecl);
                            foreach(var typeDecl in namespaceTypes)
                            {
                                ResolveExplicitMemberTypesForTypeDeclaration(typeDecl, sectionFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                            }

                            break;
                        }
                    case TypeItemTopLevelItemNode typeItem:
                        ResolveExplicitMemberTypesForTypeDeclaration(typeItem.TypeDeclaration, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        break;
                }
            }
        }
    }

    /// <summary>
    /// Dispatches explicit member type resolution for a single type declaration.
    /// </summary>
    private static void ResolveExplicitMemberTypesForTypeDeclaration(
        TypeDeclarationNode typeDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(typeDecl)
        {
            case BodyTypeTypeDeclarationNode bodyTypeNode:
                ResolveExplicitMemberTypesForBodyType(bodyTypeNode.TypeBody, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    /// <summary>
    /// Resolves explicit type annotations on all members of a class declaration.
    /// Only type annotations are resolved — initializers and bodies are deferred to Pass 2.
    /// </summary>
    private static void ResolveExplicitMemberTypesForBodyType(
        TypeBodyDeclarationNode typeBodyDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var typeSymbol = symbolTable.GetDeclaredSymbol(typeBodyDecl);
        if(typeSymbol is null)
        {
            return;
        }

        if(typeSymbol.DeclaredType is null)
        {
            return;
        }

        var memberScope = GetMemberScope(typeSymbol.DeclaredType);
        if(memberScope is not Scope typeScope)
        {
            return;
        }

        switch(typeBodyDecl.Keyword)
        {
            case ClassKeywordTypeKeywordNode:
            case StructKeywordTypeKeywordNode:
                {
                    // Pre-resolve member type aliases BEFORE building the type file scope,
                    // so that resolved aliases are included by CreateTypeParameterScope.
                    // Use a preliminary scope that includes type parameters for alias resolution.
                    var preliminaryScope = CreateTypeParameterScope(typeScope, fileScope);
                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        if(memberDecl is NestedTypeAliasMemberMemberDeclarationNode memberTypeAlias)
                        {
                            ResolveMemberTypeAliasDeclaration(memberTypeAlias.NestedTypeAlias, typeScope, preliminaryScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    // Build the type file scope AFTER member type aliases are resolved,
                    // so they are available in the resolution scope for member types.
                    var typeFileScope = CreateTypeParameterScope(typeScope, fileScope);

                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        ResolveExplicitMemberTypeAnnotation(memberDecl, typeScope, typeFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                    }

                    // Recurse into nested types — pass the type's scope so outer type
                    // parameters (e.g., TValue in Array<TValue, Length>) are visible.
                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        if(memberDecl is NestedBodyTypeMemberMemberDeclarationNode nestedTypeMember)
                        {
                            ResolveExplicitMemberTypesForTypeDeclaration(new BodyTypeTypeDeclarationNode { TypeBody = nestedTypeMember.NestedBody }, typeFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    break;
                }
            case AbstractKeywordTypeKeywordNode:
                {
                    var interfaceFileScope = CreateTypeParameterScope(typeScope, fileScope);

                    foreach(var member in typeBodyDecl.Members)
                    {
                        switch(member)
                        {
                            case MethodMemberMemberDeclarationNode methodMember
                                when methodMember.Method.Body is CallableNoBodyCallableBodyNode:
                                {
                                    var methodDecl = methodMember.Method;
                                    if(symbolTable.GetDeclaredSymbol(methodDecl) is not Symbol methodSymbol || methodSymbol.DeclaredType is not null)
                                    {
                                        break;
                                    }

                                    var returnType = ResolveTypeReference(methodDecl.ReturnType, interfaceFileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                    methodSymbol.DeclaredType = returnType;

                                    // When the parser sees "owned Foo Method(...)", it may parse "owned"
                                    // as a modifier (OwnedModifier) rather than as the returnOwnership
                                    // specifier, since Modifier* is matched greedily before
                                    // OwnershipSpecifier?. In that case, ReturnOwnership is null but the
                                    // method has an OwnedModifier. Treat this as OwnershipTier.Owned —
                                    // mirrors the equivalent fallback in PreResolveMethodSignature.
                                    if(methodDecl.ReturnOwnership is RefSpecifierOwnershipSpecifierNode)
                                    {
                                        methodSymbol.ReturnRefKind = RefKind.Ref;
                                        methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                                    }
                                    else if(methodDecl.ReturnOwnership is ReadonlyRefSpecifierOwnershipSpecifierNode)
                                    {
                                        methodSymbol.ReturnRefKind = RefKind.RefReadonly;
                                        methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                                    }
                                    else
                                    {
                                        methodSymbol.OwnershipTier = methodDecl.ReturnOwnership is null && methodDecl.Modifiers.Any(m => m is OwnedModifierModifierNode)
                                            ? OwnershipTier.Owned
                                            : MapOwnershipSpecifier(methodDecl.ReturnOwnership);
                                    }

                                    // Resolve parameter types — Phase 4 is the sole owner for
                                    // abstract type parameters since abstract types have no body resolution in Pass 2.
                                    if(methodDecl.Parameters is not null)
                                    {
                                        var methodScope = new Scope(parent: interfaceFileScope);
                                        RegisterParameters(methodDecl.Parameters, methodScope, interfaceFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                                    }

                                    break;
                                }
                            case PropertyMemberMemberDeclarationNode propertyMember:
                                {
                                    var propDecl = propertyMember.Property;
                                    if(symbolTable.GetDeclaredSymbol(propDecl) is not Symbol propSymbol || propSymbol.DeclaredType is not null)
                                    {
                                        break;
                                    }

                                    var propType = propDecl switch
                                    {
                                        BlockPropertyPropertyDeclarationNode bp =>
                                            ResolveTypeReference(bp.Type, interfaceFileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics),
                                        ExpressionBodiedPropertyPropertyDeclarationNode ep =>
                                            ResolveTypeReference(ep.Type, interfaceFileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics),
                                        _ => ErrorType.Instance
                                    };
                                    propSymbol.DeclaredType = propType;
                                    break;
                                }
                            case MethodMemberMemberDeclarationNode:
                                // Default methods with bodies get their types resolved via ResolveExplicitMemberTypeAnnotation.
                                ResolveExplicitMemberTypeAnnotation(member, typeScope, interfaceFileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                                break;
                        }
                    }

                    break;
                }
        }
    }


    /// <summary>
    /// Resolves explicit type annotation for a single class/struct member
    /// declaration — only the type annotation, not initializers or bodies.
    /// Sets <see cref="Symbol.DeclaredType"/> and parameter symbols for
    /// methods (via <see cref="PreResolveMethodSignature"/>). For constructors,
    /// indexers, operators, and cast operators, only the return/target type is
    /// resolved here — parameter types are resolved in Pass 2 when body
    /// resolution creates method scopes.
    /// <para>
    /// Phase 4 is the SOLE owner of explicit member type resolution. Diagnostics
    /// are emitted directly to the real diagnostic bag, and <see cref="Symbol.DeclaredType"/>
    /// is ALWAYS set (to the resolved type on success, or to <see cref="ErrorType.Instance"/>
    /// on failure). Pass 2 never attempts type resolution — it reads DeclaredType directly.
    /// </para>
    /// </summary>
    private static void ResolveExplicitMemberTypeAnnotation(
        MemberDeclarationNode memberDecl,
        Scope typeScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(memberDecl)
        {
            case FieldMemberMemberDeclarationNode fieldMember:
                {
                    var fieldDecl = fieldMember.Field;
                    if(symbolTable.GetDeclaredSymbol(fieldDecl) is not Symbol fieldSymbol || fieldSymbol.DeclaredType is not null)
                    {
                        break;
                    }

                    var fieldType = ResolveTypeReference(fieldDecl.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    fieldSymbol.DeclaredType = fieldType;
                    break;
                }
            case MethodMemberMemberDeclarationNode methodMember:
                {
                    // Use PreResolveMethodSignature which already has an idempotency guard
                    // and always sets DeclaredType (resolves return type + parameters).
                    PreResolveMethodSignature(methodMember.Method, typeScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
            case PropertyMemberMemberDeclarationNode propertyMember:
                {
                    switch(propertyMember.Property)
                    {
                        case BlockPropertyPropertyDeclarationNode blockProp:
                            {
                                if(symbolTable.GetDeclaredSymbol(blockProp) is not Symbol propSymbol || propSymbol.DeclaredType is not null)
                                {
                                    break;
                                }

                                var propType = ResolveTypeReference(blockProp.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                propSymbol.DeclaredType = propType;

                                // Also update the backing field's declared type if present.
                                var propInfo = propSymbol.PropertyMetadata;
                                if(propInfo?.BackingField is Symbol backingField)
                                {
                                    backingField.DeclaredType = propType;
                                }

                                break;
                            }
                        case ExpressionBodiedPropertyPropertyDeclarationNode exprProp:
                            {
                                if(symbolTable.GetDeclaredSymbol(exprProp) is not Symbol propSymbol || propSymbol.DeclaredType is not null)
                                {
                                    break;
                                }

                                var propType = ResolveTypeReference(exprProp.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                propSymbol.DeclaredType = propType;
                                break;
                            }
                    }

                    break;
                }
            case IndexerMemberMemberDeclarationNode indexerMember:
                {
                    var indexerDecl = indexerMember.Indexer;
                    if(symbolTable.GetDeclaredSymbol(indexerDecl) is not Symbol indexerSymbol || indexerSymbol.DeclaredType is not null)
                    {
                        break;
                    }

                    var indexerType = ResolveTypeReference(indexerDecl.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    indexerSymbol.DeclaredType = indexerType;
                    break;
                }
            case OperatorMemberMemberDeclarationNode operatorMember:
                {
                    var opDecl = operatorMember.Operator;
                    if(symbolTable.GetDeclaredSymbol(opDecl) is not Symbol opSymbol || opSymbol.DeclaredType is not null)
                    {
                        break;
                    }

                    var returnType = ResolveTypeReference(opDecl.ReturnType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    opSymbol.DeclaredType = returnType;
                    break;
                }
            case CastOperatorMemberMemberDeclarationNode castOpMember:
                {
                    var castOpDecl = castOpMember.CastOperator;
                    if(symbolTable.GetDeclaredSymbol(castOpDecl) is not Symbol castOpSymbol || castOpSymbol.DeclaredType is not null)
                    {
                        break;
                    }

                    var targetType = ResolveTypeReference(castOpDecl.TargetType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    castOpSymbol.DeclaredType = targetType;
                    break;
                }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Phase 2 — Resolve Type Forwards (aliases and newtype source types)
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves all type alias and newtype source types before inheritance
    /// resolution. Builds a dependency graph of all alias/newtype symbols,
    /// walks it in topological order (leaves first), and resolves each target
    /// using declaration-site scopes from <paramref name="fileScopesByUnit"/>.
    /// Cycles are detected and reported via <see cref="typeAliasResolutionStack"/>.
    /// For newtypes, only the source type identity is resolved — members are
    /// NOT cloned here (that is deferred to Phase 4b).
    /// </summary>
    private static void Pass1a_ResolveTypeForwards(
        ImmutableArray<Storm.Runtime.SyntaxNode> asts,

        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        Dictionary<Storm.Runtime.SyntaxNode, Scope> fileScopesByUnit,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Step 1: Collect all alias/newtype declaration nodes with their
        // associated file scopes and source texts.
        var forwardEntries = new List<TypeForwardEntry>();
        var nameToEntry = new Dictionary<string, TypeForwardEntry>();

        for(var i = 0; i < asts.Length; i++)
        {
            if(asts[i] is not CompilationUnitNode cu)
            {
                continue;
            }

            if(!fileScopesByUnit.TryGetValue(cu, out var fileScope))
            {
                continue;
            }

            var sourceText = i < compilation.Units.Length ? compilation.Units[i].Source : null;

            // Collect top-level type aliases.
            foreach(var item in cu.Items)
            {
                switch(item)
                {
                    case TypeItemTopLevelItemNode typeItem:
                        {
                            switch(typeItem.TypeDeclaration)
                            {
                                case TypeAliasTypeTypeDeclarationNode typeAliasTypeNode:
                                    {
                                        var aliasDecl = typeAliasTypeNode.TypeAliasDeclaration;
                                        if(symbolTable.GetDeclaredSymbol(aliasDecl) is not Symbol symbol || symbol.DeclaredType is not null)
                                        {
                                            break;
                                        }

                                        var name = aliasDecl.Name.Lexeme;
                                        var entry = new TypeForwardEntry(name, symbol, aliasDecl, null, fileScope, sourceText);
                                        forwardEntries.Add(entry);
                                        _ = nameToEntry.TryAdd(name, entry);
                                        break;
                                    }
                                case NewtypeTypeTypeDeclarationNode newtypeTypeNode:
                                    {
                                        var newtypeDecl = newtypeTypeNode.NewtypeDeclaration;
                                        if(symbolTable.GetDeclaredSymbol(newtypeDecl) is not Symbol symbol || symbol.DeclaredType is not null)
                                        {
                                            break;
                                        }

                                        var name = newtypeDecl.Name.Lexeme;
                                        var entry = new TypeForwardEntry(name, symbol, null, newtypeDecl, fileScope, sourceText);
                                        forwardEntries.Add(entry);
                                        _ = nameToEntry.TryAdd(name, entry);
                                        break;
                                    }
                            }

                            break;
                        }
                    case NamespaceItemTopLevelItemNode nsItem:
                        {
                            var nsDecl = nsItem.NamespaceDeclaration;
                            var nsAliases = GetNamespaceBodyTypeAliases(nsDecl);
                            foreach(var aliasDecl in nsAliases)
                            {
                                if(symbolTable.GetDeclaredSymbol(aliasDecl) is not Symbol symbol || symbol.DeclaredType is not null)
                                {
                                    continue;
                                }

                                var name = aliasDecl.Name.Lexeme;
                                var entry = new TypeForwardEntry(name, symbol, aliasDecl, null, fileScope, sourceText);
                                forwardEntries.Add(entry);
                                _ = nameToEntry.TryAdd(name, entry);
                            }

                            var nsNewtypes = GetNamespaceBodyNewtypes(nsDecl);
                            foreach(var newtypeDecl in nsNewtypes)
                            {
                                if(symbolTable.GetDeclaredSymbol(newtypeDecl) is not Symbol symbol || symbol.DeclaredType is not null)
                                {
                                    continue;
                                }

                                var name = newtypeDecl.Name.Lexeme;
                                var entry = new TypeForwardEntry(name, symbol, null, newtypeDecl, fileScope, sourceText);
                                forwardEntries.Add(entry);
                                _ = nameToEntry.TryAdd(name, entry);
                            }

                            break;
                        }
                }
            }
        }

        if(forwardEntries.Count == 0)
        {
            return;
        }

        // Step 2: Build the dependency graph.
        // For each alias/newtype, extract the target type name and check if
        // it references another alias/newtype in our set.
        var dependsOn = new Dictionary<string, List<string>>();
        var dependedBy = new Dictionary<string, List<string>>();
        var inDegree = new Dictionary<string, int>();

        foreach(var entry in forwardEntries)
        {
            dependsOn[entry.Name] = new List<string>();
            if(!dependedBy.ContainsKey(entry.Name))
            {
                dependedBy[entry.Name] = new List<string>();
            }

            _ = inDegree.TryAdd(entry.Name, 0);
        }

        foreach(var entry in forwardEntries)
        {
            var targetName = entry.AliasDecl is not null
                ? ExtractRefinableTypeExpressionName(entry.AliasDecl.Type, entry.SourceText)
                : ExtractTypeReferenceName(entry.NewtypeDecl!.SourceType, entry.SourceText);

            if(!string.IsNullOrEmpty(targetName) && nameToEntry.ContainsKey(targetName) && targetName != entry.Name)
            {
                dependsOn[entry.Name].Add(targetName);
                if(!dependedBy.ContainsKey(targetName))
                {
                    dependedBy[targetName] = new List<string>();
                }

                dependedBy[targetName].Add(entry.Name);
                inDegree[entry.Name] = inDegree.GetValueOrDefault(entry.Name) + 1;
            }
        }

        // Step 3: Topological sort using Kahn's algorithm (leaves first).
        var queue = new Queue<string>();
        foreach(var (name, degree) in inDegree)
        {
            if(degree == 0)
            {
                queue.Enqueue(name);
            }
        }

        var resolveOrder = new List<TypeForwardEntry>();
        while(queue.Count > 0)
        {
            var current = queue.Dequeue();
            if(nameToEntry.TryGetValue(current, out var entry))
            {
                resolveOrder.Add(entry);
            }

            if(dependedBy.TryGetValue(current, out var dependents))
            {
                foreach(var dep in dependents)
                {
                    inDegree[dep]--;
                    if(inDegree[dep] == 0)
                    {
                        queue.Enqueue(dep);
                    }
                }
            }
        }

        // Any entries not in resolveOrder are part of a cycle.
        // They will be resolved below and cycle detection will fire.
        foreach(var entry in forwardEntries)
        {
            if(!resolveOrder.Contains(entry))
            {
                resolveOrder.Add(entry);
            }
        }

        // Step 4: Resolve in topological order.
        // Initialize the shared resolution stack for cycle detection.
        typeAliasResolutionStack ??= new HashSet<string>();

        foreach(var entry in resolveOrder)
        {
            // Skip if already resolved (e.g., resolved transitively as a dependency).
            if(entry.Symbol.DeclaredType is not null)
            {
                continue;
            }

            if(entry.AliasDecl is not null)
            {
                ResolveTypeAliasDeclaration(
                    entry.AliasDecl, entry.FileScope, symbolTable,
                    ambientTypeResolver, entry.SourceText, diagnostics);
            }
            else if(entry.NewtypeDecl is not null)
            {
                ResolveNewtypeSourceOnly(
                    entry.NewtypeDecl, entry.FileScope, symbolTable,
                    ambientTypeResolver, entry.SourceText, diagnostics);
            }
        }

        // Step 5: Member cloning for newtypes is handled by Phase 4b
        // (Pass1_5b_CloneNewtypeMembers) which runs after Phase 4 resolves
        // all explicit member types on source types.
    }

    /// <summary>
    /// Phase 4b: Clones all members from each newtype's source type into the
    /// newtype's member scope. Runs after Phase 4 (<see cref="Pass1_5_ResolveExplicitMemberTypes"/>)
    /// so that source type members carry fully-resolved <c>DeclaredType</c> values.
    /// For primitive (backend-backed) source types, also adds a synthetic 'Value' field.
    /// </summary>
    private static void Pass1_5b_CloneNewtypeMembers(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Newtype)
            {
                continue;
            }

            if(symbol.DeclaredType is not NewtypeType newtypeType)
            {
                continue;
            }

            // Skip if members have already been cloned (e.g., by a previous pass or re-entry).
            if(newtypeType.MemberScope.Members.Count > 0)
            {
                continue;
            }

            var sourceType = newtypeType.SourceType;
            var name = symbol.Name;

            CloneAllMembers(sourceType, newtypeType, name);

            // For primitive (backend-backed) source types, add a synthetic 'Value' field.
            var isBackendBacked = sourceType switch
            {
                StructType st => st.IsBackendBacked,
                ClassType ct => ct.IsBackendBacked,
                _ => false,
            };
            if(isBackendBacked)
            {
                var targetScope = (Scope)newtypeType.MemberScope;
                var valueSymbol = new Symbol(
                    "Value",
                    SymbolKind.Field,
                    SymbolOrigin.UserCode,
                    targetScope,
                    sourceType,
                    declarationSpan: null,
                    isIntrinsic: false,
                    hasBody: false);
                targetScope.AddMember(valueSymbol);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Phase 5 — Resolve Accessibility and Sealed Flag
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Walks every registered symbol in the symbol table and resolves a concrete
    /// <see cref="Accessibility"/> value. For each declaration:
    /// <list type="number">
    ///   <item>Calls <see cref="AccessibilityFacts.TryReduceExplicit"/> on its modifier list.
    ///         If an explicit modifier is present, stores it.</item>
    ///   <item>Otherwise resolves the scope-kind default:
    ///         namespace/compilation (global) → <see cref="Accessibility.Internal"/>;
    ///         class/struct → <see cref="Accessibility.Private"/>;
    ///         interface (abstract)/enum → <see cref="Accessibility.Public"/>;
    ///         nested type (declared inside a class/struct) → <see cref="Accessibility.Private"/>.</item>
    /// </list>
    /// Also sets <see cref="ClassType.IsSealed"/> and <see cref="StructType.IsSealed"/>
    /// from <see cref="AccessibilityFacts.HasSealed"/>.
    /// <para>
    /// After this pass completes, every applicable declaration carries a concrete
    /// <see cref="Accessibility"/> and every class/struct a concrete <c>IsSealed</c>.
    /// </para>
    /// </summary>
    private static void ResolveAccessibilityAndSealed(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol is not Symbol mutableSymbol)
            {
                continue;
            }

            var declaringNode = symbolTable.GetDeclaringNode(symbol);
            if(declaringNode is null)
            {
                continue;
            }

            // Extract the modifier list from the declaring AST node.
            var modifiers = GetModifiersFromDeclaringNode(declaringNode);
            if(modifiers is null)
            {
                continue;
            }

            // Reduce explicit accessibility from modifiers.
            var explicit_ = AccessibilityFacts.TryReduceExplicit(modifiers, out _);

            if(explicit_.HasValue)
            {
                mutableSymbol.Accessibility = explicit_.Value;
            }
            else
            {
                // Resolve scope-kind default.
                mutableSymbol.Accessibility = GetScopeKindDefault(symbol, symbolTable);
            }

            // Set accessibility on the type object as well (types carry their own Accessibility property).
            switch(symbol.DeclaredType)
            {
                case ClassType classType:
                    classType.Accessibility = mutableSymbol.Accessibility;
                    classType.IsSealed = AccessibilityFacts.HasSealed(modifiers);
                    break;
                case StructType structType:
                    structType.Accessibility = mutableSymbol.Accessibility;
                    structType.IsSealed = AccessibilityFacts.HasSealed(modifiers);
                    break;
                case AbstractType abstractType:
                    abstractType.Accessibility = mutableSymbol.Accessibility;
                    break;
                case EnumType enumType:
                    enumType.Accessibility = mutableSymbol.Accessibility;
                    break;
                case TypeAliasType typeAliasType:
                    typeAliasType.Accessibility = mutableSymbol.Accessibility;
                    break;
                case NewtypeType newtypeType:
                    newtypeType.Accessibility = mutableSymbol.Accessibility;
                    break;
            }
        }
    }

    /// <summary>
    /// Extracts the <see cref="IReadOnlyList{ModifierNode}"/> from a declaring AST node.
    /// Returns <see langword="null"/> for nodes that do not carry modifiers (e.g., parameters, locals).
    /// </summary>
    private static IReadOnlyList<ModifierNode>? GetModifiersFromDeclaringNode(Storm.Runtime.SyntaxNode declaringNode)
    {
        return declaringNode switch
        {
            TypeBodyDeclarationNode typeBody => typeBody.Modifiers,
            FieldDeclarationNode field => field.Modifiers,
            MethodDeclarationNode method => method.Modifiers,
            ConstructorDeclarationNode ctor => ctor.Modifiers,
            OperatorDeclarationNode op => op.Modifiers,
            CastOperatorDeclarationNode castOp => castOp.Modifiers,
            EnumDeclarationNode enumDecl => enumDecl.Modifiers,
            TypeAliasDeclarationNode alias => alias.Modifiers,
            NewtypeDeclarationNode newtype => newtype.Modifiers,
            _ => GetPropertyModifiers(declaringNode),
        };
    }

    /// <summary>
    /// Extracts modifiers from property-like declaration nodes.
    /// </summary>
    private static IReadOnlyList<ModifierNode>? GetPropertyModifiers(Storm.Runtime.SyntaxNode declaringNode)
    {
        return declaringNode switch
        {
            BlockPropertyPropertyDeclarationNode bp => bp.Modifiers,
            ExpressionBodiedPropertyPropertyDeclarationNode ep => ep.Modifiers,
            IndexerDeclarationNode indexer => indexer.Modifiers,
            _ => null,
        };
    }

    /// <summary>
    /// Determines the scope-kind default accessibility for a symbol with no explicit modifier.
    /// The default is derived from the symbol's enclosing scope kind:
    /// <list type="bullet">
    ///   <item>namespace / compilation (global) scope → <see cref="Accessibility.Internal"/></item>
    ///   <item>class or struct scope → <see cref="Accessibility.Private"/></item>
    ///   <item>interface (abstract type) or enum scope → <see cref="Accessibility.Public"/></item>
    ///   <item>nested type (type declared inside another type) → <see cref="Accessibility.Private"/></item>
    /// </list>
    /// </summary>
    private static Accessibility GetScopeKindDefault(ISymbol symbol, SymbolTable symbolTable)
    {
        // A type-declaration symbol's "enclosing scope" is the scope it was added to.
        // If that scope is a namespace scope (whose parent is global, or which is the
        // global scope itself), the default is Internal. If it's a type's member scope,
        // the default depends on the enclosing type kind.
        var containingScope = symbol.ContainingScope;

        // For member-level declarations (fields, methods, etc.), the containing scope
        // IS the type's member scope. Walk registered types to find which type owns it.
        var enclosingTypeKind = FindEnclosingTypeKind(containingScope, symbolTable);

        return enclosingTypeKind switch
        {
            // Members inside a class or struct default to Private.
            EnclosingScopeKind.Class => Accessibility.Private,
            EnclosingScopeKind.Struct => Accessibility.Private,
            // Members inside an interface (abstract type) or enum default to Public.
            EnclosingScopeKind.Abstract => Accessibility.Public,
            EnclosingScopeKind.Enum => Accessibility.Public,
            // Top-level declarations in a namespace/compilation scope default to Internal.
            _ => Accessibility.Internal,
        };
    }

    /// <summary>
    /// The kind of the enclosing scope for scope-kind default resolution.
    /// </summary>
    private enum EnclosingScopeKind
    {
        /// <summary>Namespace or compilation (global) scope.</summary>
        NamespaceOrGlobal,
        /// <summary>A class's member scope.</summary>
        Class,
        /// <summary>A struct's member scope.</summary>
        Struct,
        /// <summary>An abstract type (interface) member scope.</summary>
        Abstract,
        /// <summary>An enum member scope.</summary>
        Enum,
    }

    /// <summary>
    /// Determines what kind of enclosing scope contains the given scope. Searches
    /// registered type symbols to find one whose member scope matches, returning
    /// the appropriate <see cref="EnclosingScopeKind"/>.
    /// </summary>
    private static EnclosingScopeKind FindEnclosingTypeKind(IScope containingScope, SymbolTable symbolTable)
    {
        foreach(var typeSymbol in symbolTable.AllSymbols)
        {
            var memberScope = typeSymbol.DeclaredType switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                AbstractType at => at.MemberScope,
                EnumType et => et.MemberScope,
                _ => null,
            };

            if(memberScope is not null && ReferenceEquals(memberScope, containingScope))
            {
                return typeSymbol.Kind switch
                {
                    SymbolKind.Class => EnclosingScopeKind.Class,
                    SymbolKind.Struct => EnclosingScopeKind.Struct,
                    SymbolKind.Abstract => EnclosingScopeKind.Abstract,
                    SymbolKind.Enum => EnclosingScopeKind.Enum,
                    _ => EnclosingScopeKind.NamespaceOrGlobal,
                };
            }
        }

        // No type owns this scope → must be namespace or global.
        return EnclosingScopeKind.NamespaceOrGlobal;
    }

    /// <summary>
    /// Resolves a newtype declaration's source type reference and creates a
    /// <see cref="NewtypeType"/> WITHOUT cloning members from the source type.
    /// Member cloning is deferred to Phase 4b (after all explicit member types
    /// are resolved on the source type). Extends the
    /// <see cref="typeAliasResolutionStack"/> cycle detection to cover newtypes.
    /// </summary>
    private static void ResolveNewtypeSourceOnly(
        NewtypeDeclarationNode newtypeDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(symbolTable.GetDeclaredSymbol(newtypeDecl) is not Symbol newtypeSymbol)
        {
            return;
        }

        // If already resolved, skip.
        if(newtypeSymbol.DeclaredType is not null)
        {
            return;
        }

        var name = newtypeDecl.Name.Lexeme;

        // Initialize the resolution stack if needed.
        typeAliasResolutionStack ??= new HashSet<string>();

        // Check for cycles (extending alias cycle detection to newtypes).
        if(!typeAliasResolutionStack.Add(name))
        {
            // Cycle detected — report diagnostic and assign ErrorType.
            diagnostics.Add(MakeDiagnosticWithLocation(
                CyclicTypeAlias.Value,
                DiagnosticSeverity.Error,
                $"Type '{name}' forms a cycle.",
                newtypeDecl,
                sourceText));
            newtypeSymbol.DeclaredType = ErrorType.Instance;
            return;
        }

        try
        {
            // Resolve the source type reference.
            var sourceType = ResolveTypeReference(
                newtypeDecl.SourceType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

            if(sourceType is ErrorType)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    UnresolvedNewtypeSource.Value,
                    DiagnosticSeverity.Error,
                    $"Type '{ExtractTypeReferenceName(newtypeDecl.SourceType, sourceText)}' could not be resolved in newtype '{name}'.",
                    newtypeDecl.SourceType,
                    sourceText));
                newtypeSymbol.DeclaredType = ErrorType.Instance;
                return;
            }

            // If the source resolves to a type alias, unwrap to the underlying type.
            if(sourceType is TypeAliasType aliasType)
            {
                sourceType = aliasType.UnderlyingType;
            }

            // Create the NewtypeType with source type identity only.
            // Members are NOT cloned here — that is deferred to Phase 4b.
            var newtypeType = new NewtypeType(name, sourceType);
            newtypeSymbol.DeclaredType = newtypeType;
        }
        finally
        {
            _ = typeAliasResolutionStack.Remove(name);
        }
    }

    /// <summary>
    /// Holds information about a type alias or newtype declaration that needs
    /// to be resolved during Phase 2 (type forwards).
    /// </summary>
    private sealed record TypeForwardEntry(
        string Name,
        Symbol Symbol,
        TypeAliasDeclarationNode? AliasDecl,
        NewtypeDeclarationNode? NewtypeDecl,
        Scope FileScope,
        SourceText? SourceText);

    // ── Type alias visited-set for cycle detection (Pass 2) ──────────────
    [ThreadStatic]
    private static HashSet<string>? typeAliasResolutionStack;

    /// <summary>
    /// Resolves a type alias declaration's target type reference and constructs
    /// a <see cref="TypeAliasType"/>. Detects cycles using a visited-set and
    /// reports <see cref="CyclicTypeAlias"/> on cycle, assigning <see cref="ErrorType"/>.
    /// Reports <see cref="UnresolvedTypeAliasTarget"/> if the target type cannot be resolved.
    /// </summary>
    private static void ResolveTypeAliasDeclaration(
        TypeAliasDeclarationNode aliasDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(symbolTable.GetDeclaredSymbol(aliasDecl) is not Symbol aliasSymbol)
        {
            return;
        }

        // If already resolved (e.g., resolved as a dependency of another alias), skip.
        if(aliasSymbol.DeclaredType is not null)
        {
            return;
        }

        var aliasName = aliasDecl.Name.Lexeme;

        // Initialize the resolution stack if needed.
        typeAliasResolutionStack ??= new HashSet<string>();

        // Check for cycles.
        if(!typeAliasResolutionStack.Add(aliasName))
        {
            // Cycle detected — report diagnostic and assign ErrorType.
            diagnostics.Add(MakeDiagnosticWithLocation(
                CyclicTypeAlias.Value,
                DiagnosticSeverity.Error,
                $"Type alias '{aliasName}' forms a cycle.",
                aliasDecl,
                sourceText));
            aliasSymbol.DeclaredType = ErrorType.Instance;
            return;
        }

        try
        {
            // Create a resolution scope that includes the alias's type parameters
            // so that type parameter names (e.g., T in type Box<T> = GenericBox<T>)
            // can be resolved when resolving the target type reference.
            var resolutionScope = fileScope;
            if(aliasSymbol.TypeParameters.Count > 0)
            {
                resolutionScope = new Scope(parent: fileScope);
                foreach(var tp in aliasSymbol.TypeParameters)
                {
                    var (tpName9625, _) = GetTypeParameterNameAndOrdinal(tp);
                    var tpSymbol = new Symbol(tpName9625, SymbolKind.Class, SymbolOrigin.UserCode, resolutionScope, tp, null);
                    resolutionScope.AddMember(tpSymbol);
                }
            }

            // Resolve the target type reference.
            // The type alias now uses RefinableTypeExpression which wraps SingleTypeRef(s).
            // When a refinement predicate is present, this constructs a RefinementType.
            var targetType = ResolveRefinableTypeExpression(
                aliasDecl.Type, resolutionScope, ambientTypeResolver, symbolTable, sourceText, diagnostics, aliasName);

            // Check if the resolved type is an error (unresolved).
            if(targetType is ErrorType)
            {
                // Only emit the unresolved-target diagnostic if the error wasn't caused
                // by an incompatible refinement predicate (which already emitted MIST_TC_0072).
                if(!HasRefinementPredicate(aliasDecl.Type))
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        UnresolvedTypeAliasTarget.Value,
                        DiagnosticSeverity.Error,
                        $"Type '{ExtractRefinableTypeExpressionName(aliasDecl.Type, sourceText)}' could not be resolved in type alias '{aliasName}'.",
                        aliasDecl.Type,
                        sourceText));
                }

                aliasSymbol.DeclaredType = ErrorType.Instance;
                return;
            }

            // If the target resolves to another TypeAliasType, ensure it's fully resolved
            // (handles transitive aliases like type A = B; type B = int;).
            if(targetType is TypeAliasType aliasTarget)
            {
                targetType = aliasTarget.UnderlyingType;
            }

            // If the resolved type is a RefinementType, store it directly as the alias's
            // declared type. The RefinementType already carries the alias name.
            if(targetType is RefinementType refinementType)
            {
                aliasSymbol.DeclaredType = refinementType;
            }
            else if(targetType is UnionType unionType && HasRefinementConstituent(unionType))
            {
                // Union with at least one refinement constituent — store directly.
                aliasSymbol.DeclaredType = unionType;
            }
            else
            {
                // Construct the TypeAliasType for non-refined aliases.
                var typeParams = aliasSymbol.TypeParameters;
                var typeAliasType = new TypeAliasType(aliasName, targetType, typeParams);
                aliasSymbol.DeclaredType = typeAliasType;
            }
        }
        finally
        {
            _ = typeAliasResolutionStack.Remove(aliasName);
        }
    }

    /// <summary>
    /// Resolves a member-level type alias declaration (e.g., <c>public type ArrayBounds = ZeroOrPositiveInt and &lt; Length;</c>).
    /// The resolution scope includes the enclosing type's scope so that dependent parameter names (like <c>Length</c>)
    /// can be referenced in the type expression.
    /// </summary>
    private static void ResolveMemberTypeAliasDeclaration(
        TypeAliasDeclarationNode aliasDecl,
        Scope typeScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(symbolTable.GetDeclaredSymbol(aliasDecl) is not Symbol aliasSymbol)
        {
            return;
        }

        // If already resolved, skip.
        if(aliasSymbol.DeclaredType is not null)
        {
            return;
        }

        var aliasName = aliasDecl.Name.Lexeme;

        // Create a resolution scope that includes the type's scope (for dependent parameters
        // like Length) and the file scope (for external types like ZeroOrPositiveInt).
        // The type scope is the parent so that dependent parameter references resolve first.
        var resolutionScope = new Scope(parent: fileScope);

        // Add type scope members to the resolution scope so dependent parameters are visible.
        foreach(var member in typeScope.Members)
        {
            resolutionScope.AddMember(member);
        }

        // Add alias's own type parameters if any.
        if(aliasSymbol.TypeParameters.Count > 0)
        {
            foreach(var tp in aliasSymbol.TypeParameters)
            {
                var (tpName, _) = GetTypeParameterNameAndOrdinal(tp);
                var tpSymbol = new Symbol(tpName, SymbolKind.Class, SymbolOrigin.UserCode, resolutionScope, tp, null);
                resolutionScope.AddMember(tpSymbol);
            }
        }

        // Resolve the target type reference.
        var targetType = ResolveRefinableTypeExpression(
            aliasDecl.Type, resolutionScope, ambientTypeResolver, symbolTable, sourceText, diagnostics, aliasName);

        if(targetType is ErrorType)
        {
            aliasSymbol.DeclaredType = ErrorType.Instance;
            return;
        }

        // If the target resolves to another TypeAliasType, unwrap it.
        if(targetType is TypeAliasType aliasTarget)
        {
            targetType = aliasTarget.UnderlyingType;
        }

        // Store the resolved type as the alias's declared type.
        if(targetType is RefinementType refinementType)
        {
            aliasSymbol.DeclaredType = refinementType;
        }
        else if(targetType is UnionType unionType && HasRefinementConstituent(unionType))
        {
            aliasSymbol.DeclaredType = unionType;
        }
        else
        {
            var typeParams = aliasSymbol.TypeParameters;
            var typeAliasType = new TypeAliasType(aliasName, targetType, typeParams);
            aliasSymbol.DeclaredType = typeAliasType;
        }
    }

    /// <summary>
    /// Resolves a newtype declaration by resolving the source type reference,
    /// creating a <see cref="NewtypeType"/>, and cloning all members from the
    /// source type's scope into the newtype's member scope.
    /// Reports <see cref="UnresolvedNewtypeSource"/> if the source type cannot be resolved.
    /// </summary>
    private static void ResolveNewtypeDeclaration(
        NewtypeDeclarationNode newtypeDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(symbolTable.GetDeclaredSymbol(newtypeDecl) is not Symbol newtypeSymbol)
        {
            return;
        }

        // If already resolved, skip.
        if(newtypeSymbol.DeclaredType is not null)
        {
            return;
        }

        var name = newtypeDecl.Name.Lexeme;

        // Resolve the source type reference.
        var sourceType = ResolveTypeReference(
            newtypeDecl.SourceType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        if(sourceType is ErrorType)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                UnresolvedNewtypeSource.Value,
                DiagnosticSeverity.Error,
                $"Type '{ExtractTypeReferenceName(newtypeDecl.SourceType, sourceText)}' could not be resolved in newtype '{name}'.",
                newtypeDecl.SourceType,
                sourceText));
            newtypeSymbol.DeclaredType = ErrorType.Instance;
            return;
        }

        // If the source resolves to a type alias, unwrap to the underlying type.
        if(sourceType is TypeAliasType aliasType)
        {
            sourceType = aliasType.UnderlyingType;
        }

        // Create the NewtypeType and clone all members from the source type's scope.
        var newtypeType = new NewtypeType(name, sourceType);
        CloneAllMembers(sourceType, newtypeType, name);

        // For primitive (backend-backed) source types, add a synthetic 'Value' field
        // so that member access like `myNewtype.Value` resolves in the semantic model.
        // The transpiler emits these as readonly struct wrappers with a Value property.
        var isBackendBacked = sourceType switch
        {
            StructType st => st.IsBackendBacked,
            ClassType ct => ct.IsBackendBacked,
            _ => false,
        };
        if(isBackendBacked)
        {
            var targetScope = (Scope)newtypeType.MemberScope;
            var valueSymbol = new Symbol(
                "Value",
                SymbolKind.Field,
                SymbolOrigin.UserCode,
                targetScope,
                sourceType,
                declarationSpan: null,
                isIntrinsic: false,
                hasBody: false);
            targetScope.AddMember(valueSymbol);
        }

        newtypeSymbol.DeclaredType = newtypeType;
    }

    /// <summary>
    /// Clones all member symbols from the source type's scope into the newtype's member scope.
    /// Handles fields, properties, methods, constructors (with name updated), operators,
    /// cast operators, and indexers.
    /// </summary>
    private static void CloneAllMembers(
        IType sourceType,
        NewtypeType newtypeType,
        string newtypeName)
    {
        var sourceScope = GetMemberScope(sourceType);
        if(sourceScope is null)
        {
            return;
        }

        var targetScope = (Scope)newtypeType.MemberScope;

        foreach(var member in sourceScope.Members)
        {
            var clonedName = member.Kind == SymbolKind.Constructor
                ? newtypeName
                : member.Name;

            var cloned = new Symbol(
                clonedName,
                member.Kind,
                SymbolOrigin.UserCode,
                targetScope,
                member.DeclaredType,
                member.DeclarationSpan,
                isIntrinsic: member is Symbol s && s.IsIntrinsic,
                hasBody: member is Symbol s2 && s2.HasBody);

            // Copy property metadata if present.
            if(member is Symbol sourceSym && sourceSym.PropertyMetadata is not null)
            {
                cloned.PropertyMetadata = sourceSym.PropertyMetadata;
            }

            // Copy type parameters if present (for generic methods).
            if(member is Symbol sourceMethodSym && sourceMethodSym.TypeParameters.Count > 0)
            {
                cloned.TypeParameters = sourceMethodSym.TypeParameters;
            }

            // Copy readonly status.
            if(member is Symbol readonlySym)
            {
                cloned.ReadonlyStatus = readonlySym.ReadonlyStatus;
            }

            targetScope.AddMember(cloned);
        }
    }

    private static void ResolveBodyTypeDeclaration(
        TypeBodyDeclarationNode typeBodyDecl,
        Scope fileScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var typeSymbol = symbolTable.GetDeclaredSymbol(typeBodyDecl);
        if(typeSymbol is null)
        {
            return;
        }

        switch(typeSymbol.DeclaredType)
        {
            case ClassType classType:
                {
                    var typeScope = (Scope)classType.MemberScope;

                    // Generate implicit properties for dependent type parameters.
                    GenerateDependentTypeProperties(classType.TypeParameters, typeScope, classType, sourceText, diagnostics);

                    // Pre-resolve member type aliases before other members, so that types like
                    // ArrayBounds/SpanBounds are available when referenced in parameter types.
                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        if(memberDecl is NestedTypeAliasMemberMemberDeclarationNode memberTypeAlias)
                        {
                            ResolveMemberTypeAliasDeclaration(memberTypeAlias.NestedTypeAlias, typeScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    // Create a per-class resolution scope that layers the class's type
                    // parameters on top of the file scope. This ensures that type parameter
                    // names (e.g., T in GenericBox<T>) resolve to the correct
                    // TypeParameterType instance for THIS class, not a same-named parameter
                    // from a different generic class in the same file.
                    var classFileScope = CreateTypeParameterScope(typeScope, fileScope);

                    // Phase 4 already resolved all method signatures globally via
                    // PreResolveMethodSignature — no per-class pre-pass needed here.

                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        ResolveMemberDeclaration(memberDecl, typeScope, classFileScope, classType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    break;
                }
            case StructType structType:
                {
                    var typeScope = (Scope)structType.MemberScope;

                    // Generate implicit properties for dependent type parameters.
                    GenerateDependentTypeProperties(structType.TypeParameters, typeScope, structType, sourceText, diagnostics);

                    // Pre-resolve member type aliases before other members, so that types like
                    // SpanBounds are available when referenced in parameter types.
                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        if(memberDecl is NestedTypeAliasMemberMemberDeclarationNode memberTypeAlias)
                        {
                            ResolveMemberTypeAliasDeclaration(memberTypeAlias.NestedTypeAlias, typeScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    // Create a per-struct resolution scope that layers the struct's type
                    // parameters on top of the file scope.
                    var structFileScope = CreateTypeParameterScope(typeScope, fileScope);

                    foreach(var memberDecl in typeBodyDecl.Members)
                    {
                        ResolveMemberDeclaration(memberDecl, typeScope, structFileScope, structType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    break;
                }
            case AbstractType abstractType:
                {
                    // Create a per-abstract-type resolution scope that layers the abstract type's
                    // type parameters on top of the file scope.
                    var typeScope = (Scope)abstractType.MemberScope;

                    // Generate implicit properties for dependent type parameters.
                    GenerateDependentTypeProperties(abstractType.TypeParameters, typeScope, abstractType, sourceText, diagnostics);

                    // Phase 4 already resolved all abstract type member types (return types,
                    // property types, parameter types). Nothing else to do here — abstracts
                    // have no bodies to resolve.
                    break;
                }
        }
    }


    private static void ResolveMemberDeclaration(
        MemberDeclarationNode memberDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(memberDecl)
        {
            case FieldMemberMemberDeclarationNode fieldMember:
                ResolveFieldDeclaration(fieldMember.Field, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ConstructorMemberMemberDeclarationNode ctorMember:
                ResolveConstructorDeclaration(ctorMember.Constructor, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case MethodMemberMemberDeclarationNode methodMember:
                ResolveMethodDeclaration(methodMember.Method, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case OperatorMemberMemberDeclarationNode operatorMember:
                ResolveOperatorDeclaration(operatorMember.Operator, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case CastOperatorMemberMemberDeclarationNode castOpMember:
                ResolveCastOperatorDeclaration(castOpMember.CastOperator, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case PropertyMemberMemberDeclarationNode propertyMember:
                ResolvePropertyDeclaration(propertyMember.Property, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case IndexerMemberMemberDeclarationNode indexerMember:
                ResolveIndexerDeclaration(indexerMember.Indexer, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case NestedBodyTypeMemberMemberDeclarationNode nestedBodyMember:
                ResolveTypeDeclaration(new BodyTypeTypeDeclarationNode { TypeBody = nestedBodyMember.NestedBody }, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case NestedEnumMemberMemberDeclarationNode nestedEnumMember:
                ResolveTypeDeclaration(new EnumTypeTypeDeclarationNode { EnumDeclaration = nestedEnumMember.NestedEnum }, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case NestedNewtypeMemberMemberDeclarationNode nestedNewtypeMember:
                ResolveTypeDeclaration(new NewtypeTypeTypeDeclarationNode { NewtypeDeclaration = nestedNewtypeMember.NestedNewtype }, fileScope, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case NestedTypeAliasMemberMemberDeclarationNode nestedTypeAliasMember:
                ResolveMemberTypeAliasDeclaration(nestedTypeAliasMember.NestedTypeAlias, typeScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    private static void ResolveFieldDeclaration(
        FieldDeclarationNode fieldDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of field type resolution — DeclaredType is
        // always set before Pass 2 runs. Read it directly.
        var fieldSymbol = symbolTable.GetDeclaredSymbol(fieldDecl) as Symbol;
        var fieldType = fieldSymbol?.DeclaredType ?? ErrorType.Instance;

        // Storage-ban check (unknown-type feature, Task 11.1, Requirements
        // 5.1, 7.5, 7.6, 16.1). Emitted BEFORE the symbol's declared type is
        // updated so downstream passes still see the banned type on the
        // symbol — the design note for Task 11 is explicit that we do not
        // substitute ErrorType here. Only the diagnostic is emitted.
        if(TypeContainment.IsStorageBanned(fieldType))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                UnknownAsFieldType.Value,
                DiagnosticSeverity.Error,
                $"Field '{enclosingType.DisplayName}.{fieldDecl.Name.Lexeme}' of type '{fieldType.DisplayName}' cannot have 'unknown' in its declared type: 'unknown' is not permitted as the type of writable storage.",
                fieldDecl,
                sourceText));
        }

        // Field hiding detection (struct-inheritance spec, Requirement 3.3).
        // If the enclosing type is a struct with a base struct, check whether
        // the field name collides with any ancestor field.
        if(enclosingType is StructType structType && structType.BaseType is StructType baseForHiding)
        {
            var fieldName = fieldDecl.Name.Lexeme;
            var ancestorWithField = FindFieldInStructAncestors(baseForHiding, fieldName);
            if(ancestorWithField is not null)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    StructFieldHiding.Value,
                    DiagnosticSeverity.Error,
                    $"Field '{fieldName}' in struct '{structType.DisplayName}' hides field '{fieldName}' inherited from '{ancestorWithField.DisplayName}'.",
                    fieldDecl,
                    sourceText));
            }
        }

        // Resolve the optional initializer expression.
        // The grammar defines: initializer:(EQUAL Expression)?
        // With the bugfix, the Initializer property is now ExpressionNode? directly.
        if(fieldDecl.Initializer is ExpressionNode initExpr)
        {
            var isStatic = fieldDecl.Modifiers.Any(m => m is StaticModifierModifierNode);
            emptyArrayTargetType = fieldType;
            if(IsFuncType(fieldType))
            {
                lambdaTargetType = fieldType;
            }
            else if(fieldType is DelegateType)
            {
                lambdaTargetType = fieldType;
            }

            voidLiteralTargetType = fieldType;
            targetTypedNewTargetType = fieldType;
            _ = ResolveExpression(initExpr, typeScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            emptyArrayTargetType = null;
            lambdaTargetType = null;
            voidLiteralTargetType = null;
            targetTypedNewTargetType = null;
        }
    }

    private static void ResolveConstructorDeclaration(
        ConstructorDeclarationNode ctorDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Constructors don't have an explicit return type (they implicitly return
        // the enclosing type). Phase 4 does not set DeclaredType for constructors.
        // Pass 2 only needs to register parameters and resolve the body.

        // Create a method scope for the constructor body.
        var methodScope = new Scope(parent: typeScope);

        // Register parameters.
        if(ctorDecl.Parameters is not null)
        {
            RegisterParameters(ctorDecl.Parameters, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
        }

        // Register with-clause bindings as local variables in the constructor scope.
        foreach(var withClause in ctorDecl.WithClauses)
        {
            // Skip this-tier annotations — they don't introduce local bindings.
            if(withClause is not ContextWithClauseWithClauseNode contextClause)
            {
                continue;
            }

            var contextType = ResolveTypeReference(contextClause.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
            var clauseName = contextClause.Name.Lexeme;
            var clauseSpan = ToMistSourceSpan(contextClause.Name.Span);

            CheckDuplicateLocal(clauseName, methodScope, sourceText, diagnostics);

            var clauseSymbol = new Symbol(clauseName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, methodScope, contextType, clauseSpan);
            methodScope.AddMember(clauseSymbol);
            symbolTable.Register(clauseSymbol, withClause);
        }

        // Resolve constructor chain arguments if present.
        if(ctorDecl.Chain is ThisChainConstructorChainNode thisChain && thisChain.Arguments is not null)
        {
            ResolveArgumentList(thisChain.Arguments, methodScope, fileScope, enclosingType, /* isStatic */ false, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
        else if(ctorDecl.Chain is BaseChainConstructorChainNode baseChain && baseChain.Arguments is not null)
        {
            ResolveArgumentList(baseChain.Arguments, methodScope, fileScope, enclosingType, /* isStatic */ false, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        // Resolve the body. A no-body (;) form is accepted by the grammar but
        // has no statements to resolve; semantic validation of whether ; is
        // permitted on this declaration is done elsewhere.
        if(ctorDecl.Body.GetBlock() is BlockNode ctorBlock)
        {
            ResolveBlock(ctorBlock, methodScope, fileScope, enclosingType, /* isStatic */ false, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    /// <summary>
    /// Pre-resolves a method's signature (return type + parameters) without resolving
    /// the body. Called by Phase 4 to populate DeclaredType for all methods globally.
    /// This ensures cross-file references can access parameter types for lambda
    /// target-type propagation during body resolution.
    /// Return type diagnostics are emitted to the real diagnostic bag (Phase 4 owns
    /// return type resolution). Parameter type diagnostics use a temp bag because
    /// Pass 2's RegisterParameters is the canonical source for parameter diagnostics.
    /// </summary>
    private static void PreResolveMethodSignature(
        MethodDeclarationNode methodDecl,
        Scope typeScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(symbolTable.GetDeclaredSymbol(methodDecl) is not Symbol methodSymbol || methodSymbol.DeclaredType is not null)
        {
            return; // Already resolved or no symbol.
        }

        // Resolve the return type (diagnostics go to the real bag since this is the
        // canonical resolution point for the return type).
        var returnType = ResolveTypeReference(methodDecl.ReturnType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        // Set the method symbol's declared type.
        var isAsync = methodDecl.Modifiers.Any(m => m is AsyncModifierModifierNode);
        if(isAsync)
        {
            methodSymbol.IsAsync = true;
            methodSymbol.DeclaredReturnType = returnType;
            var effectiveReturnType = ConstructTaskType(returnType, fileScope, symbolTable);
            methodSymbol.EffectiveReturnType = effectiveReturnType;
            methodSymbol.DeclaredType = effectiveReturnType;
        }
        else
        {
            methodSymbol.DeclaredReturnType = returnType;
            methodSymbol.EffectiveReturnType = returnType;
            methodSymbol.DeclaredType = returnType;
        }

        // Resolve parameter types and store them on the method symbol's Parameters
        // collection so that ParameterSignature.Extract can find them during body
        // resolution of other methods in the same class. Use a temporary diagnostic
        // bag — the canonical parameter diagnostics are emitted by RegisterParameters
        // in Pass 2 when body scope symbols are created.
        if(methodDecl.Parameters is not null)
        {
            var tempDiagnostics = new DiagnosticBag();
            var paramSymbols = new List<ISymbol>();
            foreach(var child in methodDecl.Parameters.Children())
            {
                if(child is ParameterNode param)
                {
                    var paramType = ResolveTypeReference(param.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, tempDiagnostics);
                    var paramSym = new Symbol(param.Name.Lexeme, SymbolKind.Parameter, SymbolOrigin.UserCode, typeScope, paramType, null);
                    paramSymbols.Add(paramSym);
                }
            }

            methodSymbol.Parameters = paramSymbols;
        }
    }

    private static void ResolveMethodDeclaration(
        MethodDeclarationNode methodDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 (via PreResolveMethodSignature) is the sole owner of method
        // return type resolution — DeclaredType is always set before Pass 2 runs.
        // Read it directly.
        var methodSymbol = symbolTable.GetDeclaredSymbol(methodDecl) as Symbol;
        var returnType = methodSymbol?.DeclaredReturnType ?? methodSymbol?.DeclaredType ?? ErrorType.Instance;

        if(methodSymbol is not null)
        {
            // When the parser sees "public owned Foo Method(...)", it may parse "owned"
            // as a modifier (OwnedModifier) rather than as the returnOwnership specifier.
            // In that case, ReturnOwnership is null but the method has an OwnedModifier.
            // We treat this as OwnershipTier.Owned for the return type.
            if(methodDecl.ReturnOwnership is not null)
            {
                // When the parser sees "readonly ref Foo Method(...)", it may parse
                // "readonly" as a modifier and "ref" as the returnOwnership specifier
                // (due to greedy matching). The combined meaning is ReadonlyRef.
                if(HasReadonlyModifier(methodDecl.Modifiers) && methodDecl.ReturnOwnership is RefSpecifierOwnershipSpecifierNode)
                {
                    methodSymbol.OwnershipTier = OwnershipTier.ReadonlyRef;
                    methodSymbol.ReturnRefKind = RefKind.RefReadonly;
                }
                else if(methodDecl.ReturnOwnership is RefSpecifierOwnershipSpecifierNode)
                {
                    // ref return — set ReturnRefKind and leave ownership as Unrestricted.
                    methodSymbol.ReturnRefKind = RefKind.Ref;
                    methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                }
                else if(methodDecl.ReturnOwnership is ReadonlyRefSpecifierOwnershipSpecifierNode)
                {
                    // readonly ref return — set ReturnRefKind and leave ownership as Unrestricted.
                    methodSymbol.ReturnRefKind = RefKind.RefReadonly;
                    methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                }
                else
                {
                    methodSymbol.OwnershipTier = MapOwnershipSpecifier(methodDecl.ReturnOwnership);
                }
            }
            else if(HasRefModifier(methodDecl.Modifiers))
            {
                // The parser consumed 'ref' as a RefModifier (since REF is in the Modifier rule).
                // On a method declaration, 'ref' means ref return, not ref-struct modifier.
                // "readonly ref" → RefReadonly; bare "ref" → Ref.
                if(HasReadonlyModifier(methodDecl.Modifiers))
                {
                    methodSymbol.ReturnRefKind = RefKind.RefReadonly;
                    methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                }
                else
                {
                    methodSymbol.ReturnRefKind = RefKind.Ref;
                    methodSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                }
            }
            else if(methodDecl.Modifiers.Any(m => m is OwnedModifierModifierNode))
            {
                methodSymbol.OwnershipTier = OwnershipTier.Owned;
            }
        }

        // Determine if the method is static.
        var isStatic = methodDecl.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Create a method scope for the body.
        var methodScope = new Scope(parent: typeScope);

        // Register method-level dependent type parameters in the method's lexical scope.
        if(methodSymbol is not null && methodSymbol.TypeParameters.Count > 0)
        {
            RegisterMethodDependentParameters(methodSymbol.TypeParameters, methodScope);
        }

        // Register parameters into the body scope for name resolution.
        // This is the canonical point for parameter-related diagnostics
        // (duplicate names, ref/ownership conflicts, type resolution errors).
        if(methodDecl.Parameters is not null)
        {
            RegisterParameters(methodDecl.Parameters, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
        }

        // Register with-clause bindings as local variables in the method scope.
        foreach(var withClause in methodDecl.WithClauses)
        {
            // Skip this-tier annotations — they don't introduce local bindings.
            if(withClause is not ContextWithClauseWithClauseNode contextClause)
            {
                continue;
            }

            var contextType = ResolveTypeReference(contextClause.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
            var clauseName = contextClause.Name.Lexeme;
            var clauseSpan = ToMistSourceSpan(contextClause.Name.Span);

            CheckDuplicateLocal(clauseName, methodScope, sourceText, diagnostics);

            var clauseSymbol = new Symbol(clauseName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, methodScope, contextType, clauseSpan);
            methodScope.AddMember(clauseSymbol);
            symbolTable.Register(clauseSymbol, withClause);
        }

        // Resolve the body. A no-body (;) form is accepted by the grammar but
        // has no statements to resolve.
        if(methodDecl.Body.GetBlock() is BlockNode methodBlock)
        {
            // Track async context: if this method has the async modifier,
            // expressions inside its body are in an async context (no auto-unwrap).
            var previousAsyncContext = isInAsyncContext;
            isInAsyncContext = methodDecl.Modifiers.Any(m => m is AsyncModifierModifierNode);

            // Track the method's return type so return statements can propagate
            // it as a lambda target type and as the target type for void literals.
            var previousMethodReturnType = currentMethodReturnType;
            currentMethodReturnType = methodSymbol?.DeclaredReturnType ?? returnType;

            // Initialize discarded-task tracking for this method body.
            var previousDiscardedTaskScopes = discardedTaskScopes;
            var previousDiscardedTaskCounter = discardedTaskCounter;
            discardedTaskScopes = new Stack<List<DiscardedTaskInfo>>();
            discardedTaskCounter = 0;

            try
            {
                ResolveBlock(methodBlock, methodScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            }
            finally
            {
                discardedTaskScopes = previousDiscardedTaskScopes;
                discardedTaskCounter = previousDiscardedTaskCounter;
                isInAsyncContext = previousAsyncContext;
                currentMethodReturnType = previousMethodReturnType;
            }
        }
    }

    /// <summary>
    /// Pass 2 counterpart to <see cref="RegisterOperatorDeclaration"/>. Resolves
    /// the operator's return type (so <see cref="Symbol.DeclaredType"/> is set
    /// to the operator's result type), registers its parameters into a method
    /// scope (so <see cref="ParameterSignature.Extract"/> can retrieve parameter
    /// types for overload resolution in Task 14), and — if the operator has a
    /// body — resolves the body like a static method.
    ///
    /// An operator is treated as a static method for semantic-model purposes
    /// (Requirement 4.2, 4.6): parameter and body resolution use
    /// <c>isStatic = true</c>. Operators don't have type parameters in v1, so
    /// no equivalent of <see cref="RegisterMethodTypeParameters"/> is needed.
    /// </summary>
    private static void ResolveOperatorDeclaration(
        OperatorDeclarationNode opDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of operator return type resolution — DeclaredType
        // is always set before Pass 2 runs. Read it directly.
        var opSymbol = symbolTable.GetDeclaredSymbol(opDecl) as Symbol;
        var resolvedReturnType = opSymbol?.DeclaredType;

        // Create a method scope for parameters and the optional body.
        var methodScope = new Scope(parent: typeScope);

        // Register parameters so ParameterSignature.Extract can retrieve
        // parameter types during overload resolution (Task 14).
        if(opDecl.Parameters is not null)
        {
            RegisterParameters(opDecl.Parameters, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
        }

        // Resolve the body. A no-body (;) form is accepted by the grammar
        // (Requirement 5.2 for intrinsic operators) and has no statements to
        // resolve; Pass 1e validates whether ; is permitted on this operator
        // based on the intrinsic modifier.
        if(opDecl.Body.GetBlock() is BlockNode opBlock)
        {
            var previousMethodReturnType = currentMethodReturnType;
            currentMethodReturnType = resolvedReturnType;
            ResolveBlock(opBlock, methodScope, fileScope, enclosingType, /* isStatic */ true, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            currentMethodReturnType = previousMethodReturnType;
        }
    }

    /// <summary>
    /// Pass 2 counterpart to <see cref="RegisterCastOperatorDeclaration"/>. Resolves
    /// the cast operator's target type reference to an <see cref="IType"/> and sets it
    /// as the symbol's <see cref="Symbol.DeclaredType"/> (return type). Registers the
    /// single parameter as a <see cref="SymbolKind.Parameter"/> symbol within the cast
    /// operator's scope, and resolves the body block (if present) using the same logic
    /// as <see cref="ResolveOperatorDeclaration"/>.
    ///
    /// Cast operators are always static methods (Requirement 6.4), so the body is
    /// resolved with <c>isStatic = true</c>.
    /// </summary>
    private static void ResolveCastOperatorDeclaration(
        CastOperatorDeclarationNode castOpDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of cast operator target type resolution —
        // DeclaredType is always set before Pass 2 runs. Read it directly.
        var castOpSymbol = symbolTable.GetDeclaredSymbol(castOpDecl) as Symbol;
        var resolvedTargetType = castOpSymbol?.DeclaredType;

        // Create a method scope for parameters and the optional body.
        var methodScope = new Scope(parent: typeScope);

        // Register the single parameter within the cast operator's scope.
        if(castOpDecl.Parameters is not null)
        {
            RegisterParameters(castOpDecl.Parameters, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
        }

        // Resolve the body. A no-body (;) form is accepted by the grammar
        // (for intrinsic cast operators) and has no statements to resolve;
        // Pass 1e validates whether ; is permitted based on the intrinsic modifier.
        if(castOpDecl.Body.GetBlock() is BlockNode castOpBlock)
        {
            var previousMethodReturnType = currentMethodReturnType;
            currentMethodReturnType = resolvedTargetType;
            ResolveBlock(castOpBlock, methodScope, fileScope, enclosingType, /* isStatic */ true, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            currentMethodReturnType = previousMethodReturnType;
        }
    }

    /// <summary>
    /// Resolves property type references, <c>field</c> keyword, and <c>value</c> implicit parameter.
    /// </summary>
    private static void ResolvePropertyDeclaration(
        PropertyDeclarationNode propertyDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(propertyDecl)
        {
            case BlockPropertyPropertyDeclarationNode blockProp:
                ResolveBlockPropertyDeclaration(blockProp, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ExpressionBodiedPropertyPropertyDeclarationNode exprProp:
                ResolveExpressionBodiedPropertyDeclaration(exprProp, typeScope, fileScope, enclosingType, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    private static void ResolveBlockPropertyDeclaration(
        BlockPropertyPropertyDeclarationNode blockProp,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of property type resolution — DeclaredType is
        // always set before Pass 2 runs. Read it directly.
        var propSymbol = symbolTable.GetDeclaredSymbol(blockProp) as Symbol;
        var propType = propSymbol?.DeclaredType ?? ErrorType.Instance;

        // Storage-ban check (unknown-type feature, Task 11.2, Requirements
        // 5.2, 7.5, 7.6, 16.1). See ResolveFieldDeclaration for the
        // "do not substitute ErrorType" rationale.
        if(TypeContainment.IsStorageBanned(propType))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                UnknownAsPropertyType.Value,
                DiagnosticSeverity.Error,
                $"Property '{enclosingType.DisplayName}.{blockProp.Name.Lexeme}' of type '{propType.DisplayName}' cannot have 'unknown' in its declared type: 'unknown' is not permitted as the type of writable storage.",
                blockProp,
                sourceText));
        }

        var isStatic = blockProp.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Resolve each accessor body.
        var propInfo = propSymbol?.PropertyMetadata;
        foreach(var accessor in blockProp.Accessors)
        {
            ResolveAccessorBody(accessor, propType, propInfo, typeScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        // Resolve the optional initializer expression.
        if(blockProp.Initializer is ExpressionNode initExpr)
        {
            _ = ResolveExpression(initExpr, typeScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void ResolveExpressionBodiedPropertyDeclaration(
        ExpressionBodiedPropertyPropertyDeclarationNode exprProp,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of property type resolution — DeclaredType is
        // always set before Pass 2 runs. Read it directly.
        var propSymbol = symbolTable.GetDeclaredSymbol(exprProp) as Symbol;
        var propType = propSymbol?.DeclaredType ?? ErrorType.Instance;

        // Storage-ban check (unknown-type feature, Task 11.2, Requirements
        // 5.2, 7.5, 7.6, 16.1). Expression-bodied properties have no
        // backing field per se, but Requirement 5.2 bans `unknown` as the
        // type of any property declaration regardless of how it is
        // implemented — the ban is a declaration-site rule.
        if(TypeContainment.IsStorageBanned(propType))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                UnknownAsPropertyType.Value,
                DiagnosticSeverity.Error,
                $"Property '{enclosingType.DisplayName}.{exprProp.Name.Lexeme}' of type '{propType.DisplayName}' cannot have 'unknown' in its declared type: 'unknown' is not permitted as the type of writable storage.",
                exprProp,
                sourceText));
        }

        var isStatic = exprProp.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Resolve the expression body.
        _ = ResolveExpression(exprProp.Body, typeScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Resolves an accessor body, injecting implicit <c>value</c> parameter for set/init
    /// and resolving <c>field</c> keyword references.
    /// </summary>
    private static void ResolveAccessorBody(
        AccessorDeclarationNode accessor,
        IType propType,
        PropertyInfo? propInfo,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Create an accessor scope that includes the backing field symbol (if any)
        // so that 'field' keyword resolution finds the correct backing field.
        Scope accessorBaseScope;
        if(propInfo?.BackingField is Symbol)
        {
            accessorBaseScope = new Scope(parent: typeScope);
            // Register a synthetic property symbol that points to this specific backing field,
            // so ResolveFieldKeyword finds the correct one.
            var syntheticProp = new Symbol("__accessor_property__", SymbolKind.Property, SymbolOrigin.UserCode, accessorBaseScope, propType, declarationSpan: null)
            {
                PropertyMetadata = propInfo
            };
            accessorBaseScope.AddMember(syntheticProp);
        }
        else
        {
            accessorBaseScope = typeScope;
        }

        switch(accessor)
        {
            case BlockGetAccessorAccessorDeclarationNode blockGet:
                ResolveBlock(blockGet.Body, accessorBaseScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ExpressionGetAccessorAccessorDeclarationNode exprGet:
                _ = ResolveExpression(exprGet.Expression, accessorBaseScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case BlockSetAccessorAccessorDeclarationNode blockSet:
                {
                    // Inject implicit 'value' parameter of the property's declared type.
                    var setScope = new Scope(parent: accessorBaseScope);
                    var valueSymbol = new Symbol("value", SymbolKind.Parameter, SymbolOrigin.UserCode, setScope, propType, declarationSpan: null);
                    setScope.AddMember(valueSymbol);
                    ResolveBlock(blockSet.Body, setScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
            case ExpressionSetAccessorAccessorDeclarationNode exprSet:
                {
                    var setScope = new Scope(parent: accessorBaseScope);
                    var valueSymbol = new Symbol("value", SymbolKind.Parameter, SymbolOrigin.UserCode, setScope, propType, declarationSpan: null);
                    setScope.AddMember(valueSymbol);
                    _ = ResolveExpression(exprSet.Expression, setScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
            case BlockInitAccessorAccessorDeclarationNode blockInit:
                {
                    var initScope = new Scope(parent: accessorBaseScope);
                    var valueSymbol = new Symbol("value", SymbolKind.Parameter, SymbolOrigin.UserCode, initScope, propType, declarationSpan: null);
                    initScope.AddMember(valueSymbol);
                    ResolveBlock(blockInit.Body, initScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
            case ExpressionInitAccessorAccessorDeclarationNode exprInit:
                {
                    var initScope = new Scope(parent: accessorBaseScope);
                    var valueSymbol = new Symbol("value", SymbolKind.Parameter, SymbolOrigin.UserCode, initScope, propType, declarationSpan: null);
                    initScope.AddMember(valueSymbol);
                    _ = ResolveExpression(exprInit.Expression, initScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
                // Auto accessors (AutoGet, AutoSet, AutoInit) have no body to resolve.
        }
    }

    /// <summary>
    /// Resolves indexer type references and accessor bodies.
    /// </summary>
    private static void ResolveIndexerDeclaration(
        IndexerDeclarationNode indexerDecl,
        Scope typeScope,
        Scope fileScope,
        IType enclosingType,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Phase 4 is the sole owner of indexer type resolution — DeclaredType
        // is always set before Pass 2 runs. Read it directly.
        var indexerSymbol = symbolTable.GetDeclaredSymbol(indexerDecl) as Symbol;
        var indexerType = indexerSymbol?.DeclaredType ?? ErrorType.Instance;

        if(indexerDecl.Body is not BlockIndexerBodyIndexerBodyNode blockBody2)
        {
            // Intrinsic indexer — register parameters only.
            if(indexerDecl.Parameters is not null)
            {
                var intrinsicIndexerScope = new Scope(parent: typeScope);
                RegisterParameters(indexerDecl.Parameters, intrinsicIndexerScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
            }

            return;
        }

        // Storage-ban check (unknown-type feature, Task 11.3, Requirements
        // 5.3, 7.5, 7.6, 16.1). Applies to the indexer's element type — the
        // type yielded by a get and consumed by a set — which is the
        // storage-shaped position per Requirement 5.3.
        if(TypeContainment.IsStorageBanned(indexerType))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                UnknownAsIndexerElementType.Value,
                DiagnosticSeverity.Error,
                $"Indexer '{enclosingType.DisplayName}.this[]' of element type '{indexerType.DisplayName}' cannot have 'unknown' in its declared type: 'unknown' is not permitted as the element type of writable storage.",
                indexerDecl,
                sourceText));
        }

        var isStatic = indexerDecl.Modifiers.Any(m => m is StaticModifierModifierNode);

        // Create a scope for the indexer parameters.
        var indexerScope = new Scope(parent: typeScope);

        // Register indexer parameters.
        RegisterParameters(indexerDecl.Parameters, indexerScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);

        // Resolve each accessor body with the indexer scope (which has the parameters).
        var propInfo = indexerSymbol?.PropertyMetadata;
        foreach(var accessor in blockBody2.Accessors)
        {
            ResolveAccessorBody(accessor, indexerType, propInfo, indexerScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void RegisterParameters(
        ParameterListNode paramList,
        Scope methodScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // The grammar rule is: ParameterList = Parameter (COMMA Parameter)*
        // Iterate all ParameterNode children uniformly to register every parameter.
        foreach(var child in paramList.Children())
        {
            if(child is ParameterNode param)
            {
                RegisterSingleParameter(param, methodScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
            }
        }
    }

    private static void RegisterSingleParameter(
        ParameterNode param,
        Scope methodScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Signal that we're resolving a parameter type so unsized array types
        // receive a symbolic length ID (Requirement 1.4).
        allocatingParameterArrayType = true;
        var paramType = ResolveTypeReference(param.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
        allocatingParameterArrayType = false;
        var paramName = param.Name.Lexeme;
        var paramSpan = ToMistSourceSpan(param.Name.Span);

        // Check for duplicate parameter names.
        var existing = methodScope.Lookup(paramName);
        if(existing is not null && existing.ContainingScope == methodScope)
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_DUPLICATE_DECLARATION",
                DiagnosticSeverity.Error,
                $"A parameter named '{paramName}' is already declared in this scope.",
                param,
                sourceText));
            return;
        }

        var paramSymbol = new Symbol(paramName, SymbolKind.Parameter, SymbolOrigin.UserCode, methodScope, paramType, paramSpan);

        // Handle ref modifier on the parameter.
        if(param.RefModifier is not null)
        {
            // Determine if this is ref or ref readonly (readonly ref).
            // When the parser sees "readonly ref T x", it parses modifier=READONLY, refModifier=REF.
            if(param.Modifier is not null)
            {
                // readonly ref → RefKind.RefReadonly
                paramSymbol.RefKind = RefKind.RefReadonly;
                paramSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
            }
            else
            {
                paramSymbol.RefKind = RefKind.Ref;
            }

            // Check for conflicting ownership specifiers with ref modifier.
            if(param.OwnershipSpecifier is OwnedSpecifierOwnershipSpecifierNode)
            {
                // Error: ref and owned are mutually exclusive.
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_REF_0004",
                    DiagnosticSeverity.Error,
                    "The 'ref' modifier and 'owned' specifier are mutually exclusive on a parameter",
                    param,
                    sourceText));
                paramSymbol.OwnershipTier = OwnershipTier.Unrestricted;
            }
            else if(param.OwnershipSpecifier is BorrowedSpecifierOwnershipSpecifierNode or FrozenSpecifierOwnershipSpecifierNode)
            {
                // Warning: ownership specifier is redundant on a ref parameter.
                var specifierName = param.OwnershipSpecifier switch
                {
                    BorrowedSpecifierOwnershipSpecifierNode => "borrowed",
                    FrozenSpecifierOwnershipSpecifierNode => "frozen",
                    _ => "unknown",
                };
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_REF_0013",
                    DiagnosticSeverity.Warning,
                    $"The ownership specifier '{specifierName}' is redundant on a ref parameter (ref already implies a borrow)",
                    param,
                    sourceText));
                paramSymbol.OwnershipTier = OwnershipTier.Unrestricted;
            }
            else
            {
                paramSymbol.OwnershipTier = OwnershipTier.Unrestricted;
            }
        }
        else
        {
            // Detect readonly modifier or readonly ref ownership specifier on the parameter.
            if(param.Modifier is not null || param.OwnershipSpecifier is ReadonlyRefSpecifierOwnershipSpecifierNode)
            {
                paramSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
            }

            // When the parser sees "readonly ref", it may parse it as modifier=READONLY +
            // ownershipSpecifier=RefSpecifier (due to greedy matching of the READONLY modifier).
            // In that case, the combined meaning is ReadonlyRef, not just Borrowed.
            paramSymbol.OwnershipTier = param.Modifier is not null && param.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode
                ? OwnershipTier.ReadonlyRef
                : MapOwnershipSpecifier(param.OwnershipSpecifier);
        }

        methodScope.AddMember(paramSymbol);
        symbolTable.Register(paramSymbol, param);
    }

    // ─── Block and Statement Resolution ──────────────────────────────────

    private static void ResolveBlock(
        BlockNode block,
        Scope parentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var blockScope = new Scope(parent: parentScope);

        // Push a new discarded-task scope for this block.
        discardedTaskScopes?.Push(new List<DiscardedTaskInfo>());

        foreach(var stmt in block.Statements)
        {
            ResolveStatement(stmt, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        // Pop the discarded-task scope and record un-consumed tasks.
        if(discardedTaskScopes is not null && discardedTaskScopes.Count > 0)
        {
            var scopeTasks = discardedTaskScopes.Pop();

            if(scopeTasks.Count > 0 && discardedTaskResult is not null)
            {
                discardedTaskResult[block] = scopeTasks;
            }
        }
    }

    private static void ResolveStatement(
        StatementNode stmt,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(stmt)
        {
            case VariableDeclarationStatementStatementNode varDeclStmt:
                ResolveVariableDeclaration(varDeclStmt.VariableDeclaration, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case UninitializedVariableStatementStatementNode uninitStmt:
                {
                    var uninit = uninitStmt.UninitializedVariable;
                    var declaredType = ResolveTypeReference(uninit.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    var varName = uninit.Name.Lexeme;
                    var varSpan = ToMistSourceSpan(uninit.Name.Span);
                    CheckDuplicateLocal(varName, blockScope, sourceText, diagnostics);
                    var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, declaredType, varSpan)
                    {
                        OwnershipTier = MapOwnershipSpecifier(uninit.OwnershipSpecifier)
                    };
                    blockScope.AddMember(varSymbol);
                    symbolTable.Register(varSymbol, uninitStmt);
                    break;
                }
            case ReturnStatementStatementNode returnStmt:
                if(returnStmt.ReturnStatement.Value is not null)
                {
                    // Set lambda target type from the enclosing method's return type
                    // so that implicit-param lambdas in return statements can infer types.
                    var previousLambdaTarget = lambdaTargetType;
                    if(currentMethodReturnType is not null && IsFuncType(currentMethodReturnType))
                    {
                        lambdaTargetType = currentMethodReturnType;
                    }
                    else if(currentMethodReturnType is DelegateType)
                    {
                        lambdaTargetType = currentMethodReturnType;
                    }

                    // Set target type context for void value literal resolution
                    // from the enclosing method's declared return type.
                    var previousVoidTarget = voidLiteralTargetType;
                    voidLiteralTargetType = currentMethodReturnType;

                    // Set target type context for target-typed new expression
                    // from the enclosing method's declared return type.
                    var previousTargetNewTarget = targetTypedNewTargetType;
                    targetTypedNewTargetType = currentMethodReturnType;

                    var returnValueType = ResolveExpression(returnStmt.ReturnStatement.Value, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    voidLiteralTargetType = previousVoidTarget;
                    targetTypedNewTargetType = previousTargetNewTarget;
                    lambdaTargetType = previousLambdaTarget;

                    // Named Task<T> variables returned from the method transfer
                    // ownership to the caller. The emitter's auto-drop system
                    // handles elision for returned variables (task 7.2), so no
                    // explicit MarkTaskAsReturned is needed.

                    // Top-level statements: return expressions must be integer types (exit codes).
                    // enclosingType is null only in TLS mode (passed as null! from Pass2_ResolveTypes).
                    if(enclosingType is null && returnValueType is not ErrorType && !IsIntegerType(returnValueType))
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            "MIST_TLS_RETURN_TYPE",
                            DiagnosticSeverity.Error,
                            $"Top-level 'return' must return an integer exit code, but got '{returnValueType.DisplayName}'.",
                            returnStmt.ReturnStatement,
                            sourceText));
                    }
                }

                break;
            case IfStatementStatementNode ifStmt:
                ResolveIfStatement(ifStmt.IfStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WhileStatementStatementNode whileStmt:
                _ = ResolveExpression(whileStmt.WhileStatement.Condition, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                ResolveBlock(whileStmt.WhileStatement.Body, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ForStatementStatementNode forStmt:
                ResolveForStatement(forStmt.ForStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ForeachStatementStatementNode foreachStmt:
                ResolveForeachStatement(foreachStmt.ForeachStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case ExpressionStatementStatementNode exprStmt:
                {
                    var exprType = ResolveExpression(exprStmt.ExpressionStatement.Expression, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Track discarded tasks for scope-exit await (Drop-based model):
                    // When an async method is invoked and the result is not assigned,
                    // track it as a discarded task for scope-exit await. This is NOT
                    // gated on _isInAsyncContext — discarded tasks in any context are
                    // tracked so the emitter can promote the method to async and emit
                    // scope-exit await.
                    if(discardedTaskScopes is not null
                        && discardedTaskScopes.Count > 0
                        && IsStandardTaskType(exprType)
                        && IsDiscardedAsyncInvocation(exprStmt.ExpressionStatement.Expression))
                    {
                        var varName = $"__task_{discardedTaskCounter++}";
                        var taskInfo = new DiscardedTaskInfo(varName, exprType, exprStmt.ExpressionStatement.Expression);
                        discardedTaskScopes.Peek().Add(taskInfo);
                    }

                    break;
                }
            case BreakStatementStatementNode:
                // No type resolution needed.
                break;
            case ReadonlyBlockStatementStatementNode readonlyBlockStmt:
                ResolveBlock(readonlyBlockStmt.ReadonlyBlock.Body, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case BlockStatementStatementNode blockStmt:
                ResolveBlock(blockStmt.BlockStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithVarDeclarationStatementStatementNode withVarStmt:
                ResolveWithVarDeclaration(withVarStmt.WithVarDeclaration, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithTypedDeclarationStatementStatementNode withTypedStmt:
                ResolveWithTypedDeclaration(withTypedStmt.WithTypedDeclaration, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithDiscardDeclarationStatementStatementNode withDiscardStmt:
                ResolveWithDiscardDeclaration(withDiscardStmt.WithDiscardDeclaration, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithPushStatementStatementNode withPushStmt:
                _ = ResolveExpression(withPushStmt.WithPushStatement.Value, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithBlockStatementStatementNode withBlockStmt:
                ResolveWithBlockStatement(withBlockStmt.WithBlockStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case WithVarBlockStatementStatementNode withVarBlockStmt:
                ResolveWithVarBlockStatement(withVarBlockStmt.WithVarBlockStatement, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    private static void ResolveWithVarDeclaration(
        WithVarDeclarationStatementNode withVarDecl,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Infer type from initializer expression.
        var initType = ResolveExpression(withVarDecl.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        var varName = withVarDecl.Name.Lexeme;
        var varSpan = ToMistSourceSpan(withVarDecl.Name.Span);

        CheckDuplicateLocal(varName, blockScope, sourceText, diagnostics);

        var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, initType, varSpan);
        blockScope.AddMember(varSymbol);
        symbolTable.Register(varSymbol, withVarDecl);
    }

    private static void ResolveWithTypedDeclaration(
        WithTypedDeclarationStatementNode withTypedDecl,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Resolve the explicit type reference.
        var declaredType = ResolveTypeReference(withTypedDecl.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        // Resolve the initializer expression.
        _ = ResolveExpression(withTypedDecl.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        var varName = withTypedDecl.Name.Lexeme;
        var varSpan = ToMistSourceSpan(withTypedDecl.Name.Span);

        CheckDuplicateLocal(varName, blockScope, sourceText, diagnostics);

        var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, declaredType, varSpan);
        blockScope.AddMember(varSymbol);
        symbolTable.Register(varSymbol, withTypedDecl);
    }

    private static void ResolveWithDiscardDeclaration(
        WithDiscardDeclarationStatementNode withDiscardDecl,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Resolve the explicit type reference (for context keying).
        _ = ResolveTypeReference(withDiscardDecl.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        // Resolve the initializer expression.
        _ = ResolveExpression(withDiscardDecl.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // No local variable registration for discard declarations.
    }

    private static void ResolveWithBlockStatement(
        WithBlockStatementNode withBlockStmt,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Infer type from the expression.
        _ = ResolveExpression(withBlockStmt.Expression, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Process the block body.
        ResolveBlock(withBlockStmt.Body, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void ResolveWithVarBlockStatement(
        WithVarBlockStatementNode withVarBlock,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Resolve the initializer expression.
        var initType = ResolveExpression(withVarBlock.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Create a child scope for the with-var binding so the variable doesn't
        // conflict with other locals at the same level (multiple with-var blocks
        // in the same method can reuse the same variable name).
        var withScope = new Scope(parent: blockScope);

        var varName = withVarBlock.Name.Lexeme;
        var varSpan = ToMistSourceSpan(withVarBlock.Name.Span);

        var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, withScope, initType, varSpan);
        withScope.AddMember(varSymbol);
        symbolTable.Register(varSymbol, withVarBlock);

        // Process the block body within the with-var's scope.
        ResolveBlock(withVarBlock.Body, withScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void ResolveVariableDeclaration(
        VariableDeclarationStatementNode varDecl,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(varDecl)
        {
            case TypedVariableDeclarationVariableDeclarationStatementNode typed:
                {
                    var declaredType = ResolveTypeReference(typed.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                    // Set target type context so EmptyArrayLiteralExpressionPrimaryNode
                    // can infer its element type from the declared array type.
                    emptyArrayTargetType = declaredType;

                    // Set lambda target type context so implicitly-typed lambda parameters
                    // can infer their types from the declared Func or DelegateType.
                    if(IsFuncType(declaredType))
                    {
                        lambdaTargetType = declaredType;
                    }
                    else if(declaredType is DelegateType)
                    {
                        lambdaTargetType = declaredType;
                    }

                    // Set target type context for void value literal resolution.
                    voidLiteralTargetType = declaredType;
                    targetTypedNewTargetType = declaredType;
                    _ = ResolveExpression(typed.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    emptyArrayTargetType = null;
                    lambdaTargetType = null;
                    voidLiteralTargetType = null;
                    targetTypedNewTargetType = null;

                    var varName = typed.Name.Lexeme;
                    var varSpan = ToMistSourceSpan(typed.Name.Span);

                    CheckDuplicateLocal(varName, blockScope, sourceText, diagnostics);

                    var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, declaredType, varSpan);

                    // Bare `ref` on a local variable is a ref local (C#-style ref semantics).
                    // `readonly ref` on a local variable remains an ownership lend (lending semantics)
                    // until the grammar supports disambiguation via ref on the initializer.
                    if(typed.ReadonlyModifier is not null && typed.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode)
                    {
                        // readonly ref T x = expr; → ReadonlyRef lending semantics (not a readonly ref local).
                        varSymbol.OwnershipTier = OwnershipTier.ReadonlyRef;
                    }
                    else if(typed.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode)
                    {
                        varSymbol.RefKind = RefKind.Ref;
                        varSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                    }
                    else
                    {
                        varSymbol.OwnershipTier = MapOwnershipSpecifier(typed.OwnershipSpecifier);
                    }

                    if(typed.ReadonlyModifier is not null && typed.OwnershipSpecifier is not RefSpecifierOwnershipSpecifierNode)
                    {
                        varSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
                    }

                    blockScope.AddMember(varSymbol);
                    symbolTable.Register(varSymbol, varDecl);

                    // Named Task<T>/ValueTask<T> locals are now scope-exit drop
                    // obligations handled by the emitter's auto-drop try/finally
                    // wrapping (tasks 7.1, 7.3). No DiscardedTaskInfo tracking needed.
                    break;
                }
            case InferredVariableDeclarationVariableDeclarationStatementNode inferred:
                {
                    // var — infer type from initializer.
                    var initType = ResolveExpression(inferred.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    var varName = inferred.Name.Lexeme;
                    var varSpan = ToMistSourceSpan(inferred.Name.Span);

                    CheckDuplicateLocal(varName, blockScope, sourceText, diagnostics);

                    var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, initType, varSpan);

                    // Bare `ref` on a local variable is a ref local (C#-style ref semantics).
                    // `readonly ref` on a local variable remains an ownership lend (lending semantics)
                    // until the grammar supports disambiguation via ref on the initializer.
                    if(inferred.ReadonlyModifier is not null && inferred.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode)
                    {
                        // readonly ref var x = expr; → ReadonlyRef lending semantics (not a readonly ref local).
                        varSymbol.OwnershipTier = OwnershipTier.ReadonlyRef;
                    }
                    else if(inferred.OwnershipSpecifier is RefSpecifierOwnershipSpecifierNode)
                    {
                        varSymbol.RefKind = RefKind.Ref;
                        varSymbol.OwnershipTier = OwnershipTier.Unrestricted;
                    }
                    else
                    {
                        varSymbol.OwnershipTier = MapOwnershipSpecifier(inferred.OwnershipSpecifier);
                    }

                    if(inferred.ReadonlyModifier is not null && inferred.OwnershipSpecifier is not RefSpecifierOwnershipSpecifierNode)
                    {
                        varSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
                    }

                    blockScope.AddMember(varSymbol);
                    symbolTable.Register(varSymbol, varDecl);

                    // Named Task<T>/ValueTask<T> locals are now scope-exit drop
                    // obligations handled by the emitter's auto-drop try/finally
                    // wrapping (tasks 7.1, 7.3). No DiscardedTaskInfo tracking needed.
                    break;
                }
            case VarTupleDeconstructionVariableDeclarationStatementNode varTuple:
                {
                    // var (a, b, ...) = expr; — resolve initializer, defer element type inference to type checker.
                    _ = ResolveExpression(varTuple.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Register first name.
                    var firstName = varTuple.FirstName.Lexeme;
                    CheckDuplicateLocal(firstName, blockScope, sourceText, diagnostics);
                    var firstSymbol = new Symbol(firstName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, ErrorType.Instance, ToMistSourceSpan(varTuple.FirstName.Span));
                    if(varTuple.ReadonlyModifier is not null)
                    {
                        firstSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
                    }

                    blockScope.AddMember(firstSymbol);
                    symbolTable.Register(firstSymbol, varDecl);

                    // Register rest names.
                    foreach(var restName in varTuple.RestNames)
                    {
                        var name = restName.Lexeme;
                        CheckDuplicateLocal(name, blockScope, sourceText, diagnostics);
                        var restSymbol = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, ErrorType.Instance, ToMistSourceSpan(restName.Span));
                        if(varTuple.ReadonlyModifier is not null)
                        {
                            restSymbol.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
                        }

                        blockScope.AddMember(restSymbol);
                        symbolTable.Register(restSymbol, varDecl);
                    }

                    break;
                }
            case TypedTupleDeconstructionVariableDeclarationStatementNode typedTuple:
                {
                    // (Type1 a, Type2 b, ...) = expr; — resolve each element's declared type.
                    _ = ResolveExpression(typedTuple.Initializer, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    void registerDeconstructionElement(TupleDeconstructionElementNode element)
                    {
                        var declaredType = ResolveTypeReference(element.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                        var name = element.Name.Lexeme;
                        CheckDuplicateLocal(name, blockScope, sourceText, diagnostics);
                        var sym = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, blockScope, declaredType, ToMistSourceSpan(element.Name.Span));
                        if(typedTuple.ReadonlyModifier is not null)
                        {
                            sym.ReadonlyStatus = ReadonlyStatus.ExplicitReadonly;
                        }

                        blockScope.AddMember(sym);
                        symbolTable.Register(sym, varDecl);
                    }

                    registerDeconstructionElement(typedTuple.First);
                    registerDeconstructionElement(typedTuple.Rest);
                    foreach(var additional in typedTuple.TupleDeconstructionElements)
                    {
                        registerDeconstructionElement(additional);
                    }

                    break;
                }
        }
    }

    private static void ResolveIfStatement(
        IfStatementNode ifStmt,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Step 1: Resolve the condition expression (which may contain `is` expressions).
        _ = ResolveExpression(ifStmt.Condition, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Step 2: Create a child scope for the then-branch and populate it
        // with pattern variables introduced by `is` expressions in the condition.
        var thenScope = new Scope(parent: blockScope);
        CollectPatternVariables(ifStmt.Condition, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        // Step 3: Resolve the then-branch in the child scope that contains
        // pattern variables. ResolveBlock creates its own nested scope from
        // the parent we pass, so pattern variables are visible inside.
        ResolveBlock(ifStmt.ThenBranch, thenScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Step 4: The else branch does NOT get pattern variables.
        if(ifStmt.ElseBranch is ElseIfElseClauseNode elseIf)
        {
            ResolveIfStatement(elseIf.ElseIf, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
        else if(ifStmt.ElseBranch is ElseBlockElseClauseNode elseBlock)
        {
            ResolveBlock(elseBlock.ElseBlock, blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    // ─── Pattern Variable Collection ────────────────────────────────────
    // Walks the condition expression tree looking for IsExpressionRelationalNode
    // nodes and extracts variable bindings from their patterns into the
    // then-branch scope. This enables pattern variables to be used in the
    // then-branch of an `if` statement (e.g., `if (x is string s) { ... s ... }`).

    /// <summary>
    /// Walks the condition expression tree to find <c>is</c> expressions and
    /// registers pattern variables in the given scope.
    /// </summary>
    private static void CollectPatternVariables(
        ExpressionNode condition,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Expression → Assignment → LogicalOr → LogicalAnd → Equality → Relational
        // Walk through the chain to find IsExpressionRelationalNode nodes.
        var assignment = condition.AsAssignmentOrNull();
        if(assignment is null)
        {
            return; // Lambda form has no is-expression pattern variables.
        }

        CollectFromAssignment(assignment, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void CollectFromAssignment(
        AssignmentNode node,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromLogicalOr(node.Target.Left, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void CollectFromLogicalOr(
        LogicalOrNode node,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromLogicalAnd(node.Left, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            CollectFromLogicalAnd(node.Right, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromLogicalAnd(
        LogicalAndNode node,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromEquality(node.Left, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            CollectFromEquality(node.Right, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromEquality(
        EqualityNode node,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromRelational(node.Left, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            CollectFromRelational(node.Right, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromRelational(
        RelationalNode node,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(node is IsExpressionRelationalNode isExpr)
        {
            // Get the scrutinee type from the expression types map.
            // The scrutinee (isExpr.Left) was already resolved by ResolveRelational.
            _ = expressionTypes.TryGetValue(isExpr.Left, out var scrutineeType);
            scrutineeType ??= ErrorType.Instance;

            // Extract variable bindings from the pattern.
            CollectFromPattern(isExpr.Pattern, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
        // For RelationalComparisonRelationalNode, no pattern variables to collect.
    }

    private static void CollectFromPattern(
        PatternNode pattern,
        IType scrutineeType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromOrPattern(pattern.OrPattern, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void CollectFromOrPattern(
        OrPatternNode orPattern,
        IType scrutineeType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromAndPattern(orPattern.Left, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        if(orPattern.Right is not null && !ReferenceEquals(orPattern.Right, orPattern.Left))
        {
            CollectFromAndPattern(orPattern.Right, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromAndPattern(
        AndPatternNode andPattern,
        IType scrutineeType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromUnaryPattern(andPattern.Left, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        if(andPattern.Right is not null && !ReferenceEquals(andPattern.Right, andPattern.Left))
        {
            CollectFromUnaryPattern(andPattern.Right, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromUnaryPattern(
        UnaryPatternNode unaryPattern,
        IType scrutineeType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(unaryPattern)
        {
            case NotPatternUnaryPatternNode notPattern:
                // Not patterns may contain subpatterns, but variable bindings
                // inside `not` are semantically invalid (the type checker will
                // flag them). We still collect them here so the semantic model
                // is complete — the type checker handles the diagnostic.
                CollectFromPrimaryPattern(notPattern.Operand, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                break;
            case DirectPatternUnaryPatternNode directPattern:
                CollectFromPrimaryPattern(directPattern.Primary, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    private static void CollectFromPrimaryPattern(
        PrimaryPatternNode primaryPattern,
        IType scrutineeType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(primaryPattern)
        {
            case TypePatternPrimaryPatternNode typePattern:
                {
                    // Type pattern: `Type name` — register `name` as a local variable
                    // with the pattern's resolved type.
                    var name = typePattern.Name.Lexeme;

                    // Discard `_` does not introduce a variable.
                    if(name == "_")
                    {
                        break;
                    }

                    var patternType = ResolveTypeReference(typePattern.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                    // C# semantics for `is (int a, int b) pair`: the `pair`
                    // binding has the UNNAMED tuple type, not the named form.
                    // Element names in the pattern syntax introduce separate
                    // local bindings (`a`, `b`) but do not attach to `pair`.
                    // We strip the names here so Mist lookups match C#:
                    // `pair.a` fails (there's no `a` member on the unnamed
                    // tuple), `pair.Item1` succeeds.
                    var bindingType = patternType;
                    if(patternType is TupleType tupleTypeForBinding
                        && tupleTypeForBinding.ElementNames is not null)
                    {
                        bindingType = new TupleType(tupleTypeForBinding.ElementTypes, elementNames: null);
                    }

                    CheckDuplicateLocal(name, thenScope, sourceText, diagnostics);

                    var varSpan = ToMistSourceSpan(typePattern.Name.Span);
                    var varSymbol = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, thenScope, bindingType, varSpan);
                    thenScope.AddMember(varSymbol);
                    symbolTable.Register(varSymbol, typePattern);

                    // Tuple type pattern: if the pattern type is a named
                    // tuple, each named element introduces a local binding
                    // in the then-scope, matching C# semantics. In C#,
                    // `is (int a, int b) pair` against a tuple scrutinee
                    // deconstructs into separate `a`, `b`, and `pair`
                    // bindings — `a` and `b` are the deconstructed element
                    // values, `pair` is the whole tuple (without named-element
                    // metadata on the binding).
                    //
                    // When the scrutinee is not a concrete tuple (e.g., a
                    // bare `unknown`, which lowers to C# `object`), the
                    // emitter uses the chained form
                    // `u is ValueTuple<int, int> pair && pair is (int a, int b)`
                    // to introduce the element names as locals — C# accepts
                    // this compound pattern against any scrutinee. The
                    // end result is identical from Mist's perspective: `a`
                    // and `b` are bound in the then-scope with the
                    // deconstructed element values. We therefore register
                    // the element-name bindings whenever the pattern type
                    // carries names, without restricting on the scrutinee
                    // type.
                    if(typePattern.Type.First is TupleSingleTypeRefSingleTypeRefNode tupleRef
                        && patternType is TupleType tupleType
                        && tupleType.ElementNames is not null)
                    {
                        // Walk the AST elements in order to get token spans
                        // for each named binding; parallel to the element
                        // types on the resolved TupleType.
                        var astElements = new List<TupleTypeElementNode> { tupleRef.First, tupleRef.Rest };
                        astElements.AddRange(tupleRef.TupleTypeElements);

                        for(var i = 0; i < tupleType.ElementNames.Count; i++)
                        {
                            var elementName = tupleType.ElementNames[i];
                            if(elementName is null or "_")
                            {
                                continue;
                            }

                            if(i >= astElements.Count)
                            {
                                continue;
                            }

                            var elementAst = astElements[i];
                            if(!elementAst.Name.HasValue)
                            {
                                continue;
                            }

                            CheckDuplicateLocal(elementName, thenScope, sourceText, diagnostics);

                            var elementSpan = ToMistSourceSpan(elementAst.Name.Value.Span);
                            var elementSymbol = new Symbol(
                                elementName,
                                SymbolKind.LocalVariable,
                                SymbolOrigin.UserCode,
                                thenScope,
                                tupleType.ElementTypes[i],
                                elementSpan);
                            thenScope.AddMember(elementSymbol);
                            symbolTable.Register(elementSymbol, elementAst);
                        }
                    }

                    break;
                }

            case BareTypePatternPrimaryPatternNode bareTypePattern:
                {
                    // Bare type pattern: `Type` (no binding name) — pure type test.
                    // No whole-tuple variable to register.
                    //
                    // Special case: if the type reference is a qualified name like
                    // EnumName.MemberName, ResolveTypeReference will fail (it's not a type).
                    // We detect this and resolve it as an enum member access pattern instead.
                    if(bareTypePattern.Type.First is NamedSingleTypeRefSingleTypeRefNode namedPatternRef)
                    {
                        var qualifiedName = ExtractQualifiedName(namedPatternRef.Name, sourceText);
                        var dotIndex = qualifiedName.LastIndexOf('.');
                        if(dotIndex > 0)
                        {
                            var enumName = qualifiedName[..dotIndex];
                            var memberName = qualifiedName[(dotIndex + 1)..];

                            var enumSymbol = fileScope.Lookup(enumName);

                            if(enumSymbol is null)
                            {
                                var patternImportedNamespaces = CollectImportedNamespaces(fileScope);
                                var patternGlobalScope = FindGlobalScope(fileScope);
                                if(patternGlobalScope is not null)
                                {
                                    foreach(var ns in patternImportedNamespaces)
                                    {
                                        var nsScope = FindExistingNamespaceScope(patternGlobalScope, symbolTable, ns);
                                        if(nsScope is not null)
                                        {
                                            enumSymbol = nsScope.Lookup(enumName);
                                            if(enumSymbol is not null)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                            }

                            if(enumSymbol is not null && enumSymbol.Kind == SymbolKind.Enum && enumSymbol.DeclaredType is EnumType enumType)
                            {
                                var enumMember = enumType.MemberScope.Lookup(memberName);
                                if(enumMember is not null)
                                {
                                    // Valid enum member pattern — no variable bindings to collect.
                                    break;
                                }
                            }
                        }
                    }

                    // However, if the type is a named tuple type (e.g., `(int i, string str)`),
                    // the named elements introduce local bindings in the then-scope,
                    // matching C# semantics where `is (int i, string str)` introduces
                    // `i` and `str` as deconstructed element variables.
                    var barePatternType = ResolveTypeReference(bareTypePattern.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                    if(bareTypePattern.Type.First is TupleSingleTypeRefSingleTypeRefNode bareTupleRef
                        && barePatternType is TupleType bareTupleType
                        && bareTupleType.ElementNames is not null)
                    {
                        var bareAstElements = new List<TupleTypeElementNode> { bareTupleRef.First, bareTupleRef.Rest };
                        bareAstElements.AddRange(bareTupleRef.TupleTypeElements);

                        for(var i = 0; i < bareTupleType.ElementNames.Count; i++)
                        {
                            var elementName = bareTupleType.ElementNames[i];
                            if(elementName is null or "_")
                            {
                                continue;
                            }

                            if(i >= bareAstElements.Count)
                            {
                                continue;
                            }

                            var elementAst = bareAstElements[i];
                            if(!elementAst.Name.HasValue)
                            {
                                continue;
                            }

                            CheckDuplicateLocal(elementName, thenScope, sourceText, diagnostics);

                            var elementSpan = ToMistSourceSpan(elementAst.Name.Value.Span);
                            var elementSymbol = new Symbol(
                                elementName,
                                SymbolKind.LocalVariable,
                                SymbolOrigin.UserCode,
                                thenScope,
                                bareTupleType.ElementTypes[i],
                                elementSpan);
                            thenScope.AddMember(elementSymbol);
                            symbolTable.Register(elementSymbol, elementAst);
                        }
                    }

                    break;
                }

            case VarPatternPrimaryPatternNode varPattern:
                {
                    // Var pattern: `var name` — register `name` as a local variable
                    // with the scrutinee's static type.
                    var name = varPattern.Name.Lexeme;

                    // Discard `_` does not introduce a variable.
                    if(name == "_")
                    {
                        break;
                    }

                    CheckDuplicateLocal(name, thenScope, sourceText, diagnostics);

                    var varSpan = ToMistSourceSpan(varPattern.Name.Span);
                    var varSymbol = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, thenScope, scrutineeType, varSpan);
                    thenScope.AddMember(varSymbol);
                    symbolTable.Register(varSymbol, varPattern);
                    break;
                }

            case DiscardPatternPrimaryPatternNode:
                {
                    // Bare discard pattern: `_` — no variable binding.
                    break;
                }

            case PropertyPatternPrimaryPatternNode propertyPattern:
                {
                    // Determine the pattern type for subpattern recursion.
                    var patternType = scrutineeType;
                    if(propertyPattern.TypeName is not null)
                    {
                        var typeName = ExtractQualifiedName(propertyPattern.TypeName, sourceText);
                        patternType = ResolveNamedType(typeName, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    }

                    // Recursively collect from subpatterns.
                    if(propertyPattern.Subpatterns is not null)
                    {
                        CollectFromPropertySubpatternList(propertyPattern.Subpatterns, patternType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                    }

                    // Property pattern with trailing identifier: register the identifier.
                    if(propertyPattern.Name.HasValue)
                    {
                        var name = propertyPattern.Name.Value.Lexeme;
                        if(name != "_")
                        {
                            var varSpan = ToMistSourceSpan(propertyPattern.Name.Value.Span);
                            var varSymbol = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, thenScope, patternType, varSpan);
                            thenScope.AddMember(varSymbol);
                            symbolTable.Register(varSymbol, propertyPattern);
                        }
                    }

                    break;
                }

            case ListPatternPrimaryPatternNode listPattern:
                {
                    // Determine the element type for subpattern recursion.
                    var elementType = scrutineeType is ArrayType arrayType
                        ? arrayType.ElementType
                        : ErrorType.Instance;

                    if(listPattern.Elements is not null)
                    {
                        CollectFromListPatternElementList(listPattern.Elements, elementType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                    }

                    break;
                }

            case TuplePositionalPatternPrimaryPatternNode tuplePositionalPattern:
                {
                    // Determine element types from the scrutinee type.
                    // If the scrutinee is a TupleType, pass each element's type
                    // to the corresponding subpattern. Otherwise, use ErrorType
                    // to still collect variables even when types are wrong.
                    var elementPatterns = new List<PatternNode> { tuplePositionalPattern.First, tuplePositionalPattern.Rest };
                    elementPatterns.AddRange(tuplePositionalPattern.Patterns);

                    if(scrutineeType is TupleType tupleType)
                    {
                        for(var i = 0; i < elementPatterns.Count; i++)
                        {
                            var elementType = i < tupleType.ElementTypes.Count
                                ? tupleType.ElementTypes[i]
                                : ErrorType.Instance;
                            CollectFromPattern(elementPatterns[i], elementType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }
                    else
                    {
                        // Not a tuple type or ErrorType — still recurse to collect variables.
                        foreach(var elementPattern in elementPatterns)
                        {
                            CollectFromPattern(elementPattern, ErrorType.Instance, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    break;
                }

            case ParenthesizedPatternPrimaryPatternNode parenPattern:
                {
                    CollectFromPattern(parenPattern.Inner, scrutineeType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }

                // Constant patterns, relational patterns, and discard patterns
                // do not introduce variables — nothing to collect.
        }
    }

    private static void CollectFromPropertySubpatternList(
        PropertySubpatternListNode subpatternList,
        IType patternType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromPropertySubpattern(subpatternList.PropertySubpattern, patternType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        foreach(var subpattern in subpatternList.PropertySubpatterns)
        {
            CollectFromPropertySubpattern(subpattern, patternType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromPropertySubpattern(
        PropertySubpatternNode subpattern,
        IType patternType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Determine the property's type from the pattern type's member scope.
        var propertyType = ErrorType.Instance as IType;
        var propertyName = subpattern.Name.Lexeme;

        if(patternType is ClassType classType)
        {
            var member = classType.MemberScope.Lookup(propertyName);
            if(member?.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }
        else if(patternType is StructType structType)
        {
            var member = structType.MemberScope.Lookup(propertyName);
            if(member?.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }
        else if(patternType is AbstractType abstractType)
        {
            var member = abstractType.MemberScope.Lookup(propertyName);
            if(member?.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }

        // Recursively collect from the subpattern's inner pattern.
        CollectFromPattern(subpattern.Pattern, propertyType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void CollectFromListPatternElementList(
        ListPatternElementListNode elementList,
        IType elementType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        CollectFromListPatternElement(elementList.ListPatternElement, elementType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        foreach(var element in elementList.ListPatternElements)
        {
            CollectFromListPatternElement(element, elementType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void CollectFromListPatternElement(
        ListPatternElementNode element,
        IType elementType,
        Scope thenScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(element)
        {
            case PatternElementListPatternElementNode patternElement:
                CollectFromPattern(patternElement.Pattern, elementType, thenScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
                break;

            case SliceElementListPatternElementNode sliceElement:
                // Slice element with an identifier (`.. rest`): register the identifier.
                if(sliceElement.Name.HasValue)
                {
                    var name = sliceElement.Name.Value.Lexeme;
                    if(name != "_")
                    {
                        // The slice variable captures a sub-array, so its type
                        // is the same as the scrutinee array type (not the element type).
                        // For now, use ErrorType since we don't have the full
                        // array type here — the type checker will validate.
                        var varSpan = ToMistSourceSpan(sliceElement.Name.Value.Span);
                        var varSymbol = new Symbol(name, SymbolKind.LocalVariable, SymbolOrigin.UserCode, thenScope, ErrorType.Instance, varSpan);
                        thenScope.AddMember(varSymbol);
                        symbolTable.Register(varSymbol, sliceElement);
                    }
                }

                break;
        }
    }

    private static void ResolveForStatement(
        ForStatementNode forStmt,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Create a scope for the for statement (initializer variable is scoped here).
        var forScope = new Scope(parent: blockScope);

        if(forStmt.Initializer is ForInitializerVariableDeclarationForInitializerNode varInit)
        {
            var initType = ResolveTypeReference(varInit.VariableDeclaration, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
            _ = ResolveExpression(varInit.Initializer, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

            var varName = varInit.Name.Lexeme;
            var varSpan = ToMistSourceSpan(varInit.Name.Span);
            var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, forScope, initType, varSpan);
            forScope.AddMember(varSymbol);
            symbolTable.Register(varSymbol, varInit);
        }
        else if(forStmt.Initializer is ForInitializerVarDeclarationForInitializerNode varDeclInit)
        {
            var initExprType = ResolveExpression(varDeclInit.Initializer, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

            var varName = varDeclInit.Name.Lexeme;
            var varSpan = ToMistSourceSpan(varDeclInit.Name.Span);
            var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, forScope, initExprType, varSpan);
            forScope.AddMember(varSymbol);
            symbolTable.Register(varSymbol, varDeclInit);
        }
        else if(forStmt.Initializer is ForInitializerExpressionForInitializerNode exprInit)
        {
            _ = ResolveExpression(exprInit.Expression, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        if(forStmt.Condition is not null)
        {
            _ = ResolveExpression(forStmt.Condition, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        if(forStmt.Iterator is not null)
        {
            _ = ResolveExpression(forStmt.Iterator, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        ResolveBlock(forStmt.Body, forScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void ResolveForeachStatement(
        ForeachStatementNode foreachStmt,
        Scope blockScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var typeRef = foreachStmt.GetTypeOrNull();
        var elementType = typeRef is not null
            ? ResolveTypeReference(typeRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics)
            : ErrorType.Instance;
        var collectionType = ResolveExpression(foreachStmt.GetCollection(), blockScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Resolve IEnumerable<TElement> implementation on the collection type to infer
        // the element type. This handles both Mist-native and CLR IEnumerable types.
        // (Requirements 18.4, 18.6)
        var inferredElementType = TryInferForeachElementType(collectionType);
        if(inferredElementType is not null)
        {
            // Use the inferred element type for the loop variable. The explicit type
            // annotation is still used as the declared type (for type checking by the
            // emitter), but the inferred type ensures the semantic model correctly
            // understands the element type for downstream analysis.
            elementType = inferredElementType;
        }

        // Create a scope for the foreach body with the iteration variable.
        var foreachScope = new Scope(parent: blockScope);
        var varName = foreachStmt.GetName().Lexeme;
        var varSpan = ToMistSourceSpan(foreachStmt.GetName().Span);
        var varSymbol = new Symbol(varName, SymbolKind.LocalVariable, SymbolOrigin.UserCode, foreachScope, elementType, varSpan);
        foreachScope.AddMember(varSymbol);
        symbolTable.Register(varSymbol, foreachStmt);

        ResolveBlock(foreachStmt.GetBody(), foreachScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Attempts to infer the element type from a collection type's <c>IEnumerable&lt;TElement&gt;</c>
    /// implementation. Handles both Mist-native types (that directly implement
    /// <c>Standard.IEnumerable&lt;TElement&gt;</c>) and CLR types projected by the TypeProjector.
    ///
    /// <para>For <see cref="ConstructedType"/> collections (e.g., <c>List&lt;int&gt;</c>),
    /// substitutes the outer type arguments into the abstract type's type parameters to resolve
    /// the concrete element type.</para>
    ///
    /// <para>When multiple <c>IEnumerable&lt;T&gt;</c> implementations exist, returns <c>null</c>
    /// to require an explicit type annotation (Requirement 18.6).</para>
    /// </summary>
    /// <returns>The inferred element type, or <c>null</c> if inference is not possible.</returns>
    private static IType? TryInferForeachElementType(IType collectionType)
    {
        // Get the abstract types and type parameters/arguments for substitution.
        IReadOnlyList<IType> abstracts;
        IReadOnlyList<IType>? typeParams = null;
        IReadOnlyList<IType>? typeArgs = null;

        switch(collectionType)
        {
            case ConstructedType ct:
                {
                    // For constructed generic types (e.g., List<int>), get abstracts from
                    // the generic definition and prepare type parameter substitution.
                    var def = ct.GenericDefinition;
                    abstracts = def switch
                    {
                        ClassType c => c.Abstracts,
                        StructType s => s.Abstracts,
                        AbstractType i => i.Abstracts,
                        _ => Array.Empty<IType>(),
                    };
                    typeParams = def switch
                    {
                        ClassType c => c.TypeParameters,
                        StructType s => s.TypeParameters,
                        AbstractType i => i.TypeParameters,
                        _ => null,
                    };
                    typeArgs = ct.TypeArguments;
                    break;
                }
            case ClassType ct:
                abstracts = ct.Abstracts;
                break;
            case StructType st:
                abstracts = st.Abstracts;
                break;
            case ArrayType:
                // Arrays implement IEnumerable<T> — the element type is the array's element type.
                // This is already handled by the explicit type annotation, so skip inference.
                return null;
            default:
                return null;
        }

        // Find all IEnumerable<TElement> implementations.
        var enumerableElementTypes = new List<IType>();
        foreach(var iface in abstracts)
        {
            var extractedElementType = TryExtractIEnumerableElementType(iface, typeParams, typeArgs);
            if(extractedElementType is not null)
            {
                enumerableElementTypes.Add(extractedElementType);
            }
        }

        // Also check base class abstract types for ClassType.
        if(collectionType is ClassType classType)
        {
            var baseClass = classType.BaseType;
            while(baseClass is not null)
            {
                var baseAbstracts = baseClass switch
                {
                    ClassType bc => bc.Abstracts,
                    ConstructedType bct when bct.GenericDefinition is ClassType bcc => bcc.Abstracts,
                    _ => Array.Empty<IType>(),
                };
                foreach(var iface in baseAbstracts)
                {
                    var extractedElementType = TryExtractIEnumerableElementType(iface, null, null);
                    if(extractedElementType is not null)
                    {
                        enumerableElementTypes.Add(extractedElementType);
                    }
                }

                baseClass = baseClass switch
                {
                    ClassType bc => bc.BaseType,
                    _ => null,
                };
            }
        }
        else if(collectionType is ConstructedType ctForBase && ctForBase.GenericDefinition is ClassType ctBaseDef)
        {
            var baseClass = ctBaseDef.BaseType;
            while(baseClass is not null)
            {
                var baseAbstracts = baseClass switch
                {
                    ClassType bc => bc.Abstracts,
                    ConstructedType bct when bct.GenericDefinition is ClassType bcc => bcc.Abstracts,
                    _ => Array.Empty<IType>(),
                };
                foreach(var iface in baseAbstracts)
                {
                    var extractedElementType = TryExtractIEnumerableElementType(iface, typeParams, typeArgs);
                    if(extractedElementType is not null)
                    {
                        enumerableElementTypes.Add(extractedElementType);
                    }
                }

                baseClass = baseClass switch
                {
                    ClassType bc => bc.BaseType,
                    _ => null,
                };
            }
        }

        // Requirement 18.6: When multiple IEnumerable<T> implementations exist,
        // return null to require explicit type annotation.
        if(enumerableElementTypes.Count != 1)
        {
            return null;
        }

        return enumerableElementTypes[0];
    }

    /// <summary>
    /// Attempts to extract the element type from an abstract type type that is
    /// <c>Standard.IEnumerable&lt;TElement&gt;</c>. Returns the element type if the
    /// abstract type matches, or <c>null</c> otherwise.
    ///
    /// <para>When <paramref name="typeParams"/> and <paramref name="typeArgs"/> are provided,
    /// substitutes type parameters in the element type with the corresponding type arguments
    /// (for constructed generic types like <c>List&lt;int&gt;</c>).</para>
    /// </summary>
    private static IType? TryExtractIEnumerableElementType(
        IType ifaceType,
        IReadOnlyList<IType>? typeParams,
        IReadOnlyList<IType>? typeArgs)
    {
        // IEnumerable<TElement> is represented as a ConstructedType wrapping the
        // Standard.IEnumerable AbstractType with one type argument.
        if(ifaceType is not ConstructedType { GenericDefinition: AbstractType genericIface } constructed)
        {
            return null;
        }

        // Check if this is Standard.IEnumerable (the Mist stdlib abstract type).
        if(genericIface.DisplayName != "IEnumerable" || genericIface.ContainingNamespace != "Standard")
        {
            return null;
        }

        if(constructed.TypeArguments.Count != 1)
        {
            return null;
        }

        var extractedType = constructed.TypeArguments[0];

        // If the element type is a type parameter and we have substitution info,
        // substitute it with the concrete type argument.
        if(extractedType is TypeParameterType tpt && typeParams is not null && typeArgs is not null)
        {
            for(var i = 0; i < typeParams.Count && i < typeArgs.Count; i++)
            {
                if(typeParams[i] is TypeParameterType paramType && paramType.DisplayName == tpt.DisplayName)
                {
                    return typeArgs[i];
                }
            }
        }

        // If the element type is not a type parameter (already concrete), return it directly.
        if(extractedType is not TypeParameterType)
        {
            return extractedType;
        }

        // Type parameter couldn't be resolved — return null.
        return null;
    }

    // ─── Refinable Type Expression Resolution ─────────────────────────────

    /// <summary>
    /// Resolves a <see cref="RefinableTypeExpressionNode"/> to an <see cref="IType"/>.
    /// For single types without refinements, delegates to <see cref="ResolveSingleTypeRef"/>.
    /// For single types with refinements, validates predicate compatibility and constructs
    /// a <see cref="RefinementType"/>.
    /// For union types, builds a <see cref="UnionType"/> from the constituents (each of which
    /// may be a <see cref="RefinementType"/> if it has a refinement predicate).
    /// </summary>
    private static IType ResolveRefinableTypeExpression(
        RefinableTypeExpressionNode refinableExpr,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        string? aliasName = null)
    {
        // Union when there are PIPE-separated continuations; otherwise a single (optionally refined) type.
        if(refinableExpr.RefinableSingleTypeExprs.Length > 0)
        {
            var constituents = new List<IType>();
            var firstType = ResolveRefinableSingleTypeExpr(
                refinableExpr.First, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics, aliasName);
            constituents.Add(firstType);

            foreach(var additional in refinableExpr.RefinableSingleTypeExprs)
            {
                var additionalType = ResolveRefinableSingleTypeExpr(
                    additional, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics, aliasName);
                constituents.Add(additionalType);
            }

            // If any constituent is an error, propagate.
            if(constituents.Any(c => c is ErrorType))
            {
                return ErrorType.Instance;
            }

            return new UnionType(constituents.ToImmutableArray());
        }

        return ResolveRefinableSingleTypeExpr(
            refinableExpr.First, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics, aliasName);
    }

    /// <summary>
    /// Resolves a single refinable type expression (base type + optional refinement predicate).
    /// When a refinement is present, validates predicate compatibility and constructs a
    /// <see cref="RefinementType"/>. When no refinement is present, resolves the
    /// base <see cref="SingleTypeRefNode"/> directly.
    /// </summary>
    private static IType ResolveRefinableSingleTypeExpr(
        RefinableSingleTypeExprNode singleExpr,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        string? aliasName)
    {
        var baseType = ResolveSingleTypeRef(
            singleExpr.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        if(baseType is ErrorType)
        {
            return ErrorType.Instance;
        }

        // If no refinement predicate, return the plain base type.
        if(singleExpr.Refinement is null)
        {
            return baseType;
        }

        // Refinement is present — validate predicate compatibility with the base type.
        AndPatternNode andPatternNode;
        switch(singleExpr.Refinement)
        {
            case SimpleRefinementPredicateRefinementPredicateNode simple:
                andPatternNode = simple.Predicate;
                break;
            case CompoundRefinementPredicateRefinementPredicateNode compound:
                // Synthesize an AndPatternNode from the compound parts.
                // The compound form "and <pat1> and <pat2>" is equivalent to
                // an AndPattern with first=pat1 and rest=[pat2].
                andPatternNode = new AndPatternNode
                {
                    Left = compound.First,
                    UnaryPatterns = compound.UnaryPatterns
                };
                break;
            default:
                return ErrorType.Instance;
        }

        var predicate = new RefinementPredicate(andPatternNode);

        // Validate: relational patterns require a comparable type.
        if(PredicateContainsRelationalPattern(andPatternNode) && !IsComparableType(baseType))
        {
            diagnostics.Add(MakeDiagnosticWithLocation(
                IncompatibleRefinementPredicate.Value,
                DiagnosticSeverity.Error,
                $"Refinement predicate '{predicate.Description}' is not valid for base type '{baseType.DisplayName}'. Relational patterns require a comparable type.",
                singleExpr.Refinement,
                sourceText));
            return ErrorType.Instance;
        }

        // Validate: regex refinement predicates are only valid on string types (Requirement 11.3).
        if(PredicateContainsRegexPattern(andPatternNode))
        {
            if(!IsStringType(baseType))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    RegexRefinementOnNonString.Value,
                    DiagnosticSeverity.Error,
                    $"Regex refinement predicates are only valid on 'string' types, but found base type '{baseType.DisplayName}'",
                    singleExpr.Refinement,
                    sourceText));
                return ErrorType.Instance;
            }

            // Validate regex pattern syntax (Requirement 11.4).
            var regexLexeme = ExtractRegexLexemeFromPredicate(andPatternNode);
            if(regexLexeme is not null)
            {
                var raw = regexLexeme.Length >= 2 ? regexLexeme[1..^1] : string.Empty;
                var pattern = raw.Replace("\\`", "`").Replace("\\\\", "\\");
                try
                {
                    _ = new System.Text.RegularExpressions.Regex(pattern, System.Text.RegularExpressions.RegexOptions.None);
                }
                catch(ArgumentException ex)
                {
                    var offset = ex is System.Text.RegularExpressions.RegexParseException parseEx ? parseEx.Offset : 0;
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST_TC_REGEX_INVALID",
                        DiagnosticSeverity.Error,
                        $"Invalid regex pattern: {ex.Message} at offset {offset}",
                        singleExpr.Refinement,
                        sourceText));
                    return ErrorType.Instance;
                }
            }
        }

        // Construct the RefinementType.
        var name = aliasName ?? baseType.DisplayName;
        return new RefinementType(name, baseType, predicate);
    }

    /// <summary>
    /// Determines whether a type supports comparison operators (numeric types and char).
    /// Used to validate that relational refinement predicates are compatible with the base type.
    /// </summary>
    private static bool IsComparableType(IType type)
    {
        // Unwrap RefinementType to check the underlying base type.
        // e.g., ZeroOrPositiveInt (= int >= 0) should be comparable because its base type is int.
        if(type is RefinementType refinement)
        {
            return IsComparableType(refinement.BaseType);
        }

        var displayName = type.DisplayName;
        return displayName switch
        {
            // Legacy primitive names.
            "int" or "uint" or "long" or "ulong" => true,
            "short" or "ushort" or "byte" or "sbyte" => true,
            "float" or "double" or "decimal" => true,
            "char" => true,
            // Stdlib names.
            "Int32" or "UInt32" or "Int64" or "UInt64" => true,
            "Int16" or "UInt16" or "Byte" or "SByte" => true,
            "Single" or "Double" or "Decimal" => true,
            "Char" => true,
            _ => false,
        };
    }

    /// <summary>
    /// Checks whether an <see cref="AndPatternNode"/> contains any relational patterns
    /// (greater-than, less-than, greater-than-or-equal, less-than-or-equal).
    /// </summary>
    private static bool PredicateContainsRelationalPattern(AndPatternNode andPattern)
    {
        if(IsRelationalUnaryPattern(andPattern.Left))
        {
            return true;
        }

        if(andPattern.Right is not null && !ReferenceEquals(andPattern.Right, andPattern.Left))
        {
            if(IsRelationalUnaryPattern(andPattern.Right))
            {
                return true;
            }
        }

        if(!andPattern.UnaryPatterns.IsDefaultOrEmpty)
        {
            foreach(var part in andPattern.UnaryPatterns)
            {
                if(IsRelationalUnaryPattern(part))
                {
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether a <see cref="UnaryPatternNode"/> is a relational pattern.
    /// </summary>
    private static bool IsRelationalUnaryPattern(UnaryPatternNode unary)
    {
        if(unary is not DirectPatternUnaryPatternNode direct)
        {
            return false;
        }

        return direct.Primary is GreaterThanOrEqualRelationalPatternPrimaryPatternNode
            or LessThanOrEqualRelationalPatternPrimaryPatternNode
            or GreaterThanRelationalPatternPrimaryPatternNode
            or LessThanRelationalPatternPrimaryPatternNode;
    }

    /// <summary>
    /// Checks whether an <see cref="AndPatternNode"/> contains a regex constant pattern.
    /// Used to validate that regex refinement predicates are only applied to string types.
    /// </summary>
    private static bool PredicateContainsRegexPattern(AndPatternNode andPattern)
    {
        if(IsRegexUnaryPattern(andPattern.Left))
        {
            return true;
        }

        if(andPattern.Right is not null && !ReferenceEquals(andPattern.Right, andPattern.Left))
        {
            if(IsRegexUnaryPattern(andPattern.Right))
            {
                return true;
            }
        }

        if(!andPattern.UnaryPatterns.IsDefaultOrEmpty)
        {
            foreach(var part in andPattern.UnaryPatterns)
            {
                if(IsRegexUnaryPattern(part))
                {
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether a <see cref="UnaryPatternNode"/> contains a regex constant pattern.
    /// </summary>
    private static bool IsRegexUnaryPattern(UnaryPatternNode unary)
    {
        if(unary is not DirectPatternUnaryPatternNode direct)
        {
            return false;
        }

        return direct.Primary is ConstantPatternPrimaryPatternNode { Literal: RegexConstantConstantLiteralNode };
    }

    /// <summary>
    /// Determines whether a type is the <c>string</c> type (either keyword or stdlib name).
    /// </summary>
    private static bool IsStringType(IType type)
    {
        var displayName = type.DisplayName;
        return displayName is "string" or "String";
    }

    /// <summary>
    /// Extracts the regex literal lexeme from a predicate's <see cref="AndPatternNode"/>.
    /// Returns <c>null</c> if no regex constant is found.
    /// </summary>
    private static string? ExtractRegexLexemeFromPredicate(AndPatternNode andPattern)
    {
        var lexeme = TryExtractRegexLexemeFromUnary(andPattern.Left);
        if(lexeme is not null)
        {
            return lexeme;
        }

        if(andPattern.Right is not null && !ReferenceEquals(andPattern.Right, andPattern.Left))
        {
            lexeme = TryExtractRegexLexemeFromUnary(andPattern.Right);
            if(lexeme is not null)
            {
                return lexeme;
            }
        }

        if(!andPattern.UnaryPatterns.IsDefaultOrEmpty)
        {
            foreach(var part in andPattern.UnaryPatterns)
            {
                lexeme = TryExtractRegexLexemeFromUnary(part);
                if(lexeme is not null)
                {
                    return lexeme;
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Tries to extract a regex literal lexeme from a <see cref="UnaryPatternNode"/>.
    /// </summary>
    private static string? TryExtractRegexLexemeFromUnary(UnaryPatternNode unary)
    {
        if(unary is DirectPatternUnaryPatternNode { Primary: ConstantPatternPrimaryPatternNode { Literal: RegexConstantConstantLiteralNode regexConst } })
        {
            return regexConst.Value.Lexeme;
        }

        return null;
    }

    /// <summary>
    /// Checks whether a <see cref="UnionType"/> has at least one constituent that is a
    /// <see cref="RefinementType"/>.
    /// </summary>
    private static bool HasRefinementConstituent(UnionType unionType)
    {
        foreach(var constituent in unionType.Constituents)
        {
            if(constituent is RefinementType)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Checks whether a <see cref="RefinableTypeExpressionNode"/> contains any refinement
    /// predicates. Used to suppress cascading diagnostics when an incompatible predicate
    /// already caused an error.
    /// </summary>
    private static bool HasRefinementPredicate(RefinableTypeExpressionNode refinableExpr)
    {
        if(refinableExpr.First.Refinement is not null)
        {
            return true;
        }

        foreach(var additional in refinableExpr.RefinableSingleTypeExprs)
        {
            if(additional.Refinement is not null)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Extracts a human-readable type name from a <see cref="RefinableTypeExpressionNode"/>
    /// for use in diagnostic messages.
    /// </summary>
    private static string ExtractRefinableTypeExpressionName(
        RefinableTypeExpressionNode refinableExpr,
        SourceText? sourceText)
    {
        return ExtractSingleTypeRefName(refinableExpr.First.Type, sourceText);
    }

    private static string ExtractSingleTypeRefName(SingleTypeRefNode singleTypeRef, SourceText? sourceText)
    {
        switch(singleTypeRef)
        {
            case NamedSingleTypeRefSingleTypeRefNode namedRef:
                var lexeme = namedRef.Name.IDENTIFIER.Lexeme;
                if(!string.IsNullOrEmpty(lexeme))
                {
                    return lexeme;
                }

                if(sourceText is not null)
                {
                    var span = namedRef.Name.Span;
                    if(span.Length > 0 && span.Start + span.Length <= sourceText.Contents.Length)
                    {
                        return sourceText.Contents.Substring(span.Start, span.Length);
                    }
                }

                return "";
            case PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef:
                return FormatPrimitiveType(primitiveRef.PrimitiveType);
            case VoidSingleTypeRefSingleTypeRefNode:
                return "void";
            default:
                return "unknown";
        }
    }

    // ─── Type Reference Resolution ───────────────────────────────────────

    /// <summary>
    /// Resolves a TypeReference AST node to an IType.
    /// Lookup order: primitives → string/void → scope chain → imported namespaces → ErrorType.
    /// </summary>
    /// <summary>
    /// Resolves an ElementTypeRefNode (used in array creation expressions) to an IType.
    /// ElementTypeRef is a restricted TypeReference without ArrayRankSuffix.
    /// </summary>
    private static IType ResolveElementTypeRef(
        ElementTypeRefNode elementTypeRef,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(elementTypeRef)
        {
            case PrimitiveElementTypeRefElementTypeRefNode primitiveRef:
                return ResolvePrimitiveType(primitiveRef.PrimitiveType);
            case UnknownElementTypeRefElementTypeRefNode:
                return UnknownType.Instance;
            case NamedElementTypeRefElementTypeRefNode namedRef:
                {
                    var name = ExtractQualifiedName(namedRef.Name, sourceText);
                    return ResolveNamedType(name, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                }
            default:
                return ErrorType.Instance;
        }
    }

    /// <summary>
    /// Applies the optional type suffix (<c>?</c>) to a resolved base type.
    /// When the <c>optional</c> field is present on a type reference node:
    /// <list type="bullet">
    ///   <item>If T is void itself → emit warning MIST_TC_0046 (redundant), return T unchanged.</item>
    ///   <item>If T is a UnionType that already contains void → emit error MIST_TC_0045 (double-optional), return T unchanged.</item>
    ///   <item>Otherwise → create <c>UnionType([T, VoidType])</c> with canonical ordering.</item>
    /// </list>
    /// </summary>
    private static IType ApplyOptionalSuffix(
        IType resolvedType,
        Storm.Runtime.Token optionalToken,
        Scope fileScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Unwrap type aliases to check the underlying type.
        var effectiveType = resolvedType;
        if(effectiveType is TypeAliasType alias)
        {
            effectiveType = alias.UnderlyingType;
        }

        // Case 1: T is void itself — redundant `void?`
        if(effectiveType.IsVoid())
        {
            diagnostics.Add(MakeDiagnosticWithTokenLocation(
                "MIST_TC_0046",
                DiagnosticSeverity.Warning,
                "Applying '?' to 'void' is redundant \u2014 the type is already 'void'.",
                optionalToken,
                sourceText));
            return resolvedType;
        }

        // Case 2: T is a UnionType that already contains void — double-optional error
        if(effectiveType is UnionType existingUnion)
        {
            foreach(var constituent in existingUnion.Constituents)
            {
                if(constituent.IsVoid())
                {
                    diagnostics.Add(MakeDiagnosticWithTokenLocation(
                        "MIST_TC_0045",
                        DiagnosticSeverity.Error,
                        "The optional suffix '?' cannot be applied to a type that already contains 'void'.",
                        optionalToken,
                        sourceText));
                    return resolvedType;
                }
            }
        }

        // Case 2b: T is a ref struct — ref structs cannot be optional (Requirement 3.9).
        var isRefStruct = IsRefStructType(effectiveType);
        if(isRefStruct)
        {
            var typeName = effectiveType.DisplayName;
            diagnostics.Add(MakeDiagnosticWithTokenLocation(
                RefStructCannotBeOptional.Value,
                DiagnosticSeverity.Error,
                $"Ref struct type '{typeName}' cannot be optional",
                optionalToken,
                sourceText));
            return resolvedType;
        }

        // Case 3: Normal case — wrap T in UnionType([T, VoidType])
        IType voidType;
        try
        {
            var globalScope = FindGlobalScope(fileScope) ?? fileScope;
            voidType = ResolveVoidKeyword(globalScope, symbolTable);
        }
        catch(StdlibMissingException)
        {
            voidType = LegacyPrimitiveTypes.Void;
        }

        return new UnionType(new List<IType> { resolvedType, voidType });
    }

    private static IType ResolveTypeReference(
        TypeReferenceNode typeRef,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Post parser-backtracking restructure: TypeReference is a flat
        // `first:SingleTypeRef (PIPE rest:SingleTypeRef)*` node. A union is
        // signalled by a non-empty SingleTypeRefs continuation list — never
        // by the non-nullable `Rest` codegen artifact. A non-union reference
        // is fully described by `First` and resolves through ResolveSingleTypeRef.
        if(typeRef.SingleTypeRefs.Length > 0)
        {
            return ResolveUnionTypeRef(typeRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
        }

        return ResolveSingleTypeRef(typeRef.First, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
    }

    /// <summary>
    /// Resolves a union <see cref="TypeReferenceNode"/> (one with a non-empty
    /// <see cref="TypeReferenceNode.SingleTypeRefs"/> continuation list) to an
    /// <see cref="IType"/>. Applies the construction rules from the design document:
    /// 1. Resolve each constituent type reference.
    /// 2. Flatten: if a constituent is itself a <see cref="UnionType"/>, inline its constituents.
    /// 3. Deduplicate: remove duplicate types by <see cref="IType.DisplayName"/> equality.
    /// 4. If only one distinct constituent remains, return that type directly (not a union).
    /// 5. Sort constituents by DisplayName for canonical form (handled by <see cref="UnionType"/> constructor).
    /// 6. If any constituent resolves to <see cref="ErrorType"/>, include it but still produce the union.
    /// </summary>
    private static IType ResolveUnionTypeRef(
        TypeReferenceNode typeRef,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Collect all constituent SingleTypeRefNodes: First + the PIPE-separated
        // continuations in SingleTypeRefs (never the non-nullable Rest artifact).
        var singleTypeRefs = new List<SingleTypeRefNode>
        {
            typeRef.First
        };
        foreach(var rest in typeRef.SingleTypeRefs)
        {
            singleTypeRefs.Add(rest);
        }

        // Resolve each constituent and flatten nested unions.
        var flatConstituents = new List<IType>();
        foreach(var singleRef in singleTypeRefs)
        {
            var resolved = ResolveSingleTypeRef(singleRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

            // ── MIST2005: Ref struct union type restriction (Requirement 3.8) ──
            // A ref struct type cannot participate in union types, since union types
            // may require boxing the value to store it in a discriminated container.
            if(IsRefStructType(resolved))
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST2005",
                    DiagnosticSeverity.Error,
                    $"Ref struct type '{resolved.DisplayName}' cannot participate in union types",
                    singleRef,
                    sourceText));
            }

            // Flatten: if the resolved type is itself a UnionType, inline its constituents.
            if(resolved is UnionType nestedUnion)
            {
                foreach(var nested in nestedUnion.Constituents)
                {
                    flatConstituents.Add(nested);
                }
            }
            else
            {
                flatConstituents.Add(resolved);
            }
        }

        // Deduplicate by DisplayName equality.
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var distinct = new List<IType>();
        foreach(var type in flatConstituents)
        {
            if(seen.Add(type.DisplayName))
            {
                distinct.Add(type);
            }
        }

        // If only one distinct constituent remains, return that type directly.
        if(distinct.Count == 1)
        {
            // Task 6.3 / Req 12.1: Degenerate union — fewer than 2 distinct
            // types after deduplication. Emit a warning unless the reduction
            // is caused by ErrorType (unresolved constituent), which would
            // cascade from an already-reported diagnostic.
            var hasErrorType = false;
            foreach(var type in flatConstituents)
            {
                if(type is ErrorType)
                {
                    hasErrorType = true;
                    break;
                }
            }

            if(!hasErrorType && flatConstituents.Count > distinct.Count)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_TC_0075",
                    DiagnosticSeverity.Warning,
                    $"Union type has fewer than 2 distinct types after deduplication (resolved to '{distinct[0].DisplayName}'). A union type requires at least two distinct types.",
                    typeRef,
                    sourceText));
            }

            return distinct[0];
        }

        // Produce the union (UnionType constructor handles canonical sorting).
        return new UnionType(distinct);
    }

    /// <summary>
    /// Resolves an associated type slot name from a type parameter's constraints.
    /// When a type parameter <c>T</c> is constrained by an abstract type that declares
    /// an associated type slot with the given name, returns the <see cref="AssociatedTypeSlotType"/>.
    /// Returns <c>null</c> if no constraining abstract type declares a slot with that name.
    /// </summary>
    private static AssociatedTypeSlotType? ResolveAssociatedTypeSlotFromConstraints(
        TypeParameterType typeParam,
        string slotName)
    {
        if(typeParam.Constraints is null)
        {
            return null;
        }

        var constraints = typeParam.Constraints;

        // Check abstract type constraints (may be AbstractType or ConstructedType wrapping AbstractType).
        foreach(var ifaceConstraint in constraints.AbstractConstraints)
        {
            var ifaceType = ifaceConstraint is ConstructedType ct
                ? ct.GenericDefinition as AbstractType
                : ifaceConstraint as AbstractType;

            if(ifaceType is not null)
            {
                var member = ifaceType.MemberScope.Lookup(slotName);
                if(member is not null && member.DeclaredType is AssociatedTypeSlotType slotType)
                {
                    return slotType;
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Resolves a <see cref="SingleTypeRefNode"/> to an <see cref="IType"/>.
    /// Mirrors the logic of <see cref="ResolveTypeReference"/> but for the
    /// <c>SingleTypeRef</c> grammar alternatives (which exclude the union
    /// alternative to prevent infinite left-recursion).
    /// </summary>
    private static IType ResolveSingleTypeRef(
        SingleTypeRefNode singleTypeRef,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(singleTypeRef)
        {
            case PrimitiveSingleTypeRefSingleTypeRefNode primitiveRef:
                {
                    IType primBase;
                    try
                    {
                        var primGlobalScope = FindGlobalScope(fileScope) ?? fileScope;
                        primBase = ResolvePrimitiveKeyword(primGlobalScope, symbolTable, primitiveRef.PrimitiveType);
                    }
                    catch(StdlibMissingException)
                    {
                        primBase = ResolveLegacyPrimitive(primitiveRef.PrimitiveType);
                    }

                    if(primitiveRef.ArrayRank is SizedArrayRankArrayRankSuffixNode sizedRank)
                    {
                        var size = long.Parse(sizedRank.Size.Lexeme);
                        primBase = new ArrayType(primBase, size);
                    }
                    else if(primitiveRef.ArrayRank is not null)
                    {
                        primBase = allocatingParameterArrayType
                            ? new ArrayType(primBase, nextSymbolicLengthId++)
                            : new ArrayType(primBase);
                    }
                    // Apply optional suffix: T? → UnionType([T, VoidType])
                    if(primitiveRef.Optional is { } primOptToken)
                    {
                        return ApplyOptionalSuffix(primBase, primOptToken, fileScope, symbolTable, sourceText, diagnostics);
                    }

                    return primBase;
                }

            case VoidSingleTypeRefSingleTypeRefNode:
                {
                    try
                    {
                        var voidGlobalScope = FindGlobalScope(fileScope) ?? fileScope;
                        return ResolveVoidKeyword(voidGlobalScope, symbolTable);
                    }
                    catch(StdlibMissingException)
                    {
                        return LegacyPrimitiveTypes.Void;
                    }
                }

            case UnknownSingleTypeRefSingleTypeRefNode:
                return UnknownType.Instance;

            case NamedSingleTypeRefSingleTypeRefNode namedRef:
                {
                    var typeName = ExtractQualifiedName(namedRef.Name, sourceText);

                    // Check if the identifier resolves to a TypeParameterType first.
                    var namedSymbol = fileScope.Lookup(typeName);
                    if(namedSymbol is not null && namedSymbol.DeclaredType is TypeParameterType tpt)
                    {
                        if(namedRef.TypeArgs is not null)
                        {
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                GenericsDiagnostics.NotGeneric.Id.Value,
                                DiagnosticSeverity.Error,
                                $"Type '{typeName}' is not generic and does not accept type arguments.",
                                namedRef,
                                sourceText));
                        }
                        // Apply optional suffix if present
                        if(namedRef.Optional is { } tptOptToken)
                        {
                            return ApplyOptionalSuffix(tpt, tptOptToken, fileScope, symbolTable, sourceText, diagnostics);
                        }

                        return tpt;
                    }

                    // Dependent type parameters (e.g., class Buffer<N:int>) also do not
                    // accept type arguments. Preserved from the pre-restructure
                    // ResolveTypeReference Named case so delegation is behaviour-equivalent.
                    if(namedSymbol is not null && namedSymbol.DeclaredType is DependentTypeParameterType dpt)
                    {
                        if(namedRef.TypeArgs is not null)
                        {
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                GenericsDiagnostics.NotGeneric.Id.Value,
                                DiagnosticSeverity.Error,
                                $"Type '{typeName}' is not generic and does not accept type arguments.",
                                namedRef,
                                sourceText));
                        }
                        // Apply optional suffix if present
                        if(namedRef.Optional is { } dptOptToken)
                        {
                            return ApplyOptionalSuffix(dpt, dptOptToken, fileScope, symbolTable, sourceText, diagnostics);
                        }

                        return dpt;
                    }

                    // ── Associated type resolution: T.SlotName in generic contexts ──
                    // When a qualified name like "T.SlotName" is used as a type reference
                    // and the first part is a type parameter constrained by an abstract type
                    // with associated type slots, resolve through the constraint's member scope.
                    var firstDot = typeName.IndexOf('.');
                    if(firstDot > 0 && firstDot < typeName.Length - 1)
                    {
                        var leftPart = typeName[..firstDot];
                        var rightPart = typeName[(firstDot + 1)..];

                        var leftSymbol = fileScope.Lookup(leftPart);
                        if(leftSymbol is not null && leftSymbol.DeclaredType is TypeParameterType typeParamLeft)
                        {
                            var resolvedSlot = ResolveAssociatedTypeSlotFromConstraints(typeParamLeft, rightPart);
                            if(resolvedSlot is not null)
                            {
                                // Apply optional suffix if present
                                if(namedRef.Optional is { } slotOptToken)
                                {
                                    return ApplyOptionalSuffix(resolvedSlot, slotOptToken, fileScope, symbolTable, sourceText, diagnostics);
                                }

                                return resolvedSlot;
                            }

                            // The left part is a type parameter but the right part is not
                            // an associated type slot of any constraining abstract type.
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                CommonDiagnostics.UnresolvedAssociatedTypeReference.Id.Value,
                                DiagnosticSeverity.Error,
                                $"Type parameter '{leftPart}' does not have an associated type '{rightPart}'; '{leftPart}' is not constrained by an abstract type declaring '{rightPart}'.",
                                namedRef,
                                sourceText));
                            return ErrorType.Instance;
                        }
                    }

                    // ── Span<T, Length> / ReadOnlySpan<T, Length> → SpanType ──────
                    // Mirrors the Array<T, Length> → ArrayType routing: the arity-2
                    // intrinsic span form is represented at use-sites by the dedicated
                    // SpanType IType rather than a StructType/ConstructedType. This also
                    // makes the `type Span<T> = Span<T, unknown>;` /
                    // `type ReadOnlySpan<T> = ReadOnlySpan<T, unknown>;` aliases resolve
                    // to SpanType(T, unknown): the alias RHS is a 2-arg reference handled
                    // here, and the arity-1 alias name is applied via type substitution.
                    // A literal integer Length yields a known-length span; any other
                    // Length argument (including `unknown`) yields an unknown-length span.
                    if(namedRef.TypeArgs is not null
                        && (typeName is "Span" or "Standard.Span" or "ReadOnlySpan" or "Standard.ReadOnlySpan")
                        && CountTypeArgs(namedRef.TypeArgs) == 2)
                    {
                        var spanIsReadOnly = typeName is "ReadOnlySpan" or "Standard.ReadOnlySpan";
                        var spanTypeArgList = namedRef.TypeArgs;
                        var spanElementRef = spanTypeArgList.GetTypeReference();
                        var spanElement = ResolveTypeReference(spanElementRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                        // Inspect the second type argument: an integer literal is a known
                        // compile-time Length; everything else (e.g. `unknown`) is unknown.
                        long? spanKnownLength = null;
                        var spanArgNodes = new List<TypeArgumentNode> { spanTypeArgList.TypeArgument };
                        foreach(var extra in spanTypeArgList.TypeArguments)
                        {
                            spanArgNodes.Add(extra);
                        }

                        if(spanArgNodes.Count > 1
                            && spanArgNodes[1] is IntegerLiteralTypeArgumentTypeArgumentNode spanIntLit
                            && long.TryParse(spanIntLit.Literal.Lexeme, out var spanLen))
                        {
                            spanKnownLength = spanLen;
                        }

                        IType spanType = spanKnownLength.HasValue
                            ? new SpanType(spanElement, spanKnownLength.Value, spanIsReadOnly)
                            : new SpanType(spanElement, spanIsReadOnly);

                        if(namedRef.Optional is { } spanOptToken)
                        {
                            return ApplyOptionalSuffix(spanType, spanOptToken, fileScope, symbolTable, sourceText, diagnostics);
                        }

                        return spanType;
                    }

                    var baseType = ResolveNamedType(typeName, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics,
                        typeArgumentCount: namedRef.TypeArgs is not null ? CountTypeArgs(namedRef.TypeArgs) : 0);

                    // Handle type arguments if present.
                    if(namedRef.TypeArgs is not null)
                    {
                        baseType = ResolvePass2TypeArguments(baseType, typeName, namedRef.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    }

                    if(namedRef.ArrayRank is SizedArrayRankArrayRankSuffixNode sizedRank)
                    {
                        var size = long.Parse(sizedRank.Size.Lexeme);
                        baseType = new ArrayType(baseType, size);
                    }
                    else if(namedRef.ArrayRank is not null)
                    {
                        baseType = allocatingParameterArrayType
                            ? new ArrayType(baseType, nextSymbolicLengthId++)
                            : new ArrayType(baseType);
                    }
                    // Apply optional suffix: T? → UnionType([T, VoidType])
                    if(namedRef.Optional is { } namedOptToken)
                    {
                        return ApplyOptionalSuffix(baseType, namedOptToken, fileScope, symbolTable, sourceText, diagnostics);
                    }

                    return baseType;
                }

            case ParenthesizedTypeRefSingleTypeRefNode parenRef:
                {
                    // Resolve the inner type reference (which can be any TypeReference, including unions).
                    var inner = ResolveTypeReference(parenRef.Inner, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    if(parenRef.ArrayRank is SizedArrayRankArrayRankSuffixNode parenSizedRank)
                    {
                        var size = long.Parse(parenSizedRank.Size.Lexeme);
                        return new ArrayType(inner, size);
                    }
                    else if(parenRef.ArrayRank is not null)
                    {
                        return allocatingParameterArrayType
                            ? new ArrayType(inner, nextSymbolicLengthId++)
                            : new ArrayType(inner);
                    }

                    return inner;
                }

            case TupleSingleTypeRefSingleTypeRefNode tupleRef:
                {
                    var elementCount = 2 + tupleRef.TupleTypeElements.Length;
                    var elementTypes = new List<IType>(elementCount);
                    var elementNames = new List<string?>(elementCount);
                    var hasAnyName = false;

                    elementTypes.Add(ResolveTypeReference(tupleRef.First.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics));
                    var firstName = tupleRef.First.Name?.Lexeme;
                    elementNames.Add(firstName);
                    if(firstName is not null)
                    {
                        hasAnyName = true;
                    }

                    elementTypes.Add(ResolveTypeReference(tupleRef.Rest.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics));
                    var restName = tupleRef.Rest.Name?.Lexeme;
                    elementNames.Add(restName);
                    if(restName is not null)
                    {
                        hasAnyName = true;
                    }

                    foreach(var additional in tupleRef.TupleTypeElements)
                    {
                        elementTypes.Add(ResolveTypeReference(additional.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics));
                        var additionalName = additional.Name?.Lexeme;
                        elementNames.Add(additionalName);
                        if(additionalName is not null)
                        {
                            hasAnyName = true;
                        }
                    }

                    return new TupleType(elementTypes, hasAnyName ? elementNames : null);
                }

            case FuncSingleTypeRefSingleTypeRefNode funcRef:
                {
                    // The `func<T1, ..., TN>` keyword form resolves to the same
                    // Standard.Func<T1, ..., TN> type as the named `Func<T1, ..., TN>` path.
                    var typeArgumentCount = CountTypeArgs(funcRef.TypeArgs);
                    var globalScope = FindGlobalScope(fileScope) ?? fileScope;
                    IType funcDefinition;
                    try
                    {
                        funcDefinition = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Func", typeArgumentCount);
                    }
                    catch(StdlibMissingException)
                    {
                        return ErrorType.Instance;
                    }

                    return ResolvePass2TypeArguments(funcDefinition, "func", funcRef.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                }

            default:
                return ErrorType.Instance;
        }
    }

    /// <summary>
    /// Maps a PrimitiveTypeNode to its well-known legacy fallback type.
    /// Used only when stdlib is not loaded (the primary path goes through
    /// ResolvePrimitiveKeyword). Post-Task 49: uses LegacyPrimitiveTypes
    /// instead of the deleted PrimitiveType singletons.
    /// </summary>
    private static IType ResolvePrimitiveType(PrimitiveTypeNode node)
    {
        return node switch
        {
            IntTypePrimitiveTypeNode => LegacyPrimitiveTypes.Int,
            UintTypePrimitiveTypeNode => LegacyPrimitiveTypes.Uint,
            LongTypePrimitiveTypeNode => LegacyPrimitiveTypes.Long,
            UlongTypePrimitiveTypeNode => LegacyPrimitiveTypes.Ulong,
            ShortTypePrimitiveTypeNode => LegacyPrimitiveTypes.Short,
            UshortTypePrimitiveTypeNode => LegacyPrimitiveTypes.Ushort,
            ByteTypePrimitiveTypeNode => LegacyPrimitiveTypes.Byte,
            SbyteTypePrimitiveTypeNode => LegacyPrimitiveTypes.Sbyte,
            FloatTypePrimitiveTypeNode => LegacyPrimitiveTypes.Float,
            DoubleTypePrimitiveTypeNode => LegacyPrimitiveTypes.Double,
            DecimalTypePrimitiveTypeNode => LegacyPrimitiveTypes.Decimal,
            BoolTypePrimitiveTypeNode => LegacyPrimitiveTypes.Bool,
            CharTypePrimitiveTypeNode => LegacyPrimitiveTypes.Char,
            StringTypePrimitiveTypeNode => LegacyPrimitiveTypes.String,
            RegexTypePrimitiveTypeNode => LegacyPrimitiveTypes.Regex,
            _ => ErrorType.Instance,
        };
    }

    /// <summary>
    /// Pass-2 fallback for a primitive keyword reference when no stdlib
    /// has been loaded for the current compilation: returns the legacy
    /// fallback singleton DIRECTLY (bypassing the
    /// <see cref="PrimitiveTypeRegistry"/>-backed
    /// public property accessors). Using the legacy singletons here
    /// guarantees that a build without stdlib never embeds another
    /// parallel build's stdlib <see cref="IType"/> instances in its own
    /// expression-type map — a behaviour that would make reference-
    /// equality assertions order-dependent under parallel test
    /// execution.
    /// </summary>
    private static IType ResolveLegacyPrimitive(PrimitiveTypeNode node)
    {
        return node switch
        {
            IntTypePrimitiveTypeNode => LegacyPrimitiveTypes.Int,
            UintTypePrimitiveTypeNode => LegacyPrimitiveTypes.Uint,
            LongTypePrimitiveTypeNode => LegacyPrimitiveTypes.Long,
            UlongTypePrimitiveTypeNode => LegacyPrimitiveTypes.Ulong,
            ShortTypePrimitiveTypeNode => LegacyPrimitiveTypes.Short,
            UshortTypePrimitiveTypeNode => LegacyPrimitiveTypes.Ushort,
            ByteTypePrimitiveTypeNode => LegacyPrimitiveTypes.Byte,
            SbyteTypePrimitiveTypeNode => LegacyPrimitiveTypes.Sbyte,
            FloatTypePrimitiveTypeNode => LegacyPrimitiveTypes.Float,
            DoubleTypePrimitiveTypeNode => LegacyPrimitiveTypes.Double,
            DecimalTypePrimitiveTypeNode => LegacyPrimitiveTypes.Decimal,
            BoolTypePrimitiveTypeNode => LegacyPrimitiveTypes.Bool,
            CharTypePrimitiveTypeNode => LegacyPrimitiveTypes.Char,
            StringTypePrimitiveTypeNode => LegacyPrimitiveTypes.String,
            RegexTypePrimitiveTypeNode => LegacyPrimitiveTypes.Regex,
            _ => ErrorType.Instance,
        };
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Stdlib type lookup — direct, scope-chain-bypassing resolution
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Resolves a fully-qualified Standard Library type name (e.g.,
    /// <c>"Standard.Int32"</c>) by walking directly from the global scope to
    /// the target namespace scope and looking up the simple name among its
    /// members. Does <b>not</b> consult any file scope, <c>using</c>
    /// directive, or user-declared type — per Requirement 7.6 this path
    /// intentionally bypasses all ordinary name-resolution machinery so that
    /// a primitive keyword alias like <c>int</c> always reaches the stdlib
    /// type and cannot be shadowed by user code.
    ///
    /// <para>
    /// Throws <see cref="StdlibMissingException"/> (carrying diagnostic
    /// <c>MIST_STDLIB_MISSING</c>) if the namespace scope is missing (the
    /// stdlib has not been loaded into this compilation) or if the requested
    /// simple name does not resolve to a type symbol inside the namespace.
    /// </para>
    /// </summary>
    /// <param name="globalScope">
    /// The compilation's global scope (returned by the running
    /// <see cref="Build"/> invocation).
    /// </param>
    /// <param name="symbolTable">
    /// The symbol table that <see cref="FindExistingNamespaceScope"/> uses to
    /// locate namespace scopes.
    /// </param>
    /// <param name="qualifiedName">
    /// The fully-qualified stdlib type name in <c>Namespace.SimpleName</c>
    /// form (e.g., <c>"Standard.Int32"</c>).
    /// </param>
    internal static IType LookupQualifiedStdlibType(
        Scope globalScope,
        SymbolTable symbolTable,
        string qualifiedName)
    {
        return LookupQualifiedStdlibType(globalScope, symbolTable, qualifiedName, typeArgumentCount: -1);
    }

    /// <summary>
    /// Arity-aware overload of <see cref="LookupQualifiedStdlibType(Scope, SymbolTable, string)"/>.
    /// When <paramref name="typeArgumentCount"/> is &gt;= 0, the member whose declared type
    /// has exactly that many type parameters is returned (e.g., to disambiguate the
    /// <c>Standard.Func</c> family's 17 same-named arities). When negative, the first
    /// type-kind match is returned (legacy behavior).
    /// </summary>
    internal static IType LookupQualifiedStdlibType(
        Scope globalScope,
        SymbolTable symbolTable,
        string qualifiedName,
        int typeArgumentCount)
    {
        // Split "Namespace.SimpleName" into its two parts. The stdlib keeps a
        // single-segment namespace ("Standard"); we intentionally split on
        // the LAST '.' so multi-segment namespaces like
        // "Standard.Collections.Generic" would still work if the stdlib ever
        // grows them.
        var lastDot = qualifiedName.LastIndexOf('.');
        if(lastDot <= 0 || lastDot >= qualifiedName.Length - 1)
        {
            throw new StdlibMissingException(
                qualifiedName,
                $"MIST_STDLIB_MISSING: stdlib type name '{qualifiedName}' is not fully qualified.");
        }

        var namespaceName = qualifiedName[..lastDot];
        var simpleName = qualifiedName[(lastDot + 1)..];

        // Walk directly to the target namespace scope. No file scope, no
        // using-directive, no scope chain.
        var namespaceScope = FindExistingNamespaceScope(globalScope, symbolTable, namespaceName) ?? throw new StdlibMissingException(
                qualifiedName,
                $"MIST_STDLIB_MISSING: Standard Library namespace '{namespaceName}' is not present in the semantic model (stdlib not loaded?).");

        // Look up the simple name among the namespace's direct members.
        // `Scope.Lookup` would walk up to the parent on a miss; here we
        // iterate members directly so a miss stays a miss (we must not fall
        // through to an unrelated global-scope symbol).
        foreach(var member in namespaceScope.Members)
        {
            if(member.Name != simpleName)
            {
                continue;
            }

            if(member.Kind is not SymbolKind.Class
                and not SymbolKind.Struct
                and not SymbolKind.Abstract)
            {
                continue;
            }

            if(member.DeclaredType is not IType declaredType)
            {
                continue;
            }

            // Legacy behavior: when no specific arity is requested, return the
            // first type-kind match.
            if(typeArgumentCount < 0)
            {
                return declaredType;
            }

            // Arity disambiguation: return the variant whose definition declares
            // exactly the requested number of type parameters (e.g., to pick the
            // matching member of the Standard.Func family's 17 same-named variants).
            // Callers that pass a specific arity (e.g., delegate projection) require
            // an exact-arity match for structural type identity, so a same-named
            // member of a different arity is intentionally not returned.
            if(GetTypeParameterCount(declaredType) == typeArgumentCount)
            {
                return declaredType;
            }
        }

        throw new StdlibMissingException(
            qualifiedName,
            $"MIST_STDLIB_MISSING: Standard Library type '{qualifiedName}' is not present in the semantic model.");
    }

    /// <summary>
    /// Returns the number of type parameters declared on a resolved <see cref="IType"/>.
    /// Used by the arity-aware stdlib lookup to disambiguate same-named generic families.
    /// </summary>
    private static int GetTypeParameterCount(IType type)
    {
        return type switch
        {
            ClassType ct => ct.TypeParameters.Count,
            StructType st => st.TypeParameters.Count,
            AbstractType it => it.TypeParameters.Count,
            _ => 0,
        };
    }

    /// <summary>
    /// Resolves a <see cref="PrimitiveTypeNode"/> (e.g., the AST node for the
    /// <c>int</c> keyword) to its corresponding Standard Library type,
    /// bypassing every scoping mechanism (file scope, <c>using</c> directives,
    /// user-declared types with matching simple names). Per Requirement 7.6
    /// this path is not overridable: the keyword <c>int</c> always resolves
    /// to the type named by <see cref="KeywordAliases.Map"/>
    /// (<c>Standard.Int32</c>), regardless of what else is in scope.
    ///
    /// <para>
    /// Task 31 of the Mist Standard Library spec flipped the primitive-
    /// type-reference path in <c>Pass2_ResolveTypes</c> to call this helper
    /// (with a fallback to the legacy <see cref="ResolvePrimitiveType"/>
    /// when no stdlib has been loaded, e.g., in unit tests that build a
    /// semantic model from a minimal AST). The fallback returns the same
    /// <see cref="IType"/> instance the compat-shim
    /// <c>PrimitiveType.Int</c> property would return (Task 32), so
    /// reference equality holds regardless of which path runs.
    /// </para>
    /// </summary>
    /// <param name="globalScope">The compilation's global scope.</param>
    /// <param name="symbolTable">The compilation's symbol table.</param>
    /// <param name="keyword">The primitive-keyword AST node to resolve.</param>
    internal static IType ResolvePrimitiveKeyword(
        Scope globalScope,
        SymbolTable symbolTable,
        PrimitiveTypeNode keyword)
    {
        // Extract the keyword lexeme (e.g., "int") using the existing
        // PrimitiveTypeNode → string mapping.
        var keywordText = FormatPrimitiveType(keyword);

        // Look it up in the single-source-of-truth Keyword_Alias_Mapping
        // (Requirement 7.5, Task 7).
        if(!KeywordAliases.Map.TryGetValue(keywordText, out var qualifiedName))
        {
            throw new StdlibMissingException(
                keywordText,
                $"MIST_STDLIB_MISSING: primitive keyword '{keywordText}' has no entry in KeywordAliases.Map.");
        }

        // Resolve the fully-qualified name directly against the stdlib
        // namespace — never through any scope chain or using-directive.
        return LookupQualifiedStdlibType(globalScope, symbolTable, qualifiedName);
    }

    /// <summary>
    /// Resolves the <c>void</c> keyword to its Standard Library type
    /// (<c>Standard.Void</c>), following the same pattern as
    /// <see cref="ResolvePrimitiveKeyword"/>. Bypasses all scoping.
    /// </summary>
    internal static IType ResolveVoidKeyword(Scope globalScope, SymbolTable symbolTable)
    {
        return LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Void");
    }

    /// <summary>
    /// Resolves the metatype <c>Type</c> to its Standard Library type
    /// (<c>Standard.Type</c>), following the same pattern as
    /// <see cref="ResolvePrimitiveKeyword"/>. Bypasses all scoping.
    /// </summary>
    internal static IType ResolveTypeKeyword(Scope globalScope, SymbolTable symbolTable)
    {
        return LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Type");
    }

    /// <summary>
    /// Constructs a <c>Task&lt;T&gt;</c> type by looking up the stdlib <c>Standard.Task</c>
    /// generic class and wrapping the given <paramref name="innerType"/> as its type argument.
    /// For <c>void</c> return types, the inner type is <c>Standard.Void</c> (producing
    /// <c>Task&lt;Void&gt;</c>). If the stdlib is not loaded (e.g., in unit tests), returns
    /// the <paramref name="innerType"/> unchanged as a graceful fallback.
    /// </summary>
    internal static IType ConstructTaskType(IType innerType, Scope fileScope, SymbolTable symbolTable)
    {
        var globalScope = FindGlobalScope(fileScope) ?? fileScope;
        try
        {
            var taskClass = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Task");
            return new ConstructedType(taskClass, new[] { innerType });
        }
        catch(StdlibMissingException)
        {
            // Stdlib not loaded (unit tests with minimal AST) — fall back gracefully.
            return innerType;
        }
    }

    /// <summary>
    /// Constructs a <c>ValueTask&lt;T&gt;</c> type from the given inner type.
    /// Falls back to returning the inner type if the stdlib is not loaded.
    /// </summary>
    internal static IType ConstructValueTaskType(IType innerType, Scope fileScope, SymbolTable symbolTable)
    {
        var globalScope = FindGlobalScope(fileScope) ?? fileScope;
        try
        {
            var valueTaskClass = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.ValueTask");
            return new ConstructedType(valueTaskClass, new[] { innerType });
        }
        catch(StdlibMissingException)
        {
            // Stdlib not loaded (unit tests with minimal AST) — fall back gracefully.
            return innerType;
        }
    }

    /// <summary>
    /// Resolves the return type of a block by finding return statements.
    /// Returns the type of the first return statement's value, or <c>VoidType</c> if no return value.
    /// </summary>
    private static IType ResolveBlockReturnType(
        BlockNode block,
        Scope currentScope,
        Scope fileScope,
        IType? enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Walk statements looking for return statements with values.
        foreach(var stmt in block.Statements)
        {
            if(stmt is ReturnStatementStatementNode returnStmt)
            {
                var returnNode = returnStmt.ReturnStatement;
                if(returnNode.Value is not null)
                {
                    // Resolve the return expression type.
                    var returnExprType = ResolveExpression(
                        returnNode.Value, currentScope, fileScope, enclosingType!, isStatic,
                        symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    return returnExprType;
                }
            }
        }

        // No return value found — assume void.
        return LegacyPrimitiveTypes.Void;
    }

    /// <summary>
    /// Returns <c>true</c> when the given type is a <c>Standard.Func&lt;...&gt;</c>
    /// constructed type (the Mist first-class-function type family).
    /// </summary>
    internal static bool IsFuncType(IType type)
    {
        return type is ConstructedType ct
            && ct.GenericDefinition is ClassType { DisplayName: "Func", ContainingNamespace: "Standard", IsBackendBacked: true };
    }

    /// <summary>
    /// If the type is <c>Expression&lt;Func&lt;...&gt;&gt;</c> (from System.Linq.Expressions),
    /// unwraps it and returns the inner Func/delegate type argument for lambda inference.
    /// Returns null if the type is not an Expression wrapper.
    /// </summary>
    private static IType? TryUnwrapExpressionFunc(IType type)
    {
        if(type is not ConstructedType ct)
        {
            return null;
        }

        // Check if the generic definition is "Expression" (from System.Linq.Expressions).
        if(ct.GenericDefinition is not ClassType classDef)
        {
            return null;
        }

        if(classDef.DisplayName != "Expression")
        {
            return null;
        }

        // Expression<T> has exactly one type argument — the delegate type.
        if(ct.TypeArguments.Count != 1)
        {
            return null;
        }

        var inner = ct.TypeArguments[0];

        // The inner type should be a Func-like type (stdlib Func or CLR Func/Action).
        if(IsFuncType(inner))
        {
            return inner;
        }

        // Also accept CLR Func/Action projected as ClassType.
        if(inner is ConstructedType innerCt
            && innerCt.GenericDefinition is ClassType { ContainingNamespace: "System" } innerClass
            && (innerClass.DisplayName.StartsWith("Func", StringComparison.Ordinal)
                || innerClass.DisplayName.StartsWith("Action", StringComparison.Ordinal)))
        {
            return inner;
        }

        return null;
    }

    /// <summary>
    /// Extracts the return type from a <c>Standard.Func&lt;T1, ..., TN, TResult&gt;</c>
    /// constructed type. The return type is always the last type argument.
    /// </summary>
    internal static IType GetFuncReturnType(ConstructedType funcType)
    {
        return funcType.TypeArguments[^1];
    }

    /// <summary>
    /// Constructs a <c>Standard.Func&lt;T1, ..., TN, TResult&gt;</c> type from a method
    /// symbol's parameter types and return type. Used for method group conversion: when
    /// a method identifier is used as a value (not invoked), its type is the equivalent
    /// Func type. Returns <c>null</c> if the stdlib is not loaded or the Func arity is
    /// not available.
    /// </summary>
    private static IType? ConstructFuncTypeFromMethod(Symbol methodSymbol, Scope fileScope, SymbolTable symbolTable)
    {
        // Get the method's parameter types.
        var paramTypes = ParameterSignature.Extract(methodSymbol, symbolTable);

        // Get the method's return type (effective return type visible to callers).
        var returnType = methodSymbol.DeclaredType;
        if(returnType is null or ErrorType)
        {
            return null;
        }

        // Construct the type arguments array: [paramTypes..., returnType].
        var arity = paramTypes.Count + 1;
        var typeArgs = new IType[arity];
        for(var i = 0; i < paramTypes.Count; i++)
        {
            typeArgs[i] = paramTypes[i];
        }

        typeArgs[^1] = returnType;

        // Look up Standard.Func with the matching arity.
        var globalScope = FindGlobalScope(fileScope) ?? fileScope;
        try
        {
            var funcDefinition = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Func", arity);
            return new ConstructedType(funcDefinition, typeArgs);
        }
        catch(StdlibMissingException)
        {
            // Stdlib not loaded (unit tests with minimal AST) — fall back gracefully.
            return null;
        }
    }

    /// <summary>
    /// Resolves a method group against a <see cref="DelegateType"/> target.
    /// Finds all overloads of the method name and selects the single overload whose
    /// signature is compatible with the delegate's <see cref="DelegateType.FuncSignature"/>.
    /// Emits <c>MIST_TC_0132</c> when zero overloads match and <c>MIST_TC_0133</c> when
    /// multiple overloads match (Requirements 2.7, 2.9).
    /// </summary>
    /// <returns>
    /// The constructed <c>func&lt;...&gt;</c> type of the selected overload, or <c>null</c>
    /// if no unique match could be determined (diagnostic already emitted).
    /// </returns>
    private static IType? ResolveMethodGroupForDelegateTarget(
        IdentifierExpressionPrimaryNode identifier,
        DelegateType delegateTarget,
        Scope currentScope,
        Scope fileScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var methodName = identifier.Name.Lexeme;
        var allSymbols = currentScope.LookupAll(methodName);

        // Collect all method overloads.
        var methodOverloads = new List<Symbol>();
        foreach(var sym in allSymbols)
        {
            if(sym is Symbol { Kind: SymbolKind.Method } methodSym)
            {
                methodOverloads.Add(methodSym);
            }
        }

        if(methodOverloads.Count == 0)
        {
            // No methods found — should not happen since we already know the
            // identifier resolved to a method, but fall through gracefully.
            return null;
        }

        // If only one overload exists, use it directly (no ambiguity possible).
        if(methodOverloads.Count == 1)
        {
            return ConstructFuncTypeFromMethod(methodOverloads[0], fileScope, symbolTable);
        }

        // Multiple overloads: find those whose signature is compatible with the delegate.
        var delegateFunc = delegateTarget.FuncSignature;
        var delegateParamCount = delegateFunc.TypeArguments.Count - 1; // Last type arg is return type.
        var compatibleOverloads = new List<Symbol>();

        foreach(var overload in methodOverloads)
        {
            var paramTypes = ParameterSignature.Extract(overload, symbolTable);
            var returnType = overload.DeclaredType;
            if(returnType is null or ErrorType)
            {
                continue;
            }

            // Check parameter count matches.
            if(paramTypes.Count != delegateParamCount)
            {
                continue;
            }

            // Check each parameter type matches the delegate's corresponding type.
            var compatible = true;
            for(var i = 0; i < paramTypes.Count; i++)
            {
                var delegateParamType = delegateFunc.TypeArguments[i];
                if(!TypesMatch(paramTypes[i], delegateParamType))
                {
                    compatible = false;
                    break;
                }
            }

            if(!compatible)
            {
                continue;
            }

            // Check return type matches.
            var delegateReturnType = delegateFunc.TypeArguments[^1];
            if(!TypesMatch(returnType, delegateReturnType))
            {
                continue;
            }

            compatibleOverloads.Add(overload);
        }

        if(compatibleOverloads.Count == 1)
        {
            // Exactly one compatible overload — select it.
            var selected = compatibleOverloads[0];
            return ConstructFuncTypeFromMethod(selected, fileScope, symbolTable);
        }

        if(compatibleOverloads.Count == 0)
        {
            // No overload matches the delegate signature.
            diagnostics.Add(MakeDiagnosticWithLocation(
                "MIST_TC_0132",
                DiagnosticSeverity.Error,
                $"No overload of '{methodName}' matches delegate type '{delegateTarget.DisplayName}'.",
                identifier,
                sourceText));
            return null;
        }

        // Multiple overloads match — ambiguous.
        diagnostics.Add(MakeDiagnosticWithLocation(
            "MIST_TC_0133",
            DiagnosticSeverity.Error,
            $"Multiple overloads of '{methodName}' match delegate type '{delegateTarget.DisplayName}'.",
            identifier,
            sourceText));
        return null;
    }

    /// <summary>
    /// Returns <c>true</c> when the given type is a <c>Standard.Task&lt;T&gt;</c>
    /// constructed type (the Mist concurrency primitive).
    /// </summary>
    internal static bool IsStandardTaskType(IType type)
    {
        return type is ConstructedType ct
            && ct.GenericDefinition is ClassType { DisplayName: "Task", ContainingNamespace: "Standard", IsBackendBacked: true };
    }

    /// <summary>
    /// Unwraps a <c>Task&lt;T&gt;</c> type to its inner type argument <c>T</c>.
    /// Returns the type unchanged if it is not a <c>Task&lt;T&gt;</c>.
    /// </summary>
    internal static IType UnwrapTaskType(IType type)
    {
        if(type is ConstructedType ct
            && ct.GenericDefinition is ClassType { DisplayName: "Task", ContainingNamespace: "Standard", IsBackendBacked: true }
            && ct.TypeArguments.Count > 0)
        {
            return ct.TypeArguments[0];
        }

        return type;
    }

    // (Task 49: PopulatePrimitiveTypeRegistry has been deleted along with
    // PrimitiveTypeRegistry. Stdlib types are resolved directly via
    // ResolvePrimitiveKeyword in Pass 2.)

    // ── Live task tracking helpers ───────────────────────────────────────

    /// <summary>
    /// Determines whether an expression statement represents a discarded async
    /// invocation — i.e., a method call whose result (Task&lt;T&gt;) is not
    /// assigned to a variable or explicitly awaited.
    /// </summary>
    private static bool IsDiscardedAsyncInvocation(ExpressionNode expr)
    {
        // Walk through the expression wrapper to the underlying unary node.
        // A discarded invocation is an expression statement where the expression is
        // a method call (postfix with invocation suffix) or an async functor expression.
        var assignment = expr.AsAssignmentOrNull();
        if(assignment is null)
        {
            return false; // Lambda form — not a discarded async invocation.
        }

        if(assignment.Value is not null)
        {
            return false; // It's an assignment, not a discarded expression.
        }

        var logicalOr = assignment.Target.Left;
        if(logicalOr.Right is not null)
        {
            return false;
        }

        var logicalAnd = logicalOr.Left;
        if(logicalAnd.Right is not null)
        {
            return false;
        }

        var equality = logicalAnd.Left;
        if(equality.Right is not null)
        {
            return false;
        }

        var relational = equality.Left;
        if(relational is not RelationalComparisonRelationalNode relComp)
        {
            return false;
        }

        if(relComp.Right is not null)
        {
            return false;
        }

        var additive = relComp.Left;
        if(additive.Right is not null)
        {
            return false;
        }

        var multiplicative = additive.Left;
        if(multiplicative.Right is not null)
        {
            return false;
        }

        var unary = multiplicative.Left;

        // Check if it's an async functor expression.
        if(unary is AsyncExpressionUnaryNode)
        {
            return true;
        }

        // Check if it's a postfix expression ending in an invocation.
        if(unary is PostfixExpressionUnaryNode postfix)
        {
            var suffixes = postfix.Primary.Suffix;
            if(suffixes.Length > 0 && suffixes[^1] is InvocationSuffixPostfixSuffixNode)
            {
                return true;
            }

            // Also check for method call suffix (obj.Method()).
            if(suffixes.Length > 0 && suffixes[^1] is MethodCallSuffixPostfixSuffixNode)
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Resolves a named type by searching the scope chain and imported namespaces.
    /// When <paramref name="typeArgumentCount"/> is &gt;= 0, the resolver disambiguates
    /// between types with the same name but different generic arities (e.g., <c>Foo</c>
    /// vs <c>Foo&lt;T&gt;</c> vs <c>Foo&lt;T1, T2&gt;</c>).
    /// </summary>
    private static IType ResolveNamedType(
        string typeName,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        int typeArgumentCount = -1)
    {
        // 1. Check well-known primitive types by name.
        var wellKnown = TryResolveWellKnownType(typeName);
        if(wellKnown is not null)
        {
            return wellKnown;
        }

        // 2. Search current scope → parent scopes (local → file → namespace → global).
        //    When typeArgumentCount >= 0, use arity-aware lookup to disambiguate overloads.
        var symbol = LookupTypeByArity(fileScope, typeName, typeArgumentCount);
        if(symbol is not null && (symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.TypeAlias || symbol.Kind == SymbolKind.Enum || symbol.Kind == SymbolKind.Newtype))
        {
            // For type aliases that haven't been resolved yet, trigger
            // recursive resolution so that cycle detection via
            // _typeAliasResolutionStack can fire (Requirement 5.4).
            if(symbol.Kind == SymbolKind.TypeAlias && symbol.DeclaredType is null)
            {
                var aliasNode = symbolTable.GetDeclaringNode(symbol) as TypeAliasDeclarationNode;
                if(aliasNode is not null)
                {
                    ResolveTypeAliasDeclaration(aliasNode, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                }
                else
                {
                    // Member-level type alias (e.g., public type ArrayBounds = ZeroOrPositiveInt and < Length;)
                    var memberAliasNode = symbolTable.GetDeclaringNode(symbol) as TypeAliasDeclarationNode;
                    if(memberAliasNode is not null)
                    {
                        // Resolve using the type scope (parent of the alias symbol's containing scope).
                        var typeScope = symbol.ContainingScope as Scope;
                        if(typeScope is not null)
                        {
                            ResolveMemberTypeAliasDeclaration(memberAliasNode, typeScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }
                }
            }
            // For newtypes that haven't been resolved yet, trigger resolution
            // so that forward references to newtypes work (newtypes declared
            // after the referencing class in the same namespace body).
            if(symbol.Kind == SymbolKind.Newtype && symbol.DeclaredType is null)
            {
                var newtypeNode = symbolTable.GetDeclaringNode(symbol) as NewtypeDeclarationNode;
                if(newtypeNode is not null)
                {
                    ResolveNewtypeDeclaration(newtypeNode, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);
                }
            }

            return symbol.DeclaredType ?? ErrorType.Instance;
        }

        // 3. Search imported namespaces from using declarations.
        var importedNamespaces = CollectImportedNamespaces(fileScope);

        // 3a. Search user-defined namespace scopes for the type.
        IType? userResolvedType = null;
        string? userResolvedNs = null;
        string? ambiguousNs = null;

        // Find the global scope by walking up from fileScope.
        var globalScope = FindGlobalScope(fileScope);

        foreach(var ns in importedNamespaces)
        {
            // Search user-defined namespace scopes.
            var nsScope = globalScope is not null
                ? FindExistingNamespaceScope(globalScope, symbolTable, ns)
                : null;

            if(nsScope is not null)
            {
                var nsMember = LookupTypeMemberByArity(nsScope, typeName, typeArgumentCount);
                if(nsMember is not null)
                {
                    if(userResolvedType is not null)
                    {
                        // Ambiguity: same type name found in multiple imported namespaces.
                        ambiguousNs = ns;
                    }
                    else
                    {
                        userResolvedType = nsMember.DeclaredType ?? ErrorType.Instance;
                        userResolvedNs = ns;
                    }
                }
            }
        }

        if(ambiguousNs is not null && userResolvedNs is not null)
        {
            diagnostics.Report(SemanticDiagnostics.AmbiguousType, default, sourceText?.Path ?? "<unknown>", (object)typeName, userResolvedNs, ambiguousNs);
            return ErrorType.Instance;
        }

        if(userResolvedType is not null)
        {
            return userResolvedType;
        }

        // 3b. Search ambient namespaces via ambient resolver.
        if(ambientTypeResolver is not null)
        {
            IType? ambientResolvedType = null;
            string? ambientResolvedNs = null;
            string? ambientAmbiguousNs = null;

            foreach(var ns in importedNamespaces)
            {
                // Try ambient resolver for each imported namespace, with arity when available.
                var resolvedType = typeArgumentCount >= 0
                    ? ambientTypeResolver.ResolveType(ns, typeName, typeArgumentCount)
                    : ambientTypeResolver.ResolveType(ns, typeName);
                if(resolvedType is not null)
                {
                    if(ambientResolvedType is not null)
                    {
                        // Ambiguity: same type name found in multiple imported ambient namespaces.
                        ambientAmbiguousNs = ns;
                    }
                    else
                    {
                        ambientResolvedType = resolvedType;
                        ambientResolvedNs = ns;
                    }
                }
            }

            if(ambientAmbiguousNs is not null && ambientResolvedNs is not null)
            {
                diagnostics.Report(SemanticDiagnostics.AmbiguousType, default, sourceText?.Path ?? "<unknown>", (object)typeName, ambientResolvedNs, ambientAmbiguousNs);
                return ErrorType.Instance;
            }

            if(ambientResolvedType is not null)
            {
                // Register the resolved ambient type in the scope hierarchy.
                RegisterAmbientTypeInScope(ambientResolvedType, typeName, fileScope, ambientTypeResolver);
                return ambientResolvedType;
            }

            // 3c. Fully-qualified namespace.type reference: if the typeName contains dots,
            // try splitting at each dot position (right to left) and check if the left
            // part is a known ambient namespace containing the right part as a type.
            // This handles cases like "Microsoft.AspNetCore.Http.QueryString" or
            // "Newtonsoft.Json.JsonConvert" without requiring a using directive.
            if(typeName.Contains('.'))
            {
                for(var dotIdx = typeName.LastIndexOf('.'); dotIdx > 0; dotIdx = typeName.LastIndexOf('.', dotIdx - 1))
                {
                    var candidateNs = typeName[..dotIdx];
                    var candidateType = typeName[(dotIdx + 1)..];

                    if(ambientTypeResolver.HasNamespace(candidateNs))
                    {
                        var resolved = typeArgumentCount >= 0
                            ? ambientTypeResolver.ResolveType(candidateNs, candidateType, typeArgumentCount)
                            : ambientTypeResolver.ResolveType(candidateNs, candidateType);
                        if(resolved is not null)
                        {
                            RegisterAmbientTypeInScope(resolved, candidateType, fileScope, ambientTypeResolver);
                            return resolved;
                        }
                    }
                }

                // 3d. Relative namespace resolution: if the dotted typeName's prefix is not
                // a fully-qualified namespace, try combining each imported namespace with the
                // prefix. This handles cases like "IO.MemoryStream" resolving to
                // "System.IO.MemoryStream" when "using System;" is present.
                for(var dotIdx = typeName.LastIndexOf('.'); dotIdx > 0; dotIdx = typeName.LastIndexOf('.', dotIdx - 1))
                {
                    var candidateNsSuffix = typeName[..dotIdx];
                    var candidateType = typeName[(dotIdx + 1)..];

                    foreach(var importedNs in importedNamespaces)
                    {
                        var combinedNs = importedNs + "." + candidateNsSuffix;
                        if(ambientTypeResolver.HasNamespace(combinedNs))
                        {
                            var resolved = typeArgumentCount >= 0
                                ? ambientTypeResolver.ResolveType(combinedNs, candidateType, typeArgumentCount)
                                : ambientTypeResolver.ResolveType(combinedNs, candidateType);
                            if(resolved is not null)
                            {
                                RegisterAmbientTypeInScope(resolved, candidateType, fileScope, ambientTypeResolver);
                                return resolved;
                            }
                        }
                    }
                }
            }
        }

        // 4. Not found → emit diagnostic, return ErrorType.
        diagnostics.Report(SemanticDiagnostics.UndefinedType, default, sourceText?.Path ?? "<unknown>", (object)typeName);

        return ErrorType.Instance;
    }

    /// <summary>
    /// Looks up a type symbol by name in the scope chain, disambiguating by arity when
    /// <paramref name="typeArgumentCount"/> is &gt;= 0. When arity is -1, falls back to
    /// the original first-match behavior for backward compatibility.
    /// </summary>
    private static ISymbol? LookupTypeByArity(Scope scope, string typeName, int typeArgumentCount)
    {
        if(typeArgumentCount < 0)
        {
            // Legacy behavior: return first match.
            return scope.Lookup(typeName);
        }

        // Arity-aware: collect all candidates and pick the one with matching arity.
        var candidates = scope.LookupAll(typeName);
        ISymbol? fallback = null;

        foreach(var candidate in candidates)
        {
            if(candidate.Kind is not (SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum or SymbolKind.Newtype))
            {
                continue;
            }

            var candidateArity = GetSymbolTypeParameterCount(candidate);
            if(candidateArity == typeArgumentCount)
            {
                return candidate;
            }

            // Keep the first type-kind match as fallback in case no arity match is found.
            fallback ??= candidate;
        }

        // If no exact arity match, return the first type-kind match (preserves existing
        // diagnostic behavior — ResolvePass2TypeArguments will emit MIST_ARITY_MISMATCH).
        return fallback;
    }

    /// <summary>
    /// Looks up a type member by name within a single scope (not walking parents),
    /// disambiguating by arity when <paramref name="typeArgumentCount"/> is &gt;= 0.
    /// Used for searching imported namespace scopes.
    /// </summary>
    private static ISymbol? LookupTypeMemberByArity(Scope scope, string typeName, int typeArgumentCount)
    {
        ISymbol? fallback = null;

        foreach(var member in scope.Members)
        {
            if(member.Name != typeName)
            {
                continue;
            }

            if(member.Kind is not (SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum or SymbolKind.Newtype))
            {
                continue;
            }

            if(typeArgumentCount < 0)
            {
                return member; // Legacy: first match.
            }

            var candidateArity = GetSymbolTypeParameterCount(member);
            if(candidateArity == typeArgumentCount)
            {
                return member;
            }

            fallback ??= member;
        }

        return typeArgumentCount >= 0 ? fallback : null;
    }

    /// <summary>
    /// Gets the number of type parameters declared on a type symbol.
    /// Works by inspecting the symbol's <see cref="ISymbol.DeclaredType"/>.
    /// </summary>
    private static int GetSymbolTypeParameterCount(ISymbol symbol)
    {
        var type = symbol.DeclaredType;
        if(type is null)
        {
            // Type not yet resolved (forward reference). Check the Symbol's TypeParameters list.
            if(symbol is Symbol s)
            {
                return s.TypeParameters.Count;
            }

            return 0;
        }

        return type switch
        {
            ClassType ct => ct.TypeParameters.Count,
            StructType st => st.TypeParameters.Count,
            AbstractType it => it.TypeParameters.Count,
            TypeAliasType at => at.TypeParameters.Count,
            _ => 0,
        };
    }

    /// <summary>
    /// Finds the global scope by walking up the parent chain from the given scope.
    /// The global scope is the one with no parent.
    /// </summary>
    private static Scope? FindGlobalScope(Scope scope)
    {
        IScope? current = scope;
        while(current is not null)
        {
            if(current is Scope s && s.Parent is null)
            {
                return s;
            }

            current = current.Parent;
        }

        return scope; // fallback
    }

    /// <summary>
    /// Finds the global scope by walking up the parent chain from an <see cref="IScope"/>.
    /// Used in Pass 1b constraint resolution where only an IScope is available.
    /// </summary>
    private static Scope? FindGlobalScopeFromIScope(IScope scope)
    {
        var current = scope;
        while(current is not null)
        {
            if(current is Scope s && s.Parent is null)
            {
                return s;
            }

            current = current.Parent;
        }

        return scope as Scope;
    }

    /// <summary>
    /// Substitutes type parameters in a type with the corresponding type arguments.
    /// If the type is a <see cref="TypeParameterType"/> that matches one of the
    /// type parameters, returns the corresponding type argument. Otherwise returns
    /// the type unchanged. Handles constructed types recursively.
    /// </summary>
    private static IType SubstituteTypeParameters(
        IType type,
        IReadOnlyList<IType> typeParameters,
        IReadOnlyList<IType> typeArguments)
    {
        if(type is TypeParameterType tpt)
        {
            for(var i = 0; i < typeParameters.Count; i++)
            {
                // Match by name and ordinal (not reference equality) because the
                // TypeProjector creates separate TypeParameterType instances for
                // type parameters in the type definition vs. in member signatures.
                if(typeParameters[i] is TypeParameterType tp
                    && tpt.Name == tp.Name
                    && tpt.Ordinal == tp.Ordinal)
                {
                    return i < typeArguments.Count ? typeArguments[i] : type;
                }
            }
            // Type parameter not in the substitution list — return as-is.
            return type;
        }

        if(type is ConstructedType ct)
        {
            var substitutedArgs = new List<IType>(ct.TypeArguments.Count);
            var anyChanged = false;
            foreach(var arg in ct.TypeArguments)
            {
                var substituted = SubstituteTypeParameters(arg, typeParameters, typeArguments);
                substitutedArgs.Add(substituted);
                if(!ReferenceEquals(substituted, arg))
                {
                    anyChanged = true;
                }
            }

            if(anyChanged)
            {
                return new ConstructedType(ct.GenericDefinition, substitutedArgs);
            }

            return type;
        }

        if(type is ArrayType arrayType)
        {
            var substitutedElement = SubstituteTypeParameters(arrayType.ElementType, typeParameters, typeArguments);
            if(!ReferenceEquals(substitutedElement, arrayType.ElementType))
            {
                return new ArrayType(substitutedElement);
            }

            return type;
        }

        if(type is SpanType spanType)
        {
            var substitutedElement = SubstituteTypeParameters(spanType.ElementType, typeParameters, typeArguments);
            if(!ReferenceEquals(substitutedElement, spanType.ElementType))
            {
                return new SpanType(substitutedElement, spanType.IsReadOnly);
            }

            return type;
        }

        return type;
    }

    /// <summary>
    /// Resolves type arguments on a type reference in Pass 2 context.
    /// Validates arity and emits diagnostics for mismatches and non-generic types.
    /// Returns a <see cref="ConstructedType"/> if the type is generic with matching arity,
    /// or the original type with diagnostics if there's an error.
    /// For type aliases, emits <c>MIST_SB_0063</c> on arity mismatch and returns
    /// the underlying type (transparent resolution).
    /// </summary>
    private static IType ResolvePass2TypeArguments(
        IType resolvedType,
        string typeName,
        TypeArgumentListNode typeArgList,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // If the resolved type is unknown, don't cascade errors.
        if(resolvedType is ErrorType)
        {
            return resolvedType;
        }

        var typeParams = GetTypeParameters(resolvedType);
        if(typeParams.Count == 0)
        {
            // The type is not generic — emit MIST_NOT_GENERIC.
            diagnostics.Add(MakeDiagnosticWithLocation(
                GenericsDiagnostics.NotGeneric.Id.Value,
                DiagnosticSeverity.Error,
                $"Type '{typeName}' is not generic and does not accept type arguments.",
                typeArgList,
                sourceText));
            return resolvedType;
        }

        // Resolve each type argument, handling dependent type argument disambiguation.
        var (resolvedTypeArgs, dependentArgs) = ResolvePass2TypeArgumentListWithDependents(
            typeArgList, typeParams, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        if(resolvedTypeArgs.Count != typeParams.Count)
        {
            // For type aliases, emit MIST_SB_0063 (Requirement 5.3).
            if(resolvedType is TypeAliasType aliasType)
            {
                diagnostics.Add(MakeDiagnosticWithLocation(
                    "MIST_SB_0063",
                    DiagnosticSeverity.Error,
                    $"Type alias '{aliasType.Name}' expects {typeParams.Count} type argument(s) but was given {resolvedTypeArgs.Count}.",
                    typeArgList,
                    sourceText));
                return ErrorType.Instance;
            }

            // Arity mismatch — emit MIST_ARITY_MISMATCH.
            diagnostics.Add(MakeDiagnosticWithLocation(
                GenericsDiagnostics.ArityMismatch.Id.Value,
                DiagnosticSeverity.Error,
                $"Type '{typeName}' expects {typeParams.Count} type argument(s) but received {resolvedTypeArgs.Count}.",
                typeArgList,
                sourceText));
            return ErrorType.Instance;
        }

        // For type aliases, substitute type arguments into the underlying type
        // and return the result (transparent resolution). This ensures that
        // `Box<int>` where `type Box<T> = GenericBox<T>` resolves to
        // `GenericBox<int>` (a ConstructedType with concrete type arguments).
        if(resolvedType is TypeAliasType alias)
        {
            var underlying = alias.UnderlyingType;
            // Substitute each type parameter with the corresponding type argument.
            return SubstituteTypeInMember(underlying, alias.TypeParameters, resolvedTypeArgs);
        }

        // For generic delegate types (e.g., Predicate<T>), construct a new DelegateType
        // with the concrete type arguments and a substituted FuncSignature. This ensures
        // that `System.Predicate<int>` resolves to DelegateType (not ConstructedType
        // wrapping a DelegateType), so assignability rules in IsAssignable can match it
        // directly as a DelegateType instance.
        if(resolvedType is DelegateType openDelegate)
        {
            // Substitute type parameters in the FuncSignature to produce the concrete signature.
            var substitutedSignature = SubstituteTypeInMember(openDelegate.FuncSignature, openDelegate.TypeParameters, resolvedTypeArgs);
            var concreteFuncSignature = substitutedSignature as ConstructedType ?? openDelegate.FuncSignature;

            return new DelegateType(
                clrFullName: openDelegate.ClrFullName,
                clrNamespace: openDelegate.ClrNamespace,
                clrSimpleName: openDelegate.ClrSimpleName,
                funcSignature: concreteFuncSignature,
                typeParameters: Array.Empty<IType>(),
                typeArguments: resolvedTypeArgs,
                memberScope: openDelegate.MemberScope);
        }

        return new ConstructedType(resolvedType, resolvedTypeArgs, dependentArgs);
    }

    /// <summary>
    /// Resolves a <see cref="TypeArgumentListNode"/> to a list of <see cref="IType"/> instances
    /// in Pass 2 context. Each type argument is resolved using the standard
    /// <see cref="ResolveTypeReference"/> method, supporting nested generics.
    /// Emits <c>MIST_UNDEFINED_TYPE_ARGUMENT</c> for unresolvable type arguments.
    /// </summary>
    private static IReadOnlyList<IType> ResolvePass2TypeArgumentList(
        TypeArgumentListNode typeArgList,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var resolvedArgs = new List<IType>();

        // Resolve the first type argument.
        var firstType = ResolvePass2SingleTypeArg(typeArgList.GetTypeReference(), fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
        resolvedArgs.Add(firstType);

        // Resolve the rest of the type arguments.
        foreach(var typeRef in typeArgList.GetTypeReferences())
        {
            var argType = ResolvePass2SingleTypeArg(typeRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
            resolvedArgs.Add(argType);
        }

        return resolvedArgs;
    }

    /// <summary>
    /// Resolves a <see cref="TypeArgumentListNode"/> to a list of <see cref="IType"/> instances
    /// and a parallel list of <see cref="DependentValueArgument"/> entries, performing
    /// disambiguation of bare identifiers and literal type arguments against the
    /// corresponding type parameters.
    /// <para>
    /// When the type parameter at a given position is a <see cref="DependentTypeParameterType"/>:
    /// <list type="bullet">
    ///   <item>Literal type arguments (integer, boolean, char, hex, binary, negated) are parsed
    ///         and converted to <see cref="DependentValueArgument"/> instances.</item>
    ///   <item>A bare identifier (<see cref="TypeReferenceTypeArgumentTypeArgumentNode"/> with a
    ///         simple <see cref="NamedSingleTypeRefSingleTypeRefNode"/>) is looked up in scope:
    ///         if it resolves to a const/dependent-parameter → dependent value argument;
    ///         if it resolves to a type → regular type argument (type mismatch handled later by type checker);
    ///         if unresolved → diagnostic emitted.</item>
    /// </list>
    /// </para>
    /// </summary>
    private static (IReadOnlyList<IType> TypeArgs, IReadOnlyList<DependentValueArgument?>? DependentArgs) ResolvePass2TypeArgumentListWithDependents(
        TypeArgumentListNode typeArgList,
        IReadOnlyList<IType> typeParams,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Collect all TypeArgumentNode entries in order.
        var argNodes = new List<TypeArgumentNode> { typeArgList.TypeArgument };
        foreach(var extra in typeArgList.TypeArguments)
        {
            argNodes.Add(extra);
        }

        var resolvedTypeArgs = new List<IType>(argNodes.Count);
        List<DependentValueArgument?>? dependentArgs = null;

        for(var i = 0; i < argNodes.Count; i++)
        {
            var argNode = argNodes[i];
            var correspondingParam = i < typeParams.Count ? typeParams[i] : null;
            var isDependentPosition = correspondingParam is DependentTypeParameterType;

            // Try to resolve as a dependent value argument if the position expects one.
            if(isDependentPosition)
            {
                var depParam = (DependentTypeParameterType)correspondingParam!;
                var depArg = TryResolveDependentValueArgument(argNode, depParam, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                if(depArg is not null)
                {
                    // Successfully resolved as a dependent value argument.
                    // Use the dependent parameter's value type as the type argument placeholder.
                    resolvedTypeArgs.Add(depParam.ValueType);
                    dependentArgs ??= new List<DependentValueArgument?>(new DependentValueArgument?[argNodes.Count]);
                    dependentArgs[i] = depArg;
                    continue;
                }
                // If TryResolveDependentValueArgument returned null, it means the argument
                // is a type reference (not a const/literal). Fall through to normal resolution.
            }

            // Normal type argument resolution (for regular type parameters or when
            // a dependent position has a type reference that isn't a const).
            if(argNode is TypeReferenceTypeArgumentTypeArgumentNode typeRefArg)
            {
                var resolved = ResolvePass2SingleTypeArg(typeRefArg.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                resolvedTypeArgs.Add(resolved);
            }
            else
            {
                // A literal type argument in a non-dependent position — this is an error
                // that will be caught by the type checker later. For now, use ErrorType.
                resolvedTypeArgs.Add(ErrorType.Instance);
            }
        }

        return (resolvedTypeArgs, dependentArgs);
    }

    /// <summary>
    /// Attempts to resolve a <see cref="TypeArgumentNode"/> as a <see cref="DependentValueArgument"/>
    /// for a dependent type parameter position. Returns <c>null</c> if the argument is a type
    /// reference (not a const or literal), indicating normal type argument resolution should proceed.
    /// </summary>
    private static DependentValueArgument? TryResolveDependentValueArgument(
        TypeArgumentNode argNode,
        DependentTypeParameterType depParam,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(argNode)
        {
            case IntegerLiteralTypeArgumentTypeArgumentNode intLit:
                {
                    var valueText = intLit.Literal.Lexeme;
                    if(long.TryParse(valueText, out var value))
                    {
                        return new DependentValueArgument(value, depParam.ValueType, valueText);
                    }

                    return new DependentValueArgument(0L, depParam.ValueType, valueText);
                }

            case NegatedIntegerTypeArgumentTypeArgumentNode negLit:
                {
                    var valueText = negLit.Literal.Lexeme;
                    if(long.TryParse(valueText, out var value))
                    {
                        return new DependentValueArgument(-value, depParam.ValueType, $"-{valueText}");
                    }

                    return new DependentValueArgument(0L, depParam.ValueType, $"-{valueText}");
                }

            case HexLiteralTypeArgumentTypeArgumentNode hexLit:
                {
                    var valueText = hexLit.Literal.Lexeme;
                    var hexStr = valueText.StartsWith("0x", StringComparison.OrdinalIgnoreCase)
                        ? valueText[2..] : valueText;
                    if(long.TryParse(hexStr, System.Globalization.NumberStyles.HexNumber, null, out var value))
                    {
                        return new DependentValueArgument(value, depParam.ValueType, valueText);
                    }

                    return new DependentValueArgument(0L, depParam.ValueType, valueText);
                }

            case BinaryLiteralTypeArgumentTypeArgumentNode binLit:
                {
                    var valueText = binLit.Literal.Lexeme;
                    var binStr = valueText.StartsWith("0b", StringComparison.OrdinalIgnoreCase)
                        ? valueText[2..] : valueText;
                    try
                    {
                        var value = Convert.ToInt64(binStr, 2);
                        return new DependentValueArgument(value, depParam.ValueType, valueText);
                    }
                    catch
                    {
                        return new DependentValueArgument(0L, depParam.ValueType, valueText);
                    }
                }

            case TrueLiteralTypeArgumentTypeArgumentNode:
                return new DependentValueArgument(true, depParam.ValueType, "true");

            case FalseLiteralTypeArgumentTypeArgumentNode:
                return new DependentValueArgument(false, depParam.ValueType, "false");

            case CharLiteralTypeArgumentTypeArgumentNode charLit:
                {
                    var valueText = charLit.Literal.Lexeme;
                    // Strip surrounding quotes to get the char value.
                    var charValue = valueText.Length >= 3 ? valueText[1] : '\0';
                    return new DependentValueArgument(charValue, depParam.ValueType, valueText);
                }

            case TypeReferenceTypeArgumentTypeArgumentNode typeRefArg:
                {
                    // Disambiguation: check if this is a bare identifier that resolves to a const.
                    if(typeRefArg.Type.First is NamedSingleTypeRefSingleTypeRefNode namedRef
                        && namedRef.TypeArgs is null
                        && namedRef.ArrayRank is null)
                    {
                        var argName = ExtractQualifiedName(namedRef.Name, sourceText);

                        // Don't treat well-known type names as const references.
                        if(TryResolveWellKnownType(argName) is not null)
                        {
                            return null; // It's a type, not a const.
                        }

                        // Look up in scope to disambiguate.
                        var symbol = fileScope.Lookup(argName);

                        if(symbol is not null)
                        {
                            // If the symbol's declared type is a DependentTypeParameterType,
                            // it's a forwarded dependent parameter (e.g., class Derived<N:int> : Base<N>).
                            if(symbol.DeclaredType is DependentTypeParameterType forwardedParam)
                            {
                                return new DependentValueArgument(argName, forwardedParam.ValueType, argName);
                            }

                            // If the symbol is a type (class, struct, abstract type, etc.), treat as regular type arg.
                            if(symbol.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum)
                            {
                                return null; // Fall through to normal type resolution.
                            }

                            // If the symbol is a property with a DependentTypeParameterType value type
                            // (generated implicit property for dependent parameters), treat as const ref.
                            if(symbol.Kind == SymbolKind.Property
                                && symbol is Symbol propSym
                                && propSym.PropertyMetadata is { IsStatic: true, HasGet: true, HasSet: false })
                            {
                                // This is likely a dependent parameter property — treat as forwarded.
                                return new DependentValueArgument(argName, symbol.DeclaredType ?? depParam.ValueType, argName);
                            }

                            // If the symbol is a field or local variable (potential const),
                            // treat as a dependent value argument reference.
                            if(symbol.Kind is SymbolKind.Field or SymbolKind.LocalVariable)
                            {
                                return new DependentValueArgument(argName, symbol.DeclaredType ?? depParam.ValueType, argName);
                            }
                        }

                        // Check if it resolves to a type via namespace imports before emitting diagnostic.
                        var importedNamespaces = CollectImportedNamespaces(fileScope);
                        var globalScope = FindGlobalScope(fileScope);
                        foreach(var ns in importedNamespaces)
                        {
                            var nsScope = globalScope is not null
                                ? FindExistingNamespaceScope(globalScope, symbolTable, ns)
                                : null;
                            if(nsScope is not null)
                            {
                                foreach(var member in nsScope.Members)
                                {
                                    if(member.Name == argName &&
                                        member.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.TypeAlias or SymbolKind.Enum)
                                    {
                                        return null; // It's a type from an imported namespace.
                                    }
                                }
                            }
                        }

                        // Check ambient resolver.
                        if(ambientTypeResolver is not null)
                        {
                            foreach(var ns in importedNamespaces)
                            {
                                if(ambientTypeResolver.ResolveType(ns, argName) is not null)
                                {
                                    return null; // It's an ambient type.
                                }
                            }
                        }

                        // Unresolved identifier in a dependent position — emit diagnostic.
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            GenericsDiagnostics.UndefinedTypeArgument.Id.Value,
                            DiagnosticSeverity.Error,
                            $"Type argument '{argName}' could not be resolved.",
                            typeRefArg,
                            sourceText));
                        return new DependentValueArgument(argName, depParam.ValueType, argName);
                    }

                    // Not a bare identifier (has type args or array rank) — treat as type reference.
                    return null;
                }

            default:
                return null;
        }
    }

    /// <summary>
    /// Resolves a single type argument in Pass 2 context.
    /// Uses <see cref="ResolveTypeReference"/> for full recursive resolution.
    /// Emits <c>MIST_UNDEFINED_TYPE_ARGUMENT</c> if the result is <see cref="ErrorType"/>
    /// and the type reference is a named type (not a primitive or void).
    /// </summary>
    private static IType ResolvePass2SingleTypeArg(
        TypeReferenceNode typeRef,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // For named type references, check if the name can be resolved before
        // calling the full ResolveTypeReference (which emits MIST_UNDEFINED_TYPE).
        // If it can't be resolved, emit MIST_UNDEFINED_TYPE_ARGUMENT instead.
        if(typeRef.First is NamedSingleTypeRefSingleTypeRefNode namedRef)
        {
            var argName = ExtractQualifiedName(namedRef.Name, sourceText);

            // Check if the name resolves to anything.
            var wellKnown = TryResolveWellKnownType(argName);
            if(wellKnown is null)
            {
                var symbol = fileScope.Lookup(argName);
                if(symbol is null || (symbol.Kind != SymbolKind.Class && symbol.Kind != SymbolKind.Struct && symbol.Kind != SymbolKind.Abstract && symbol.Kind != SymbolKind.TypeAlias && symbol.Kind != SymbolKind.Enum))
                {
                    // Check user-defined namespace scopes first.
                    var importedNamespaces = CollectImportedNamespaces(fileScope);
                    var globalScope = FindGlobalScope(fileScope);
                    var userResolved = false;

                    foreach(var ns in importedNamespaces)
                    {
                        var nsScope = globalScope is not null
                            ? FindExistingNamespaceScope(globalScope, symbolTable, ns)
                            : null;

                        if(nsScope is not null)
                        {
                            foreach(var member in nsScope.Members)
                            {
                                if(member.Name == argName &&
                                    (member.Kind == SymbolKind.Class || member.Kind == SymbolKind.Struct || member.Kind == SymbolKind.Abstract || member.Kind == SymbolKind.TypeAlias || member.Kind == SymbolKind.Enum))
                                {
                                    userResolved = true;
                                    break;
                                }
                            }

                            if(userResolved)
                            {
                                break;
                            }
                        }
                    }

                    // Check ambient resolver.
                    IType? ambientResolved = null;
                    if(!userResolved && ambientTypeResolver is not null)
                    {
                        foreach(var ns in importedNamespaces)
                        {
                            ambientResolved = ambientTypeResolver.ResolveType(ns, argName);
                            if(ambientResolved is not null)
                            {
                                break;
                            }
                        }
                    }

                    if(!userResolved && ambientResolved is null)
                    {
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            GenericsDiagnostics.UndefinedTypeArgument.Id.Value,
                            DiagnosticSeverity.Error,
                            $"Type argument '{argName}' could not be resolved.",
                            namedRef,
                            sourceText));
                        return ErrorType.Instance;
                    }
                }
            }
        }

        // Use the standard type reference resolution for full recursive support.
        return ResolveTypeReference(typeRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
    }

    /// <summary>
    /// Tries to resolve a well-known type by name (primitives, string, void).
    /// </summary>
    private static IType? TryResolveWellKnownType(string name)
    {
        return name switch
        {
            "int" => LegacyPrimitiveTypes.Int,
            "uint" => LegacyPrimitiveTypes.Uint,
            "long" => LegacyPrimitiveTypes.Long,
            "ulong" => LegacyPrimitiveTypes.Ulong,
            "short" => LegacyPrimitiveTypes.Short,
            "ushort" => LegacyPrimitiveTypes.Ushort,
            "byte" => LegacyPrimitiveTypes.Byte,
            "sbyte" => LegacyPrimitiveTypes.Sbyte,
            "float" => LegacyPrimitiveTypes.Float,
            "double" => LegacyPrimitiveTypes.Double,
            "decimal" => LegacyPrimitiveTypes.Decimal,
            "bool" => LegacyPrimitiveTypes.Bool,
            "char" => LegacyPrimitiveTypes.Char,
            "string" => LegacyPrimitiveTypes.String,
            "regex" => LegacyPrimitiveTypes.Regex,
            "void" => LegacyPrimitiveTypes.Void,
            "Void" => LegacyPrimitiveTypes.Void,
            "object" => UnknownType.Instance,
            _ => null,
        };
    }

    /// <summary>
    /// Creates a new scope that layers the type parameters from <paramref name="typeScope"/>
    /// on top of <paramref name="fileScope"/>. This ensures that type parameter names
    /// resolve to the correct TypeParameterType instance for the current generic
    /// declaration, without polluting the shared file scope with type parameters
    /// from multiple generic types.
    /// </summary>
    private static Scope CreateTypeParameterScope(Scope typeScope, Scope fileScope)
    {
        var hasTypeParams = false;
        var hasNestedTypes = false;
        var hasAssociatedTypeSlots = false;
        var hasResolvedMemberTypeAliases = false;
        foreach(var member in typeScope.Members)
        {
            if(member.DeclaredType is TypeParameterType or DependentTypeParameterType)
            {
                hasTypeParams = true;
            }
            else if(member.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.Enum)
            {
                hasNestedTypes = true;
            }
            else if(member.DeclaredType is AssociatedTypeSlotType)
            {
                hasAssociatedTypeSlots = true;
            }
            else if(member.Kind == SymbolKind.TypeAlias && member.DeclaredType is not null)
            {
                // Only include member type aliases that have already been resolved.
                // Unresolved aliases (DeclaredType == null) would trigger on-demand
                // resolution which can cause ordering issues.
                hasResolvedMemberTypeAliases = true;
            }
        }

        if(!hasTypeParams && !hasNestedTypes && !hasAssociatedTypeSlots && !hasResolvedMemberTypeAliases)
        {
            return fileScope;
        }

        var scope = new Scope(parent: fileScope);
        foreach(var member in typeScope.Members)
        {
            if(member.DeclaredType is TypeParameterType or DependentTypeParameterType)
            {
                scope.AddMember(member);
            }
            else if(member.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract or SymbolKind.Enum)
            {
                scope.AddMember(member);
            }
            else if(member.DeclaredType is AssociatedTypeSlotType)
            {
                scope.AddMember(member);
            }
            else if(member.Kind == SymbolKind.TypeAlias && member.DeclaredType is not null)
            {
                scope.AddMember(member);
            }
        }

        return scope;
    }

    /// <summary>
    /// Collects all imported namespaces from the scope chain.
    /// </summary>
    private static List<string> CollectImportedNamespaces(Scope scope)
    {
        var namespaces = new List<string>();
        IScope? current = scope;
        while(current is not null)
        {
            if(current is Scope s)
            {
                foreach(var ns in s.ImportedNamespaces)
                {
                    if(!namespaces.Contains(ns))
                    {
                        namespaces.Add(ns);
                    }
                }
            }

            current = current.Parent;
        }

        return namespaces;
    }

    /// <summary>
    /// Registers an ambient type and its members in the scope hierarchy.
    /// </summary>
    private static void RegisterAmbientTypeInScope(
        IType type,
        string typeName,

        Scope fileScope,
        IAmbientTypeResolver ambientTypeResolver)
    {
        // Check if already registered in the scope.
        var existing = fileScope.Lookup(typeName);
        if(existing is not null && (existing.Kind == SymbolKind.Class || existing.Kind == SymbolKind.Struct || existing.Kind == SymbolKind.Abstract))
        {
            return; // Already registered.
        }

        // Create a type symbol with SymbolOrigin.Backend.
        var kind = type is ClassType ? SymbolKind.Class : type is AbstractType ? SymbolKind.Abstract : SymbolKind.Struct;
        var typeSymbol = new Symbol(typeName, kind, SymbolOrigin.Backend, fileScope, type, declarationSpan: null);
        fileScope.AddMember(typeSymbol);

        // Register members in the type's member scope.
        var members = ambientTypeResolver.GetMembers(type);
        if(type is ClassType ct && ct.MemberScope is Scope memberScope)
        {
            foreach(var member in members)
            {
                // Only add if not already present.
                if(memberScope.Lookup(member.Name) is null)
                {
                    memberScope.AddMember(member);
                }
            }
        }
        else if(type is StructType st && st.MemberScope is Scope structMemberScope)
        {
            foreach(var member in members)
            {
                if(structMemberScope.Lookup(member.Name) is null)
                {
                    structMemberScope.AddMember(member);
                }
            }
        }
    }

    // ─── Property Assignment Value Resolution ────────────────────────────

    /// <summary>
    /// Resolves the value expression within a PropertyAssignment node,
    /// handling both named property assignments and collection element assignments.
    /// </summary>
    private static void ResolvePropertyAssignmentValue(
        PropertyAssignmentNode assignment,
        Scope currentScope,
        Scope fileScope,
        IType? enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var valueExpr = assignment switch
        {
            NamedPropertyAssignmentPropertyAssignmentNode named => named.Value,
            CollectionElementAssignmentPropertyAssignmentNode element => element.Value,
            _ => null!
        };

        if(valueExpr is not null)
        {
            _ = ResolveExpression(valueExpr, currentScope, fileScope, enclosingType!, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    // ─── Expression Resolution ───────────────────────────────────────────

    /// <summary>
    /// Resolves the type of an expression and records it in the expression type map.
    /// Returns the resolved type.
    /// </summary>
    private static IType ResolveExpression(
        ExpressionNode expr,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // ExpressionNode is now an abstract base split into a lambda form and an
        // assignment form. Dispatch on the subtype.
        var type = expr switch
        {
            AssignmentFormExpressionNode assignmentForm => ResolveAssignment(assignmentForm.Assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics),
            LambdaFormExpressionNode lambdaForm => ResolveLambdaExpression(lambdaForm.Lambda, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics),
            _ => throw new InvalidOperationException(
                                $"Unknown ExpressionNode variant: {expr.GetType().Name}"),
        };
        expressionTypes[expr] = type;
        return type;
    }

    /// <summary>
    /// Resolves a lambda expression's type using target-type-driven inference.
    /// When a target Func type is available (from a typed variable declaration or
    /// a Func-typed parameter), infers implicit parameter types from the target
    /// type's type arguments, creates a child scope with the parameters registered,
    /// and resolves the lambda body in that scope.
    /// </summary>
    private static IType ResolveLambdaExpression(
        LambdaExpressionNode lambda,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Check if a target type is available from the enclosing context.
        var targetType = lambdaTargetType;

        // When the target type is a DelegateType, extract its FuncSignature for inference.
        // The lambda's parameter types come from the FuncSignature's type arguments.
        ConstructedType? funcCt = null;
        if(targetType is not null and DelegateType delegateTarget)
        {
            funcCt = delegateTarget.FuncSignature;
        }
        else if(targetType is not null && IsFuncType(targetType) && targetType is ConstructedType directFuncCt)
        {
            funcCt = directFuncCt;
        }
        else if(targetType is not null && targetType is ConstructedType clrDelegateCt
            && clrDelegateCt.GenericDefinition is ClassType { ContainingNamespace: "System" } clrDelegateClass
            && (clrDelegateClass.DisplayName.StartsWith("Action", StringComparison.Ordinal)
                || clrDelegateClass.DisplayName.StartsWith("Func", StringComparison.Ordinal)))
        {
            // CLR Action<T>/Func<T> types that were projected as plain ClassType rather than
            // stdlib Func (due to projection ordering). Treat type arguments as parameter types
            // (for Action, all args are params; for Func, last arg is return type).
            funcCt = clrDelegateCt;
        }

        if(funcCt is not null)
        {
            // Target-type-driven inference: extract parameter types from the Func/Action
            // type arguments. For Standard.Func, all but the last are params (last is return type).
            // For raw CLR Action (projected as ClassType), ALL type args are params.
            var typeArgs = funcCt.TypeArguments;
            List<IType> paramTypes;
            IType returnType;

            var isClrAction = funcCt.GenericDefinition is ClassType { ContainingNamespace: "System" } clrActionClass
                && clrActionClass.DisplayName.StartsWith("Action", StringComparison.Ordinal);

            if(isClrAction)
            {
                // CLR Action<T1, ..., TN>: all type args are parameter types, return is void.
                paramTypes = typeArgs.ToList();
                returnType = UnknownType.Instance; // void-like
            }
            else
            {
                // Standard.Func<T1, ..., TN, TResult>: all but last are params, last is return.
                paramTypes = typeArgs.Count > 1
                    ? typeArgs.Take(typeArgs.Count - 1).ToList()
                    : new List<IType>();
                returnType = GetFuncReturnType(funcCt);
            }

            // Create a child scope for the lambda body.
            var lambdaScope = new Scope(parent: currentScope);

            // Register lambda parameters in the child scope.
            RegisterLambdaParameters(lambda, paramTypes, lambdaScope, fileScope, symbolTable, ambientTypeResolver, sourceText, diagnostics);

            // Set async context if the lambda has the async modifier.
            var isAsync = IsAsyncLambda(lambda);
            var previousAsyncContext = isInAsyncContext;
            if(isAsync)
            {
                isInAsyncContext = true;
            }

            try
            {
                // Resolve the lambda body in the child scope.
                ResolveLambdaBody(lambda, lambdaScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            }
            finally
            {
                isInAsyncContext = previousAsyncContext;
            }

            // Generic type argument inference (Requirement 6.8): when the target Func type
            // contains unresolved type parameters (e.g., Func<int, T> from a generic method),
            // infer the actual return type from the lambda body and construct a concrete Func
            // type. This allows the TypeArgumentInferenceEngine to unify the method's parameter
            // type (Func<int, T>) with the lambda's concrete type (Func<int, string>) and
            // deduce T = string.
            //
            // Also infer when the lambda has explicitly-typed parameters that differ from
            // the target delegate's parameter types (e.g., ASP.NET Core minimal API lambdas
            // with DI-injected parameters like IOptions<T>). In this case the lambda's
            // actual signature takes precedence over the target delegate.
            var hasExplicitlyTypedParams = HasExplicitlyTypedParameters(lambda);
            if(ContainsTypeParameter(returnType) || hasExplicitlyTypedParams)
            {
                var inferredReturnType = InferLambdaBodyReturnType(lambda, expressionTypes, fileScope, symbolTable, isAsync);
                if(inferredReturnType is not null and not ErrorType and not UnknownType)
                {
                    // When explicitly-typed params are present, use the resolved param
                    // types from the lambda scope instead of the target delegate's types.
                    var actualParamTypes = hasExplicitlyTypedParams
                        ? CollectLambdaResolvedParamTypes(lambda, lambdaScope)
                        : paramTypes;

                    // Construct a concrete Func type from the actual param types and inferred return type.
                    var concreteArity = actualParamTypes.Count + 1;
                    var concreteTypeArgs = new IType[concreteArity];
                    for(var i = 0; i < actualParamTypes.Count; i++)
                    {
                        concreteTypeArgs[i] = actualParamTypes[i];
                    }

                    concreteTypeArgs[^1] = inferredReturnType;

                    try
                    {
                        var globalScopeForFunc = FindGlobalScope(fileScope) ?? fileScope;
                        var funcDefinition = LookupQualifiedStdlibType(globalScopeForFunc, symbolTable, "Standard.Func", concreteArity);
                        return new ConstructedType(funcDefinition, concreteTypeArgs);
                    }
                    catch(StdlibMissingException)
                    {
                        // Stdlib not loaded — fall back to target type.
                    }
                }
            }

            // The lambda's type is the equivalent Func type (even when targeting a DelegateType,
            // the lambda is typed as func<...> — conversion to the delegate happens at the call site).
            // When funcCt came from a CLR Action/Func ClassType (not stdlib Func), construct
            // the proper stdlib Func type so the overload resolver can match it.
            if(!IsFuncType(funcCt))
            {
                // Construct stdlib Func<paramTypes..., returnType> from the extracted types.
                var funcArity = paramTypes.Count + 1;
                var funcTypeArgs = new IType[funcArity];
                for(var pi = 0; pi < paramTypes.Count; pi++)
                {
                    funcTypeArgs[pi] = paramTypes[pi];
                }

                try
                {
                    var globalScope = FindGlobalScope(fileScope) ?? fileScope;

                    if(isClrAction)
                    {
                        // CLR Action: return type is Void.
                        var voidType = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Void");
                        funcTypeArgs[^1] = voidType;
                    }
                    else
                    {
                        // CLR Func: infer return type from lambda body.
                        var inferredReturn = InferLambdaBodyReturnType(lambda, expressionTypes, fileScope, symbolTable, false);
                        if(inferredReturn is not null and not ErrorType and not UnknownType)
                        {
                            funcTypeArgs[^1] = inferredReturn;
                        }
                        else
                        {
                            // Fallback to the target Func's last type arg (may contain type params).
                            funcTypeArgs[^1] = returnType;
                        }
                    }

                    var funcDefinition = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Func", funcArity);
                    return new ConstructedType(funcDefinition, funcTypeArgs);
                }
                catch(StdlibMissingException)
                {
                    return funcCt;
                }
            }

            return funcCt;
        }

        // No target type available (or target type is not a Func type / DelegateType).
        // Attempt explicit-parameter inference: if the lambda has all explicitly-typed
        // parameters, resolve their type annotations, infer the return type from the
        // body, and construct the Func type.
        return ResolveExplicitParamLambda(lambda, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Handles the case where a lambda has explicitly-typed parameters but no target
    /// Func type (e.g., <c>var f = (int x) => x + 1;</c>). Resolves parameter type
    /// annotations, infers the return type from the body, and constructs the Func type.
    /// Returns <see cref="UnknownType"/> if the lambda does not have all explicitly-typed params.
    /// </summary>
    private static IType ResolveExplicitParamLambda(
        LambdaExpressionNode lambda,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Get the parameter list from the lambda.
        var paramList = lambda switch
        {
            ExpressionLambdaLambdaExpressionNode exprLambda => exprLambda.Params,
            BlockLambdaLambdaExpressionNode blockLambda => blockLambda.Params,
            _ => null,
        };

        // Single implicit param (e.g., x => x + 1) cannot be inferred without a target type.
        if(paramList is null or SingleImplicitParamLambdaParameterListNode)
        {
            return UnknownType.Instance;
        }

        if(paramList is not ParenthesizedLambdaParamsLambdaParameterListNode parenParams)
        {
            return UnknownType.Instance;
        }

        // Collect all param nodes.
        var paramNodes = new List<LambdaParamNode>();
        if(parenParams.Params is not null)
        {
            paramNodes.Add(parenParams.Params.LambdaParam);
            paramNodes.AddRange(parenParams.Params.LambdaParams);
        }

        // Check that ALL parameters are explicitly typed.
        foreach(var paramNode in paramNodes)
        {
            if(paramNode is not TypedLambdaParamLambdaParamNode)
            {
                return UnknownType.Instance;
            }
        }

        // All parameters are explicitly typed — resolve their type annotations.
        var lambdaScope = new Scope(parent: currentScope);
        var paramTypes = new List<IType>(paramNodes.Count);

        foreach(var paramNode in paramNodes)
        {
            var typed = (TypedLambdaParamLambdaParamNode)paramNode;
            var paramType = ResolveTypeReference(typed.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
            paramTypes.Add(paramType);

            var paramName = typed.Name.Lexeme;
            var paramSpan = ToMistSourceSpan(typed.Name.Span);
            var paramSymbol = new Symbol(paramName, SymbolKind.Parameter, SymbolOrigin.UserCode, lambdaScope, paramType, paramSpan);
            lambdaScope.AddMember(paramSymbol);
            symbolTable.Register(paramSymbol, typed);
        }

        // Resolve the lambda body and infer the return type.
        // Set async context if the lambda has the async modifier.
        var isAsync = IsAsyncLambda(lambda);
        var previousAsyncContext = isInAsyncContext;
        if(isAsync)
        {
            isInAsyncContext = true;
        }

        IType returnType;
        try
        {
            switch(lambda)
            {
                case ExpressionLambdaLambdaExpressionNode exprLambda:
                    {
                        // Expression body: the return type is the expression's resolved type.
                        returnType = ResolveExpression(exprLambda.Body, lambdaScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        break;
                    }

                case BlockLambdaLambdaExpressionNode blockLambda:
                    {
                        // Block body: resolve the block, then find all return statements
                        // and determine the common return type.
                        ResolveBlock(blockLambda.Body, lambdaScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                        // Collect return types from the block's return statements.
                        var returnTypes = new List<IType>();
                        CollectReturnTypes(blockLambda.Body, expressionTypes, returnTypes);

                        if(returnTypes.Count == 0)
                        {
                            // No return statements with values — void lambda.
                            var globalScope = FindGlobalScope(fileScope) ?? fileScope;
                            try
                            {
                                returnType = ResolveVoidKeyword(globalScope, symbolTable);
                            }
                            catch(StdlibMissingException)
                            {
                                returnType = LegacyPrimitiveTypes.Void;
                            }
                        }
                        else if(returnTypes.Count == 1)
                        {
                            returnType = returnTypes[0];
                        }
                        else
                        {
                            // Multiple return statements — find the common type.
                            var firstType = returnTypes[0];
                            var allSame = true;
                            for(var i = 1; i < returnTypes.Count; i++)
                            {
                                if(!ReferenceEquals(firstType, returnTypes[i])
                                    && firstType.DisplayName != returnTypes[i].DisplayName)
                                {
                                    allSame = false;
                                    break;
                                }
                            }

                            returnType = allSame ? firstType : ErrorType.Instance;
                        }

                        break;
                    }

                default:
                    return UnknownType.Instance;
            }
        }
        finally
        {
            isInAsyncContext = previousAsyncContext;
        }

        // For async lambdas, wrap the inferred return type in Task<T>.
        if(isAsync)
        {
            returnType = ConstructTaskType(returnType, fileScope, symbolTable);
        }

        // Construct the Func type: Func<paramType1, ..., paramTypeN, returnType>.
        var arity = paramTypes.Count + 1;
        var typeArgs = new IType[arity];
        for(var i = 0; i < paramTypes.Count; i++)
        {
            typeArgs[i] = paramTypes[i];
        }

        typeArgs[^1] = returnType;

        var globalScopeForFunc = FindGlobalScope(fileScope) ?? fileScope;
        try
        {
            var funcDefinition = LookupQualifiedStdlibType(globalScopeForFunc, symbolTable, "Standard.Func", arity);
            return new ConstructedType(funcDefinition, typeArgs);
        }
        catch(StdlibMissingException)
        {
            // Stdlib not loaded (unit tests with minimal AST) — fall back gracefully.
            return UnknownType.Instance;
        }
    }

    /// <summary>
    /// Recursively collects the types of all return statement values within a block.
    /// Only collects returns with a value expression (bare <c>return;</c> is treated as void).
    /// Does not descend into nested lambdas (their returns belong to the inner lambda).
    /// </summary>
    private static void CollectReturnTypes(
        BlockNode block,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        List<IType> returnTypes)
    {
        foreach(var stmt in block.Statements)
        {
            CollectReturnTypesFromStatement(stmt, expressionTypes, returnTypes);
        }
    }

    /// <summary>
    /// Collects return types from a single statement, recursing into control-flow
    /// blocks (if/else, while, for, etc.) but NOT into nested lambdas.
    /// </summary>
    private static void CollectReturnTypesFromStatement(
        StatementNode stmt,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        List<IType> returnTypes)
    {
        switch(stmt)
        {
            case ReturnStatementStatementNode returnStmt:
                if(returnStmt.ReturnStatement.Value is not null
                    && expressionTypes.TryGetValue(returnStmt.ReturnStatement.Value, out var returnValueType))
                {
                    returnTypes.Add(returnValueType);
                }

                break;

            case IfStatementStatementNode ifStmt:
                CollectReturnTypesFromBlock(ifStmt.IfStatement.ThenBranch, expressionTypes, returnTypes);
                if(ifStmt.IfStatement.ElseBranch is not null)
                {
                    CollectReturnTypesFromElse(ifStmt.IfStatement.ElseBranch, expressionTypes, returnTypes);
                }

                break;

            case WhileStatementStatementNode whileStmt:
                CollectReturnTypesFromBlock(whileStmt.WhileStatement.Body, expressionTypes, returnTypes);
                break;

            case ForStatementStatementNode forStmt:
                CollectReturnTypesFromBlock(forStmt.ForStatement.Body, expressionTypes, returnTypes);
                break;

            case ForeachStatementStatementNode foreachStmt:
                CollectReturnTypesFromBlock(foreachStmt.ForeachStatement.GetBody(), expressionTypes, returnTypes);
                break;

            case ReadonlyBlockStatementStatementNode readonlyBlockStmt:
                CollectReturnTypesFromBlock(readonlyBlockStmt.ReadonlyBlock.Body, expressionTypes, returnTypes);
                break;

            case BlockStatementStatementNode blockStmt:
                CollectReturnTypesFromBlock(blockStmt.BlockStatement, expressionTypes, returnTypes);
                break;

            case WithBlockStatementStatementNode withBlockStmt:
                CollectReturnTypesFromBlock(withBlockStmt.WithBlockStatement.Body, expressionTypes, returnTypes);
                break;
        }
    }

    /// <summary>
    /// Collects return types from a block node.
    /// </summary>
    private static void CollectReturnTypesFromBlock(
        BlockNode block,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        List<IType> returnTypes)
    {
        foreach(var stmt in block.Statements)
        {
            CollectReturnTypesFromStatement(stmt, expressionTypes, returnTypes);
        }
    }

    /// <summary>
    /// Collects return types from an else clause (which may be an else-if chain).
    /// </summary>
    private static void CollectReturnTypesFromElse(
        ElseClauseNode elseClause,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        List<IType> returnTypes)
    {
        switch(elseClause)
        {
            case ElseBlockElseClauseNode elseBlock:
                CollectReturnTypes(elseBlock.ElseBlock, expressionTypes, returnTypes);
                break;

            case ElseIfElseClauseNode elseIf:
                CollectReturnTypesFromBlock(elseIf.ElseIf.ThenBranch, expressionTypes, returnTypes);
                if(elseIf.ElseIf.ElseBranch is not null)
                {
                    CollectReturnTypesFromElse(elseIf.ElseIf.ElseBranch, expressionTypes, returnTypes);
                }

                break;
        }
    }

    /// <summary>
    /// Registers lambda parameters as symbols in the given scope. For implicitly-typed
    /// parameters, uses the corresponding type from the target Func type's type arguments.
    /// For explicitly-typed parameters, resolves the type annotation.
    /// </summary>
    private static void RegisterLambdaParameters(
        LambdaExpressionNode lambda,
        List<IType> paramTypes,
        Scope lambdaScope,
        Scope fileScope,
        SymbolTable symbolTable,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Get the parameter list from the lambda (both expression and block lambdas
        // share the same Params property via the grammar structure).
        var paramList = lambda switch
        {
            ExpressionLambdaLambdaExpressionNode exprLambda => exprLambda.Params,
            BlockLambdaLambdaExpressionNode blockLambda => blockLambda.Params,
            _ => null,
        };

        if(paramList is null)
        {
            return;
        }

        switch(paramList)
        {
            case SingleImplicitParamLambdaParameterListNode singleParam:
                {
                    // Single implicit param (e.g., x => x + 1).
                    // Infer type from the first target type argument.
                    var paramType = paramTypes.Count > 0 ? paramTypes[0] : UnknownType.Instance;
                    var paramName = singleParam.Name.Lexeme;
                    var paramSpan = ToMistSourceSpan(singleParam.Name.Span);
                    var paramSymbol = new Symbol(paramName, SymbolKind.Parameter, SymbolOrigin.UserCode, lambdaScope, paramType, paramSpan);
                    lambdaScope.AddMember(paramSymbol);
                    symbolTable.Register(paramSymbol, singleParam);
                    break;
                }

            case ParenthesizedLambdaParamsLambdaParameterListNode parenParams:
                {
                    if(parenParams.Params is null)
                    {
                        // Zero-parameter lambda: () => expr
                        break;
                    }

                    // Collect all param nodes (first + rest).
                    var paramNodes = new List<LambdaParamNode> { parenParams.Params.LambdaParam };
                    paramNodes.AddRange(parenParams.Params.LambdaParams);

                    for(var i = 0; i < paramNodes.Count; i++)
                    {
                        var paramNode = paramNodes[i];
                        switch(paramNode)
                        {
                            case UntypedLambdaParamLambdaParamNode untyped:
                                {
                                    // Infer type from the target Func type argument at this position.
                                    var paramType = i < paramTypes.Count ? paramTypes[i] : UnknownType.Instance;
                                    var paramName = untyped.Name.Lexeme;
                                    var paramSpan = ToMistSourceSpan(untyped.Name.Span);
                                    var paramSymbol = new Symbol(paramName, SymbolKind.Parameter, SymbolOrigin.UserCode, lambdaScope, paramType, paramSpan);
                                    lambdaScope.AddMember(paramSymbol);
                                    symbolTable.Register(paramSymbol, untyped);
                                    break;
                                }

                            case TypedLambdaParamLambdaParamNode typed:
                                {
                                    // Explicitly-typed param — resolve the type annotation.
                                    // The explicit annotation takes precedence over the target
                                    // delegate's parameter type. This enables ASP.NET Core minimal
                                    // API patterns where typed lambda parameters are DI-injected
                                    // services, not necessarily matching the delegate signature.
                                    var paramType = ResolveTypeReference(typed.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                    if(paramType is ErrorType or UnknownType)
                                    {
                                        // Resolution failed — fall back to the target type.
                                        paramType = i < paramTypes.Count ? paramTypes[i] : UnknownType.Instance;
                                    }

                                    var paramName = typed.Name.Lexeme;
                                    var paramSpan = ToMistSourceSpan(typed.Name.Span);
                                    var paramSymbol = new Symbol(paramName, SymbolKind.Parameter, SymbolOrigin.UserCode, lambdaScope, paramType, paramSpan);
                                    lambdaScope.AddMember(paramSymbol);
                                    symbolTable.Register(paramSymbol, typed);
                                    break;
                                }
                        }
                    }

                    break;
                }
        }
    }

    /// <summary>
    /// Returns <c>true</c> when the lambda has the <c>async</c> modifier.
    /// </summary>
    private static bool IsAsyncLambda(LambdaExpressionNode lambda)
    {
        var modifiers = lambda switch
        {
            ExpressionLambdaLambdaExpressionNode exprLambda => exprLambda.Modifiers,
            BlockLambdaLambdaExpressionNode blockLambda => blockLambda.Modifiers,
            _ => ImmutableArray<LambdaModifierNode>.Empty,
        };

        return modifiers.Any(m => m is AsyncLambdaModifierLambdaModifierNode);
    }

    /// <summary>
    /// Returns <c>true</c> if the lambda has all explicitly-typed parameters.
    /// </summary>
    private static bool HasExplicitlyTypedParameters(LambdaExpressionNode lambda)
    {
        var paramList = lambda switch
        {
            ExpressionLambdaLambdaExpressionNode exprLambda => exprLambda.Params,
            BlockLambdaLambdaExpressionNode blockLambda => blockLambda.Params,
            _ => null,
        };

        if(paramList is not ParenthesizedLambdaParamsLambdaParameterListNode parenParams)
        {
            return false;
        }

        if(parenParams.Params is null)
        {
            return false; // zero-parameter lambda
        }

        // Check if the first param is typed.
        if(parenParams.Params.LambdaParam is not TypedLambdaParamLambdaParamNode)
        {
            return false;
        }

        // Check all remaining params are typed.
        foreach(var param in parenParams.Params.LambdaParams)
        {
            if(param is not TypedLambdaParamLambdaParamNode)
            {
                return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Collects the resolved parameter types from the lambda scope.
    /// Used when the lambda has explicitly-typed parameters to construct the
    /// correct Func type based on the actual resolved annotations.
    /// </summary>
    private static List<IType> CollectLambdaResolvedParamTypes(LambdaExpressionNode lambda, Scope lambdaScope)
    {
        var paramList = lambda switch
        {
            ExpressionLambdaLambdaExpressionNode exprLambda => exprLambda.Params,
            BlockLambdaLambdaExpressionNode blockLambda => blockLambda.Params,
            _ => null,
        };

        var result = new List<IType>();

        if(paramList is ParenthesizedLambdaParamsLambdaParameterListNode parenParams && parenParams.Params is not null)
        {
            // Collect param names in order and look up their types from the scope.
            var paramNodes = new List<LambdaParamNode> { parenParams.Params.LambdaParam };
            paramNodes.AddRange(parenParams.Params.LambdaParams);

            foreach(var paramNode in paramNodes)
            {
                var name = paramNode switch
                {
                    TypedLambdaParamLambdaParamNode typed => typed.Name.Lexeme,
                    UntypedLambdaParamLambdaParamNode untyped => untyped.Name.Lexeme,
                    _ => null,
                };

                if(name is not null)
                {
                    var symbol = lambdaScope.Lookup(name);
                    result.Add(symbol?.DeclaredType ?? UnknownType.Instance);
                }
            }
        }

        return result;
    }

    /// <summary>
    /// Resolves the body of a lambda expression (either an expression body or a block body)
    /// in the given scope.
    /// </summary>
    private static void ResolveLambdaBody(
        LambdaExpressionNode lambda,
        Scope lambdaScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(lambda)
        {
            case ExpressionLambdaLambdaExpressionNode exprLambda:
                // Expression body: resolve the body expression in the lambda scope.
                _ = ResolveExpression(exprLambda.Body, lambdaScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;

            case BlockLambdaLambdaExpressionNode blockLambda:
                // Block body: resolve the block in the lambda scope.
                // ResolveBlock creates its own child scope, but we pass lambdaScope
                // as the parent so the lambda parameters are visible.
                ResolveBlock(blockLambda.Body, lambdaScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    /// <summary>
    /// Returns <c>true</c> if the given type contains any <see cref="TypeParameterType"/> instances,
    /// either directly or nested within a <see cref="ConstructedType"/>'s type arguments.
    /// Used to detect when a lambda's target Func type has unresolved generic type parameters
    /// (e.g., <c>Func&lt;int, T&gt;</c> from a generic method parameter).
    /// </summary>
    private static bool ContainsTypeParameter(IType type)
    {
        if(type is TypeParameterType)
        {
            return true;
        }

        if(type is ConstructedType ct)
        {
            foreach(var arg in ct.TypeArguments)
            {
                if(ContainsTypeParameter(arg))
                {
                    return true;
                }
            }
        }

        if(type is ArrayType arrayType)
        {
            return ContainsTypeParameter(arrayType.ElementType);
        }

        return false;
    }

    /// <summary>
    /// Infers the actual return type of a lambda body after it has been resolved.
    /// For expression lambdas, retrieves the resolved type of the body expression.
    /// For block lambdas, collects return statement types and finds the common type.
    /// Returns <c>null</c> if the return type cannot be determined.
    /// </summary>
    private static IType? InferLambdaBodyReturnType(
        LambdaExpressionNode lambda,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        Scope fileScope,
        SymbolTable symbolTable,
        bool isAsync)
    {
        IType? returnType = null;

        switch(lambda)
        {
            case ExpressionLambdaLambdaExpressionNode exprLambda:
                {
                    // Expression body: the return type is the resolved type of the body expression.
                    if(expressionTypes.TryGetValue(exprLambda.Body, out var bodyType))
                    {
                        returnType = bodyType;
                    }

                    break;
                }

            case BlockLambdaLambdaExpressionNode blockLambda:
                {
                    // Block body: collect return types from all return statements.
                    var returnTypes = new List<IType>();
                    CollectReturnTypes(blockLambda.Body, expressionTypes, returnTypes);

                    if(returnTypes.Count == 0)
                    {
                        // No return statements with values — void lambda.
                        var globalScope = FindGlobalScope(fileScope) ?? fileScope;
                        try
                        {
                            returnType = ResolveVoidKeyword(globalScope, symbolTable);
                        }
                        catch(StdlibMissingException)
                        {
                            returnType = LegacyPrimitiveTypes.Void;
                        }
                    }
                    else if(returnTypes.Count == 1)
                    {
                        returnType = returnTypes[0];
                    }
                    else
                    {
                        // Multiple return statements — find the common type.
                        var firstType = returnTypes[0];
                        var allSame = true;
                        for(var i = 1; i < returnTypes.Count; i++)
                        {
                            if(!ReferenceEquals(firstType, returnTypes[i])
                                && firstType.DisplayName != returnTypes[i].DisplayName)
                            {
                                allSame = false;
                                break;
                            }
                        }

                        returnType = allSame ? firstType : null;
                    }

                    break;
                }
        }

        // For async lambdas, wrap the inferred return type in Task<T>.
        if(isAsync && returnType is not null)
        {
            returnType = ConstructTaskType(returnType, fileScope, symbolTable);
        }

        return returnType;
    }

    private static IType ResolveAssignment(
        AssignmentNode assignment,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var targetType = ResolveVoidCoalescing(assignment.Target, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(assignment.Value is not null)
        {
            // This is an assignment expression: target = value.
            // The RHS is now a full ExpressionNode (widened to reach lambdas), so
            // resolve it through the Expression-level entry point.
            // Set target type context for target-typed new expression from the
            // assignment target's resolved type.
            var previousTargetNewTarget = targetTypedNewTargetType;
            targetTypedNewTargetType = targetType;
            _ = ResolveExpression(assignment.Value, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            targetTypedNewTargetType = previousTargetNewTarget;
            expressionTypes[assignment] = targetType;
            return targetType;
        }

        expressionTypes[assignment] = targetType;
        return targetType;
    }

    private static IType ResolveVoidCoalescing(
        VoidCoalescingNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var leftType = ResolveLogicalOr(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(node.LogicalOrs.Length > 0)
        {
            // For `a ?? b ?? c`, resolve each right operand.
            // The result type is the non-void portion of the left type.
            // The type checker will validate the types; here we just compute the result.
            var currentType = leftType;
            foreach(var rightOperand in node.LogicalOrs)
            {
                _ = ResolveLogicalOr(rightOperand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                // Compute the non-void portion of the current left type for the result.
                if(currentType is UnionType union)
                {
                    var nonVoidConstituents = union.Constituents
                        .Where(c => !c.IsVoid())
                        .ToList();
                    currentType = nonVoidConstituents.Count == 1
                        ? nonVoidConstituents[0]
                        : currentType; // Keep as-is if can't simplify; type checker will validate.
                }
                // If not a union containing void, keep the type as-is (type checker will emit error).
            }

            expressionTypes[node] = currentType;
            return currentType;
        }

        expressionTypes[node] = leftType;
        return leftType;
    }

    private static IType ResolveLogicalOr(
        LogicalOrNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var leftType = ResolveLogicalAnd(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            _ = ResolveLogicalAnd(node.Right, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            var result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
            expressionTypes[node] = result;
            return result;
        }

        expressionTypes[node] = leftType;
        return leftType;
    }

    private static IType ResolveLogicalAnd(
        LogicalAndNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var leftType = ResolveEquality(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            // C#-style definite assignment for pattern variables: a variable
            // introduced by an `is` pattern on the LHS of `&&` is definitely
            // assigned on the RHS (short-circuit semantics guarantee the RHS
            // only executes when the LHS is true). Create a child scope that
            // contains those pattern bindings so the RHS can reference them.
            var rhsScope = currentScope;
            if(LhsContainsIsPattern(node.Left))
            {
                rhsScope = new Scope(parent: currentScope);
                CollectFromEquality(node.Left, rhsScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);
            }

            _ = ResolveEquality(node.Right, rhsScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            var result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
            expressionTypes[node] = result;
            return result;
        }

        expressionTypes[node] = leftType;
        return leftType;
    }

    /// <summary>
    /// Quick structural check: returns <c>true</c> if the given <see cref="EqualityNode"/>
    /// contains an <see cref="IsExpressionRelationalNode"/> with a binding pattern. Used by
    /// <see cref="ResolveLogicalAnd"/> to decide whether pattern variables need to be
    /// injected into a child scope for the RHS of <c>&amp;&amp;</c>.
    /// </summary>
    private static bool LhsContainsIsPattern(EqualityNode node)
    {
        if(node.Left is not IsExpressionRelationalNode)
        {
            return false;
        }

        return true;
    }

    private static IType ResolveEquality(
        EqualityNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var rightOperand = node.Right is not null && !ReferenceEquals(node.Right, node.Left)
            ? node.Right
            : null;

        // Target-type-aware void resolution for equality operands: when either
        // operand is a bare `void` keyword literal (e.g. `void == void`), there
        // is no external target type to drive value-literal resolution, so each
        // `void` would otherwise resolve to the Standard.Type metatype — which
        // declares no equality operators. Set the void target type so each bare
        // `void` operand resolves as VoidType (the Void singleton) instead. The
        // void-equality short-circuit in TypeCheckerAnalyzer.CheckEqualityNode
        // then types the comparison as bool. (void-value-literal, Requirement 9.)
        var setVoidTarget = rightOperand is not null
            && (IsBareVoidTypeLiteral(node.Left) || IsBareVoidTypeLiteral(rightOperand));
        var previousVoidTarget = voidLiteralTargetType;
        if(setVoidTarget)
        {
            voidLiteralTargetType = LegacyPrimitiveTypes.Void;
        }

        try
        {
            var leftType = ResolveRelational(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

            if(rightOperand is not null)
            {
                _ = ResolveRelational(rightOperand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                var result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                expressionTypes[node] = result;
                return result;
            }

            expressionTypes[node] = leftType;
            return leftType;
        }
        finally
        {
            if(setVoidTarget)
            {
                voidLiteralTargetType = previousVoidTarget;
            }
        }
    }

    /// <summary>
    /// Returns true when the given relational operand is a bare <c>void</c>
    /// keyword type literal — i.e. it reduces (with no binary operators or
    /// postfix suffixes) to a <see cref="TypeLiteralExpressionPrimaryNode"/>
    /// whose <c>TypeRef.First</c> is a <see cref="VoidSingleTypeRefSingleTypeRefNode"/>.
    /// Used to drive target-type-aware void resolution for equality operands
    /// such as <c>void == void</c>, which have no external target type. Returns
    /// false for any other operand (e.g. <c>1 == 2</c>, <c>"a" == "b"</c>,
    /// <c>x == y</c>), preserving normal equality behavior.
    /// </summary>
    private static bool IsBareVoidTypeLiteral(RelationalNode? relational)
    {
        if(relational is not RelationalComparisonRelationalNode { Right: null } cmp)
        {
            return false;
        }

        if(cmp.Left is not AdditiveNode { Right: null } additive)
        {
            return false;
        }

        if(additive.Left is not MultiplicativeNode { Right: null } multiplicative)
        {
            return false;
        }

        if(multiplicative.Left is not PostfixExpressionUnaryNode postfix)
        {
            return false;
        }

        if(postfix.Primary is not PostfixNode { Suffix.Length: 0 } postfixNode)
        {
            return false;
        }

        return postfixNode.Target is TypeLiteralExpressionPrimaryNode { TypeRef: { SingleTypeRefs.Length: 0, First: VoidSingleTypeRefSingleTypeRefNode } };
    }

    private static IType ResolveRelational(
        RelationalNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(node)
        {
            case RelationalComparisonRelationalNode cmp:
                {
                    var leftType = ResolveAdditive(cmp.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    if(cmp.Right is not null && !ReferenceEquals(cmp.Right, cmp.Left))
                    {
                        _ = ResolveAdditive(cmp.Right, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        var result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                        expressionTypes[node] = result;
                        return result;
                    }

                    expressionTypes[node] = leftType;
                    return leftType;
                }

            case IsExpressionRelationalNode isExpr:
                {
                    // Resolve the left-hand side (scrutinee) additive expression.
                    var scrutineeType = ResolveAdditive(isExpr.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Resolve type references and constant expressions within the pattern.
                    ResolvePattern(isExpr.Pattern, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Record bool as the expression type — an `is` expression always evaluates to bool.
                    var boolType = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                    expressionTypes[node] = boolType;
                    return boolType;
                }

            case AsExpressionRelationalNode asExpr:
                {
                    // Resolve the left-hand side operand to determine its Compile_Time_Type.
                    _ = ResolveAdditive(asExpr.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Resolve the target type reference to an IType.
                    var targetType = ResolveTypeReference(asExpr.TargetType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                    // Store the resolved target type on the TargetType node so the emitter
                    // can retrieve the raw target type via GetTypeOf(asExpr.TargetType).
                    // This is needed because the type checker overwrites the expression type
                    // on `asExpr` itself with the result type (T or T | void).
                    expressionTypes[asExpr.TargetType] = targetType;

                    // Record the resolved target type as a preliminary type on the node.
                    // The type checker will override this with the final result type (T or T | void).
                    expressionTypes[node] = targetType;
                    return targetType;
                }

            default:
                {
                    expressionTypes[node] = ErrorType.Instance;
                    return ErrorType.Instance;
                }
        }
    }

    // ─── Pattern Resolution ─────────────────────────────────────────────
    // Recursively resolves type references within patterns (e.g., the type
    // in a type pattern, the type prefix in a property pattern) and records
    // expression types for constant sub-expressions.

    private static void ResolvePattern(
        PatternNode pattern,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        ResolveOrPattern(pattern.OrPattern, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    private static void ResolveOrPattern(
        OrPatternNode orPattern,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        ResolveAndPattern(orPattern.Left, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(orPattern.Right is not null && !ReferenceEquals(orPattern.Right, orPattern.Left))
        {
            ResolveAndPattern(orPattern.Right, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void ResolveAndPattern(
        AndPatternNode andPattern,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        ResolveUnaryPattern(andPattern.Left, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(andPattern.Right is not null && !ReferenceEquals(andPattern.Right, andPattern.Left))
        {
            ResolveUnaryPattern(andPattern.Right, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    private static void ResolveUnaryPattern(
        UnaryPatternNode unaryPattern,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(unaryPattern)
        {
            case NotPatternUnaryPatternNode notPattern:
                ResolvePrimaryPattern(notPattern.Operand, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case DirectPatternUnaryPatternNode directPattern:
                ResolvePrimaryPattern(directPattern.Primary, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
        }
    }

    private static void ResolvePrimaryPattern(
        PrimaryPatternNode primaryPattern,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(primaryPattern)
        {
            case TypePatternPrimaryPatternNode typePattern:
                {
                    // Resolve the type reference to get the pattern type.
                    var resolvedPatternType = ResolveTypeReference(typePattern.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    // Store the resolved type so the type checker can retrieve it via
                    // GetTypeOf(typePattern.Type) — especially needed for discard patterns
                    // where no symbol is registered (no GetDeclaredSymbol fallback).
                    expressionTypes[typePattern.Type] = resolvedPatternType;
                    break;
                }

            case BareTypePatternPrimaryPatternNode bareTypePattern:
                {
                    // Bare type pattern: resolve the type reference (no binding name).
                    // Store the resolved type in the expression-type map so the
                    // type checker can retrieve it via GetTypeOf(bareTypePattern.Type).
                    //
                    // Special case: if the type reference is a qualified name like
                    // EnumName.MemberName, ResolveTypeReference will fail (it's not a type).
                    // We detect this and resolve it as an enum member access pattern instead.
                    if(bareTypePattern.Type.First is NamedSingleTypeRefSingleTypeRefNode namedPatternRef)
                    {
                        var qualifiedName = ExtractQualifiedName(namedPatternRef.Name, sourceText);
                        var dotIndex = qualifiedName.LastIndexOf('.');
                        if(dotIndex > 0)
                        {
                            // Qualified name with a dot — try to resolve as EnumName.MemberName.
                            var enumName = qualifiedName[..dotIndex];
                            var memberName = qualifiedName[(dotIndex + 1)..];

                            // First try the scope chain (covers same-namespace enums).
                            var enumSymbol = fileScope.Lookup(enumName);

                            // If not found, search imported namespace scopes (covers
                            // enums from referenced projects accessed via using directives).
                            if(enumSymbol is null)
                            {
                                var patternImportedNamespaces = CollectImportedNamespaces(fileScope);
                                var patternGlobalScope = FindGlobalScope(fileScope);
                                if(patternGlobalScope is not null)
                                {
                                    foreach(var ns in patternImportedNamespaces)
                                    {
                                        var nsScope = FindExistingNamespaceScope(patternGlobalScope, symbolTable, ns);
                                        if(nsScope is not null)
                                        {
                                            enumSymbol = nsScope.Lookup(enumName);
                                            if(enumSymbol is not null)
                                            {
                                                break;
                                            }
                                        }
                                    }
                                }
                            }

                            if(enumSymbol is not null && enumSymbol.Kind == SymbolKind.Enum && enumSymbol.DeclaredType is EnumType enumType)
                            {
                                var enumMember = enumType.MemberScope.Lookup(memberName);
                                if(enumMember is not null)
                                {
                                    // Valid enum member pattern — store the EnumType.
                                    expressionTypes[bareTypePattern.Type] = enumType;
                                    break;
                                }
                            }
                        }
                    }

                    var resolvedType = ResolveTypeReference(bareTypePattern.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    expressionTypes[bareTypePattern.Type] = resolvedType;
                    break;
                }

            case VarPatternPrimaryPatternNode:
                {
                    // Var pattern: the type is the scrutinee type. No resolution needed.
                    break;
                }

            case DiscardPatternPrimaryPatternNode:
                {
                    // Bare discard pattern: no type resolution needed.
                    break;
                }

            case ConstantPatternPrimaryPatternNode constantPattern:
                {
                    // Resolve the constant literal to record its type.
                    ResolveConstantLiteral(constantPattern.Literal, fileScope, symbolTable, expressionTypes);
                    break;
                }

            case LessThanRelationalPatternPrimaryPatternNode ltPattern:
                {
                    // Resolve the constant expression (now bounded to VoidCoalescing).
                    _ = ResolveVoidCoalescing(ltPattern.Constant, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }

            case GreaterThanRelationalPatternPrimaryPatternNode gtPattern:
                {
                    _ = ResolveVoidCoalescing(gtPattern.Constant, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }

            case LessThanOrEqualRelationalPatternPrimaryPatternNode ltePattern:
                {
                    _ = ResolveVoidCoalescing(ltePattern.Constant, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }

            case GreaterThanOrEqualRelationalPatternPrimaryPatternNode gtePattern:
                {
                    _ = ResolveVoidCoalescing(gtePattern.Constant, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }

            case PropertyPatternPrimaryPatternNode propertyPattern:
                {
                    // If there's a type name prefix, resolve it.
                    var patternType = scrutineeType;
                    if(propertyPattern.TypeName is not null)
                    {
                        var typeName = ExtractQualifiedName(propertyPattern.TypeName, sourceText);
                        patternType = ResolveNamedType(typeName, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    }

                    // Recursively resolve subpatterns.
                    if(propertyPattern.Subpatterns is not null)
                    {
                        ResolvePropertySubpatternList(propertyPattern.Subpatterns, patternType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    break;
                }

            case ListPatternPrimaryPatternNode listPattern:
                {
                    // Determine the element type: if the scrutinee is an array, use its element type.
                    var elementType = scrutineeType is ArrayType arrayType
                        ? arrayType.ElementType
                        : ErrorType.Instance;

                    // Recursively resolve element patterns.
                    if(listPattern.Elements is not null)
                    {
                        ResolveListPatternElementList(listPattern.Elements, elementType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    break;
                }

            case TuplePositionalPatternPrimaryPatternNode tuplePositionalPattern:
                {
                    // Determine element types from the scrutinee type and recursively
                    // resolve each element subpattern with the corresponding type.
                    var elementPatterns = new List<PatternNode> { tuplePositionalPattern.First, tuplePositionalPattern.Rest };
                    elementPatterns.AddRange(tuplePositionalPattern.Patterns);

                    if(scrutineeType is TupleType tupleType)
                    {
                        for(var i = 0; i < elementPatterns.Count; i++)
                        {
                            var elementType = i < tupleType.ElementTypes.Count
                                ? tupleType.ElementTypes[i]
                                : ErrorType.Instance;
                            ResolvePattern(elementPatterns[i], elementType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }
                    else
                    {
                        // Not a tuple type — still resolve subpatterns with ErrorType.
                        foreach(var elementPattern in elementPatterns)
                        {
                            ResolvePattern(elementPattern, ErrorType.Instance, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    break;
                }

            case ParenthesizedPatternPrimaryPatternNode parenPattern:
                {
                    // Recursively resolve the inner pattern.
                    ResolvePattern(parenPattern.Inner, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    break;
                }
        }
    }

    /// <summary>
    /// Resolves a constant literal within a pattern, recording its type in the expression types map.
    /// </summary>
    private static void ResolveConstantLiteral(
        ConstantLiteralNode literal,
        Scope fileScope,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes)
    {
        var type = literal switch
        {
            IntegerConstantConstantLiteralNode intConst =>
                ResolveIntegerLiteralType(intConst.Value.Lexeme, fileScope, symbolTable),
            FloatConstantConstantLiteralNode floatConst =>
                ResolveFloatLiteralType(floatConst.Value.Lexeme, fileScope, symbolTable),
            StringConstantConstantLiteralNode =>
                ResolvePrimitiveByKeyword("string", fileScope, symbolTable),
            RegexConstantConstantLiteralNode =>
                ResolvePrimitiveByKeyword("regex", fileScope, symbolTable),
            CharConstantConstantLiteralNode =>
                ResolvePrimitiveByKeyword("char", fileScope, symbolTable),
            TrueConstantConstantLiteralNode =>
                ResolvePrimitiveByKeyword("bool", fileScope, symbolTable),
            FalseConstantConstantLiteralNode =>
                ResolvePrimitiveByKeyword("bool", fileScope, symbolTable),
            _ => ErrorType.Instance,
        };

        expressionTypes[literal] = type;
    }

    /// <summary>
    /// Resolves a property subpattern list, recursively resolving each subpattern.
    /// </summary>
    private static void ResolvePropertySubpatternList(
        PropertySubpatternListNode subpatternList,
        IType patternType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Resolve the first subpattern.
        ResolvePropertySubpattern(subpatternList.PropertySubpattern, patternType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Resolve additional subpatterns.
        foreach(var subpattern in subpatternList.PropertySubpatterns)
        {
            ResolvePropertySubpattern(subpattern, patternType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    /// <summary>
    /// Resolves a single property subpattern. The subpattern's inner pattern
    /// is resolved against the property's type (if known) or the scrutinee type.
    /// </summary>
    private static void ResolvePropertySubpattern(
        PropertySubpatternNode subpattern,
        IType patternType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Try to determine the property's type from the pattern type's member scope.
        var propertyType = ErrorType.Instance as IType;
        var propertyName = subpattern.Name.Lexeme;

        if(patternType is ClassType classType)
        {
            var member = classType.MemberScope.Lookup(propertyName);
            if(member is not null && member.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }
        else if(patternType is StructType structType)
        {
            var member = structType.MemberScope.Lookup(propertyName);
            if(member is not null && member.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }
        else if(patternType is AbstractType abstractType)
        {
            var member = abstractType.MemberScope.Lookup(propertyName);
            if(member is not null && member.DeclaredType is not null)
            {
                propertyType = member.DeclaredType;
            }
        }

        // Recursively resolve the subpattern's inner pattern.
        ResolvePattern(subpattern.Pattern, propertyType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Resolves a list pattern element list, recursively resolving each element pattern.
    /// </summary>
    private static void ResolveListPatternElementList(
        ListPatternElementListNode elementList,
        IType elementType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Resolve the first element.
        ResolveListPatternElement(elementList.ListPatternElement, elementType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Resolve additional elements.
        foreach(var element in elementList.ListPatternElements)
        {
            ResolveListPatternElement(element, elementType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }
    }

    /// <summary>
    /// Resolves a single list pattern element. Pattern elements are resolved
    /// against the array element type; slice elements need no resolution.
    /// </summary>
    private static void ResolveListPatternElement(
        ListPatternElementNode element,
        IType elementType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(element)
        {
            case PatternElementListPatternElementNode patternElement:
                ResolvePattern(patternElement.Pattern, elementType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;
            case SliceElementListPatternElementNode:
                // Slice elements (`..` or `.. name`) need no type resolution.
                break;
        }
    }

    private static IType ResolveAdditive(
        AdditiveNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var leftType = ResolveMultiplicative(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            var rightType = ResolveMultiplicative(node.Right, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

            // String concatenation: if either operand is string, result is string.
            // After Task 50, StringType has been deleted. String is now either
            // the stdlib Standard.String ClassType or the legacy
            // LegacyPrimitiveTypes.String ClassType fallback.
            if(IsStringLikeType(leftType) || IsStringLikeType(rightType))
            {
                // Return whichever string-like type we found (prefer left).
                var stringType = IsStringLikeType(leftType) ? leftType : rightType;
                expressionTypes[node] = stringType;
                return stringType;
            }

            var result = GetCommonNumericType(leftType, rightType);
            expressionTypes[node] = result;
            return result;
        }

        expressionTypes[node] = leftType;
        return leftType;
    }

    private static IType ResolveMultiplicative(
        MultiplicativeNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var leftType = ResolveUnary(node.Left, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        if(node.Right is not null && !ReferenceEquals(node.Right, node.Left))
        {
            var rightType = ResolveUnary(node.Right, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            var result = GetCommonNumericType(leftType, rightType);
            expressionTypes[node] = result;
            return result;
        }

        expressionTypes[node] = leftType;
        return leftType;
    }

    private static IType ResolveUnary(
        UnaryNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(node)
        {
            case LogicalNotUnaryNode logicalNot:
                {
                    _ = ResolveUnary(logicalNot.Operand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    var result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                    expressionTypes[node] = result;
                    return result;
                }
            case NegateUnaryNode negate:
                {
                    var operandType = ResolveUnary(negate.Operand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    expressionTypes[node] = operandType;
                    return operandType;
                }
            case CastExpressionUnaryNode castExpr:
                return ResolveCastExpression(castExpr, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            case PostfixExpressionUnaryNode postfix:
                {
                    var type = ResolvePostfix(postfix.Primary, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    expressionTypes[node] = type;
                    return type;
                }
            case AsyncExpressionUnaryNode asyncExpr:
                {
                    // Resolve the operand expression (should be a method invocation).
                    var operandType = ResolveUnary(asyncExpr.Operand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Wrap the operand's type in Task<T>.
                    var taskType = ConstructTaskType(operandType, fileScope, symbolTable);
                    expressionTypes[node] = taskType;
                    return taskType;
                }
            case AwaitExpressionUnaryNode awaitExpr:
                {
                    // Suppress auto-unwrap for the await operand so that async method calls
                    // return Task<T> (not T) — the await itself will do the unwrapping.
                    var prevAsyncContext = isInAsyncContext;
                    isInAsyncContext = true;
                    // Resolve the operand expression (should be of type Task<T>).
                    var operandType = ResolveUnary(awaitExpr.Operand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    isInAsyncContext = prevAsyncContext;

                    // If the operand is Task<T>, unwrap to T. Otherwise, return UnknownType
                    // (the diagnostic for non-Task operands is added in task 8.5).
                    if(operandType is ConstructedType ct && IsStandardTaskType(ct))
                    {
                        var innerType = ct.TypeArguments[0];
                        expressionTypes[node] = innerType;

                        // Under the Drop-based model, named Task<T> variables are
                        // auto-dropped at scope exit (tasks 7.1, 7.3). An explicit
                        // await acts as a Drop() call, transitioning the variable to
                        // Dropped state — the DropAnalyzer handles this flow-sensitively.
                        // No MarkTaskAsAwaited is needed for the discarded-task tracking
                        // since discarded tasks (synthetic __task_N) are never awaited
                        // by name in user code.

                        return innerType;
                    }

                    // Also handle ValueTask<T> — unwrap to T.
                    if(operandType is ConstructedType vtCt
                        && vtCt.GenericDefinition is ClassType { DisplayName: "ValueTask", ContainingNamespace: "Standard", IsBackendBacked: true }
                        && vtCt.TypeArguments.Count > 0)
                    {
                        var innerType = vtCt.TypeArguments[0];
                        expressionTypes[node] = innerType;
                        return innerType;
                    }

                    var unknownResult = UnknownType.Instance;
                    expressionTypes[node] = unknownResult;
                    return unknownResult;
                }
            case AsyncBlockExpressionUnaryNode asyncBlock:
                {
                    // async { return expr; } produces Task<T> where T is the block's return type.
                    // For simplicity, we resolve the block's statements to find the return type.
                    var returnType = ResolveBlockReturnType(asyncBlock.Body, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    var taskType = ConstructTaskType(returnType, fileScope, symbolTable);
                    expressionTypes[node] = taskType;
                    return taskType;
                }
            case AsyncHintBlockExpressionUnaryNode asyncHintBlock:
                {
                    // async valuetask { return expr; } produces ValueTask<T> where T is the block's return type.
                    // The hint identifier determines the wrapper type.
                    var returnType = ResolveBlockReturnType(asyncHintBlock.Body, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    var hint = asyncHintBlock.Hint.Lexeme;
                    var resultType = hint == "valuetask"
                        ? ConstructValueTaskType(returnType, fileScope, symbolTable)
                        : ConstructTaskType(returnType, fileScope, symbolTable);
                    expressionTypes[node] = resultType;
                    return resultType;
                }
            default:
                expressionTypes[node] = ErrorType.Instance;
                return ErrorType.Instance;
        }
    }

    /// <summary>
    /// Resolves a cast expression <c>(TargetType)operand</c> in Pass 2.
    /// Resolves the target type reference to an <see cref="IType"/>, resolves
    /// the operand expression, and records the target type as the expression
    /// type of the cast expression node.
    /// </summary>
    private static IType ResolveCastExpression(
        CastExpressionUnaryNode castExpr,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // 1. Resolve the target type reference to an IType.
        var targetType = ResolveTypeReference(castExpr.TargetType, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

        // 2. Resolve the operand expression to get its type.
        _ = ResolveUnary(castExpr.Operand, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // 3. For casts targeting an enum type, the result is always
        //    EnumType | void (the cast is fallible — the value may not match any variant).
        //    This applies regardless of whether the source type is fully resolved
        //    (e.g., in lambda bodies where parameter types depend on target-type propagation).
        if(targetType is EnumType targetEnum && targetEnum.UnderlyingType is not null)
        {
            var voidType = TryLookupVoidType(fileScope, symbolTable);
            if(voidType is not null)
            {
                var nullableEnumType = new UnionType(new List<IType> { targetEnum, voidType });
                expressionTypes[castExpr] = nullableEnumType;
                return nullableEnumType;
            }
        }

        // 4. Record the target type as the expression type of the cast expression node.
        expressionTypes[castExpr] = targetType;

        // 5. Return the target type.
        return targetType;
    }

    private static IType ResolvePostfix(
        PostfixNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        var targetType = ResolvePrimary(node.Target, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Method group conversion: when an identifier resolves to a method symbol
        // and is NOT followed by an invocation suffix (i.e., it's used as a value,
        // not called), convert the expression type to the equivalent Func type
        // constructed from the method's parameter types + return type.
        if(node.Target is IdentifierExpressionPrimaryNode identifierTarget
            && (node.Suffix.Length == 0 || node.Suffix[0] is not InvocationSuffixPostfixSuffixNode))
        {
            var targetSymbol = symbolTable.GetDeclaredSymbol(node.Target);
            if(targetSymbol is Symbol { Kind: SymbolKind.Method } methodSymbol)
            {
                // ── delegate-func-conversion: method group resolution for DelegateType targets ──
                // When the target type context is a DelegateType, resolve the method group
                // against the delegate's FuncSignature to select the single compatible overload.
                if(lambdaTargetType is DelegateType delegateTarget)
                {
                    var resolved = ResolveMethodGroupForDelegateTarget(
                        identifierTarget,
                        delegateTarget,
                        currentScope,
                        fileScope,
                        symbolTable,
                        sourceText,
                        diagnostics);
                    if(resolved is not null)
                    {
                        targetType = resolved;
                    }
                }
                else
                {
                    var funcType = ConstructFuncTypeFromMethod(methodSymbol, fileScope, symbolTable);
                    if(funcType is not null)
                    {
                        targetType = funcType;
                    }
                }
            }
        }

        // Explicitly store the target's type on the PostfixNode.Target node as well,
        // so that downstream analysis (e.g., for-loop narrowing) can retrieve it
        // via model.GetTypeOf(postfix.Target).
        expressionTypes[node.Target] = targetType;

        // ── Primitive keyword static member access ──────────────────────────
        // When a type literal (e.g., `string`, `int`, `List<int>`) is followed
        // by a member access or method call suffix, check if the referenced type
        // has the member as a static member. If yes, redirect the target type
        // to the referenced type so static members are accessible
        // (e.g., `string.IsNullOrWhiteSpace(x)`). If not, keep the metatype
        // so that reflection properties like `int.Name` still work via typeof().
        if(node.Target is TypeLiteralExpressionPrimaryNode typeLiteralTarget
            && node.Suffix.Length > 0
            && node.Suffix[0] is MemberAccessSuffixPostfixSuffixNode or MethodCallSuffixPostfixSuffixNode or OptionalMethodCallSuffixPostfixSuffixNode or OptionalMemberAccessSuffixPostfixSuffixNode)
        {
            var referencedType = ResolveTypeReference(
                typeLiteralTarget.TypeRef, fileScope, ambientTypeResolver,
                symbolTable, sourceText, diagnostics);

            if(referencedType is not null and not ErrorType)
            {
                // Determine the member name from the first suffix.
                var firstSuffix = node.Suffix[0];
                var firstMemberName = firstSuffix is MemberAccessSuffixPostfixSuffixNode ma ? ma.Name.Lexeme
                    : firstSuffix is MethodCallSuffixPostfixSuffixNode mc ? mc.Name.Lexeme
                    : firstSuffix is OptionalMemberAccessSuffixPostfixSuffixNode oma ? oma.Name.Lexeme
                    : firstSuffix is OptionalMethodCallSuffixPostfixSuffixNode omc ? omc.Name.Lexeme
                    : default;

                if(firstMemberName is not null)
                {
                    // Probe: does the referenced type have this member?
                    var probeDiagnostics = new DiagnosticBag();
                    var probedMember = LookupMemberType(
                        referencedType, firstMemberName, ambientTypeResolver,
                        fileScope, symbolTable, sourceText, probeDiagnostics);

                    if(probedMember is not ErrorType)
                    {
                        // The referenced type has the member — redirect.
                        targetType = referencedType;
                        expressionTypes[node.Target] = targetType;
                    }
                    // Otherwise keep the metatype (typeof) — member is on System.Type.
                }
            }
        }

        // Look up the primary node's symbol for parameter type threading
        // in direct invocations (e.g., method(void)).
        IReadOnlyList<IType>? primaryParamTypes = null;
        if(node.Suffix.Length > 0 && node.Suffix[0] is InvocationSuffixPostfixSuffixNode)
        {
            var primarySymbol = symbolTable.GetDeclaredSymbol(node.Target);
            if(primarySymbol is not null && primarySymbol.Kind == SymbolKind.Method)
            {
                primaryParamTypes = ParameterSignature.Extract(primarySymbol, symbolTable);
            }
        }

        // Apply each postfix suffix in order.
        foreach(var suffix in node.Suffix)
        {
            // For direct invocations (e.g., foo(lambda)), propagate the method's
            // parameter types so lambda arguments can infer their types and so
            // void value literals can resolve via target-type threading.
            if(suffix is InvocationSuffixPostfixSuffixNode invocationSuffix
                && invocationSuffix.Arguments is not null)
            {
                var methodParamTypes = primaryParamTypes;

                // If primaryParamTypes wasn't pre-computed, try to look up the
                // method symbol from an identifier target.
                if(methodParamTypes is null && node.Target is IdentifierExpressionPrimaryNode)
                {
                    var targetSymbol = symbolTable.GetDeclaredSymbol(node.Target);
                    if(targetSymbol is Symbol { Kind: SymbolKind.Method } methodSym)
                    {
                        methodParamTypes = ParameterSignature.Extract(methodSym, symbolTable);
                    }
                }

                if(methodParamTypes is not null)
                {
                    ResolveArgumentListWithParameterTypes(invocationSuffix.Arguments, methodParamTypes, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // Still need to resolve the suffix for its return type, but skip
                    // re-resolving arguments (they're already resolved above).
                    targetType = ResolvePostfixSuffixSkipArguments(invocationSuffix, targetType, expressionTypes);
                    primaryParamTypes = null;
                    continue;
                }
            }

            targetType = ResolvePostfixSuffix(suffix, targetType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
            primaryParamTypes = null;
        }

        // Auto-unwrap for direct invocations of async methods in sync contexts.
        // When the last suffix is an InvocationSuffix (e.g., AsyncMethod()), and
        // the target identifier resolves to an async method, unwrap Task<T> to T.
        if(!isInAsyncContext
            && node.Suffix.Length > 0
            && node.Suffix[^1] is InvocationSuffixPostfixSuffixNode
            && IsStandardTaskType(targetType))
        {
            // Look up the symbol for the target identifier to check IsAsync.
            var targetSymbol = symbolTable.GetDeclaredSymbol(node.Target);
            if(targetSymbol is Symbol { IsAsync: true })
            {
                targetType = UnwrapTaskType(targetType);
                expressionTypes[node.Suffix[^1]] = targetType;
            }
        }

        expressionTypes[node] = targetType;
        return targetType;
    }

    /// <summary>
    /// Resolves the return type of an InvocationSuffix without re-resolving its arguments.
    /// Used when arguments have already been resolved with lambda target type propagation.
    /// </summary>
    private static IType ResolvePostfixSuffixSkipArguments(
        InvocationSuffixPostfixSuffixNode invocation,
        IType targetType,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes)
    {
        // If the target expression's type is a Func constructed type,
        // the invocation's result type is the Func's return type (last type arg).
        if(IsFuncType(targetType) && targetType is ConstructedType funcCt)
        {
            var returnType = GetFuncReturnType(funcCt);
            if(!isInAsyncContext && IsStandardTaskType(returnType))
            {
                returnType = UnwrapTaskType(returnType);
            }

            expressionTypes[invocation] = returnType;
            return returnType;
        }

        // ── delegate-func-conversion: DelegateType invocation ──
        // When the target expression's type is a DelegateType, the invocation's
        // result type is the FuncSignature's return type (last type argument).
        if(targetType is DelegateType delegateType)
        {
            var returnType = GetFuncReturnType(delegateType.FuncSignature);
            if(!isInAsyncContext && IsStandardTaskType(returnType))
            {
                returnType = UnwrapTaskType(returnType);
            }

            expressionTypes[invocation] = returnType;
            return returnType;
        }

        // ── delegate-func-conversion: BaseDelegateType is NOT invocable ──
        if(targetType is BaseDelegateType)
        {
            expressionTypes[invocation] = ErrorType.Instance;
            return ErrorType.Instance;
        }

        // The result type is the return type of the target (if it's a method).
        expressionTypes[invocation] = targetType;
        return targetType;
    }

    private static IType ResolvePostfixSuffix(
        PostfixSuffixNode suffix,
        IType targetType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        switch(suffix)
        {
            case MethodCallSuffixPostfixSuffixNode methodCall:
                {
                    var memberName = methodCall.Name.Lexeme;

                    // ── Unified method resolution (Phase B) ─────────────────────────
                    // Construct resolution hints from the call site context.
                    var typeArgCount = methodCall.TypeArgs is not null ? CountTypeArgs(methodCall.TypeArgs) : (int?)null;
                    var importedNamespaces = CollectImportedNamespaces(fileScope);

                    // Eagerly resolve non-lambda argument types for applicability-based
                    // overload selection. Lambda arguments are left as null (wildcard)
                    // because their parameter types depend on the selected overload.
                    IReadOnlyList<IType?>? resolvedArgTypes = null;
                    if(methodCall.Arguments is not null)
                    {
                        var argExprs = methodCall.Arguments.GetAllExpressions();
                        var argTypeList = new IType?[argExprs.Length];
                        for(var ai = 0; ai < argExprs.Length; ai++)
                        {
                            if(argExprs[ai] is LambdaFormExpressionNode)
                            {
                                argTypeList[ai] = null; // wildcard — lambda needs target type
                            }
                            else
                            {
                                argTypeList[ai] = ResolveExpression(argExprs[ai], currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            }
                        }

                        resolvedArgTypes = argTypeList;
                    }

                    var unifiedHints = new MethodResolutionHints(
                        TypeArgCount: typeArgCount,
                        ArgumentCount: resolvedArgTypes?.Count,
                        PreferLambdaCompatible: false,
                        ArgumentTypes: resolvedArgTypes);
                    var unifiedResult = ResolveMethodMember(targetType, memberName, unifiedHints, importedNamespaces);

                    // Determine memberType: use unified result if available, otherwise
                    // fall back to LookupMemberType for non-method cases (namespace refs,
                    // enum access, special types like arrays/strings, etc.).
                    var memberType = unifiedResult is not null
                        ? unifiedResult.Value.ReturnType
                        : LookupMemberType(targetType, memberName, ambientTypeResolver, fileScope, symbolTable, sourceText, diagnostics);

                    // Kind-aware validation: method call must not resolve to a field or property.
                    if(memberType is not ErrorType)
                    {
                        var resolvedSymbol = LookupMemberSymbol(targetType, memberName);
                        if(resolvedSymbol is not null && resolvedSymbol.Kind is SymbolKind.Field or SymbolKind.Property)
                        {
                            diagnostics.Add(new Diagnostic(
                                MethodCallResolvesToProperty,
                                DiagnosticSeverity.Error,
                                PipelineStage.SemanticModelConstruction,
                                $"'{memberName}' is a {(resolvedSymbol.Kind == SymbolKind.Field ? "field" : "property")} and cannot be invoked as a method. Use '{memberName}' without parentheses.",
                                Location: default,
                                CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                                AnalyzerName: null));
                            expressionTypes[suffix] = ErrorType.Instance;
                            return ErrorType.Instance;
                        }

                        // Register the resolved method symbol on the call site node so the
                        // emitter can look it up via GetDeclaredSymbol to check ClrCallingConvention
                        // for in/ref keyword selection at call sites (Requirement 3.4).
                        // Only register for Backend-origin symbols to avoid interfering with the
                        // TypeChecker's GetDeclaredSymbol lookups (which expect null for user-code
                        // method calls and would otherwise produce duplicate diagnostics or crash
                        // on dependent type arguments).
                        if(resolvedSymbol is not null && resolvedSymbol.Kind == SymbolKind.Method
                            && resolvedSymbol.Origin == SymbolOrigin.Backend)
                        {
                            symbolTable.RegisterUsageSite(methodCall, resolvedSymbol);
                        }
                    }

                    // Handle type arguments on method invocations (e.g., obj.Method<int>()).
                    IReadOnlyList<IType>? resolvedMethodTypeArgs = null;
                    IReadOnlyList<IType>? methodTypeParams = null;
                    ISymbol? resolvedGenericMethodSymbol = null;
                    if(methodCall.TypeArgs is not null)
                    {
                        // Use the unified result's symbol when available — it already
                        // selected the arity-matching overload. Fall back to
                        // LookupGenericMemberSymbol only when unified resolution
                        // did not find the method (e.g., non-method cases).
                        var providedArity = CountTypeArgs(methodCall.TypeArgs);
                        var methodSymbol = unifiedResult?.Symbol;
                        methodSymbol ??= LookupGenericMemberSymbol(targetType, memberName, providedArity, fileScope);

                        if(methodSymbol is Symbol sym && sym.TypeParameters.Count > 0)
                        {
                            // Resolve the type arguments. Use the dependent-aware resolver
                            // if the method has any dependent type parameters.
                            var hasDependentParams = false;
                            foreach(var tp in sym.TypeParameters)
                            {
                                if(tp is DependentTypeParameterType)
                                {
                                    hasDependentParams = true;
                                    break;
                                }
                            }

                            IReadOnlyList<IType> resolvedTypeArgs;
                            if(hasDependentParams)
                            {
                                var (typeArgs, _) = ResolvePass2TypeArgumentListWithDependents(
                                    methodCall.TypeArgs, sym.TypeParameters, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                resolvedTypeArgs = typeArgs;
                            }
                            else
                            {
                                resolvedTypeArgs = ResolvePass2TypeArgumentList(methodCall.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                            }

                            if(resolvedTypeArgs.Count != sym.TypeParameters.Count)
                            {
                                // Method arity mismatch.
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    GenericsDiagnostics.MethodArityMismatch.Id.Value,
                                    DiagnosticSeverity.Error,
                                    $"Method '{memberName}' expects {sym.TypeParameters.Count} type argument(s) but received {resolvedTypeArgs.Count}.",
                                    methodCall.TypeArgs,
                                    sourceText));
                                memberType = ErrorType.Instance;
                            }
                            else
                            {
                                // Substitute type parameters in the return type with
                                // the resolved type arguments. Use the symbol's own
                                // DeclaredType as the base for substitution — the unified
                                // resolution already selected the arity-matching overload,
                                // so sym.DeclaredType is the correct return type to substitute.
                                var returnTypeForSubstitution = sym.DeclaredType ?? memberType;
                                memberType = SubstituteTypeParameters(returnTypeForSubstitution, sym.TypeParameters, resolvedTypeArgs);

                                // Capture for parameter type substitution below (lambda inference).
                                resolvedMethodTypeArgs = resolvedTypeArgs;
                                methodTypeParams = sym.TypeParameters;
                                resolvedGenericMethodSymbol = sym;
                            }
                        }
                        else if(methodSymbol is not null)
                        {
                            // Method is not generic but type arguments were provided.
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                GenericsDiagnostics.MethodArityMismatch.Id.Value,
                                DiagnosticSeverity.Error,
                                $"Method '{memberName}' expects 0 type argument(s) but received {CountTypeArgs(methodCall.TypeArgs)}.",
                                methodCall.TypeArgs,
                                sourceText));
                        }
                        else
                        {
                            // Soundness: methodSymbol is null — the generic method lookup
                            // failed to find the method at all. If memberType is a raw
                            // TypeParameterType, it would leak an unsubstituted type
                            // parameter into the expression cache and eventually resolve
                            // to 'unknown'. Set ErrorType to surface a clear error instead
                            // of silently producing a misleading type.
                            if(memberType is TypeParameterType)
                            {
                                memberType = ErrorType.Instance;
                            }
                        }
                    }

                    // Resolve arguments with lambda target type propagation.
                    if(methodCall.Arguments is not null)
                    {
                        // Look up the method symbol to get parameter types for lambda inference.
                        // When we already resolved a generic method symbol with explicit type args,
                        // use it directly IF it has parameters. Otherwise fall back to finding
                        // the correct overload (e.g., Entity<T>() vs Entity<T>(Action<...>)).
                        ISymbol? methodSymForParams;
                        if(resolvedGenericMethodSymbol is Symbol resolvedSym
                            && resolvedSym.Parameters.Count > 0)
                        {
                            methodSymForParams = resolvedGenericMethodSymbol;
                        }
                        else if(methodTypeParams is not null && methodCall.TypeArgs is not null)
                        {
                            // The resolved generic symbol has no params but the call has args.
                            // Look for an overload with the same type arg count that DOES have params.
                            var providedArity = CountTypeArgs(methodCall.TypeArgs);
                            methodSymForParams = LookupGenericMemberSymbolWithParams(targetType, memberName, providedArity);
                        }
                        else
                        {
                            // For non-generic methods, prefer the overload whose param count
                            // matches the argument count (handles HasMany(string) vs HasMany(Expression<...>)).
                            var argCount = methodCall.Arguments.GetAllExpressions().Length;
                            methodSymForParams = LookupMemberSymbolByParamCount(targetType, memberName, argCount);
                        }

                        // If not found on the type itself, check extension methods.
                        var isExtensionMethod = false;
                        IReadOnlyList<TypeParameterType>? extensionTypeParams = null;
                        if(methodSymForParams is null && extensionRegistryContext is not null)
                        {
                            var extLookupType = targetType;
                            if(extLookupType is ConstructedType extCt)
                            {
                                _ = extCt.GenericDefinition;
                            }

                            var extensions = extensionRegistryContext.GetApplicableExtensions(targetType);
                            var argCount = methodCall.Arguments.GetAllExpressions().Length;
                            ISymbol? firstExtMatch = null;
                            ExtensionBlockInfo? matchedExtBlock = null;
                            foreach(var ext in extensions)
                            {
                                foreach(var m in ext.MemberScope.Members)
                                {
                                    if(m.Name == memberName && m.Kind == SymbolKind.Method)
                                    {
                                        firstExtMatch ??= m;
                                        matchedExtBlock ??= ext;
                                        // For backend (ambient) extension methods with populated Parameters,
                                        // prefer the overload whose param count (minus receiver) matches
                                        // the argument count at the call site.
                                        if(m is Symbol extSym && extSym.Parameters.Count > 0
                                            && extSym.Parameters.Count - 1 == argCount)
                                        {
                                            methodSymForParams = m;
                                            isExtensionMethod = true;
                                            extensionTypeParams = ext.TypeParameters;
                                            break;
                                        }
                                    }
                                }

                                if(methodSymForParams is not null)
                                {
                                    break;
                                }
                            }
                            // Fallback: use first match if no exact param count match.
                            if(methodSymForParams is null && firstExtMatch is not null)
                            {
                                methodSymForParams = firstExtMatch;
                                isExtensionMethod = true;
                                extensionTypeParams = matchedExtBlock?.TypeParameters;
                            }
                        }

                        // If still not found, check ambient members (e.g., List<T>.ForEach).
                        if(methodSymForParams is null && ambientTypeResolver is not null)
                        {
                            var ambientLookupType = targetType is ConstructedType ambCt
                                ? ambCt.GenericDefinition
                                : targetType;
                            if(ambientLookupType is ClassType or StructType or AbstractType)
                            {
                                var ambientMembers = ambientTypeResolver.GetMembers(ambientLookupType);
                                var argCount = methodCall.Arguments.GetAllExpressions().Length;
                                ISymbol? firstAmbientMatch = null;
                                ISymbol? lambdaAmbientMatch = null;
                                foreach(var m in ambientMembers)
                                {
                                    if(m.Name == memberName && m.Kind == SymbolKind.Method)
                                    {
                                        firstAmbientMatch ??= m;
                                        // Prefer the overload with lambda-compatible params and matching param count.
                                        if(m is Symbol ambSym && ambSym.Parameters.Count == argCount
                                            && HasLambdaCompatibleParameter(ambSym))
                                        {
                                            lambdaAmbientMatch = m;
                                            break;
                                        }
                                    }
                                }

                                methodSymForParams = lambdaAmbientMatch ?? firstAmbientMatch;
                            }
                        }

                        IReadOnlyList<IType>? methodParamTypes = null;
                        if(methodSymForParams is not null)
                        {
                            methodParamTypes = ParameterSignature.Extract(methodSymForParams, symbolTable);

                            // Extension methods from CLR assemblies include the 'this' receiver
                            // as the first parameter in Symbol.Parameters. Skip it so argument
                            // indices align with parameter indices correctly.
                            // Mist-defined extensions don't have this issue (AST-based extraction
                            // already excludes the receiver).
                            if(isExtensionMethod && methodParamTypes.Count > 0
                                && methodSymForParams is Symbol { Origin: SymbolOrigin.Backend })
                            {
                                methodParamTypes = methodParamTypes.Skip(1).ToList();
                            }

                            // If the target is a constructed generic type (e.g., List<int>),
                            // substitute type parameters in the extracted parameter types so that
                            // lambda target types use concrete types (e.g., Func<int, void>
                            // instead of Func<T, void>).
                            if(methodParamTypes.Count > 0 && targetType is ConstructedType ctForSubst)
                            {
                                var typeParams = GetTypeParameters(ctForSubst.GenericDefinition);
                                if(typeParams.Count > 0 && typeParams.Count == ctForSubst.TypeArguments.Count)
                                {
                                    var substituted = new IType[methodParamTypes.Count];
                                    var anyChanged = false;
                                    for(var pi = 0; pi < methodParamTypes.Count; pi++)
                                    {
                                        substituted[pi] = SubstituteTypeInMember(methodParamTypes[pi], typeParams, ctForSubst.TypeArguments);
                                        if(!ReferenceEquals(substituted[pi], methodParamTypes[pi]))
                                        {
                                            anyChanged = true;
                                        }
                                    }

                                    if(anyChanged)
                                    {
                                        methodParamTypes = substituted;
                                    }
                                }
                            }

                            // For extension methods on generic receivers, substitute the extension's
                            // receiver type parameters with the target's type arguments.
                            // E.g., HasMany on EntityTypeBuilder<TEntity> with target EntityTypeBuilder<Request>
                            // needs TEntity → Request substituted into the extension's parameter types.
                            if(isExtensionMethod && methodParamTypes.Count > 0
                                && extensionTypeParams is { Count: > 0 }
                                && targetType is ConstructedType extTargetCt)
                            {
                                // The extension's type params correspond to the receiver's generic args.
                                // Map them to the target's concrete type arguments.
                                if(extensionTypeParams.Count <= extTargetCt.TypeArguments.Count)
                                {
                                    var extTypeParamsAsIType = extensionTypeParams.Cast<IType>().ToList();
                                    var substituted = new IType[methodParamTypes.Count];
                                    var anyChanged = false;
                                    for(var pi = 0; pi < methodParamTypes.Count; pi++)
                                    {
                                        substituted[pi] = SubstituteTypeInMember(
                                            methodParamTypes[pi], extTypeParamsAsIType, extTargetCt.TypeArguments);
                                        if(!ReferenceEquals(substituted[pi], methodParamTypes[pi]))
                                        {
                                            anyChanged = true;
                                        }
                                    }

                                    if(anyChanged)
                                    {
                                        methodParamTypes = substituted;
                                    }
                                }
                            }

                            // If the method itself is generic and explicit type arguments were
                            // provided (e.g., Entity<Request>), substitute the method's type
                            // parameters in the parameter types so that lambda target types
                            // use concrete types (e.g., Action<EntityTypeBuilder<Request>>
                            // instead of Action<EntityTypeBuilder<T>>).
                            if(methodParamTypes.Count > 0
                                && resolvedMethodTypeArgs is not null
                                && methodTypeParams is not null)
                            {
                                var substituted = new IType[methodParamTypes.Count];
                                var anyChanged = false;
                                for(var pi = 0; pi < methodParamTypes.Count; pi++)
                                {
                                    substituted[pi] = SubstituteTypeInMember(methodParamTypes[pi], methodTypeParams, resolvedMethodTypeArgs);
                                    if(!ReferenceEquals(substituted[pi], methodParamTypes[pi]))
                                    {
                                        anyChanged = true;
                                    }
                                }

                                if(anyChanged)
                                {
                                    methodParamTypes = substituted;
                                }
                            }
                        }

                        // When the method is generic and no explicit type args were provided,
                        // pass the method's type parameters to enable incremental inference.
                        // This allows multi-lambda patterns like OwnsOne(e => e.QualityTier, qt => {...})
                        // where the second lambda's parameter type depends on inference from the first.
                        IReadOnlyList<IType>? incrementalTypeParams = null;
                        if(resolvedMethodTypeArgs is null && methodSymForParams is Symbol symForIncremental
                            && symForIncremental.TypeParameters.Count > 0)
                        {
                            incrementalTypeParams = symForIncremental.TypeParameters;
                        }

                        ResolveArgumentListWithParameterTypes(methodCall.Arguments, methodParamTypes, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics, incrementalTypeParams);

                        // Post-resolution type argument inference: when the method is generic
                        // and no explicit type args were provided, infer type args from the
                        // resolved argument types and substitute into the return type.
                        // This handles cases like HasMany<TRelated>(e => e.WorkItems) where
                        // TRelated is inferred as WI10 from the lambda's return type.
                        if(resolvedMethodTypeArgs is null && methodSymForParams is Symbol methodSymForInference
                            && methodSymForInference.TypeParameters.Count > 0
                            && ContainsTypeParameter(memberType))
                        {
                            var inferenceArgTypes = CollectResolvedArgumentTypes(methodCall.Arguments, expressionTypes);
                            if(inferenceArgTypes.Count > 0)
                            {
                                var inferParamTypes = ParameterSignature.Extract(methodSymForInference, symbolTable);
                                // Skip receiver param for extension methods.
                                if(isExtensionMethod && inferParamTypes.Count > 0
                                    && methodSymForInference.Origin == SymbolOrigin.Backend)
                                {
                                    inferParamTypes = inferParamTypes.Skip(1).ToList();
                                }

                                var inferenceResult = TypeArgumentInferenceEngine.TryInfer(
                                    methodSymForInference.TypeParameters, inferParamTypes, inferenceArgTypes);
                                if(inferenceResult.Success && inferenceResult.InferredTypeArguments is not null)
                                {
                                    memberType = SubstituteTypeInMember(
                                        memberType, methodSymForInference.TypeParameters, inferenceResult.InferredTypeArguments);
                                }
                            }
                        }
                    }

                    // Auto-unwrap: in a sync context, if the invoked method is async,
                    // unwrap Task<T> to T so the caller sees the inner type.
                    if(!isInAsyncContext && memberType is not ErrorType)
                    {
                        var methodSym = LookupMemberSymbol(targetType, memberName);
                        if(methodSym is Symbol { IsAsync: true } && IsStandardTaskType(memberType))
                        {
                            memberType = UnwrapTaskType(memberType);
                        }
                    }

                    // The result type is the return type of the method (stored as DeclaredType on the member symbol).
                    // ── Slice length inference (mirrors TypeCheckerAnalyzer.TryInferSliceLengthFromCall) ──
                    // When a Slice call is made on a SpanType receiver with a literal
                    // length argument, refine the result to a known-length SpanType so
                    // the inferred variable type carries the correct length.
                    if(memberType is SpanType sliceResultSpan
                        && memberName == "Slice"
                        && methodCall.Arguments is not null
                        && methodCall.Arguments.Arguments.Length >= 1)
                    {
                        var sliceLengthArg = methodCall.Arguments.Arguments[0];
                        var sliceLengthExpr = ArgumentListNodeExtensions.ExtractExpression(sliceLengthArg);
                        var sliceLiteralLength = TryExtractIntegerLiteral(sliceLengthExpr);
                        if(sliceLiteralLength.HasValue)
                        {
                            memberType = new SpanType(
                                sliceResultSpan.ElementType, sliceLiteralLength.Value, sliceResultSpan.IsReadOnly);
                        }
                    }

                    expressionTypes[suffix] = memberType;
                    return memberType;
                }
            case MemberAccessSuffixPostfixSuffixNode memberAccess:
                {
                    var memberName = memberAccess.Name.Lexeme;

                    // Special case: Void.Void → void type instance expression.
                    // The identifier "Void" resolves to the void type via
                    // TryResolveWellKnownType, but the legacy fallback type has
                    // no members. Until the Standard namespace is implicitly
                    // imported, this special case bridges the gap.
                    // We resolve through the stdlib path to get the same type
                    // instance that the `void` keyword resolves to.
                    if(targetType.IsVoid() && memberName == "Void")
                    {
                        // Emit deprecation warning for Void.Void usage.
                        diagnostics.Add(MakeDiagnosticWithLocation(
                            VoidDotVoidDeprecated.Value,
                            DiagnosticSeverity.Warning,
                            "Use 'void' in expression position instead of 'Void.Void' to obtain the Void singleton.",
                            suffix,
                            sourceText));

                        IType voidType;
                        try
                        {
                            var voidGlobalScope = FindGlobalScope(fileScope) ?? fileScope;
                            voidType = ResolveVoidKeyword(voidGlobalScope, symbolTable);
                        }
                        catch(StdlibMissingException)
                        {
                            voidType = targetType;
                        }

                        expressionTypes[suffix] = voidType;
                        return voidType;
                    }

                    var memberType = LookupMemberType(targetType, memberName, ambientTypeResolver, fileScope, symbolTable, sourceText, diagnostics);

                    // Kind-aware validation: property/field access must not resolve to a method.
                    if(memberType is not ErrorType)
                    {
                        var memberSymbol = LookupMemberSymbol(targetType, memberName);
                        if(memberSymbol is not null && memberSymbol.Kind == SymbolKind.Method)
                        {
                            diagnostics.Add(new Diagnostic(
                                PropertyAccessResolvesToMethod,
                                DiagnosticSeverity.Error,
                                PipelineStage.SemanticModelConstruction,
                                $"'{memberName}' is a method and must be invoked with parentheses: '{memberName}()'.",
                                Location: default,
                                CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                                AnalyzerName: null));
                            expressionTypes[suffix] = ErrorType.Instance;
                            return ErrorType.Instance;
                        }
                    }

                    expressionTypes[suffix] = memberType;
                    return memberType;
                }
            case IndexSuffixPostfixSuffixNode indexSuffix:
                {
                    // Resolve the index expression.
                    _ = ResolveExpression(indexSuffix.Index, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    // The result type is the element type of the array.
                    if(targetType is ArrayType arrayType)
                    {
                        expressionTypes[suffix] = arrayType.ElementType;
                        return arrayType.ElementType;
                    }

                    // Check for custom indexer on the target type (e.g., Dictionary<TKey, TValue>).
                    // Look up an indexer symbol ("this[]") in the target type's member scope.
                    var indexerLookupType = targetType is ConstructedType ict ? ict.GenericDefinition : targetType;
                    var indexerMemberScope = indexerLookupType switch
                    {
                        ClassType ct2 => ct2.MemberScope,
                        StructType st2 => st2.MemberScope,
                        AbstractType it2 => it2.MemberScope,
                        _ => null,
                    };

                    if(indexerMemberScope is not null)
                    {
                        ISymbol? indexerSymbol = null;
                        foreach(var member in indexerMemberScope.Members)
                        {
                            if(member.Kind == SymbolKind.Indexer)
                            {
                                indexerSymbol = member;
                                break;
                            }
                        }

                        if(indexerSymbol is not null && indexerSymbol.DeclaredType is { } indexerReturnType)
                        {
                            // Apply type substitution for ConstructedType (e.g., Dictionary<string, int>).
                            if(targetType is ConstructedType ict2)
                            {
                                var typeParams = GetTypeParameters(ict2.GenericDefinition);
                                if(typeParams is not null)
                                {
                                    indexerReturnType = SubstituteTypeParameters(indexerReturnType, typeParams, ict2.TypeArguments);
                                }
                            }

                            expressionTypes[suffix] = indexerReturnType;
                            return indexerReturnType;
                        }
                    }

                    expressionTypes[suffix] = ErrorType.Instance;
                    return ErrorType.Instance;
                }
            case InvocationSuffixPostfixSuffixNode invocation:
                {
                    // Direct invocation (e.g., function call without dot).
                    if(invocation.Arguments is not null)
                    {
                        ResolveArgumentList(invocation.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    // If the target expression's type is a Func constructed type,
                    // the invocation's result type is the Func's return type (last type arg).
                    if(IsFuncType(targetType) && targetType is ConstructedType funcCt)
                    {
                        var returnType = GetFuncReturnType(funcCt);
                        if(!isInAsyncContext && IsStandardTaskType(returnType))
                        {
                            returnType = UnwrapTaskType(returnType);
                        }

                        expressionTypes[suffix] = returnType;
                        return returnType;
                    }

                    // ── delegate-func-conversion: DelegateType invocation ──
                    // When the target expression's type is a DelegateType, the invocation's
                    // result type is the FuncSignature's return type (last type argument).
                    if(targetType is DelegateType delegateType)
                    {
                        var returnType = GetFuncReturnType(delegateType.FuncSignature);
                        if(!isInAsyncContext && IsStandardTaskType(returnType))
                        {
                            returnType = UnwrapTaskType(returnType);
                        }

                        expressionTypes[suffix] = returnType;
                        return returnType;
                    }

                    // ── delegate-func-conversion: BaseDelegateType is NOT invocable ──
                    // System.Delegate cannot be invoked directly. The type checker will
                    // emit the diagnostic; here we resolve to ErrorType to suppress
                    // cascading type errors.
                    if(targetType is BaseDelegateType)
                    {
                        expressionTypes[suffix] = ErrorType.Instance;
                        return ErrorType.Instance;
                    }

                    // The result type is the return type of the target (if it's a method).
                    expressionTypes[suffix] = targetType;
                    return targetType;
                }
            case SwitchExpressionSuffixPostfixSuffixNode switchExpr:
                {
                    // The scrutinee type is the accumulated postfix expression type
                    // (already resolved as targetType by the time this suffix is processed).
                    var scrutineeType = targetType;

                    if(switchExpr.Arms is not null)
                    {
                        // Process the first arm.
                        ResolveSwitchArm(switchExpr.Arms.SwitchArm, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                        // Process remaining arms.
                        foreach(var arm in switchExpr.Arms.SwitchArms)
                        {
                            ResolveSwitchArm(arm, scrutineeType, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    // Determine the unified result type from all arm result expressions.
                    var resultType = DetermineUnifiedSwitchResultType(switchExpr, expressionTypes);
                    expressionTypes[suffix] = resultType;
                    return resultType;
                }
            case OptionalMemberAccessSuffixPostfixSuffixNode optionalMemberAccess:
                {
                    // Task 6.1: Optional chaining member access.
                    // The receiver must be a UnionType containing void. Project to T
                    // (remove void), resolve the member on T, and wrap result as R | void.
                    // Type validation is deferred to the type checker; here we resolve
                    // the member type for downstream consumers.
                    var projectedType = ProjectOptionalType(targetType);
                    if(projectedType is null or ErrorType)
                    {
                        expressionTypes[suffix] = ErrorType.Instance;
                        return ErrorType.Instance;
                    }

                    var memberType = LookupMemberType(projectedType, optionalMemberAccess.Name.Lexeme, ambientTypeResolver, fileScope, symbolTable, sourceText, diagnostics);
                    // Wrap result as R | void (flattened if R already contains void).
                    var wrappedType = WrapTypeWithVoid(memberType, fileScope, symbolTable);
                    expressionTypes[suffix] = wrappedType;
                    return wrappedType;
                }
            case OptionalMethodCallSuffixPostfixSuffixNode optionalMethodCall:
                {
                    // Task 6.1: Optional chaining method call.
                    // The receiver must be a UnionType containing void. Project to T
                    // (remove void), resolve the method on T, and wrap result as R | void.
                    var projectedType = ProjectOptionalType(targetType);
                    if(projectedType is null or ErrorType)
                    {
                        // Still resolve arguments to avoid cascading errors.
                        if(optionalMethodCall.Arguments is not null)
                        {
                            ResolveArgumentList(optionalMethodCall.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }

                        expressionTypes[suffix] = ErrorType.Instance;
                        return ErrorType.Instance;
                    }

                    var memberName = optionalMethodCall.Name.Lexeme;
                    var memberType = LookupMemberType(projectedType, memberName, ambientTypeResolver, fileScope, symbolTable, sourceText, diagnostics);

                    // Handle method-level type arguments.
                    if(optionalMethodCall.TypeArgs is not null)
                    {
                        var optProvidedArity = CountTypeArgs(optionalMethodCall.TypeArgs);
                        var methodSymbol = LookupGenericMemberSymbol(projectedType, memberName, optProvidedArity, fileScope);
                        if(methodSymbol is Symbol sym && sym.TypeParameters.Count > 0)
                        {
                            var hasDependentParams = false;
                            foreach(var tp in sym.TypeParameters)
                            {
                                if(tp is DependentTypeParameterType)
                                {
                                    hasDependentParams = true;
                                    break;
                                }
                            }

                            IReadOnlyList<IType> resolvedTypeArgs;
                            if(hasDependentParams)
                            {
                                var (typeArgs, _) = ResolvePass2TypeArgumentListWithDependents(
                                    optionalMethodCall.TypeArgs, sym.TypeParameters, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                                resolvedTypeArgs = typeArgs;
                            }
                            else
                            {
                                resolvedTypeArgs = ResolvePass2TypeArgumentList(optionalMethodCall.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                            }

                            if(resolvedTypeArgs.Count == sym.TypeParameters.Count)
                            {
                                memberType = SubstituteTypeParameters(memberType, sym.TypeParameters, resolvedTypeArgs);
                            }
                        }
                    }

                    // Resolve arguments.
                    if(optionalMethodCall.Arguments is not null)
                    {
                        ResolveArgumentList(optionalMethodCall.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }

                    // Auto-unwrap: in a sync context, if the invoked method is async,
                    // unwrap Task<T> to T so the caller sees the inner type.
                    if(!isInAsyncContext && memberType is not ErrorType)
                    {
                        var methodSym = LookupMemberSymbol(projectedType, memberName);
                        if(methodSym is Symbol { IsAsync: true } && IsStandardTaskType(memberType))
                        {
                            memberType = UnwrapTaskType(memberType);
                        }
                    }

                    // Wrap result as R | void (flattened if R already contains void).
                    var wrappedType = WrapTypeWithVoid(memberType, fileScope, symbolTable);
                    expressionTypes[suffix] = wrappedType;
                    return wrappedType;
                }
            default:
                return targetType;
        }
    }

    // ─── Optional Chaining Helpers ───────────────────────────────────────

    /// <summary>
    /// Returns true if the given type is VoidType or a union type containing void
    /// (i.e., an optional type like T?). Used for target-type-aware void literal resolution.
    /// </summary>
    private static bool IsVoidOrOptionalType(IType? type)
    {
        if(type is null)
        {
            return false;
        }

        if(type.IsVoid())
        {
            return true;
        }

        if(type is TypeAliasType alias)
        {
            type = alias.UnderlyingType;
        }

        if(type is UnionType union)
        {
            foreach(var constituent in union.Constituents)
            {
                if(constituent.IsVoid())
                {
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Projects an optional type by removing void from a union type.
    /// If the type is a UnionType containing void, returns the non-void portion.
    /// If the type is not a union containing void, returns null (indicating an error).
    /// </summary>
    private static IType? ProjectOptionalType(IType targetType)
    {
        if(targetType is ErrorType)
        {
            return null;
        }

        // Unwrap type aliases to see the underlying union.
        if(targetType is TypeAliasType alias)
        {
            targetType = alias.UnderlyingType;
        }

        if(targetType is UnionType union)
        {
            var hasVoid = false;
            foreach(var constituent in union.Constituents)
            {
                if(constituent.IsVoid())
                {
                    hasVoid = true;
                    break;
                }
            }

            if(hasVoid)
            {
                var nonVoidConstituents = new List<IType>();
                foreach(var constituent in union.Constituents)
                {
                    if(!constituent.IsVoid())
                    {
                        nonVoidConstituents.Add(constituent);
                    }
                }

                if(nonVoidConstituents.Count == 0)
                {
                    return null;
                }

                if(nonVoidConstituents.Count == 1)
                {
                    return nonVoidConstituents[0];
                }

                return new UnionType(nonVoidConstituents);
            }
        }

        // Not a union containing void — the type checker will emit the error.
        // Return the type as-is so the semantic model can still resolve members
        // (the type checker will catch the invalid usage).
        return targetType;
    }

    /// <summary>
    /// Wraps a type with void to produce R | void. If the type already contains
    /// void (is a union with void), returns it unchanged (flattening).
    /// </summary>
    private static IType WrapTypeWithVoid(IType type, Scope fileScope, SymbolTable symbolTable)
    {
        if(type is ErrorType)
        {
            return ErrorType.Instance;
        }

        if(type.IsVoid())
        {
            return type;
        }

        // If R is already a union containing void, return it unchanged.
        if(type is UnionType existingUnion)
        {
            foreach(var constituent in existingUnion.Constituents)
            {
                if(constituent.IsVoid())
                {
                    return type;
                }
            }
        }

        // Resolve the void type from stdlib if available, otherwise use legacy.
        IType voidType;
        try
        {
            var globalScope = FindGlobalScope(fileScope);
            voidType = globalScope is not null
                ? ResolveVoidKeyword(globalScope, symbolTable)
                : LegacyPrimitiveTypes.Void;
        }
        catch(StdlibMissingException)
        {
            voidType = LegacyPrimitiveTypes.Void;
        }

        return new UnionType(new List<IType> { type, voidType });
    }

    /// <summary>
    /// Attempts to look up the Standard.Void type for constructing nullable unions.
    /// Returns null if the stdlib is not loaded (e.g., in minimal test contexts).
    /// </summary>
    private static IType? TryLookupVoidType(Scope fileScope, SymbolTable symbolTable)
    {
        try
        {
            var globalScope = FindGlobalScope(fileScope) ?? fileScope;
            return ResolveVoidKeyword(globalScope, symbolTable);
        }
        catch(StdlibMissingException)
        {
            return LegacyPrimitiveTypes.Void;
        }
    }

    // ─── Switch Arm Resolution ───────────────────────────────────────────

    /// <summary>
    /// Resolves a single switch arm: creates a child scope for pattern variables,
    /// registers pattern variables from the arm's pattern, resolves the guard
    /// expression (if present), and resolves the result expression.
    /// </summary>
    private static void ResolveSwitchArm(
        SwitchArmNode arm,
        IType scrutineeType,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        // Create a child scope for this arm's pattern variables.
        var armScope = new Scope(parent: currentScope);

        // Resolve type references within the pattern (e.g., the type in a type pattern).
        ResolvePattern(arm.Pattern, scrutineeType, armScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

        // Register pattern variables introduced by the arm's pattern into the arm scope.
        // This reuses the same logic used by `is` expressions for pattern variable collection.
        CollectFromPattern(arm.Pattern, scrutineeType, armScope, symbolTable, expressionTypes, fileScope, ambientTypeResolver, sourceText, diagnostics);

        // Resolve the guard expression (if present) within the arm scope.
        // The guard condition is now bounded to VoidCoalescing (below lambda/assignment).
        if(arm.Guard is not null)
        {
            _ = ResolveVoidCoalescing(arm.Guard.Condition, armScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
        }

        // Resolve the result expression within the arm scope.
        _ = ResolveExpression(arm.Result, armScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Determines the unified result type of a switch expression by collecting
    /// all arm result expression types and finding the common type.
    /// </summary>
    /// <remarks>
    /// Algorithm:
    /// <list type="bullet">
    ///   <item>If there are no arms, returns <see cref="UnknownType.Instance"/>.</item>
    ///   <item>If all arms have the same type, returns that type.</item>
    ///   <item>If types differ but share a common base class, returns the common base.</item>
    ///   <item>If no common type exists, returns <see cref="UnknownType.Instance"/>
    ///         (the type checker will report the incompatibility error).</item>
    /// </list>
    /// </remarks>
    private static IType DetermineUnifiedSwitchResultType(
        SwitchExpressionSuffixPostfixSuffixNode switchExpr,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes)
    {
        if(switchExpr.Arms is null)
        {
            return UnknownType.Instance;
        }

        // Collect all arm result expression types.
        var armTypes = new List<IType>();

        if(expressionTypes.TryGetValue(switchExpr.Arms.SwitchArm.Result, out var firstType))
        {
            armTypes.Add(firstType);
        }

        foreach(var arm in switchExpr.Arms.SwitchArms)
        {
            if(expressionTypes.TryGetValue(arm.Result, out var armType))
            {
                armTypes.Add(armType);
            }
        }

        if(armTypes.Count == 0)
        {
            return UnknownType.Instance;
        }

        // Check if all arms have the same type.
        var unified = armTypes[0];
        var allSame = true;
        for(var i = 1; i < armTypes.Count; i++)
        {
            if(!TypesMatch(unified, armTypes[i]))
            {
                allSame = false;
                break;
            }
        }

        if(allSame)
        {
            return unified;
        }

        // Types differ — attempt to find a common base class.
        // Walk the base type chain of the first type and check if all other
        // types are assignable to each ancestor. The first ancestor that all
        // types are assignable to is the common base.
        var commonBase = FindCommonBaseType(armTypes);
        return commonBase ?? UnknownType.Instance;
    }

    /// <summary>
    /// Returns true if two types are considered the same for result type unification.
    /// Uses display name comparison (consistent with the identity check in
    /// <see cref="TypeCheckerAnalyzer.IsAssignable"/>).
    /// </summary>
    private static bool TypesMatch(IType a, IType b)
    {
        if(ReferenceEquals(a, b))
        {
            return true;
        }

        if(a is ErrorType || b is ErrorType)
        {
            return true; // Suppress cascading errors.
        }

        return a.DisplayName == b.DisplayName;
    }

    /// <summary>
    /// Attempts to find a common base type for a list of types by walking
    /// the inheritance chain of the first type and checking if all other
    /// types share that ancestor.
    /// </summary>
    /// <returns>The common base type, or null if none exists.</returns>
    private static IType? FindCommonBaseType(List<IType> types)
    {
        if(types.Count == 0)
        {
            return null;
        }

        // Skip ErrorType entries — they should not influence the result.
        var nonErrorTypes = new List<IType>();
        foreach(var t in types)
        {
            if(t is not ErrorType)
            {
                nonErrorTypes.Add(t);
            }
        }

        if(nonErrorTypes.Count == 0)
        {
            return ErrorType.Instance;
        }

        if(nonErrorTypes.Count == 1)
        {
            return nonErrorTypes[0];
        }

        // Try to find a common base by walking the first type's ancestor chain.
        // For each candidate ancestor, check if all other types are assignable to it.
        var first = nonErrorTypes[0];
        if(first is ClassType firstClass)
        {
            var candidate = firstClass.BaseType as ClassType;
            while(candidate is not null)
            {
                var allAssignable = true;
                for(var i = 1; i < nonErrorTypes.Count; i++)
                {
                    if(!IsSubtypeOf(nonErrorTypes[i], candidate))
                    {
                        allAssignable = false;
                        break;
                    }
                }

                if(allAssignable)
                {
                    return candidate;
                }

                candidate = candidate.BaseType as ClassType;
            }
        }

        return null;
    }

    /// <summary>
    /// Checks if <paramref name="source"/> is a subtype of <paramref name="target"/>
    /// by walking the base type chain. Used for common base type resolution in
    /// switch expression result type unification.
    /// </summary>
    private static bool IsSubtypeOf(IType source, ClassType target)
    {
        if(ReferenceEquals(source, target))
        {
            return true;
        }

        if(source.DisplayName == target.DisplayName)
        {
            return true;
        }

        if(source is ClassType sourceClass)
        {
            var current = sourceClass.BaseType as ClassType;
            while(current is not null)
            {
                if(ReferenceEquals(current, target) || current.DisplayName == target.DisplayName)
                {
                    return true;
                }

                current = current.BaseType as ClassType;
            }
        }

        return false;
    }

    // ─── Primary Expression Resolution ───────────────────────────────────

    private static IType ResolvePrimary(
        PrimaryNode node,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        IType result;

        switch(node)
        {
            case IntegerLiteralExpressionPrimaryNode intLit:
                result = ResolveIntegerLiteralType(intLit.IntegerLiteral.Lexeme, fileScope, symbolTable);
                break;

            case HexLiteralExpressionPrimaryNode hexLit:
                result = ResolveIntegerLiteralType(hexLit.HexLiteral.Lexeme, fileScope, symbolTable);
                break;

            case BinaryLiteralExpressionPrimaryNode binLit:
                result = ResolveIntegerLiteralType(binLit.BinaryLiteral.Lexeme, fileScope, symbolTable);
                break;

            case FloatLiteralExpressionPrimaryNode floatLit:
                result = ResolveFloatLiteralType(floatLit.FloatLiteral.Lexeme, fileScope, symbolTable);
                break;

            case StringLiteralExpressionPrimaryNode:
                result = ResolvePrimitiveByKeyword("string", fileScope, symbolTable);
                break;

            case RegexLiteralExpressionPrimaryNode:
                result = ResolvePrimitiveByKeyword("regex", fileScope, symbolTable);
                break;

            case InterpolatedStringExpressionPrimaryNode interpolated:
                // Resolve all expression parts within the interpolated string.
                foreach(var part in interpolated.InterpolatedString.Parts)
                {
                    if(part is ExpressionPartInterpolatedPartNode exprPart)
                    {
                        _ = ResolveExpression(exprPart.Expression, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    }
                }

                result = ResolvePrimitiveByKeyword("string", fileScope, symbolTable);
                break;

            case CharLiteralExpressionPrimaryNode:
                result = ResolvePrimitiveByKeyword("char", fileScope, symbolTable);
                break;

            case TrueLiteralExpressionPrimaryNode:
                result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                break;

            case FalseLiteralExpressionPrimaryNode:
                result = ResolvePrimitiveByKeyword("bool", fileScope, symbolTable);
                break;

            case ThisExpressionPrimaryNode:
                if(isStatic)
                {
                    diagnostics.Add(MakeDiagnosticWithLocation(
                        "MIST_INVALID_THIS",
                        DiagnosticSeverity.Error,
                        "'this' cannot be used in a static context.",
                        node,
                        sourceText));
                    result = ErrorType.Instance;
                }
                else
                {
                    result = enclosingType;
                }

                break;

            case FieldKeywordExpressionPrimaryNode:
                {
                    // Resolve 'field' keyword to the backing field symbol of the enclosing property.
                    // Walk the scope chain to find the enclosing property symbol.
                    var backingFieldType = ResolveFieldKeyword(currentScope);
                    result = backingFieldType;
                    break;
                }

            case ArrayCreationExpressionPrimaryNode arrayCreation:
                {
                    var elementType = ResolveElementTypeRef(arrayCreation.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    _ = ResolveExpression(arrayCreation.Size, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    var literalSize = TryExtractIntegerLiteral(arrayCreation.Size);
                    result = literalSize.HasValue
                        ? new ArrayType(elementType, literalSize.Value)
                        : new ArrayType(elementType);
                    break;
                }

            case StackallocExpressionPrimaryNode stackallocExpr:
                {
                    // Mirrors ArrayCreationExpressionPrimaryNode: resolve the element type
                    // and the size expression, extract a literal size, and build a SpanType.
                    // A literal size N yields the known-length Span<T, N>; a runtime size
                    // yields the unknown-length Span<T> (R4.1, R4.2).
                    var spanElementType = ResolveElementTypeRef(stackallocExpr.Type, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    _ = ResolveExpression(stackallocExpr.Size, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                    var stackallocLiteralSize = TryExtractIntegerLiteral(stackallocExpr.Size);

                    // The read-only target context is threaded the same way the builder
                    // threads _emptyArrayTargetType for array literals: when the declared
                    // target type at the stackalloc position is a ReadOnlySpan<T, Length>
                    // SpanType, the result is a read-only span; otherwise it is a mutable
                    // Span (R4.3).
                    var stackallocIsReadOnly = emptyArrayTargetType is SpanType { IsReadOnly: true };

                    result = stackallocLiteralSize.HasValue
                        ? new SpanType(spanElementType, stackallocLiteralSize.Value, stackallocIsReadOnly)
                        : new SpanType(spanElementType, stackallocIsReadOnly);
                    break;
                }

            case ObjectCreationExpressionPrimaryNode objCreation:
                {
                    var typeName = ExtractQualifiedName(objCreation.Type, sourceText);

                    // ── Special case: new Array<T, Size>(fn) ─────────────────────
                    // The bootstrap Array<TValue, Length:ZeroOrPositiveInt> class is
                    // not resolvable via normal name lookup (its dependent type param
                    // uses a refinement type alias). Route "Array" or "Standard.Array"
                    // with 2 type arguments to produce an ArrayType directly.
                    var typeArgCount = objCreation.TypeArgs is not null ? CountTypeArgs(objCreation.TypeArgs) : 0;
                    IType createdType;
                    if((typeName == "Array" || typeName == "Standard.Array") && typeArgCount == 2)
                    {
                        // Resolve the type arguments.
                        var typeArgList = objCreation.TypeArgs!;
                        var firstTypeRef = typeArgList.GetTypeReference();
                        var elementType = ResolveTypeReference(firstTypeRef, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);

                        // Resolve the size (second type argument — a literal integer for the array length).
                        long? knownLength = null;
                        var typeArgNodes = new List<TypeArgumentNode> { typeArgList.TypeArgument };
                        foreach(var extra in typeArgList.TypeArguments)
                        {
                            typeArgNodes.Add(extra);
                        }

                        if(typeArgNodes.Count > 1 && typeArgNodes[1] is IntegerLiteralTypeArgumentTypeArgumentNode intLitArg)
                        {
                            if(long.TryParse(intLitArg.Literal.Lexeme, out var size))
                            {
                                knownLength = size;
                            }
                        }

                        createdType = knownLength.HasValue
                            ? new ArrayType(elementType, knownLength.Value)
                            : new ArrayType(elementType);

                        // Resolve arguments with Func<int, TValue> as the lambda target type.
                        if(objCreation.Arguments is not null)
                        {
                            var globalScopeForFunc = FindGlobalScope(fileScope) ?? fileScope;
                            try
                            {
                                var funcDefinition = LookupQualifiedStdlibType(globalScopeForFunc, symbolTable, "Standard.Func", 2);
                                var intType = ResolvePrimitiveByKeyword("int", fileScope, symbolTable);
                                var funcType = new ConstructedType(funcDefinition, new IType[] { intType, elementType });
                                var ctorParamTypes = new List<IType> { funcType };
                                ResolveArgumentList(objCreation.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics, ctorParamTypes);
                            }
                            catch(StdlibMissingException)
                            {
                                // Fallback: resolve without lambda target type.
                                ResolveArgumentList(objCreation.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            }
                        }

                        result = createdType;
                        break;
                    }

                    createdType = ResolveNamedType(typeName, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics,
                        typeArgumentCount: typeArgCount);

                    // Check for abstract type instantiation.
                    if(createdType is ClassType { IsAbstract: true } abstractClass)
                    {
                        diagnostics.Report(SemanticDiagnostics.AbstractInstantiation, default, sourceText?.Path ?? "<unknown>", (object)abstractClass.DisplayName);
                    }

                    // Handle type arguments on new expressions (e.g., new Box<int>()).
                    if(objCreation.TypeArgs is not null)
                    {
                        createdType = ResolvePass2TypeArguments(createdType, typeName, objCreation.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    }

                    if(objCreation.Arguments is not null)
                    {
                        // Look up constructor parameter types for void value literal
                        // target-type threading (e.g., new Result<void>(void, true)).
                        IReadOnlyList<IType>? ctorParamTypes = null;
                        var ctorLookupType = createdType is ConstructedType ict ? ict.GenericDefinition : createdType;
                        var ctorMemberScope = ctorLookupType switch
                        {
                            ClassType ct => ct.MemberScope,
                            StructType st => st.MemberScope,
                            _ => null,
                        };
                        if(ctorMemberScope is not null)
                        {
                            var ctorSymbol = ctorMemberScope.Members
                                .FirstOrDefault(m => m.Kind == SymbolKind.Constructor);
                            if(ctorSymbol is not null)
                            {
                                ctorParamTypes = ParameterSignature.Extract(ctorSymbol, symbolTable);
                                // Apply type argument substitution for generic types.
                                if(createdType is ConstructedType constructedType && ctorParamTypes.Count > 0)
                                {
                                    var typeParams = GetTypeParameters(constructedType.GenericDefinition);
                                    if(typeParams is not null && typeParams.Count == constructedType.TypeArguments.Count)
                                    {
                                        var substituted = new List<IType>(ctorParamTypes.Count);
                                        foreach(var pt in ctorParamTypes)
                                        {
                                            substituted.Add(SubstituteTypeParameters(pt, typeParams, constructedType.TypeArguments));
                                        }

                                        ctorParamTypes = substituted;
                                    }
                                }
                            }
                        }

                        ResolveArgumentList(objCreation.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics, ctorParamTypes);
                    }

                    // Resolve value expressions in the property initializer block.
                    if(objCreation.Initializer is not null && objCreation.Initializer.Assignments is not null)
                    {
                        var assignments = objCreation.Initializer.Assignments;
                        ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        foreach(var assignment in assignments.PropertyAssignments)
                        {
                            ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    result = createdType;
                    break;
                }

            case ObjectCreationExpressionNoArgsPrimaryNode objCreationNoArgs:
                {
                    var typeName = ExtractQualifiedName(objCreationNoArgs.Type, sourceText);
                    var createdType = ResolveNamedType(typeName, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics,
                        typeArgumentCount: objCreationNoArgs.TypeArgs is not null ? CountTypeArgs(objCreationNoArgs.TypeArgs) : 0);

                    // Check for abstract type instantiation.
                    if(createdType is ClassType { IsAbstract: true } abstractClass)
                    {
                        diagnostics.Report(SemanticDiagnostics.AbstractInstantiation, default, sourceText?.Path ?? "<unknown>", (object)abstractClass.DisplayName);
                    }

                    // Handle type arguments on new expressions (e.g., new Box<int> { ... }).
                    if(objCreationNoArgs.TypeArgs is not null)
                    {
                        createdType = ResolvePass2TypeArguments(createdType, typeName, objCreationNoArgs.TypeArgs, fileScope, ambientTypeResolver, symbolTable, sourceText, diagnostics);
                    }

                    // Resolve value expressions in the property initializer block.
                    if(objCreationNoArgs.Initializer.Assignments is not null)
                    {
                        var assignments = objCreationNoArgs.Initializer.Assignments;
                        ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        foreach(var assignment in assignments.PropertyAssignments)
                        {
                            ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    result = createdType;
                    break;
                }

            case TargetTypedNewExpressionPrimaryNode targetNew:
                {
                    var targetType = targetTypedNewTargetType;
                    if(targetType is null or ErrorType)
                    {
                        // No target type available — resolve arguments for IDE support
                        // but record ErrorType. The type checker will emit the diagnostic.
                        if(targetNew.Arguments is not null)
                        {
                            ResolveArgumentList(targetNew.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }

                        if(targetNew.Initializer?.Assignments is not null)
                        {
                            var assignments = targetNew.Initializer.Assignments;
                            ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            foreach(var assignment in assignments.PropertyAssignments)
                            {
                                ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            }
                        }

                        result = ErrorType.Instance;
                        break;
                    }

                    // Resolve arguments using constructor parameter types from target type.
                    if(targetNew.Arguments is not null)
                    {
                        IReadOnlyList<IType>? ctorParamTypes = null;
                        var ctorLookupType = targetType is ConstructedType ict ? ict.GenericDefinition : targetType;
                        var ctorMemberScope = ctorLookupType switch
                        {
                            ClassType ct => ct.MemberScope,
                            StructType st => st.MemberScope,
                            _ => null,
                        };
                        if(ctorMemberScope is not null)
                        {
                            var ctorSymbol = ctorMemberScope.Members
                                .FirstOrDefault(m => m.Kind == SymbolKind.Constructor);
                            if(ctorSymbol is not null)
                            {
                                ctorParamTypes = ParameterSignature.Extract(ctorSymbol, symbolTable);
                                // Apply type argument substitution for generic types.
                                if(targetType is ConstructedType constructedType && ctorParamTypes.Count > 0)
                                {
                                    var typeParams = GetTypeParameters(constructedType.GenericDefinition);
                                    if(typeParams is not null && typeParams.Count == constructedType.TypeArguments.Count)
                                    {
                                        var substituted = new List<IType>(ctorParamTypes.Count);
                                        foreach(var pt in ctorParamTypes)
                                        {
                                            substituted.Add(SubstituteTypeParameters(pt, typeParams, constructedType.TypeArguments));
                                        }

                                        ctorParamTypes = substituted;
                                    }
                                }
                            }
                        }

                        ResolveArgumentList(targetNew.Arguments, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics, ctorParamTypes);
                    }

                    // Resolve property initializer values if present.
                    if(targetNew.Initializer?.Assignments is not null)
                    {
                        var assignments = targetNew.Initializer.Assignments;
                        ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        foreach(var assignment in assignments.PropertyAssignments)
                        {
                            ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    result = targetType;
                    break;
                }

            case TargetTypedNewExpressionNoArgsPrimaryNode targetNewNoArgs:
                {
                    var targetType = targetTypedNewTargetType;
                    if(targetType is null or ErrorType)
                    {
                        // No target type available — resolve initializer for IDE support
                        // but record ErrorType. The type checker will emit the diagnostic.
                        if(targetNewNoArgs.Initializer.Assignments is not null)
                        {
                            var assignments = targetNewNoArgs.Initializer.Assignments;
                            ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            foreach(var assignment in assignments.PropertyAssignments)
                            {
                                ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                            }
                        }

                        result = ErrorType.Instance;
                        break;
                    }

                    // Resolve property initializer values.
                    if(targetNewNoArgs.Initializer.Assignments is not null)
                    {
                        var assignments = targetNewNoArgs.Initializer.Assignments;
                        ResolvePropertyAssignmentValue(assignments.PropertyAssignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        foreach(var assignment in assignments.PropertyAssignments)
                        {
                            ResolvePropertyAssignmentValue(assignment, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        }
                    }

                    result = targetType;
                    break;
                }

            case TupleLiteralExpressionPrimaryNode tupleLit:
                {
                    // Collect all elements: First + Rest + Additional.
                    var tupleElementCount = 2 + tupleLit.TupleLiteralElements.Length;
                    var tupleElementTypes = new List<IType>(tupleElementCount);
                    var tupleElementNames = new List<string?>(tupleElementCount);
                    var tupleHasAnyName = false;

                    void resolveTupleLiteralElement(TupleLiteralElementNode element)
                    {
                        switch(element)
                        {
                            case NamedTupleLiteralElementTupleLiteralElementNode named:
                                tupleElementTypes.Add(ResolveExpression(named.Value, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics));
                                tupleElementNames.Add(named.Name.Lexeme);
                                tupleHasAnyName = true;
                                break;
                            case UnnamedTupleLiteralElementTupleLiteralElementNode unnamed:
                                tupleElementTypes.Add(ResolveExpression(unnamed.Value, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics));
                                tupleElementNames.Add(null);
                                break;
                        }
                    }

                    resolveTupleLiteralElement(tupleLit.First);
                    resolveTupleLiteralElement(tupleLit.Rest);
                    foreach(var additional in tupleLit.TupleLiteralElements)
                    {
                        resolveTupleLiteralElement(additional);
                    }

                    result = new TupleType(tupleElementTypes, tupleHasAnyName ? tupleElementNames : null);
                    break;
                }

            case ParenthesizedExpressionPrimaryNode paren:
                result = ResolveExpression(paren.Inner, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                break;

            case IdentifierExpressionPrimaryNode identifier:
                {
                    var name = identifier.Name.Lexeme;
                    var symbol = currentScope.Lookup(name);

                    if(symbol is null)
                    {
                        // Try to resolve as a type name (for static access like Console.WriteLine).
                        var typeAsSymbol = ResolveIdentifierAsType(name, fileScope, ambientTypeResolver, symbolTable);
                        if(typeAsSymbol is not null)
                        {
                            result = typeAsSymbol;
                        }
                        // Check if the identifier is a namespace root (for fully-qualified
                        // type references like Newtonsoft.Json.JsonConvert.SerializeObject).
                        else if(ambientTypeResolver is not null && IsNamespaceOrPrefix(name, ambientTypeResolver))
                        {
                            result = new NamespaceReferenceType(name);
                        }
                        // In a non-static instance context, bare identifiers may refer
                        // to inherited members from the base class chain. Walk the
                        // BaseType chain to find the member, mirroring what
                        // LookupMemberType does for explicit this.member access.
                        else if(!isStatic && enclosingType is ClassType enclosingClass)
                        {
                            IType? inheritedMemberType = null;
                            ISymbol? inheritedSymbol = null;
                            var ancestor = enclosingClass.BaseType as ClassType;
                            while(ancestor is not null)
                            {
                                foreach(var m in ancestor.MemberScope.Members)
                                {
                                    if(m.Name == name)
                                    {
                                        inheritedMemberType = m.DeclaredType ?? ErrorType.Instance;
                                        inheritedSymbol = m;
                                        break;
                                    }
                                }

                                if(inheritedMemberType is not null)
                                {
                                    break;
                                }

                                ancestor = ancestor.BaseType as ClassType;
                            }

                            if(inheritedMemberType is not null)
                            {
                                result = inheritedMemberType;

                                // Register usage site so downstream analysis (e.g., auto-unwrap
                                // for async methods) can resolve the symbol from the identifier node.
                                if(inheritedSymbol is not null && inheritedSymbol.Kind is SymbolKind.Method)
                                {
                                    symbolTable.RegisterUsageSite(identifier, inheritedSymbol);
                                }
                            }
                            else
                            {
                                diagnostics.Add(MakeDiagnosticWithLocation(
                                    "MIST_UNDEFINED_IDENTIFIER",
                                    DiagnosticSeverity.Error,
                                    $"The name '{name}' does not exist in the current context.",
                                    identifier,
                                    sourceText));
                                result = ErrorType.Instance;
                            }
                        }
                        else
                        {
                            diagnostics.Add(MakeDiagnosticWithLocation(
                                "MIST_UNDEFINED_IDENTIFIER",
                                DiagnosticSeverity.Error,
                                $"The name '{name}' does not exist in the current context.",
                                identifier,
                                sourceText));
                            result = ErrorType.Instance;
                        }
                    }
                    else
                    {
                        result = symbol.DeclaredType ?? ErrorType.Instance;

                        // Register the usage-site identifier node → resolved symbol mapping
                        // so that downstream analyzers (e.g., OwnershipAnalyzer) can resolve
                        // identifier references at call sites via GetDeclaredSymbol.
                        if(symbol.Kind is SymbolKind.LocalVariable or SymbolKind.Parameter or SymbolKind.Field or SymbolKind.Method)
                        {
                            symbolTable.RegisterUsageSite(identifier, symbol);
                        }
                    }

                    break;
                }

            case TypeLiteralExpressionPrimaryNode typeLiteral:
                {
                    // Resolve the TypeReference to get the referenced type (for validation).
                    var referencedType = ResolveTypeReference(
                        typeLiteral.TypeRef, fileScope, ambientTypeResolver,
                        symbolTable, sourceText, diagnostics);

                    // Target-type-aware void resolution: when the type literal is `void`
                    // and the target type is VoidType (or a union containing void, i.e. optional),
                    // resolve as the Void singleton value rather than the metatype Type.
                    if(typeLiteral.TypeRef is { SingleTypeRefs.Length: 0, First: VoidSingleTypeRefSingleTypeRefNode } && IsVoidOrOptionalType(voidLiteralTargetType))
                    {
                        result = referencedType; // VoidType.Instance
                        break;
                    }

                    // Existing behavior: resolve as Standard.Type (metatype).
                    try
                    {
                        var typeGlobalScope = FindGlobalScope(fileScope) ?? fileScope;
                        result = ResolveTypeKeyword(typeGlobalScope, symbolTable);
                    }
                    catch(StdlibMissingException)
                    {
                        result = LegacyPrimitiveTypes.Type;
                    }

                    break;
                }

            case DefaultExpressionPrimaryNode defaultExpr:
                {
                    // Resolve the explicit type reference in default(TypeName).
                    // The resolved type becomes the expression type. The type
                    // checker will later validate that the type is defaultable.
                    result = ResolveTypeReference(
                        defaultExpr.Type, fileScope, ambientTypeResolver,
                        symbolTable, sourceText, diagnostics);
                    break;
                }

            case DefaultLiteralExpressionPrimaryNode:
                {
                    // Bare 'default' — the type must be inferred from context
                    // (e.g., assignment target type, return type, parameter type).
                    // Record as ErrorType here; the type checker will resolve
                    // the actual type from context or emit a diagnostic if
                    // inference is not possible.
                    result = ErrorType.Instance;
                    break;
                }

            case EmptyArrayLiteralExpressionPrimaryNode:
                {
                    // Empty array literal [] — if a target type is available (from variable
                    // declaration annotation) and is an ArrayType, use the target element type.
                    // Otherwise, produce ErrorType (the type checker will emit a diagnostic
                    // indicating that empty array literals require an explicit element type).
                    result = emptyArrayTargetType is ArrayType targetArrayType ? new ArrayType(targetArrayType.ElementType, 0) : ErrorType.Instance;

                    break;
                }

            case ArrayLiteralExpressionPrimaryNode arrayLiteral:
                {
                    // Resolve all element expressions and produce an ArrayType
                    // with the common element type.
                    var elementType = ResolveExpression(arrayLiteral.First, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                    foreach(var elem in arrayLiteral.Expressions)
                    {
                        var elemType = ResolveExpression(elem, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
                        if(!TypesMatch(elementType, elemType))
                        {
                            // Types differ — attempt to find a common base type.
                            var commonBase = FindCommonBaseType(new List<IType> { elementType, elemType });
                            elementType = commonBase ?? elementType;
                        }
                    }

                    // Element count = 1 (First) + rest (Expressions).
                    var elementCount = 1 + arrayLiteral.Expressions.Length;
                    result = new ArrayType(elementType, elementCount);
                    break;
                }

            case AnonymousTypeExpressionPrimaryNode anonTypeExpr:
                {
                    // Resolve anonymous type expression: new { Name = expr, projection, ... }
                    // Collect property names and types, validate constraints, build AnonymousType.
                    var propertyNames = new List<string>();
                    var propertyTypes = new List<IType>();
                    var seenNames = new HashSet<string>(StringComparer.Ordinal);

                    void processAnonymousProperty(AnonymousPropertyNode prop)
                    {
                        switch(prop)
                        {
                            case ExplicitAnonymousPropertyAnonymousPropertyNode explicit_:
                                {
                                    var name = explicit_.Name.Lexeme;
                                    var propType = ResolveExpression(explicit_.Value, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                                    if(!seenNames.Add(name))
                                    {
                                        diagnostics.Add(MakeDiagnosticWithTokenLocation(
                                            "MIST_ANON_DUPLICATE_PROP",
                                            DiagnosticSeverity.Error,
                                            $"Anonymous type already contains a property named '{name}'.",
                                            explicit_.Name,
                                            sourceText));
                                        propertyNames.Add(name);
                                        propertyTypes.Add(ErrorType.Instance);
                                    }
                                    else
                                    {
                                        propertyNames.Add(name);
                                        propertyTypes.Add(propType);
                                    }

                                    break;
                                }

                            case ProjectedAnonymousPropertyAnonymousPropertyNode projected:
                                {
                                    var projection = projected.Projection;

                                    // Resolve the projection expression type.
                                    var projType = ResolvePostfix(projection, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

                                    // Extract the inferred property name from the postfix node.
                                    string? inferredName = null;

                                    if(projection.Suffix.Length == 0 && projection.Target is IdentifierExpressionPrimaryNode identTarget)
                                    {
                                        // Simple identifier projection: new { variable }
                                        inferredName = identTarget.Name.Lexeme;
                                    }
                                    else if(projection.Suffix.Length > 0 && projection.Suffix[^1] is MemberAccessSuffixPostfixSuffixNode memberAccess)
                                    {
                                        // Member access projection: new { expr.Member }
                                        inferredName = memberAccess.Name.Lexeme;
                                    }

                                    if(inferredName is null)
                                    {
                                        // Cannot infer name from literals, method calls, etc.
                                        diagnostics.Add(MakeDiagnosticWithLocation(
                                            "MIST_ANON_NO_PROJECTION_NAME",
                                            DiagnosticSeverity.Error,
                                            "Cannot infer property name from expression; use explicit `Name = expr` form.",
                                            projection,
                                            sourceText));
                                        propertyNames.Add("<error>");
                                        propertyTypes.Add(ErrorType.Instance);
                                    }
                                    else if(!seenNames.Add(inferredName))
                                    {
                                        diagnostics.Add(MakeDiagnosticWithLocation(
                                            "MIST_ANON_DUPLICATE_PROP",
                                            DiagnosticSeverity.Error,
                                            $"Anonymous type already contains a property named '{inferredName}'.",
                                            projection,
                                            sourceText));
                                        propertyNames.Add(inferredName);
                                        propertyTypes.Add(ErrorType.Instance);
                                    }
                                    else
                                    {
                                        propertyNames.Add(inferredName);
                                        propertyTypes.Add(projType);
                                    }

                                    break;
                                }
                        }
                    }

                    // Process the first property.
                    processAnonymousProperty(anonTypeExpr.Properties.AnonymousProperty);

                    // Process additional properties.
                    foreach(var additional in anonTypeExpr.Properties.AnonymousPropertys)
                    {
                        processAnonymousProperty(additional);
                    }

                    // Construct the AnonymousType and register it.
                    result = new AnonymousType(propertyNames, propertyTypes);
                    break;
                }

            default:
                result = ErrorType.Instance;
                break;
        }

        expressionTypes[node] = result;
        return result;
    }

    /// <summary>
    /// Tries to resolve an identifier as a type name (for static member access).
    /// Returns the type if found, null otherwise.
    /// </summary>
    private static IType? ResolveIdentifierAsType(
        string name,
        Scope fileScope,
        IAmbientTypeResolver? ambientTypeResolver,
        SymbolTable symbolTable)
    {
        // Check well-known types.
        var wellKnown = TryResolveWellKnownType(name);
        if(wellKnown is not null)
        {
            return wellKnown;
        }

        // Check scope chain for type symbols (local → file → namespace → global).
        var symbol = fileScope.Lookup(name);
        if(symbol is not null && (symbol.Kind == SymbolKind.Class || symbol.Kind == SymbolKind.Struct || symbol.Kind == SymbolKind.Abstract || symbol.Kind == SymbolKind.TypeAlias || symbol.Kind == SymbolKind.Enum))
        {
            return symbol.DeclaredType;
        }

        // Check imported namespaces — first user-defined, then ambient.
        var importedNamespaces = CollectImportedNamespaces(fileScope);
        var globalScope = FindGlobalScope(fileScope);

        // Check user-defined namespace scopes.
        foreach(var ns in importedNamespaces)
        {
            var nsScope = globalScope is not null
                ? FindExistingNamespaceScope(globalScope, symbolTable, ns)
                : null;

            if(nsScope is not null)
            {
                foreach(var member in nsScope.Members)
                {
                    if(member.Name == name &&
                        (member.Kind == SymbolKind.Class || member.Kind == SymbolKind.Struct || member.Kind == SymbolKind.Abstract || member.Kind == SymbolKind.TypeAlias || member.Kind == SymbolKind.Enum))
                    {
                        return member.DeclaredType;
                    }
                }
            }
        }

        // Check imported namespaces via ambient resolver.
        if(ambientTypeResolver is not null)
        {
            foreach(var ns in importedNamespaces)
            {
                var resolvedType = ambientTypeResolver.ResolveType(ns, name);
                if(resolvedType is not null)
                {
                    RegisterAmbientTypeInScope(resolvedType, name, fileScope, ambientTypeResolver);
                    return resolvedType;
                }
            }
        }

        return null;
    }

    // ─── Helper Methods ──────────────────────────────────────────────────

    /// <summary>
    /// Looks up a member by name on a given type. Searches the type's member scope
    /// and, for ambient types, queries the ambient resolver.
    /// </summary>
    /// <remarks>
    /// DEPRECATED: This function is being replaced by <see cref="ResolveMethodMember"/>
    /// for method resolution. It is retained for non-method member access (properties,
    /// fields, namespace refs, enum access, etc.) and will be removed once all callers
    /// are migrated.
    /// </remarks>
    private static IType LookupMemberType(
        IType targetType,
        string memberName,
        IAmbientTypeResolver? ambientTypeResolver,
        Scope fileScope,
        SymbolTable symbolTable,
        SourceText? sourceText,
        DiagnosticBag diagnostics)
    {
        if(targetType is ErrorType)
        {
            return ErrorType.Instance;
        }

        // Namespace-qualified access: when the target is a NamespaceReferenceType, the
        // member name is the next segment in a fully-qualified reference. Try to resolve
        // it as a sub-namespace or as a type within the namespace.
        if(targetType is NamespaceReferenceType nsRef && ambientTypeResolver is not null)
        {
            var qualifiedNs = $"{nsRef.NamespaceName}.{memberName}";

            // First check if the qualified name is a type in the namespace.
            var resolvedType = ambientTypeResolver.ResolveType(nsRef.NamespaceName, memberName);
            if(resolvedType is not null)
            {
                RegisterAmbientTypeInScope(resolvedType, memberName, fileScope, ambientTypeResolver);
                return resolvedType;
            }

            // Otherwise check if it's a sub-namespace.
            if(IsNamespaceOrPrefix(qualifiedNs, ambientTypeResolver))
            {
                return new NamespaceReferenceType(qualifiedNs);
            }

            // Neither a type nor a namespace — emit diagnostic.
            diagnostics.Report(SemanticDiagnostics.UndefinedMember, default, sourceText?.Path ?? "<unknown>", (object)nsRef.NamespaceName, memberName);
            return ErrorType.Instance;
        }

        // Type aliases are transparent — unwrap to the underlying type
        // before member lookup so that alias-typed variables have full
        // member access (Requirement 5.1).
        if(targetType is TypeAliasType aliasTarget)
        {
            targetType = aliasTarget.UnderlyingType;
        }

        // ── Union type with void: project to non-void constituents ──
        // When the receiver is a T | void union, skip void constituents and
        // resolve the member on the non-void portion. This allows member access
        // on optional types (T?) without requiring explicit ?. syntax.
        if(targetType is UnionType unionTarget)
        {
            var nonVoidConstituents = unionTarget.Constituents
                .Where(c => !c.IsVoid())
                .ToList();

            // If there's exactly one non-void constituent, resolve the member on it.
            if(nonVoidConstituents.Count == 1 && unionTarget.Constituents.Any(c => c.IsVoid()))
            {
                return LookupMemberType(
                    nonVoidConstituents[0], memberName, ambientTypeResolver,
                    fileScope, symbolTable, sourceText, diagnostics);
            }
        }

        // ── Constrained type parameter member access (Requirements 6.1–6.4, 6.7) ──
        // When the receiver is a TypeParameterType with constraints, look up the
        // member in the constraint types (abstract types, base class).
        if(targetType is TypeParameterType typeParam && typeParam.Constraints is not null)
        {
            var constraints = typeParam.Constraints;

            // Check abstract type constraints.
            foreach(var ifaceConstraint in constraints.AbstractConstraints)
            {
                if(ifaceConstraint is AbstractType iface)
                {
                    var member = iface.MemberScope.Lookup(memberName);
                    if(member is not null)
                    {
                        return member.DeclaredType ?? ErrorType.Instance;
                    }

                    // Also check inherited abstract types transitively.
                    var inherited = LookupInheritedInterfaceMember(iface, memberName);
                    if(inherited is not null)
                    {
                        return inherited;
                    }
                }
            }

            // Check base class constraint (including inherited members).
            if(constraints.BaseClassConstraint is ClassType baseClass)
            {
                var current = baseClass;
                while(current is not null)
                {
                    foreach(var m in current.MemberScope.Members)
                    {
                        if(m.Name == memberName)
                        {
                            return m.DeclaredType ?? ErrorType.Instance;
                        }
                    }

                    current = current.BaseType as ClassType;
                }
            }

            // If constraints exist but none provide the member, fall through
            // to the MIST_UNDEFINED_MEMBER diagnostic below.
        }

        // ── Associated type slot member access (Requirements 5.1–5.3) ──
        // When the receiver is an AssociatedTypeSlotType, look up the member
        // in the slot's constraint types (abstract types, base class).
        // This allows method calls and member access on values whose type is
        // an associated type reference (e.g., T.Enumerator).
        if(targetType is AssociatedTypeSlotType slotTarget)
        {
            var slotConstraints = slotTarget.Constraints;
            if(slotConstraints is not null)
            {
                // Check abstract type constraints.
                foreach(var ifaceConstraint in slotConstraints.AbstractConstraints)
                {
                    var ifaceType = ifaceConstraint is ConstructedType ctIface
                        ? ctIface.GenericDefinition as AbstractType
                        : ifaceConstraint as AbstractType;

                    if(ifaceType is not null)
                    {
                        var member = ifaceType.MemberScope.Lookup(memberName);
                        if(member is not null)
                        {
                            return member.DeclaredType ?? ErrorType.Instance;
                        }

                        // Also check inherited abstract types transitively.
                        var inherited = LookupInheritedInterfaceMember(ifaceType, memberName);
                        if(inherited is not null)
                        {
                            return inherited;
                        }
                    }
                }

                // Check base class constraint (including inherited members).
                if(slotConstraints.BaseClassConstraint is ClassType slotBaseClass)
                {
                    var current = slotBaseClass;
                    while(current is not null)
                    {
                        foreach(var m in current.MemberScope.Members)
                        {
                            if(m.Name == memberName)
                            {
                                return m.DeclaredType ?? ErrorType.Instance;
                            }
                        }

                        current = current.BaseType as ClassType;
                    }
                }
            }

            // If constraints exist but none provide the member, fall through
            // to the MIST_UNDEFINED_MEMBER diagnostic below.
        }

        // Enum member access: EnumName.MemberName resolves to the EnumType itself.
        // Enum members are static fields in the enum's MemberScope. If the member
        // exists, the result type is the EnumType (not the underlying type).
        // If the member does not exist, report MIST_SB_0082.
        if(targetType is EnumType enumTarget)
        {
            var enumMember = enumTarget.MemberScope.Lookup(memberName);
            if(enumMember is not null)
            {
                return enumTarget;
            }

            diagnostics.Add(new Diagnostic(
                UndefinedEnumMemberAccess,
                DiagnosticSeverity.Error,
                PipelineStage.SemanticModelConstruction,
                $"Enum '{enumTarget.DisplayName}' does not contain a member '{memberName}'.",
                Location: default,
                CompilationUnitPath: sourceText?.Path ?? "<unknown>",
                AnalyzerName: null));

            return ErrorType.Instance;
        }

        // For ConstructedType, unwrap to the generic definition and look up the member,
        // then substitute type parameters with type arguments.
        IReadOnlyList<IType>? constructedTypeParams = null;
        IReadOnlyList<IType>? constructedTypeArgs = null;
        if(targetType is ConstructedType constructedTarget)
        {
            constructedTypeParams = constructedTarget.GenericDefinition switch
            {
                ClassType ct2 => ct2.TypeParameters,
                StructType st2 => st2.TypeParameters,
                AbstractType it2 => it2.TypeParameters,
                _ => null,
            };
            constructedTypeArgs = constructedTarget.TypeArguments;
            targetType = constructedTarget.GenericDefinition;
        }

        // Get the member scope from the target type.
        var memberScope = targetType switch
        {
            ClassType ct => ct.MemberScope,
            StructType st => st.MemberScope,
            AbstractType it => it.MemberScope,
            NewtypeType nt => nt.MemberScope,
            ArrayType => null, // Arrays use special handling.
            _ => null,
        };

        // For string type with no members in its scope (legacy fallback
        // ClassType from LegacyPrimitiveTypes.String), look up members
        // via the stdlib Standard.String type or the ambient resolver.
        // When stdlib IS loaded, the string type is the stdlib ClassType
        // with a populated member scope, so this path only fires for the
        // legacy fallback in tests without stdlib.
        if(IsStringLikeType(targetType) && (memberScope is null || !memberScope.Members.Any(m => m.Name == memberName)))
        {
            var globalScope = FindGlobalScope(fileScope);
            if(globalScope is not null)
            {
                try
                {
                    var stdlibString = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.String");
                    if(stdlibString is ClassType stdlibStringClass)
                    {
                        foreach(var m in stdlibStringClass.MemberScope.Members)
                        {
                            if(m.Name == memberName)
                            {
                                return m.DeclaredType ?? ErrorType.Instance;
                            }
                        }
                    }
                }
                catch(StdlibMissingException)
                {
                    // Stdlib not loaded — fall through to ambient resolver fallback below.
                }
            }

            // Legacy fallback: try the ambient resolver (for backward compat
            // with tests that don't load stdlib).
            if(ambientTypeResolver is not null)
            {
                var resolvedStringType = ambientTypeResolver.ResolveType("System", "String");
                if(resolvedStringType is not null)
                {
                    var members = ambientTypeResolver.GetMembers(resolvedStringType);
                    foreach(var member in members)
                    {
                        if(member.Name == memberName)
                        {
                            return member.DeclaredType ?? ErrorType.Instance;
                        }
                    }
                }
            }
        }

        // For array types, look up Length via the stdlib Standard.Array<T> type.
        // After Task 42, Array is no longer an ambient type — it's a stdlib type.
        if(targetType is ArrayType arrayTargetForMember)
        {
            // Special case: .Length on arrays returns int. Standard.Array defines
            // Length as a type parameter (not a member property), so we resolve it
            // directly to Int32 here.
            if(memberName == "Length")
            {
                var globalScope2 = FindGlobalScope(fileScope);
                if(globalScope2 is not null)
                {
                    try
                    {
                        var int32Type = LookupQualifiedStdlibType(globalScope2, symbolTable, "Standard.Int32");
                        if(int32Type is not null)
                        {
                            return int32Type;
                        }
                    }
                    catch(StdlibMissingException)
                    {
                        // Fall through to legacy lookup below.
                    }
                }
                // Legacy fallback: return a basic int type.
                return LegacyPrimitiveTypes.Int;
            }

            // Special case: .AsSpan() on arrays returns a Span<T> with unknown length.
            // This is an extension method from System.MemoryExtensions but is resolved
            // directly here to avoid the ambient extension scanner complexity.
            if(memberName == "AsSpan")
            {
                return new SpanType(arrayTargetForMember.ElementType, isReadOnly: false);
            }

            var globalScope = FindGlobalScope(fileScope);
            if(globalScope is not null)
            {
                try
                {
                    var stdlibArray = LookupQualifiedStdlibType(globalScope, symbolTable, "Standard.Array");
                    if(stdlibArray is ClassType stdlibArrayClass)
                    {
                        foreach(var m in stdlibArrayClass.MemberScope.Members)
                        {
                            if(m.Name == memberName)
                            {
                                return m.DeclaredType ?? ErrorType.Instance;
                            }
                        }

                        // Standard.Array is loaded but doesn't have this member.
                        // Do NOT fall through to System.Array ambient resolver — that
                        // would expose static methods (like Array.Reverse) as instance
                        // members. Let extension method lookup handle it instead.
                    }
                }
                catch(StdlibMissingException)
                {
                    // Stdlib not loaded — skip. Extension method lookup will handle
                    // any methods not in Standard.Array. Do NOT fall through to
                    // System.Array ambient resolver — that would expose static methods
                    // (like Array.Reverse) as instance members.
                }
            }
            // If globalScope is null, skip the System.Array fallback entirely.
            // Extension method lookup will handle any methods not in Standard.Array.
        }

        // Span member access: mirrors the Array member lookup above.
        // SpanType is a dedicated IType (no member scope), so .Length and .Slice
        // are resolved directly here — exactly as Array resolves .Length above.
        if(targetType is SpanType spanMemberTarget)
        {
            if(memberName == "Length")
            {
                var globalScope2 = FindGlobalScope(fileScope);
                if(globalScope2 is not null)
                {
                    try
                    {
                        var int32Type = LookupQualifiedStdlibType(globalScope2, symbolTable, "Standard.Int32");
                        if(int32Type is not null)
                        {
                            return int32Type;
                        }
                    }
                    catch(StdlibMissingException) { }
                }

                return LegacyPrimitiveTypes.Int;
            }

            if(memberName == "Slice")
            {
                // Slice returns a SpanType of the same kind with unknown length.
                // The TypeCheckerAnalyzer infers the precise length from the call
                // site arguments (literal → known, else unknown).
                return new SpanType(spanMemberTarget.ElementType, spanMemberTarget.IsReadOnly);
            }

            // Fall through to ambient resolver for other members (e.g., GetEnumerator).
            if(ambientTypeResolver is not null)
            {
                var clrTypeName = spanMemberTarget.IsReadOnly ? "ReadOnlySpan" : "Span";
                var resolvedClrType = ambientTypeResolver.ResolveType("System", clrTypeName);
                if(resolvedClrType is not null)
                {
                    var members = ambientTypeResolver.GetMembers(resolvedClrType);
                    foreach(var member in members)
                    {
                        if(member.Name == memberName)
                        {
                            return member.DeclaredType ?? ErrorType.Instance;
                        }
                    }
                }
            }
        }

        // Tuple element access: resolve ItemN positional access and named access.
        if(targetType is TupleType tupleTarget)
        {
            // Check positional access: Item1, Item2, ..., ItemN (1-indexed).
            if(memberName.StartsWith("Item", StringComparison.Ordinal)
                && int.TryParse(memberName.AsSpan(4), out var itemIndex)
                && itemIndex >= 1
                && itemIndex <= tupleTarget.Arity)
            {
                return tupleTarget.ElementTypes[itemIndex - 1];
            }

            // Check named access: match against declared element names.
            if(tupleTarget.ElementNames is not null)
            {
                for(var i = 0; i < tupleTarget.ElementNames.Count; i++)
                {
                    if(tupleTarget.ElementNames[i] == memberName)
                    {
                        return tupleTarget.ElementTypes[i];
                    }
                }
            }

            // No match — report MIST_TC_0063 (undefined tuple member access).
            diagnostics.Report(SemanticDiagnostics.UndefinedTupleMember, default, sourceText?.Path ?? "<unknown>", (object)tupleTarget.DisplayName, memberName);

            return ErrorType.Instance;
        }

        // Anonymous type property access: look up property by name in the ordered list.
        if(targetType is AnonymousType anonTarget)
        {
            for(var i = 0; i < anonTarget.PropertyNames.Count; i++)
            {
                if(anonTarget.PropertyNames[i] == memberName)
                {
                    return anonTarget.PropertyTypes[i];
                }
            }

            // Property not found — report undefined member.
            diagnostics.Report(SemanticDiagnostics.UndefinedMember, default, sourceText?.Path ?? "<unknown>", (object)anonTarget.DisplayName, memberName);

            return ErrorType.Instance;
        }

        // Search the type's member scope, walking the BaseType chain for class types.
        if(targetType is ClassType classTarget)
        {
            var current = classTarget;
            while(current is not null)
            {
                // Search only the direct members of this class's scope.
                foreach(var m in current.MemberScope.Members)
                {
                    if(m.Name == memberName)
                    {
                        var memberType = m.DeclaredType ?? ErrorType.Instance;
                        return SubstituteMemberTypeIfNeeded(memberType, constructedTypeParams, constructedTypeArgs);
                    }
                }

                // If the type has ambient members, try the ambient resolver.
                if(ambientTypeResolver is not null)
                {
                    var ambientMembers = ambientTypeResolver.GetMembers(current);
                    foreach(var m in ambientMembers)
                    {
                        if(m.Name == memberName)
                        {
                            // Skip static methods during instance member lookup —
                            // static methods are only reachable via the type name,
                            // not via an instance. This prevents e.g. Array.Reverse
                            // from shadowing Enumerable.Reverse<T> extension method.
                            if(m is Symbol { IsStatic: true, Kind: SymbolKind.Method })
                            {
                                continue;
                            }

                            var memberType = m.DeclaredType ?? ErrorType.Instance;
                            return SubstituteMemberTypeIfNeeded(memberType, constructedTypeParams, constructedTypeArgs);
                        }
                    }
                }

                current = current.BaseType as ClassType;
            }

            // ── Default method fallback for class types (Phase 3) ──────────────
            // If the member was not found on the class hierarchy, search the
            // abstract types' DefaultMethods transitively. This enables Rust-style
            // semantics where defaults are callable directly on the concrete type.
            var classDefaultResult = LookupDefaultMethodInAbstracts(classTarget.Abstracts, memberName);
            if(classDefaultResult is not null)
            {
                return SubstituteMemberTypeIfNeeded(classDefaultResult, constructedTypeParams, constructedTypeArgs);
            }
        }
        else if(memberScope is not null)
        {
            var member = memberScope.Lookup(memberName);
            if(member is not null)
            {
                var memberType = member.DeclaredType ?? ErrorType.Instance;
                return SubstituteMemberTypeIfNeeded(memberType, constructedTypeParams, constructedTypeArgs);
            }

            // For abstract types, walk inherited abstract types transitively.
            if(targetType is AbstractType abstractTarget)
            {
                var result = LookupInheritedInterfaceMember(abstractTarget, memberName);
                if(result is not null)
                {
                    return SubstituteMemberTypeIfNeeded(result, constructedTypeParams, constructedTypeArgs);
                }
            }

            // ── Default method fallback for struct types (Phase 3) ─────────────
            // Same as the class case: if a struct implements abstract types with
            // default methods, those defaults are callable directly on the struct.
            if(targetType is StructType structTarget)
            {
                var structDefaultResult = LookupDefaultMethodInAbstracts(structTarget.Abstracts, memberName);
                if(structDefaultResult is not null)
                {
                    return SubstituteMemberTypeIfNeeded(structDefaultResult, constructedTypeParams, constructedTypeArgs);
                }
            }
        }

        // ── Extension member lookup fallback (Task 7.1 + 7.2 + 7.6) ────────
        // Before emitting MIST_UNDEFINED_MEMBER, check the extension registry
        // for applicable extension members matching the name.
        // Abstract-type receivers are allowed because .NET extension methods
        // targeting abstracts (e.g., LINQ on IEnumerable, DI on IServiceCollection)
        // are the primary API consumption pattern and must resolve as instance calls.
        // Task 7.2: Collect ALL candidates and apply specificity ordering.
        var isUnwrappedFromConstructed = constructedTypeParams is not null && constructedTypeArgs is not null;
        if(extensionRegistryContext is not null)
        {
            // Use the original target type (before ConstructedType unwrapping)
            // for the extension registry query. If the original was a
            // ConstructedType, reconstruct it; otherwise use targetType as-is.
            var lookupType = (constructedTypeParams is not null && constructedTypeArgs is not null)
                ? new ConstructedType(targetType, constructedTypeArgs)
                : targetType;

            // Task 7.7: When the static type is `unknown`, only search universal extensions.
            // Type-specific extensions should NOT be included because we can't verify
            // they're applicable when the concrete type is not known at compile time.
            // Task 7.8: When the static type is a union type (A | B), only include
            // extensions applicable to ALL constituents. Universal extensions always apply.
            var applicableExtensions = lookupType is UnknownType
                ? extensionRegistryContext.UniversalExtensions
                : lookupType is UnionType unionType
                    ? extensionRegistryContext.GetApplicableExtensionsForUnion(unionType.Constituents)
                    : extensionRegistryContext.GetApplicableExtensions(lookupType);

            // Filter by namespace visibility: only include extensions whose
            // ContainingNamespace is null (top-level) or is in the current
            // file's imported namespaces.
            var importedNamespaces = CollectImportedNamespaces(fileScope);

            // Collect ALL matching extension candidates (receiver type + member type).
            var candidates = new List<(IType ReceiverType, IType MemberType)>();

            foreach(var ext in applicableExtensions)
            {
                // Namespace visibility check.
                if(ext.ContainingNamespace is not null && !importedNamespaces.Contains(ext.ContainingNamespace))
                {
                    continue;
                }

                // Search the extension block's member scope for a matching member.
                var extMember = ext.MemberScope.Lookup(memberName);
                if(extMember is not null)
                {
                    var memberType = extMember.DeclaredType ?? ErrorType.Instance;

                    // Task 7.3: Generic extension type inference.
                    // If the extension block has type parameters, attempt to unify
                    // the extension's receiver type pattern with the actual receiver type.
                    if(ext.TypeParameters.Count > 0)
                    {
                        var bindings = TryUnifyReceiverType(ext.ReceiverType, lookupType, ext.TypeParameters);
                        if(bindings is null)
                        {
                            // Unification failed — silently exclude this extension.
                            continue;
                        }

                        // Substitute the inferred type arguments into the member's declared type.
                        memberType = SubstituteTypeInMember(memberType, ext.TypeParameters, bindings);
                    }

                    candidates.Add((ext.ReceiverType, memberType));
                }
            }

            if(candidates.Count == 1)
            {
                // Single candidate — use it directly.
                return candidates[0].MemberType;
            }

            if(candidates.Count > 1)
            {
                // Deduplicate candidates that originate from structurally identical
                // receiver types (e.g., the same abstract type projected from multiple
                // assemblies creating separate AbstractType instances).
                var deduplicated = new List<(IType ReceiverType, IType MemberType)> { candidates[0] };
                for(var i = 1; i < candidates.Count; i++)
                {
                    var isDuplicate = false;
                    for(var j = 0; j < deduplicated.Count; j++)
                    {
                        if(AreStructurallyEquivalentReceivers(candidates[i].ReceiverType, deduplicated[j].ReceiverType))
                        {
                            isDuplicate = true;
                            break;
                        }
                    }

                    if(!isDuplicate)
                    {
                        deduplicated.Add(candidates[i]);
                    }
                }

                candidates = deduplicated;

                if(candidates.Count == 1)
                {
                    return candidates[0].MemberType;
                }

                // Apply specificity ordering: find the most-specific candidate.
                var bestIndex = 0;
                var ambiguous = false;

                for(var i = 1; i < candidates.Count; i++)
                {
                    var comparison = CompareReceiverSpecificity(candidates[bestIndex].ReceiverType, candidates[i].ReceiverType);
                    if(comparison > 0)
                    {
                        // Current best is less specific than candidate i → i becomes new best.
                        bestIndex = i;
                        ambiguous = false;
                    }
                    else if(comparison == 0)
                    {
                        // Equally specific → potential ambiguity.
                        ambiguous = true;
                    }
                    // comparison < 0 means current best is already more specific — keep it.
                }

                // Verify the best candidate is strictly more specific than ALL others.
                if(!ambiguous)
                {
                    for(var i = 0; i < candidates.Count; i++)
                    {
                        if(i == bestIndex)
                        {
                            continue;
                        }

                        var cmp = CompareReceiverSpecificity(candidates[bestIndex].ReceiverType, candidates[i].ReceiverType);
                        if(cmp >= 0)
                        {
                            ambiguous = true;
                            break;
                        }
                    }
                }

                if(!ambiguous)
                {
                    return candidates[bestIndex].MemberType;
                }

                // Ambiguity: emit MIST_TC_0082.
                var candidateDescriptions = string.Join(", ", candidates.Select(c => $"extension({c.ReceiverType.DisplayName})"));
                diagnostics.Report(SemanticDiagnostics.AmbiguousExtensionMethod, default, sourceText?.Path ?? "<unknown>",
                    (object)$"Ambiguous extension method resolution: member '{memberName}' is provided by multiple equally-specific extension blocks: {candidateDescriptions}.");

                return ErrorType.Instance;
            }

            // ── Static extension member lookup (Task 7.4) ─────────────────
            // When instance extension lookup finds no candidates, also search
            // for static extension members using exact type match only.
            // Static extension members are callable via TypeName.MemberName.
            var exactExtensions = extensionRegistryContext.GetExactExtensions(lookupType);
            var staticCandidates = new List<(IType ReceiverType, IType MemberType)>();

            foreach(var ext in exactExtensions)
            {
                // Namespace visibility check.
                if(ext.ContainingNamespace is not null && !importedNamespaces.Contains(ext.ContainingNamespace))
                {
                    continue;
                }

                // Search the extension block's member scope for a matching member.
                var extMember = ext.MemberScope.Lookup(memberName);
                if(extMember is null)
                {
                    continue;
                }

                // Filter: only consider members marked static.
                var declaringNode = symbolTable.GetDeclaringNode(extMember);
                if(!IsExtensionMemberStatic(declaringNode))
                {
                    continue;
                }

                var memberType = extMember.DeclaredType ?? ErrorType.Instance;

                // Generic extension type inference (same rules as instance lookup).
                if(ext.TypeParameters.Count > 0)
                {
                    var bindings = TryUnifyReceiverType(ext.ReceiverType, lookupType, ext.TypeParameters);
                    if(bindings is null)
                    {
                        continue;
                    }

                    memberType = SubstituteTypeInMember(memberType, ext.TypeParameters, bindings);
                }

                staticCandidates.Add((ext.ReceiverType, memberType));
            }

            if(staticCandidates.Count == 1)
            {
                return staticCandidates[0].MemberType;
            }

            if(staticCandidates.Count > 1)
            {
                // Apply specificity ordering for static candidates.
                var bestIndex = 0;
                var ambiguous = false;

                for(var i = 1; i < staticCandidates.Count; i++)
                {
                    var comparison = CompareReceiverSpecificity(staticCandidates[bestIndex].ReceiverType, staticCandidates[i].ReceiverType);
                    if(comparison > 0)
                    {
                        bestIndex = i;
                        ambiguous = false;
                    }
                    else if(comparison == 0)
                    {
                        ambiguous = true;
                    }
                }

                if(!ambiguous)
                {
                    for(var i = 0; i < staticCandidates.Count; i++)
                    {
                        if(i == bestIndex)
                        {
                            continue;
                        }

                        var cmp = CompareReceiverSpecificity(staticCandidates[bestIndex].ReceiverType, staticCandidates[i].ReceiverType);
                        if(cmp >= 0)
                        {
                            ambiguous = true;
                            break;
                        }
                    }
                }

                if(!ambiguous)
                {
                    return staticCandidates[bestIndex].MemberType;
                }

                // Ambiguity among static extension members.
                var staticCandidateDescriptions = string.Join(", ", staticCandidates.Select(c => $"extension({c.ReceiverType.DisplayName})"));
                diagnostics.Report(SemanticDiagnostics.AmbiguousExtensionMethod, default, sourceText?.Path ?? "<unknown>",
                    (object)$"Ambiguous extension method resolution: static member '{memberName}' is provided by multiple equally-specific extension blocks: {staticCandidateDescriptions}.");

                return ErrorType.Instance;
            }
        }

        // Use the original target type display name for the diagnostic (including type args).
        var diagnosticTypeName = (constructedTypeParams is not null && constructedTypeArgs is not null)
            ? $"{targetType.DisplayName}<{string.Join(", ", constructedTypeArgs.Select(a => a.DisplayName))}>"
            : targetType.DisplayName;

        diagnostics.Report(SemanticDiagnostics.UndefinedMember, default, sourceText?.Path ?? "<unknown>", (object)diagnosticTypeName, memberName);

        return ErrorType.Instance;
    }

    /// <summary>
    /// Compares two extension receiver types for specificity.
    /// Returns:
    ///   negative value if <paramref name="r1"/> is more specific than <paramref name="r2"/>,
    ///   positive value if <paramref name="r2"/> is more specific than <paramref name="r1"/>,
    ///   zero if they are equally specific (ambiguous).
    /// </summary>
    /// <remarks>
    /// Specificity rules:
    /// - <c>unknown</c> is always less specific than any concrete type.
    /// - If R1 is assignable to R2 but not vice versa → R1 is more specific (return negative).
    /// - If R2 is assignable to R1 but not vice versa → R2 is more specific (return positive).
    /// - If neither is assignable to the other → equally specific (ambiguous, return 0).
    /// - If both are assignable to each other (same type) → equally specific (return 0).
    /// </remarks>
    private static int CompareReceiverSpecificity(IType r1, IType r2)
    {
        // Same type reference — equally specific.
        if(ReferenceEquals(r1, r2))
        {
            return 0;
        }

        // Special case: unknown is always less specific than any concrete type.
        var r1IsUnknown = r1 is UnknownType;
        var r2IsUnknown = r2 is UnknownType;

        if(r1IsUnknown && !r2IsUnknown)
        {
            return 1; // r2 is more specific.
        }

        if(r2IsUnknown && !r1IsUnknown)
        {
            return -1; // r1 is more specific.
        }

        if(r1IsUnknown && r2IsUnknown)
        {
            return 0; // Both unknown — equally specific.
        }

        // Check assignability in both directions.
        var r1AssignableToR2 = IsReceiverAssignableTo(r1, r2);
        var r2AssignableToR1 = IsReceiverAssignableTo(r2, r1);

        if(r1AssignableToR2 && !r2AssignableToR1)
        {
            return -1; // r1 is more specific (it fits into r2 but not vice versa).
        }

        if(r2AssignableToR1 && !r1AssignableToR2)
        {
            return 1; // r2 is more specific.
        }

        // Both assignable to each other, or neither assignable → equally specific (ambiguous).
        return 0;
    }

    /// <summary>
    /// Determines whether <paramref name="source"/> is assignable to <paramref name="target"/>
    /// for the purposes of extension receiver specificity comparison.
    /// A type is assignable to another if it is a subtype (via base type chain or abstract type implementation).
    /// </summary>
    private static bool IsReceiverAssignableTo(IType source, IType target)
    {
        // Same reference — trivially assignable.
        if(ReferenceEquals(source, target))
        {
            return true;
        }

        // Everything is assignable to unknown.
        if(target is UnknownType)
        {
            return true;
        }

        // Nothing is assignable from unknown to a concrete type.
        if(source is UnknownType)
        {
            return false;
        }

        // Check base type chain for class types.
        if(source is ClassType sourceClass)
        {
            // Walk the base type chain.
            var current = sourceClass.BaseType;
            while(current is not null)
            {
                if(ReferenceEquals(current, target))
                {
                    return true;
                }

                current = (current as ClassType)?.BaseType;
            }

            // Check abstract type implementations.
            foreach(var iface in sourceClass.Abstracts)
            {
                if(ReferenceEquals(iface, target))
                {
                    return true;
                }
            }
        }

        // Check struct abstract type implementations.
        if(source is StructType sourceStruct)
        {
            foreach(var iface in sourceStruct.Abstracts)
            {
                if(ReferenceEquals(iface, target))
                {
                    return true;
                }
            }
        }

        // Check ConstructedType: walk the generic definition's base chain.
        // E.g., EntityTypeBuilder<T> (ConstructedType) → EntityTypeBuilder (ClassType base).
        if(source is ConstructedType sourceCt && sourceCt.GenericDefinition is ClassType sourceCtClass)
        {
            // The source ConstructedType is assignable to its own generic definition.
            if(ReferenceEquals(sourceCtClass, target) || sourceCtClass.DisplayName == target.DisplayName)
            {
                return true;
            }

            // Walk the base type chain of the generic definition.
            var current = sourceCtClass.BaseType;
            while(current is not null)
            {
                if(ReferenceEquals(current, target) || current.DisplayName == target.DisplayName)
                {
                    return true;
                }

                current = (current as ClassType)?.BaseType;
            }
        }

        // Check plain ClassType assignable to a ConstructedType's generic definition.
        // E.g., EntityTypeBuilder (ClassType) IS assignable to EntityTypeBuilder<T> (ConstructedType)
        // only if it's the same type or a base — but a non-generic base is NOT assignable to
        // a more-specific generic derived type. So this direction is false (correctly not handled).

        return false;
    }

    /// <summary>
    /// Determines whether two receiver types are structurally equivalent.
    /// Used to deduplicate extension candidates that originate from the same logical
    /// abstract type projected as separate AbstractType instances (e.g., from multiple assemblies).
    /// </summary>
    private static bool AreStructurallyEquivalentReceivers(IType r1, IType r2)
    {
        if(ReferenceEquals(r1, r2))
        {
            return true;
        }

        // Both plain abstractType: compare by name + namespace.
        if(r1 is AbstractType i1 && r2 is AbstractType i2)
        {
            return i1.DisplayName == i2.DisplayName
                && i1.ContainingNamespace == i2.ContainingNamespace;
        }

        // Both ConstructedType with abstract type generic definitions.
        if(r1 is ConstructedType ct1 && r2 is ConstructedType ct2)
        {
            if(ct1.GenericDefinition is AbstractType gi1 && ct2.GenericDefinition is AbstractType gi2)
            {
                return gi1.DisplayName == gi2.DisplayName
                    && gi1.ContainingNamespace == gi2.ContainingNamespace
                    && ct1.TypeArguments.Count == ct2.TypeArguments.Count;
            }
        }

        return false;
    }

    /// <summary>
    /// Determines whether an extension member's declaring node has the <c>static</c> modifier.
    /// Used during static extension member lookup (Task 7.4) to filter for static members only.
    /// </summary>
    private static bool IsExtensionMemberStatic(Storm.Runtime.SyntaxNode? declaringNode)
    {
        return declaringNode switch
        {
            MethodDeclarationNode md => md.Modifiers.Any(m => m is StaticModifierModifierNode),
            BlockPropertyPropertyDeclarationNode bp => bp.Modifiers.Any(m => m is StaticModifierModifierNode),
            ExpressionBodiedPropertyPropertyDeclarationNode ep => ep.Modifiers.Any(m => m is StaticModifierModifierNode),
            _ => false,
        };
    }

    /// <summary>
    /// Attempts to unify an extension's receiver type pattern with the actual receiver type,
    /// extracting type argument bindings for the extension's type parameters.
    /// </summary>
    /// <param name="pattern">The extension's receiver type pattern (e.g., the resolved type for <c>List&lt;T&gt;</c>).</param>
    /// <param name="actual">The actual receiver type at the call site (e.g., <c>List&lt;int&gt;</c>).</param>
    /// <param name="typeParameters">The extension block's declared type parameters.</param>
    /// <returns>
    /// A list of concrete type bindings (one per type parameter, in order) if unification succeeds;
    /// <c>null</c> if unification fails.
    /// </returns>
    private static IReadOnlyList<IType>? TryUnifyReceiverType(
        IType pattern,
        IType actual,
        IReadOnlyList<IType> typeParameters)
    {
        // Build a dictionary to collect bindings: type parameter name → concrete type.
        var bindings = new Dictionary<string, IType>();

        if(!UnifyTypes(pattern, actual, typeParameters, bindings))
        {
            return null;
        }

        // Ensure all type parameters have been bound.
        var result = new IType[typeParameters.Count];
        for(var i = 0; i < typeParameters.Count; i++)
        {
            var (paramName, _) = GetTypeParameterNameAndOrdinal(typeParameters[i]);
            if(!bindings.TryGetValue(paramName, out var bound))
            {
                return null; // Not all type parameters could be inferred.
            }

            result[i] = bound;
        }

        return result;
    }

    /// <summary>
    /// Recursively unifies a type pattern with an actual type, collecting type parameter bindings.
    /// </summary>
    /// <returns><c>true</c> if unification succeeds; <c>false</c> otherwise.</returns>
    private static bool UnifyTypes(
        IType pattern,
        IType actual,
        IReadOnlyList<IType> typeParameters,
        Dictionary<string, IType> bindings)
    {
        // Case 1: The pattern is a type parameter — bind it to the actual type.
        if(pattern is TypeParameterType tpt)
        {
            // Verify this is one of the extension's own type parameters.
            var isExtensionTypeParam = false;
            for(var i = 0; i < typeParameters.Count; i++)
            {
                var (paramName, paramOrdinal) = GetTypeParameterNameAndOrdinal(typeParameters[i]);
                if(tpt.Name == paramName && tpt.Ordinal == paramOrdinal)
                {
                    isExtensionTypeParam = true;
                    break;
                }
            }

            if(isExtensionTypeParam)
            {
                // If already bound, check consistency.
                if(bindings.TryGetValue(tpt.Name, out var existing))
                {
                    return ReferenceEquals(existing, actual);
                }

                bindings[tpt.Name] = actual;
                return true;
            }

            // Not one of our type parameters — must match exactly.
            return ReferenceEquals(pattern, actual);
        }

        // Case 2: The pattern is a ConstructedType (e.g., List<T>) — the actual must also
        // be a ConstructedType with the same generic definition and matching arity.
        if(pattern is ConstructedType patternConstructed)
        {
            if(actual is ConstructedType actualConstructed)
            {
                // Generic definitions must match.
                if(!ReferenceEquals(patternConstructed.GenericDefinition, actualConstructed.GenericDefinition))
                {
                    // The generic definitions differ — check if the actual type implements
                    // the pattern's interface through its Abstracts list. This handles cases
                    // like IQueryable<TSource> (pattern) matching DbSet<Request> (actual) where
                    // DbSet<T> implements IQueryable<T>.
                    if(patternConstructed.GenericDefinition is AbstractType patternAbstractDef)
                    {
                        var actualAbstracts = actualConstructed.GenericDefinition switch
                        {
                            ClassType ct => ct.Abstracts,
                            StructType st => st.Abstracts,
                            AbstractType at => at.Abstracts,
                            _ => null
                        };

                        if(actualAbstracts is not null)
                        {
                            foreach(var abs in actualAbstracts)
                            {
                                if(abs is ConstructedType absCtImpl)
                                {
                                    // Check if this abstract's GenericDefinition matches the pattern's.
                                    var genDefMatches = ReferenceEquals(absCtImpl.GenericDefinition, patternAbstractDef)
                                        || (absCtImpl.GenericDefinition is AbstractType absGenDef
                                            && absGenDef.DisplayName == patternAbstractDef.DisplayName
                                            && absGenDef.ContainingNamespace == patternAbstractDef.ContainingNamespace
                                            && absGenDef.TypeParameters.Count == patternAbstractDef.TypeParameters.Count);

                                    if(genDefMatches && absCtImpl.TypeArguments.Count == patternConstructed.TypeArguments.Count)
                                    {
                                        // Unify the pattern's type arguments with the interface's
                                        // type arguments, substituting actual type args for the
                                        // original type parameters.
                                        var allUnified = true;
                                        for(var i = 0; i < patternConstructed.TypeArguments.Count; i++)
                                        {
                                            var ifaceArg = absCtImpl.TypeArguments[i];
                                            // If the interface's type argument is a TypeParameterType
                                            // from the generic definition, substitute it with the
                                            // actual's corresponding type argument.
                                            if(ifaceArg is TypeParameterType ifaceTpt
                                                && ifaceTpt.Ordinal < actualConstructed.TypeArguments.Count)
                                            {
                                                ifaceArg = actualConstructed.TypeArguments[ifaceTpt.Ordinal];
                                            }

                                            if(!UnifyTypes(patternConstructed.TypeArguments[i], ifaceArg, typeParameters, bindings))
                                            {
                                                allUnified = false;
                                                break;
                                            }
                                        }

                                        if(allUnified)
                                        {
                                            return true;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    return false;
                }

                // Arity must match.
                if(patternConstructed.TypeArguments.Count != actualConstructed.TypeArguments.Count)
                {
                    return false;
                }

                // Recursively unify each type argument.
                for(var i = 0; i < patternConstructed.TypeArguments.Count; i++)
                {
                    if(!UnifyTypes(patternConstructed.TypeArguments[i], actualConstructed.TypeArguments[i], typeParameters, bindings))
                    {
                        return false;
                    }
                }

                return true;
            }

            // Special case: ArrayType implements IEnumerable<T>, ICollection<T>, IList<T>,
            // IReadOnlyCollection<T>, IReadOnlyList<T>. When the pattern is one of these
            // abstracts with a single type argument, unify that argument with the array's
            // element type.
            if(actual is ArrayType actualArray &&
                patternConstructed.GenericDefinition is AbstractType patternIface &&
                patternConstructed.TypeArguments.Count == 1 &&
                IsArrayCompatibleInterface(patternIface))
            {
                return UnifyTypes(patternConstructed.TypeArguments[0], actualArray.ElementType, typeParameters, bindings);
            }

            // The actual is not a ConstructedType — unification fails.
            return false;
        }

        // Case 3: The pattern is a plain type (ClassType, StructType, abstractType, etc.)
        // with type parameters on it (it's a generic definition used as the receiver pattern).
        // For example, extension<T>(List<T> self) where the receiver type resolves to the
        // generic definition ClassType "List" with TypeParameters [T].
        // The actual must be a ConstructedType whose GenericDefinition matches.
        if(pattern is ClassType patternClass && patternClass.TypeParameters.Count > 0)
        {
            if(actual is ConstructedType actualCt && ReferenceEquals(actualCt.GenericDefinition, patternClass))
            {
                // Unify the class's type parameters with the actual's type arguments.
                for(var i = 0; i < patternClass.TypeParameters.Count && i < actualCt.TypeArguments.Count; i++)
                {
                    if(!UnifyTypes(patternClass.TypeParameters[i], actualCt.TypeArguments[i], typeParameters, bindings))
                    {
                        return false;
                    }
                }

                return true;
            }

            return false;
        }

        if(pattern is StructType patternStruct && patternStruct.TypeParameters.Count > 0)
        {
            if(actual is ConstructedType actualCt && ReferenceEquals(actualCt.GenericDefinition, patternStruct))
            {
                for(var i = 0; i < patternStruct.TypeParameters.Count && i < actualCt.TypeArguments.Count; i++)
                {
                    if(!UnifyTypes(patternStruct.TypeParameters[i], actualCt.TypeArguments[i], typeParameters, bindings))
                    {
                        return false;
                    }
                }

                return true;
            }

            return false;
        }

        if(pattern is AbstractType patternAbstract && patternAbstract.TypeParameters.Count > 0)
        {
            if(actual is ConstructedType actualCt && ReferenceEquals(actualCt.GenericDefinition, patternAbstract))
            {
                for(var i = 0; i < patternAbstract.TypeParameters.Count && i < actualCt.TypeArguments.Count; i++)
                {
                    if(!UnifyTypes(patternAbstract.TypeParameters[i], actualCt.TypeArguments[i], typeParameters, bindings))
                    {
                        return false;
                    }
                }

                return true;
            }

            return false;
        }

        // Case 4: Non-generic, non-type-parameter types — must match by reference.
        return ReferenceEquals(pattern, actual);
    }

    /// <summary>
    /// Returns true if the given interface type is one that .NET arrays implement:
    /// IEnumerable, ICollection, IList, IReadOnlyCollection, IReadOnlyList.
    /// These all have a single type parameter corresponding to the array's element type.
    /// </summary>
    private static bool IsArrayCompatibleInterface(AbstractType iface)
    {
        // Arrays implement these generic abstract types from System.Collections.Generic:
        // IEnumerable<T>, ICollection<T>, IList<T>, IReadOnlyCollection<T>, IReadOnlyList<T>
        var name = iface.DisplayName;
        return name is "IEnumerable" or "ICollection" or "IList"
            or "IReadOnlyCollection" or "IReadOnlyList";
    }

    /// <summary>
    /// Substitutes type parameters with type arguments in a member type if a substitution mapping is available.
    /// Used when looking up members on a <see cref="ConstructedType"/>.
    /// </summary>
    private static IType SubstituteMemberTypeIfNeeded(
        IType memberType,
        IReadOnlyList<IType>? typeParams,
        IReadOnlyList<IType>? typeArgs)
    {
        if(typeParams is null || typeArgs is null || typeParams.Count == 0)
        {
            return memberType;
        }

        return SubstituteTypeInMember(memberType, typeParams, typeArgs);
    }

    /// <summary>
    /// Substitutes type parameters with corresponding type arguments in a type.
    /// - If the type is a <see cref="TypeParameterType"/> matching one of the type params, returns the corresponding type arg.
    /// - If the type is a <see cref="ConstructedType"/>, recursively substitutes its type arguments.
    /// - Otherwise, returns the type unchanged.
    /// </summary>
    private static IType SubstituteTypeInMember(IType type, IReadOnlyList<IType> typeParams, IReadOnlyList<IType> typeArgs)
    {
        if(type is TypeParameterType tpt)
        {
            for(var i = 0; i < typeParams.Count; i++)
            {
                var (paramName, paramOrdinal) = GetTypeParameterNameAndOrdinal(typeParams[i]);
                if(tpt.Name == paramName && tpt.Ordinal == paramOrdinal)
                {
                    return i < typeArgs.Count ? typeArgs[i] : type;
                }
            }

            return type;
        }

        if(type is ConstructedType ct)
        {
            var substitutedArgs = new IType[ct.TypeArguments.Count];
            var changed = false;
            for(var i = 0; i < ct.TypeArguments.Count; i++)
            {
                substitutedArgs[i] = SubstituteTypeInMember(ct.TypeArguments[i], typeParams, typeArgs);
                if(!ReferenceEquals(substitutedArgs[i], ct.TypeArguments[i]))
                {
                    changed = true;
                }
            }

            return changed ? new ConstructedType(ct.GenericDefinition, substitutedArgs) : ct;
        }


        if(type is UnionType unionType)
        {
            var substitutedConstituents = new IType[unionType.Constituents.Count];
            var changed = false;
            for(var i = 0; i < unionType.Constituents.Count; i++)
            {
                substitutedConstituents[i] = SubstituteTypeInMember(unionType.Constituents[i], typeParams, typeArgs);
                if(!ReferenceEquals(substitutedConstituents[i], unionType.Constituents[i]))
                {
                    changed = true;
                }
            }

            return changed ? new UnionType(substitutedConstituents) : unionType;
        }

        if(type is ArrayType arrayType)
        {
            var substitutedElement = SubstituteTypeInMember(arrayType.ElementType, typeParams, typeArgs);
            if(!ReferenceEquals(substitutedElement, arrayType.ElementType))
            {
                return new ArrayType(substitutedElement);
            }

            return type;
        }

        // DelegateType: substitute type parameters in TypeArguments and FuncSignature
        // so that e.g. Predicate<T> on List<int> becomes Predicate<int> with
        // FuncSignature = Func<int, bool> after substituting T → int.
        if(type is DelegateType delegateType)
        {
            // Substitute in TypeArguments
            var substitutedTypeArgs = delegateType.TypeArguments;
            var typeArgsChanged = false;
            if(delegateType.TypeArguments.Count > 0)
            {
                var newTypeArgs = new IType[delegateType.TypeArguments.Count];
                for(var i = 0; i < delegateType.TypeArguments.Count; i++)
                {
                    newTypeArgs[i] = SubstituteTypeInMember(delegateType.TypeArguments[i], typeParams, typeArgs);
                    if(!ReferenceEquals(newTypeArgs[i], delegateType.TypeArguments[i]))
                    {
                        typeArgsChanged = true;
                    }
                }

                if(typeArgsChanged)
                {
                    substitutedTypeArgs = newTypeArgs;
                }
            }

            // Substitute in FuncSignature (a ConstructedType)
            var substitutedFuncSig = (ConstructedType)SubstituteTypeInMember(delegateType.FuncSignature, typeParams, typeArgs);
            var funcSigChanged = !ReferenceEquals(substitutedFuncSig, delegateType.FuncSignature);

            if(typeArgsChanged || funcSigChanged)
            {
                return new DelegateType(
                    clrFullName: delegateType.ClrFullName,
                    clrNamespace: delegateType.ClrNamespace,
                    clrSimpleName: delegateType.ClrSimpleName,
                    funcSignature: substitutedFuncSig,
                    typeParameters: delegateType.TypeParameters,
                    typeArguments: substitutedTypeArgs,
                    memberScope: delegateType.MemberScope);
            }

            return type;
        }

        if(type is SpanType spanType)
        {
            var substitutedElement = SubstituteTypeInMember(spanType.ElementType, typeParams, typeArgs);
            if(!ReferenceEquals(substitutedElement, spanType.ElementType))
            {
                return new SpanType(substitutedElement, spanType.IsReadOnly);
            }

            return type;
        }

        return type;
    }

    /// <summary>
    /// Walks the inherited abstract types of an <see cref="AbstractType"/> transitively
    /// to find a member by name. Uses a visited set to handle diamond inheritance
    /// and prevent infinite loops.
    /// </summary>
    /// <returns>The member's declared type if found; <c>null</c> otherwise.</returns>
    private static IType? LookupInheritedInterfaceMember(
        AbstractType abstractType,
        string memberName)
    {
        var visited = new HashSet<AbstractType>(ReferenceEqualityComparer.Instance);
        return LookupInheritedInterfaceMemberCore(abstractType.Abstracts, memberName, visited);
    }

    private static IType? LookupInheritedInterfaceMemberCore(
        IReadOnlyList<IType> abstracts,
        string memberName,
        HashSet<AbstractType> visited)
    {
        foreach(var ifaceType in abstracts)
        {
            if(ifaceType is not AbstractType iface)
            {
                continue;
            }

            if(!visited.Add(iface))
            {
                continue;
            }

            var member = iface.MemberScope.Lookup(memberName);
            if(member is not null)
            {
                return member.DeclaredType ?? ErrorType.Instance;
            }

            var inherited = LookupInheritedInterfaceMemberCore(iface.Abstracts, memberName, visited);
            if(inherited is not null)
            {
                return inherited;
            }
        }

        return null;
    }

    /// <summary>
    /// Searches the DefaultMethods dictionaries of a concrete type's implemented abstract
    /// types transitively (following the abstract type inheritance chain). This enables
    /// Rust-style semantics where default methods are callable directly on the concrete
    /// type without requiring a cast to the abstract type reference.
    /// </summary>
    /// <returns>The default method's declared type if found; <c>null</c> otherwise.</returns>
    private static IType? LookupDefaultMethodInAbstracts(
        IReadOnlyList<IType> abstracts,
        string memberName)
    {
        var visited = new HashSet<AbstractType>(ReferenceEqualityComparer.Instance);
        return LookupDefaultMethodInAbstractsCore(abstracts, memberName, visited);
    }

    private static IType? LookupDefaultMethodInAbstractsCore(
        IReadOnlyList<IType> abstracts,
        string memberName,
        HashSet<AbstractType> visited)
    {
        foreach(var absType in abstracts)
        {
            var def = absType is ConstructedType ct ? ct.GenericDefinition as AbstractType : absType as AbstractType;
            if(def is null)
            {
                continue;
            }

            if(!visited.Add(def))
            {
                continue;
            }

            if(def.DefaultMethods.TryGetValue(memberName, out var defaultSymbol))
            {
                return defaultSymbol.DeclaredType ?? ErrorType.Instance;
            }

            var inherited = LookupDefaultMethodInAbstractsCore(def.Abstracts, memberName, visited);
            if(inherited is not null)
            {
                return inherited;
            }
        }

        return null;
    }

    /// <summary>
    /// Looks up a member symbol by name in an abstract type's inherited abstract types transitively.
    /// Returns the <see cref="ISymbol"/> if found; <c>null</c> otherwise.
    /// Used for constrained type parameter member lookup in <see cref="LookupMemberSymbol"/>.
    /// </summary>
    private static ISymbol? LookupInheritedInterfaceMemberSymbol(
        AbstractType abstractType,
        string memberName)
    {
        var visited = new HashSet<AbstractType>(ReferenceEqualityComparer.Instance);
        return LookupInheritedInterfaceMemberSymbolCore(abstractType.Abstracts, memberName, visited);
    }

    private static ISymbol? LookupInheritedInterfaceMemberSymbolCore(
        IReadOnlyList<IType> abstracts,
        string memberName,
        HashSet<AbstractType> visited)
    {
        foreach(var ifaceType in abstracts)
        {
            if(ifaceType is not AbstractType iface)
            {
                continue;
            }

            if(!visited.Add(iface))
            {
                continue;
            }

            var member = iface.MemberScope.Lookup(memberName);
            if(member is not null)
            {
                return member;
            }

            var inherited = LookupInheritedInterfaceMemberSymbolCore(iface.Abstracts, memberName, visited);
            if(inherited is not null)
            {
                return inherited;
            }
        }

        return null;
    }

    // ── Unified method resolution types ─────────────────────────────────

    /// <summary>
    /// Hints for narrowing method resolution during overload selection.
    /// </summary>
    /// <param name="TypeArgCount">Number of explicit type arguments at the call site (null if none).</param>
    /// <param name="ArgumentCount">Number of arguments at the call site (null if unknown).</param>
    /// <param name="PreferLambdaCompatible">When true, prefer overloads with delegate/func parameters.</param>
    /// <param name="ArgumentTypes">
    /// Resolved argument types at the call site for applicability-based filtering.
    /// Null entries represent lambda arguments whose type depends on the selected overload
    /// (wildcard — matches any parameter type). When the entire list is null, argument-type
    /// filtering is skipped and the fallback heuristics are used.
    /// </param>
    private readonly record struct MethodResolutionHints(
        int? TypeArgCount,
        int? ArgumentCount,
        bool PreferLambdaCompatible,
        IReadOnlyList<IType?>? ArgumentTypes = null);

    /// <summary>
    /// The result of a unified method resolution pass, combining both the
    /// resolved symbol and its return type in a single value.
    /// </summary>
    private readonly record struct MethodResolutionResult(
        ISymbol Symbol,
        IType ReturnType,
        bool IsExtension,
        ExtensionBlockInfo? ExtensionBlock,
        IReadOnlyList<TypeParameterType>? ExtensionTypeParams);

    /// <summary>
    /// Unified method resolution: searches own members (walking the base chain for
    /// classes), ambient members via resolver, default methods on abstracts, and
    /// finally the extension registry (applicable, namespace-filtered). Applies
    /// consistent overload selection based on <paramref name="hints"/> at each level.
    /// Returns null if no matching method is found (no silent fallthrough).
    /// </summary>
    private static MethodResolutionResult? ResolveMethodMember(
        IType targetType,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<string>? importedNamespaces)
    {
        if(targetType is ErrorType)
        {
            return null;
        }

        // For ConstructedType, unwrap to the generic definition for scope lookup
        // but remember the type arguments for substitution.
        IReadOnlyList<IType>? constructedTypeParams = null;
        IReadOnlyList<IType>? constructedTypeArgs = null;
        var originalTargetType = targetType;
        if(targetType is ConstructedType constructedTarget)
        {
            constructedTypeParams = constructedTarget.GenericDefinition switch
            {
                ClassType ct => ct.TypeParameters,
                StructType st => st.TypeParameters,
                AbstractType at => at.TypeParameters,
                _ => null,
            };
            constructedTypeArgs = constructedTarget.TypeArguments;
            targetType = constructedTarget.GenericDefinition;
        }

        // ── Step 1: Own member scope (walk base chain for classes) ──────────
        if(targetType is ClassType classTarget)
        {
            var result = SearchClassChainForMethod(classTarget, methodName, hints, constructedTypeParams, constructedTypeArgs);
            if(result is not null)
            {
                return result;
            }
        }
        else
        {
            var memberScope = targetType switch
            {
                StructType st => st.MemberScope,
                AbstractType at => at.MemberScope,
                NewtypeType nt => nt.MemberScope,
                _ => null,
            };

            if(memberScope is not null)
            {
                var result = SearchScopeForMethodOverload(memberScope, methodName, hints, constructedTypeParams, constructedTypeArgs);
                if(result is not null)
                {
                    return result;
                }

                // For abstract types, walk inherited abstracts transitively.
                if(targetType is AbstractType abstractTarget)
                {
                    var inheritedResult = SearchInheritedAbstractsForMethod(abstractTarget, methodName, hints, constructedTypeParams, constructedTypeArgs);
                    if(inheritedResult is not null)
                    {
                        return inheritedResult;
                    }
                }
            }
        }

        // ── Step 2: Ambient members via resolver ────────────────────────────
        // Ambient members are accessed through the extension registry's member
        // scope on applicable extensions; they share the same path as own members
        // but are projected from CLR assemblies. The class base chain walk above
        // already covers ambient members if the resolver populated them into the
        // class's own scope. For non-class types with ambient projection this is
        // handled via the extension path below.

        // ── Step 3: Default methods on abstracts ────────────────────────────
        var abstracts = targetType switch
        {
            ClassType ct => ct.Abstracts,
            StructType st => st.Abstracts,
            _ => null,
        };

        if(abstracts is not null)
        {
            var defaultResult = SearchDefaultMethodsForOverload(abstracts, methodName, hints, constructedTypeParams, constructedTypeArgs);
            if(defaultResult is not null)
            {
                return defaultResult;
            }
        }

        // ── Step 4: Extension registry (applicable, namespace-filtered) ─────
        if(extensionRegistryContext is not null)
        {
            var lookupType = originalTargetType;

            var applicableExtensions = lookupType is UnknownType
                ? extensionRegistryContext.UniversalExtensions
                : lookupType is UnionType unionType
                    ? extensionRegistryContext.GetApplicableExtensionsForUnion(unionType.Constituents)
                    : extensionRegistryContext.GetApplicableExtensions(lookupType);

            foreach(var ext in applicableExtensions)
            {
                // Namespace visibility check.
                if(ext.ContainingNamespace is not null
                    && (importedNamespaces is null || !importedNamespaces.Contains(ext.ContainingNamespace)))
                {
                    continue;
                }

                // Use LookupAll to find all overloads in the extension scope.
                var allExtMembers = ext.MemberScope.LookupAll(methodName);
                if(allExtMembers.Count == 0)
                {
                    continue;
                }

                // Apply overload selection from hints.
                var selected = SelectOverloadFromHints(allExtMembers, hints);
                if(selected is null)
                {
                    continue;
                }

                var memberType = selected.DeclaredType ?? ErrorType.Instance;
                IReadOnlyList<TypeParameterType>? extensionTypeParams = null;

                // Generic extension type inference: unify receiver and substitute.
                if(ext.TypeParameters.Count > 0)
                {
                    var bindings = TryUnifyReceiverType(ext.ReceiverType, lookupType, ext.TypeParameters);
                    if(bindings is null)
                    {
                        continue;
                    }

                    memberType = SubstituteTypeInMember(memberType, ext.TypeParameters, bindings);
                    extensionTypeParams = ext.TypeParameters.OfType<TypeParameterType>().ToList();
                }

                return new MethodResolutionResult(
                    Symbol: selected,
                    ReturnType: memberType,
                    IsExtension: true,
                    ExtensionBlock: ext,
                    ExtensionTypeParams: extensionTypeParams);
            }
        }

        // ── No match found ──────────────────────────────────────────────────
        return null;
    }

    /// <summary>
    /// Walks the class base chain searching for a method matching the given name and hints.
    /// </summary>
    private static MethodResolutionResult? SearchClassChainForMethod(
        ClassType classTarget,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs)
    {
        var current = classTarget;
        while(current is not null)
        {
            var result = SearchScopeForMethodOverload(current.MemberScope, methodName, hints, constructedTypeParams, constructedTypeArgs);
            if(result is not null)
            {
                return result;
            }

            current = current.BaseType as ClassType;
        }

        return null;
    }

    /// <summary>
    /// Searches a scope for all overloads with the given name, then applies
    /// hint-based selection (arity, param count, lambda preference).
    /// </summary>
    private static MethodResolutionResult? SearchScopeForMethodOverload(
        IScope scope,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs)
    {
        var allMembers = scope.LookupAll(methodName);
        if(allMembers.Count == 0)
        {
            return null;
        }

        var selected = SelectOverloadFromHints(allMembers, hints);
        if(selected is null)
        {
            return null;
        }

        var memberType = selected.DeclaredType ?? ErrorType.Instance;
        memberType = SubstituteMemberTypeIfNeeded(memberType, constructedTypeParams, constructedTypeArgs);

        return new MethodResolutionResult(
            Symbol: selected,
            ReturnType: memberType,
            IsExtension: false,
            ExtensionBlock: null,
            ExtensionTypeParams: null);
    }

    /// <summary>
    /// Walks inherited abstract types (transitively) searching for a method matching
    /// the given name and hints.
    /// </summary>
    private static MethodResolutionResult? SearchInheritedAbstractsForMethod(
        AbstractType abstractTarget,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs)
    {
        var visited = new HashSet<AbstractType>(ReferenceEqualityComparer.Instance);
        return SearchInheritedAbstractsForMethodCore(abstractTarget.Abstracts, methodName, hints, constructedTypeParams, constructedTypeArgs, visited);
    }

    private static MethodResolutionResult? SearchInheritedAbstractsForMethodCore(
        IReadOnlyList<IType> abstracts,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs,
        HashSet<AbstractType> visited)
    {
        foreach(var ifaceType in abstracts)
        {
            if(ifaceType is not AbstractType iface)
            {
                continue;
            }

            if(!visited.Add(iface))
            {
                continue;
            }

            var result = SearchScopeForMethodOverload(iface.MemberScope, methodName, hints, constructedTypeParams, constructedTypeArgs);
            if(result is not null)
            {
                return result;
            }

            var inherited = SearchInheritedAbstractsForMethodCore(iface.Abstracts, methodName, hints, constructedTypeParams, constructedTypeArgs, visited);
            if(inherited is not null)
            {
                return inherited;
            }
        }

        return null;
    }

    /// <summary>
    /// Searches default methods on abstract types (transitively) for a method matching
    /// the given name and hints.
    /// </summary>
    private static MethodResolutionResult? SearchDefaultMethodsForOverload(
        IReadOnlyList<IType> abstracts,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs)
    {
        var visited = new HashSet<AbstractType>(ReferenceEqualityComparer.Instance);
        return SearchDefaultMethodsForOverloadCore(abstracts, methodName, hints, constructedTypeParams, constructedTypeArgs, visited);
    }

    private static MethodResolutionResult? SearchDefaultMethodsForOverloadCore(
        IReadOnlyList<IType> abstracts,
        string methodName,
        MethodResolutionHints hints,
        IReadOnlyList<IType>? constructedTypeParams,
        IReadOnlyList<IType>? constructedTypeArgs,
        HashSet<AbstractType> visited)
    {
        foreach(var absType in abstracts)
        {
            var def = absType is ConstructedType ct ? ct.GenericDefinition as AbstractType : absType as AbstractType;
            if(def is null)
            {
                continue;
            }

            if(!visited.Add(def))
            {
                continue;
            }

            if(def.DefaultMethods.TryGetValue(methodName, out var defaultSymbol))
            {
                // Default methods are single entries (no overload set), so hints
                // are applied as a filter: reject if they don't match.
                if(MatchesHints(defaultSymbol, hints))
                {
                    var memberType = defaultSymbol.DeclaredType ?? ErrorType.Instance;
                    memberType = SubstituteMemberTypeIfNeeded(memberType, constructedTypeParams, constructedTypeArgs);

                    return new MethodResolutionResult(
                        Symbol: defaultSymbol,
                        ReturnType: memberType,
                        IsExtension: false,
                        ExtensionBlock: null,
                        ExtensionTypeParams: null);
                }
            }

            var inherited = SearchDefaultMethodsForOverloadCore(def.Abstracts, methodName, hints, constructedTypeParams, constructedTypeArgs, visited);
            if(inherited is not null)
            {
                return inherited;
            }
        }

        return null;
    }

    /// <summary>
    /// Selects the best overload from a list of candidates based on the resolution hints.
    /// Priority: type argument arity match → parameter count match with lambda preference → first match.
    /// </summary>
    /// <summary>
    /// Selects the best overload from a set of candidates using resolution hints.
    /// Priority: argument-type applicability → type argument arity → parameter count with lambda preference.
    /// Returns null when no candidate matches (the caller will propagate ErrorType).
    /// </summary>
    private static ISymbol? SelectOverloadFromHints(IReadOnlyList<ISymbol> candidates, MethodResolutionHints hints)
    {
        if(candidates.Count == 0)
        {
            return null;
        }

        // If type argument arity hint is provided, prefer the overload matching exactly.
        if(hints.TypeArgCount is not null)
        {
            foreach(var candidate in candidates)
            {
                if(candidate is Symbol s && s.TypeParameters.Count == hints.TypeArgCount.Value)
                {
                    // If we also have param count + lambda hints, verify them too.
                    if(hints.ArgumentCount is not null && s.Parameters.Count != hints.ArgumentCount.Value)
                    {
                        continue;
                    }

                    return s;
                }
            }

            // No arity match — fall through to argument-type / param count filtering.
        }

        // ── Argument-type applicability filtering ────────────────────────────
        // When resolved argument types are available, filter candidates by checking
        // that each non-null argument type is assignable to the corresponding parameter type.
        // This is the same applicability check the type checker's OverloadResolver performs.
        if(hints.ArgumentTypes is { } argTypes && argTypes.Count > 0)
        {
            var applicable = new List<(ISymbol Symbol, IReadOnlyList<IType> ParamTypes)>();

            foreach(var candidate in candidates)
            {
                if(candidate is not Symbol s)
                {
                    continue;
                }

                // Parameter count must match argument count.
                if(s.Parameters.Count != argTypes.Count)
                {
                    continue;
                }

                // Extract parameter types from the candidate.
                var paramTypes = new IType[s.Parameters.Count];
                var hasAllTypes = true;
                for(var i = 0; i < s.Parameters.Count; i++)
                {
                    if(s.Parameters[i].DeclaredType is { } pt)
                    {
                        paramTypes[i] = pt;
                    }
                    else
                    {
                        hasAllTypes = false;
                        break;
                    }
                }

                if(!hasAllTypes)
                {
                    continue;
                }

                // Check each argument against its corresponding parameter.
                var allAssignable = true;
                for(var i = 0; i < argTypes.Count; i++)
                {
                    // Null argument type = lambda/wildcard — matches any parameter type.
                    if(argTypes[i] is null)
                    {
                        continue;
                    }

                    if(!TypeCheckerAnalyzer.IsAssignable(argTypes[i]!, paramTypes[i]))
                    {
                        allAssignable = false;
                        break;
                    }
                }

                if(allAssignable)
                {
                    applicable.Add((candidate, paramTypes));
                }
            }

            // Exactly one applicable candidate — return it.
            if(applicable.Count == 1)
            {
                return applicable[0].Symbol;
            }

            // Multiple applicable — find the most specific.
            if(applicable.Count > 1)
            {
                var best = applicable[0];
                var bestIsValid = true;

                for(var i = 1; i < applicable.Count; i++)
                {
                    if(IsMoreSpecific(applicable[i].ParamTypes, best.ParamTypes))
                    {
                        best = applicable[i];
                        bestIsValid = true;
                    }
                    else if(!IsMoreSpecific(best.ParamTypes, applicable[i].ParamTypes))
                    {
                        bestIsValid = false;
                    }
                }

                if(bestIsValid)
                {
                    // Verify best is more specific than ALL others.
                    foreach(var other in applicable)
                    {
                        if(ReferenceEquals(other.Symbol, best.Symbol))
                        {
                            continue;
                        }

                        if(!IsMoreSpecific(best.ParamTypes, other.ParamTypes))
                        {
                            // Ambiguous — return first applicable (type checker will report the error).
                            return applicable[0].Symbol;
                        }
                    }

                    return best.Symbol;
                }

                // Ambiguous — return first applicable (type checker will report the error).
                return applicable[0].Symbol;
            }

            // Zero applicable via argument types — fall through to param count / lambda heuristics.
            // This can happen when argument types are partially resolved (e.g., all null/lambda).
        }

        // If argument count hint is provided, filter by parameter count.
        if(hints.ArgumentCount is not null)
        {
            ISymbol? paramCountMatch = null;
            ISymbol? lambdaCompatibleMatch = null;

            foreach(var candidate in candidates)
            {
                if(candidate is Symbol s && s.Parameters.Count == hints.ArgumentCount.Value)
                {
                    if(hints.PreferLambdaCompatible && HasLambdaCompatibleParameter(s))
                    {
                        lambdaCompatibleMatch = s;
                    }
                    else
                    {
                        paramCountMatch ??= s;
                    }
                }
            }

            if(lambdaCompatibleMatch is not null)
            {
                return lambdaCompatibleMatch;
            }

            if(paramCountMatch is not null)
            {
                return paramCountMatch;
            }
        }

        // Fallback: prefer lambda-compatible if hint is set.
        if(hints.PreferLambdaCompatible)
        {
            foreach(var candidate in candidates)
            {
                if(candidate is Symbol s && HasLambdaCompatibleParameter(s))
                {
                    return s;
                }
            }
        }

        // Final fallback: return the first candidate.
        // This path is reached only when no argument types were available AND no
        // argument count was provided (should not happen in normal Pass 2 resolution).
        return candidates[0];
    }

    /// <summary>
    /// Determines whether candidate A's parameter types are more specific than candidate B's.
    /// A is more specific if all of A's types are assignable to B's corresponding types,
    /// and at least one of B's types is NOT assignable to A's.
    /// </summary>
    private static bool IsMoreSpecific(IReadOnlyList<IType> aParams, IReadOnlyList<IType> bParams)
    {
        if(aParams.Count != bParams.Count)
        {
            return false;
        }

        var allAtoB = true;
        var anyBnotToA = false;

        for(var i = 0; i < aParams.Count; i++)
        {
            if(!TypeCheckerAnalyzer.IsAssignable(aParams[i], bParams[i]))
            {
                allAtoB = false;
            }

            if(!TypeCheckerAnalyzer.IsAssignable(bParams[i], aParams[i]))
            {
                anyBnotToA = true;
            }
        }

        return allAtoB && anyBnotToA;
    }

    /// <summary>
    /// Checks whether a single symbol matches the resolution hints.
    /// Used for default methods where there's no overload set.
    /// </summary>
    private static bool MatchesHints(ISymbol symbol, MethodResolutionHints hints)
    {
        if(symbol is not Symbol s)
        {
            return true; // Non-Symbol (e.g., interface member stub) — allow by default.
        }

        if(hints.TypeArgCount is not null && s.TypeParameters.Count != hints.TypeArgCount.Value)
        {
            return false;
        }

        if(hints.ArgumentCount is not null && s.Parameters.Count != hints.ArgumentCount.Value)
        {
            return false;
        }

        return true;
    }

    /// <summary>
    /// Looks up a member symbol by name on a target type.
    /// Similar to <see cref="LookupMemberType"/> but returns the <see cref="ISymbol"/> instead of the type.
    /// Used for checking method type parameters on generic method invocations.
    /// </summary>
    private static ISymbol? LookupMemberSymbol(
        IType targetType,
        string memberName)
    {
        if(targetType is ErrorType)
        {
            return null;
        }

        // Namespace references have no symbol-level members; return null to
        // avoid the kind-aware validation from emitting spurious errors.
        if(targetType is NamespaceReferenceType)
        {
            return null;
        }

        // ── Constrained type parameter member access (Requirements 6.1–6.4, 6.7) ──
        // When the receiver is a TypeParameterType with constraints, look up the
        // member in the constraint types (abstract types, base class).
        if(targetType is TypeParameterType typeParam && typeParam.Constraints is not null)
        {
            var constraints = typeParam.Constraints;

            // Check abstract type constraints.
            foreach(var ifaceConstraint in constraints.AbstractConstraints)
            {
                if(ifaceConstraint is AbstractType iface)
                {
                    var member = iface.MemberScope.Lookup(memberName);
                    if(member is not null)
                    {
                        return member;
                    }

                    // Also check inherited abstract types transitively.
                    var inherited = LookupInheritedInterfaceMemberSymbol(iface, memberName);
                    if(inherited is not null)
                    {
                        return inherited;
                    }
                }
            }

            // Check base class constraint (including inherited members).
            if(constraints.BaseClassConstraint is ClassType baseClass)
            {
                var current = baseClass;
                while(current is not null)
                {
                    foreach(var m in current.MemberScope.Members)
                    {
                        if(m.Name == memberName)
                        {
                            return m;
                        }
                    }

                    current = current.BaseType as ClassType;
                }
            }

            return null;
        }

        // ── Associated type slot member access (Requirements 5.1–5.3) ──
        // When the receiver is an AssociatedTypeSlotType, look up the member
        // in the slot's constraint types.
        if(targetType is AssociatedTypeSlotType slotTarget)
        {
            var slotConstraints = slotTarget.Constraints;
            if(slotConstraints is not null)
            {
                // Check abstract type constraints.
                foreach(var ifaceConstraint in slotConstraints.AbstractConstraints)
                {
                    var ifaceType = ifaceConstraint is ConstructedType ctIface
                        ? ctIface.GenericDefinition as AbstractType
                        : ifaceConstraint as AbstractType;

                    if(ifaceType is not null)
                    {
                        var member = ifaceType.MemberScope.Lookup(memberName);
                        if(member is not null)
                        {
                            return member;
                        }

                        var inherited = LookupInheritedInterfaceMemberSymbol(ifaceType, memberName);
                        if(inherited is not null)
                        {
                            return inherited;
                        }
                    }
                }

                // Check base class constraint (including inherited members).
                if(slotConstraints.BaseClassConstraint is ClassType slotBaseClass)
                {
                    var current = slotBaseClass;
                    while(current is not null)
                    {
                        foreach(var m in current.MemberScope.Members)
                        {
                            if(m.Name == memberName)
                            {
                                return m;
                            }
                        }

                        current = current.BaseType as ClassType;
                    }
                }
            }

            return null;
        }

        // For ConstructedType, look up in the generic definition's member scope.
        if(targetType is ConstructedType ct)
        {
            targetType = ct.GenericDefinition;
        }

        var memberScope = targetType switch
        {
            ClassType classType => classType.MemberScope,
            StructType structType => structType.MemberScope,
            AbstractType abstractType => abstractType.MemberScope,
            _ => null,
        };

        if(targetType is ClassType classTarget)
        {
            var current = classTarget;
            while(current is not null)
            {
                foreach(var m in current.MemberScope.Members)
                {
                    if(m.Name == memberName)
                    {
                        return m;
                    }
                }

                current = current.BaseType as ClassType;
            }
        }
        else if(memberScope is not null)
        {
            var member = memberScope.Lookup(memberName);
            if(member is not null)
            {
                return member;
            }
        }

        return null;
    }

    /// <summary>
    /// Looks up a method symbol by name, preferring a generic overload whose type
    /// parameter count matches the provided type argument count. Falls back to the
    /// first match (generic or non-generic) if no exact arity match is found.
    /// Used for type argument validation on method invocations.
    /// </summary>
    /// <remarks>
    /// DEPRECATED: This function is being replaced by <see cref="ResolveMethodMember"/>
    /// which provides unified arity-aware overload selection. Retained until all callers
    /// are migrated.
    /// </remarks>
    private static ISymbol? LookupGenericMemberSymbol(
        IType targetType,
        string memberName,
        int typeArgCount,

        Scope fileScope)
    {
        if(targetType is ErrorType or NamespaceReferenceType)
        {
            return null;
        }

        // For ConstructedType, look up in the generic definition's member scope.
        var originalTargetType = targetType;
        if(targetType is ConstructedType ct)
        {
            targetType = ct.GenericDefinition;
        }

        var memberScope = targetType switch
        {
            ClassType classType => classType.MemberScope,
            StructType structType => structType.MemberScope,
            AbstractType abstractType => abstractType.MemberScope,
            _ => null,
        };

        if(targetType is ClassType classTarget)
        {
            var current = classTarget;
            while(current is not null)
            {
                ISymbol? firstMatch = null;
                foreach(var m in current.MemberScope.Members)
                {
                    if(m.Name == memberName)
                    {
                        firstMatch ??= m;
                        if(m is Symbol s && s.TypeParameters.Count == typeArgCount)
                        {
                            return s;
                        }
                    }
                }

                if(firstMatch is not null)
                {
                    return firstMatch;
                }

                current = current.BaseType as ClassType;
            }
        }
        else if(memberScope is not null)
        {
            var allMembers = memberScope.LookupAll(memberName);
            if(allMembers.Count > 0)
            {
                // Prefer the overload whose type parameter count matches.
                foreach(var m in allMembers)
                {
                    if(m is Symbol s && s.TypeParameters.Count == typeArgCount)
                    {
                        return s;
                    }
                }

                return allMembers[0];
            }
        }

        // Extension method fallback: if the member was not found on the type's
        // own scope, search the extension registry for a generic method with
        // matching name and type-argument arity. This handles cases like
        // GetRequiredService<T>() which is an extension method on IServiceProvider.
        if(extensionRegistryContext is not null)
        {
            var lookupType = originalTargetType;
            var applicableExtensions = lookupType is UnknownType
                ? extensionRegistryContext.UniversalExtensions
                : extensionRegistryContext.GetApplicableExtensions(lookupType);

            var importedNamespaces = CollectImportedNamespaces(fileScope);

            foreach(var ext in applicableExtensions)
            {
                if(ext.ContainingNamespace is not null && !importedNamespaces.Contains(ext.ContainingNamespace))
                {
                    continue;
                }

                // Use LookupAll to find all overloads with the same name, then
                // select the one whose type parameter arity matches. Lookup()
                // returns only the first registered overload which may be the
                // non-generic variant (e.g., GetRequiredService(Type) instead
                // of GetRequiredService<T>()).
                var allExtMembers = ext.MemberScope.LookupAll(memberName);
                foreach(var m in allExtMembers)
                {
                    if(m is Symbol s && s.TypeParameters.Count == typeArgCount)
                    {
                        return s;
                    }
                }
            }
        }

        return null;
    }

    /// <summary>
    /// Looks up a generic method symbol by name and type argument count, preferring an
    /// overload that has parameters (i.e., is not parameterless). Used when the initial
    /// generic member lookup found a parameterless overload but the call site has arguments,
    /// indicating a different overload is needed for lambda target type inference.
    /// </summary>
    private static ISymbol? LookupGenericMemberSymbolWithParams(
        IType targetType,
        string memberName,
        int typeArgCount)
    {
        if(targetType is ErrorType or NamespaceReferenceType)
        {
            return null;
        }

        if(targetType is ConstructedType ct)
        {
            targetType = ct.GenericDefinition;
        }

        if(targetType is ClassType classTarget)
        {
            var current = classTarget;
            while(current is not null)
            {
                foreach(var m in current.MemberScope.Members)
                {
                    if(m.Name == memberName
                        && m is Symbol s
                        && s.TypeParameters.Count == typeArgCount
                        && s.Parameters.Count > 0)
                    {
                        return s;
                    }
                }

                current = current.BaseType as ClassType;
            }
        }

        return null;
    }

    /// <summary>
    /// Looks up a method symbol by name, preferring an overload whose parameter count
    /// matches the provided argument count. Falls back to the first name match.
    /// Used for lambda target type inference when multiple overloads exist
    /// (e.g., HasMany(string) vs HasMany(Expression&lt;Func&lt;...&gt;&gt;)).
    /// </summary>
    private static ISymbol? LookupMemberSymbolByParamCount(
        IType targetType,
        string memberName,
        int argCount)
    {
        if(targetType is ErrorType or NamespaceReferenceType)
        {
            return null;
        }

        if(targetType is ConstructedType ct)
        {
            targetType = ct.GenericDefinition;
        }

        if(targetType is ClassType classTarget)
        {
            var current = classTarget;
            ISymbol? firstMatch = null;
            ISymbol? lambdaCompatibleMatch = null;
            while(current is not null)
            {
                foreach(var m in current.MemberScope.Members)
                {
                    if(m.Name == memberName && m.Kind == SymbolKind.Method)
                    {
                        firstMatch ??= m;
                        if(m is Symbol s && s.Parameters.Count == argCount)
                        {
                            // Prefer overloads with Expression/Func/Action/delegate params
                            // (lambda-compatible) over plain value params.
                            if(HasLambdaCompatibleParameter(s))
                            {
                                lambdaCompatibleMatch = s;
                            }
                            else
                            {
                                firstMatch = s; // At least param count matches
                            }
                        }
                    }
                }

                if(lambdaCompatibleMatch is not null)
                {
                    return lambdaCompatibleMatch;
                }

                current = current.BaseType as ClassType;
            }

            return firstMatch;
        }

        // Fallback to standard lookup for non-class types.
        return LookupMemberSymbol(targetType, memberName);
    }

    /// <summary>
    /// Checks whether a method symbol has at least one parameter whose type is
    /// lambda-compatible (Func, Action, Expression, DelegateType, or a ConstructedType
    /// wrapping any of those). Used to prefer lambda-accepting overloads during
    /// lambda target type inference.
    /// </summary>
    private static bool HasLambdaCompatibleParameter(Symbol symbol)
    {
        foreach(var param in symbol.Parameters)
        {
            var paramType = param.DeclaredType;
            if(paramType is null)
            {
                continue;
            }

            // Unwrap nullable unions (T | void) to check the inner type.
            if(paramType is UnionType union)
            {
                foreach(var c in union.Constituents)
                {
                    if(IsLambdaCompatibleType(c))
                    {
                        return true;
                    }
                }
            }
            else if(IsLambdaCompatibleType(paramType))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Determines if a type represents a lambda-compatible delegate/func/expression type.
    /// </summary>
    private static bool IsLambdaCompatibleType(IType type)
    {
        if(IsFuncType(type))
        {
            return true;
        }

        if(type is DelegateType)
        {
            return true;
        }

        if(TryUnwrapExpressionFunc(type) is not null)
        {
            return true;
        }
        // CLR Action/Func projected as ClassType.
        if(type is ConstructedType ct
            && ct.GenericDefinition is ClassType { ContainingNamespace: "System" } cls
            && (cls.DisplayName.StartsWith("Action", StringComparison.Ordinal)
                || cls.DisplayName.StartsWith("Func", StringComparison.Ordinal)
                || cls.DisplayName == "Expression"))
        {
            return true;
        }

        return false;
    }

    /// <summary>
    /// Counts the number of type arguments in a <see cref="TypeArgumentListNode"/>.
    /// </summary>
    private static int CountTypeArgs(TypeArgumentListNode typeArgList)
    {
        return 1 + typeArgList.TypeArguments.Length;
    }

    /// <summary>
    /// Resolves argument list expressions.
    /// </summary>
    private static void ResolveArgumentList(
        ArgumentListNode argList,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        IReadOnlyList<IType>? parameterTypes = null)
    {
        ResolveArgumentListWithParameterTypes(argList, parameterTypes, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);
    }

    /// <summary>
    /// Collects the resolved types of arguments from the expression types dictionary.
    /// Used for post-resolution type argument inference on generic methods.
    /// </summary>
    private static List<IType> CollectResolvedArgumentTypes(
        ArgumentListNode argList,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes)
    {
        var result = new List<IType>();
        var argExprs = argList.GetAllExpressions();
        foreach(var expr in argExprs)
        {
            if(expressionTypes.TryGetValue(expr, out var resolvedType))
            {
                result.Add(resolvedType);
            }
            else
            {
                result.Add(UnknownType.Instance);
            }
        }

        return result;
    }

    /// <summary>
    /// Resolves argument list expressions with optional parameter type information
    /// for lambda target-type inference. When parameter types are provided and a
    /// parameter is a Func type, sets the lambda target type context so that
    /// implicitly-typed lambda arguments can infer their parameter types.
    /// </summary>
    private static void ResolveArgumentListWithParameterTypes(
        ArgumentListNode argList,
        IReadOnlyList<IType>? parameterTypes,
        Scope currentScope,
        Scope fileScope,
        IType enclosingType,
        bool isStatic,
        SymbolTable symbolTable,
        Dictionary<Storm.Runtime.SyntaxNode, IType> expressionTypes,
        IAmbientTypeResolver? ambientTypeResolver,
        SourceText? sourceText,
        DiagnosticBag diagnostics,
        IReadOnlyList<IType>? methodTypeParameters = null)
    {
        // The ArgumentListNode has Argument (first) and Arguments (rest),
        // each wrapping an ExpressionNode.
        var argExprs = argList.GetAllExpressions();

        // Mutable copy of parameter types for incremental type arg substitution.
        IType[]? mutableParamTypes = null;
        if(parameterTypes is not null && methodTypeParameters is not null && methodTypeParameters.Count > 0)
        {
            mutableParamTypes = new IType[parameterTypes.Count];
            for(var j = 0; j < parameterTypes.Count; j++)
            {
                mutableParamTypes[j] = parameterTypes[j];
            }
        }

        for(var i = 0; i < argExprs.Length; i++)
        {
            var expr = argExprs[i];

            // Use the potentially-substituted param types for lambda target inference.
            var effectiveParamTypes = mutableParamTypes ?? parameterTypes;

            // Set lambda target type if the corresponding parameter is a Func type.
            // Also handles nullable Func types (UnionType containing a Func constituent).
            var previousLambdaTarget = lambdaTargetType;
            var previousVoidTarget = voidLiteralTargetType;
            var previousTargetNewTarget = targetTypedNewTargetType;
            if(effectiveParamTypes is not null && i < effectiveParamTypes.Count)
            {
                var paramType = effectiveParamTypes[i];
                voidLiteralTargetType = paramType;
                targetTypedNewTargetType = paramType;
                if(IsFuncType(paramType))
                {
                    lambdaTargetType = paramType;
                }
                else if(paramType is DelegateType)
                {
                    lambdaTargetType = paramType;
                }
                else if(TryUnwrapExpressionFunc(paramType) is { } expressionFunc)
                {
                    // Expression<Func<T, R>> — unwrap to the inner Func for lambda inference.
                    lambdaTargetType = expressionFunc;
                }
                else if(paramType is UnionType unionParam)
                {
                    // Check if the union contains a Func or DelegateType constituent
                    // (e.g., Func<T, void> | Void or Predicate<int> | Void from nullable projection).
                    foreach(var constituent in unionParam.Constituents)
                    {
                        if(IsFuncType(constituent))
                        {
                            lambdaTargetType = constituent;
                            break;
                        }

                        if(constituent is DelegateType)
                        {
                            lambdaTargetType = constituent;
                            break;
                        }
                        // Also detect CLR Action<T>/Func<T> types that were projected as
                        // plain ClassType (not stdlib Func) due to projection ordering.
                        // These are ConstructedTypes whose GenericDefinition has a name
                        // like "Action" or "Func" in the "System" namespace.
                        if(constituent is ConstructedType ctConstituent
                            && ctConstituent.GenericDefinition is ClassType { ContainingNamespace: "System" } ctClass
                            && (ctClass.DisplayName.StartsWith("Action", StringComparison.Ordinal)
                                || ctClass.DisplayName.StartsWith("Func", StringComparison.Ordinal)))
                        {
                            lambdaTargetType = constituent;
                            break;
                        }
                        // Expression<Func<...>> inside a nullable union.
                        if(TryUnwrapExpressionFunc(constituent) is { } innerFunc)
                        {
                            lambdaTargetType = innerFunc;
                            break;
                        }
                    }
                }
            }

            _ = ResolveExpression(expr, currentScope, fileScope, enclosingType, isStatic, symbolTable, expressionTypes, ambientTypeResolver, sourceText, diagnostics);

            // Restore previous target types.
            lambdaTargetType = previousLambdaTarget;
            voidLiteralTargetType = previousVoidTarget;
            targetTypedNewTargetType = previousTargetNewTarget;

            // Incremental type argument inference: after resolving each argument,
            // attempt to infer type args from what we have so far and substitute
            // into remaining parameter types. This enables multi-lambda patterns
            // like OwnsOne(e => e.QualityTier, qt => {...}) where the second
            // lambda's parameter type depends on inference from the first.
            if(mutableParamTypes is not null && methodTypeParameters is not null
                && i < argExprs.Length - 1) // Only if there are remaining args
            {
                // Collect resolved arg types so far.
                var resolvedSoFar = new List<IType>();
                for(var k = 0; k <= i; k++)
                {
                    if(expressionTypes.TryGetValue(argExprs[k], out var resolvedType))
                    {
                        resolvedSoFar.Add(resolvedType);
                    }
                    else
                    {
                        resolvedSoFar.Add(UnknownType.Instance);
                    }
                }

                // Attempt partial inference.
                var partialParamTypes = new IType[resolvedSoFar.Count];
                for(var k = 0; k < resolvedSoFar.Count; k++)
                {
                    partialParamTypes[k] = mutableParamTypes[k];
                }

                var partialResult = TypeArgumentInferenceEngine.TryInfer(
                    methodTypeParameters, partialParamTypes, resolvedSoFar);

                if(partialResult.Success && partialResult.InferredTypeArguments is not null)
                {
                    // Substitute inferred type args into remaining parameter types.
                    for(var k = i + 1; k < mutableParamTypes.Length; k++)
                    {
                        mutableParamTypes[k] = SubstituteTypeInMember(
                            mutableParamTypes[k], methodTypeParameters, partialResult.InferredTypeArguments);
                    }
                }
            }
        }
    }

    /// <summary>
    /// Determines the type of an integer literal based on its suffix.
    /// </summary>
    private static IType ResolveIntegerLiteralType(string lexeme, Scope fileScope, SymbolTable symbolTable)
    {
        var upper = lexeme.ToUpperInvariant();

        if(upper.EndsWith("UL") || upper.EndsWith("LU"))
        {
            return ResolvePrimitiveByKeyword("ulong", fileScope, symbolTable);
        }

        if(upper.EndsWith("L"))
        {
            return ResolvePrimitiveByKeyword("long", fileScope, symbolTable);
        }

        if(upper.EndsWith("U"))
        {
            return ResolvePrimitiveByKeyword("uint", fileScope, symbolTable);
        }

        return ResolvePrimitiveByKeyword("int", fileScope, symbolTable);
    }

    /// <summary>
    /// Determines the type of a float literal based on its suffix.
    /// </summary>
    private static IType ResolveFloatLiteralType(string lexeme, Scope fileScope, SymbolTable symbolTable)
    {
        var upper = lexeme.ToUpperInvariant();

        if(upper.EndsWith("F"))
        {
            return ResolvePrimitiveByKeyword("float", fileScope, symbolTable);
        }

        if(upper.EndsWith("M"))
        {
            return ResolvePrimitiveByKeyword("decimal", fileScope, symbolTable);
        }

        return ResolvePrimitiveByKeyword("double", fileScope, symbolTable);
    }

    /// <summary>
    /// Resolves a primitive keyword to its stdlib type when the Standard
    /// Library is loaded, falling back to the legacy
    /// <see cref="LegacyPrimitiveTypes"/> singleton otherwise. This
    /// replaces the deleted <c>PrimitiveType.Int</c> etc. property
    /// accessors that used to consult <c>PrimitiveTypeRegistry</c>.
    /// </summary>
    private static IType ResolvePrimitiveByKeyword(string keyword, Scope fileScope, SymbolTable symbolTable)
    {
        if(!KeywordAliases.Map.TryGetValue(keyword, out var qualifiedName))
        {
            // Not a primitive keyword — return legacy fallback.
            return TryResolveWellKnownType(keyword) ?? ErrorType.Instance;
        }

        try
        {
            var globalScope = FindGlobalScope(fileScope) ?? fileScope;
            return LookupQualifiedStdlibType(globalScope, symbolTable, qualifiedName);
        }
        catch(StdlibMissingException)
        {
            // Stdlib not loaded — return legacy fallback.
            return TryResolveWellKnownType(keyword) ?? ErrorType.Instance;
        }
    }

    /// <summary>
    /// Returns <c>true</c> when <paramref name="type"/> represents the
    /// Mist <c>string</c> / <c>Standard.String</c> type, regardless of
    /// whether the instance is the legacy <see cref="LegacyPrimitiveTypes.String"/>
    /// fallback or the stdlib <see cref="ClassType"/>.
    /// </summary>
    private static bool IsStringLikeType(IType type)
    {
        if(type is ClassType ct)
        {
            if(ct.IsBackendBacked
                && ct.ContainingNamespace == "Standard"
                && ct.DisplayName == "String")
            {
                return true;
            }
            // Legacy fallback: LegacyPrimitiveTypes.String has DisplayName "string"
            if(ct.DisplayName == "string")
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Returns true if the given type is an integer type (int, uint, long, ulong,
    /// short, ushort, byte, sbyte). Used to validate TLS return expressions.
    /// </summary>
    private static bool IsIntegerType(IType type)
    {
        // Unwrap refinement types to their base type.
        if(type is RefinementType refinement)
        {
            type = refinement.BaseType;
        }

        return type.DisplayName is "int" or "Int32"
            or "uint" or "UInt32"
            or "long" or "Int64"
            or "ulong" or "UInt64"
            or "short" or "Int16"
            or "ushort" or "UInt16"
            or "byte" or "Byte"
            or "sbyte" or "SByte";
    }

    /// <summary>
    /// Returns the common numeric type for binary arithmetic operations.
    /// If either operand is ErrorType, returns ErrorType.
    /// </summary>
    private static IType GetCommonNumericType(IType left, IType right)
    {
        if(left is ErrorType || right is ErrorType)
        {
            return ErrorType.Instance;
        }

        // ── refinement-types feature: arithmetic erasure (Requirement 8.1) ──
        // When a RefinementType participates in arithmetic, the result is the
        // BaseType. Unwrap before numeric ranking so the correct base type is
        // used for the result.
        if(left is RefinementType leftRefinement)
        {
            left = leftRefinement.BaseType;
        }

        if(right is RefinementType rightRefinement)
        {
            right = rightRefinement.BaseType;
        }

        // Numeric widening: decimal > double > float > ulong > long > uint > int > smaller types.
        // Use DisplayName-based ranking to handle both legacy (e.g., "int")
        // and stdlib (e.g., "Int32") type instances.
        static int numericRank(IType t)
        {
            return t.DisplayName switch
            {
                "sbyte" or "SByte" => 1,
                "byte" or "Byte" => 2,
                "short" or "Int16" => 3,
                "ushort" or "UInt16" => 4,
                "int" or "Int32" => 5,
                "uint" or "UInt32" => 6,
                "long" or "Int64" => 7,
                "ulong" or "UInt64" => 8,
                "float" or "Single" => 9,
                "double" or "Double" => 10,
                "decimal" or "Decimal" => 11,
                _ => -1,
            };
        }

        var leftRank = numericRank(left);
        var rightRank = numericRank(right);

        if(leftRank >= 0 && rightRank >= 0)
        {
            return leftRank >= rightRank ? left : right;
        }

        // If not both numeric, return the left type as a fallback.
        return left;
    }

    /// <summary>
    /// Resolves the <c>field</c> keyword to the backing field of the enclosing property.
    /// Walks the symbol table to find a property symbol whose backing field is in the
    /// current scope chain.
    /// </summary>
    private static IType ResolveFieldKeyword(
        Scope currentScope)
    {
        // Walk the scope chain to find the type scope that contains a property with a backing field.
        // The 'field' keyword should resolve to the backing field of the enclosing property.
        // We look for property symbols in the type scope (parent of the accessor scope).
        IScope? scope = currentScope;
        while(scope is not null)
        {
            foreach(var member in scope.Members)
            {
                if(member.Kind == SymbolKind.Property && member is Symbol propSymbol && propSymbol.PropertyMetadata?.BackingField is Symbol backingField)
                {
                    return backingField.DeclaredType ?? ErrorType.Instance;
                }
            }

            scope = scope.Parent;
        }

        // 'field' keyword used outside a property accessor or in a computed property.
        // Return ErrorType — the type checker will report the appropriate diagnostic.
        return ErrorType.Instance;
    }

    /// <summary>
    /// Returns true if <paramref name="name"/> is either an exact namespace in the ambient
    /// resolver or a prefix of one (e.g., "Newtonsoft" is a prefix of "Newtonsoft.Json").
    /// Used to detect namespace roots in expression context for fully-qualified type access.
    /// </summary>
    private static bool IsNamespaceOrPrefix(string name, IAmbientTypeResolver resolver)
    {
        // Exact match: the name itself is a namespace.
        if(resolver.HasNamespace(name))
        {
            return true;
        }

        // Prefix match: check if any type name exists in a namespace that starts
        // with "name." — this detects namespace root identifiers like "Newtonsoft"
        // when "Newtonsoft.Json" is a known namespace.
        var prefix = name + ".";
        // Use GetTypeNamesInNamespace? No — we don't know the full namespace name yet.
        // Instead, rely on the fact that if the ambient resolver is an AssemblyTypeProvider,
        // it has a namespace index. We cast to check.
        if(resolver is Backends.CSharpTranspiler.AssemblyTypeProvider atp)
        {
            return atp.HasNamespaceWithPrefix(prefix);
        }

        return false;
    }

    /// <summary>
    /// Checks for duplicate local variable declarations in the current scope.
    /// </summary>
    private static void CheckDuplicateLocal(string name, Scope scope, SourceText? sourceText, DiagnosticBag diagnostics)
    {
        foreach(var member in scope.Members)
        {
            if(member.Name == name)
            {
                diagnostics.Report(SemanticDiagnostics.DuplicateDeclaration, default, sourceText?.Path ?? "<unknown>", (object)name);
                return;
            }
        }
    }

    /// <summary>
    /// Extracts the full qualified name from a QualifiedIdentifierNode.
    /// </summary>
    private static string ExtractQualifiedName(QualifiedIdentifierNode qualifiedId, SourceText? sourceText)
    {
        if(sourceText is not null)
        {
            var span = qualifiedId.Span;
            if(span.Length > 0 && span.Start + span.Length <= sourceText.Contents.Length)
            {
                var extracted = sourceText.Contents.Substring(span.Start, span.Length);
                // Validate that the extracted text looks like a qualified identifier
                // (only letters, digits, underscores, and dots). If not, the source
                // text is from the wrong file (overlapping AST spans across files).
                if(IsValidQualifiedIdentifier(extracted))
                {
                    return extracted;
                }
            }
        }

        // Fallback: reconstruct the dotted name from the AST tokens.
        // QualifiedIdentifier = IDENTIFIER (DOT IDENTIFIER)* — so we need
        // to join the first IDENTIFIER with any additional IDENTIFIERs.
        if(qualifiedId.IDENTIFIERs.IsDefaultOrEmpty)
        {
            return qualifiedId.IDENTIFIER.Lexeme;
        }

        var sb = new System.Text.StringBuilder(qualifiedId.IDENTIFIER.Lexeme);
        foreach(var token in qualifiedId.IDENTIFIERs)
        {
            if(!string.IsNullOrEmpty(token.Lexeme))
            {
                _ = sb.Append('.');
                _ = sb.Append(token.Lexeme);
            }
        }

        return sb.ToString();
    }

    /// <summary>
    /// Checks whether a string looks like a valid qualified identifier (e.g., "Foo.Bar.Baz").
    /// Used to validate source text extraction results.
    /// </summary>
    private static bool IsValidQualifiedIdentifier(string text)
    {
        if(string.IsNullOrEmpty(text))
        {
            return false;
        }

        foreach(var ch in text)
        {
            if(!char.IsLetterOrDigit(ch) && ch != '_' && ch != '.')
            {
                return false;
            }
        }

        return true;
    }

    private static string ExtractNamespaceName(
        NamespaceDeclarationNode namespaceNode,
        SourceText? sourceText)
    {
        var qualifiedId = namespaceNode switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Name,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Name,
            _ => null
        };

        if(qualifiedId is null)
        {
            return "<unknown>";
        }

        if(sourceText is not null)
        {
            var span = qualifiedId.Span;
            if(span.Length > 0 && span.Start + span.Length <= sourceText.Contents.Length)
            {
                return sourceText.Contents.Substring(span.Start, span.Length);
            }
        }

        return qualifiedId.IDENTIFIER.Lexeme;
    }

    private static ImmutableArray<TypeDeclarationNode> GetNamespaceBodyTypes(
        NamespaceDeclarationNode namespaceNode)
    {
        var bodyItems = namespaceNode switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Body,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Body,
            _ => ImmutableArray<NamespaceBodyItemNode>.Empty
        };

        var builder = ImmutableArray.CreateBuilder<TypeDeclarationNode>();
        foreach(var item in bodyItems)
        {
            if(item is NamespaceTypeItemNamespaceBodyItemNode typeItem)
            {
                builder.Add(typeItem.TypeDeclaration);
            }
        }

        return builder.ToImmutable();
    }

    private static ImmutableArray<TypeAliasDeclarationNode> GetNamespaceBodyTypeAliases(
        NamespaceDeclarationNode namespaceNode)
    {
        var bodyItems = namespaceNode switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Body,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Body,
            _ => ImmutableArray<NamespaceBodyItemNode>.Empty
        };

        var builder = ImmutableArray.CreateBuilder<TypeAliasDeclarationNode>();
        foreach(var item in bodyItems)
        {
            if(item is NamespaceTypeItemNamespaceBodyItemNode { TypeDeclaration: TypeAliasTypeTypeDeclarationNode typeAliasType })
            {
                builder.Add(typeAliasType.TypeAliasDeclaration);
            }
        }

        return builder.ToImmutable();
    }

    private static ImmutableArray<NewtypeDeclarationNode> GetNamespaceBodyNewtypes(
        NamespaceDeclarationNode namespaceNode)
    {
        var bodyItems = namespaceNode switch
        {
            FileScopedNamespaceNamespaceDeclarationNode fileScopedNs => fileScopedNs.Body,
            BlockNamespaceNamespaceDeclarationNode blockNs => blockNs.Body,
            _ => ImmutableArray<NamespaceBodyItemNode>.Empty
        };

        var builder = ImmutableArray.CreateBuilder<NewtypeDeclarationNode>();
        foreach(var item in bodyItems)
        {
            if(item is NamespaceTypeItemNamespaceBodyItemNode { TypeDeclaration: NewtypeTypeTypeDeclarationNode newtypeType })
            {
                builder.Add(newtypeType.NewtypeDeclaration);
            }
        }

        return builder.ToImmutable();
    }

    // ═══════════════════════════════════════════════════════════════════════
    // Post-Pass 2 — Defaultability Analysis
    // ═══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// The set of stdlib display names that are intrinsically defaultable.
    /// Covers both the stdlib <c>Standard.*</c> names and the legacy
    /// keyword-based names used when stdlib is not loaded.
    /// </summary>
    private static readonly HashSet<string> IntrinsicDefaultableNames = new(StringComparer.Ordinal)
    {
        // Stdlib names (Standard.*)
        "Int32", "UInt32", "Int64", "UInt64", "Int16", "UInt16",
        "Byte", "SByte", "Single", "Double", "Decimal",
        "Boolean", "Char", "String",
        // Legacy keyword names (when stdlib is not loaded)
        "int", "uint", "long", "ulong", "short", "ushort",
        "byte", "sbyte", "float", "double", "decimal",
        "bool", "char", "string",
    };

    /// <summary>
    /// Returns <c>true</c> when <paramref name="type"/> is intrinsically
    /// defaultable — i.e., a primitive type or <c>string</c>.
    /// </summary>
    private static bool IsIntrinsicallyDefaultable(IType type)
    {
        // Primitive types are StructType (stdlib) or StructType (legacy).
        // String is ClassType (stdlib) or ClassType (legacy).
        if(type is StructType or ClassType)
        {
            return IntrinsicDefaultableNames.Contains(type.DisplayName);
        }

        return false;
    }

    /// <summary>
    /// Returns <c>true</c> when <paramref name="type"/> is defaultable:
    /// either intrinsically defaultable (primitive/string), or a ClassType/StructType
    /// whose <see cref="ClassType.Defaultability"/> or <see cref="StructType.Defaultability"/>
    /// is <see cref="DefaultabilityStatus.Inferred"/> or <see cref="DefaultabilityStatus.Explicit"/>.
    /// </summary>
    private static bool IsTypeDefaultable(IType type)
    {
        if(IsIntrinsicallyDefaultable(type))
        {
            return true;
        }

        return type switch
        {
            ClassType ct => ct.Defaultability is DefaultabilityStatus.Inferred or DefaultabilityStatus.Explicit,
            StructType st => st.Defaultability is DefaultabilityStatus.Inferred or DefaultabilityStatus.Explicit,
            UnionType ut => ut.Constituents.Any(c => c.IsVoid()),
            _ => false,
        };
    }

    /// <summary>
    /// Computes defaultability for all <see cref="ClassType"/> and <see cref="StructType"/>
    /// symbols in the symbol table. Processes types in topological order so that
    /// a type's field types are resolved before the type itself is processed.
    /// </summary>
    private static void ComputeDefaultability(
        SymbolTable symbolTable,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // Step 1: Collect all class and struct type symbols.
        var typeSymbols = new List<(ISymbol Symbol, IType Type)>();
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind is SymbolKind.Class or SymbolKind.Struct)
            {
                var type = symbol.DeclaredType;
                if(type is ClassType or StructType)
                {
                    // Skip intrinsically defaultable types (stdlib primitives and string).
                    if(IsIntrinsicallyDefaultable(type))
                    {
                        continue;
                    }

                    // Skip generic type definitions (types with unbound type parameters).
                    // Generic types like Optional<T> cannot be defaulted without concrete
                    // type arguments — defaultability is only meaningful for closed types.
                    if(type is ClassType ct && ct.TypeParameters.Count > 0)
                    {
                        continue;
                    }

                    if(type is StructType st && st.TypeParameters.Count > 0)
                    {
                        continue;
                    }

                    typeSymbols.Add((symbol, type));
                }
            }
        }

        // Step 2: Build a dependency graph. A type depends on the types of its fields.
        // Map from type → index in typeSymbols list.
        var typeToIndex = new Dictionary<IType, int>();
        for(var i = 0; i < typeSymbols.Count; i++)
        {
            typeToIndex[typeSymbols[i].Type] = i;
        }

        // Adjacency list: dependencies[i] = set of indices that type i depends on.
        var dependencies = new List<HashSet<int>>();
        for(var i = 0; i < typeSymbols.Count; i++)
        {
            var deps = new HashSet<int>();
            var memberScope = typeSymbols[i].Type switch
            {
                ClassType ct => ct.MemberScope,
                StructType st => st.MemberScope,
                _ => null,
            };

            if(memberScope is not null)
            {
                foreach(var member in memberScope.Members)
                {
                    if(member.Kind == SymbolKind.Field && member.DeclaredType is not null)
                    {
                        if(typeToIndex.TryGetValue(member.DeclaredType, out var depIndex))
                        {
                            _ = deps.Add(depIndex);
                        }
                    }
                }
            }

            // Also depend on the base type if it's a class with a base.
            if(typeSymbols[i].Type is ClassType classType && classType.BaseType is not null)
            {
                if(typeToIndex.TryGetValue(classType.BaseType, out var baseIndex))
                {
                    _ = deps.Add(baseIndex);
                }
            }

            dependencies.Add(deps);
        }

        // Step 3: Topological sort using Kahn's algorithm.
        var inDegree = new int[typeSymbols.Count];
        var reverseDeps = new List<List<int>>();
        for(var i = 0; i < typeSymbols.Count; i++)
        {
            reverseDeps.Add(new List<int>());
        }

        for(var i = 0; i < typeSymbols.Count; i++)
        {
            foreach(var dep in dependencies[i])
            {
                reverseDeps[dep].Add(i);
                inDegree[i]++;
            }
        }

        var queue = new Queue<int>();
        for(var i = 0; i < typeSymbols.Count; i++)
        {
            if(inDegree[i] == 0)
            {
                queue.Enqueue(i);
            }
        }

        var processingOrder = new List<int>();
        while(queue.Count > 0)
        {
            var idx = queue.Dequeue();
            processingOrder.Add(idx);

            foreach(var dependent in reverseDeps[idx])
            {
                inDegree[dependent]--;
                if(inDegree[dependent] == 0)
                {
                    queue.Enqueue(dependent);
                }
            }
        }

        // Any types not in processingOrder have circular dependencies.
        // Process them after the topological order (class fields are pointer-sized,
        // so circular references between classes are allowed per Requirement 8.6).
        for(var i = 0; i < typeSymbols.Count; i++)
        {
            if(!processingOrder.Contains(i))
            {
                processingOrder.Add(i);
            }
        }

        // Step 4: Process each type in topological order.
        for(var orderIdx = 0; orderIdx < processingOrder.Count; orderIdx++)
        {
            var idx = processingOrder[orderIdx];
            var (_, type) = typeSymbols[idx];

            switch(type)
            {
                case ClassType classType:
                    ComputeDefaultabilityForType(classType, symbolTable, compilation, diagnostics);
                    break;
                case StructType structType:
                    ComputeDefaultabilityForType(structType, symbolTable, compilation, diagnostics);
                    break;
            }
        }

        // Step 5: Process enum types (no topological ordering needed — enum
        // defaultability depends only on the IsDefault modifier of its own members).
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind == SymbolKind.Enum && symbol.DeclaredType is EnumType enumType)
            {
                ComputeDefaultabilityForEnum(enumType, diagnostics);
            }
        }
    }

    /// <summary>
    /// Computes defaultability for a single <see cref="EnumType"/>.
    /// An enum is defaultable if exactly one member has the <c>default</c> modifier.
    /// If zero members have the modifier, the enum is <see cref="DefaultabilityStatus.NotDefaultable"/>.
    /// If more than one member has the modifier, a <c>MIST_ENUM_MULTIPLE_DEFAULTS</c> diagnostic is emitted.
    /// </summary>
    private static void ComputeDefaultabilityForEnum(
        EnumType enumType,
        DiagnosticBag diagnostics)
    {
        var defaultMembers = new List<EnumMemberInfo>();

        foreach(var member in enumType.Members)
        {
            if(member.IsDefault)
            {
                defaultMembers.Add(member);
            }
        }

        if(defaultMembers.Count == 1)
        {
            enumType.Defaultability = DefaultabilityStatus.Explicit;
            enumType.DefaultMember = defaultMembers[0];
        }
        else if(defaultMembers.Count == 0)
        {
            enumType.Defaultability = DefaultabilityStatus.NotDefaultable;
        }
        else
        {
            // Multiple members have the default modifier — emit an error.
            enumType.Defaultability = DefaultabilityStatus.NotDefaultable;
            diagnostics.Add(new Diagnostic(
                CommonDiagnostics.EnumMultipleDefaults.Id,
                DiagnosticSeverity.Error,
                PipelineStage.SemanticModelConstruction,
                $"Enum '{enumType.DisplayName}' has multiple variants with the 'default' modifier. Only one variant may be designated as default.",
                Location: default,
                CompilationUnitPath: "<unknown>",
                AnalyzerName: null));
        }
    }

    /// <summary>
    /// Computes defaultability for a single <see cref="ClassType"/>.
    /// </summary>
    private static void ComputeDefaultabilityForType(
        ClassType classType,

        SymbolTable symbolTable,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // If already set to Explicit by Pass 1 (has a default block), keep it.
        // We still need to compute DefaultValues.
        var hasExplicitBlock = classType.Defaultability == DefaultabilityStatus.Explicit;

        // Determine if the type has user-defined constructors.
        var hasConstructors = classType.MemberScope.Members.Any(m => m.Kind == SymbolKind.Constructor);

        // Check base class defaultability.
        if(classType.BaseType is ClassType baseClass)
        {
            if(!IsIntrinsicallyDefaultable(baseClass) &&
                baseClass.Defaultability is not (DefaultabilityStatus.Inferred or DefaultabilityStatus.Explicit))
            {
                // If the type has constructors and no default block, it's simply
                // NotDefaultable — the constructors handle initialization directly.
                // No diagnostic needed because the type isn't trying to be defaultable.
                if(hasConstructors && !hasExplicitBlock)
                {
                    classType.Defaultability = DefaultabilityStatus.NotDefaultable;
                    return;
                }

                // Otherwise (no constructors, or has an explicit default block with
                // non-defaultable base), emit the diagnostic.
                classType.Defaultability = DefaultabilityStatus.NotDefaultable;
                diagnostics.Add(new Diagnostic(
                    CommonDiagnostics.DefaultBaseNotDefaultable.Id,
                    DiagnosticSeverity.Error,
                    PipelineStage.SemanticModelConstruction,
                    $"Type '{classType.DisplayName}' cannot be defaultable because its base class '{baseClass.DisplayName}' is not defaultable.",
                    Location: default,
                    CompilationUnitPath: "<unknown>",
                    AnalyzerName: null));
                return;
            }
        }

        // If the type has constructors and no explicit default block, it is
        // NotDefaultable — constructors handle initialization. No diagnostic.
        if(hasConstructors && !hasExplicitBlock)
        {
            classType.Defaultability = DefaultabilityStatus.NotDefaultable;
            return;
        }

        // Collect fields from this type's member scope.
        var fields = new List<ISymbol>();
        foreach(var member in classType.MemberScope.Members)
        {
            if(member.Kind == SymbolKind.Field)
            {
                fields.Add(member);
            }
        }

        // Check if all fields are defaultable (considering the explicit default block for type bindings).
        if(!hasExplicitBlock)
        {
            // No explicit block, no constructors — check if all fields have defaultable types.
            foreach(var field in fields)
            {
                if(field.DeclaredType is null)
                {
                    continue;
                }

                if(!IsTypeDefaultable(field.DeclaredType))
                {
                    classType.Defaultability = DefaultabilityStatus.NotDefaultable;

                    // Only emit the diagnostic for abstract type fields that need
                    // a type binding. Other non-defaultable field types (type parameters,
                    // void, etc.) silently make the type not-defaultable.
                    if(field.DeclaredType is AbstractType)
                    {
                        diagnostics.Add(new Diagnostic(
                            CommonDiagnostics.DefaultRequiresTypeBinding.Id,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Field '{field.Name}' on type '{classType.DisplayName}' has type '{field.DeclaredType.DisplayName}' which is not defaultable. Either add a constructor to explicitly assign this field, or add a `default {{}}` block with a type binding.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    return;
                }
            }

            // All fields are defaultable — mark as Inferred.
            classType.Defaultability = DefaultabilityStatus.Inferred;
        }

        // Compute default values.
        var defaultValues = ComputeDefaultValues(classType.MemberScope, classType.BaseType as ClassType,
            classType.DefaultBlockNode, symbolTable, compilation);
        classType.DefaultValues = defaultValues;
    }

    /// <summary>
    /// Computes defaultability for a single <see cref="StructType"/>.
    /// </summary>
    private static void ComputeDefaultabilityForType(
        StructType structType,

        SymbolTable symbolTable,
        MistCompilation compilation,
        DiagnosticBag diagnostics)
    {
        // If already set to Explicit by Pass 1 (has a default block), keep it.
        var hasExplicitBlock = structType.Defaultability == DefaultabilityStatus.Explicit;

        // Determine if the type has user-defined constructors.
        var hasConstructors = structType.MemberScope.Members.Any(m => m.Kind == SymbolKind.Constructor);

        // Structs don't have base types in Mist, so no base class check needed.

        // If the type has constructors and no explicit default block, it is
        // NotDefaultable — constructors handle initialization. No diagnostic.
        if(hasConstructors && !hasExplicitBlock)
        {
            structType.Defaultability = DefaultabilityStatus.NotDefaultable;
            return;
        }

        // Collect fields from this type's member scope.
        var fields = new List<ISymbol>();
        foreach(var member in structType.MemberScope.Members)
        {
            if(member.Kind == SymbolKind.Field)
            {
                fields.Add(member);
            }
        }

        // Check if all fields are defaultable.
        if(!hasExplicitBlock)
        {
            // No explicit block, no constructors — check if all fields have defaultable types.
            foreach(var field in fields)
            {
                if(field.DeclaredType is null)
                {
                    continue;
                }

                if(!IsTypeDefaultable(field.DeclaredType))
                {
                    structType.Defaultability = DefaultabilityStatus.NotDefaultable;

                    // Only emit the diagnostic for abstract type fields that need
                    // a type binding. Other non-defaultable field types (type parameters,
                    // void, etc.) silently make the type not-defaultable.
                    if(field.DeclaredType is AbstractType)
                    {
                        diagnostics.Add(new Diagnostic(
                            CommonDiagnostics.DefaultRequiresTypeBinding.Id,
                            DiagnosticSeverity.Error,
                            PipelineStage.SemanticModelConstruction,
                            $"Field '{field.Name}' on type '{structType.DisplayName}' has type '{field.DeclaredType.DisplayName}' which is not defaultable. Either add a constructor to explicitly assign this field, or add a `default {{}}` block with a type binding.",
                            Location: default,
                            CompilationUnitPath: "<unknown>",
                            AnalyzerName: null));
                    }

                    return;
                }
            }

            structType.Defaultability = DefaultabilityStatus.Inferred;
        }

        // Compute default values.
        var defaultValues = ComputeDefaultValues(structType.MemberScope, baseClass: null,
            structType.DefaultBlockNode, symbolTable, compilation);
        structType.DefaultValues = defaultValues;
    }

    /// <summary>
    /// Computes stampability for all struct types in the symbol table.
    /// A struct is stampable if and only if every instance field's declared type
    /// is transitively a primitive type or another stampable struct. Classes,
    /// abstracts, unions, arrays, and type-parameter-typed fields make
    /// a struct non-stampable. Cycles are handled via a visited set (conservative
    /// false). Invoked after field types are resolved (same timing as
    /// <see cref="ComputeDefaultability"/>).
    /// </summary>
    private static void ComputeStampability(SymbolTable symbolTable)
    {
        foreach(var symbol in symbolTable.AllSymbols)
        {
            if(symbol.Kind != SymbolKind.Struct)
            {
                continue;
            }

            if(symbol.DeclaredType is not StructType structType)
            {
                continue;
            }

            // Skip generic type definitions (types with unbound type parameters).
            // Stampability is only meaningful for closed (non-generic) struct types.
            if(structType.TypeParameters.Count > 0)
            {
                continue;
            }

            // Skip intrinsically defaultable structs — they are primitives and
            // already stampable by definition.
            if(IsIntrinsicallyDefaultable(structType))
            {
                structType.IsStampable = true;
                continue;
            }

            var visited = new HashSet<StructType>(ReferenceEqualityComparer.Instance);
            structType.IsStampable = IsStructStampable(structType, visited);
        }
    }

    /// <summary>
    /// Recursively determines whether <paramref name="structType"/> is stampable.
    /// A struct is stampable when every instance field is a primitive or another
    /// stampable struct. The <paramref name="visited"/> set prevents infinite
    /// recursion on cyclic struct-field references (conservative false on cycles).
    /// </summary>
    private static bool IsStructStampable(StructType structType, HashSet<StructType> visited)
    {
        // Cycle detection: if we have already visited this struct in the current
        // recursion chain, return false conservatively (Requirement 3.5).
        if(!visited.Add(structType))
        {
            return false;
        }

        foreach(var member in structType.MemberScope.Members)
        {
            if(member.Kind != SymbolKind.Field)
            {
                continue;
            }

            // Skip static fields — only instance fields contribute to the
            // struct's value representation.
            if(member is Symbol { IsStatic: true })
            {
                continue;
            }

            var fieldType = member.DeclaredType;
            if(fieldType is null)
            {
                continue;
            }

            switch(fieldType)
            {
                case StructType innerStruct:
                    // Primitive structs (int, bool, char, float, etc.) are stampable.
                    if(IsIntrinsicallyDefaultable(innerStruct))
                    {
                        continue;
                    }

                    // Non-primitive struct → recurse.
                    if(!IsStructStampable(innerStruct, visited))
                    {
                        return false;
                    }

                    break;

                case TypeParameterType:
                    // Type parameter fields make the struct non-stampable (Req 3.4).
                    return false;

                case DependentTypeParameterType:
                    // Dependent type parameter fields make the struct non-stampable.
                    return false;

                case ClassType:
                case AbstractType:
                case UnionType:
                case ArrayType:
                    // Reference types, abstracts, unions, and arrays are
                    // not stampable (Req 3.2, 3.3).
                    return false;

                default:
                    // Any other type kind (ConstructedType, ErrorType, etc.) is
                    // conservatively non-stampable.
                    return false;
            }
        }

        return true;
    }

    /// <summary>
    /// Computes the <see cref="DefaultFieldValue"/> dictionary for a defaultable type.
    /// Combines inherited base defaults, field initializers, zero-initialization,
    /// explicit overrides, and type bindings.
    /// </summary>
    private static Dictionary<string, DefaultFieldValue> ComputeDefaultValues(
        IScope memberScope,
        ClassType? baseClass,
        DefaultBlockDeclarationNode? defaultBlockNode,
        SymbolTable symbolTable,
        MistCompilation compilation)
    {
        var result = new Dictionary<string, DefaultFieldValue>();

        // Step 1: Inherit base class defaults.
        if(baseClass is not null && baseClass.DefaultValues is not null)
        {
            foreach(var (fieldName, baseDefault) in baseClass.DefaultValues)
            {
                result[fieldName] = new DefaultFieldValue
                {
                    FieldName = baseDefault.FieldName,
                    FieldType = baseDefault.FieldType,
                    ValueKind = DefaultValueKind.InheritedDefault,
                    ConstantValue = baseDefault.ConstantValue,
                    ConcreteType = baseDefault.ConcreteType,
                    NestedOverrides = baseDefault.NestedOverrides,
                };
            }
        }

        // Step 2: Compute defaults for this type's own fields.
        foreach(var member in memberScope.Members)
        {
            if(member.Kind != SymbolKind.Field || member.DeclaredType is null)
            {
                continue;
            }

            // Skip fields that were inherited (already in result from base).
            if(result.ContainsKey(member.Name))
            {
                continue;
            }

            // Skip static fields — they are not part of instance default values.
            var declaringNode = symbolTable.GetDeclaringNode(member);
            if(declaringNode is FieldDeclarationNode staticCheck
                && staticCheck.Modifiers.Any(m => m is StaticModifierModifierNode))
            {
                continue;
            }

            // Skip backing fields for static properties (auto-properties generate
            // backing fields named _PropertyName_k__BackingField registered against
            // the property AST node, not a FieldDeclarationNode).
            if(declaringNode is BlockPropertyPropertyDeclarationNode propCheck
                && propCheck.Modifiers.Any(m => m is StaticModifierModifierNode))
            {
                continue;
            }

            var fieldType = member.DeclaredType;

            // Check if the field has an initializer expression.
            object? initializerValue = null;
            var hasInitializer = false;

            if(declaringNode is FieldDeclarationNode fieldDecl && fieldDecl.Initializer is ExpressionNode initExpr)
            {
                initializerValue = TryExtractConstantValue(initExpr);
                hasInitializer = true;
            }

            if(hasInitializer)
            {
                result[member.Name] = new DefaultFieldValue
                {
                    FieldName = member.Name,
                    FieldType = fieldType,
                    ValueKind = DefaultValueKind.FieldInitializer,
                    ConstantValue = initializerValue,
                };
            }
            else if(IsIntrinsicallyDefaultable(fieldType))
            {
                result[member.Name] = new DefaultFieldValue
                {
                    FieldName = member.Name,
                    FieldType = fieldType,
                    ValueKind = DefaultValueKind.ZeroInitialized,
                    ConstantValue = GetZeroValue(fieldType),
                };
            }
            else if(fieldType is ClassType nestedClass && IsTypeDefaultable(nestedClass))
            {
                result[member.Name] = new DefaultFieldValue
                {
                    FieldName = member.Name,
                    FieldType = fieldType,
                    ValueKind = DefaultValueKind.NestedTypeDefault,
                    ConcreteType = nestedClass,
                };
            }
            else if(fieldType is StructType nestedStruct && IsTypeDefaultable(nestedStruct))
            {
                result[member.Name] = new DefaultFieldValue
                {
                    FieldName = member.Name,
                    FieldType = fieldType,
                    ValueKind = DefaultValueKind.NestedTypeDefault,
                    ConcreteType = nestedStruct,
                };
            }
            else
            {
                // Non-defaultable field type — this should only happen for
                // types with explicit default blocks that provide type bindings.
                // The field will be handled by the explicit block processing below.
                result[member.Name] = new DefaultFieldValue
                {
                    FieldName = member.Name,
                    FieldType = fieldType,
                    ValueKind = DefaultValueKind.ZeroInitialized,
                    ConstantValue = null,
                };
            }
        }

        // Step 3: Apply explicit default block overrides and type bindings.
        if(defaultBlockNode is not null)
        {
            foreach(var entry in defaultBlockNode.Entries)
            {
                switch(entry)
                {
                    case DefaultFieldOverrideDefaultFieldInitializerNode fieldOverride:
                        {
                            var fieldName = fieldOverride.FieldName.Lexeme;
                            var overrideValue = TryExtractConstantValue(fieldOverride.Value);

                            // Find the field's type from the existing result or member scope.
                            IType? fieldType = null;
                            if(result.TryGetValue(fieldName, out var existing))
                            {
                                fieldType = existing.FieldType;
                            }
                            else
                            {
                                // Look up in member scope (including inherited).
                                var fieldSymbol = memberScope.Lookup(fieldName);
                                fieldType = fieldSymbol?.DeclaredType;
                            }

                            result[fieldName] = new DefaultFieldValue
                            {
                                FieldName = fieldName,
                                FieldType = fieldType!,
                                ValueKind = DefaultValueKind.ExplicitOverride,
                                ConstantValue = overrideValue,
                            };
                            break;
                        }

                    case DefaultTypeBindingDefaultFieldInitializerNode typeBinding:
                        {
                            var fieldName = typeBinding.FieldName.Lexeme;

                            // Find the field's type.
                            IType? fieldType = null;
                            if(result.TryGetValue(fieldName, out var existing))
                            {
                                fieldType = existing.FieldType;
                            }
                            else
                            {
                                var fieldSymbol = memberScope.Lookup(fieldName);
                                fieldType = fieldSymbol?.DeclaredType;
                            }

                            // Extract the concrete type name from the type binding.
                            // The IDENTIFIER.Lexeme on QualifiedIdentifierNode may be empty
                            // (Storm source generator stores text in spans, not lexemes).
                            // Find the correct source text by locating the struct's declaring
                            // node in the compilation units.
                            var concreteTypeName = "";
                            if(typeBinding.TypeName.First is NamedSingleTypeRefSingleTypeRefNode namedTypeRef)
                            {
                                // First try the Lexeme directly
                                concreteTypeName = namedTypeRef.Name.IDENTIFIER.Lexeme;

                                // If empty, extract from source text via span
                                if(string.IsNullOrEmpty(concreteTypeName))
                                {
                                    var nameSpan = namedTypeRef.Name.Span;
                                    if(nameSpan.Length > 0)
                                    {
                                        // Try each compilation unit — validate extracted text
                                        for(var unitIdx = compilation.Units.Length - 1; unitIdx >= 0; unitIdx--)
                                        {
                                            var src = compilation.Units[unitIdx].Source;
                                            if(src is not null
                                                && nameSpan.Start + nameSpan.Length <= src.Contents.Length)
                                            {
                                                var candidate = src.Contents.Substring(nameSpan.Start, nameSpan.Length);
                                                if(IsValidQualifiedIdentifier(candidate))
                                                {
                                                    concreteTypeName = candidate;
                                                    break;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            else
                            {
                                concreteTypeName = ExtractTypeReferenceName(typeBinding.TypeName, null);
                            }

                            var concreteType = FindTypeByName(memberScope, concreteTypeName);

                            // Process nested overrides if present.
                            Dictionary<string, DefaultFieldValue>? nestedOverrides = null;
                            if(typeBinding.NestedEntries.Length > 0)
                            {
                                nestedOverrides = new Dictionary<string, DefaultFieldValue>();
                                foreach(var nested in typeBinding.NestedEntries)
                                {
                                    var nestedFieldName = nested.FieldName.Lexeme;
                                    var nestedValue = TryExtractConstantValue(nested.Value);

                                    // Try to find the nested field's type from the concrete type.
                                    IType? nestedFieldType = null;
                                    if(concreteType is ClassType concreteCt)
                                    {
                                        var nestedSymbol = concreteCt.MemberScope.Lookup(nestedFieldName);
                                        nestedFieldType = nestedSymbol?.DeclaredType;
                                    }
                                    else if(concreteType is StructType concreteSt)
                                    {
                                        var nestedSymbol = concreteSt.MemberScope.Lookup(nestedFieldName);
                                        nestedFieldType = nestedSymbol?.DeclaredType;
                                    }

                                    nestedOverrides[nestedFieldName] = new DefaultFieldValue
                                    {
                                        FieldName = nestedFieldName,
                                        FieldType = nestedFieldType ?? ErrorType.Instance,
                                        ValueKind = DefaultValueKind.ExplicitOverride,
                                        ConstantValue = nestedValue,
                                    };
                                }
                            }

                            result[fieldName] = new DefaultFieldValue
                            {
                                FieldName = fieldName,
                                FieldType = fieldType ?? ErrorType.Instance,
                                ValueKind = DefaultValueKind.TypeBinding,
                                ConcreteType = concreteType,
                                NestedOverrides = nestedOverrides,
                            };
                            break;
                        }
                }
            }
        }

        return result;
    }

    /// <summary>
    /// Returns the zero-initialization value for an intrinsically defaultable type.
    /// </summary>
    private static object? GetZeroValue(IType type)
    {
        return type.DisplayName switch
        {
            // Integer types
            "int" or "Int32" => 0,
            "uint" or "UInt32" => 0u,
            "long" or "Int64" => 0L,
            "ulong" or "UInt64" => 0UL,
            "short" or "Int16" => (short)0,
            "ushort" or "UInt16" => (ushort)0,
            "byte" or "Byte" => (byte)0,
            "sbyte" or "SByte" => (sbyte)0,
            // Floating-point types
            "float" or "Single" => 0.0f,
            "double" or "Double" => 0.0d,
            "decimal" or "Decimal" => 0.0m,
            // Boolean
            "bool" or "Boolean" => false,
            // Char
            "char" or "Char" => '\0',
            // String
            "string" or "String" => "",
            _ => null,
        };
    }

    /// <summary>
    /// Attempts to extract a compile-time constant value from a literal expression.
    /// Returns <c>null</c> if the expression is not a recognized literal.
    /// In v1, only literal expressions are compile-time constants.
    /// </summary>
    private static object? TryExtractConstantValue(ExpressionNode expression)
    {
        // Unwrap the expression to get to the primary node.
        // Expression → UnaryExpression → ... → Primary
        var primary = UnwrapToPrimary(expression);
        if(primary is null)
        {
            return null;
        }

        return primary switch
        {
            IntegerLiteralExpressionPrimaryNode intLit =>
                TryParseIntegerLiteral(intLit.IntegerLiteral.Lexeme),
            HexLiteralExpressionPrimaryNode hexLit =>
                TryParseIntegerLiteral(hexLit.HexLiteral.Lexeme),
            BinaryLiteralExpressionPrimaryNode binLit =>
                TryParseIntegerLiteral(binLit.BinaryLiteral.Lexeme),
            FloatLiteralExpressionPrimaryNode floatLit =>
                TryParseFloatLiteral(floatLit.FloatLiteral.Lexeme),
            StringLiteralExpressionPrimaryNode stringLit =>
                ExtractStringLiteralValue(stringLit.StringLiteral.Lexeme),
            CharLiteralExpressionPrimaryNode charLit =>
                ExtractCharLiteralValue(charLit.CharLiteral.Lexeme),
            TrueLiteralExpressionPrimaryNode => true,
            FalseLiteralExpressionPrimaryNode => false,
            _ => null,
        };
    }

    /// <summary>
    /// Unwraps an expression node down to its innermost <see cref="PrimaryNode"/>.
    /// Returns <c>null</c> if the expression structure is not a simple primary.
    /// </summary>
    private static PrimaryNode? UnwrapToPrimary(ExpressionNode expression)
    {
        // Walk down the expression tree to find the innermost PrimaryNode.
        // The Storm AST wraps primaries in multiple layers of expression nodes
        // (Expression → ConditionalExpression → ... → UnaryExpression → Primary).
        Storm.Runtime.SyntaxNode current = expression;

        for(var depth = 0; depth < 20; depth++)
        {
            if(current is PrimaryNode primary)
            {
                return primary;
            }

            // Look for a single non-token child to follow.
            // Skip null children that may be yielded by generated AST nodes
            // whose optional properties are typed as non-nullable.
            Storm.Runtime.SyntaxNode? next = null;
            var childCount = 0;
            foreach(var child in current.Children())
            {
                if(child is null)
                {
                    continue;
                }

                childCount++;
                if(child is PrimaryNode childPrimary)
                {
                    return childPrimary;
                }

                // Follow the first (and hopefully only) syntax node child.
                next ??= child;
            }

            // If there are multiple children, this is not a simple literal expression.
            if(childCount > 1 || next is null)
            {
                return null;
            }

            current = next;
        }

        return null;
    }

    /// <summary>
    /// Attempts to parse an integer literal string into a numeric value.
    /// </summary>
    private static object? TryParseIntegerLiteral(string lexeme)
    {
        // Remove underscores (Mist allows _ as digit separator).
        var cleaned = lexeme.Replace("_", "");
        var upper = cleaned.ToUpperInvariant();

        // Check for suffix.
        if(upper.EndsWith("UL") || upper.EndsWith("LU"))
        {
            if(ulong.TryParse(cleaned[..^2], out var val))
            {
                return val;
            }
        }
        else if(upper.EndsWith("L"))
        {
            if(long.TryParse(cleaned[..^1], out var val))
            {
                return val;
            }
        }
        else if(upper.EndsWith("U"))
        {
            if(uint.TryParse(cleaned[..^1], out var val))
            {
                return val;
            }
        }
        else if(upper.StartsWith("0X"))
        {
            if(long.TryParse(cleaned[2..], System.Globalization.NumberStyles.HexNumber, null, out var val))
            {
                return val;
            }
        }
        else if(upper.StartsWith("0B"))
        {
            try { return Convert.ToInt64(cleaned[2..], 2); }
            catch { return null; }
        }
        else
        {
            if(int.TryParse(cleaned, out var val))
            {
                return val;
            }

            if(long.TryParse(cleaned, out var lval))
            {
                return lval;
            }
        }

        return null;
    }

    /// <summary>
    /// Attempts to parse a float literal string into a numeric value.
    /// </summary>
    private static object? TryParseFloatLiteral(string lexeme)
    {
        var cleaned = lexeme.Replace("_", "");
        var upper = cleaned.ToUpperInvariant();

        if(upper.EndsWith("F"))
        {
            if(float.TryParse(cleaned[..^1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var val))
            {
                return val;
            }
        }
        else if(upper.EndsWith("M"))
        {
            if(decimal.TryParse(cleaned[..^1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var val))
            {
                return val;
            }
        }
        else
        {
            if(double.TryParse(cleaned, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var val))
            {
                return val;
            }
        }

        return null;
    }

    /// <summary>
    /// Extracts the string value from a string literal lexeme (removes surrounding quotes).
    /// </summary>
    private static string ExtractStringLiteralValue(string lexeme)
    {
        if(lexeme.Length >= 2 && lexeme[0] == '"' && lexeme[^1] == '"')
        {
            return lexeme[1..^1];
        }

        return lexeme;
    }

    /// <summary>
    /// Extracts the char value from a char literal lexeme (removes surrounding quotes).
    /// </summary>
    private static char ExtractCharLiteralValue(string lexeme)
    {
        if(lexeme.Length >= 3 && lexeme[0] == '\'' && lexeme[^1] == '\'')
        {
            var inner = lexeme[1..^1];
            if(inner.Length == 1)
            {
                return inner[0];
            }
            // Handle escape sequences.
            if(inner.StartsWith('\\') && inner.Length >= 2)
            {
                return inner[1] switch
                {
                    'n' => '\n',
                    'r' => '\r',
                    't' => '\t',
                    '\\' => '\\',
                    '\'' => '\'',
                    '0' => '\0',
                    _ => inner[1],
                };
            }
        }

        return '\0';
    }

    /// <summary>
    /// Finds a type by simple name by searching the scope chain upward.
    /// </summary>
    private static IType? FindTypeByName(IScope scope, string typeName)
    {
        var current = scope;
        while(current is not null)
        {
            foreach(var member in current.Members)
            {
                if(member.Kind is SymbolKind.Class or SymbolKind.Struct or SymbolKind.Abstract
                    && member.Name == typeName
                    && member.DeclaredType is not null)
                {
                    return member.DeclaredType;
                }
            }

            current = current.Parent;
        }

        return null;
    }

    private static Diagnostic MakeDiagnosticWithLocation(
        string id,
        DiagnosticSeverity severity,
        string message,
        Storm.Runtime.SyntaxNode node,
        SourceText? sourceText)
    {
        LinePositionSpan location = default;
        var compilationUnitPath = sourceText?.Path ?? "<unknown>";

        if(sourceText is not null && node.Span.Length > 0)
        {
            var mistSpan = new SourceSpan(node.Span.Start, node.Span.Length);
            location = sourceText.ToLinePositionSpan(mistSpan);
        }

        return new Diagnostic(
            new DiagnosticId(id),
            severity,
            PipelineStage.SemanticModelConstruction,
            message,
            Location: location,
            CompilationUnitPath: compilationUnitPath,
            AnalyzerName: null);
    }

    /// <summary>
    /// Walks the struct ancestor chain starting from <paramref name="baseStruct"/>
    /// looking for a field with the given name. Returns the ancestor struct that
    /// declares the field, or <c>null</c> if no ancestor has a field with that name.
    /// </summary>
    private static StructType? FindFieldInStructAncestors(StructType? baseStruct, string fieldName)
    {
        var current = baseStruct;
        while(current is not null)
        {
            foreach(var member in current.MemberScope.Members)
            {
                if(member.Kind == SymbolKind.Field && member.Name == fieldName)
                {
                    return current;
                }
            }

            current = current.BaseType as StructType;
        }

        return null;
    }

    private static SourceSpan ToMistSourceSpan(Storm.Runtime.SourceSpan span)
    {
        return new SourceSpan(span.Start, span.Length);
    }

    private static Diagnostic MakeDiagnosticWithTokenLocation(
        string id,
        DiagnosticSeverity severity,
        string message,
        Storm.Runtime.Token token,
        SourceText? sourceText)
    {
        LinePositionSpan location = default;
        var compilationUnitPath = sourceText?.Path ?? "<unknown>";

        if(sourceText is not null && token.Span.Length > 0)
        {
            var mistSpan = new SourceSpan(token.Span.Start, token.Span.Length);
            location = sourceText.ToLinePositionSpan(mistSpan);
        }

        return new Diagnostic(
            new DiagnosticId(id),
            severity,
            PipelineStage.SemanticModelConstruction,
            message,
            Location: location,
            CompilationUnitPath: compilationUnitPath,
            AnalyzerName: null);
    }

    /// <summary>
    /// Returns true if the given type is a ref struct (stack-only value type).
    /// Handles <see cref="SpanType"/>, plain <see cref="StructType"/>, and <see cref="ConstructedType"/>
    /// whose generic definition is a ref struct.
    /// </summary>
    private static bool IsRefStructType(IType type)
    {
        return type is SpanType
            || type is StructType { IsRefStruct: true }
            || (type is ConstructedType ct && ct.GenericDefinition is StructType { IsRefStruct: true });
    }
}